-- Sources: data/i18n/deDE. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["quest:6541"] = {n="Meldung bei Kadrak",s="Thork am Wegekreuz schickt fähige Hordekämpfer nach Norden zu Kadraks Wachturm nahe der Grenze zum Eschental. Kadrak koordiniert die Expansion der Horde in den uralten Wald und bereitet eintreffende Rekruten auf die bevorstehenden Gefechte vor.",h="Thork am Wegekreuz schickt fähige Hordekämpfer nach Norden zu Kadraks Wachturm nahe der Grenze zum Eschental.",kw={"eschental","brachland","das wegekreuz","kadrak","splitterholz","thork","wachturm","der zoramstrand"},ang={["faction:Horde"]="Diese Depesche markiert den Übergang von der Verteidigung besiedelter Gebiete im Brachland zur Sicherung lebenswichtiger Ressourcenadern in den umkämpften Wäldern im Norden.",["race:Orc"]="Das Eschental ist ein entscheidendes Bewährungsfeld für die Orcs, um das Holz zu sichern, das zur Befestigung von Orgrimmar und zum Aufbau einer dauerhaften Heimat auf Kalimdor benötigt wird."},sec={{t="Die Straße nach Norden",b="Während sich das Wegekreuz mit Borstennacken, Zentauren und örtlichen Räubern auseinandersetzen muss, richten sich die weiter reichenden territorialen Interessen der Horde nach Norden auf die dichten Wälder des Eschentals. Thork fungiert als Vermittler und schickt erfahrene Kämpfer, die sich im zentralen Brachland bewährt haben, zum von Kadrak besetzten Turm an der nördlichen Grenze."},{t="Grenzlandstrategie",b="Kadrak überwacht den südlichen Zugang zum Eschental und organisiert Verstärkung für die Stellungen der Horde jenseits der Grenze. Mit neuen Lagern wie dem Splitterholzposten und dem Außenposten entlang des Zoramstrands festigt die Horde aktiv ihre Präsenz in den holzreichen Waldgebieten, ungeachtet des erbitterten Widerstands der einheimischen Nachtelfen."}},faq={{q="Wer ist Thork?",a="Thork ist ein Offizier der Orcs, der am Wegekreuz im Brachland stationiert ist. Er hilft bei der Koordination der örtlichen Verteidigung und mobilisiert vielversprechende Abenteurer für regionale Kriegsanstrengungen wie den Feldzug im Eschental.",al={"thork wegekreuz","wer gibt meldung bei kadrak","thork brachland"}},{q="Wo befindet sich Kadrak?",a="Kadrak ist am nördlichen Wachturm im Brachland stationiert, direkt an der Hauptstraße, die in den Wald des Eschentals führt.",al={"kadrak aufenthaltsort","wo ist kadrak","kadrak wachturm"}},{q="Warum dringt die Horde in das Eschental vor?",a="Die Horde benötigt Bauholz und Ressourcen, um ihre neuen Städte in Durotar und im Brachland zu errichten. Die Expansion in das Eschental liefert unverzichtbares Holz, bringt sie jedoch in direkten Konflikt mit den Nachtelfen.",al={"warum eschental","horde im eschental","eschental-invasion"}},{q="Welche Außenposten hat die Horde im Eschental errichtet?",a="Kadrak merkt an, dass die Horde den Splitterholzposten an der zentralen Straße in den Wald und einen weiteren Außenposten weiter westlich entlang des Zoramstrands errichtet hat.",al={"horde stützpunkte eschental","zoramstrand stützpunkt","splitterholz"}},{q="Was folgt nach der Meldung bei Kadrak?",a="Sobald Ihr Euch bei Kadrak meldet, unterrichtet er Euch über die örtliche militärische Lage und trägt Euch auf, Berichte von den verschiedenen Außenposten der Kriegshymnen im gesamten Eschental einzuholen.",al={"nach kadrak","nächste quest nach kadrak","was gibt kadrak"}},{q="Kann man diesen Auftrag auch woanders als im Brachland erhalten?",a="Ja. Eine nahezu identische Aufforderung, sich bei Kadrak zu melden, wird an Hordekämpfer ausgegeben, die von Malaka'jin im Steinkrallengebirge aus operieren.",al={"alternative kadrak-quest","steinkrallengebirge kadrak quest"}}},fx={d049fa98={q="Warum will Thork, dass ich mich bei Kadrak melde?",a="Die Horde sichert aktiv ihren Halt im Eschental, nachdem sie kürzlich Außenposten wie den am Zoram-Strand errichtet hat. Thork beaufsichtigt die Verteidigung des Wegekreuzes, doch die Frontlinien im Norden erfordern ständig frische Rekruten, um diese neu beanspruchten Gebiete zu schützen. Er schickt fähige Krieger hinauf zu Kadrak, der die Kampagne vom nördlichen Wachturm aus koordiniert und bestimmt, wo Verstärkung am dringendsten benötigt wird.",al={"warum bei kadrak melden","motiv von thork melden bei kadrak","warum schickt thork mich zu kadrak"}}},fp="16,238,14.322.0,17.338.0,13.204.0,24.127.0,40.204.0,53.157.0,37.158.0,69.136.0"}
P.entries["quest:6542"] = {n="Meldung bei Kadrak",s="Diese militärische Depesche schickt Krieger der Horde von Malaka'jin im Steinkrallengebirge zu Kadraks Wachtposten an der Grenze des nördlichen Brachlands. Sie markiert den Übergang von der Verteidigung der schroffen Felsen zur Verstärkung des umkämpften Feldzugs der Horde in Eschental. Durch ihre Meldung bei Kadrak werden Soldaten zusammengezogen, um Vorposten wie den Splitterholzposten und den Zoramstrand zu unterstützen.",h="Diese militärische Depesche schickt Krieger der Horde von Malaka'jin im Steinkrallengebirge zu Kadraks...",kw={"eschental","brachland","darn talongrip","kadrak","splintertreeposten","steinkrallengebirge","die warsongberichte","der zoramstrand"},ang={["faction:Horde"]="Dieser Befehl bindet Euch in die umfassenderen Kriegsanstrengungen des Kriegshäuptlings ein und führt Grenzveteranen direkt in den aktiven Kampf um die Ressourcen von Eschental.",["race:Orc"]="Der Feldzug in Eschental ist von entscheidender Bedeutung für den Kriegshymnenklan und das Überleben von Durotar, was Kadraks Posten zu einem Prüfstein für junge Orckrieger macht.",["race:Tauren"]="Späher der Horde wie der Orc Darn Talongrip geleiten Reisende sicher über die Berggrenzen und halten die Verbindungswege zwischen den Ländern der Bluthufe und der Nordfront des Kriegshäuptlings offen."},sec={{t="Ein Ruf an die Nordfront",b="Im zerklüfteten Pass von Malaka'jin wacht der Orc Darn Talongrip über die südlichen und bergigen Grenzen der Horde. Doch der größte militärische Druck herrscht weiter nördlich in den uralten Wäldern von Eschental, wo Schildwachen der Nachtelfen unaufhörlich mit den Holzfällern des Kriegshymnenklans aneinandergeraten. Wenn Darn kampferprobte Krieger erblickt, die das Steinkrallengebirge durchqueren, schickt er fähige Rekruten zum Wachturm im nördlichen Brachland, um bei den dortigen Feldzügen zu helfen."},{t="Kadraks Wacht",b="Direkt an der nördlichen Schwelle, wo die trockene Savanne auf das grüne Blätterdach von Eschental trifft, überwacht der Orc Kadrak die Truppenbewegungen der Horde in das umkämpfte Gebiet. Die Horde sichert ihren Stützpunkt entschlossen ab und unterhält Außenposten sowohl am westlichen Zoramstrand als auch am Splitterholzposten im Norden. Kadrak dient als wichtiger Knotenpunkt für die Koordination von Nachschub, Truppen und dringenden Berichten entlang dieser umkämpften Frontlinien im Wald."}},faq={{q="Wer schickt Euch vom Steinkrallengebirge aus zu Kadrak?",a="Darn Talongrip, ein Orc, der im Außenposten Malaka'jin im Steinkrallengebirge stationiert ist, übergibt diese Depesche an fähige Abenteurer, die zur Waldgrenze reisen.",al={"questgeber meldung bei kadrak","wer startet meldung bei kadrak steinkrallengebirge","darn talongrip quest"}},{q="Wo befindet sich Kadrak?",a="Kadrak ist am nördlichen Wachturm im Brachland stationiert und bewacht die Hauptstraße, die nach Norden nach Eschental führt.",al={"kadrak aufenthaltsort","wo ist kadrak","kadrak finden"}},{q="Warum rekrutiert die Horde Krieger für Eschental?",a="Die Horde benötigt Holz, um Orgrimmar zu versorgen, und hat befestigte Stellungen wie den Zoramstrand und den Splitterholzposten errichtet. Da diese Bemühungen auf heftigen Widerstand der einheimischen Nachtelfen stoßen, benötigen die Befehlshaber ständige Verstärkung, um das Gebiet zu sichern.",al={"warum nach eschental","horde feldzug eschental","warum in eschental kämpfen"}},{q="Was geschieht nach der Meldung bei Kadrak?",a="Kadrak wird Euch über die strategische Lage in Eschental informieren und Euch damit beauftragen, über die Quest Die Berichte des Kriegshymnenklans militärische Berichte an die umkämpften Außenposten im Wald zu überbringen und einzuholen.",al={"wie geht es nach kadrak weiter","die berichte des kriegshymnenklans","kadrak folgequest"}},{q="Unterscheidet sich diese Quest von der Version aus dem Brachland?",a="Beide sind Hinführungsquests, die zu Kadrak an die Grenze von Eschental leiten. Eine wird im Brachland (beim Wegekreuz) angeboten und diese hier im Steinkrallengebirge; der Abschluss einer der beiden führt Euch in die Handlung von Eschental ein.",al={"brachland vs steinkrallengebirge kadrak","zwei meldung bei kadrak quests","kadrak hinführung duplikat"}},{q="Was ist der in der Lagebesprechung erwähnte Zoramstrand?",a="Der Zoramstrand ist ein Küstengebiet im Nordwesten von Eschental am Verhüllten Meer. Die Horde hat dort einen befestigten Strandaußenposten errichtet, um taktische Manöver zu unterstützen und den Zugang zur See zu sichern.",al={"was ist der zoramstrand","zoramstrand außenposten","eschental strandbasis"}}},fx={f0da3cc6={q="Warum will Darn Talongrip, dass Ihr Euch bei Kadrak meldet?",a="Die Horde hat kürzlich einen Außenposten am Zoram-Strand im Eschental errichtet und benötigt Rekruten zur Verteidigung ihrer neuen Fronten. Darn Talongrip, stationiert in Malaka'jin, verweist fähige Abenteurer an Kadrak am Wachturm des nördlichen Brachlands für weitere Befehle.",al={"warum schickt darn mich zu kadrak","motiv von darn talongrip","warum bei kadrak melden"}}},fp="16,398,28.440.0,14.447.0,40.174.0,24.128.0,51.274.0,39.186.0,49.221.0,51.197.0"}
P.entries["quest:6543"] = {n="Die Berichte des Kriegshymnenklans",s="Diese von Kadrak am Grenzwachturm zwischen dem nördlichen Brachland und Eschental vergebene Mission beauftragt Kuriere damit, Feldaufklärung im umkämpften Wald zu koordinieren. Abenteurer müssen bestehende Befehle überbringen und Berichte von der Front von Vorhuten einholen, die nahe Azshara, dem Splitterholzposten und dem Zoramstrand stationiert sind.",h="Diese von Kadrak am Grenzwachturm zwischen dem nördlichen Brachland und Eschental vergebene Mission...",kw={"eschental","brachland","kadrak","splitterholzposten","vorhut des kriegshymnenklans","die warsongberichte","läufer des kriegshymnenklans","späher des kriegshymnenklans","der zoramstrand","außenposten von zoram'gar"},ang={["class:Hunter"]="Das Reisen über Eschentals tückische Straßen stellt die Orientierungs- und Überlebensfähigkeiten in der Wildnis gegen wilde Raubtiere und verborgene elbische Bogenschützen auf die Probe.",["faction:Horde"]="Die Zustellung dieser Berichte markiert einen der ersten echten Schritte eines jungen Kriegers der Horde im territorialen Kampf gegen die Nachtelfen im nördlichen Kalimdor.",["race:Orc"]="Für Orcs ist die Unterstützung des Kriegshymnenklans ein Gebot der Klanehre und eine praktische Notwendigkeit, um sicherzustellen, dass weiterhin Bauholz für die Errichtung von Orgrimmar fließt."},sec={{t="Grenzlandlogistik",b="Oben auf dem befestigten Wachturm am nördlichen Rand des Brachlands überwacht Kadrak die Bewegungen durch die enge Bergschlucht, die nach Eschental führt. Für die Horde ist die Sicherung des Zugangs durch diesen Pass von entscheidender Bedeutung: Die kargen Steppen können die gewaltigen Holzmengen nicht liefern, die Orgrimmar benötigt, sodass der Kriegshymnenklan gezwungen ist, tief in die uralten Wälder der Elfen vorzudringen. Um die verstreuten Vorpostenpatrouillen zu versorgen und abzustimmen, bedarf es verlässlicher Kuriere, die in der Lage sind, Hinterhalten der Nachtelfen auf den tückischen Wildnispfaden Eschentals zu entgehen."},{t="Augen über Eschental",b="Die Mission zieht einen Bogen über die gesamte Breite des uralten Waldes. Weit im Westen an der nebligen Küste des Zoramstrands beobachtet ein Läufer des Kriegshymnenklans die Aktivitäten der Naga und Gefahren an der Küste nahe dem Außenposten von Zoram'gar. Weiter landeinwärts am Splitterholzposten koordiniert ein Späher die Verteidigung gegen anhaltende Überfälle der Schildwachen. Weiter östlich entlang der kurvenreichen Straße zu den zerborstenen Ruinen von Azshara überwacht eine Vorhut die östlichen Zugänge. Das Einholen von Berichten von allen drei Posten verschafft Kadrak ein geschlossenes Bild über die Truppenbewegungen der Nachtelfen und die Schwachstellen an der Grenze."}},faq={{q="Wo beginnt diese Mission?",a="Die Mission beginnt bei Kadrak, einem Orcoffizier, der im hölzernen Wachturm stationiert ist, welcher den Bergpass an der Grenze zwischen dem nördlichen Brachland und dem südlichen Eschental bewacht.",al={"questgeber","kadrak aufenthaltsort","wer gibt die warsongberichte","wo beginnen"}},{q="Warum spioniert die Horde in Eschental?",a="Die Horde ist stark auf das dichte Holz von Eschental angewiesen, um Siedlungen wie Orgrimmar zu errichten und zu verstärken. Die einheimischen Nachtelfen verteidigen ihre heiligen Haine erbittert, was die gesamte Region in ein aktives Kriegsgebiet verwandelt, das ständige Aufklärung erfordert, um Außenposten zu halten und Nachschublinien zu sichern.",al={"warum eschental","warsong holz","eschental konflikt"}},{q="Wo sind die drei Späher des Kriegshymnenklans zu finden?",a="Der Läufer des Kriegshymnenklans ist am Außenposten von Zoram'gar am Zoramstrand ganz im Nordwesten stationiert. Der Späher des Kriegshymnenklans befindet sich am Splitterholzposten an der Hauptstraße. Die Vorhut des Kriegshymnenklans patrouilliert auf der östlichen Straße in Richtung der Grenze von Azshara.",al={"späher standorte","wo sind die späher","vorhut läufer späher standort"}},{q="Wer ist die Vorhut des Kriegshymnenklans?",a="Die Vorhut des Kriegshymnenklans besteht aus Spähern und Plünderern des orcischen Kriegshymnenklans. Berühmt für ihre ungestüme Kavallerie und ihre Scharmützeltaktiken bilden sie die Speerspitze der Expansion der Horde, des Holzabbaus und der territorialen Verteidigung in den Wäldern von Eschental.",al={"kriegshymnenklan","wer ist die warsongvorhut","warsongklan eschental"}},{q="Was geschieht nach der Rückgabe der Berichte?",a="Nachdem Kadrak die gesammelten Informationen erhalten hat, nutzt er die taktischen Berichte, um bevorstehende Truppenbewegungen zu planen, verwundbare Außenposten wie Zoram'gar und Splintertree zu verstärken und die Präsenz der Horde tiefer im Wald zu festigen.",al={"berichte abgeben","nächster schritt","was macht kadrak"}},{q="Ist die Straße durch Eschental für niedrigstufige Kuriere sicher?",a="Nein. Entlang der Hauptstraße durch Eschental kommt es häufig zu Hinterhalten durch getarnte Nachtelfen-Schildwachen, feindselige Wildtiere wie Pirscher und Bären sowie Allianz-Patrouillen, die von Siedlungen wie Astranaar aus operieren.",al={"gefahr in eschental","ist die straße sicher","nachtelfen hinterhalte"}}},fx={["197774e3"]={q="Warum möchte Kadrak die Berichte gesammelt haben?",a="Kadrak bewacht die Grenze zwischen dem Brachland und den umkämpften Wäldern des Eschentals. Die Horde ist aktiv bestrebt, ihre Präsenz unter dem Blätterdach auszubauen, aber blind in das Gebiet der Nachtelfen zu marschieren, lädt zum Desaster ein. Kadrak setzte Aufklärer tief in der Region ein, um feindliche Aktivitäten und das Gelände zu überwachen. Er muss diese Aktualisierungen dringend geliefert und zurückerhalten, damit die Führung der Horde ihre taktische Lage genau einschätzen und ihre nächsten Schritte im laufenden Feldzug koordinieren kann.",al={"motiv von kadrak","warum will kadrak berichte","warum warsongberichte sammeln"}},["649e115c"]={q="Was ist der Aktualisierte Bericht der Vorhut des Kriegshymnenklans?",a="Der Aktualisierte Bericht der Vorhut des Kriegshymnenklans ist ein taktisches Geheimdokument, das von der Vorhut der Horde zusammengestellt wurde, die die östlichen Abschnitte des Eschentals in Richtung der Grenze von Azshara patrouilliert. Er enthält Beobachtungen zu Bewegungen der Allianz, Wächterpatrouillen und lokaler Geographie entlang der wichtigen Hauptstraße und versorgt Kadrak mit dem Überblick über die Ostgrenze, der für die Planung von Truppenmanövern erforderlich ist.",al={"aktualisierter bericht der vorhut des kriegshymnenklans","was ist aktualisierter bericht der vorhut","vorhutbericht"}},f6b4d8ea={q="Was ist der Aktualisierte Bericht des Läufers des Kriegshymnenklans?",a="Der Aktualisierte Bericht des Läufers des Kriegshymnenklans enthält Aufklärungsdaten, die an den westlichen Rändern des Waldes gesammelt wurden, stationiert vom Außenposten von Zoram'gar entlang des Zoram-Strandes. Diese Depesche beschreibt Bedrohungen an der Küste, lokale feindliche Kräfte und Annäherungen von der Seeseite und informiert Kadrak über die Sicherheit der Positionen der Horde weit westlich der Hauptstraße.",al={"aktualisierter bericht des läufers des kriegshymnenklans","was ist aktualisierter bericht des läufers","läuferbericht"}},["92e54885"]={q="Was ist der Aktualisierte Bericht des Spähers des Kriegshymnenklans?",a="Der Aktualisierte Bericht des Spähers des Kriegshymnenklans ist ein strategischer Bericht, der vom Splitterholzposten, dem wichtigsten Stützpunkt der Horde im zentralen Eschental, gesendet wurde. Erstellt vom dort stationierten Vorhutspäher, verfolgt er Einfälle der feindlichen Nachtelfen, logistische Versorgungsgüter und die Bereitschaft des Außenpostens, weitere Expansionen der Horde in der umliegenden Wildnis zu unterstützen.",al={"aktualisierter bericht des spähers des kriegshymnenklans","was ist aktualisierter bericht des spähers","späherbericht"}}},fp="19,333,18.542.0,21.568.0,30.175.0,37.290.0,44.255.0,30.242.0,41.226.0,58.210.0"}
P.entries["quest:6544"] = {n="Toreks Angriff",s="Toreks Angriff ist ein direkter Überfall der Horde, der aus der Wildnis des Eschentals gegen die nahe gelegene Nachtelfengarnison am Außenposten der Silberschwingen geführt wird. Angefeuert und angeführt von dem Orc-Räuber Torek auf Befehl aus dem Splitterholzposten, zielt der Schlag darauf ab, den örtlichen Widerstand der Schildwachen zu brechen und ihre Kommandantin Duriel Moonfire zu töten. Er markiert eines der dreistesten und blutigsten Scharmützel im anhaltenden Krieg um die Grenzen des Eschentals.",h="Toreks Angriff ist ein direkter Überfall der Horde, der aus der Wildnis des Eschentals gegen die nahe...",kw={"eschental","duriel moonfire","ertog ragetusk","räuber","schildwachen","außenposten der silberschwingen","splitterholzposten","torek"},ang={["class:Warrior"]="Ein brutales, frontales Handgemenge, das rohe physische Ausdauer gegen erfahrene Bogenschützen und Klingenmeister der Schildwachen auf die Probe stellt.",["faction:Alliance"]="Der Fall von Duriel Moonfire entblößt den Außenposten der Silberschwingen und bedroht die uralten Waldgebiete der Nachtelfen.",["faction:Horde"]="Für die Horde ist das Vorrücken über den Außenposten der Silberschwingen hinaus eine entscheidende Machtprobe, welche die Blockade der Nachtelfen rund um den Splitterholzposten schwächt.",["race:NightElf"]="Der Überfall trifft das Herz des Frontkommandos der Schildwachen und vergießt Elfenblut unter den Wipfeln des Eschentals."},sec={{t="Ein Schlag aus den Schatten",b="Das Eschental befindet sich in einem eskalierenden Grenzkrieg zwischen den Holzfällerlagern der Horde und den einheimischen Nachtelfen. Um den Verteidigungsring der Allianz zu durchbrechen, versammelt Torek eine Gruppe von Räubern des Splitterholzpostens direkt vor dem Außenposten der Silberschwingen. Anstatt auf einen Gegenangriff zu warten, koordiniert Torek einen frontalen Sturmangriff, um die Verteidigung des Außenpostens zu zerschlagen, bevor die Nachtelfen einen verstärkten Feldzug gegen den Splitterholzposten starten können."},{t="Die Einnahme der Silberschwingen",b="Der Außenposten der Silberschwingen ist eine befestigte Bastion im Wald, die von wachsamen Schildwachen der Silberschwingen und wilden Elfenkriegern besetzt ist. Toreks Hauptziel ist ihre Anführerin Duriel Moonfire. Duriel zur Strecke zu bringen enthauptet die örtliche militärische Hierarchie der Nachtelfen in der Region und ermöglicht es den Räubern, Kommandant Ertog Ragetusk am Splitterholzposten einen blutigen Sieg zu melden."}},faq={{q="Wer ist Torek?",a="Torek ist ein aggressiver Orc-Räuber, der vom Splitterholzposten im Eschental aus operiert. Er ist grimmig, kampfhungrig und befehligt eine Abteilung von Räubern, die damit beauftragt ist, den Kampf direkt zu den im Wald verschanzten Streitkräften der Nachtelfen zu tragen.",al={"torek nsc","wer ist torek","torek orc"}},{q="Was ist der Außenposten der Silberschwingen?",a="Der Außenposten der Silberschwingen ist eine befestigte Nachtelfensiedlung im Eschental. Von Eliteschildwachen und Kriegern bewacht, dient er als militärisches Bollwerk, um die Truppenbewegungen der Horde entlang der Waldpfade zu überwachen.",al={"außenposten der silberschwingen","was ist silberschwingen"}},{q="Wer ist Duriel Moonfire?",a="Duriel Moonfire ist die Kommandantin der Nachtelfen, die den Außenposten der Silberschwingen verteidigt. Als Leiterin der Garnison führt sie die örtlichen Schildwachen gegen Übergriffe der Horde, bis Toreks Raubzug das Lager durchbricht, um sie niederzustrecken.",al={"duriel moonfire","duriel"}},{q="Wer ist Ertog Ragetusk?",a="Ertog Ragetusk ist ein Offizier der Horde, der am Splitterholzposten stationiert ist. Er dient als Toreks vorgesetzter Offizier, der die militärischen Operationen in der Region leitet und Berichte über Siege gegen die Allianz entgegennimmt.",al={"ertog ragetusk","ertog"}},{q="Warum greift die Horde den Außenposten der Silberschwingen an?",a="Die Horde und die Nachtelfen befinden sich im gesamten Eschental in einem aktiven Territorialkrieg. Der Angriff auf den Außenposten der Silberschwingen entlastet die Nachschublinien der Horde und schwächt direkt das Verteidigungsnetz der Schildwachen, welches das Innere des Waldes schützt.",al={"warum silberschwingen angreifen","eschental konflikt silberschwingen"}},{q="Wo findet dieser Angriff statt?",a="Der Angriff beginnt direkt vor dem Außenposten der Silberschwingen, der sich auf der östlichen, von der Horde gehaltenen Seite des Falfarren im Eschental befindet, und gipfelt im Lager der Nachtelfen selbst.",al={"toreks angriff ort","wo ist torek"}}},fx={["6e6dcd55"]={q="Warum benötigt Torek meine Hilfe für den Angriff?",a="Torek befehligt bereits einen Trupp Plünderer des Splitterholzpostens, aber seine Späher berichten, dass der Außenposten der Silberschwingen schwer von erfahrenen Nachtelfen-Wächterinnen und Kriegern befestigt ist. Da er weiß, dass die Verteidiger nicht leicht nachgeben werden, begrüßt er einen kampffähigen Champion, um ihre Frontlinie zu verstärken und sicherzustellen, dass der Schlag gegen Duriel Moonfire in einem entscheidenden Sieg der Horde endet.",al={"warum braucht torek mich","warum rekrutiert torek spieler","warum torek helfen"}}},fp="15,390,25.430.0,17.373.0,13.236.0,27.204.0,23.224.1,22.206.0,45.234.0,34.180.0"}
P.entries["quest:6545"] = {n="Aktualisierter Bericht des Läufers des Kriegshymnenklans",s="Aktualisierter Bericht des Läufers des Kriegshymnenklans ist eine Kommunikationsaufgabe der Horde, welche die vorderste Verteidigung im Eschental mit den Befehlshabern an der Grenze verbindet. Die Depesche, die Boten und neuen Rekruten anvertraut wird, beschreibt den wachsenden militärischen Druck, dem die Späher der Kriegshymnen ausgesetzt sind, insbesondere die Aggression vordringender Naga.",h="Aktualisierter Bericht des Läufers des Kriegshymnenklans ist eine Kommunikationsaufgabe der Horde, welche die...",kw={"eschental","kadrak","mor'shan","naga","schutzwall","bericht","läufer","späher","kriegshymnen"},ang={["faction:Horde"]="An der Waldgrenze zählt jeder Soldat, wo die Aufrechterhaltung der Kommunikationslinien zwischen dem Brachland und den vorgeschobenen Außenposten überlebenswichtig ist.",["race:Orc"]="Der Kriegshymnenklan verlässt sich auf die Entschlossenheit und Wachsamkeit seiner Läufer, um das unter Kriegshäuptling Thralls Befehl beanspruchte Land zu halten."},sec={{t="Frontberichte",b="Der Kriegshymnenklan unterhält im gesamten Eschental eine Kette von Spähern und Läufern, um feindliche Aktivitäten in der Umgebung zu überwachen und die Nachschublinien intakt zu halten. Zwischen territorialen Scharmützeln mit Schildwachen der Nachtelfen und der rauen Umgebung sind rasche Aufklärungsergebnisse überlebenswichtig. Kuriere, die Frontberichte überbringen, sind unerlässlich, damit abgelegene Garnisonen mit Befehlshabern wie Kadrak abgestimmt bleiben, der am Mor'shan-Schutzwall stationiert ist."},{t="Die Bedrohung durch die Naga",b="Während die Horde zwischen den Bäumen auf heftigen Widerstand der Nachtelfen gefasst ist, melden die Wachen des Außenpostens zunehmend kühnere Angriffe der Naga. Diese schlangenartigen Eindringlinge schlagen von Wasserwegen und uralten Ruinen aus zu, stellen die Barrikaden des Außenpostens auf die Probe und zwingen die Verteidiger dazu, ihre Aufmerksamkeit von Forstarbeiten und Grenzpatrouillen abzuziehen. Der zum Mor'shan-Schutzwall zurückgebrachte Bericht schlägt wegen dieser koordinierten amphibischen Angriffe Alarm."}},faq={{q="An wen wird der Bericht gesendet?",a="Der Bericht wird direkt zu Kadrak zurückgebracht, einem Aufseher, der am Mor'shan-Schutzwall an der Grenze zwischen dem Eschental und dem nördlichen Brachland stationiert ist.",al={"wer erhält bericht","kadrak bericht","wohin geht der bericht"}},{q="Welche Bedrohungen werden in dem Bericht erwähnt?",a="Der Späher berichtet, dass der örtliche Außenposten wiederholte Angriffe überstanden hat, und hebt eine eskalierende Bedrohung durch feindselige Naga hervor, die in den nahegelegenen Gewässern operieren.",al={"was steht im bericht","inhalt des läuferberichts","naga-angriffe"}},{q="Warum verlässt sich die Horde hier auf Fußläufer?",a="Dichtes Blätterdach, aktive Scharfschützen der Nachtelfen und abgelegene Außenposten machen Lufttransporte in Teilen des Eschentals schwierig oder anfällig. Bodenkuriere ermöglichen eine schnelle, unauffällige Kommunikation entlang bewachter Pfade.",al={"warum läufer","hintergrund der läufer des kriegshymnenklans","warum keine wyvern"}},{q="Wer sind die Läufer des Kriegshymnenklans?",a="Sie sind Späher, Kuriere und Vorhutkämpfer des Kriegshymnenklans, deren Aufgabe es ist, Nachschublinien zu sichern und feindliche Bewegungen entlang der umkämpften Waldgrenzen zu beobachten.",al={"kriegshymnenklan eschental","wer sind die läufer des kriegshymnenklans"}},{q="Wo greifen die Naga im Eschental an?",a="Naga haben Festungen in den Ruinen an den Ufern und Seen des Eschentals errichtet und überfallen oft Reisende und nahegelegene Lager.",al={"wo sind naga","eschental naga"}},{q="Welchen Zweck erfüllt der Außenposten in dieser Region?",a="Der Posten dient als Frühwarnstation und Verteidigungsanker, der sicherstellt, dass feindliche Truppen die Verbindung zwischen den Holzfällerarbeiten tief im Wald und dem Brachland nicht unterbrechen können.",al={"warum ist der außenposten hier","zweck des horde-lagers"}}},fx={["3fdffadb"]={q="Warum muss der Läufer des Kriegshymnenklans diesen Bericht überbringen lassen?",a="Der Außenposten steht unter wachsendem Druck durch kürzliche Angriffe der Naga, und das Kommando benötigt ein genaues Bild der Frontlinien. Der Läufer hat Wache gestanden und mehrere Wellen von Angreifern zurückgeschlagen, aber Kadrak zurück am Mor'shan-Schutzwall muss verstehen, wie gefährlich die Situation geworden ist, damit die Horde ihre Verteidigungen über das gesamte Eschental koordinieren kann.",al={"warum bericht senden","motiv des läufers","warum warsongbericht zustellen"}},ae645a70={q="Wofür ist der Warsongbericht?",a="Der Warsongbericht enthält wichtige Feldinformationen, die die eskalierenden Einfälle der Naga gegen den Außenposten beschreiben. Ihn zurückzubringen, informiert Kadrak über aktuelle Frontverteidigungen und Truppenbedarf und stellt sicher, dass die Führung der Horde über die neuesten Bedrohungen der Region informiert bleibt.",al={"zweck des warsongberichts","was ist warsongbericht","was sagt der bericht"}},["0f7ad725"]={q="Warum bittet der Läufer Euch, die Aktualisierung zu überbringen, anstatt selbst zu gehen?",a="Die Garnison des Außenpostens ist überlastet, während sie aktiv Einfälle der Naga zurückschlägt. Als kampffähiger Kurier, der ohnehin zwischen den Frontstationen reist, ermöglicht Ihr es den lokalen Verteidigern, auf ihren Posten zu bleiben, anstatt die Schutzwälle zu verlassen, um Pergament an die Grenze des Brachlands zu tragen.",al={"warum ich warsongläufer","warum nicht selbst zustellen","warum braucht der läufer euch"}}},fp="21,288,20.419.0,15.446.0,32.153.0,41.157.0,45.206.0,28.170.0,42.139.0,43.172.0"}
P.entries["quest:6546"] = {n="Aktualisierter Bericht der Vorhut des Kriegshymnenklans",s="Aktualisierter Bericht der Vorhut des Kriegshymnenklans ist eine Botenquest der Horde, die auf den gefährlichen Pfaden des östlichen Eschentals beginnt. Ein einsamer Späher des Kriegshymnenklans vertraut einem Abenteurer wichtige Aufklärungsdaten an, die Bedrohungen durch die nahe Allianz, verschanzte Satyren und vordringende Naga im benachbarten Azshara beschreiben.",h="Aktualisierter Bericht der Vorhut des Kriegshymnenklans ist eine Botenquest der Horde, die auf den...",kw={"eschental","azshara","kadrak","der mor'shan-schutzwall","naga","satyr","vorhut des kriegshymnenklans","bericht des kriegshymnenklans"},ang={["faction:Horde"]="Jede entlang der Mor'shan-Linie überbrachte Meldung stärkt die zerbrechliche Stellung der Horde in den üppigen Wäldern von Eschental.",["race:Orc"]="Der Kriegshymnenklan ist stolz darauf, die Vorhut zu bilden, doch seine Späher wissen, dass Mut allein die sie von allen Seiten umringenden Feinde nicht aufhalten kann."},sec={{t="Augen am Waldrand",b="Das östliche Eschental ist eine umkämpfte Grenzzone, in der die Nachschublinien der Horde ständigen Überfällen ausgesetzt sind. Die Vorhut des Kriegshymnenklans unterhält einen wachsamen Postenkette durch die Wälder und späht feindliche Bewegungen aus, lange bevor Überfallkommandos Außenposten wie den Mor'shan-Schutzwall oder den Splitterholzposten angreifen können. Auf eine Vorhut auf Patrouille zu treffen bedeutet, direkt ein aktives Aufklärungsgebiet zu betreten, in dem Informationen den Unterschied zwischen dem Halten einer Befestigung und ihrem Verlust durch einen Hinterhalt bedeuten können."},{t="Bedrohungen an jedem Horizont",b="Der von der Vorhut erstellte Bericht zeichnet ein düsteres taktisches Bild für die Horde in den zentralen Wäldern von Kalimdor. Neben den allgegenwärtigen Scharmützeln mit den Nachtelfen und der Allianz im Allgemeinen wimmelt es im östlichen Eschental von gerissenen, dämonischen Satyren. Erschwerend kommt hinzu, dass Späher eine massive Präsenz von Naga entdeckt haben, die sich über die verfallenen Küstengebiete des benachbarten Azshara ausbreiten, was den Kommandanten vor Augen führt, dass die Horde aus fast jeder Richtung von feindlichen Mächten bedrängt wird."}},faq={{q="Was ist der Bericht des Kriegshymnenklans?",a="Es handelt sich um einen Aufklärungsbericht, der von einer Vorhut des Kriegshymnenklans verfasst wurde und feindliche Truppenaufstellungen sowie regionale Gefahren zusammenfasst. Er hebt Bedrohungen durch nahe Streitkräfte der Allianz, aktive Satyrzirkel im östlichen Eschental und neu entdeckte Truppenbewegungen der Naga in ganz Azshara hervor.",al={"warsongbericht questgegenstand","was steht im bericht","späherbericht"}},{q="Wer ist Kadrak?",a="Kadrak ist ein Kommandant der Horde, der am Mor'shan-Schutzwall stationiert ist, der Verteidigungsbarrikade, die die nördliche Grenze zwischen dem Brachland und Eschental sichert. Er beaufsichtigt eintreffende Späher und koordiniert Vorstöße in den Wald.",al={"wer ist kadrak","wo ist kadrak","kadrak abgabe"}},{q="Warum werden die Naga in Azshara erwähnt?",a="Azshara grenzt direkt an das östliche Eschental. Die Vorhut verfolgt fremde Bewegungen in den Nachbargebieten, um sicherzustellen, dass die Flanken der Horde bei Kämpfen gegen die Nachtelfen nicht von massiven Vorstößen überrascht werden.",al={"naga azshara verbindung","warum azshara erwähnen","azshara naga bedrohung"}},{q="Was macht das östliche Eschental für die Horde so gefährlich?",a="Die Region liegt im Spannungsfeld zwischen aktiven Truppenteilen der Allianz, uralten Satyrruinen voller dämonischer Verderbnis und ungezähmten Waldtieren, wodurch Kuriere und Patrouillen der Horde aus allen Richtungen anfällig für Hinterhalte sind.",al={"warum ist östliches eschental gefährlich","eschental bedrohungen","satyrbedrohung"}},{q="Wer ist die Vorhut des Kriegshymnenklans?",a="Sie sind die Vorhut und berittene Aufklärung des Kriegshymnenklans in Eschental, die dafür zuständig ist, Bewegungen der Nachtelfen zu verfolgen, Holzfällerlager abzusichern und Handelswege zu schützen.",al={"was ist die warsongvorhut","warsongspäher","warsongvorhut lore"}},{q="Warum kann der Vorhutreiter den Bericht nicht selbst abliefern?",a="Der Vorhutreiter hat den Auftrag, seine Wache am Pfad aufrechtzuerhalten, um sich anbahnende feindliche Bewegungen in Echtzeit zu verfolgen. Das Verlassen seines Beobachtungspostens würde die Frontlinie für unerwartete Vorstöße der Allianz oder der Satyren blind machen.",al={"warum liefere ich den bericht ab","warum liefert er nicht selbst ab"}}},fx={["43097ba7"]={q="Warum muss die Vorhut des Kriegshymnenklans diesen Bericht überbringen lassen?",a="Die Horde steht an jeder Front im östlichen Eschental vor Bedrohungen. Mit der Allianz in der Nähe, Satyrn, die die Wälder verderben, und Naga, die im Grenzgebiet von Azshara Territorium besetzen, benötigt Kadrak sofortige Informationen über feindliche Bewegungen. Die Zustellung dieses Berichts stellt sicher, dass die Kommandeure der Außenposten die regionalen Gefahren verstehen und verwundbare Positionen verstärken können, bevor Feinde zuschlagen.",al={"warum bericht senden","motiv der warsongvorhut","warum aktualisierung zustellen"}}},fp="23,283,26.482.0,24.477.0,27.264.0,14.230.0,38.209.0,56.218.0,30.187.0,50.208.0"}
P.entries["quest:6547"] = {n="Aktualisierter Bericht des Spähers des Kriegshymnenklans",s="Aktualisierter Bericht des Spähers des Kriegshymnenklans ist eine Kommunikationsaufgabe der Horde, die die Außenpostenkommandanten entlang der Grenzen von Eschental mit den vorgeschobenen Spähern verbindet, die den umkämpften Wald überwachen. Kuriere überbringen strategische Befehle von Kadrak und stellen so sicher, dass der Kriegshymnenklan eine lückenlose Überwachung gegen Hinterhalte der Nachtelfen aufrechterhält. Dies verdeutlicht den heiklen, feindseligen Griff, mit dem die Horde versucht, ihr neu beanspruchtes Territorium zu behaupten.",h="Aktualisierter Bericht des Spähers des Kriegshymnenklans ist eine Kommunikationsaufgabe der Horde, die die...",kw={"eschental","brachland","kadrak","nachtelfen","bericht","späher","schildwachen","warsong"},ang={["faction:Horde"]="Jeder Läufer, der Befehle zwischen Kadrak und den äußeren Spähern überbringt, trägt dazu bei, den Stützpunkt der Horde in Eschental gegen unerbittliche Hinterhalte der Nachtelfen zu sichern.",["race:NightElf"]="Die Anwesenheit von Spähern des Kriegshymnenklans, die an den Grenzen lauern, stellt eine fortwährende Entweihung der heiligen Wälder von Elune dar, die die Schildwachen auszumerzen versuchen.",["race:Orc"]="Das Vermächtnis des Kriegshymnenklans ist geprägt von seiner Zähigkeit in Eschental, wo er sich trotz der Feindseligkeit des Landes und seiner uralten Verteidiger lebenswichtiges Bauholz erkämpft."},sec={{t="Augen in den Schatten",b="Die Grenzlande von Eschental bleiben ein Pulverfass, in dem keine Seite auch nur einen Fußbreit nachgibt. Die Hordetruppen unter Kadrak sind stark auf verstreute Späher des Kriegshymnenklans angewiesen, die in Außenposten mit hohem Risiko stationiert sind, um die Bewegungen der Nachtelfen zu verfolgen und umkämpfte Nachschublinien zu sichern. Da der Wald den heimlichen Schildwachen der Allianz natürlichen Schutz bietet, sind regelmäßige Berichte und schriftliche Aktualisierungen entscheidend, damit die isolierten Späher nicht abgeschnitten und überwältigt werden."},{t="Die Stellung halten",b="Für den Kriegshymnenklan wurde jedes gerodete oder besetzte Waldstück mit Blut bezahlt. Die Späher halten unentwegt Ausschau nach Vergeltungsangriffen der Nachtelfen, die darauf abzielen, die Wälder zurückzuerobern. Die Überbringung von Kadraks Befehlen versichert der Vorhut, dass Verstärkung und Koordination aufrechterhalten werden, sodass die Späher zurückmelden können, dass ihre Verteidigungsmaßnahmen trotz des ständigen elfischen Widerstands greifen."}},faq={{q="Wer ist Kadrak?",a="Kadrak ist ein Kommandant der Horde, der an der Grenze zwischen dem Brachland und Eschental stationiert ist. Er koordiniert Spähmissionen, Grenzverteidigung und logistische Unterstützung für die Operationen des Kriegshymnenklans, die in den uralten Wald vordringen.",al={"kadrak","wer ist kadrak","kadrak rolle"}},{q="Warum fürchten die Späher des Kriegshymnenklans die Nachtelfen so sehr?",a="Nachtelfen verschmelzen von Natur aus mit den Schatten ihrer uralten Wälder und führen plötzliche Hinterhalte auf Hordepatrouillen durch. Da der Kriegshymnenklan aktiv Holz fällt und Land besiedelt, das die Elfen als heilig erachten, sind die Späher einer ständigen Bedrohung durch tödliche Überraschungsangriffe ausgesetzt.",al={"warum furcht vor nachtelfen","nachtelfen im schatten","warsongspäher elfische gefahr"}},{q="Warum wird um Eschental gekämpft?",a="Die Horde benötigt das Holz und die Ressourcen aus Eschental, um Orgrimmar zu erbauen und ihre Siedlungen im trockenen Brachland und in Durotar zu versorgen. Die einheimischen Nachtelfen betrachten den Wald als heiligen Boden und kämpfen erbittert darum, die Holzfäller und Garnisonen der Orcs zu vertreiben.",al={"warum kampf um eschental","eschental krieg","horde eschental konflikt"}},{q="Welche Rolle spielt der Kriegshymnenklan hier?",a="Der Kriegshymnenklan führt die Expansion und die Ressourcengewinnung der Horde in Eschental an. Ursprünglich von Grom Höllschrei während des Dritten Krieges in die Wälder geführt, hat sich seine Präsenz tief verwurzelt; er betreibt Holzfällerlager und liefert sich fortlaufende Gefechte mit den Schildwachen.",al={"warsongklan eschental","warsong rolle"}},{q="Wohin gelangt dieser Bericht, nachdem er den Späher erreicht hat?",a="Nachdem der Späher Kadraks aktualisierte Befehle erhalten hat, sendet er Bericht über seine örtlichen Erfolge gegen elfische Gegenangriffe zurück, damit die Führung der Horde stets über die Stabilität der Frontlinien im Bilde ist.",al={"wer erhält bericht","kadrak bericht","späher update ergebnis"}},{q="Haben die Pläne der Horde in Eschental zu diesem Zeitpunkt Erfolg?",a="Die Späher an vorderster Front betrachten ihre Verteidigungsbemühungen als Erfolg, da es ihnen gelingt, ihre befestigten Stellungen zu halten und elfische Angriffe abzuwehren. Dennoch bleibt die Region ein hart umkämpftes Schlachtfeld, auf dem keine Seite die absolute Vorherrschaft erringen kann.",al={"gewinnt horde in eschental","warsong fortschritt"}}},fx={aadbe711={q="Warum möchte der Späher des Kriegshymnenklans, dass dies erledigt wird?",a="Späher des Kriegshymnenklans patrouillieren tief im feindlichen Gebiet des Eschentals, umgeben von Nachtelfen, die in den Schatten lauern. Der Späher benötigt neue Befehle von Kadrak, um die Verteidigung an der Front zu koordinieren, den hart erkämpften Stützpunkt im Wald zu halten und mitzuteilen, ob ihre Bemühungen, die Elfen zurückzudrängen, erfolgreich sind.",al={"motivation warsongspäher","warum bericht überbringen","warum braucht der späher befehle"}},ae4f0954={q="Wozu dient der Warsongbericht?",a="Der Warsongbericht enthält strategische Anweisungen und Truppenaufstellungen, die von Kadrak vom Mor'shan-Schutzwall aus versandt wurden. Für Späher, die isolierte Außenposten im Eschental halten, stellt der Erhalt dieses Berichts sicher, dass sie über die taktischen Manöver der Horde auf dem Laufenden bleiben, während sie die Ansprüche des Clans gegen lauernde Kräfte der Nachtelfen verteidigen.",al={"zweck warsongbericht","was bewirkt der warsongbericht","hintergrund warsongbericht"}},f7519c0a={q="Warum benötigt Kadrak einen Abenteurer, um den Bericht zu überbringen?",a="Die Grenze zwischen dem Brachland und dem Eschental ist voller Hinterhalte. Die am Mor'shan-Schutzwall stationierten Grunz und Wachen können ihre Stellungen nicht ohne Weiteres verlassen, ohne die Verteidigung des Außenpostens zu gefährden. Daher ist ein unabhängiger Reisender ein idealer Kurier, um durch die Wälder zu schlüpfen und vertrauliche militärische Anweisungen an isolierte Späher zu überbringen.",al={"warum soll ich den warsongbericht überbringen","warum können die wachen ihn nicht ausliefern","warum ich warsongspäher"}}},fp="20,404,19.450.0,18.405.0,14.224.0,57.279.0,35.261.0,37.283.0,51.212.0,60.242.0"}
P.entries["quest:6548"] = {n="Rächt mein Dorf",s="Makaba Flachhuf überlebte nur knapp einen brutalen Überfall, als Räuber des Grimtotemklans sein Dorf im südöstlichen Steinkrallengebirge überrannten. Abgeschnitten von seiner Sippe und umringt von den Toten bittet er Reisende der Horde, das Lager der Grimtotemraufbolde und angeheuerten Söldner anzugreifen, um sein gefallenes Volk zu rächen.",h="Makaba Flachhuf überlebte nur knapp einen brutalen Überfall, als Räuber des Grimtotemklans sein Dorf im...",kw={"rächt mein dorf","grimtotem","grimtotemsöldner","grimtotemraufbold","grundig darkcloud","makaba flachhuf","steinkrallengebirge"},ang={["faction:Horde"]="Die Horde ist auf offene, sichere Pässe zwischen dem Brachland und dem Steinkrallengebirge angewiesen. Eine abtrünnige Grimtotembande, die Reisende und verbündete Dörfer ermordet, bedroht die Nachschublinien des Kriegshäuptlings durch das Gebirge.",["race:Tauren"]="Der Verrat des Grimtotemklans trifft reisende Tauren am härtesten. Mitanzusehen, wie andere Shu'halo von der eigenen Art abgeschlachtet werden, führt die bittere Realität der Stammesklüfte und die Gefahr vor Augen, die die Grimtotem für Cairnes vereintes Volk darstellen."},sec={{t="Blut in den Klüften",b="Nahe der Grenze zwischen dem Brachland und den roten Felspässen des Steinkrallengebirges steht Makaba Flachhuf als einziger Überlebender eines grausamen Massakers. Räuber unter den dunklen Bannern des Grimtotemklans schlugen ohne Vorwarnung zu und metzelten nahezu jeden in seiner Siedlung nieder. Obwohl Makaba sich erbittert wehrte und mehrere Angreifer niederstreckte, wurde er schließlich in die Flucht geschlagen – mit kaum mehr als seinem nackten Leben und seinem Zorn."},{t="Die Grimtotembedrohung",b="Die Grimtotem sind den unter Oberhäuptling Cairne Bluthuf vereinten Taurenstämmen seit Langem ein widerspenstiger, aggressiver Dorn im Auge. Anders als die friedfertigen Nomaden, die durch Mulgore ziehen, heuern Kriegstrupps der Grimtotem häufig skrupellose Raufbolde und opportunistische Söldner an, um Gebiete zu erobern und abgelegene Siedlungen zu überfallen. Für Makaba haben Diplomatie oder Stammesbande keine Bedeutung mehr; nur Blut, das mit Blut vergolten wird, kann seiner Trauer Linderung verschaffen."}},faq={{q="Wer vergibt diese Quest?",a="Makaba Flachhuf ist ein überlebender Taure, der nahe dem südöstlichen Pass ins Steinkrallengebirge lagert. Er überlebte die gewaltsame Zerstörung seines nahe gelegenen Dorfes durch den Grimtotemklan und trachtet nach Vergeltung an den Angreifern.",al={"questgeber","makaba flachhuf","wer ist makaba"}},{q="Warum greifen die Grimtotem andere Tauren an?",a="Der Grimtotemklan hat die Einheit der Horde oder Cairne Bluthufs Vision vom Frieden nie wahrhaft angenommen. Grimmig territorial, fremdenfeindlich und angriffslustig überfallen sie offen rivalisierende Siedlungen, töten Außenseiter und nutzen bewaffnete Schläger sowie gedungene Söldner, um die Vorherrschaft über Regionen wie das Steinkrallengebirge an sich zu reißen.",al={"warum grimtotem feindlich","tauren greifen tauren an","geschichte des grimtotemklans"}},{q="Wo befinden sich die Grimtotemangreifer?",a="Die Raufbolde und Söldner der Grimtotem sind in einem Lager direkt westlich von Makaba Flachhufs Position im südöstlichen Steinkrallengebirge stationiert, eingebettet in die felsigen Hügel über dem Pass.",al={"wo sind die mobs","standort des grimtotemlagers","wo man raufbolde findet"}},{q="Wer sind die Grimtotemsöldner?",a="Der Grimtotemklan verstärkt seine eigenen Krieger regelmäßig durch das Anheuern skrupelloser Kämpfer und Söldner, um sicherzustellen, dass ihre Kriegstrupps über genügend Schlagkraft verfügen, um abgelegene Siedlungen zu terrorisieren und zu überrennen.",al={"söldner","grimtotemsöldner","wer sind die söldner"}},{q="Was geschieht nach dieser Quest?",a="Nachdem Ihr die Raufbolde und Söldner an vorderster Front niedergestreckt habt, bittet Makaba Euch in der Folgequest 'Kill Grundig Darkcloud', den Anführer hinter dem Massaker, Grundig Darkcloud, zur Rechenschaft zu ziehen.",al={"nächste quest","was folgt auf rächt mein dorf","tötet grundig finsterwolke"}},{q="Wo lag Makabas Dorf?",a="Makabas Siedlung war ein abgelegenes Taurenlager an den Grenzsbereichen des südöstlichen Steinkrallengebirges. Es wurde durch den Überfall der Grimtotem völlig vernichtet, sodass Makaba als einer der wenigen bekannten Überlebenden zurückblieb.",al={"flathoofs dorf","wo war das dorf","welches dorf zerstört wurde"}}},fx={ee147ee3={q="Warum will Makaba Flachhuf, dass die Grimtotem getötet werden?",a="Makaba Flachhuf sucht Rache, nachdem der Grimtotemstamm einen brutalen Überfall auf sein Dorf gestartet und fast jeden, der dort lebte, abgeschlachtet hat. Nachdem er seine Heimat und sein Volk verloren hat, treibt ihn jetzt nur noch Vergeltung gegen den Stamm an, der seine Familie und Nachbarn massakriert hat.",al={"motiv von makaba flachhuf","warum dorf rächen","warum will makaba rache"}},["2ec07636"]={q="Wer sind die Grimtotem, die dieses Gebiet ins Visier nehmen?",a="Ihr werdet gegen die Grimtotem-Raudaus und Mercenaries ausgesandt, die im Westen kampieren. Die Grimtotem sind ein aggressiver, isolationistischer Taurenstamm, der für seine Feindseligkeit gegenüber anderen Stämmen und der Horde gleichermaßen bekannt ist und lokale Siedlungen überfällt, um seinen Halt im Steinkrallengebirge auszubauen.",al={"grimtotem-raudaus und mercenaries","wen sollt ihr töten","wer griff makabas dorf an"}},bd5303e7={q="Warum benötigt Makaba Flachhuf Eure Hilfe?",a="Makaba kämpfte während des Überfalls verzweifelt und tötete so viele Grimtotem, wie er konnte, aber er entkam kaum mit dem eigenen Leben. Verwundet, isoliert und ohne Verbündete oder Dorfwachen, um sie zu versammeln, kann er sich den verbliebenen Plünderern nicht alleine stellen.",al={"warum kann makaba nicht kämpfen","warum mich fragen","warum braucht makaba hilfe"}}},fp="17,328,18.429.0,20.448.0,20.222.0,45.297.0,42.185.0,34.212.0,30.187.1,35.214.0"}
P.entries["quest:655"] = {n="Hammerfall",s="Hammerfall erzählt vom tragischen Fall von Kriegshäuptling Orgrim Schicksalshammer während der Befreiung eines Internierungslagers der Allianz im Arathihochland. Durch die von Trauer erfüllten Erinnerungen von Gor'mul erfahren Reisende, wie das Lager befreit wurde und warum die Festung ihren feierlichen Namen trägt.",h="Hammerfall erzählt vom tragischen Fall von Kriegshäuptling Orgrim Schicksalshammer während der Befreiung...",kw={"arathihochland","schicksalshammer","gor'mul","hammerfall","internierungslager","orgrim schicksalshammer","thrall","tor'gan"},ang={["class:Warrior"]="Orgrim Schicksalshammer bleibt ein ikonischer Krieger der Legende, und das Betreten des Bodens, auf dem er im Kampf fiel, besitzt eine große kriegerische Bedeutung.",["faction:Horde"]="Hammerfall steht als feierliches Denkmal für die Befreiung der Internierungslager der Orcs und das Opfer von Kriegshäuptling Orgrim Schicksalshammer.",["race:Orc"]="Für Orcs ist der Fall von Schicksalshammer in Arathi einer der schmerzvollsten Momente in ihrer Geschichte, der das Ende einer Ära und den Aufstieg von Thralls neuer Horde markiert."},sec={{t="Blut und zerbrochene Ketten",b="Hammerfall war einst ein düsteres Internierungslager der Allianz, in dem gefangene Orcs nach dem Zweiten Krieg hinter Holz und Stahl festgehalten wurden. Das änderte sich, als der junge Thrall und Kriegshäuptling Orgrim Schicksalshammer einen Angriff starteten, um die Gehege aufzubrechen und ihre Sippe zu befreien. Obwohl der Überfall erfolgreich viele Gefangene befreite und die Verteidigung des Lagers niederwarf, endete er in einer Tragödie, als Schicksalshammer von hinten von einer Lanze zu Pferd getroffen wurde und auf ebenjenem Boden starb, auf dem heute die Siedlung der Horde steht."},{t="Der anhaltende Schatten der Niederlage",b="Nicht jeder Gefangene erlangte an jenem schicksalhaften Tag die Freiheit. Im Chaos der Schlacht und den Erschütterungen der Erde sah ein Orc namens Gor'mul den legendären Kriegshäuptling fallen und verlor jeglichen Kampfesmut. Zurückgelassen, während seine Brüder flohen, verbrachte Gor'mul Jahre damit, in zielloser Trauer durch das Hochland zu wandern. Selbst jetzt, da die Horde den Ort als befestigten Stützpunkt zurückgefordert hat, verfolgt die Erinnerung an jenen feigen Streich noch immer jene, die ihn überlebt haben."}},faq={{q="Wer ist Gor'mul?",a="Gor'mul war ein gefangener Orc im Internierungslager, das einst dort stand, wo sich heute Hammerfall befindet. Obwohl Thrall und Schicksalshammer einen Angriff anführten, um das Lager zu befreien, wurde Gor'mul bei der chaotischen Flucht zurückgelassen und irrte jahrelang verzweifelt und allein umher.",al={"wer ist gormul","gor mul hintergrundgeschichte","was geschah mit gormul"}},{q="Wie starb Orgrim Schicksalshammer?",a="Orgrim Schicksalshammer wurde während der Schlacht zur Befreiung des Arathi-Internierungslagers getötet. Während er den Angriff in seiner schwarzen Plattenrüstung anführte, wurde er von hinten von einem auf einem Pferd anstürmenden Ritter der Allianz getroffen, der ihn mit einer Lanze durchbohrte.",al={"wie schicksalshammer starb","wer schicksalshammer tötete","schicksalshammers todesgeschichte"}},{q="Warum heißt der Außenposten Hammerfall?",a="Der Außenposten wurde zu Ehren von Kriegshäuptling Orgrim Schicksalshammer benannt, der genau an diesem Ort fiel, als er sein Volk aus der Gefangenschaft der Menschen befreite. Später kehrte die Horde zu dem zerstörten Lager zurück, um einen dauerhaften Stützpunkt zu errichten.",al={"warum heisst es hammerfall","ursprung des namens hammerfall","hammerfall geschichte"}},{q="Wer ist Tor'gan?",a="Tor'gan ist ein in Hammerfall stationierter Vertreter der Horde, der bei der Versorgung des Lagers hilft und das anhaltende Trauma ehemaliger Gefangener wie Gor'mul versteht.",al={"wer ist tor'gan","torgan hammerfall","torgan quest"}},{q="Hat Thrall an der Schlacht hier teilgenommen?",a="Ja. Thrall kämpfte beim Angriff auf dieses Internierungslager in Arathi an der Seite von Kriegshäuptling Orgrim Schicksalshammer. Gemeinsam durchbrachen sie die Verteidigung des Lagers, um die gefangenen Orcs zu befreien, auch wenn der Sieg das Leben von Schicksalshammer kostete.",al={"thrall und schicksalshammer arathi","befreiung von hammerfall","kämpfte thrall bei hammerfall"}},{q="Warum ist Gor'mul so niedergeschlagen?",a="Gor'mul wurde Zeuge, wie Schicksalshammer vor seinen Augen niedergestreckt wurde, was seinen Geist brach. Als die anderen Gefangenen in die Wildnis entkamen, blieb er zurück und irrte ziellos und ohne Hoffnung umher, bis die Horde zurückkehrte, um Hammerfall zu errichten.",al={"warum ist gormul so traurig","gormul depression","warum gormul die hoffnung verlor"}}},fp="10,276,23.483.0,30.437.0,15.253.0,30.240.0,36.226.0,15.172.0,40.235.0,29.230.0"}
P.entries["quest:656"] = {n="Beschwören der Prinzessin",s="Theldurin der Verirrte sagt, Myzrael müsse bezwungen werden, solange sie noch wächst, bevor ihre Stärke ausreicht, um jene herauszufordern, die sie gefangen halten. Bei den Shards of Myzrael ruft Ihr sie herbei, besiegt sie und bindet ihre Geisterhaften Fesseln an die Shards.",h="Theldurin der Verirrte sagt, Myzrael müsse bezwungen werden, solange sie noch wächst, bevor ihre Stärke...",kw={"arathihochland","geisterhafte fesseln","myzrael","rolle von myzrael","shards of myzrael","theldurin der verirrte"},sec={{t="Warum sie aufgehalten werden muss",b="Theldurin will, dass Myzrael aufgehalten wird, bevor ihre Macht so weit anschwillt, dass sie sich gegen ihre Entführer wenden kann. Manche behaupten, sie könne kontrolliert werden; Theldurin fragt sich, warum die Riesen sich dann überhaupt die Mühe machten, sie anzuketten."},{t="Bei den Shards",b="Ihr bringt die Rolle von Myzrael zu den Shards, dem Ort, an dem Ihr zuerst mit ihr gesprochen habt, und ruft sie herbei. Nachdem Ihr sie besiegt habt, könnt Ihr ihre Geisterhaften Fesseln an die Shards binden, und sie ist erneut gefangen."},{t="Wenn die Fesseln angebracht werden",b="Als sich die Fesseln um die Shards legen, steigt ein Wehklagen aus der Tiefe empor, gefolgt von einem Brüllen. Die Wärme und das Gefühl der Sicherheit, die die Shards einst ausstrahlten, sind verflogen. Nun pulsieren sie voller offener Bedrohung, als hege das Wesen unter ihnen Groll gegen die Oberfläche."}},faq={{q="Wer schickt Euch in den Kampf gegen Myzrael?",a="Theldurin der Verirrte, der davor warnt, dass Myzrael bezwungen werden muss, bevor ihre Stärke groß genug ist, um ihre Peiniger herauszufordern.",al={"questgeber","wer vergibt summoning the princess","theldurin quest"}},{q="Wo findet die Beschwörung statt?",a="Bei den Shards of Myzrael, dem Ort, an dem Ihr zuerst mit ihr gesprochen habt.",al={"wo man myzrael beschwört","shards of myzrael ort","beschwörungsort"}},{q="Warum will Theldurin, dass Myzrael besiegt wird?",a="Theldurin fürchtet, sie werde stark genug werden, um ihre Peiniger herauszufordern. Theldurin weist auch darauf hin, dass die Riesen sie nicht angekettet hätten, wenn sie sich wahrhaftig kontrollieren ließe.",al={"warum myzrael töten","theldurin motivation","warum sie beschwören"}},{q="Wie wird Myzrael beschworen?",a="Mit der Rolle von Myzrael, eingesetzt bei den Shards of Myzrael.",al={"wie man sie beschwört","rolle von myzrael verwendung","beschwörungsablauf"}},{q="Was macht Ihr mit den Geisterhaften Fesseln?",a="Besiegt Myzrael, nehmt ihre Fesseln und befestigt sie an den Shards. Dann ist sie wieder gefangen.",al={"welcher gegenstand wird benötigt","geisterhafte fesseln","fesseln von myzrael"}}},fp="22,248,23.195.0,13.212.0,28.245.1,31.116.0,36.68.0,41.173.0,24.58.0,42.92.0"}
P.entries["quest:6561"] = {n="Schurkerei in der Tiefschwarzen Grotte",s="Blackfathom-Schurkerei ist ein dringender Hilferuf eines sterbenden Kreuzfahrers der Argentumdämmerung, der in den Tiefen der Tiefschwarzen Grotte gefangen ist. Helden der Horde werden damit beauftragt, Zwielichtfürst Kelris das Handwerk zu legen – dem Kultistenführer, der in den Ruinen darunter grauenhafte Blutopfer für eine uralte Monstrosität inszeniert.",h="Blackfathom-Schurkerei ist ein dringender Hilferuf eines sterbenden Kreuzfahrers der Argentumdämmerung, der...",kw={"aku'mai","argentumdämmerung","bashana runentotem","tiefschwarze grotte","schurkerei in der tiefschwarzen grotte","kelris","mondbrunnen","thaelrid","zwielichtfürst kelris","schattenhammer"},ang={["class:Druid"]="Die Schändung eines uralten Nachtelfen-Mondbrunnens durch leerenanbetende Kultisten und Naga ist eine qualvolle Wunde für das natürliche und spirituelle Refugium Kalimdors.",["class:Shaman"]="Die von Kelris und Aku'mai heraufbeschworene Unruhe verletzt das Gleichgewicht der Elemente und verwandelt reine unterirdische Gewässer in ein fauliges Bett aus Schatten und Opferkult.",["faction:Horde"]="Für die Horde bedeutet dieser Pakt mit einem Kundschafter der Argentumdämmerung einen seltenen Moment gemeinsamen Interesses gegen eine kosmische Plage und verschafft ihr frühes Wohlwollen bei der Dämmerung.",["race:Tauren"]="Bashana Runentotem betrachtet den Sieg über Kelris als einen wesentlichen Dienst am Schutz der Erdenmutter, der eine Abscheulichkeit beseitigt hat, welche die natürliche Ordnung der Welt in ein urzeitliches Chaos stürzen wollte."},sec={{t="Ein verzweifeltes letztes Gefecht",b="Angelockt von dem unterirdischen Tempel an der Küste von Eschental entdeckte Scout Thaelrid von der Argentumdämmerung Schrecken, die weit über bloße Überfälle der Naga hinausgingen. Verwundet und seiner Kräfte beraubt in den Höhlen, erkennt der Nachtelf, dass er seine Mission nicht allein beenden kann. Anstatt seine Aufklärungsergebnisse mit sich sterben zu lassen, wendet er sich an vorbeikommende Champions der Horde, die bereit sind, die finstere Führung in den versunkenen Hallen anzugreifen."},{t="Opfergaben an die Tiefe",b="Das Ziel der Aufgabe ist Zwielichtfürst Kelris, das Oberhaupt der Kultisten des Schattenhammers, die sich im zerstörten Tempel des Mondes verschanzt haben. Im Bündnis mit den ansässigen Naga führt Kelris finstere Rituale über dem geschändeten Mondbrunnen durch und wirft Aku'mai – einer unersättlichen Hydra und Bestie der Alten Götter – lebende Gefangene zum Fraß vor, in einem wahnhaften Streben nach kosmischer Macht und primordialem Chaos."},{t="Kunde nach Donnerfels",b="Kelris galt bei der Argentumdämmerung einst als tot oder verschollen, weshalb die Bestätigung seines Todes von entscheidender Bedeutung ist. Anstatt die Helden zurück in die Länder der Menschen zu schicken, weist Thaelrid an, den Beweis für das Ableben des Kultistenführers zu Bashana Runentotem auf der Anhöhe der Ältesten in Donnerfels zu bringen. Bashana, die tief mit dem natürlichen Gleichgewicht der Erdenmutter verbunden ist, würdigt den Sieg über die Auslöschung einer abscheulichen Verderbnis, die Kalimdor in den Urzeit-Ruin stürzen wollte."}},faq={{q="Wer ist Zwielichtfürst Kelris?",a="Kelris ist der Anführer der Kultisten des Schattenhammers, welche die Tiefschwarze Grotte besetzen. Von der Argentumdämmerung für tot oder verschollen gehalten, sammelte er stattdessen heimlich Macht, indem er der uralten Hydra Aku'mai im verderbten Mondbrunnen lebende Opfer darbrachte.",al={"kelris","wer ist kelris","zwielichtfürst kelris"}},{q="Warum befindet sich ein Mitglied der Argentumdämmerung in der Tiefschwarzen Grotte?",a="Argentumwache Thaelrid kam, um der wachsenden Bedrohung im zerstörten Nachtelfentempel nachzugehen. Von den dortigen Bewohnern überwältigt und tödlich geschwächt, sitzt er in der Falle und muss sich auf durchreisende Abenteurer verlassen, um seine Pflicht zu erfüllen und Kelris auszuschalten.",al={"argentumwache thaelrid","warum ist thaelrid hier","argentumdämmerung in bfd"}},{q="Was ist Aku'mai?",a="Aku'mai ist eine monströse, uralte mehrköpfige Hydra, die als urzeitlicher Diener der Alten Götter gilt. Sie schlummerte unter den versunkenen Ruinen und erwachte, als tiefe unterirdische Verderbnis die heiligen Gewässer des Tempels verpestete; nun verschlingt sie Gefangene, die ihr vom Schattenhammer ausgeliefert werden.",al={"akumai","wer ist akumai","aku'mai lore"}},{q="Warum wird die Quest bei Bashana Runentotem abgegeben?",a="Thaelrid verweist Champions der Horde an Bashana Runentotem auf der Anhöhe der Ältesten in Donnerfels. Als Hüterin des Gleichgewichts der Erdenmutter steht Bashana in Kontakt mit Verteidigern gegen uralte Übel und erkennt in Kelris' Verehrung der Alten Götter eine abscheuliche Plage für Kalimdor.",al={"bashana runentotem","warum donnerfels","wo blackfathom-schurkerei abgeben"}},{q="Was geschah mit den Ruinen der Tiefschwarzen Grotte?",a="Vor langer Zeit war der unterirdische Komplex ein heiliger, der Mondgöttin Elune geweihter Tempel. Kataklysmische Umwälzungen und uralte finstere Sickerungen aus dem Erdreich verdarben den großen Mondbrunnen, sodass Naga und Endzeitkultisten die versunkenen Heiligtümer für ihren finsteren Meister Aku'mai beanspruchen konnten.",al={"geschichte der blackfathom-tiefe","ruinen des elune-tempels","warum ist bfd verderbt"}},{q="Was ist das Ziel des Schattenhammer-Kults hier?",a="Der Schattenhammer strebt danach, die Welt durch die Anbetung der Alten Götter in ein Zeitalter primordialen Chaos zurückzuversetzen. Kelris trachtet nach persönlicher Macht durch finstere Zwiegespräche und wirft Unschuldige in die Tiefe, um sich die Gunst uralter Wesenheiten zu sichern.",al={"motive des schattenhammers","warum kult in bfd","kelris ziele"}}},fx={["8c6f2eb7"]={q="Warum will Argentumwache Thaelrid, dass Zwielichtfürst Kelris getötet wird?",a="Zwielichtfürst Kelris und seine Kultisten des Schattenhammers opfern aktiv unschuldige Gefangene an Aku'mai, einen niederträchtigen Diener der Alten Götter, im Austausch für dunkle Macht. Thaelrid wurde von der Argentumdämmerung ausgesandt, um diese Schrecken zu beenden, und er kann nicht zulassen, dass die Verderbtheit und die chaotische Anbetung des Kults ungehindert weitergehen.",al={"beweggrund von thaelrid","warum will thaelrid kelris tot","warum kelris töten"}},["6dbae1c3"]={q="Wofür dient Kelris Kopf?",a="Der Kopf dient als unbestreitbarer Beweis für das Ableben des Kultführers. Kelris entkam der Argentumdämmerung lange Zeit, was viele zu der Annahme verleitete, er sei bereits tot oder verschollen. Ihn also Bashana Runetotem in Donnerfels zu präsentieren, bestätigt, dass seine Schreckensherrschaft und die Menschenopfer wahrhaftig ein Ende gefunden haben.",al={"zweck von kelris kopf","was tun mit kelris kopf","warum kelris kopf nehmen"}},f2efcdf9={q="Warum braucht Thaelrid Eure Hilfe, statt Kelris selbst aufzuhalten?",a="Thaelrid wurde tief im Versunkenen Tempel schwer verwundet. Geschwächt, ausgelaugt und völlig kraftlos kann er dem Kultführer nicht allein entgegentreten. Damit seid Ihr der Einzige, der seine Mission vollenden kann.",al={"warum braucht thaelrid hilfe","warum kann thaelrid kelris nicht bekämpfen","thaelrid warum ich"}}},fp="20,291,22.427.0,22.381.0,21.422.1,28.273.0,54.252.0,16.279.0,43.278.0,48.281.0,52.231.0"}
P.entries["quest:6562"] = {n="Ärger in der Tiefe",s="Ärger in der Tiefe ist ein Hilferuf, der aus dem Steinkrallengebirge an die abgelegenen Küsten von Eschental gesandt wird. Tsunaman weist Abenteurer der Horde an, den Trollgelehrten Je'neu Sancrea am Außenposten von Zoram'gar aufzusuchen, und warnt davor, dass gefährliche Mächte entlang der Küste lauern.",h="Ärger in der Tiefe ist ein Hilferuf, der aus dem Steinkrallengebirge an die abgelegenen Küsten von Eschental...",kw={"eschental","tiefschwarze grotte","je'neu sancrea","steinkrallengebirge","tsunaman","die scherwindklippe","der zoramstrand","außenposten von zoram'gar"},ang={["class:Shaman"]="Die Störung unter den Wellen des Zoramstrands bedroht das Gleichgewicht der örtlichen Wassergeister und verlangt nach spiritueller Einsicht, um die Fäulnis zu reinigen.",["faction:Horde"]="Die Stellung am Außenposten von Zoram'gar zu halten, ist entscheidend, um die Westflanke von Kalimdor sowohl gegen Streitkräfte der Nachtelfen als auch gegen Schrecken der Küste zu sichern.",["race:Troll"]="Dem Ruf von Je'neu Sancrea zu folgen, bietet den Angehörigen der Dunkelspeere eine entscheidende Gelegenheit, einem ihrer bedeutendsten Gelehrten bei der Lüftung uralter Geheimnisse von Kalimdor zu helfen."},sec={{t="Ein Ruf an die Küste",b="In den kargen Klüften des Steinkrallengebirges erkennt Tsunaman, dass finstere Gerüchte im Norden Aufmerksamkeit verlangen. Er beauftragt fähige Reisende der Horde damit, nach Eschental aufzubrechen – dem angestammten Wald der Nachtelfen –, um Kontakt mit Je'neu Sancrea aufzunehmen. Stationiert am Außenposten von Zoram'gar am äußersten westlichen Rand, der als der Zoramstrand bekannt ist, sieht sich Je'neu einer wachsenden Gefahr gegenüber, die ein Eingreifen von außen erfordert."},{t="Der Weg zum Zoramstrand",b="Das Erreichen des westlichen Ufers von Eschental ist für Reisende der Horde keine leichte Reise. Ob sie nun die von Goblins gestörten Pässe der Scherwindklippe durchqueren oder aus dem Brachland nach Norden ziehen – Reisende müssen einen feindseligen Wald betreten, der von Schildwachen der Nachtelfen erbittert bewacht wird. Weit hinter dem dichten Blätterdach, an der sturmumtosten Küste des Zoramstrands, klammert sich der einsame Außenposten ans Überleben, während er in die nahe gelegenen schattigen Gewässer blickt."},{t="Flüstern unter den Wellen",b="Nach der Ankunft an der Küste enthüllt Je'neu Sancrea, dass der sich anbahnende Ärger seine Wurzeln im unterirdischen Tempel der Tiefschwarzen Grotte hat. Uralte Verderbnis, üble Wasserelementare und Kultisten des Twilight's Hammer haben sich unter den Gezeiten versammelt, um uralte Übel wieder in die Welt zu locken. Je'neu verlässt sich auf eintreffende Champions, die unter die Oberfläche vordringen und sich dem urzeitlichen Schrecken stellen, der in den versunkenen Hallen erwacht ist."}},faq={{q="Wer vergibt die Quest Ärger in der Tiefe?",a="Tsunaman, der sich im Steinkrallengebirge befindet, bietet die Quest an. Er erkennt, dass Verbündete entlang der Küste von Eschental Verstärkung benötigen, und weist reisenden Abenteurern der Horde den Weg zum Meer.",al={"questgeber","wer startet ärger in der tiefe","tsunaman"}},{q="Wo befindet sich Je'neu Sancrea?",a="Je'neu Sancrea ist am Außenposten von Zoram'gar am Zoramstrand stationiert, an der äußersten westlichen Küstenlinie von Eschental.",al={"wo ist je'neu","standort von jeneu sancrea","außenposten von zoram'gar"}},{q="Wie erreicht Ihr den Außenposten von Zoram'gar aus dem Steinkrallengebirge?",a="Reisende können nach Nordosten durch die Scherwindklippe nach Eschental ziehen oder einen Bogen nach Osten durch das Brachland machen und den Wald von Süden her betreten. Reist vom zentralen Eschental aus direkt nach Westen, bis Ihr die offenen Gewässer des Zoramstrands erreicht.",al={"weg nach eschental","weg zum zoramstrand","route vom steinkrallengebirge nach eschental"}},{q="Welchen Ärger untersucht Je'neu?",a="Je'neu Sancrea überwacht die nahe gelegenen Ruinen der Tiefschwarzen Grotte, wo Kultisten und verderbte Wasserwesen uralte Schrecken unter der Oberfläche aufrühren.",al={"was am zoramstrand geschieht","warum jeneu hilfe braucht"}},{q="Welche Quest folgt auf Ärger in der Tiefe?",a="Das Gespräch mit Je'neu Sancrea führt direkt zu The Essence of Aku'Mai, wodurch Abenteurer in die Tiefschwarze Grotte geschickt werden, um die elementar aufgeladenen Sapphires of Aku'Mai aus ihren Tunneln zu sammeln.",al={"nächste quest","folgequest zu ärger in der tiefe"}},{q="Warum gilt die Reise durch Eschental als gefährlich?",a="Eschental ist das souveräne Herrschaftsgebiet der Nachtelfen, die sich jedem Vordringen der Horde erbittert widersetzen. Reisende, die das Waldland durchqueren, riskieren, feindseligen Schildwachen und schwer fassbaren Angreifern aus dem Hinterhalt zu begegnen.",al={"gefahr in eschental","bedrohung durch nachtelfen"}}},fx={dde1b6c4={q="Warum schickt Tsunaman Euch zu Je'neu Sancrea?",a="Tsunaman weiß, dass Je'neu Sancrea am abgelegenen Außenposten von Zoram'gar isoliert ist und verzweifelt fähige Verbündete benötigt. Stationiert an der fernen Westküste von Eschental, sieht sich Je'neu zunehmenden Gefahren rund um die geheimnisvollen Tiefen der Tiefschwarzen Grotte ohne ausreichende Unterstützung gegenüber. Tsunaman entsendet Euch, um ihn zu verstärken, bevor feindliche Streitkräfte den Stützpunkt der Horde überwältigen.",al={"warum will tsunaman dies erledigt haben","warum schickst du mich nach eschental","beweggrund von tsunaman"}}},fp="20,265,22.435.0,24.425.0,24.420.1,41.195.0,32.121.0,51.230.0,37.161.0,40.192.0,57.194.0"}
P.entries["quest:6563"] = {n="Die Essenz von Aku'mai",s="Je'neu Sancrea am Außenposten von Zoram'gar hat bemerkt, dass die Naga der Tiefschwarzen Grotte mächtige Saphiransammlungen in den Höhlen abbauen. Beunruhigt über deren magische Eigenschaften und elementare Wasserenergien beauftragt der Schamane Abenteurer der Horde damit, die Edelsteine zu bergen, bevor sie missbraucht werden können.",h="Je'neu Sancrea am Außenposten von Zoram'gar hat bemerkt, dass die Naga der Tiefschwarzen Grotte mächtige...",kw={"eschental","tiefschwarze grotte","je'neu sancrea","naga","saphir von aku'mai","trouble in the deeps","wassergeister","der zoramstrand"},ang={["class:Shaman"]="Je'neu Sancreas Deutung der Kristalle hebt die unruhigen Wassergeister hervor, die an sie gebunden sind – eine subtile Warnung, dass unter dem Tempel elementare Mächte verderbt werden.",["faction:Horde"]="Der Stützpunkt der Horde am Außenposten von Zoram'gar ist gefährdet; die nahegelegenen Naga daran zu hindern, rohe magische Macht zu erlangen, trägt zum Schutz des Lagers an der Küste bei.",["race:Troll"]="Je'neu Sancrea erweist sich als aufmerksamer Mystiker der Dunkelspeere, der sich auf den Austausch mit den Geistern und die Weisheit der Ahnen verlässt, um den fremdartigen Bedrohungen Kalimdors zu begegnen."},sec={{t="Eine Bedrohung in der Tiefe",b="An den nebelverhangenen Gestaden des Zoramstrands wacht der Dunkelspeer-Schamane Je'neu Sancrea über uralte Kaldorei-Ruinen, die nun von finsteren Mächten heimgesucht werden. Tief in den überfluteten Kammern der Tiefschwarzen Grotte haben Naga begonnen, leuchtende Saphirformationen abzubauen, die an den feuchten Höhlenwänden sprießen. Da Sancrea spürt, dass die schlangenartigen Eindringlinge diese unbeständige Macht nutzen wollen, versucht er, die Ernte abzufangen, bevor ihre Pläne Früchte tragen können."},{t="Wassergeister und arkane Macht",b="Die Sapphires of Aku'mai sind weit mehr als gewöhnliche Edelsteine; sie vibrieren vor elementarer Resonanz und beherbergen anhaftende Wassergeister. In den Händen fähiger Zauberer könnten solche Kanäle gefährliche arkane Rituale speisen oder den Einfluss der schattenhaften Hydra Aku'mai verstärken, deren finstere Präsenz den unterirdischen Tempel durchdringt. Die Bergung dieser Ansammlungen beraubt die Naga eines unschätzbaren Reagenzes und schützt die Küstenlinie vor unkontrollierter Elementarmagie."}},faq={{q="Wer vergibt diese Quest?",a="Die Quest wird von Je'neu Sancrea angeboten, einem Schamanen der Dunkelspeertrolle, der am Außenposten von Zoram'gar am Zoramstrand im nordwestlichen Eschental stationiert ist.",al={"questgeber","wer startet die essenz von aku'mai","aufenthaltsort von je'neu sancrea"}},{q="Warum wollen die Naga die Sapphires of Aku'Mai?",a="Obwohl ihre genauen Pläne im Verborgenen liegen, verfügen die Saphire über gewaltige elementare Wasserenergie sowie rohe magische Macht, was sie zu außergewöhnlich gefährlichen Reagenzien für das Wirken von Zaubern der Naga macht.",al={"warum wollen die naga saphire","wozu dienen die kristalle","zweck der saphire"}},{q="Wo sind die Saphiransammlungen zu finden?",a="Sie säumen die Höhlenwände und -böden in den äußeren Tunneln und überfluteten Gängen der Tiefschwarzen Grotte, gleich hinter dem verfallenen unterirdischen Eingang am Zoramstrand.",al={"wo findet man saphire","fundort von saphir von aku'mai","kristallvorkommen"}},{q="Was ist Aku'mai?",a="Aku'mai ist eine monströse dreiköpfige Hydra, die tief in den überfluteten Tempelruinen haust. Er wird von den Kultisten des Schattenhammers verehrt und als Diener der Alten Götter gefürchtet.",al={"wer ist aku'mai","was ist aku'mai","aku'mai"}},{q="Muss ich für diese Quest Dungeon-Bosse töten?",a="Nein. Die Saphiransammlungen wachsen an den Höhlenwänden in den früheren überfluteten Tunneln, noch bevor man auf die Hauptbosse der Tiefschwarzen Grotte trifft.",al={"brauche ich eine volle gruppe","kann ich saphire alleine sammeln","bossanforderung"}},{q="Ist diese Quest mit einer anderen Handlung verbunden?",a="Ja. Sie folgt auf „Trouble in the Deeps“ und ist Teil von Je'neu Sancreas Untersuchung der wachsenden Dunkelheit und der Aktivitäten der Kultisten, die sich in der Tiefschwarzen Grotte ausbreiten.",al={"questreihe","voraussetzungen","trouble in the deeps"}}},fx={["7dd39a86"]={q="Warum möchte Je'neu Sancrea die Saphire von Aku'mai?",a="Je'neu Sancrea bemerkte, dass die Naga diese Kristallgruppen systematisch von den Höhlenwänden der Tiefschwarzen Grotte ernten. Während ihr genauer Plan unklar bleibt, spürt er gewaltige elementare Energie, die in den Steinen verweilt. Er möchte, dass sie gesammelt werden, bevor die Naga sie als mächtige arkane Komponenten waffenfähig machen können.",al={"beweggrund von jeneu sancrea","warum saphire sammeln","warum saphire von akumai sammeln"}},["644dacf9"]={q="Was ist der Saphir von Aku'mai?",a="Diese Saphire sind kristalline Formationen, die die überfluteten Tunnel der Tiefschwarzen Grotte säumen. Sie resonieren mit roher elementarer Kraft und ziehen Wassergeister an, die sich an sie klammern. Aufgrund dieser natürlichen Energiekonzentration dienen sie als gewaltige arkane Reagenzien, sofern sie korrekt kanalisiert werden.",al={"was sind die saphire","lore der saphire von akumai","kraft der saphire von akumai"}}},fp="22,287,22.461.0,30.455.0,21.143.0,46.181.0,38.169.0,16.179.0,52.144.0,47.168.0"}
P.entries["quest:6564"] = {n="Treue zu den Alten Göttern",s="Treue zu den Alten Göttern ist eine Quest der Horde, die durch die Bergung einer durchnässten Botschaft von den Naga in der Tiefschwarzen Grotte begonnen wird. Die Übergabe der Notiz an Je'neu Sancrea am Außenposten von Zoram'gar deckt eine finstere rituelle Verschwörung auf, die sich tief in den überfluteten Ruinen der Tiefschwarzen Grotte entfaltet.",h="Treue zu den Alten Göttern ist eine Quest der Horde, die durch die Bergung einer durchnässten Botschaft von...",kw={"aku'mai","treue","eschental","tiefschwarze grotte","feuchte notiz","je'neu sancrea","lorgus jett","alte götter","wrathscale","außenposten von zoram'gar"},ang={["class:Shaman"]="Die Unterjochung von Wasserelementargeistern in Ritualkristallen durch die Naga stellt eine schwere Perversion des natürlichen Gleichgewichts dar, die eine rasche Korrektur erfordert.",["faction:Horde"]="Die Entdeckung von Lorgus Jetts Notiz hilft dabei, den Außenposten von Zoram'gar gegen den Twilight's Hammer und seine Naga-Verbündeten zu sichern, die den Stützpunkt der Horde an der Westküste des Eschentals bedrohen.",["race:Troll"]="Die Unterstützung Eures Dunkelspeer-Verwandten Je'neu Sancrea entlarvt uralte kosmische Wesenheiten, deren Rückkehr jeden Stamm in ganz Azeroth bedrohen würde."},sec={{t="Eine gekritzelte Erklärung",b="Beim Kampf gegen die Naga der Tiefschwarzen Grotte entdecken Späher der Horde eine feuchte, zusammengeknüllte Notiz mit einer hektischen Handschrift. Das bekritzelte Pergament enthält detaillierte Anweisungen an die Naga-Priesterinnen, in denen sie angewiesen werden, elementare Wasserkristalle zu sammeln. Weit entfernt von willkürlicher Plünderung werden diese Kristalle gesammelt, um die Beschwörungen der Naga-Aquamanten zu speisen und Elementarkräfte für ein weitaus düstereres Ziel zu sammeln."},{t="Flüstern der Tiefe",b="Die sichergestellten Befehle enthüllen, dass die Naga beabsichtigen, die Elementarenergie in den Kristallen zu nutzen, um Aku'mai, eine monströse Hydra im Dienste der Alten Götter, zu besänftigen und vollständig zu beschwören. Die Notiz verkündet kühn, dass dies die Rückkehr zur „größten Ära“ der Welt einläuten wird – der prähistorischen Herrschaft der Alten Götter. Nach Erhalt des Pergaments am Außenposten von Zoram'gar identifiziert der Dunkelspeermystiker Je'neu Sancrea den Urheber dieser Verschwörung: den Twilight's Hammer-Kultisten Lorgus Jett."}},faq={{q="Was ist die Feuchte Notiz?",a="Die Feuchte Notiz ist eine Reihe sichergestellter Befehle, die von dem Twilight's Hammer-Kultisten Lorgus Jett verfasst wurden. Sie weist die Naga-Priesterinnen an, von Elementarenergie erfüllte Kristalle zu sammeln, um ihre Aquamanten zu stärken und den monströsen Diener Aku'mai zu beschwören.",al={"feuchte notiz","was steht auf der notiz","notiz lore"}},{q="Wer ist Je'neu Sancrea?",a="Je'neu Sancrea ist ein Seher und Gelehrter der Dunkelspeertrolle, der am Außenposten von Zoram'gar im Eschental stationiert ist. Als Vertreter des Irdenen Rings untersucht er elementare Ungleichgewichte und uralte Bedrohungen, die aus den nahegelegenen Ruinen der Tiefschwarzen Grotte erwachsen.",al={"jeneu sancrea","wer ist jeneu","questgeber außenposten von zoram'gar"}},{q="Wer ist Lorgus Jett?",a="Lorgus Jett ist ein menschlicher Schamane des Twilight's Hammer-Kults, der in der Tiefschwarzen Grotte operiert, wo die Kultisten mit den Naga verbündet sind. Er überwacht das Ernten von Elementarkristallen, um Rituale der Naga zu stärken und dunkle uralte Schrecken wiederzuerwecken.",al={"lorgus jett","wer hat die notiz geschrieben","naga-anführer zoram"}},{q="Was ist Aku'mai?",a="Aku'mai ist eine kolossale dreiköpfige Hydra, die in den überfluteten Tiefen der Tiefschwarzen Grotte haust. Eng an die ursprüngliche Dunkelheit der Alten Götter gebunden, wird die Kreatur sowohl vom Twilight's Hammer-Kult als auch von den Naga der Tiefschwarzen Grotte verehrt.",al={"akumai","wer ist akumai","aku'mai lore"}},{q="Warum sammeln die Naga Wasserkristalle?",a="Die in den Kristallen gefangenen Wasserelementargeister verleihen den Naga-Aquamanten rohe Macht. Indem sie diese Elementarmagie abziehen, hoffen sie, Aku'mai zu besänftigen und genügend Macht zu sammeln, um die Rückkehr der Alten Götter einzuläuten.",al={"warum naga-kristalle","elementarkristalle naga","kristalle der aquamanten"}},{q="Wohin führt diese Questreihe?",a="Die Übergabe der Notiz an Je'neu Sancrea führt direkt zu einer Folgemission, deren Aufgabe es ist, Lorgus Jett aufzuspüren und hinzurichten, um die Ritualpläne des Kults in der Tiefschwarzen Grotte zu durchkreuzen.",al={"was kommt nach treue zu den alten göttern","treue zu den alten göttern teil 2","nächste quest"}}},fp="26,282,23.413.0,20.491.1,22.235.0,22.236.0,19.248.0,16.251.0,43.226.0,33.186.1"}
P.entries["quest:6565"] = {n="Treue zu den Alten Göttern",s="Treue zu den Alten Göttern ist eine Horde-Quest, bei der Abenteurer den Auftrag erhalten, Lorgus Jett in den Tiefen der Tiefschwarzen Grotte zu eliminieren. Geleitet vom Seher der Dunkelspeere Je'neu Sancrea am Außenposten von Zoram'gar zielt die Mission darauf ab, die Kultisten des Schattenhammers zu stören, die uralte Zerstörungskräfte erwecken wollen. Das Niederschlagen von Lorgus versetzt den subversiven Machenschaften des Kults unter der Küste von Eschental einen direkten Schlag.",h="Treue zu den Alten Göttern ist eine Horde-Quest, bei der Abenteurer den Auftrag erhalten, Lorgus Jett in den...",kw={"treue zu den alten göttern","eschental","tiefschwarze grotte","je'neu sancrea","lorgus jett","alte götter","schattenhammer","zoram'gar"},ang={["class:Shaman"]="Der Schattenhammer versucht, elementare Wut im Dienste der chaotischen Alten Götter zu entfesseln, was seine Auslöschung zu einer Priorität für all jene macht, die gemeinsam mit dem Irdenen Ring geschworen haben, das Gleichgewicht der Elemente zu wahren.",["faction:Horde"]="Das Ausschalten von Lorgus Jett sichert die Umgebung des Zoram'gar-Außenpostens und schützt das abgelegene Küstenlager der Horde in Eschental vor heimtückischen Plänen der Kultisten.",["race:Troll"]="Je'neu Sancrea beizustehen ehrt die Weisheit eines angesehenen Sehers der Dunkelspeere, der weit entfernt von den Echoinseln im Einsatz ist, um Azeroths Urgeister zu beschützen."},sec={{t="Die Bedrohung unter Zoram'gar",b="Ankernd am Strand von Eschental wacht der Außenposten der Horde bei Zoram'gar nervös über die Tiefschwarze Grotte. Der versunkene Tempelkomplex hat sich zu einer Brutstätte dunkler Zauberei entwickelt, überrannt von Naga, verderbten Bestien und den verhüllten Fanatikern des Schattenhammers. Je'neu Sancrea, ein an der Küste stationierter Seher des Irdenen Rings, erkennt, dass die Kultisten weder das natürliche Gleichgewicht noch die Geister des Landes verehren. Stattdessen geloben sie den Alten Göttern ihre Knechtschaft – monströsen Wesen des Chaos, die in uralten Zeitaltern besiegt wurden und deren bösartige Berührung noch immer in den vergessenen Winkeln Azeroths verweilt."},{t="Das Ende von Lorgus Jett",b="Je'neu beauftragt Champions der Horde damit, in die unterirdischen Ruinen vorzudringen, um Lorgus Jett zur Strecke zu bringen, einen entscheidenden Anführer in den Reihen der Kultisten. Lorgus agiert tief in den steinernen Gängen, die sich zwischen den Kammern der Riesenschildkröte Ghamoo-ra und des Wasserelementars Baron Aquanis erstrecken. Je'neu selbst ist zu gebrechlich, um in die feuchte Dunkelheit zu marschieren, weshalb die Hinrichtung von Lorgus unerlässlich ist, um welche dunklen Rituale auch immer zu unterbinden, die der Kultist unter den Wellen von Eschental inszenieren wollte."},{t="Abwendung des Chaos",b="Mit dem Tod von Lorgus Jett ist die unmittelbare rituelle Bedrohung für die Küste eingedämmt, doch Je'neu räumt ein, dass der Schattenhammer noch lange nicht ausgerottet ist. Die schleichende Infiltration alter heiliger Stätten durch den Kult kündet von einer weitreichenderen, lauernden Gefahr, die nichts Geringeres als die absolute Rückkehr der Alten Götter anstrebt. Für die Horde bei Zoram'gar verschafft der Sieg über Lorgus wertvolle Zeit gegen einen Feind, der sich in den Schatten der Welt verbirgt."}},faq={{q="Wer ist Lorgus Jett?",a="Lorgus Jett ist ein prominenter Anführer der Kultisten des Schattenhammers in der Tiefschwarzen Grotte. Er leitet Kultrituale, die darauf abzielen, die Rückkehr und Herrschaft der uralten Alten Götter herbeizuführen.",al={"lorgus jett","wer ist lorgus","lorgus jett lore"}},{q="Wo ist Lorgus Jett in der Tiefschwarzen Grotte zu finden?",a="Lorgus Jett patrouilliert in den überfluteten Korridoren der Tiefschwarzen Grotte, genauer gesagt in den Verbindungsgängen zwischen der Kammer von Ghamoo-ra und dem Altarbereich von Baron Aquanis.",al={"lorgus jett aufenthaltsort","wo ist lorgus","lorgus jett finden"}},{q="Wer ist Je'neu Sancrea?",a="Je'neu Sancrea ist ein Seher der Dunkelspeertrolle, der dem Irdenen Ring angehört und am Außenposten von Zoram'gar auf dem Zoramstrand in Eschental stationiert ist, um elementare Unruhen und die Verderbnis in der Tiefschwarzen Grotte zu überwachen.",al={"je'neu sancrea","wer gibt treue zu den alten göttern","jeneu"}},{q="Warum kümmert sich Je'neu um den Schattenhammer?",a="Als Seher, der sich dem Verständnis der Natur und des elementaren Gleichgewichts verschrieben hat, sieht Je'neu im Schattenhammer eine existenzielle Bedrohung. Der Kult dient den Alten Göttern, chaotischen uralten Wesenheiten, deren Rückkehr die Harmonie der Welt zerstören würde.",al={"warum schattenhammer bekämpfen","irdener ring alte götter"}},{q="Was sind die Alten Götter?",a="Die Alten Götter sind urzeitliche Wesen des Chaos und der Zerstörung, die Azeroth in ferner Vergangenheit beherrschten, bevor sie besiegt und verbannt wurden. Der Kult des Schattenhammers verehrt sie aktiv und schmiedet Pläne, um ihre Siegel zu brechen und ihre zerstörerische Herrschaft zurückzubringen.",al={"alte götter lore","wer sind alte götter","wesen des chaos"}},{q="Warum kann Je'neu Sancrea Lorgus Jett nicht selbst töten?",a="Je'neu räumt ein, zu gebrechlich und schwach zu sein, um den Gefahren der Tiefschwarzen Grotte allein zu trotzen. Er verlässt sich darauf, dass fähige Champions der Horde den Kampf übernehmen, während er die spirituellen und elementaren Erschütterungen vom Außenposten aus verfolgt.",al={"warum jeneu nicht geht","ist jeneu schwach"}}},fp="26,413,28.592.0,18.482.0,17.443.1,19.195.0,52.170.0,22.217.0,49.232.0,22.254.0,50.224.0"}
P.entries["quest:6568"] = {n="Nachricht von Rexxar",s="Rexxar sagt, dass es einer Illusion bedarf, um an den Verteidigungen des Schwarzen Drachenschwarms vorbeizukommen. Er kennt eine Meisterillusionistin, Myranda die Vettel, die in den Westlichen Pestländern lebt, und schickt Euch mit einer Nachricht zu ihr.",h="Rexxar sagt, dass es einer Illusion bedarf, um an den Verteidigungen des Schwarzen Drachenschwarms...",kw={"schwarzer drachenschwarm","desolace","illusion","meisterin der täuschung","myranda die vettel","rexxar","trauerhügel","testament von rexxar","westliche pestländer"},sec={{t="Die Kunst der Illusion",b="Rexxar fragt, was Ihr über Illusionen wisst, da Ihr die Verteidigungen des Schwarzen Drachenschwarms mithilfe einer Illusion umgehen werdet. Er nennt jemanden, der Euch bei einer solchen Täuschung behilflich sein könnte: Myranda die Vettel, eine von der Allianz von Lordaeron vertriebene Meisterillusionistin, die in den Westlichen Pestländern lebt. Rexxar sagt, dass sie Seinesgleichen schon zuvor zur Hand gegangen ist, wann immer sie eine Sache für würdig befand. Ihr überbringt ihr seine Botschaft."},{t="Ein Besucher in Lordaeron",b="Myranda bemerkt, dass ein Mitglied der Horde in diesen Teilen von Lordaeron ein seltener Anblick ist, und sie fragt, was Ihr ihr gebracht habt."},{t="Myrandas Antwort",b="Myranda hält die Notiz, hält inne und lächelt. Sie erkundigt sich nach Rexxar und erklärt dann, dass das Blatt mit Absicht unbeschrieben war: Es trug die Gedanken und Absichten seines Verfassers, und sie versteht, warum er auf Tinte verzichtete, da es gefährlich gewesen wäre, falls Ihr gefangen genommen oder getötet worden wäret. Sie erklärt sich bereit, Euch zu helfen, da sie dem Kriegshäuptling noch den einen oder anderen Gefallen schuldet."}},faq={{q="Wer ist Myranda die Vettel?",a="Myranda die Vettel ist eine Meisterillusionistin, die einst aus Lordaeron stammte und von dessen Allianz verbannt wurde. Sie ist in den Westlichen Pestländern auf dem Trauerhügel zu finden.",al={"wer ist myranda","myranda die vettel lore","wo ist myranda"}},{q="Warum müsst Ihr eine Illusionskünstlerin aufsuchen?",a="Rexxar sagt, dass Ihr die Verteidigungen des Schwarzen Drachenschwarms mithilfe einer Illusion umgehen werdet, und er kennt eine Meisterin, die helfen könnte.",al={"warum verkleidung","warum eine illusionskünstlerin aufsuchen","den schwarzen drachenschwarm täuschen"}},{q="Wohin schickt Euch Rexxar?",a="Er schickt Euch in die Westlichen Pestländer, um Myranda die Vettel auf dem Trauerhügel zu finden.",al={"wohin muss ich gehen","wo ist trauerhügel","zielort der meisterin der täuschung"}},{q="Hat Myranda der Horde schon zuvor geholfen?",a="Rexxar sagt, dass sie Seinesgleichen schon zuvor geholfen hat, wann immer sie die Sache für würdig befand.",al={"mag myranda die horde","myranda allianz oder horde","myranda gefallen kriegshäuptling"}}},fp="23,204,19.393.0,22.127.0,16.328.1,23.154.0,37.115.0,27.80.0,36.80.0"}
P.entries["quest:657"] = {n="Hinweise auf eine neue Seuche?",s="Quae hat die Mappe durchgesehen und erfahren, dass Apotheker Jorell auf Go'Sheks Hof tödliche Experimente durchführt. Quae ist nach einem Zusammenstoß mit Orcs in schlechter Verfassung und kann Kinelory nicht helfen, die Euren Schutz brauchen wird, wenn sie sich zum Hof aufmacht, um jegliche Forschung von Jorell zu stehlen, die noch nicht nach Tarrens Mühle geschickt wurde.",h="Quae hat die Mappe durchgesehen und erfahren, dass Apotheker Jorell auf Go'Sheks Hof tödliche Experimente...",kw={"apotheker jorell","verlassene","go'sheks hof","kinelory","phin","seuche","quae","tarrens mühle"},sec={{t="Jorells Experimente",b="Quae liest die Mappe durch und stellt fest, dass Apotheker Jorell auf Go'Sheks Hof tödliche Experimente durchführt. Wie dies Hillsbrad berührt, ist Quae unklar, doch Phin würde nicht wollen, dass es weitergeht. Ein Teil von Jorells Forschung wurde bereits nach Tarrens Mühle geschickt."},{t="Kinelorys Beschützer",b="Während Ihr fort wart, geriet Quae mit einigen Orcs aneinander und ist nicht in der Verfassung, Kinelory zu helfen. Kinelory beabsichtigt, zum Hof hinunterzugehen und die Forschung zu stehlen, die Jorell noch nicht nach Tarrens Mühle geschickt hat, und sie wird Schutz brauchen. Ihr sollt mit Kinelory sprechen."},{t="Kinelorys Entschlossenheit",b="Kinelory sagt, dass sie jeden Einzelnen der Verlassenen persönlich vernichten wird, wenn es Phin Frieden bringt. Phin hat seit der Seuche so viel für Kinelory und die anderen getan, und sie hätten nie gedacht, dass sie jemals wieder Freunde oder Familie finden würden. Kinelory bittet Euch zu sagen, wann Ihr bereit seid, und Ihr beide werdet sofort aufbrechen."}},faq={{q="Warum kann Quae Kinelory nicht begleiten?",a="Quae geriet mit einigen Orcs aneinander, während Ihr fort wart, und ist nicht in der Verfassung, Kinelory zu helfen.",al={"warum quae bleibt","warum quae nicht hilft","warum kinelory allein eskortieren"}},{q="Was wurde in der Mappe entdeckt?",a="Dass Apotheker Jorell auf Go'Sheks Hof an tödlichen Experimenten gearbeitet hat.",al={"was in der mappe war","jorells experimente","was jorell macht"}},{q="Warum untersuchen Quae und Kinelory dies?",a="Sie sind Gefährten von Phin, der eine Gruppe von Abenteurern anführt, die merkwürdigen Ereignissen nachgehen. Phin würde es nicht gefallen, wenn Jorells Experimente fortgesetzt werden dürften.",al={"wer phin ist","warum ihnen die seuche wichtig ist","warum phin helfen"}},{q="Wohin wird die Forschung geschickt?",a="Ein Teil davon wurde bereits nach Tarrens Mühle geschickt. Kinelory plant zu stehlen, was Jorell noch nicht verschickt hat.",al={"wohin die aufzeichnungen gehen","tarrens mühle forschung"}}},fp="22,308,20.257.0,20.246.0,18.326.1,34.84.0,34.78.0,45.162.0,33.102.0"}
P.entries["quest:6571"] = {n="Nachschub des Kriegshymnenklans",s="„Nachschub des Kriegshymnenklans“ ist eine umfangreiche Logistikquest der Horde, die Locke Okarr am Splitterholzposten vergibt. Um das Holzfällerlager des Kriegshymnenklans betriebsfähig zu halten, müssen wichtige Holzfällergeräte zurückgeholt werden, die in feindseligen Gebieten der Furbolgs und Satyrn verstreut sind. Hinzu kommen Lieferungen aus weit entfernten Goblinhäfen.",h="„Nachschub des Kriegshymnenklans“ ist eine umfangreiche Logistikquest der Horde, die Locke Okarr am...",kw={"eschental","beutebucht","locke okarr","holzfällerseil","pixel","sägeblätter","splitterholzposten","holzfällerlager des kriegshymnenklans","öl des kriegshymnenklans","nachschub des kriegshymnenklans"},ang={["faction:Horde"]="Die Expansion der Horde in Durotar hängt vollständig von dem Holz ab, das der Kriegshymnenklan beschafft. Diese Werkzeuge zurückzuholen stärkt unmittelbar das Fundament Orgrimmars.",["profession:Engineering"]="Die Goblinkomponenten dieser Lieferung verdeutlichen die unverzichtbare mechanische Versorgungskette – von Pixels Sägeblättern bis hin zu Schmiermitteln für Dampfmaschinen –, die zum Fällen uralter Wälder benötigt wird.",["race:Orc"]="Das Erbe des Kriegshymnenklans im Eschental zu ehren bedeutet, seine Äxte scharf und seine Lager versorgt zu halten – trotz der ständigen Angriffe der Waldbewohner."},sec={{t="Die Sägen am Laufen halten",b="Der Feldzug des Kriegshymnenklans, das uralte Holz des Eschentals zu schlagen, erfordert einen ununterbrochenen Nachschub an schweren Werkzeugen. Von ihrem Außenposten am Splitterholzposten aus sehen sich die Quartiermeister der Horde ständigen Versorgungsengpässen gegenüber. Locke Okarr ist dafür verantwortlich, das Holzfällerlager vollständig auszustatten, doch örtliche Lieferungen sind durch Überfälle einheimischer Wildtiere und dämonischer Kultisten zerschlagen worden, sodass dem Betrieb wichtige Ausrüstung fehlt."},{t="Eine verstreute Logistikkette",b="Die benötigte Ausrüstung zu beschaffen ist eine beschwerliche Aufgabe, die sich über weite Teile Kalimdors erstreckt und sogar über das Meer hinausführt. Während kreisrunde Sägeblätter direkt am Splitterholzposten beim Goblinkurier Pixel abgeholt werden können, muss die Kiste mit schweren Äxten bei einer Lieferung von Werftmeister Lozgil unten in der Beutebucht abgeholt werden. Die übrigen unverzichtbaren Güter müssen den Feinden direkt entrissen werden: robuste Holzfällerseile, die feindselige Foulweald- und Thistlefur-Furbolgs an sich gebracht haben, sowie Fässer mit Maschinenöl des Kriegshymnenklans, das die Satyrn von Nachtflucht, Satyrnaar und Xavian für ihre ruchlosen Rituale gestohlen haben."}},faq={{q="Welche Nachschubgüter des Kriegshymnenklans werden benötigt?",a="Locke Okarr benötigt vier unverzichtbare Gegenstände: eine Lieferung Sägeblätter des Kriegshymnenklans, die der Goblin Pixel verwahrt, eine Kiste Äxte des Kriegshymnenklans, die nach Beutebucht verschifft wurde, schwere Holzfällerseile, die örtliche Furbolgs erbeutet haben, und Fässer mit Öl des Kriegshymnenklans, das Satyrn aus dem Eschental gestohlen haben.",al={"nachschub des kriegshymnenklans liste","welche gegenstände benötigt","benötigter nachschub"}},{q="Wer ist Locke Okarr?",a="Locke Okarr ist ein Orc am Splitterholzposten, der für die Koordination der Materiallieferungen an das Holzfällerlager des Kriegshymnenklans verantwortlich ist. Da er unter großem Druck steht, Betriebsverzögerungen zu vermeiden, bittet er umherziehende Abenteurer der Horde, seine verstreuten Lieferungen zurückzuholen.",al={"locke okarr lore","wer vergibt nachschub des kriegshymnenklans","splintertreeposten questgeber"}},{q="Warum verschifft die Horde Ausrüstung aus der Beutebucht?",a="Die Horde verlässt sich auf neutrale Handelsnetze wie das Steamwheedle Cartel, um speziell gefertigte Waren einzuführen, die sich in Durotar und im Brachland nicht ohne Weiteres in großen Mengen schmieden lassen. Schwere Holzfälleräxte, die über Goblinkanäle bestellt werden, gelangen über maritime Handelszentren wie die Beutebucht ins Eschental.",al={"warum beutebucht","äxtelieferung beutebucht","steamwheedle werkzeuge"}},{q="Warum wollen die Satyrn Öl des Kriegshymnenklans?",a="Anstatt es für Maschinen zu verwenden, leiten die Satyrn in Ruinen wie Satyrnaar, Nachtflucht und Xavian das gestohlene Industrieöl in dunkle, verderbte Riten um, die der Brennenden Legion und der Ausbreitung der Verderbnis des Teufelswalds gewidmet sind.",al={"satyr öl lore","warum haben satyrn öl","rituale mit kriegshymnenöl"}},{q="Welche Furbolgs haben das Holzfällerseil gestohlen?",a="Das Holzfällerseil wurde bei einem Hinterhalt von den Furbolgstämmen Foulweald und Thistlefur erbeutet. Beide Stämme sind der Horde gegenüber erbittert territorial eingestellt, weil diese im ganzen Eschental Kahlschlag betreibt.",al={"wer stahl das seil","furbolg seil lore","foulweald thistlefur seil"}},{q="Warum ist das Holzfällerlager des Kriegshymnenklans für die Horde so wichtig?",a="Die trockenen Lande Durotars bieten praktisch kein brauchbares Bauholz. Der Kriegshymnenklan wurde gezielt in die üppigen Grenzlande des Eschentals entsandt, um die riesigen Bäume zu schlagen, die für den Bau Orgrimmars und die wachsende militärische Infrastruktur der Horde benötigt werden.",al={"warum eschental abholzen","warsong holzfäller bedeutung","orcs fällen bäume"}}},fx={b7ffa730={q="Warum muss Locke Okarr diese Vorräte sammeln lassen?",a="Locke Okarr ist für die Versorgung des Holzfällerlagers des Kriegshymnenklans verantwortlich, wo es zu einem gefährlichen Mangel an wichtigen Werkzeugen gekommen ist. Lieferungen wurden im Eschental und darüber hinaus verzögert, gestohlen oder abgefangen. Sollte er diese essenziellen Holzfällermaterialien nicht umgehend liefern, droht ihm ernster Ärger von seinen Vorgesetzten im Kriegshymnenklan.",al={"warum vorräte für locke okarr","warum vorräte für locke okarr sammeln","beweggrund von locke okarr"}},["54c7a3c1"]={q="Wofür werden die Sägeblätter des Kriegshymnenklans verwendet?",a="Die Sägeblätter sind entscheidende industrielle Komponenten für die mechanisierten Schredder und Mühlen, die im Holzfällerlager des Kriegshymnenklans betrieben werden. Ohne frische Sägeblätter können die schweren Holzfällermaschinen der Horde die massiven, uralten Bäume des Eschentals nicht effizient fällen, um Bauholz für den Bau von Orgrimmar und örtlichen Lagern zu liefern.",al={"wofür sind die sägeblätter","verwendung der sägeblätter des kriegshymnenklans","sägeblätter holzfällerlager"}},["9c63ad01"]={q="Wofür wird die Axtlieferung des Kriegshymnenklans verwendet?",a="Importiert aus den Goblinschmieden in Beutebucht, versorgt diese Kiste mit strapazierfähigen Äxten die Vorhut des Kriegshymnenklans und die Arbeiter, die dichtes Gestrüpp roden und das dichte Holz des Eschentals von Hand fällen. In einem feindseligen Wald, der von Nachtelfen und Bestien wimmelt, dienen diese robusten Werkzeuge gleichzeitig als verlässliche Kriegswaffen.",al={"wofür ist die axtlieferung","verwendung der axtlieferung des kriegshymnenklans","axtlieferung beutebucht"}},["74cafbab"]={q="Wofür wird das Öl des Kriegshymnenklans verwendet?",a="Das Öl des Kriegshymnenklans ist ein schweres Schmiermittel, das benötigt wird, damit die Dampfmaschinen, Schredder und komplexen Holzfällanlagen des Lagers unter harten Bedingungen reibungslos funktionieren. Ohne es blockieren die schweren Eisenwerke und bringen den Holzbetrieb vollständig zum Erliegen.",al={"wofür ist das öl des kriegshymnenklans","zweck des öls des kriegshymnenklans","warum öl für das holzfällerlager"}},["76a0db14"]={q="Wofür wird das Holzfällerseil verwendet?",a="Dieses haltbare Hochleistungsseil wird von den Mannschaften des Holzfällerlagers verwendet, um massive Baumstämme nach dem Fällen zu ziehen, zu sichern und hochzuheben. Die riesigen Bäume des Eschentals ohne angemessene Ausrüstung zu bewältigen, ist nahezu unmöglich und birgt das Risiko, Arbeiter zu zerquetschen oder wertvolle Ausrüstung zu beschädigen.",al={"wofür ist das holzfällerseil","zweck des holzfällerseils","seil kriegshymnenlager"}},["4e02126d"]={q="Warum bittet Locke Okarr einen Abenteurer anstelle der Wachen des Außenpostens?",a="Die Garnison des Splitterholzpostens ist dünn besetzt, da sie sich gegen ständige Einfälle der Schildwachen der Silberschwingen und feindseliger Waldbewohner verteidigen muss. Locke kann keine unverzichtbaren Wachen von der Peripherie abziehen, noch kann er seinen Posten persönlich verlassen, um entlegene Winkel des Eschentals zu durchsuchen und bis nach Beutebucht zu reisen.",al={"warum ich locke okarr","warum können wachen keine vorräte beschaffen","warum nicht die wachen schicken"}}},fp="16,290,25.415.0,27.573.0,39.246.0,19.252.0,51.303.0,35.229.0,38.197.0,53.269.0"}
P.entries["quest:658"] = {n="Hinweise auf eine neue Seuche?",s="Quae und Kin beobachten Go'Sheks Hof schon seit Tagen. Kin sah einen Kurier aus einem kleinen Haus im Süden kommen, und sie vermuten, dass der Kurier Notizen bei sich trägt, die für Tarrens Mühle bestimmt sind. Quae möchte diese Dokumente haben und fragt, ob Ihr ein geschickter Fährtenleser seid.",h="Quae und Kin beobachten Go'Sheks Hof schon seit Tagen.",kw={"apotheker","arathihochland","forsaken courier","go'sheks hof","kin","phin odelic","quae","versiegelter ordner","tarrens mühle"},sec={{t="Den Hof beobachten",b="Quae ist nicht überrascht, dass Phin Odelic Euch geschickt hat, um nach ihnen zu sehen, da Phin sich zu viele Sorgen macht. Quae und Kin beobachten den Hof schon seit Tagen. Vor Kurzem sah Kin einen Kurier aus einem kleinen Haus im Süden kommen. Kin redet viel, aber Quae kann Kins Sinnen in gefährlichen Gebieten stets vertrauen."},{t="Der Ordner des Kuriers",b="Quae fragt, ob Ihr ein geschickter Fährtenleser seid. Der Kurier trägt möglicherweise Notizen bei sich, die für Tarrens Mühle bestimmt sind, und der Erhalt dieser Dokumente könnte etwas Licht darauf werfen, was in Hillsbrad geschieht. Ihr sollt den Forsaken Courier finden und ihren Versiegelten Ordner zu Quae nahe Go'Sheks Hof zurückbringen. Während Ihr sucht, bemerkt Kin einen Apotheker, der dasselbe Haus verlässt. Quae ist zuversichtlich, dass der Apotheker nichts Gutes im Schilde führt, benötigt jedoch Beweise, bevor jemand etwas Unüberlegtes tut."}},faq={{q="Wer hat Euch geschickt, um Quae und Kin zu finden?",a="Phin Odelic hat Euch geschickt, um nach ihnen zu sehen, obwohl Quae nicht überrascht ist, da Phin sich zu viele Sorgen macht.",al={"wer hat mich zu quae geschickt","wer hat hints of a new plague gestartet","phin odelic quest"}},{q="Woher kam der Kurier?",a="Kin sah den Kurier aus einem kleinen Haus im Süden kommen.",al={"woher kommt der kurier","aufenthaltsort des kuriers","haus südlich des hofs"}},{q="Wohin ist der Kurier unterwegs?",a="Quae und Kin vermuten, dass der Kurier Notizen bei sich trägt, die für Tarrens Mühle bestimmt sind.",al={"ziel des kuriers","wohin geht der kurier"}},{q="Welchen Gegenstand sollt Ihr beschaffen?",a="Den Versiegelten Ordner des Forsaken Courier, der zu Quae nahe Go'Sheks Hof zurückgebracht werden soll.",al={"welchen gegenstand hat der kurier","versiegelter ordner"}},{q="Wer wurde noch an dem Haus gesichtet?",a="Kin bemerkte einen Apotheker, der dasselbe Haus im Süden verließ, während Ihr fort wart.",al={"apotheker auf dem hof","wer kam aus dem haus"}},{q="Warum möchte Quae die Dokumente haben?",a="Sie könnten etwas Licht darauf werfen, was in Hillsbrad geschieht, und Quae benötigt Beweise, bevor jemand etwas Unüberlegtes tut.",al={"warum die dokumente beschaffen","wofür sind die notizen"}}},fp="22,249,17.292.0,20.454.0,34.96.0,32.59.0,29.69.0,35.83.0,34.83.0,33.117.0"}
P.entries["quest:6581"] = {n="Sägeblätter des Kriegshymnenklans",s="Sägeblätter des Kriegshymnenklans ist eine Besorgung der Horde, die am Splitterholzposten im Auftrag der Holzfällerkampagne des Kriegshymnenklans unternommen wird. Um schwere, aus Ratschet importierte Sägeblätter zu erhalten, müssen Abenteurer einen heimlichen Handel mit der Kurierin Pixel eingehen, die vor der Übergabe der Lieferung persönlichen Schutz verlangt. Die Erfüllung ihres Tauschs sichert lebenswichtige Maschinen, um die Sägewerke der Horde in Eschental am Laufen zu halten.",h="Sägeblätter des Kriegshymnenklans ist eine Besorgung der Horde, die am Splitterholzposten im Auftrag der...",kw={"eschental","tödliche donnerbüchse","pixel","ratschet","splitterholzposten","vorhut des kriegshymnenklans","sägeblätter des kriegshymnenklans","warsongnachschub"},ang={["faction:Horde"]="Die Holzfällerlager in Eschental bilden das lebenswichtige bauliche Rückgrat für die Expansionen von Orgrimmar, wodurch jede Maschinenlieferung für das Überleben der Horde auf Kalimdor von essenzieller Bedeutung ist.",["profession:Engineering"]="Die von Pixel verlangte Tödliche Donnerbüchse ist ein Paradebeispiel für die Arbeit versierter Tüftler und verdeutlicht, wie goblinische und sterbliche Ingenieurskunst die Logistik an der Front antreibt.",["race:Orc"]="Der Kriegshymnenklan setzte unter Grommash Hellscream seinen ganzen Stolz in die Abholzung Eschentals; ihre industriellen Sägeblätter am Laufen zu halten, ehrt die fortwährende Vormachtstellung des Klans im Wald."},sec={{t="Das schlaue Tauschgeschäft einer Kurierin",b="Die Holzfäller des Kriegshymnenklans in Eschental sind vollständig auf importierte schwere Maschinen angewiesen, um das uralte Holz des tiefen Waldes zu fällen. Obwohl Pixel eine Lieferung spezialisierter Sägeblätter direkt aus der Goblinhafenstadt Ratschet zum Splitterholzposten gebracht hat, hat sie keineswegs die Absicht, diese einfach kostenlos auszuhändigen. Draußen in der gefährlichen Wildnis von Eschental sind Münzen nur begrenzt von Wert; persönliche Sicherheit zählt weitaus mehr. Anstatt Gold zu verlangen, besteht Pixel darauf, die schweren Sägeblätter gegen eine zuverlässige Tödliche Donnerbüchse einzutauschen, um sich bei ihren gefährlichen Reisen durch feindliches Gebiet zu schützen."},{t="Versorgung der Kriegsanstrengungen",b="Das dichte Blätterdach von Eschental wird von der Horde hoch geschätzt, die in den kargen Ebenen von Durotar und dem Brachland unter schwerem Holzmangel leidet. Das Abholzen uralter Haine der Schildwachen stumpft gewöhnliche Äxte jedoch rasch ab, weshalb goblingeschmiedete Industriesägeblätter unerlässlich sind. Die Sicherung von Pixels Lieferung treibt die Operationen der Holzfällerlager des Kriegshymnenklans direkt an und stellt sicher, dass die Horde trotz erbitterten Widerstands der Nachtelfen weiterhin Außenposten und Kriegsmaschinen errichten kann."}},faq={{q="Wer ist Pixel und warum hat sie die Sägeblätter?",a="Pixel ist eine derzeit am Splitterholzposten stationierte Kurierin, die eine Lieferung industrieller Sägeblätter direkt aus der Goblinhafenstadt Ratschet transportiert hat. Sie hält die Lieferung zurück, bis sie sich eine verlässliche Waffe zum eigenen Schutz sichern kann.",al={"wer ist pixel","pixel splintertree","sägeblatt kurier"}},{q="Warum möchte Pixel eine Tödliche Donnerbüchse statt Gold?",a="Reisen durch das Brachland und tief in das Gebiet der Nachtelfen in Eschental sind extrem gefährlich. Da Pixel die Gefahren der Straße kennt, zieht sie persönliche Verteidigung barem Geld vor und fordert eine von einem Ingenieur gefertigte Schusswaffe, um ihre Reisen abzusichern.",al={"warum tödliche donnerbüchse","pixel waffentausch","warum eine schusswaffe gewollt"}},{q="Warum sind diese Sägeblätter für die Horde so wichtig?",a="Die Horde benötigt gewaltige Mengen an Holz, um überall auf Kalimdor Befestigungen und Kriegsmaschinen zu errichten. Standard-Fällwerkzeuge nutzen sich an den uralten Eisenholzbäumen Eschentals rasch ab, was importierte mechanische Sägeblätter für die Holzfällermaschinen des Kriegshymnenklans unverzichtbar macht.",al={"warum sägeblätter benötigt werden","bedeutung warsong holz","warum warsongnachschub"}},{q="Woher stammten die Sägeblätter ursprünglich?",a="Die Sägeblätter wurden in Ratschet, der neutralen Goblinhafenstadt an der Ostküste des Brachlands, hergestellt und verschifft, bevor sie über Land zum Splitterholzposten transportiert wurden.",al={"ursprung der sägeblätter","ratschet sägeblätter","woher sägeblätter stammten"}},{q="Wie fügt sich diese Quest in die Holzfällerkampagne des Kriegshymnenklans ein?",a="Diese Aufgabe ist Teil der größeren Bemühung, Nachschub des Kriegshymnenklans für die Holzfällerlager in Eschental zusammenzustellen. Das Beschaffen der Sägeblätter von Pixel erfüllt eine der wichtigsten logistischen Voraussetzungen, um die Holzfällerarbeiten der Horde aufrechtzuerhalten.",al={"warsong versorgungskette","warsongsägeblätter voraussetzung"}},{q="Kann jeder die Waffe herstellen, die Pixel verlangt?",a="Eine Tödliche Donnerbüchse wird von geschickten Ingenieuren aus Kupferrohren, Kupferbolzen, einem hölzernen Schaft und Leder gefertigt, auch wenn Kuriere und Krieger sie oft auf lokalen Märkten oder von anderen Abenteurern eintauschen.",al={"tödliche donnerbüchse erhalten","donnerbüchse herkunft","ingenieurskunst waffe"}}},fx={["496db877"]={q="Wofür ist die Tödliche Donnerbüchse?",a="Pixel benötigt persönlichen Schutz in der Wildnis. Als Kurier, der Fracht durch ungezähmte Gebiete wie das Eschental und das Brachland transportiert, ist es gefährlich, allein zu reisen. Anstelle von Gold, das Bestien oder Nachtelfen nicht abwehren kann, verlangt sie eine verlässliche technische Schusswaffe, damit sie unterwegs auf sich selbst aufpassen kann.",al={"warum donnerbüchse","tödliche donnerbüchse pixel","wofür benutzt pixel die donnerbüchse"}}},fp="18,421,25.614.0,24.461.0,50.244.0,57.244.0,51.275.0,46.173.0,58.237.0,39.210.0"}
P.entries["quest:659"] = {n="Hinweise auf eine neue Seuche?",s="Phin Odelic führt eine Gruppe von Abenteurern an, die seltsame Vorfälle in der Gegend untersuchen, und glaubt, dass die Untoten verwickelt sind. Zwei Gefährten, Quae und Kinelory, brachen zu Go'Sheks Hof im Arathihochland auf. Seit Tagen gibt es keine Nachricht von ihnen.",h="Phin Odelic führt eine Gruppe von Abenteurern an, die seltsame Vorfälle in der Gegend untersuchen, und...",kw={"arathihochland","go'sheks hof","vorgebirge des hügellands","kinelory","phin odelic","quae","stanley"},sec={{t="Seltsame Vorfälle",b="Vor nicht allzu langer Zeit musste ein Cousin von Phin in Hillsbrad seinen Hund Stanley einschläfern. Die Bestie war auf mystische Weise zu einer riesigen Größe angeschwollen und ging wild auf jeden los, der sich ihr näherte. Phin glaubt, dass die Untoten in die seltsamen Vorfälle verwickelt sind, und die Gruppe sucht nach Hinweisen, um dies zu beweisen."},{t="Die vermissten Gefährten",b="Quae und Kinelory, zwei von Phins Gefährten, brachen ins Arathihochland zu Go'Sheks Hof auf und haben sich seit Tagen nicht gemeldet. Phin macht sich Sorgen und möchte, dass Ihr sie in der Nähe des Hofes findet."}},faq={{q="Wer ist Phin Odelic?",a="Phin führt eine Gruppe von Abenteurern an, die seltsame Vorfälle in der Gegend untersuchen.",al={"phin odelic","wer vergibt hints of a new plague","questgeber"}},{q="Was ist mit Stanley geschehen?",a="Stanley war der Hund von Phins Cousin in Hillsbrad. Die Bestie schwoll auf mystische Weise zu einer riesigen Größe an und ging wild auf jeden los, der sich ihr näherte, sodass der Cousin sie einschläferte.",al={"hund stanley","was geschah mit dem hund","stanley hillsbrad"}},{q="Wo sollten Quae und Kinelory eigentlich sein?",a="In der Nähe von Go'Sheks Hof im Arathihochland, wohin sie aufgebrochen waren. Phin hat seit Tagen nichts von ihnen gehört.",al={"wo ist quae","wo ist kinelory","quae aufenthaltsort","quae finden"}},{q="Warum stellt Phin Nachforschungen an?",a="Phin glaubt, dass die Untoten in die seltsamen Vorfälle in der Gegend verwickelt sind, und die Gruppe sucht nach Hinweisen, um dies zu beweisen.",al={"warum go'sheks hof","go'sheks hof untote","go'shek untersuchen"}}},fp="22,240,14.281.0,22.192.0,19.81.0,25.166.0,43.105.0,26.120.0"}
P.entries["quest:66"] = {n="Die Legende von Stalvan",s="Die Legende von Stalvan beginnt in Dunkelhain mit einer unheilvollen Vision der Seherin des Ortes, Madame Eva. Beunruhigt von einem Omen, das ihrer Enkelin Alyssa den Tod verheißt, nutzt Eva ihre Karten und Trancevisionen, um einen einzigen verbleibenden Namen zu ergründen: Stalvan. Um diesen Faden des Schreckens zu entwirren, schickt sie Reisende los, um die städtischen Aufzeichnungen im Rathaus von Dunkelhain einzusehen.",h="Die Legende von Stalvan beginnt in Dunkelhain mit einer unheilvollen Vision der Seherin des Ortes, Madame Eva.",kw={"alyssa","amtmann daltry","dunkelhain","todeskarte","dämmerwald","madame eva","stalvan","rathaus"},ang={["class:Priest"]="Priester, die die dunklen Pfade von Dunkelhain beschreiten, beherzigen oft spirituelle Warnungen, wodurch Madame Evas erschütternde Todesomen zu einer dringenden Angelegenheit ihrer Seelsorge werden.",["faction:Alliance"]="Da der Dämmerwald ohne reguläre militärische Unterstützung aus Sturmwind kämpft, springen Abenteurer der Allianz häufig ein, um den Ältesten des Ortes beizustehen und schutzlose Familien wie die von Madame Eva zu beschützen."},sec={{t="Eine Vision des Todes",b="In der ewigen Düsternis des Dämmerwalds dient Madame Eva als ansässige Seherin von Dunkelhain, die Vorzeichen deutet und beunruhigten Einheimischen die Karten legt. Nachdem sie von einer schrecklichen Erschütterung aus dem Schlaf gerissen worden war, befragte Eva ihr Wahrsagedeck – nur um die Todeskarte in Verbindung mit ihrer jungen Enkelin Alyssa zu ziehen. Als sie in eine tiefe, schattenhafte Trance fiel, um das Dunkel zu durchdringen, brachte sie nur einen einzigen Hinweis hervor: den Namen Stalvan. Aus Angst davor, was dieses Omen für ihre Familie und die Stadt bedeutet, wendet sie sich an fähige Abenteurer, um dem Faden nachzugehen, bevor eine Tragödie geschieht."},{t="Nachforschungen im Rathaus",b="Eva weiß, dass die Aufdeckung der Wahrheit über Stalvan einen Blick in die geschriebene Geschichte von Dunkelhain erfordert. Sie schickt Abenteurer über den Platz zum Rathaus von Dunkelhain, um mit Amtmann Daltry zu sprechen, dem städtischen Hüter der Register und öffentlichen Archive. Daltry beaufsichtigt die verstaubten Dokumente der Gemeinde, was ihn zur einzigen Person macht, die feststellen kann, ob Stalvan ein ehemaliger Bewohner, ein durchreisender Wanderer oder etwas weitaus Unheimlicheres war, das in der Vergangenheit des Dämmerwalds begraben liegt."}},faq={{q="Wer ist Madame Eva?",a="Madame Eva ist eine Wahrsagerin und Seherin, die in Dunkelhain lebt. Sie nutzt Karten und Trancerituale, um Blicke auf Vorzeichen der Zukunft zu erhaschen, und spürt magische Erschütterungen, die den Dämmerwald durchziehen.",al={"madame eva","wer ist eva","wahrsagerin dunkelhain"}},{q="Warum benötigt Madame Eva Hilfe?",a="Madame Eva hatte eine schreckliche Vision, die darauf hinweist, dass ihre Enkelin Alyssa in Lebensgefahr schwebt. Ihre Karten zogen die Todeskarte, und ihre Trance brachte lediglich den Namen „Stalvan“ hervor, was sie dazu veranlasst, Hilfe von außerhalb zu suchen, um die Bedrohung zu untersuchen.",al={"warum stalvan beginnen","eva vision","warum eva helfen"}},{q="Wer ist Amtmann Daltry?",a="Amtmann Daltry ist der städtische Archivar, der im Rathaus von Dunkelhain stationiert ist. Er verwaltet die Register, Verzeichnisse und historischen Dokumente der Stadt und ist damit der beste Ansprechpartner, um sich nach unbekannten Namen zu erkundigen.",al={"amtmann daltry","daltry","wer ist amtmann"}},{q="Was ist das Rathaus von Dunkelhain?",a="Das Rathaus von Dunkelhain ist das Verwaltungszentrum des Ortes und beherbergt die örtlichen Regierungsbeamten, historische Aufzeichnungen sowie die Führungsriege der Nachtwache.",al={"rathaus von dunkelhain","rathaus dämmerwald"}},{q="Wer ist Alyssa?",a="Alyssa ist Madame Evas junge Enkelin, die in Dunkelhain lebt. Evas Weissagung enthüllte, dass Alyssa das Ziel eines tödlichen Omens ist, das mit jemandem namens Stalvan in Verbindung steht.",al={"alyssa","madame eva enkelin"}},{q="Wohin führt diese Nachforschung als Nächstes?",a="Das Gespräch mit Amtmann Daltry enthüllt städtische Aufzeichnungen und frühere Nachforschungen und leitet eine umfassende Untersuchung im gesamten Dämmerwald und den benachbarten Regionen ein, um Stalvans Geschichte und Schicksal aufzudecken.",al={"stalvan nächster schritt","was sagt daltry"}}},fx={aeb2106e={q="Wer ist Stalvan?",a="Zum jetzigen Zeitpunkt ist Stalvan kaum mehr als ein schattenhafter Name, der durch Madame Evas Weissagung flüstert. Beunruhigt durch eine Vorahnung tödlicher Gefahr für ihre Enkelin Alyssa, legte Eva ihre Karten und begab sich in eine tiefe Trance, um Antworten zu finden. Der Tod wurde offenbart, zusammen mit nur diesem einen Namen. Ihr werdet ausgesandt, um in den alten Aufzeichnungen von Dunkelhain aufzudecken, wer Stalvan war.",al={"wer ist stalvan","wer stalvan","was ist stalvan"}},["9e863436"]={q="Warum bittet Madame Eva Euch anstelle der The Night Watch?",a="Madame Eva verlässt sich auf Omen und Weissagungen anstelle konventioneller Verbrechen, was es schwierig macht, einen obskuren Namen aus einer Kartenlegung formell vor die The Night Watch zu bringen. Da Dunkelhain bereits von Wölfen, Spinnen und den Untoten belagert wird, ist die örtliche Garnison bis an ihre Grenzen damit beschäftigt, die Stadtgrenze zu verteidigen. Sie benötigt einen unabhängigen Abenteurer, der bereit ist, in ihrem Auftrag diskret in alten städtischen Aufzeichnungen zu graben.",al={"warum bittest du mich","warum nicht die stadtwache","warum nicht die the night watch"}}},fp="21,363,17.562.0,22.470.0,18.192.0,30.244.0,20.208.0,28.162.0,14.163.0,40.181.0"}
P.entries["quest:660"] = {n="Hinweise auf eine neue Seuche?",s="Kinelory ist bereit, hinunter zum Bauernhof zu gehen, und möchte Euch an ihrer Seite haben. Sie fürchtet, dass die Untoten hinten in Hillsbrad Unheil anrichten könnten, je länger sie warten, und Ihr werdet gebeten, sie sicher zurück zu Quae zu geleiten.",h="Kinelory ist bereit, hinunter zum Bauernhof zu gehen, und möchte Euch an ihrer Seite haben.",kw={"eskorte","vorgebirge des hügellands","hints of a new plague","kinelory","seuche","quae"},sec={{t="Kinelory den Rücken freihalten",b="Nach den früheren Schritten der Untersuchung ist Kinelory bereit zu handeln. Sie bittet Euch, mit ihr hinunter zum Bauernhof zu kommen. Ihr sollt sie sicher zurück zu Quae bringen, und jeder, dem das Volk von Hillsbrad am Herzen liegt, wird dazu angehalten, sie zu beschützen."},{t="Eine sichere Rückkehr",b="Zurück bei Quae dankt man Euch für Eure Dienste. Quae gibt zu, gehofft zu haben, dass Kinelory nicht zu anstrengend war: Sie ist sehr freundlich, aber ebenso tödlich, wenn man ihr Feind ist."}},faq={{q="Wer schickt Euch auf diese Eskorte?",a="Kinelory bittet Euch, mit ihr zu kommen, sobald sie bereit ist aufzubrechen.",al={"questgeber","wer gibt die quest","wer startet hints of a new plague 4"}},{q="Wohin muss Kinelory gehen?",a="Sie geht hinunter zu einem Bauernhof und macht sich dann auf den Rückweg zu Quae.",al={"eskortierungsroute","wohin geht kinelory","kinelory zielort"}},{q="Bei wem meldet Ihr Euch nach Abschluss?",a="Quae, sobald Kinelory zu ihr zurückgekehrt ist.",al={"abgabe","wer schließt die quest ab","wo abgeben"}},{q="Was geschah unmittelbar vor diesem Teil der Untersuchung?",a="Der dritte Teil von Hints of a New Plague?, der direkt zu diesem hier führt.",al={"vorherige quest","voraussetzung","was kommt davor"}},{q="Was folgt nach der sicheren Rückkehr?",a="Die Untersuchung wird mit dem fünften Teil von Hints of a New Plague? fortgesetzt.",al={"folgequest","what comes next","fortsetzung"}},{q="Warum muss Kinelory beschützt werden?",a="Jeder, dem das Volk von Hillsbrad am Herzen liegt, wird dazu angehalten, sie sicher hindurchzubringen.",al={"warum kinelory beschützen","warum sich um kinelory sorgen"}}},fp="22,198,24.235.0,13.175.1,29.64.0,31.57.0,35.44.0,54.77.0,36.72.0,31.82.0"}
P.entries["quest:6608"] = {n="Ihr zu gut",s="„Ihr zu gut“ ist eine Horde-Quest, die vom Angellehrer in Orgrimmar, Lumak, angeboten wird, sobald ein Angler die gewöhnliche Ausbildung hinter sich gelassen hat. Lumak schickt seinen fähigen Schüler los, um seinen menschlichen Freund Nat Pagle aufzuspüren, der an den abgelegenen Ufern der Düstermarschen sein Lager aufgeschlagen hat. Sie markiert den Übergang von gewöhnlicher Unterweisung zur anspruchsvollen Kunst des Angel-Fachmanns.",h="„Ihr zu gut“ ist eine Horde-Quest, die vom Angellehrer in Orgrimmar, Lumak, angeboten wird, sobald ein Angler...",kw={"fachmann angeln","düstermarschen","lumak","nat pagle","orgrimmar","theramore","ihr zu gut"},ang={["faction:Horde"]="Diese Quest verdeutlicht, dass Individuen abseits des Fraktionskriegs gelegentlich fraktionsübergreifende Bande über ein harmloses Handwerk und gemeinsame Hobbys knüpfen.",["race:Orc"]="Selbst innerhalb der kriegerischen Festung Orgrimmar beweist Lumak, dass Geduld, Humor und tiefer Respekt vor der Natur einen Ork dazu bringen können, Freundschaften über feindliche Linien hinweg zu schließen."},sec={{t="Lumaks Grenzen",b="Lumak dient als Orgrimmars primärer Angellehrer unten im Tal der Ehre, doch selbst der geduldige Ork erkennt, wann ein Schüler sein eigenes Verständnis von Rute und Rolle erreicht hat. Anstatt vorzugeben, noch weitere Weisheiten vermitteln zu können, gesteht Lumak offen ein, dass der Angler für den gewöhnlichen Unterricht „zu gut“ geworden ist. Um den Rang eines Fachmanns zu erreichen, muss man über Stadtmauern und Völkergrenzen hinausblicken."},{t="Eine ungewöhnliche Freundschaft",b="Trotz der schwelenden Spannungen zwischen der Horde und der Allianz quer durch Kalimdor überbrückt das Angeln oft Gräben, an denen die Diplomatie scheitert. Lumak weist Reisende an seinen persönlichen Bekannten Nat Pagle weiter und betont nachdrücklich, dass dem Menschen kein Leid zugefügt und er nicht gegessen werden darf. Nat schlägt sein Lager auf einer kleinen Insel südlich der Insel Theramore in den Düstermarschen auf – zufrieden damit, die Politik zu ignorieren, solange die Fische anbeißen."}},faq={{q="Wer schickt mich auf diese Quest?",a="Lumak, der Angellehrer am Wasser im Tal der Ehre in Orgrimmar, gibt Euch diese Quest, sobald Eure Angelfertigkeit hoch genug ist, um über den Expertenstatus hinauszugehen.",al={"wer startet ihr zu gut","lumak questgeber","wo bekommt man ihr zu gut"}},{q="Wo befindet sich Nat Pagle?",a="Nat Pagle befindet sich auf einer kleinen Insel vor der Küste der Düstermarschen, südlich der menschlichen Siedlung Die Insel Theramore.",al={"wo ist nat pagle","nat pagle standort","nat pagle finden"}},{q="Warum hat ein Ork einen menschlichen Freund?",a="Angler in ganz Azeroth teilen oft einen gegenseitigen Respekt, der über den Fraktionskrieg hinausgeht. Lumak und Nat Pagle fanden ihre Verbindung rein über das Angeln und schätzen die Leidenschaft des jeweils anderen, ungeachtet der erbitterten Rivalität zwischen Orks und Menschen.",al={"lumak und nat pagle freundschaft","warum ist nat pagle mit einem ork befreundet"}},{q="Was geschieht, wenn ich mit Nat Pagle spreche?",a="Wenn Ihr mit Nat Pagle sprecht, weiht er Euch in seine anspruchsvolle Fachmann-Prüfung ein, für die Ihr durch ganz Azeroth reisen und seltene Fische fangen müsst, bevor er Euch persönlich weiter unterrichtet.",al={"was lehrt nat pagle","fachmann angeln quest"}},{q="Ist Theramore für Angehörige der Horde sicher zu durchqueren?",a="Nein, Theramore ist eine streng von der Allianz bewachte Festungsstadt. Abenteurer der Horde müssen einen Bogen um die Stadt machen oder an der Küste entlangreisen, um Nats Insel zu erreichen, ohne den Zorn der Wachen von Theramore auf sich zu ziehen.",al={"kann horde durch theramore reisen","zu nat pagle gelangen als horde"}},{q="Warum kann Lumak mich nicht selbst weiter ausbilden?",a="Lumak hat Euch alles beigebracht, was er weiß. Die wahre Meisterschaft des Fachmann-Angelns erfordert die Einsichten von Nat Pagle, der weithin als legendärster Angler der bekannten Welt gilt.",al={"warum bildet lumak nicht mehr aus","angeln experte zu fachmann horde"}}},fp="13,350,14.413.0,22.406.0,27.165.0,27.118.0,36.227.0,39.176.0,44.197.0,41.164.0"}
P.entries["quest:661"] = {n="Hinweise auf eine neue Seuche?",s="Kinelory ist unversehrt vom Hof zurück, und Quae hat die Gegenstände, die sie mitgebracht hat. Quae und Kinelory beabsichtigen, noch eine Weile in Arathi zu bleiben, daher liegt es an Euch, Phin Odelic in Süderstade Nachricht zu bringen.",h="Kinelory ist unversehrt vom Hof zurück, und Quae hat die Gegenstände, die sie mitgebracht hat.",kw={"arathihochland","verlassene","hillsbrad","kinelory","phin odelic","seuche","quae","süderstade"},sec={{t="Nachricht für Süderstade",b="Quae ist erfreut darüber, wie gut Ihr auf Kinelory aufgepasst habt, die in besserer Verfassung zurückgekehrt ist als nach einer Nacht in der Taverne. Die Gegenstände vom Hof sollten Phin Odelic eine Vorstellung davon vermitteln, was sich draußen in Arathi abspielt. Da der Hof angegriffen wurde, planen Quae und Kinelory, für den Fall von Vergeltungsmaßnahmen noch ein wenig vor Ort zu bleiben, und bitten Euch, nach Süderstade zurückzukehren und mit Phin zu sprechen."},{t="Phins Antwort",b="Phin ist froh zu hören, dass Kinelory und Quae wohlauf sind, und bezeichnet die beiden als unersetzliche Freunde und Weggefährten. Phin dankt Euch im Namen der gesamten Gruppe mit einem Geschenk und hofft, dass sie mit etwas Glück erfahren werden, was die Verlassenen planen, und dem ein Ende setzen können."}},faq={{q="Wer schickt Euch, um mit Phin Odelic zu sprechen?",a="Quae bittet Euch, nach Süderstade zu gehen, sobald Kinelory wohlbehalten vom Hof zurück ist.",al={"wer vergibt hints of a new plague 5","wer startet hints of a new plague","quae quest"}},{q="Warum kehren Quae und Kinelory nicht selbst nach Süderstade zurück?",a="Quae möchte, dass sie noch ein wenig in Arathi bleiben, um sicherzugehen, falls jemand Vergeltung für den Angriff auf den Hof übt.",al={"warum bleibt quae in arathi","warum zurückbleiben","quae bleibt"}},{q="Wo ist Phin Odelic zu finden?",a="In Süderstade.",al={"phin odelic aufenthaltsort","wo ist phin","phin odelic süderstade"}},{q="Was ist der Zweck der Überbringung von Nachrichten an Phin Odelic?",a="Die Gegenstände, die Kinelory vom Hof mitgebracht hat, sollten Phin Odelic helfen zu verstehen, was draußen in Arathi vor sich geht.",al={"warum phin aufsuchen","phin odelic zweck","was will phin"}}},fp="22,212,19.378.0,13.290.1,40.77.0,64.115.0,31.14.0,52.112.0"}
P.entries["quest:6611"] = {n="Ab mit Euch nach Gadgetzan!",s="Ab mit Euch nach Gadgetzan! ist eine Reise, die von Köchen der Horde angetreten wird, die über die Grenzen der Ausbilder ihrer Hauptstadt hinauswachsen wollen. Von Zamja in Orgrimmar angewiesen, reisen angehende Köche quer durch Kalimdor nach Süden nach Tanaris, um den exzentrischen Goblinmetzger Dirge Schnetzelhack aufzusuchen. Dieser Wegweiser markiert den Übergang zu wahrer Meisterschaft in den Kochkünsten.",h="Ab mit Euch nach Gadgetzan!",kw={"kochfachmann","kochen","dirge schnetzelhack","gadgetzan","orgrimmar","tanaris","tal der stärke","zamja"},ang={["faction:Horde"]="Orgrimmar verlässt sich auf externe Spezialisten wie neutrale Goblindköche, um seine Handwerker über die grundlegende Stammeskost hinaus zu fördern.",["profession:Cooking"]="Diese Quest markiert den Meilenstein, an dem ein Koch der Ausbildung in der Hauptstadt entwachsen ist und in die gefährliche Wildnis aufbrechen muss, um bei einem Fachmann-Meister zu lernen."},sec={{t="Ein Koch wächst über Orgrimmar hinaus",b="In der Gasse versorgt die Trollköchin Zamja zahllose Krieger und Reisende, die durch die roten Schluchten von Durotar ziehen. Doch wenn ein engagierter Koch jedes Rezept und jede Technik verinnerlicht hat, die Zamja zu bieten hat, gesteht die Meisterin ihre Grenzen ein. Nachdem sie ihr gesamtes kulinarisches Mojo weitergegeben hat, schickt sie ihren erfahrenen Schüler nach Süden in den Sand von Tanaris, wohl wissend, dass nur ein wahrer Meister seltsamer und exotischer Fleischsorten einen talentierten Koch noch weiter voranbringen kann."},{t="Der Metzger in der Wüste",b="Das Ziel ist Gadgetzan, der dampfbetriebene Handelsplatz des Steamwheedle-Kartells. Dort, im Inneren der lauten Taverne des Ortes, geht Dirge Schnetzelhack seinem Handwerk nach. Als Goblin mit einem unkonventionellen Gaumen und keinerlei kulinarischer Zimperlichkeit ist Dirge in ganz Kalimdor dafür berühmt, monströse Wüstenfauna – und gelegentliche Lederreste – zu deftigen Mahlzeiten zuzubereiten, die selbst abgehärtete Abenteurer stärken können."}},faq={{q="Wer schickt Euch nach Gadgetzan?",a="Zamja, die erfahrene Kochlehrerin der Trolle an den Kochfeuern in der Gasse von Orgrimmar, erteilt diese Aufgabe Köchen, die alles gemeistert haben, was sie weiß.",al={"questgeber","wer startet dies","zamja quest"}},{q="Warum schickt Zamja Euch fort?",a="Zamja hat alle Rezepte und Kochtechniken erschöpft, die sie lehren kann. Um den Fachmann-Rang im Kochen zu erlangen, schickt sie vielversprechende Köche zu Dirge Schnetzelhack nach Tanaris – einem exzentrischen Experten, der dafür bekannt ist, selbst aus den rauesten Wüstenzutaten genießbare Mahlzeiten zu zaubern.",al={"warum gadgetzan","warum dirge schnetzelhack","kochmeister"}},{q="Wer ist Dirge Schnetzelhack?",a="Dirge Schnetzelhack ist ein Goblinmetzger und Kochlehrer für Fachmänner, der im Gasthaus von Gadgetzan zu finden ist. Er ist berühmt für sein raues Gemüt, seine sonderbaren Ernährungstheorien – wie etwa das Aufspüren von Proteinen in alten Lederstiefeln – und seine Meisterschaft in exquisiter, exotischer Wildnisküche.",al={"wer ist dirge","dirge gadgetzan"}},{q="Ist diese Quest erforderlich, um Kochfachmann zu lernen?",a="Nein. Die Quest ist lediglich ein Wegweiser, der Horde-Spieler nach Tanaris leitet. Ein Koch mit ausreichender Fertigkeit kann direkt nach Gadgetzan reisen und mit Dirge Schnetzelhack sprechen, ohne zuvor von Zamja weiterempfohlen worden zu sein.",al={"brauche ich diese quest","wegweiser kochen","ist es pflicht"}},{q="Wo liegt Gadgetzan?",a="Gadgetzan ist der ummauerte Wüstenaußenposten des Steamwheedle-Kartells im nördlichen Sand von Tanaris, weit im Süden auf dem Kontinent Kalimdor unterhalb von Tausend Nadeln.",al={"standort gadgetzan","wo ist dirge"}},{q="Lernt Zamja eigentlich etwas, wenn Ihr zurückkehrt?",a="Obwohl Zamja keck verlangt, dass Ihr zurückkehrt und sie unterrichtet, sobald Ihr der Meisterkoch der Gegend seid, bleibt sie weiterhin eine Experten-Lehrerin in Orgrimmar und hütet ihre Kochfeuer für die nächste Generation von Reisenden.",al={"lernt zamja kochen","zamja unterrichten"}}},fp="20,356,25.422.0,25.395.0,27.158.0,29.269.0,24.267.0,48.224.0,27.179.0,51.206.0"}
P.entries["quest:662"] = {n="Tiefsee-Bergung",s="Im Anschluss an Land Ho! bittet Euch Erster Maat Nilzlix darum, die Seekarten und Logbücher zweier gesunkener Schiffe zurückzubringen, bevor irgendjemand die Bucht verlässt.",h="Im Anschluss an Land Ho!",kw={"arathihochland","beutebucht","deep sea salvage","harbinger","maiden's folly","nilzlix","o'breen","seehorn","spirit of silverpine"},sec={{t="Zwei im Riff verlorene Schiffe",b="O'Breen führte drei Schiffe in die Bucht, sicher, dass der Schatz hier lag. Die Harbinger legte sicher an. Als dann die Maiden's Folly zusammen mit der Spirit of Silverpine einlief, setzte die Ebbe ein, und beide Schiffe liefen auf einem tempelartigen Bauwerk im Riff auf Grund und sanken schnell."},{t="Was Nilzlix zurückhaben will",b="Nilzlix möchte die Logbücher und Seekarten beider Schiffswracks geborgen haben, da diese Informationen nicht neugierigen Blicken überlassen werden dürfen. Sollten sie in feindliche Hände geraten, so sagt er, würde Flottenmeister Seehorn die Mannschaft über die Planke schicken."}},faq={{q="Warum sanken die Maiden's Folly und die Spirit of Silverpine?",a="Als die beiden Schiffe einliefen, setzte die Ebbe ein. Beide liefen auf etwas auf Grund, das wie ein Tempel im Riff aussieht, und sanken rasch.",al={"warum die schiffe verunglückten","wie die schiffe sanken","ursache des schiffbruchs in der arathibucht"}},{q="Wer ist Erster Maat Nilzlix?",a="Er ist der Erste Maat, der von den drei Schiffen berichtet, die O'Breen in die Bucht führte, und er will, dass die Logbücher und Seekarten der beiden gesunkenen Schiffe geborgen werden.",al={"nilzlix","wer vergibt deep sea salvage"}},{q="Warum sind die Seekarten und Logbücher so wichtig?",a="Nilzlix möchte nicht, dass diese Informationen neugierigen Blicken überlassen werden. Sollten Feinde sie in die Hände bekommen, würde Flottenmeister Seehorn seiner Aussage nach die Mannschaft über die Planke schicken.",al={"warum logbücher bergen","warum seekarten und logbücher"}},{q="Welches Schiff gelangte in Sicherheit?",a="Nur die Harbinger. Sie legte sicher in der Bucht an, während die anderen beiden Schiffe untergingen.",al={"welches schiff überlebte","schiff harbinger"}},{q="Wer ist Flottenmeister Seehorn?",a="Nilzlix nennt ihn als denjenigen, der die Mannschaft über die Planke schicken würde, falls ihre Aufzeichnungen in feindliche Hände fielen.",al={"rolle von flottenmeister seehorn","wer ist seehorn"}},{q="Was ging dieser Aufgabe voraus?",a="Sie folgt auf Land Ho!",al={"voraussetzung für deep sea salvage","vorherige quest"}}},fp="16,132,26.272.0,23.228.0,57.125.0,26.144.0,41.160.0,28.86.0,28.106.0,27.19.0"}
P.entries["quest:6621"] = {n="König der Fäulnisklauen",s="König der Fäulnisklauen ist ein militärischer Vorstoß der Horde, der von Karang Amakkar am Außenposten von Zoram'gar in Auftrag gegeben wird. Um die verdorbenen Furbolgs der Fäulnisklauen südöstlich von Astranaar zu unterwerfen, pflanzen Champions der Horde ein Kriegsbanner direkt auf den heiligen Totemhügel des Stammes, was deren Häuptling, Häuptling Murgut, provoziert und zu seiner Hinrichtung führt.",h="König der Fäulnisklauen ist ein militärischer Vorstoß der Horde, der von Karang Amakkar am Außenposten von...",kw={"eschental","fäulnisklauen","furbolg","laubtatzenlichtung","karang amakkar","murgut","totemhügel","zoram'gar"},ang={["class:Shaman"]="Die verzerrten Totems und die Aggression der Fäulnisklauen spiegeln das anhaltende spirituelle Ungleichgewicht wider, das Eschentals einheimische Stämme nach der Invasion der Brennenden Legion heimsuchte.",["faction:Horde"]="Karang Amakkar nutzt offene Demonstrationen kriegerischer Dominanz, um feindselige Stämme in Eschental einzuschüchtern und den Nachschubkarawanen der Horde sicheres Geleit entlang der zentralen Pfade zu gewährleisten.",["race:Orc"]="Ein Banner zu platzieren, um einen feindlichen Häuptling zum Zweikampf herauszufordern, ist klassische orcische Kriegskunst, die Stärke und eine entscheidende Konfrontation langen Scharmützeln vorzieht."},sec={{t="Eine Machtdemonstration",b="Während die Nachtelfen darum kämpfen, die verdorbenen einheimischen Stämme von Eschental einzudämmen, begegnet die Horde der Bedrohung mit kalkulierter Aggression. Karang Amakkar am Außenposten von Zoram'gar erkennt, dass der Stamm der Fäulnisklauen zwar nicht die riesige Zahl der nördlichen Distelfelle erreicht, seine ungezügelte Wildheit jedoch eine lauernde Gefahr entlang der südlichen Straße darstellt. Anstatt auf Hinterhalte gegen Hordepatrouillen zu warten, befiehlt Karang eine präventive Demonstration kriegerischer Dominanz, um den Willen des Stammes zu brechen."},{t="Entweihung und Herausforderung",b="Der Angriff zielt auf die Laubtatzenlichtung ab, die nordöstlich des Mystralsees liegt. Karang fertigt ein Stammeskriegsbanner an, das direkt in die Mitte des Totemhügels der Fäulnisklauen gerammt werden soll – eine unverzeihliche Beleidigung der Ahnengeister und des Stolzes des Stammes. Verteidiger der Furbolgs stürmen in ihrer Verzweiflung auf den Hügel zu, um die anstößige Standarte niederzureißen, was Häuptling Murgut dazu zwingt, hervorzubrechen und seine Ehre im offenen Kampf zu verteidigen. Den persönlichen Totem Murguts an sich zu reißen, bricht ihre Führung und begründet die Vormachtstellung der Horde in diesem Gebiet."}},faq={{q="Wer befiehlt den Tod von Häuptling Murgut?",a="Karang Amakkar, ein Orc, der am Außenposten von Zoram'gar an der Westküste von Eschental stationiert ist, erteilt die Mission im Anschluss an seine Nachforschungen über die benachbarten Distelfellfurbolgs.",al={"questgeber könig der fäulnisklauen","wer vergibt könig der fäulnisklauen","karang amakkar quest"}},{q="Wo befindet sich die Laubtatzenlichtung?",a="Die Laubtatzenlichtung liegt südöstlich der Nachtelfensiedlung Astranaar und befindet sich nordöstlich des Mystralsees, direkt südlich von Eschentals östlicher Hauptstraße.",al={"wo liegt laubtatzenlichtung","standort fäulnisklauen","wo karangs banner platzieren"}},{q="Warum pflanzt die Horde ein Banner auf dem Totemhügel auf?",a="Das Einrammen von Karangs Banner direkt in den heiligen Totemhügel des Stammes ist eine bewusste Provokation. Die Entweihung ihrer heiligen Stätten zwingt die Fäulnisklauen zu einem wutentbrannten Angriff und nötigt Häuptling Murgut dazu, offen zu kämpfen, um sein Ansehen zu wahren.",al={"warum banner aufstellen","zweck banner totemhügel","warum murgut herausfordern"}},{q="Wer sind die Furbolgs der Fäulnisklauen?",a="Die Fäulnisklauen sind einer von mehreren Furbolgstämmen in Eschental, die nach dem Dritten Krieg dem Wahnsinn und der Verderbnis anheimgefallen sind. Obwohl sie zahlenmäßig kleiner sind als die Distelfelle, bleiben sie gewalttätig und Fremden gegenüber feindselig gesinnt.",al={"was sind die fäulnisklauen","fäulnisklauen stamm lore","wer ist häuptling murgut"}},{q="Was wird durch die Beschaffung von Murguts Totem erreicht?",a="Häuptling Murguts Totem zurück zum Außenposten von Zoram'gar zu bringen, beweist die Niederlage des Häuptlings. Ohne ihren Anführer und nach der Entehrung ihres heiligen Hügels sind die überlebenden Fäulnisklauen so eingeschüchtert, dass sie weitere Konflikte mit der Horde meiden.",al={"murguts totem zweck","was geschieht nach murguts tod"}},{q="Wie fügt sich diese Quest in die früheren Furbolg-Nachforschungen ein?",a="Diese Mission folgt direkt auf 'Zwischen den Zehen'. Nachdem er sich um den nördlichen Stamm der Distelfelle gekümmert hat, wendet Karang seine Aufmerksamkeit nach Süden, um die Fäulnisklauen präventiv zu zerschlagen, bevor diese koordinierte Überfälle starten können.",al={"verbindung zu zwischen den zehen","vorquest könig der fäulnisklauen"}}},fx={b1528232={q="Warum will Karang Amakkar, dass Chief Murgut besiegt wird?",a="Karang Amakkar betrachtet den Foulweald-Stamm als eine wachsende Gefahr für den Stützpunkt der Horde im Eschental. Obwohl sie zahlenmäßig geringer sind als die benachbarten Thistlefur, macht sie ihre schiere Wildheit zu einer unberechenbaren Bedrohung. Indem er eine direkte Herausforderung ausspricht und ihren Häuptling tötet, zielt Karang darauf ab, ihren Willen zu brechen und eine unmissverständliche Warnung auszusprechen, dass die Horde im Wald keinerlei Bedrohungen dulden wird.",al={"beweggrund von karang","warum murgut töten","warum foulweald besiegen"}},["9b8cfe09"]={q="Wer ist Chief Murgut?",a="Chief Murgut ist der wilde Anführer der Foulweald-Furbolgs, die in der Laubtatzenlichtung südöstlich von Astranaar leben. Er behält die Herrschaft über den Stamm von ihrem heiligen Totemhügel aus und führt durch reine Stärke und territoriale Aggression. Karang schickt Euch, um ihn zu einem offenen Kampf zu provozieren, indem Ihr das Stammesgebiet mit einem Kriegsbanner der Horde schändet.",al={"wer ist murgut","chief murgut foulweald","wer ist der king of the foulweald"}}},fp="21,312,15.490.0,25.511.0,37.180.0,34.158.0,53.240.0,31.222.0,47.227.0,64.229.0"}
P.entries["quest:6623"] = {n="Traumachirurg der Horde",s="„Traumachirurg der Horde“ ist eine Aufforderung, die versierte Sanitäter der Horde anweist, sich in Hammerfall im Arathihochland zu melden. Doktor Gregory Victor, der leitende Arzt der Traumaabteilung der Horde, sucht fähige Hände, um sie zu rekrutieren und zu prüfen, ob sie unter extremem Druck Leben retten können. Dem Ruf zu folgen, versetzt einen Sanitäter direkt in die düstere, hochriskante Realität der frontnahen Feldchirurgie.",h="„Traumachirurg der Horde“ ist eine Aufforderung, die versierte Sanitäter der Horde anweist, sich in...",kw={"arathihochland","doktor gregory victor","erste hilfe","hammerfall","traumachirurg der horde","arnok","triage"},ang={["class:Priest"]="Während göttliche Magie Wunden augenblicklich schließt, lehrt die weltliche Triage unerlässliche Disziplin bei der Erkennung, wer gerettet werden kann, wenn das Mana vollkommen versiegt ist.",["faction:Horde"]="Die militärische Stärke der Horde hängt stark von abgehärteten Schlachtfeldchirurgen ab, die dafür sorgen, dass Grunzer in brutalen Grenzkonflikten wie dem Arathihochland zusammengeflickt werden und weiterkämpfen können."},sec={{t="Eine Vorladung aus Hammerfall",b="Im Tal der Geister in Orgrimmar überbringt der Orc-Lehrer für Erste Hilfe, Arnok, erfahrenen Heilern die Nachricht, dass sie die Aufmerksamkeit von Doktor Gregory Victor persönlich erregt haben. Victor beaufsichtigt den Traumachirurgen der Horde vom befestigten Außenposten Hammerfall aus, gelegen in den umkämpften Hügeln des Arathihochlands. Arnok betrachtet die Vorladung nicht bloß als Befehl, sondern als den Gipfel des beruflichen Aufstiegs für jeden Schlachtfeldchirurgen."},{t="Die brutale Arbeit der Triage auf dem Schlachtfeld",b="Beim Erreichen von Hammerfall zeigt sich, dass der Posten alles andere als behaglich ist. Inmitten ständiger Scharmützel mit Stromgardes Streitkräften und örtlichen feindlichen Fraktionen wird Victor von verwundeten Grunzer, Räubern und Spähern überrannt. Der Chefarzt verliert keine Zeit mit Höflichkeiten zur Begrüßung der Neuankömmlinge; stattdessen werden Rekruten sofort in ihre Kittel befohlen, um ihren Wert bei einer brutalen, rasanten Notfalltriage unter Beweis zu stellen."}},faq={{q="Was ist Traumachirurg der Horde?",a="Traumachirurg der Horde stellt den engagierten medizinischen und chirurgischen Zweig dar, der an den Frontlinien der Horde dient. Unter der Leitung von Doktor Gregory Victor von Hammerfall aus haben sich seine Mitglieder auf Schlachtfeldmedizin, Notfalltriage und die Behandlung schwerer Kampfverletzungen unter chaotischen Bedingungen spezialisiert.",al={"traumachirurg der horde fraktion","was ist traumachirurg der horde","wer sind traumachirurg der horde"}},{q="Wer schickt mich auf diesen Einsatz?",a="Arnok, der Orc-Lehrer für Erste Hilfe im Tal der Geister in Orgrimmar, spricht die Vorladung aus. Er betrachtet den Dienst unter Doktor Gregory Victor als die höchste Ehre, die ein angehender Feldsanitäter erhoffen kann zu erreichen.",al={"questgeber traumachirurg der horde","wer startet traumachirurg der horde","krenk choplimb","arnok"}},{q="Wo befindet sich Doktor Gregory Victor?",a="Doktor Gregory Victor ist im Lazarett von Hammerfall stationiert, der Hauptfestung der Horde im nordöstlichen Arathihochland.",al={"doktor gregory victor aufenthaltsort","wo ist victor","hammerfall arzt"}},{q="Was geschieht nach der Meldung in Hammerfall?",a="Nach Eurer Ankunft weist Doktor Victor Euch unverzüglich an, Eure Kittel für die Folgeaufgabe „Triage“ anzulegen. Ihr werdet einer extremen Belastungsprobe unterzogen, bei der Ihr rapide abbauende verwundete Soldaten priorisieren und behandeln müsst, bevor sie ihren Verletzungen erliegen.",al={"was kommt nach traumachirurg der horde","folgequest nach traumachirurg der horde","triage quest"}},{q="Warum benötigt Hammerfall so dringend Feldsanitäter?",a="Hammerfall ist in Arathi von Feindseligkeiten umgeben und sieht sich unerbittlichen Konflikten mit menschlichen Streitkräften, Agenten des Syndikats und einheimischen Bestien gegenüber. Fortwährend strömen Verwundete in das Lager, was das kleine medizinische Personal des Stützpunkts an seine Grenzen bringt.",al={"warum braucht hammerfall sanitäter","hammerfall medizinische lage"}},{q="Können Allianz-Spieler diesen Einsatz annehmen?",a="Nein. „Traumachirurg der Horde“ ist ausschließlich Angehörigen der Horde vorbehalten. Die Allianz führt eine gleichwertige medizinische Beurteilung unter der Leitung von Doktor Gustav van Howzen in der Festung auf der Insel Theramore durch.",al={"kann allianz traumachirurg der horde machen","allianz-version von traumachirurg der horde"}}},fx={ac636cdf={q="Warum schickt Arnok mich zu Doktor Gregory Victor?",a="Doktor Gregory Victor, der Chefarzt von Horde Trauma in Hammerfall, hat persönlich nach Euch gefragt. Arnok schätzt Doktor Victor sehr und hält es für die Gelegenheit seines Lebens, unter ihm zu lernen – eine Gelegenheit, für die er nach eigenen Worten alles geben würde. Aus tiefem beruflichem Respekt und Begeisterung für Euer Talent möchte Arnok sicherstellen, dass Ihr eine solch seltene Berufung nicht verschwendet.",al={"warum will krenk das","beweggrund von krenk choplimb","warum zu victor schicken","warum will arnok das","beweggrund von arnok"}},b6720468={q="Warum bittet Doktor Victor speziell um mich?",a="Doktor Gregory Victor sucht die fähigsten Feldsanitäter der Horde, um sich den Reihen von Horde Trauma im Arathihochland anzuschließen. Eure bewiesene Meisterschaft in Erster Hilfe hat in Hammerfall seine Aufmerksamkeit erregt, was zu einer direkten persönlichen Vorladung führte, damit Ihr unter ihm trainieren könnt, anstatt unerprobte Rekruten oder gewöhnliche Soldaten aufzunehmen.",al={"warum ich horde trauma","warum braucht victor mich","warum will doktor victor mich"}}},fp="12,389,25.427.0,37.417.0,21.279.0,32.206.0,39.149.0,43.262.0,48.240.0,42.180.0"}
P.entries["quest:6625"] = {n="Traumachirurg der Allianz",s="Traumachirurg der Allianz ist eine Vorladung, die versierte Feldsanitäter anweist, sich auf der Insel Theramore in den Düstermarschen zu melden. Sie wird von Erste-Hilfe-Lehrern in den Hauptstädten der Allianz ausgegeben und lädt geschickte Heiler dazu ein, bei Doktor Gustav van Howzen zu lernen, dem leitenden Arzt des medizinischen Elitekorps der Allianz.",h="Traumachirurg der Allianz ist eine Vorladung, die versierte Feldsanitäter anweist, sich auf der Insel...",kw={"traumachirurg der allianz","düstermarschen","erste hilfe","eisenschmiede","nissa feuerstein","theramore","triage","van howzen"},ang={["faction:Alliance"]="Der Traumachirurg der Allianz stellt sicher, dass Frontkämpfer in ganz Kalimdor und den Östlichen Königreichen über fähige Feldsanitäter verfügen, die in der Lage sind, kritische Verletzungen unter Beschuss zu stabilisieren.",["race:Dwarf"]="Ausbilder wie Nissa Feuerstein in Eisenschmiede halten in der Großen Schmiede eifrig Ausschau nach vielversprechenden Schülern, die als beste medizinische Talente der Allianz in Theramore antreten können."},sec={{t="Ein Ruf ins Feld",b="Sobald ein Sanitäter die grundlegenden Techniken beherrscht, die in den großen Städten der Allianz gelehrt werden, können die örtlichen Ausbilder ihm kaum noch etwas beibringen. Für diejenigen, die ein außergewöhnliches Talent mit Nadel, Stoff und Triage an den Tag legen, ergeht direkt Nachricht an Doktor Gustav van Howzen. Von der Grenzfeste auf der Insel Theramore aus leitet Van Howzen den Traumachirurgen der Allianz – die Organisation, die damit betraut ist, in den brutalsten Kriegsgebieten Kalimdors und darüber hinaus Leben zu retten."},{t="Der Weg nach Theramore",b="Ausbilder wie Nissa Feuerstein in Eisenschmiede betrachten eine persönliche Vorladung von Van Howzen als ein außergewöhnliches Privileg. Die Insel Theramore steht unter ständigem Druck durch regionale Bedrohungen, Scharmützel und raue Wildnisbedingungen, was zu einem stetigen Zustrom schwer verwundeter Soldaten führt. Um Van Howzens Lazarett zu erreichen, bedarf es einer langen Seereise in die Düstermarschen, wo nur die besonnensten Schlachtfeldchirurgen hoffen können, seinen strengen Triage-Standards zu genügen."}},faq={{q="Was ist der Traumachirurg der Allianz?",a="Traumachirurg der Allianz ist der medizinische Elitezweig, der für fortschrittliche Schlachtfeldmedizin und Notfalltriage in der gesamten Allianz zuständig ist. Unter der Leitung des Chefarztes Gustaf Van Howzen kümmert sich das Korps um kritische Wunden, die mit normalen Feldverbänden nicht versorgt werden können.",al={"traumachirurg der allianz lore","wer sind traumachirurg der allianz"}},{q="Wer schickt Euch auf diese Quest?",a="Erste-Hilfe-Lehrer der Allianz, wie etwa Nissa Feuerstein in der Großen Schmiede von Eisenschmiede, entsenden vielversprechende Schüler, sobald diese den Gipfel der regulären städtischen Ausbildung erreicht haben.",al={"wer vergibt traumachirurg der allianz","eisenschmiede erste hilfe questgeber"}},{q="Wohin müsst Ihr reisen?",a="Ihr müsst zur menschlichen Hafenfeste auf der Insel Theramore reisen, die an der Ostküste der Düstermarschen auf dem Kontinent Kalimdor liegt.",al={"wo ist van howzen","traumachirurg der allianz ziel"}},{q="Wer ist Doktor Gustav van Howzen?",a="Doktor Gustav van Howzen ist der Chefarzt des Traumachirurgen der Allianz. Stationiert im Militärlazarett von Theramore, gilt er als eine der führenden Koryphäen für Notfallmedizin und chirurgische Triage in der Allianz.",al={"gustaf van howzen","chefarzt van howzen"}},{q="Was geschieht, nachdem man sich bei Doktor Van Howzen gemeldet hat?",a="Nach der Meldung in Theramore unterzieht Van Howzen die Kandidaten einer intensiven praktischen Triage-Prüfung, bei der ihre Fähigkeit getestet wird, Wellen sterbender Soldaten zu retten, bevor sie in die oberen Ränge der Feldmedizin aufgenommen werden.",al={"was kommt nach traumachirurg der allianz","triage quest danach"}},{q="Warum befindet sich das Lazarett in Theramore statt in Sturmwind oder Eisenschmiede?",a="Theramore ist eine aktive Grenzfeldgarnison, umgeben von feindseligem Marschland, gefährlichen Bestien und territorialen Scharmützeln. Die ständige Ankunft schwer verwundeter Truppen macht es zum idealen Schauplatz für ein hochintensives Traumatraining.",al={"warum lazarett theramore","warum dustwallow für trauma"}}},fx={a452e047={q="Warum schickt Nissa Feuerstein Euch nach Theramore?",a="Doktor Gustav van Howzen, der Chefarzt von Alliance Trauma, hat die persönliche Bitte geäußert, dass Ihr Euch seinen Reihen in Theramore anschließt. Nissa Feuerstein schätzt den renommierten Chirurgen sehr und betrachtet die Arbeit unter ihm als eine unvergleichliche Ehre. Sie leitet die Vorladung weiter, weil sie sicherstellen möchte, dass Ihr eine solch seltene medizinische Gelegenheit nicht verschwendet.",al={"warum will nissa dass dies getan wird","beweggrund von nissa feuerstein","warum nach theramore schicken"}},a6ba6381={q="Warum verlangt Doktor Gustav van Howzen nach Euch persönlich?",a="Doktor Gustav van Howzen benötigt fähige, erfahrene Feldmediziner, die unter Druck mit schweren Verletzungen umgehen können. Da Ihr Eure außergewöhnliche Meisterschaft in Erster Hilfe bewiesen habt, seid Ihr dem medizinischen Korps der Allianz aufgefallen, was Doktor Gustav van Howzen dazu veranlasste, Euch persönlich nach Theramore zu rufen, um Eure Fähigkeiten unter Feldbedingungen zu beurteilen.",al={"warum ich alliance trauma","warum will vanhowzen mich","warum spieler nach theramore schicken"}}},fp="15,307,19.448.0,21.468.0,24.252.0,28.178.0,28.143.0,31.221.0,49.217.0,71.240.0"}
P.entries["quest:6627"] = {n="Test der Lehre",s="Der Test der Lehre ist eine Prüfung des Verstandes und des historischen Wissens, die von dem Einsiedler Braug Dimspirit im Steinkrallengebirge gestellt wird. Nach dem Bergen des uralten Wälzers Vermächtnis der Aspekte müssen Reisende ihr Verständnis der alten Geschichte unter Beweis stellen, indem sie Braugs Frage beantworten. Wer dem Text keine Beachtung schenkt, findet sich jäh quer über Kalimdor verbannt wieder.",h="Der Test der Lehre ist eine Prüfung des Verstandes und des historischen Wissens, die von dem Einsiedler Braug...",kw={"aspekte","braug dimspirit","erdwächter","neltharion","steinkrallengebirge","taurajo","test des glaubens","der wetterwinkel"},ang={["class:Mage"]="Magier werden Braugs Teleportationsbann sowohl beeindruckend als auch strafend finden, da er zeigt, dass die Einsiedler des Steinkrallengebirges uralte Magie wirken, um unachtsame Gelehrte zu züchtigen.",["faction:Horde"]="Die Prüfungen der Horde in Kalimdor verlangen mehr als rohe Gewalt; von Kriegern wie Schamanen wird gleichermaßen erwartet, dass sie die uralten Narben und drakonischen Mächte verstehen, die den Kontinent geformt haben.",["race:Tauren"]="Die Prüfung verkörpert den Respekt der Tauren vor dem Wissen der Ahnen und der alten Geschichte und stellt sicher, dass junge Streiter nicht blindlings voranschreiten, ohne das Gleichgewicht der Welt zu kennen."},sec={{t="Eine Prüfung der Weisheit",b="Als Teil einer umfassenderen Reihe von Prüfungen, die bei Dorn Ebenenpirscher im Wetterwinkel ihren Anfang nahm, verlagert der Test der Lehre den Schwerpunkt von kriegerischem Überleben oder blindem Vertrauen auf das Verständnis der uralten Vergangenheit der Welt. Braug Dimspirit, der in den zerklüfteten Felsen des Steinkrallengebirges weilt, verlangt von Suchenden, uralte Schriften zu bergen und das darin enthaltene Wissen wahrhaftig zu verinnerlichen."},{t="Vermächtnis der Aspekte",b="Die Lektion dreht sich um die Erschaffung und Teilung der Drachenaspekte, insbesondere um den folgenschweren Pakt, der lange vor der Großen Zerschlagung geschlossen wurde. Braug prüft das Erinnerungsvermögen des Suchenden bezüglich des Erdwächters Neltharion, dessen Abgleiten in den Wahnsinn und Verrat die Oberfläche von Azeroth für immer veränderten. Denen, die die Geschichte nicht achten, ist es verwehrt, den Pfad der Weisheit weiter zu beschreiten."},{t="Der Preis des Ratens",b="Braug duldet kein planloses Raten. Ein Suchender, der eine falsche Antwort gibt, wird auf der Stelle durch mystische Mittel vertrieben und meilenweit entfernt nach Camp Taurajo im Südlichen Brachland teleportiert. Um seinen Ruf wiederherzustellen, bedarf es eines langen Fußmarsches zurück ins Steinkrallengebirge, um sich dem Urteil des Einsiedlers ein zweites Mal zu stellen."}},faq={{q="Wie lautet die Antwort auf Braug Dimspirits Frage?",a="Braug fragt nach der Identität des Erdwächters, die in dem Wälzer Vermächtnis der Aspekte beschrieben wird. Die richtige Antwort lautet Neltharion, der Schwarze Aspekt, der sich später gegen seine Drachengeschwister wenden sollte.",al={"braug frage antwort","test der lehre antwort","vermächtnis der aspekte frage"}},{q="Was geschieht, wenn Ihr falsch antwortet?",a="Nennt Ihr Braug den falschen Namen, führt dies zu einer sofortigen magischen Verbannung, die Euch direkt nach Camp Taurajo im Brachland teleportiert. Ihr müsst den gesamten Weg zurück zu seinem Hochsitz im Steinkrallengebirge zurücklegen, um die Prüfung erneut zu versuchen.",al={"falsche antwort test der lehre","test der lehre fehlgeschlagen","nach taurajo teleportiert"}},{q="Wer ist Braug Dimspirit?",a="Braug Dimspirit ist ein ältlicher Einsiedler, der im Steinkrallengebirge haust und Prüfungen des Wissens und der Überlieferung für die Horde abnimmt, womit er die in Tausend Nadeln begonnene Reihe spiritueller Prüfungen fortführt.",al={"braug dimspirit","wer vergibt test der lehre"}},{q="Wie hängt dies mit den Prüfungen in Tausend Nadeln zusammen?",a="Die Prüfung begann bei Dorn Ebenenpirscher im Wetterwinkel in Tausend Nadeln mit dem Test des Glaubens. Dorn prüft das körperliche und spirituelle Vertrauen und entsendet würdige Initianden anschließend quer durch Kalimdor, um ihren Verstand, ihre Entschlossenheit und ihre Stärke von anderen weisen Ältesten prüfen zu lassen.",al={"dorn ebenenpirscher verbindung","test des glaubens reihe"}},{q="Über welches Buch befragt Braug Euch?",a="Das Quiz prüft Euer Verständnis des Vermächtnisses der Aspekte, einer uralten Abhandlung, die den Segen der fünf Großen Drachenaspekte durch die Titanen zum Schutze Azeroths beschreibt.",al={"welches buch braug","vermächtnis der aspekte"}},{q="Wohin führt diese Questreihe als Nächstes?",a="Das Bestehen von Braugs Quiz über die Drachenaspekte führt zu weiteren forschenden Prüfungen der alten Geschichte, die von den Suchenden verlangen, ferne Regionen nach weiteren verschollenen Aufzeichnungen und uraltem Wissen zu durchkämmen.",al={"was kommt nach test der lehre","nächste quest nach test der lehre"}}},fx={a70a9b29={q="Warum prüft Euch Braug Dimspirit?",a="Braug Dimspirit fungiert als Prüfer bei den Prüfungen, die in Tausend Nadeln begannen. Während andere Prüfungen Euer kriegerisches Können oder Euren Glauben herausfordern, wurde der Test of Lore entwickelt, um sicherzustellen, dass Ihr Euch nicht nur auf rohe Gewalt verlasst. Indem er von Euch verlangt, alte Texte zu beschaffen und deren Inhalt zu verstehen, möchte Braug Weisheit und historisches Verständnis bei denjenigen kultivieren, die danach streben, die Horde zu repräsentieren.",al={"warum prüft euch braug","braug dimspirit ziel","warum test of lore"}}},fp="12,361,17.381.0,21.371.0,22.317.1,49.193.0,39.226.0,23.203.0,56.265.0,38.171.0,38.192.0"}
P.entries["quest:6628"] = {n="Test der Lehre",s="Diese Prüfung markiert die intellektuelle Untersuchung in einer umfassenderen Reihe spiritueller Prüfungen, die ihren Ursprung in Tausend Nadeln haben. Nachdem sie die Welt nach historischen Texten durchforstet haben, stellen sich Initianden Parqual Fintallas in Unterstadt, um zu beweisen, dass sie die finstereren Geschichten verstehen, die Azeroth prägen.",h="Diese Prüfung markiert die intellektuelle Untersuchung in einer umfassenderen Reihe spiritueller Prüfungen...",kw={"dorn ebenenpirscher","lichkönig","mark of shame","nerzhul","parqual fintallas","test der lehre","tausend nadeln","unterstadt","der wetterwinkel"},ang={["faction:Horde"]="Die Prüfung stärkt die Bande zwischen den Stämmen Kalimdors und dem Königreich unter Lordaeron und erinnert die Champions daran, dass Weisheit für das Überleben der Horde ebenso wichtig ist wie rohe Stärke.",["race:Tauren"]="Dieser durch die Tradition der Ältesten ins Leben gerufene Test drängt reisende Tauren dazu, die düstere Geschichte ihrer nördlichen Verbündeten, der Verlassenen, und der Welt jenseits von Kalimdor kennenzulernen.",["race:Undead"]="Die Thematik trifft das Herz der Identität der Verlassenen: die Tragödie von Ner'zhuls Erschaffung und die Entstehung des Fluchs, der sie band, bevor Sylvanas den Griff des Lichkönigs brach."},sec={{t="Eine Prüfung des Wissens",b="Während viele Prüfungen der Horde die kriegerische Stärke oder schiere Ausdauer auf die Probe stellen, erfordert der Test der Lehre wissenschaftliche Hingabe. Ausgehend von Dorn Ebenenpirschers spirituellem Programm im Wetterwinkel führt die Reise die Anwärter weit weg von den windgepeitschten Schluchten von Tausend Nadeln in die schattigen Hallen von Unterstadt. Parqual Fintallas fungiert als Prüfer und verlangt von den Suchenden ein anspruchsvolles Maß an historischer Bildung."},{t="Die Entstehung der Geißel",b="Um Parqual zufriedenzustellen, muss ein Initiand „Beginnings of the Undead Threat“ studieren, einen Text, der die verfluchten Ursprünge der Geißel in Lordaeron detailliert beschreibt. Der Kern seiner Befragung betrifft den Ursprung des Wesens, das auf dem Frostthron herrscht: des ehemaligen Ältestenschamanen Ner'zhul, dessen Essenz von der Brennenden Legion zum Lichkönig geschmiedet wurde. Diese düstere Abstammung zu kennen, gilt als unerlässlich, um die Existenz der Verlassenen und die Gefahren zu verstehen, die sowohl Kalimdor als auch den Östlichen Königreichen drohen."}},faq={{q="Wie lautet die Antwort auf Parquals Frage?",a="Parqual Fintallas fragt nach dem ursprünglichen Namen des Lichkönigs. Die richtige Antwort lautet Ner'zhul, der uralte Orcschamane, dessen Geist an den Frostthron gebunden war.",al={"lichkönig antwort","parqual frage","test der lehre antwort"}},{q="Was passiert, wenn Ihr die Frage falsch beantwortet?",a="Eine falsche Antwort bürdet Euch den Schwächungszauber Mark of Shame auf, der Euch dazu zwingt, die Strafe abzuwarten, bevor Parqual Euch einen erneuten Prüfungsversuch gestattet.",al={"mark of shame","falsche antwort test der lehre"}},{q="Wo beginnt diese Questreihe?",a="Die übergeordnete Prüfung beginnt bei Dorn Ebenenpirscher im Wetterwinkel, inmitten der aufragenden Felsnadeln von Tausend Nadeln.",al={"wo beginnt test der lehre","dorn ebenenpirscher questreihe"}},{q="Wo befindet sich Parqual Fintallas?",a="Parqual Fintallas hält sich in Unterstadt auf, wo er in den unterirdischen Bibliotheken und Korridoren der Verlassenen verweilt und angehende Schüler befragt.",al={"parqual finden","parqual fintallas standort"}},{q="Auf welchem Text basiert diese Prüfung?",a="Der Test basiert auf dem Wälzer „Beginnings of the Undead Threat“, der die Ursprünge der Seuche des Untods und die Erschaffung des Lichkönigs beschreibt.",al={"welches buch für test der lehre","beginnings buch"}},{q="Warum schickt eine Quest aus Tausend Nadeln Reisende nach Unterstadt?",a="Die von den Tauren ins Leben gerufenen Prüfungen sollen jede Facette eines Abenteurers fordern. Um das Wissen zu prüfen, werden die Anwärter über das Meer geschickt, um nach wissenschaftlichen Aufzeichnungen zu suchen, die in den Ruinen von Lordaeron aufbewahrt werden.",al={"warum nach unterstadt","tausend nadeln unterstadt"}}},fx={b37475e3={q="Warum will Parqual Fintallas, dass dies erledigt wird?",a="Parqual Fintallas stellt Eure Hingabe zum Streben nach Wissen auf die ultimative Probe. Er glaubt, dass Wissen in dieser gefährlichen Welt für das Überleben von größter Bedeutung ist – je mehr Ihr lernt und beobachtet, desto mehr von der Wahrheit werdet Ihr sehen. Da er Euch mit der Beschaffung des Wälzers über die Bedrohung durch die Untoten beauftragt hat, verlangt er den Beweis, dass Ihr dessen düstere Geschichte tatsächlich studiert und verinnerlicht habt, anstatt nur einen Botengang zu erledigen.",al={"parquals motiv","warum prüft mich parqual","warum test of lore"}}},fp="12,297,20.430.0,21.495.1,41.162.0,46.165.0,34.130.0,35.155.0,33.152.0,60.208.0"}
P.entries["quest:6629"] = {n="Tötet Grundig Finsterwolke",s="Tötet Grundig Finsterwolke ist eine Horde-Quest, die von Makaba Flachhuf entlang des südöstlichen Pfads im Steinkrallengebirge vergeben wird. Nachdem Ihr die Raufbolde und Söldner der Grimmtotem dezimiert habt, weist Euch Makaba an, den Anführer zur Strecke zu bringen, der für die Zerstörung seiner Heimat verantwortlich ist: Grundig Darkcloud. Die Eliminierung von Grundig und seinem Gefolge aus Schlägern bringt der verwüsteten Siedlung Gerechtigkeit.",h="Tötet Grundig Finsterwolke ist eine Horde-Quest, die von Makaba Flachhuf entlang des südöstlichen Pfads im...",kw={"schläger","darkcloud","flathoof","grimmtotem","grundig","makaba","posten","steinkrallengebirge"},ang={["faction:Horde"]="Das Steinkrallengebirge ist für die Expansion der Horde nach Kalimdor von entscheidender Bedeutung, und aggressive Kriegsfürsten der Grimmtotem wie Grundig bedrohen die Versorgungswege, die das Brachland mit Sonnenfels verbinden.",["race:Tauren"]="Der Grimmtotem-Clan sät weiterhin Zwietracht unter den Tauren und beweist durch Grundigs Massaker, dass der Zusammenhalt unter der Horde von ihrem mörderischen Extremismus stets bekämpft werden wird."},sec={{t="Der Schlächter des Pfades",b="Makaba Flachhuf gelang es, den plötzlichen, gewaltsamen Überfall auf seine Siedlung am Steinkrallenpfad zu überleben, doch sein Schmerz sitzt noch immer tief. Nachdem er Eure Fähigkeiten gegen das Fußvolk der Grimmtotem auf die Probe gestellt hat, weist er Euch auf den Drahtzieher des Blutvergießens hin: Grundig Darkcloud. Anders als bloße opportunistische Plünderer befehligt Grundig ein treues Gefolge aus Schlägern und führte das Massaker an, das das Dorf dem Erdboden gleichmachte."},{t="Schlag gegen den Posten der Grimmtotem",b="Grundig hat sein Lager am Posten der Grimmtotem aufgeschlagen, der weiter oben an der Bergstraße im Westen liegt. Um Makabas Volk zu rächen und den Pass vor weiterer Gewalt zu schützen, müssen Reisende in die Festung vordringen, Darkclouds inneren Kreis aus Schlägern zerschlagen und Grundig selbst das Handwerk legen, bevor seine Plünderer über andere verwundbare Lager herfallen können."}},faq={{q="Wer ist Grundig Darkcloud?",a="Grundig Darkcloud ist ein gewalttätiger Kommandant der Grimmtotem, der am Posten der Grimmtotem im südöstlichen Steinkrallengebirge stationiert ist. Er orchestrierte und führte den brutalen Angriff an, der das Dorf von Makaba Flachhuf zerstörte.",al={"grundig darkcloud","wer ist grundig","grimmtotem anführer"}},{q="Wo ist Grundig Darkcloud zu finden?",a="Grundig Darkcloud befindet sich am Posten der Grimmtotem, der am Bergpfad kurz hinter Makaba Flachhufs Lager nahe der Grenze zum Brachland im Westen liegt.",al={"grundig aufenthaltsort","wo ist grundig","posten der grimmtotem standort"}},{q="Was ist Makaba Flachhufs Motiv für diese Aufgabe?",a="Makaba musste mitansehen, wie seine Heimat und seine Clanmitglieder von den Grimmtotem niedergemetzelt wurden. Nachdem er bereits erste Rache an ihren Raufbolden und Söldnern geübt hat, verlangt er nach dem Kopf des Rädelsführers Grundig Darkcloud, um wirkliche Vergeltung und Seelenfrieden zu finden.",al={"warum grundig töten","makaba geschichte","makaba rache"}},{q="Warum greifen die Grimmtotem hier friedliche Siedlungen an?",a="Der Grimmtotem-Clan hegt tiefe Verachtung für die anderen Taurenstämme, insbesondere für jene, die sich mit der Horde verbündet haben oder friedlichere Wege beschreiten. Sie nutzen regelmäßig Hinterhalte, Überfälle und schiere Brutalität, um rivalisierende Clans von Ländereien zu vertreiben, die sie selbst beherrschen wollen.",al={"warum greifen grimmtotem an","grimmtotem feindseligkeit"}},{q="Was folgt, nachdem Grundig Darkcloud getötet wurde?",a="Der Tod von Grundig Darkcloud und seinen Schlägern bildet den Abschluss von Makaba Flachhufs kurzer Rachequestreihe. Da der Schlächter gerichtet ist, kann Makaba endlich um sein Dorf trauern – im Wissen, dass Gerechtigkeit geübt wurde.",al={"wie geht es nach grundig weiter","flathoof questreihe fortsetzung"}},{q="Welche Quest ist die Voraussetzung für diese Aufgabe?",a="Ihr müsst zuerst 'Rächt mein Dorf' abschließen, worin Makaba Flachhuf Eure Entschlossenheit auf die Probe stellt, indem er Euch die Raufbolde und Söldner der Grimmtotem im Lager direkt westlich niederstrecken lässt.",al={"voraussetzung tötet grundig","quest vor grundig"}}},fx={ce2e4f2e={q="Warum benötigt Makaba Flachhuf Eure Hilfe, anstatt selbst gegen Grundig zu kämpfen?",a="Makaba Flachhuf ist ein einsamer Überlebender, der auf der Bergstraße gestrandet ist, am Boden zerstört durch das Abschlachten seines Dorfes. Grundig Darkcloud befehligt den Posten der Grimmtotem, flankiert von einer persönlichen Vorhut aus wilden Bestien, die viel zu stark verteidigt ist, als dass ein einzelner, verwundeter Tauren sie direkt herausfordern könnte. Nachdem er gesehen hat, wie Ihr die einfachen Plünderer niedergemetzelt habt, setzt Makaba seine Hoffnung auf Vergeltung ganz in Eure Kampfkraft.",al={"warum ich makaba","warum kämpft makaba flachhuf nicht gegen grundig","warum schickt ihr mich kill grundig darkcloud"}}},fp="22,363,23.418.0,24.351.0,25.209.0,37.160.0,47.245.0,58.260.0,43.191.0,45.178.0"}
P.entries["quest:663"] = {n="Land in Sicht!",s="In der Faldirbucht begrüßt Euch der Ausguck Lolo mit der Nachricht, dass Kapitän O'Breens Aufenthalt hier weitaus länger dauern wird als geplant. Zwei Schiffe der Formation, die Spirit of Silverpine und die Maiden's Folly, sind verloren gegangen, und Lolo schlägt vor, dass Ihr mit dem Kapitän sprecht.",h="In der Faldirbucht begrüßt Euch der Ausguck Lolo mit der Nachricht, dass Kapitän O'Breens Aufenthalt hier...",kw={"beutebucht","die faldirbucht","harbinger","lolo the lookout","maiden's folly","seahorn","shakes o'breen","spirit of silverpine"},sec={{t="Lolos Begrüßung",b="Lolo, stets auf der Lauer, bemerkt Eure Ankunft in der Faldirbucht. Kapitän O'Breen hatte der Mannschaft hier nur wenige Stunden versprochen, genug Zeit, um den Schatz einzusammeln und nach Beutebucht zurückzukehren. Lolo bezweifelt, dass es so schnell gehen wird. Zwei Schiffe der Formation, die Spirit of Silverpine und die Maiden's Folly, liegen nun auf dem Meeresgrund. Jedem, der vorhat zu bleiben, wird geraten, mit dem Kapitän zu sprechen."},{t="Der Bericht des Kapitäns",b="Kapitän O'Breen nennt die ganze Angelegenheit ein schreckliches Schlamassel und fürchtet, dass Seahorn das Schiff übernehmen wird, wenn sich das herumspricht. Einer der Apparate des Professors deutete auf den verlorenen Schatz nahe der Bucht hin, also lief die Harbinger zum Anlegen ein und den beiden anderen Schiffen wurde signalisiert zu folgen. Dann grollte das Meer, das Wasser wich zurück und beide Schiffe zerschellten am Riff. Es ist nicht bloß ein Riff, sagt der Kapitän, und da unten befindet sich etwas. Für Hilfe für die Mannschaft wird eine ansehnliche Bezahlung versprochen."}},faq={{q="Was geschah mit den anderen Schiffen?",a="Zwei Schiffe der Formation, die Spirit of Silverpine und die Maiden's Folly, gingen verloren und liegen auf dem Meeresgrund.",al={"wo sind die anderen schiffe","gesunkene schiffe faldir","was hat die schiffe versenkt"}},{q="Warum kam die Mannschaft zur Faldirbucht?",a="Kapitän O'Breen kam zur Bucht, um Schätze zu bergen, in der Erwartung, nur wenige Stunden zu bleiben, bevor es zurück nach Beutebucht geht.",al={"warum sind sie hier","zweck der expedition","was hat sie nach arathi gebracht"}},{q="Mit wem solltet Ihr in der Faldirbucht sprechen?",a="Der Ausguck Lolo schlägt vor, dass Ihr mit Kapitän O'Breen in der Faldirbucht sprecht, falls Ihr vorhabt, hierzubleiben.",al={"wer ist captain o'breen","wo ist shakes o'breen"}}},fp="8,256,14.390.0,21.472.1,33.120.0,39.121.0,40.105.0"}
P.entries["quest:664"] = {n="Ertrunkene Trauer",s="Kapitän Steelgut sitzt trauernd in der Faldirbucht, nachdem er die geliebte Maiden's Folly verloren hat. Steelgut bittet Euch, die Daggerspine-Naga zu verfolgen, die die Überlebenden des Wracks niedergemetzelt haben.",h="Kapitän Steelgut sitzt trauernd in der Faldirbucht, nachdem er die geliebte Maiden's Folly verloren hat.",kw={"arathi","daggerspine","die faldirbucht","maiden's folly","naga","o'breen","raider","sorceress","steelgut"},sec={{t="Ein Kapitän am Feuer",b="Kapitän Steelgut sitzt am Feuer in der Faldirbucht und wünscht sich stattdessen ein nasses Grab. Die Mannschaft kämpfte hart, um die wunderschöne Maiden's Folly zu retten, doch das Meer versenkte sie, wobei das Wasser auf einen Schlag hereinbrach. O'Breen erreichte das Ufer sicher, doch Naga töteten die Überlebenden. Steelgut will Daggerspine-Räuber und -Hexenmeisterinnen tot sehen."}},faq={{q="Wer ist Kapitän Steelgut?",a="Der Kapitän der Maiden's Folly, der nun an einem Feuer in der Faldirbucht sitzt, nachdem das Schiff verloren ging.",al={"kapitän steelgut","steelgut","wer ist der questgeber"}},{q="Was geschah mit der Maiden's Folly?",a="Steelgut berichtet, dass das Meer das Schiff versenkte: In der einen Sekunde schwamm es noch, in der nächsten strömte bereits das Wasser herein, obwohl die Mannschaft sich nach Kräften bemühte, es zu retten.",al={"maidens folly","was geschah mit dem schiff","warum erlitt steelgut schiffbruch"}},{q="Warum will Kapitän Steelgut, dass die Naga getötet werden?",a="Naga töteten die Überlebenden des Wracks. Steelgut bezeichnet sie als Abschaum und will sie tot sehen.",al={"warum naga toeten","steelguts rache","daggerspine grund"}},{q="Welche Naga will Steelgut tot sehen?",a="Zehn Daggerspine-Räuber und drei Daggerspine-Hexenmeisterinnen.",al={"welche naga toeten","ziel naga","daggerspine ziele"}}},fp="15,183,21.320.0,24.98.0,36.135.0,47.85.0,35.58.0"}
P.entries["quest:6641"] = {n="Vorsha die Peitscherin",s="Vorsha die Peitscherin ist eine aggressive Hydra, die den Stützpunkt der Horde am Außenposten von Zoram'gar an der Küste von Eschental terrorisiert. Die einheimischen Naga verehren die Wildheit der Kreatur und unterhalten auf einer vorgelagerten Insel eine Opferpfanne, um sie zu ehren. Indem sie diese heilige Flamme löschen, provozieren Champions der Horde Vorsha und locken sie an Land, um ihren räuberischen Angriffen ein Ende zu setzen.",h="Vorsha die Peitscherin ist eine aggressive Hydra, die den Stützpunkt der Horde am Außenposten von Zoram'gar...",kw={"eschental","feuerschale","hydra","muglash","naga","vorsha","der zoramstrand","zoram'gar"},ang={["faction:Horde"]="Die Verteidigung des Zoram'gar-Außenpostens ist unerlässlich, um einen nördlichen Nachschubstützpunkt in Eschental aufrechtzuerhalten, wo die Versorgungslinien fortwährend angegriffen werden.",["race:Orc"]="Orcs wie Muglash weigern sich, hinter behelfsmäßigen Palisaden zu kauern, und ziehen es vor, in die Brandung zu stürmen, um räuberische Bestien von Angesicht zu Angesicht zu jagen."},sec={{t="Ein Schrecken aus der Tiefe",b="Der Außenposten von Zoram'gar liegt an einem exponierten Küstenstreifen im Nordwesten von Eschental und wird ständig von feindseligen Wildtieren, Nachtelfen und schlangenartigen Eindringlingen belagert. Zu den verheerendsten Bedrohungen, die den Zoramstrand durchstreifen, gehört Vorsha die Peitscherin – eine gigantische Hydra, die für brutale, unprovozierte Angriffe auf den Außenposten bekannt ist. Die Bestie taucht aus der Brandung auf, um Befestigungen zu zermalmen und Krieger abzuschlachten, ehe sie wieder in den tiefen Fluten verschwindet."},{t="Die Feuerschale der Naga",b="Die nahegelegenen Naga dulden die unersättliche Hydra nicht bloß; sie verehren aktiv ihre räuberische Bosheit. Auf einer felsigen Erhebung vor dem Strand halten die schlangenartigen Unholde eine Opferpfanne als Tribut an Vorsha ununterbrochen am Brennen. Muglash, ein Orc, der den ständigen Überfällen auf den Außenposten ein Ende setzen will, erkannte, dass die Entweihung dieser Ritualflamme die Bestie voller Wut an die Oberfläche treiben würde. So könnten die Verteidiger sie in einen Hinterhalt locken, anstatt auf das nächste überraschende Blutbad zu warten."}},faq={{q="Wer ist Vorsha die Peitscherin?",a="Vorsha die Peitscherin ist eine wilde, gewaltige Hydra, die die Gewässer vor dem Zoramstrand heimsucht. Sie unternimmt regelmäßig unprovozierte Überfälle auf den Außenposten von Zoram'gar, zerstört die Verteidigungsanlagen des Lagers und schlachtet Angehörige der Horde ab.",al={"vorsha","was ist vorsha","vorsha hydra"}},{q="Warum ehren die Naga Vorsha?",a="Die Naga des Zoramstrands achten Vorsha für ihre unerbittliche Wildheit und ihren zerstörerischen Appetit. Sie unterhalten eine vorgelagerte Feuerschale, die zu Ehren ihres bösartigen Wesens brennend gehalten wird, und behandeln die Bestie als Verkörperung unbändiger Küstenwut.",al={"warum naga hydra verehren","vorsha naga feuerschale","warum vorsha anbeten"}},{q="Wie wird Vorsha zum Kampf herausgelockt?",a="Muglash führt einen Angriff auf die Insel an, auf der die Naga Vorshas Feuerschale pflegen. Das Löschen der heiligen Flamme versetzt sowohl die ansässigen Naga-Wächter als auch die Hydra selbst in tiefen Zorn und zwingt Vorsha dazu, aus dem Meer aufzutauchen, um Vergeltung zu üben.",al={"wie vorsha beschwören","wie ruft man vorsha","feuerschaleninsel vorsha"}},{q="Wer ist Muglash?",a="Muglash ist ein Orc, der am Außenposten von Zoram'gar stationiert ist. Des ständigen Schreckens vor Vorshas unprovozierten Küstenangriffen überdrüssig, fasst er den Plan, die Ritualpfanne der Naga zu löschen und der Bestie an der Seite verlässlicher Verbündeter entgegenzutreten.",al={"wer ist muglash","muglash orc","zoramgar muglash"}},{q="Warum ist der Außenposten von Zoram'gar anfällig für Küstenbestien?",a="Der Außenposten von Zoram'gar ist ein abgelegenes und ungeschütztes Grenzpostenlager direkt an den Stränden von Eschental. Da Naga die Ruinen im Meer beherrschen und wilde Hydren die Brandung durchstreifen, macht seine Nähe zum Wasser ihn anfällig für amphibische Angriffe aus allen Richtungen.",al={"warum zoramgar angegriffen wird","gefahr am zoramstrand"}},{q="Was geschieht, nachdem Vorsha erschlagen wurde?",a="Nach dem Tod der Hydra wird der Sieg den Läufern des Kriegshymnenklans gemeldet, die die Stellungen am Außenposten von Zoram'gar sichern. Dies erleichtert die ständige Last der Grenzposten und schützt die unmittelbare Küste vor plötzlichen Überfällen.",al={"vorsha quest abgeben","wem vorsha melden"}}},fx={["4cca3bd5"]={q="Warum will Muglash, dass Vorsha getötet wird?",a="Vorsha ist ein ständiger Schrecken für den Außenposten von Zoram'gar. Die bösartige Hydra bricht wiederholt unprovoziert aus dem Meer hervor und verwüstet die Streitkräfte der Horde und alles andere, was ihr an der Küste in den Weg kommt. Muglash zielt darauf ab, diese verheerenden Raubzüge ein für alle Mal zu beenden, indem er die Bestie an ihrem heiligen Beschwörungsort konfrontiert.",al={"muglashs motiv","warum vorsha töten","warum vorsha bekämpfen"}},["23eb1be6"]={q="Warum benötigt Muglash Eure Hilfe gegen Vorsha?",a="Die Tötung von Vorsha erfordert eine Reise zu einer Insel, die von Küsten-Naga gehalten wird, und das Löschen des heiligen Kohlebeckens, das sie zu ihren Ehren bewahren. Muglash beabsichtigt, an Eurer Seite zu kämpfen, aber er weiß, dass das Ritual nicht nur die riesige Hydra selbst, sondern auch Wellen wütender Naga-Verteidiger anlocken wird. Ein einzelner Krieger kann solche Massen nicht alleine aufhalten.",al={"warum braucht muglash hilfe","warum bewacht die horde vorsha nicht","warum ich muglash"}}},fp="17,352,22.436.0,23.501.0,25.213.0,29.228.0,33.236.0,15.226.0,54.269.0,35.221.1"}
P.entries["quest:665"] = {n="Versunkener Schatz",s="Nun, da sie vollwertige Blackwater Raiders sind, sollen Professor Phizzlethorpe und Doktor Draxlegauge Mr. O'Breen dabei helfen, den verlorenen Elfenschatz zu finden. Um das dunkle Meer nach den Edelsteinen abzusuchen, benötigt der Professor Euren Schutz, während er an einem verzauberten Stein in einer Höhle eine Brille auflädt.",h="Nun, da sie vollwertige Blackwater Raiders sind, sollen Professor Phizzlethorpe und Doktor Draxlegauge Mr.",kw={"arathihochland","blackwater raiders","draxlegauge","verzauberter stein","brille","o'breen","phizzlethorpe","sunken treasure"},sec={{t="Aufladen der Brille",b="Die Edelsteine sind im dunklen Meer ohne Hilfe nahezu unmöglich zu finden, daher hat Doktor Draxlegauge eine Brille für die Suche gebaut. Sie muss mit der Macht des verzauberten Steins aufgeladen werden, der sich in einer Höhle ein kurzes Stück bergauf befindet. Die Höhle ist jedoch verflucht: Wer sich ihr nähert, gerät in einen Hinterhalt. Professor Phizzlethorpe bittet Euch, ihn zu verteidigen, während er die Energie des Steins in die Brille leitet."}},faq={{q="Wer bittet um Hilfe?",a="Professor Phizzlethorpe bittet Euch, ihn zu verteidigen, während er zur Höhle und zurück geht und die Brille des Doktors am verzauberten Stein auflädt.",al={"wer vergibt diese quest","phizzlethorpe","questgeber"}},{q="Warum muss die Brille aufgeladen werden?",a="Doktor Draxlegauge hat sie gebaut, um bei der Suche nach den verlorenen Edelsteinen im dunklen Meer zu helfen. Damit sie funktioniert, muss sie zuerst mit der Macht des Steins aufgeladen werden.",al={"warum brille aufladen","zweck der brille","wofür ist die brille"}},{q="Warum benötigt der Professor eine Eskorte?",a="Die Höhle ist verflucht, und wenn sie ihr nahe kommen, geraten sie in einen Hinterhalt. Er braucht Euch zu seiner Verteidigung, während er die Energie des Steins kanalisiert.",al={"warum phizzlethorpe beschützen","was ist in der höhle"}},{q="Für wen arbeiten der Professor und der Doktor?",a="Der Professor sagt, dass sie nun vollwertige Blackwater Raiders sind, sodass es ihnen zufällt, Mr. O'Breen bei der Suche nach dem verlorenen Elfenschatz zu helfen.",al={"wem helfen sie","mr obreen","blackwater raiders"}}},fp="15,292,20.372.0,23.133.0,38.133.0,38.127.0,49.131.0"}
P.entries["quest:666"] = {n="Versunkener Schatz",s="Nach dem ersten Teil von Sunken Treasure leiht Euch Doktor Draxlegauge seine Edelsteinjagdschutzbrille und bittet Euch, für Captain O'Breen zehn Elfen-Edelsteine vom Meeresgrund zu sammeln und die Schutzbrille anschließend zurückzubringen.",h="Nach dem ersten Teil von Sunken Treasure leiht Euch Doktor Draxlegauge seine Edelsteinjagdschutzbrille und...",kw={"arathihochland","captain o'breen","doktor draxlegauge","elven gem","die faldirbucht","flottenmeister seehorn","edelsteinjagdschutzbrille","versunkener schatz"},sec={{t="Zu Stein gewordene Edelsteine",b="Unten auf dem Meeresgrund lagen die Edelsteine so viele Jahre lang, dass sie zu dickem Gestein verhärtet sind. Die in die Schutzbrille eingearbeitete Kraft lässt Euch diese dennoch finden, und Doktor Draxlegauge ist stolz auf den Gnomen-Einfallsreichtum, der dahintersteckt. Er leiht Euch die Schutzbrille, damit Ihr die verlorenen Edelsteine für Captain O'Breen sammeln könnt."},{t="Trockener Boden für den Doktor",b="Er würde selbst hinunterschwimmen, sagt er, doch auf sicherem, trockenem Boden wartet wissenschaftliche Arbeit auf ihn. Er möchte, dass die Schutzbrille danach zurückgegeben wird, da er sicher ist, dass Captain O'Breen reichlich Verwendung für sie haben wird."}},faq={{q="Wer schickt Euch aus, um die Edelsteine zu sammeln?",a="Doktor Draxlegauge, der in der Faldirbucht wartet. Er möchte, dass zehn Elfen-Edelsteine für Captain O'Breen gesammelt werden.",al={"wer gibt versunkener schatz 2","questgeber versunkener schatz"}},{q="Warum ist für die Suche eine spezielle Schutzbrille erforderlich?",a="Nach so langer Zeit auf dem Meeresgrund haben sich die Edelsteine in dicken Stein verwandelt. Die in die Edelsteinjagdschutzbrille eingearbeitete Kraft lässt Euch diese leicht finden.",al={"warum edelsteinjagdschutzbrille","was bewirkt die schutzbrille"}},{q="Warum taucht Doktor Draxlegauge nicht selbst nach den Edelsteinen?",a="Er sagt, wichtige wissenschaftliche Angelegenheiten hielten ihn oben auf sicherem, trockenem Boden.",al={"warum schwimmt draxlegauge nicht","warum draxlegauge an land bleibt"}},{q="Könnt Ihr die Edelsteinjagdschutzbrille behalten?",a="Nein. Der Doktor leiht sie Euch und möchte sie zurückhaben, wenn Ihr fertig seid, da er erwartet, dass Captain O'Breen sie oft verwenden wird.",al={"edelsteinjagdschutzbrille behalten","muss ich die schutzbrille zurueckbringen"}},{q="An welcher Stelle der Reihe um Sunken Treasure steht dies?",a="Es folgt auf den ersten Teil von Sunken Treasure, als Professor Phizzlethorpe die Schutzbrille auflud. Ein dritter Teil folgt darauf.",al={"was kommt davor","was ist der naechste schritt"}}},fp="15,204,20.309.0,23.200.0,33.102.0,48.145.0,57.69.0,40.113.0,50.124.0"}
P.entries["quest:6661"] = {n="Tiefenbahn-Ratten-Razzia",s="Deeprun Rat Roundup ist eine Aufgabe der Allianz in der Tiefenbahn, bei der Spieler Monty bei der Schädlingsbekämpfung unterstützen. Mithilfe einer bezaubernden musikalischen Flöte treiben die Spieler lebende Tiefenbahnratten zusammen, um Montys Bruder mit frischem Fleisch für Rattenkebabs zu versorgen.",h="Deeprun Rat Roundup ist eine Aufgabe der Allianz in der Tiefenbahn, bei der Spieler Monty bei der...",kw={"tiefenbahnratte","deeprun rat roundup","die tiefenbahn","monty","rattenfänger-flöte","rattenkebab","ungeziefer"},ang={["profession:Cooking"]="Montys Bruder verwendet frisch gefangenes Tiefenbahn-Ungeziefer zur Zubereitung von Rattenkebabs und betont dabei, dass die Nagetiere bis zum Kochen am Leben bleiben müssen, damit das Fleisch nicht verdirbt."},sec={{t="Ungeziefer unter den Schienen",b="Unten in der unterirdischen Röhre der Tiefenbahn müht sich eine schillernde Gestalt namens Monty ab, die unterirdische Transitstrecke frei von Schädlingen zu halten. Monty spricht in rauem Seemannsjargon, behandelt die Bahnstrecke wie ein Schiffsdeck und heuert vorbeikommende Reisende an, um das umherwuselnde Ungeziefer zusammenzutreiben, das den Bahnhof heimsucht."},{t="Eine fragwürdige Delikatesse",b="Anstatt die Nagetiere direkt auszurotten, stattet Monty Helfer mit einer Rattenfänger-Flöte aus, die eine bezaubernde Melodie spielt, um die Tiefenbahnratten dazu zu verleiten, einem zu folgen. Die Kreaturen müssen quicklebendig zurückgebracht werden, da Montys Bruder frische Exemplare für kulinarische Zwecke benötigt: genauer gesagt, um sie zu Rattenkebabs zu verarbeiten, bevor das Fleisch verdirbt."}},faq={{q="Wer vergibt die Quest Deeprun Rat Roundup?",a="Monty, eine wie ein Pirat sprechende Gestalt, die unten in der Tiefenbahn stationiert ist, vergibt die Aufgabe. Er sucht nach helfenden Händen, um einen Ungezieferbefall entlang der unterirdischen Transitstrecke unter Kontrolle zu bringen.",al={"wer vergibt deeprun rat roundup","monty tiefenbahn","rattenquest-typ"}},{q="Warum muss Monty die Ratten lebendig gefangen bekommen?",a="Monty benötigt die Tiefenbahnratten lebendig gefangen, damit sie nicht verderben, bevor sein Bruder sie zu Rattenkebabs verarbeiten kann. Wenn das Ungeziefer vorzeitig stirbt, verdirbt das Fleisch.",al={"warum ratten lebendig fangen","was macht monty mit ratten","rattenkebab-lore"}},{q="Wie bezaubert und treibt Ihr die Ratten zusammen?",a="Monty stellt eine verzauberte Rattenfänger-Flöte zur Verfügung. Das Spielen ihrer Melodie in der Nähe des Ungeziefers bezaubert dieses, sodass die Ratten dem Spieler zurück zu Montys Station folgen.",al={"wie man tiefenbahnratten fängt","wofür ist die flöte","rattenfänger-flöte tiefenbahn"}},{q="Wo findet diese Aufgabe statt?",a="Die Quest findet im Inneren der Tiefenbahn statt, dem unterirdischen Wunderwerk der Ingenieurskunst, das die Allianzstädte Sturmwind und Eisenschmiede verbindet. Monty ist an den Bahnsteigen stationiert.",al={"wo ist deeprun rat roundup","monty aufenthaltsort","tiefenbahn ratten"}},{q="Wer ist Montys Bruder?",a="Monty erwähnt, dass er einen Bruder hat, der Rattenkebabs zubereitet, nennt ihn jedoch nicht namentlich. Sein Bruder ist auf einen stetigen Nachschub an frischen, lebenden Ratten angewiesen, um zu verhindern, dass er ranziges Fleisch serviert.",al={"wer ist montys bruder","montys bruder koch","kebab-bruder"}},{q="Warum spricht Monty wie ein Pirat?",a="Obwohl Monty in starkem nautischem Piratenjargon spricht und die Bahn wie ein Schiffsdeck behandelt, hat er die Pflichten der Schädlingsbekämpfung unten in der Untergrundbahn übernommen.",al={"warum ist ein pirat in der tiefenbahn","monty pirat tiefenbahn"}}},fp="19,232,24.312.0,23.357.1,40.189.0,44.167.0,39.166.0,32.186.0,23.176.0,34.157.0"}
P.entries["quest:6662"] = {n="Mein Bruder Nipsy...",s="Me Brother, Nipsy ist eine Lieferungsquest der Allianz, die Reisende über die Tiefenbahn zwischen Eisenschmiede und Sturmwind führt. Ein Gnom namens Monty beauftragt Pendler damit, eine Kiste lebender Ratten zu seinem Bruder Nipsy zu transportieren, der am gegenüberliegenden Endbahnhof einen Rattenspieß-Stand betreibt. Hinter dem skurrilen Auftrag verbirgt sich ein berührender Einblick in Montys zerrütteten Verstand nach der Tragödie von Gnomeregan.",h="Me Brother, Nipsy ist eine Lieferungsquest der Allianz, die Reisende über die Tiefenbahn zwischen...",kw={"die tiefenbahn","gnomeregan","eisenschmiede depot","me brother, nipsy","monty","eigenartiges fleisch","nipsy","rattenspieß","sturmwind depot"},ang={["faction:Alliance"]="Die Tiefenbahn dient als unverzichtbares, rasantes Meisterwerk der Ingenieurskunst, das Sturmwind und Eisenschmiede verbindet – komplett mit skurrilen lokalen Händlern, die Reisende in beiden Depots bedienen.",["profession:Cooking"]="Nipsys kulinarisches Unternehmen dreht sich darum, frische Deeprun-Ratten zu essbaren Spießen für Pendler zu verarbeiten, die zwischen Eisenschmiede und Sturmwind reisen.",["race:Gnome"]="Montys exzentrische Wahnvorstellungen und piratenhafte Allüren rühren direkt vom Trauma des Vorfalls in Gnomeregan her und zeigen den tiefen persönlichen Tribut, den der Fall ihrer Stadt den überlebenden Gnomen abverlangte."},sec={{t="Eine unterirdische Lieferung",b="Me Brother, Nipsy ist eine kurze Botenaufgabe, die Pendlern die Wunder – und Gefahren – der Tiefenbahn näherbringt. Auf der Seite von Eisenschmiede stationiert, beauftragt ein sonderbarer Gnom namens Monty Reisende damit, einen Karton frischer Tierchen durch den unterirdischen Transitkorridor zu seinem Bruder Nipsy im Depot von Sturmwind zu befördern. Die Lieferung verdeutlicht den bizarren alltäglichen Handel, der sich unter den Bergen abspielt, welche die Zwergen- und Menschenhauptstädte miteinander verbinden."},{t="Der Handel mit Rattenspießen",b="Obwohl das Paket als Karton mit eigenartigem Fleisch beschriftet ist, ist es tatsächlich mit lebenden, sich windenden Deeprun-Ratten gefüllt. Nipsy betreibt am Sturmwinder Terminal ein Ratten-Kabob-Unternehmen und benötigt seine Ware, bevor sie verdirbt. Als die Kiste unversehrt und zuckend ankommt, ist Nipsy erleichtert, seinen kulinarischen Betrieb für hungrige Reisende, die den Verkehrsknotenpunkt passieren, weiter bestücken zu können."},{t="Narben von Gnomeregan",b="Hinter der humorvollen Lieferung verbirgt sich ein düsterer Einblick in das Leben der vertriebenen Gnome von Eisenschmiede. Monty spricht in übertriebenem Piratenjargon und warnt Reisende davor, ihre Gliedmaßen an Bord zu behalten, damit sie nicht mit einem Holzbein enden. Nach Erhalt der Ratten beklagt Nipsy, dass Monty in seinem Leben noch nie ein Meer gesehen hat; seine exzentrische Piratenpersönlichkeit ist lediglich ein Bewältigungsmechanismus, der aus dem anhaltenden Trauma des radioaktiven Falls von Gnomeregan entstanden ist."}},faq={{q="Wer vergibt die Quest Me Brother, Nipsy?",a="Monty ist ein exzentrischer Gnom, der auf der Eisenschmiede-Seite der Tiefenbahn zu finden ist. Tief gezeichnet von der Katastrophe in Gnomeregan, hat Monty die Sprache und Verhaltensweisen eines Piraten angenommen, obwohl er noch nie ein Meer gesehen hat, und fängt lebende Ratten, um sie über die Bahnlinie zu verschicken.",al={"wer vergibt me brother nipsy","wer ist monty","monty tiefenbahn"}},{q="Wer ist Nipsy?",a="Nipsy ist Montys Bruder, der einen Essensstand im Tiefenbahndepot von Sturmwind betreibt. Er verlässt sich darauf, dass Monty Lieferungen lebender Ratten durch den Bahntunnel schickt, um sein Rattenspieß-Geschäft mit frischen Zutaten zu versorgen.",al={"wer ist nipsy","wo ist nipsy","nipsy standort"}},{q="Was befindet sich im Karton mit eigenartigem Fleisch?",a="Trotz der scherzhaften Beschriftung als Eigenartiges Fleisch ist die Kiste mit lebenden, zuckenden Deeprun-Ratten gefüllt, die von Monty gefangen wurden. Nipsy besteht darauf, dass sie lebendig und munter ankommen, damit das Fleisch nicht verdirbt, bevor es auf Spieße gesteckt und zu Kabobs verarbeitet wird.",al={"was ist karton mit eigenartigem fleisch","kiste mit eigenartigem fleisch","was ist in der kiste"}},{q="Warum spricht Monty wie ein Pirat?",a="Monty redet wie ein Pirat, weil das Trauma der Katastrophe von Gnomeregan seinen Verstand zerrüttet hat. Wie sein Bruder Nipsy beklagt, hat Monty noch nie ein Meer gesehen, dennoch hält er an piratenhaften Allüren fest und warnt Reisende davor, Gliedmaßen über den Schienen der Bahn zu verlieren.",al={"warum spricht monty wie ein pirat","ist monty ein pirat","monty pirat geschichte"}},{q="Was macht Nipsy mit den Ratten?",a="Nipsy bereitet Rattenspieße zu und verkauft sie an Pendler, die das Depot von Sturmwind passieren. Ein stetiger Nachschub an frischen, zuckenden Tierchen, die mit der Bahn ankommen, hält sein unkonventionelles unterirdisches Speiselokal am Laufen.",al={"was macht nipsy mit den ratten","rattenspieß betrieb","nipsy essen"}},{q="Wohin liefert Ihr die Sendung?",a="Ihr bringt die Sendung mit der Tiefenbahn vom Depot in Eisenschmiede zum Endbahnhof von Sturmwind. Wenn Ihr in einen der Hochgeschwindigkeits-Waggons der Bahn einsteigt, werdet Ihr durch den Unterwassertunnel direkt zu Nipsys Station auf der Sturmwind-Seite befördert.",al={"weg zu nipsy","wohin mit dem fleisch","tiefenbahnfahrt zu nipsy"}}},fp="17,385,23.470.0,19.380.0,19.421.1,38.266.0,13.224.0,42.232.0,35.256.0,33.220.0,34.238.0"}
P.entries["quest:667"] = {n="Tod von unten",s="Im Arathihochland erwartet Shakes O'Breen einen Angriff der Daggerspine-Naga aus dem Meer, und die Mannschaft kann ohne O'Breens Kenntnis der Gewässer nicht nach Beutebucht zurücksegeln. Ihr bleibt neben O'Breen an Bord, bemannt die Kanone und schlagt die Naga zurück.",h="Im Arathihochland erwartet Shakes O'Breen einen Angriff der Daggerspine-Naga aus dem Meer, und die Mannschaft...",kw={"arathihochland","beutebucht","daggerspine","naga","shakes o'breen","schiffskanone"},sec={{t="Das Deck halten",b="Nach „Sunken Treasure“ sieht Shakes O'Breen, wie sich die Daggerspines zum Angriff sammeln. Naga sind für ihre Rücksichtslosigkeit bekannt und werden nicht aufhören, bis O'Breen tot ist. O'Breen stellt das eigene Leben nicht über das der Mannschaft, bittet Euch jedoch um Verteidigung, da die Mannschaft ohne diese Kenntnis der Meere Beutebucht nicht erreichen kann. Ihr wartet mit O'Breen an Bord darauf, dass die Naga aus dem Wasser kommen."},{t="Danach",b="Wenn der Angriff vorüber ist, sagt O'Breen, dass das Schiff auslaufen wird, sobald die Flut steigt. O'Breen hätte Euch einen Platz in der Mannschaft angeboten, sieht aber ein, dass Ihr Wichtigeres zu tun habt."}},faq={{q="Wer greift Shakes O'Breen an?",a="Die Daggerspine-Naga sammeln sich zum Angriff und werden nicht nachlassen, bis Shakes O'Breen tot ist. Sie kommen aus dem Meer.",al={"wer greift shakes an","wer sind die angreifer","angriff der daggerspine"}},{q="Warum ist der Schutz von Shakes O'Breen für die Mannschaft so entscheidend?",a="Shakes O'Breen stellt das eigene Leben nicht über das der Mannschaft, aber ohne O'Breens Kenntnis der Meere kann die Mannschaft nicht nach Beutebucht zurücksegeln.",al={"warum shakes obreen beschützen","warum ist shakes wichtig","shakes obreen navigation"}},{q="Wie wehrt Ihr den Angriff der Naga ab?",a="Ihr bleibt oben auf dem Schiff bei Shakes O'Breen und bemannt die Kanone, um die Naga zurückzuschlagen, wenn sie aus dem Meer kommen.",al={"wie man tod von unten meistert","wie man shakes verteidigt","kanonenverteidigung"}},{q="Wo findet diese Verteidigung statt?",a="Auf Shakes O'Breens Schiff im Arathihochland, wobei die Naga aus dem Meer kommen.",al={"wo ist tod von unten","ort von tod von unten"}}},fp="16,250,16.390.0,9.179.1,32.124.0,54.153.0,34.114.0,35.84.0"}
P.entries["quest:668"] = {n="Versunkener Schatz",s="Doktor Draxlegauge uebergibt Euch die Elfengemmen und schickt Euch los, um sie zu Captain O'Breen zu bringen. Nach einigen Wochen unter Piraten wissen er und der Professor, dass es ungesund ist, ihren Schatz zu behalten.",h="Doktor Draxlegauge uebergibt Euch die Elfengemmen und schickt Euch los, um sie zu Captain O'Breen zu bringen.",kw={"arathihochland","captain o'breen","doktor draxlegauge","elfenedelsteine","piraten","shakes o'breen","sunken treasure"},sec={{t="Schatz fuer den Captain",b="Doktor Draxlegauge moechte Captain O'Breen nicht warten lassen, da der Captain die Elfengemmen selbst sehen will. Nach Wochen unter diesen Piraten haben der Doktor und der Professor gelernt, dass es ihrer Gesundheit abtraeglich ist, wenn man dabei erwischt wird, wie man den Schatz von Piraten einbehaelt. Er haendigt Euch die Gemmen aus, damit Ihr sie zu O'Breen bringt, der an der Bruecke wartet."}},faq={{q="Wer schickt Euch zu Captain O'Breen?",a="Doktor Draxlegauge gibt Euch die Elfengemmen und bittet Euch, sie zu Captain O'Breen zu bringen.",al={"wer gibt sunken treasure 3","draxlegauge quest"}},{q="Warum ist Doktor Draxlegauge so begierig darauf, die Gemmen abzugeben?",a="Nach einigen Wochen unter diesen Piraten sind er und der Professor zu dem Schluss gekommen, dass es ihrer Gesundheit schaden wuerde, wenn man dabei erwischt wird, den Schatz der Piraten einzubehalten.",al={"warum elfenedelsteine uebergeben","warum edelsteine pirat geben"}},{q="An welcher Stelle der Reihe steht dies?",a="Es folgt auf den zweiten Teil von Sunken Treasure, und danach kommt ein vierter Teil.",al={"sunken treasure reihenfolge","was kommt vor sunken treasure 3"}}},fp="15,198,24.341.0,33.89.0,55.157.0,34.80.0"}
P.entries["quest:669"] = {n="Versunkener Schatz",s="Nach dem vorherigen Schritt in der Reihe „Sunken Treasure“ sitzt Shakes O'Breen dort fest, wo er ist, und benötigt jemanden, der Flottenmeister Seehorn in Beutebucht Nachricht überbringt. Er bittet Euch, einen Probe-Edelstein als Beweis für den Fund mitzunehmen.",h="Nach dem vorherigen Schritt in der Reihe „Sunken Treasure“ sitzt Shakes O'Breen dort fest, wo er ist, und...",kw={"arathihochland","blackwater raiders","beutebucht","flottenmeister seehorn","elfenedelsteinprobe","shakes o'breen","sunken treasure"},sec={{t="Nachricht für Beutebucht",b="Shakes O'Breen möchte, dass Flottenmeister Seehorn unverzüglich von dem Fund erfährt, kann jedoch nicht so einfach weg. Die Ebbe steht zu niedrig, und die Kreaturen, die sie aufgeschreckt haben, beobachten jede Bewegung. Er bittet Euch, den Blackwater Raiders zu helfen, indem Ihr Seehorn in Beutebucht mitteilt, dass der Schatz gefunden wurde und weiterer geborgen wird. Als Beweis wird Euch ein elfischer Probe-Edelstein mitgegeben."}},faq={{q="Warum kann Shakes O'Breen den Edelstein nicht selbst überbringen?",a="Die Ebbe steht zu niedrig, als dass sie wegkommen könnten, und die Kreaturen, die sie aufgeschreckt haben, behalten ihre Bewegungen genau im Auge.",al={"warum shakes nicht wegkann","warum shakes festsitzt","warum shakes einen kurier braucht"}},{q="Wer ist Flottenmeister Seehorn?",a="Er ist der Flottenmeister in Beutebucht, von dem O'Breen möchte, dass er unverzüglich von dem Fund erfährt.",al={"wer ist seehorn","wo ist flottenmeister seehorn"}},{q="Welcher Beweis wird nach Beutebucht gebracht?",a="Ein elfischer Probe-Edelstein, der zeigt, dass der Schatz gefunden wurde und weiterer geborgen wird.",al={"was ist der beweis","welcher edelstein wird ueberbracht"}}},fp="15,204,18.358.0,49.118.0,28.84.0,41.93.0"}
P.entries["quest:67"] = {n="Die Legende von Stalvan",s="Dieser Botengang leitet die Spurensuche nach dem Schicksal von Stalvan Dunstmantel ein, beauftragt von Amtmann Daltry aus dem Rathaus von Dunkelhain. Seine ältesten Aufzeichnungen weisen nach Westen zum verlassenen Schule in Mondbruch in Westfall und eröffnen eine klassische Untersuchung des Niedergangs eines gewöhnlichen Mannes.",h="Dieser Botengang leitet die Spurensuche nach dem Schicksal von Stalvan Dunstmantel ein, beauftragt von...",kw={"daltry","dämmerwald","fußkiste","unglückseliger geist","mistmantle","mondbruch","schulhaus","stalvan","westfall"},ang={["class:Mage"]="Der Unglückselige Geist, der die Fußkiste bewacht, nutzt Verwandlung und schwächende Fluche und bietet eine unheimliche Begegnung mit trauergebundener Magie in einem ansonsten gewöhnlichen Klassenzimmer.",["faction:Alliance"]="Dieser Abschnitt der Untersuchung verdeutlicht, wie tief die ländlichen Städte des Königreichs zerrüttet sind, und zwingt Helden dazu, durch das von den Defias besetzte Westfall zu wandern, nur um eine Anfrage im Stadtregister von Dunkelhain zu klären."},sec={{t="Die Bitte des Amtmanns",b="Nach den ersten Nachforschungen in Dunkelhain zieht Amtmann Daltry das Stadtregister heran, um Stalvan Dunstmantel ausfindig zu machen. Zu seiner Überraschung wurde das Buch seit Jahren nicht aktualisiert und verzeichnet Stalvans letzten bekannten Wohnsitz weit im Westen, am Schulhaus in Mondbruch. Unwissend über die düstere Natur der Nachforschungen betrachtet Daltry dies als routinemäßige bürokratische Angelegenheit und bittet Reisende darum, die Adresse zu überprüfen und alle Aufzeichnungen zu beschaffen, die Dunkelhains verstaubte Archive auf den neuesten Stand bringen könnten."},{t="Die Ruinen von Mondbruch",b="Der Spur zu folgen bedeutet, sich über die Düsternis des Dämmerwalds hinaus in den gesetzlosen Staub von Westfall zu wagen. In Mondbruch, einst eine blühende ländliche Siedlung, wimmelt es nun von Gesetzlosen der Bruderschaft der Defias. Nahe dem Zentrum der verfallenen Stadt steht ihr verlassenes Schulhaus, ruhig inmitten der Besatzung durch die Banditen. Im Inneren birgt eine alte Fußkiste die ersten handfesten Hinweise auf Stalvans früheres Leben als Lehrer, ebenso wie eine anhaltende, ruhelose Trauer, die an die Truhe gebunden ist."},{t="Eine tragische Heimsuchung",b="Die alte Fußkiste zu stören offenbart mehr als nur vergessene Seiten; es beschwört einen Unglückseligen Geist herauf, der jeden angreift, der Stalvans Vergangenheit ans Licht bringt. Die klagende Magie der Erscheinung verflucht Eindringlinge und deutet auf eine ungelöste Tragödie hin, die mit dem Fortgang des Schulmeisters aus Westfall verknüpft ist, wodurch sich eine einfache historische Nachforschung in eine aktive Heimsuchung verwandelt."}},faq={{q="Wer ist Amtmann Daltry?",a="Amtmann Daltry ist der Verwalter der städtischen Aufzeichnungen im Rathaus von Dunkelhain im Dämmerwald. Er hilft, indem er das örtliche Register nach Erwähnungen von Stalvan Dunstmantel durchsucht, findet dort jedoch nur uralte, veraltete Einträge.",al={"daltry","amtmann dunkelhain","wer startet die legende von stalvan 2"}},{q="Wo befindet sich das Schule in Mondbruch?",a="Das Schulhaus befindet sich in Mondbruch im südwestlichen Westfall. Es ähnelt in seiner Architektur dem Rathaus von Dunkelhain und steht inmitten der Stadt, umgeben von feindseligen Defias-Banditen.",al={"schule in mondbruch standort","wo ist das schulhaus","wo ist stalvans fußkiste"}},{q="Was befindet sich in der alten Fußkiste?",a="Die Fußkiste enthält alte Aufzeichnungen und persönliche Gegenstände aus Stalvan Dunstmantels Zeit als Lehrer in Mondbruch und liefert den nächsten Anhaltspunkt bei der Suche nach seinem Aufenthaltsort.",al={"stalvans fußkiste","was ist in der fußkiste"}},{q="Warum greift beim Öffnen der Fußkiste ein Geist an?",a="Das Öffnen der Fußkiste beschwört einen Unglückseligen Geist herauf, der mit Verwandlung und Flüchen angreift. Die ruhelose Erscheinung ist an die dunkle Tragödie rund um Stalvans Vergangenheit und seinen Weggang aus Mondbruch gebunden.",al={"unglückseliger geist","warum erscheint ein geist","fluch von stalvans geist"}},{q="Warum hat Stalvan Westfall verlassen?",a="Stalvan diente als Schulmeister in Mondbruch, bevor er weiterzog, um andernorts im Königreich eine Anstellung als Hauslehrer zu suchen, wobei er seine alten Besitztümer aus dem Schulhaus in der verlassenen Stadt zurückließ.",al={"warum verließ stalvan mondbruch","stalvan mondbruch geschichte"}},{q="Ist es sicher, Mondbruch zu betreten?",a="Nein. Mondbruch ist vollständig unter die Kontrolle der Bruderschaft der Defias gefallen, was bedeutet, dass sich jeder, der das Schulhaus sucht, durch bewaffnete Diebe und Gesetzlose kämpfen muss.",al={"ist mondbruch gefährlich","mobs in mondbruch"}}},fx={["803ebeb2"]={q="Warum will Amtmann Daltry, dass dies erledigt wird?",a="Amtmann Daltry ist sehr stolz auf das Führen des Stadtregisters von Dunkelhain. Bei der Überprüfung der Unterlagen für Stalvan Dunstmantel stellte er fest, dass als letzte bekannte Adresse des Mannes die Schule in Mondbruch in Westfall eingetragen ist. Da er weiß, wie veraltet dieser Eintrag ist, möchte er, dass Ihr die Schule besucht und aktuelle Informationen aufdeckt, damit er seine Geschäftsbücher ordentlich, sauber und korrekt halten kann.",al={"warum will daltry stalvan aufzeichnungen","amtmann daltrys motiv","warum stalvan finden"}}},fp="21,278,24.479.0,22.465.0,17.359.1,20.206.0,35.190.0,34.179.0,52.201.1,31.198.0,27.163.0"}
P.entries["quest:670"] = {n="Versunkener Schatz",s="Flottenmeister Seehorn, dessen Schiffe nicht aus Beutebucht auslaufen können, bis sie ihre Vorräte aufgestockt haben, bittet Euch, einen geheimen Brief zu Shakes O'Breen zu bringen, der vor der Küste des Arathihochlands beschäftigt ist.",h="Flottenmeister Seehorn, dessen Schiffe nicht aus Beutebucht auslaufen können, bis sie ihre Vorräte...",kw={"arathihochland","blackwater raiders","beutebucht","flottenmeister seehorn","seehorns versiegelter brief","shakes o'breen","versunkener schatz"},sec={{t="Ein Brief für O'Breen",b="Flottenmeister Seehorn schätzt Euch als abenteuerlustigen Schlag Mensch ein. Seine Schiffe können Beutebucht nicht verlassen, bis sie ihre Vorräte aufgestockt haben, und er sagt, dass sich sowohl hier als auch in der Ferne schwere Dinge zusammenbrauen. Er muss streng geheime Korrespondenz zu Shakes O'Breen vor der Küste des Arathihochlands bringen lassen und fragt, ob er darauf vertrauen kann, dass Ihr die Nachricht sicher und vertraulich überbringt."}},faq={{q="Wer schickt Euch aus, um diesen Brief zu überbringen?",a="Flottenmeister Seehorn in Beutebucht gibt Euch einen versiegelten Brief für Shakes O'Breen.",al={"wer gibt versunkener schatz 5","wer startet diese quest","seehorns brief questgeber"}},{q="Warum überbringt Flottenmeister Seehorn den Brief nicht selbst?",a="Seine Schiffe können Beutebucht nicht verlassen, bis sie ihre Vorräte aufgestockt haben.",al={"warum seehorn beutebucht nicht verlassen kann","warum flottebmeister seehorn festsitzt"}},{q="Wo befindet sich Shakes O'Breen?",a="Vor der Küste des Arathihochlands, wo er laut Seehorn beschäftigt ist.",al={"wo man shakes o'breen findet","shakes o'breen standort","wo ist shakes"}},{q="Was ging dieser Übergabe voraus?",a="Es folgt auf den vierten Teil von Sunken Treasure.",al={"versunkener schatz questreihe","welche quest kommt vor versunkener schatz 5"}}},fp="15,160,20.346.0,37.79.0,60.63.0,32.69.0,31.46.0"}
P.entries["quest:671"] = {n="Elende Magien",s="Foul Magics ist eine Quest der Horde, die ihren Ursprung in Hammerfall im Arathihochland hat. Tor'gan spürt eine beunruhigende dämonische Präsenz im Westen und entdeckt auf Nordhof Spuren dunkler Beschwörungsrituale. Er bittet Abenteurer darum, sich zum Gutshof zu wagen und Blutsteinamulette zu beschaffen, die bei diesen Beschwörungen verwendet wurden, damit er deren dunkle Magie studieren kann.",h="Foul Magics ist eine Quest der Horde, die ihren Ursprung in Hammerfall im Arathihochland hat.",kw={"arathihochland","blutstein","blutsteinamulett","dämonenbeschwörung","üble magie","hammerfall","nordhof","tor'gan"},ang={["class:Warlock"]="Hexenmeister sind mit den Ritualen und den bindenden Reagenzien, die zur Beschwörung von Dämonen erforderlich sind, bestens vertraut, was die auf Nordhof gefundenen Blutsteinamulette zu Gegenständen von besonderem Interesse macht.",["faction:Horde"]="Da Hammerfall als einziger Außenposten der Horde im Arathihochland dient, stellt die Anwesenheit finsterer Beschwörer, die unmittelbar westlich davon agieren, eine direkte Bedrohung für die Sicherheit der Siedlung dar.",["race:Orc"]="Orcs blicken auf eine lange, schmerzhafte Geschichte mit dämonischer Verderbnis zurück, und verbleibende Teufelsmagie kann ihr Blut sprichwörtlich zum Kochen bringen sowie unnatürliche Wut entfachen. Tor'gans instinktive Reaktion in der Nähe von Nordhof verdeutlicht die anhaltende Empfindlichkeit, die Orcs gegenüber Dämonenbeschwörungen teilen."},sec={{t="Eine brodelnde Wut",b="Tor'gan, ein im Außenposten Hammerfall der Horde stationierter Orc, bemerkte eine beunruhigende Störung, die durch das Arathihochland zog. Für einen Orc sind dämonische Energien nicht bloß eine abstrakte Bedrohung; sie rufen eine instinktive, biologische Reaktion hervor, die in der Geschichte des Blutfluchs wurzelt. Als Tor'gan die Quelle seiner Unruhe nach Westen in Richtung Nordhof verfolgte, brachte die umgebende Verderbnis sein Blut zum Kochen und schürte eine unwillkürliche Wut in ihm. Er erkannte die unverkennbaren Nachwirkungen einer Dämonenbeschwörung und zog sich zurück, ehe der dunkle Einfluss seine Sinne überwältigen konnte, um Hilfe von außerhalb zu suchen, anstatt selbst zurückzukehren."},{t="Die Blutsteinamulette",b="Auf Nordhof entdeckte Tor'gan handfeste Beweise für dunkle Rituale: ein aus Blutstein geschnitztes Amulett, das auf dem Boden lag. Diese magischen Amulette werden aktiv genutzt, um dämonische Beschwörungsrituale zu erleichtern und zu stabilisieren. Das konkrete Amulett, das Tor'gan bergen konnte, war in seinen magischen Reserven bereits erschöpft, was eine gründliche magische Analyse unmöglich machte. Um das volle Ausmaß der Beschwörung zu untersuchen und festzustellen, welche Wesenheiten herbeigerufen wurden, beauftragt er Reisende der Horde damit, sich nach Nordhof zu begeben, um zehn intakte Blutsteinamulette von den dort ansässigen Ausübenden zu beschaffen."}},faq={{q="Wer vergibt die Quest Foul Magics?",a="Die Quest wird von Tor'gan angeboten, einem Orc in Hammerfall, der Festung der Horde im Arathihochland. Tor'gan spürt eine beunruhigende dämonische Präsenz in der Nähe und bittet Abenteurer darum, Nordhof zu untersuchen, um herauszufinden, welche finsteren Mächte am Werk sind.",al={"questgeber für üble magie","wer startet üble magie","tor'gan quest arathi"}},{q="Wo liegt Nordhof?",a="Nordhof liegt westlich von Hammerfall in den nördlichen Hügeln des Arathihochlands. Einst ein Gehöft der Menschen, ist das Anwesen zu einer Stätte heimlicher Dämonenbeschwörungen mithilfe von Blutsteinamuletten geworden.",al={"standort von nordhof","wo ist nordhof","nordhof arathi finden"}},{q="Wofür werden Blutsteinamulette verwendet?",a="Blutsteinamulette sind magische Foki, die zur Unterstützung von Dämonenbeschwörungsritualen verwendet werden. Tor'gan fand heraus, dass die Ausübenden auf Nordhof diese Steine nutzen, um dunkle Magie zu kanalisieren, auch wenn einzelne Amulette ihre Wirkung verlieren, sobald ihre Kraft während einer Beschwörung entzogen wurde.",al={"was ist ein blutsteinamulett","zweck des blutsteinamuletts","warum blutsteinamulette"}},{q="Warum verspürt Tor'gan in der Nähe von Nordhof Wut?",a="Aufgrund der verbliebenen Energien der Dämonenbeschwörung durchlebt Tor'gan in der Nähe von Nordhof eine heftige körperliche Reaktion. Für Orcs wühlt der Kontakt mit Teufelsmagie die Überreste des Blutfluchs auf, wodurch ihr Blut kocht und unkontrollierbare Wut entfacht wird.",al={"warum tor'gans blut kocht","tor'gan wut nordhof","warum wird tor'gan wütend"}},{q="Warum weigert sich Tor'gan, nach Nordhof zurückzukehren?",a="Tor'gan weigert sich, nach Nordhof zurückzukehren, weil die verbleibende dämonische Macht eine gefährliche Wut in ihm aufrührt. Aus Angst davor, die Kontrolle zu verlieren oder dem verderblichen Einfluss zu erliegen, heuert er fremde Abenteurer an, um die Amulette an seiner statt zu beschaffen.",al={"warum tor'gan nicht nach nordhof geht","warum tor'gan nicht zurückkehrt","warum tor'gan amulette nicht holen kann"}},{q="Wie viele Blutsteinamulette werden benötigt?",a="Tor'gan bittet um zehn Blutsteinamulette von Nordhof. Da das einzelne Amulett, das er auf dem Boden fand, vollkommen entleert war, benötigt er mehrere aufgeladene Exemplare, um die dort stattfindenden Rituale eingehend zu untersuchen und zu verstehen.",al={"wie viele blutsteinamulette","anzahl blutsteinamulette","üble magie anzahl ziele"}},{q="Wer beschwört Dämonen auf Nordhof?",a="Dunkle Gewirkte haben Nordhof eingenommen, um verbotene Dämonenbeschwörungen durchzuführen. Ihre finsteren Rituale und die daraus resultierenden Teufelsrückstände erregten von Hammerfall aus Tor'gans Aufmerksamkeit und veranlassten die Horde dazu, den Gutshof zu untersuchen.",al={"wer ist auf nordhof","wer beschwört dämonen auf nordhof","nordhof kultisten"}}},fp="11,344,16.632.0,22.610.0,32.254.0,33.207.0,37.270.0,48.253.0,53.258.0,39.241.0,43.233.0"}
P.entries["quest:672"] = {n="Mut machen",s="Raising Spirits ist eine Quest der Horde im Arathihochland, bei der Tor'gan versucht, die Lebensgeister eines niedergeschlagenen Orcs namens Gor'mul zu wecken. Als Erzählungen über Orgrimmar und Kriegshäuptling Thrall keine Wirkung zeigen, besinnt sich Tor'gan auf neu wiederentdeckte schamanistische Traditionen, um aus den Augen von Hochlandraptoren ein belebendes Amulett herzustellen.",h="Raising Spirits ist eine Quest der Horde im Arathihochland, bei der Tor'gan versucht, die Lebensgeister eines...",kw={"arathihochland","gor'mul","hammerfall","hochlandraptorenaugen","orgrimmar","raising spirits","schamanismus","thrall","tor'gan"},ang={["class:Shaman"]="Diese Bemühung zeigt, wie die wiederbelebten Schamanentraditionen der Horde angewendet werden, um seelische Wunden und Antriebslosigkeit zu heilen, indem Tiergeister genutzt werden, um den Lebenswillen eines Bruders neu zu entfachen.",["faction:Horde"]="Die Quest spiegelt die mitfühlende Seite von Thralls Horde wider, in der Kameraden an abgelegenen Außenposten wie Hammerfall sich um niedergeschlagene Waffenbrüder kümmern, anstatt sie zu verstoßen.",["race:Orc"]="Viele Veteranen wie Gor'mul leiden nach wie vor unter der Lethargie und Verzweiflung infolge der Internierungslager und des Verlusts ihrer früheren Lebensweise, weshalb es ihnen schwerfällt, Thralls neue Horde anzunehmen."},sec={{t="Ein schweres Herz in Hammerfall",b="Im abgelegenen Außenposten Hammerfall im Arathihochland sehen sich die Orcs Feinden von außen und stillen Kämpfen im Inneren gegenüber. Einer der ihren, Gor'mul, ist in eine tiefe, unerschütterliche Melancholie verfallen. Seine Gefährten versuchten, ihn mit stolzen Erzählungen über Kalimdor, die mächtige Festungsstadt Orgrimmar und die visionäre Führung des jungen Kriegshäuptlings Thrall aufzurichten. Doch keine dieser großen Siege oder fernen Wunder vermochte Gor'muls Schwermut zu durchdringen oder ihm Grund zur Hoffnung zu geben."},{t="Geister der Wildnis",b="In der Erkenntnis, dass bloße Worte gegen Gor'muls Niedergeschlagenheit machtlos sind, wendet sich Tor'gan dem wiederbelebten spirituellen Erbe der Horde zu. Indem er die Augen wilder Hochlandraptoren sammelt, die das Arathihochland durchstreifen, fertigt Tor'gan ein Amulett an, das mit den Geistern der Raubtiere gesegnet ist. Statt auf rohe Gewalt oder Dämonenmacht zu setzen, ruft dieses Ritual die wiederherstellende Kraft der neu angenommenen schamanistischen Traditionen an, in der Hoffnung, dass die Lebensflamme der Bestie den schlummernden Lebenswillen eines Bruders erwecken kann."}},faq={{q="Wer ist Tor'gan?",a="Tor'gan ist ein Orc, der im Außenposten der Horde Hammerfall im Arathihochland stationiert ist. Um einem entmutigten Gefährten namens Gor'mul zu helfen, wendet sich Tor'gan der neu wiederentdeckten schamanistischen Magie der Horde zu, um ein Amulett herzustellen, das das innere Feuer seines Kameraden wieder entfachen kann.",al={"wer ist tor'gan","torgan hammerfall","questgeber raising spirits"}},{q="Wer ist Gor'mul und warum muss er aufgemuntert werden?",a="Gor'mul ist ein in Hammerfall ansässiger Orc, der unter schwerer Niedergeschlagenheit und Lethargie leidet. Trotz der Bemühungen seiner orcischen Gefährten, ihn mit Geschichten über Orgrimmar und Thralls Führung aufzumuntern, vermochte nichts ihn zu bewegen oder seine Lebensgeister zu wecken.",al={"wer ist gormul","warum ist gormul traurig","orc deprimiert hammerfall"}},{q="Warum braucht Tor'gan Hochlandraptorenaugen?",a="Tor'gan nutzt die Augen von Hochlandstreunern und Hochlanddreschern, um ein Schamanenamulett herzustellen. Indem er die Geister dieser wilden Raubtiere kanalisiert, hofft Tor'gan, die ihnen innewohnende Stärke und Beharrlichkeit auf Gor'mul zu übertragen, um dessen Kampfgeist wieder neu zu entfachen.",al={"warum raptorenaugen","amulett aus raptorenaugen","zweck von raptorenaugen"}},{q="Wo findet diese Quest statt?",a="Hammerfall ist der wichtigste Außenposten der Horde im Arathihochland, benannt zu Ehren des ehemaligen Kriegshäuptlings Orgrim Schicksalshammer. Er dient den in den Östlichen Königreichen verbliebenen Orcs als befestigte Zuflucht.",al={"wo liegt hammerfall","standort von hammerfall","orcs im arathihochland"}},{q="Was ist die von Tor'gan erwähnte neu gefundene schamanistische Magie?",a="Während ihrer Zeit unter dämonischer Verderbnis und der darauffolgenden Internierung verloren die Orcs ihre spirituelle Verbindung zu den Elementen und den Geistern der Ahnen. Unter der Führung von Kriegshäuptling Thrall hat die Horde diesen uralten schamanistischen Pfad wiedererlangt und nutzt spirituelle Harmonie statt Dämonenmagie, um ihr Volk zu führen.",al={"schamanenmagie orcs","orc-schamanismus neue horde","warum neue schamanenmagie"}},{q="Welche Geschichten vermochten es nicht, Gor'mul aufzumuntern?",a="Seine Gefährten versuchten, Gor'mul mit großartigen Geschichten über die neue Hauptstadt Orgrimmar jenseits des Meeres in Kalimdor sowie den Heldenmut von Kriegshäuptling Thrall zu inspirieren, der die Rüstung und den legendären Kriegshammer von Orgrim Schicksalshammer führt.",al={"geschichten über thrall","welche geschichten wurden gormul erzählt","orgrimmar geschichten gormul"}}},fp="15,295,27.467.0,19.468.0,15.273.0,48.249.0,43.261.0,33.196.0,63.304.0,40.228.0"}
P.entries["quest:673"] = {n="Elende Magien",s="Tor'gan in Hammerfall ist sich sicher, dass ein mächtiger Hexenmeister innerhalb der Mauern von Stromgarde lebt und ein arkanes Relikt nutzt, um Dämonen in großer Zahl zu beschwören. Im Anschluss an den ersten Teil von Foul Magics schickt er Euch los, um den Hexenmeister zu töten und das Relikt zurückzubringen.",h="Tor'gan in Hammerfall ist sich sicher, dass ein mächtiger Hexenmeister innerhalb der Mauern von Stromgarde...",kw={"arathihochland","blutstein","hammerfall","marez cowl","stromgarde","torgan","hexenmeister"},sec={{t="Ein Hexenmeister in Stromgarde",b="Tor'gan ist sich sicher, dass ein Hexenmeister innerhalb der Mauern von Stromgarde lebt. Hin und wieder nutzt der Hexenmeister ein arkanes Relikt, um schreckliche Dämonen in großer Zahl herbeizurufen. Das Brennen in Tor'gans Blut wächst von Tag zu Tag. Er will, dass der Hexenmeister gefunden und getötet wird und dass jedwedes magische Objekt an dessen Leiche zu ihm gebracht wird, damit er es zerstören und verhindern kann, dass seine Macht das Land verdirbt. Bei dem Hexenmeister handelt es sich um Marez Cowl, und das Objekt ist eine Beschmutzte Blutsteinkugel."},{t="Woran die Kugel erinnert",b="Ist die Kugel erst zerstört, erwartet Tor'gan, dass seine rastlosen Nächte in friedvollen Schlaf übergehen. Ihn erinnert sie an die furchtbare Macht, die Dämonen einst über die Orcs hatten, damals bevor Hellscream sie von ihrem Fluch befreite."}},faq={{q="Wer schickt Euch aus, um den Hexenmeister zu jagen?",a="Tor'gan in Hammerfall schickt Euch nach Stromgarde, um den Hexenmeister zu finden und das magische Objekt an Euch zu nehmen, das dieser bei sich trägt.",al={"wer vergibt foul magics","foul magics questgeber","torgan quest"}},{q="Wo befindet sich der Hexenmeister?",a="Marez Cowl befindet sich innerhalb der Mauern von Stromgarde, außerhalb der Feste selbst und im Westen, wo sie sich hinter einem Gebäude versteckt. Ihr könnt hören, wie sie einen Zauber kanalisiert.",al={"wo ist marez cowl","stromgarde hexenmeister aufenthaltsort","wo man marez cowl findet"}},{q="Welches Relikt sollt Ihr beschaffen?",a="Marez Cowls Beschmutzte Blutsteinkugel, der magische Gegenstand, von dem Tor'gan will, dass er ihm gebracht wird, damit er ihn zerstören kann.",al={"welchen gegenstand will torgan","beschmutzte blutsteinkugel","foul magics gegenstand"}},{q="Warum will Tor'gan, dass der Hexenmeister aufgehalten wird?",a="Der Hexenmeister hat schreckliche Dämonen in großer Zahl beschworen. Tor'gan möchte, dass die Quelle dieser Macht beseitigt und die Kugel zerstört wird, damit sie das Land nicht länger verdirbt.",al={"warum die kugel zerstören","torgan motivation","warum den hexenmeister aufhalten"}}},fp="11,250,23.445.0,20.205.1,34.107.0,29.149.0,36.107.0,42.167.0"}
P.entries["quest:674"] = {n="Mut machen",s="„Raising Spirits“ ist eine Horde-Quest, bei der der Kampfeswille von Gor'mul, einem gebrochenen Krieger, der von Verzweiflung erfüllt ist, neu entfacht werden soll. Ein Abgesandter überbringt ein Raptorkrallen-Amulett in der Hoffnung, den wilden Geist zu wecken, den Gor'mul einst besaß. Doch Gor'mul bleibt verbittert und fragt sich, ob ein einfacher Glücksbringer jemals seinen Kummer lindern oder der Horde zu altem Ruhm verhelfen könnte.",h="„Raising Spirits“ ist eine Horde-Quest, bei der der Kampfeswille von Gor'mul, einem gebrochenen Krieger, der...",kw={"gor'mul","gormul","horde","raising spirits","raptor amulett","raptorkrallen-amulett","krieger"},ang={["class:Warrior"]="Diese Aufgabe konzentriert sich darauf, den erloschenen Kriegergeist in einem Orc neu zu entfachen, der von Verzweiflung und Trauer über einen feigen Schlag gelähmt ist.",["faction:Horde"]="Gor'mul trauert um die verlorene Macht der Horde und fragt sich, ob ein einfacher Glücksbringer der Fraktion jemals zu ihrem verlorenen Ruhm verhelfen könnte."},sec={{t="Ein Funke für eine erloschene Flamme",b="Bei „Raising Spirits“ soll einem Orc namens Gor'mul ein Raptorkrallen-Amulett überbracht werden. Seine Verbündeten hoffen, dass die wilde Kraft und Grausamkeit der Raptoren, die durch das Amulett geleitet wird, die Flamme des Kriegers neu entfacht, die einst heftig in seinen Adern brannte."},{t="Verbitterung und Verzweiflung",b="Als Gor'mul das Amulett erhält, bringt er nur bitteren Kummer zum Ausdruck. Gequält von der Erinnerung daran, wie die mächtigsten Champions von feigen Händen niedergestreckt wurden, weist er das Geschenk als bloß polierten Knochen zurück und fragt, wie irgendein Glücksbringer der Horde zu ihrem einstigen Ruhm verhelfen könnte."}},faq={{q="Was ist Raising Spirits?",a="„Raising Spirits“ ist eine Quest, bei der einem verzweifelten Krieger namens Gor'mul ein Raptorkrallen-Amulett überbracht werden soll, um seinen Kampfesgeist neu zu entfachen.",al={"was ist raising spirits","raising spirits quest"}},{q="Wer ist Gor'mul?",a="Gor'mul ist ein gebrochener Krieger, der der Verzweiflung anheimgefallen ist, nachdem er mitansehen musste, wie die mächtigsten Champions durch die Hand eines Feiglings fielen. Er tut Glücksbringer als bedeutungslos ab und stellt die Zukunft der Horde infrage.",al={"wer ist gormul","gor mul"}},{q="Warum wird Gor'mul das Raptorkrallen-Amulett gebracht?",a="Das Raptorkrallen-Amulett ist aus poliertem Knochen und Raptorkrallen gefertigt. Es wird in der Hoffnung überreicht, dass die natürliche Kraft und Grausamkeit der Raptoren Gor'muls innere Flamme wieder entfachen kann.",al={"warum amulett bringen","wozu dient das raptorkrallen-amulett"}},{q="Warum ist Gor'mul verzweifelt?",a="Gor'mul hat jede Hoffnung verloren, nachdem er gesehen hat, wie die mächtigsten Krieger durch feiges Handeln getötet wurden. Diese Tragödie überzeugte ihn davon, dass Ehre und Stärke leicht ausgelöscht werden können, und brach seinen Kampfeswillen.",al={"warum ist gormul traurig","warum ist gormul deprimiert"}},{q="Wie reagiert Gor'mul auf das Amulett?",a="Gor'mul weist das Geschenk zurück und tut das Amulett verbittert als bloß polierten Knochen ab, der unmöglich die Horde wiederherstellen oder die von ihm beklagte Tragödie rückgängig machen kann.",al={"mag gormul das amulett","gormul reaktion"}},{q="Was sagt Gor'mul über die Horde?",a="Gor'mul zweifelt offen daran, dass die Horde jemals ihren einstigen Ruhm zurückerlangen kann. Er sieht wenig Hoffnung, wenn niederträchtiger Verrat selbst die größten Helden niederstrecken kann.",al={"kann die horde wiederhergestellt werden","gormul ruhm der horde"}}},fp="15,352,26.256.0,22.267.1,24.153.0,15.193.0,50.187.0,26.191.0,37.149.0,38.155.0"}
P.entries["quest:675"] = {n="Mut machen",s="Raising Spirits ist eine Quest der Horde, die sich mit dem anhaltenden seelischen Trauma eines alten Orcveteranen befasst. Unter der Führung von Tor'gan versucht ein Schamane, den verbitterten Gor'mul mithilfe uralter Ahnenmagie zu erreichen, um dessen verlorenen Stolz und Lebenswillen wiederherzustellen.",h="Raising Spirits ist eine Quest der Horde, die sich mit dem anhaltenden seelischen Trauma eines alten...",kw={"amulett","gor'mul","gnade","orc","raising spirits","schamane","tor'gan","veteran","kriegshaeuptling"},ang={["class:Shaman"]="Diese Aufgabe veranschaulicht den wiederherstellenden und spirituellen Zweck des modernen Schamanismus der Orcs, der ermächtigte Relikte nutzt, um anhaltende Traumata unter gebrochenen Veteranen heilen zu helfen.",["faction:Horde"]="Unter Thralls Führung versucht die Horde aktiv, verbitterte Veteranen wieder einzugliedern und aufzurichten, anstatt sie der Verzweiflung zu überlassen.",["race:Orc"]="Gor'mul verkörpert die tiefe spirituelle Niedergeschlagenheit und Schmach, die alte Veteranen empfinden, denen das verwehrt blieb, was sie als ehrenhaften Tod an der Seite ihres früheren Kriegshäuptlings betrachteten."},sec={{t="Ein gebrochener Geist",b="Nach vergangenen Kriegen kämpfen viele orcische Veteranen mit den Lasten des Überlebens und vermeintlicher Schande. Gor'mul ist ein solcher Krieger, der in bitterer Mutlosigkeit dahinsiecht, weil ihm verwehrt blieb, was er als ehrenhaften Tod an der Seite seines gefallenen Kriegshäuptlings betrachtet. Tor'gan, ein einfühlsamer Schamane, versucht Gor'muls Leiden zu lindern, indem er ihn an die spirituelle Stärke seines Volkes erinnert. Im Glauben daran, dass die Energien der Ahnen seelische Wunden heilen können, bereitet Tor'gan ein verzaubertes Amulett vor, das den Stolz des alten Kämpfers neu entfachen soll."},{t="Die Grenzen des Amuletts",b="Als der Talisman Gor'mul überreicht wird, verfehlt er die gewünschte Wirkung. In einem Ausbruch von Groll schleudert Gor'mul das Amulett in den Staub und fragt sich, warum ihm überhaupt jemand Gnade erweisen sollte, wenn das Schicksal ihm ein ehrenvolles Ende verwehrt hat. Tor'gan nimmt diesen Rückschlag gelassen hin, wohl wissend, dass ein einzelner Talisman nicht die Macht besaß, Jahre tief sitzender Trauer zu überwinden. Dennoch hält der Schamane unbeirrt an seiner Mission fest, fest entschlossen, dass das aufstrebende Wirken des Schamanismus Gor'mul letztlich zu seiner einstigen Ehre zurückführen wird."}},faq={{q="Wer ist Gor'mul?",a="Gor'mul ist ein verbitterter Orcveteran, der von Trauer und Überlebensschuld verzehrt wird. Da er die Konflikte der älteren Horde überlebt hat, als sein Kriegshäuptling fiel, betrachtet er das Weiterleben als grausame Fügung des Schicksals und lehnt herkömmliches Mitgefühl ab.",al={"wer ist gormul","gormuls hintergrundgeschichte","was fehlt gormul"}},{q="Wer ist Tor'gan und warum hilft er Gor'mul?",a="Tor'gan ist ein Schamane, der versucht, Gor'mul aus seiner bitteren Verzweiflung zu befreien. Im Glauben daran, dass die Rückbesinnung auf die Pfade der Ahnen gebrochene Seelen heilen kann, fertigt Tor'gan erfüllte Talismane, um ehemalige Krieger an die spirituelle Wiedergeburt ihres Volkes zu erinnern.",al={"wer ist torgan","was will torgan","torgans ziel"}},{q="Was war der Zweck des Amuletts?",a="Das Amulett war ein verzauberter Talisman, den Tor'gan vorbereitet hatte, um Gor'muls Kriegergeist durch schamanische Energie wiederzuerwecken. Als man es Gor'mul überreichte, lehnte er es ab und warf es zu Boden, da er der Ansicht war, seine Magie reiche nicht aus, um seine tiefe Verbitterung zu vertreiben.",al={"was ist das amulett","warum warf gormul das amulett weg","hat das amulett gewirkt"}},{q="Um welchen Kriegshäuptling trauert Gor'mul?",a="Obwohl Gor'mul das Schicksal dafür verflucht, ihm den Tod an der Seite seines Kriegshäuptlings in der Schlacht verwehrt zu haben, nennt er ihn nicht namentlich. Seine Worte spiegeln die tragische Perspektive der besiegten Überreste der alten Horde wider, die sich nach einem ehrenhaften Tod auf dem Schlachtfeld sehnten.",al={"welcher kriegshaeuptling starb","wer war gormuls kriegshaeuptling","wem diente gormul"}},{q="Was plant Tor'gan zu tun, nachdem das Amulett versagt hat?",a="Tor'gan bleibt trotz des anfänglichen Fehlschlags geduldig. Er erkennt an, dass das Amulett allein nicht mächtig genug war, vertraut aber weiterhin darauf, dass die Demonstration der wahren Macht des Schamanismus Gor'muls verlorenen Stolz letztendlich wieder entfachen wird.",al={"gibt torgan auf","was geschieht nach geister wecken","wird sich gormul erholen"}},{q="Warum nutzt Tor'gan Schamanismus, um Gor'mul zu helfen?",a="Dieses Bemühen unterstreicht die entscheidende Rolle der Schamanen innerhalb der New Horde als spirituelle Heiler, die nicht bloß daran arbeiten, die Elemente für den Krieg zu kanalisieren, sondern auch den verwundeten Geist und den Stolz ihres Volkes zu pflegen.",al={"was zeigt dies ueber schamanen","warum hier schamanenmagie nutzen"}}},fp="15,250,15.528.0,24.526.1,15.228.0,45.242.0,35.254.0,34.238.0,52.232.0,47.200.0"}
P.entries["quest:676"] = {n="Der Hammer kann fallen",s="Von Tallow aus Tarrens Mühle entsandt, werden Champions der Horde über das Gebirge ins Arathihochland geschickt, um der bedrängten Siedlung Hammerfall beizustehen. Bevor sie sich bei Drum Teufel melden, müssen Abenteurer ihre Kampfbereitschaft gegen die brutalen Oger der Felsfäuste beweisen, die nahe den Ruinen von Stromgarde lauern.",h="Von Tallow aus Tarrens Mühle entsandt, werden Champions der Horde über das Gebirge ins Arathihochland...",kw={"arathihochland","vollstrecker der felsfäuste","oger der felsfäuste","drum teufel","hammerfall","vorgebirge des hügellands","stromgarde","tallow","tarrens mühle","der hammer kann fallen"},ang={["class:Warrior"]="Sich den hünenhaften Vollstreckern der Felsfäuste zu stellen, dient als klassische Bewährungsprobe für Frontkämpfer, die sich den Respekt erfahrener Orckommandanten wie Drum Teufel verdienen wollen.",["faction:Horde"]="Diese Aufgabe markiert den entscheidenden Übergang von den lokalen Streitigkeiten in Hillsbrad zur weiträumigeren Verteidigung des Arathihochlands und stärkt Hammerfalls lebenswichtigen Stützpunkt in der Region.",["race:Orc"]="Hammerfall besitzt für Orcs einen tiefen emotionalen und historischen Wert, da es an dem Ort gegründet wurde, an dem Kriegshäuptling Orgrim Schicksalshammer während der Befreiungsfeldzüge sein Leben ließ."},sec={{t="Ein schroffer Ruf zu den Waffen",b="In Tarrens Mühle hat Tallow wenig Geduld für unerprobte Abenteurer, die durch das Vorgebirge streifen. Da er sieht, wie undisziplinierte Rekruten untätig herumstehen, während entfernte Verbündete verbluten, schickt er fähige Kämpfer ostwärts durch den Thoradinswall ins Arathihochland. Der Hordenaußenposten Hammerfall wird an mehreren Fronten belagert, doch Tallow weigert sich, bloßes Kanonenfutter zu schicken, solange sie ihren Wert nicht zuerst gegen erheblichen Widerstand bewiesen haben."},{t="Prüfung durch die Felsfäuste",b="Statt Rekruten blindlings nach Hammerfall stolpern zu lassen, verlangt Tallow einen Beweis ihrer kriegerischen Stärke am Ogerhügel nordöstlich von Stromgarde. Der Stamm der Felsfäuste unterhält eine starke Präsenz im Arathihochland; seine massigen Oger und Vollstrecker stellen eine unmittelbare Bedrohung für jeden dar, der die Hochlandpfade bereist. Das Erschlagen dieser Rohlinge dient sowohl dazu, die feindlichen Kräfte an den Flanken der Straße auszudünnen, als auch sicherzustellen, dass nur fähige Krieger am Außenposten eintreffen."},{t="Meldung in Hammerfall",b="Nachdem das Lager der Felsfäuste gesäubert wurde, führt der Pfad nach Nordosten nach Hammerfall, einem Außenposten, der im Gedenken an Kriegshäuptling Orgrim Schicksalshammer benannt wurde. Dort empfängt Kommandant Drum Teufel Neuankömmlinge mit kühler Skepsis. Ob Tallow nun die Garnison verstärken oder einfach Narren in den Tod schicken wollte – Drum Teufel verliert keine Zeit und setzt die bewährten Kämpfer unverzüglich in den endlosen Scharmützeln ein, die das Überleben des Außenpostens bedrohen."}},faq={{q="Wo beginnt und endet diese Quest?",a="Die Quest wird von Tallow in Tarrens Mühle im Vorgebirge des Hügellands angeboten. Nachdem die erforderlichen Tötungen im Arathihochland abgeschlossen sind, wird sie bei Drum Teufel im Hordenaußenposten Hammerfall abgegeben.",al={"wo starte ich der hammer kann fallen","abgabeort der quest","wer vergibt der hammer kann fallen"}},{q="Wo befinden sich die Oger der Felsfäuste?",a="Die Oger der Felsfäuste bewohnen einen markanten Erdhügel samt umliegendem Lager nordöstlich der Ruinen von Stromgarde im Arathihochland.",al={"standort oger der felsfäuste","wo sind die oger in arathi","hügel der felsfäuste"}},{q="Was ist der Außenposten Hammerfall?",a="Hammerfall ist eine befestigte Hordensiedlung im nordöstlichen Arathihochland. Sie ist zu Ehren des früheren Kriegshäuptlings Orgrim Schicksalshammer benannt, der ganz in der Nähe während der Befreiung der Internierungslager der Orcs im Kampf fiel.",al={"was ist hammerfall","lore zu hammerfall","wer gründete hammerfall"}},{q="Warum lässt Tallow einen gegen Oger kämpfen, bevor man sich in Hammerfall meldet?",a="Hammerfall steht unter ständigem Angriff und benötigt dringend fähige Kämpfer. Tallow schickt Rekruten als harte Bewährungsprobe gegen die Oger der Felsfäuste, um sicherzustellen, dass jeder, der zur Verstärkung von Drum Teufel eintrifft, auch tatsächlich kämpfen kann und nicht zu einer zusätzlichen Last wird.",al={"warum zuerst oger töten","tallows beweggrund","warum werde ich geprüft"}},{q="Wer ist Drum Teufel?",a="Drum Teufel ist ein erfahrener Orckrieger und Kommandant in Hammerfall im Arathihochland, der damit beauftragt ist, die Verteidigung gegen feindliche Wildtiere, Oger, Trolle und Überreste der Allianz zu organisieren.",al={"wer ist drum teufel","kommandant von hammerfall"}},{q="Was folgt auf diesen Auftrag?",a="Die Meldung bei Drum Teufel führt direkt in die Kampagne „Zu den Waffen!“, eine Reihe militärischer Operationen mit dem Ziel, umliegende Bedrohungen zu beseitigen – darunter die Trollstämme der Bleichborken, die das Hochland bedrohen.",al={"folgequest","nachfolgequest der hammer kann fallen","was kommt danach"}}},fx={b3b0715a={q="Wer sind die Boulderfist-Oger, gegen die Ihr ausgesandt werdet?",a="Der Boulderfist-Stamm ist ein brutaler Ogerclan, der im Arathihochland Territorium beansprucht, mit dem Schwerpunkt um ihren Hügel nordöstlich der Ruinen von Stromgarde. Wild, stur und körperlich imposant, beherrschen sie die felsigen Hügel des Hochlands und streitig gemachte Gebiete in der Umgebung. Tallow schickt Euch zu ihrem Hügel, um zu sehen, ob Ihr gegen ihre Vollstrecker an der Front bestehen könnt, um sicherzustellen, dass Ihr die notwendige Stärke besitzt, bevor Ihr Euch in den Fleischwolf der Arathi-Kriegszone werft.",al={"boulderfist oger","wer sind boulderfist","oger arathi"}}},fp="19,317,15.441.0,20.463.0,23.415.1,36.207.0,40.143.0,34.212.0,68.259.0,16.198.0,29.206.0"}
P.entries["quest:677"] = {n="Zu den Waffen",s="Call to Arms ist eine militärische Initiative der Horde, die von Drum Teufel vom Außenposten Hammerfall im Arathihochland geleitet wird. Bedroht von einer Allianz zwischen den einheimischen Waldtrollen der Witherbark und den Oger der Boulderfist, startet die Horde einen Präventivschlag gegen die Witherbark, um ihren Stützpunkt in der Region zu sichern.",h="Call to Arms ist eine militärische Initiative der Horde, die von Drum Teufel vom Außenposten Hammerfall im...",kw={"arathihochland","axtwerfer","boulderfist","zu den waffen","drum teufel","hammerfall","kopfjaeger","hexendoktor","witherbark"},ang={["faction:Horde"]="Hammerfall steht isoliert im Arathihochland, umgeben von feindlichen Kräften; die Verteidigung des Außenpostens gegen aggressive einheimische Fraktionen ist unerlässlich, um einen dauerhaften Stützpunkt der Horde in von Menschen beherrschten Ländern zu sichern.",["race:Orc"]="Erbaut auf dem Gelände eines ehemaligen Internierungslagers aus dem Zweiten Krieg, ist Hammerfall ein Symbol der Befreiung für Orcs, was die Verteidigung ihrer neuen Siedlung gegen feindselige Nachbarn zu einer zutiefst persönlichen Angelegenheit macht.",["race:Troll"]="Für Dunkelspeertrolle, die Thralls Horde dienen, unterstreicht der Kampf gegen die feindlichen Waldtrolle der Witherbark die tiefe Kluft zwischen ihrem Volk und jenen Stämmen, die The New Horde ablehnten."},sec={{t="Verteidigung von Hammerfall",b="Vom befestigten Zufluchtsort Hammerfall aus organisiert Drum Teufel einen militärischen Präventivschlag gegen die feindlichen einheimischen Mächte des Arathihochlands. Umgeben von alten Ruinen der Menschen und aggressiven lokalen Fraktionen sieht sich die Siedlung der Horde einer drohenden Gefahr durch einen Pakt zwischen den einheimischen Waldtrollen der Witherbark und den brutalen Ogern der Boulderfist gegenüber. Anstatt zuzulassen, dass ihre Feinde die Bedingungen für ihr Überleben diktieren, ruft Drum Teufel Streiter dazu auf, in die Offensive zu gehen."},{t="Die Bedrohung durch die Witherbark",b="Die anfängliche Offensive konzentriert sich auf den Süden von Hammerfall und zielt auf das Herz des Territoriums der Witherbark ab. Die Witherbark haben jeglicher Diplomatie den Rücken gekehrt und sich stattdessen entschieden, sich mit den Ogern der Boulderfist zu verschwören, um die Horde aus dem Hochland zu vertreiben. Durch das Dezimieren ihrer spezialisierten Axtwerfer, Kopfjäger und Hexendoktoren versucht Hammerfall, ihre militärische Führung zu zerschlagen und zu beweisen, dass die Horde gekommen ist, um zu bleiben."}},faq={{q="Wer bietet die Quest Call to Arms an?",a="Call to Arms wird von Drum Teufel vergeben, einem Orc, der am Außenposten der Horde Hammerfall im nordöstlichen Arathihochland stationiert ist. Er koordiniert Verteidigungs- und Angriffsschläge, um das Überleben des Lagers gegen Bedrohungen aus der Nachbarschaft zu sichern.",al={"wer gibt zu den waffen","wo ist drum teufel","questgeber zu den waffen"}},{q="Warum nimmt Hammerfall die Witherbarktrolle ins Visier?",a="Der Stamm der Witherbark-Waldtrolle hat sich mit den Ogern der Boulderfist verbündet, um die Horde aus dem Arathihochland zu vertreiben. Da sie eine friedliche Koexistenz ablehnten und der Horde den Rücken kehrten, lässt ihre aggressive Haltung Hammerfall keine andere Wahl, als zuerst zuzuschlagen.",al={"warum witherbark toeten","warum trolle im arathi angreifen","was haben die witherbark getan"}},{q="Wo befinden sich die Witherbarktrolle?",a="Die Witherbarktrolle bewohnen mehrere Siedlungen und Lager südlich von Hammerfall im Arathihochland, darunter tief im Inneren von Witherbark nahe den Bergen.",al={"wo sind witherbarktrolle","witherbark lager standort","wo axtwerfer im arathi finden"}},{q="Welche Rolle spielen die Oger der Boulderfist in diesem Konflikt?",a="Die Oger der Boulderfist sind ein brutaler Clan, der im Arathihochland ansässig ist. Laut Drum Teufel sind sie ein Zweckbündnis mit den Witherbarktrollen eingegangen, um die Präsenz der Horde im Hochland auszulöschen.",al={"wer sind die boulderfist","oger im arathihochland","boulderfist troll allianz"}},{q="Was ist Hammerfall und warum muss es verteidigt werden?",a="Hammerfall ist der wichtigste Außenposten der Horde im Arathihochland, benannt zum Gedenken an Kriegshäuptling Orgrim Schicksalshammer. Errichtet auf dem Gelände eines ehemaligen Internierungslagers der Allianz, dient es als hart erkämpfter Zufluchtsort und militärische Bastion für die Horde in den Östlichen Königreichen.",al={"was ist hammerfall","hammerfall lore","warum ist die horde im arathi"}},{q="Sind die Witherbarktrolle Teil der Horde?",a="Nein. Während die Dschungeltrolle des Darkspear tribe Mitglieder der Horde sind, handelt es sich bei den Witherbark um in den Östlichen Königreichen beheimatete Waldtrolle. Sie hegen tiefe Feindseligkeit gegenüber Außenstehenden und haben jegliche Annäherungsversuche der Horde gewaltsam zurückgewiesen.",al={"gehoeren die witherbark zur horde","sind waldtrolle der horde freundlich gesinnt","dunkelspeer gegen witherbark"}}},fp="12,316,20.489.0,21.423.0,34.241.0,50.275.0,40.173.0,57.220.0,50.262.0,44.243.0"}
P.entries["quest:678"] = {n="Zu den Waffen",s="Call to Arms ist eine kriegerische Prüfung der Horde, die von Drum Teufel im Außenposten Hammerfall im Arathihochland ausgegeben wird. Nachdem sie ihre grundlegende Kampfbereitschaft unter Beweis gestellt haben, werden Abenteurer nach Südwesten zur Zwergenbrücke geschickt, um die gefährlichen Boulderfist-Oger anzugreifen. Das Ausschalten von Raufbolden an vorderster Front sowie zauberwirkenden Magiern stellt die Entschlossenheit des Kriegers auf die Probe und schützt gleichzeitig den verwundbaren Stützpunkt der Horde in Arathi.",h="Call to Arms ist eine kriegerische Prüfung der Horde, die von Drum Teufel im Außenposten Hammerfall im...",kw={"arathihochland","boulderfist","boulderfist-raufbold","boulderfist magi","call to arms","drum teufel","hammerfall","oger","thandol-übergang"},ang={["class:Mage"]="Die Konfrontation mit Boulderfist Magi ermöglicht es Magiern, Zauberwirkern mit roher Gewalt entgegenzutreten, die arkane Energien für primitive, zerstörerische Zwecke nutzen.",["class:Warrior"]="Drum Teufels Forderung nach Zähigkeit gegenüber roher Gewalt und arkaner Macht stellt für Krieger eine direkte Prüfung der Kampfausdauer und der kriegerischen Ehre dar.",["faction:Horde"]="Die Sicherung von Hammerfall ist überaus wichtig für den Stützpunkt der Horde in den Östlichen Königreichen, und das Dezimieren der aggressiven Boulderfist-Oger bewahrt den Außenposten davor, überrannt zu werden.",["race:Orc"]="Hammerfall ist nach Kriegshäuptling Orgrim Schicksalshammer benannt, was den Orcs ein zutiefst persönliches Anliegen verleiht, jeden rivalisierenden Raufbold zu vertreiben, der diese Gedenkfestung bedroht."},sec={{t="Eine Zerreißprobe",b="In der abgelegenen Feste der Horde von Hammerfall verlangt das Überleben unerschütterliche kriegerische Stärke. Da Drum Teufel die wachsenden Fähigkeiten der Reisenden erkennt, die dem Außenposten beistehen, weigert er sich, irgendjemanden auf leichten Siegen ausruhen zu lassen. Statt sich unbedeutenden Scharmützlern zu stellen, müssen Krieger ihren Mut gegen das beweisen, was Teufel als echte Bedrohung ansieht: die massigen Boulderfist-Oger. Diese Raufbolde haben die Expedition der Horde fortwährend bedrängt und die Entschlossenheit der Verteidiger von Hammerfall geprüft. Teufel stellt einfache Bedingungen für die Aufgabe: Von den Kriegern wird erwartet, dass sie entweder leibhaftig siegreich oder ehrenvoll im Geiste zurückkehren, wobei für schiere Zähigkeit im Kampf Lob versprochen wird."},{t="Die Boulderfist-Bedrohung",b="Der Boulderfist-Klan hat südwestlich von Hammerfall einen befestigten Unterschlupf errichtet und sein Territorium in Richtung der großen Zwergenbrücke ausgedehnt, die Arathi mit dem Sumpfland verbindet. Anders als undisziplinierte Bestien verfügen die Oger sowohl über vernichtende körperliche Kraft als auch über tödliche mystische Künste und setzen widerstandsfähige Raufbolde an der Seite gerissener Magier ein. Ihre aggressive Präsenz stellt eine direkte Herausforderung für die Versorgungslinien und die regionale Vorherrschaft der Horde dar. Indem Drum Teufel die Vernichtung von zehn Boulderfist-Raufbolden und vier Magiern anordnet, will er ihre Stärke brechen und sicherstellen, dass die Boulderfists verstehen, dass die Krieger von Hammerfall im Arathihochland weder weichen noch Rivalen dulden werden."}},faq={{q="Wer vergibt die Quest „Call to Arms“?",a="Die Quest wird von Drum Teufel angeboten, einem Offizier, der im befestigten Horde-Außenposten Hammerfall im nordöstlichen Arathihochland stationiert ist. Auf der Suche nach fähigen Streitern zum Schutz der fragilen Position der Festung beauftragt Teufel erprobte Kämpfer damit, gegen gefährliche regionale Widersacher vorzugehen, um ihre kriegerische Disziplin und rohe Stärke zu demonstrieren.",al={"wer vergibt call to arms","drum teufel quest","questgeber call to arms"}},{q="Wo befindet sich der Unterschlupf der Boulderfists?",a="Die Ogersiedlung der Boulderfists liegt südwestlich von Hammerfall am Pfad, der zum Thandol-Übergang führt, der großen Zwergenbrücke zum Sumpfland. Die Oger bewohnen Erdhöhlen und Erdhügel im Hochland, wo sich sowohl ihre Schläger als auch ihre Zauberwirker in großer Zahl versammeln.",al={"standort der boulderfists","wo sind die oger","boulderfist-unterschlupf arathi"}},{q="Welche Feinde müssen für diese Aufgabe bezwungen werden?",a="Drum Teufel weist Krieger an, zehn Boulderfist Brutes und vier Boulderfist Magi zu eliminieren, bevor sie nach Hammerfall zurückkehren. Die Raufbolde verlassen sich auf wuchtige Nahkampfangriffe, während die Magier sie aus der Ferne mit Arkanzaubern unterstützen, was sie deutlich gefährlicher macht als gewöhnliche Wegelagerer im Arathihochland.",al={"call to arms anzahl der siege","welche oger töten","call to arms ziele"}},{q="Warum gelten die Boulderfist-Oger als Bedrohung für Hammerfall?",a="Die Boulderfists haben einen befestigten Stützpunkt in Arathi errichtet und die Horde-Garnison in Hammerfall wiederholt herausgefordert. Ihre Nähe zu wichtigen Verkehrswegen in Richtung der südlichen Zwergenbrücke bedroht die Aufklärungs- und Nachschublinien der Horde. Drum Teufel betrachtet sie als eine echte rivalisierende Streitmacht, die durch regelmäßige militärische Schläge aktiv eingedämmt werden muss.",al={"warum gegen boulderfists kämpfen","sind boulderfists feindlich gegenüber der horde","ogerbedrohung in arathi"}},{q="Was meint Drum Teufel damit, leibhaftig oder im Geiste zurückzukehren?",a="Drum Teufels düstere Bemerkung spiegelt das kompromisslose Kriegerethos der Horde in Arathi wider. Er erwartet von seinen Kämpfern, dass sie Erfolg haben und lebend zurückkehren, respektiert jedoch jeden, der im tapferen Kampf gegen gewaltige Feinde fällt. In seinen Augen bringt das Zeigen von Zähigkeit und Furchtlosigkeit gegenüber der überwältigenden Stärke der Oger Ehre, unabhängig davon, ob man das blutige Gefecht überlebt.",al={"zitat von drum teufel","bedeutung von im geiste zurückkehren","leibhaftig oder im geiste kommen"}},{q="Können Allianz-Spieler diese Quest annehmen?",a="Nein, dieser Ruf zu den Waffen ist ausschließlich eine Horde-Quest, die von Drum Teufel in Hammerfall vergeben wird. Die Streitkräfte der Allianz operieren von der Zuflucht im Westen aus und betrachten sowohl die Verteidiger von Hammerfall als auch die Boulderfist-Oger als feindlich gesinnte Widersacher, die um die Vorherrschaft über das Arathihochland konkurrieren.",al={"ist call to arms nur für die horde","allianz call to arms arathi","kann die allianz diese quest machen"}},{q="Warum nimmt Drum Teufel sowohl Raufbolde als auch Magier ins Visier?",a="Beide Ogertypen ins Visier zu nehmen, neutralisiert den taktischen Vorteil der Boulderfists im Kampf der verbundenen Waffen. Die Raufbolde bilden die muskulöse Frontlinie, die Schläge abfängt, während die Magier von hinten zerstörerische Magie wirken. Beide Arten zu besiegen, stellt sicher, dass der Klan keine organisierte Gegenoffensive gegen Hammerfall starten kann.",al={"warum magier töten","wichtigkeit der boulderfist magi","boulderfist-raufbold und -magier"}}},fp="12,399,16.642.0,22.661.0,33.356.0,38.307.0,48.306.0,64.356.0,58.370.0,42.275.0,46.307.0"}
P.entries["quest:679"] = {n="Zu den Waffen",s="Im Anschluss an das vorherige Zu den Waffen erklärt Drum Teufel bei Hammerfall, dass es an der Zeit sei, der Bestie den Kopf abzuschlagen. Er schickt Euch hinter den Boulderfist-Lords und -Schamanen her, die in den Ruinen von Stromgarde hausen.",h="Im Anschluss an das vorherige Zu den Waffen erklärt Drum Teufel bei Hammerfall, dass es an der Zeit sei, der...",kw={"arathihochland","boulderfist","boulderfist lords","boulderfist schamanen","drum teufel","hammerfall","stromgarde"},sec={{t="The Head of the Beast",b="Drum Teufel sagt, Ihr hättet Euch als fähig genug erwiesen, um bei einem letzten großen Schlag zu helfen. Diejenigen, die die Angriffe anführen, haben ihr Lager in den Ruinen von Stromgarde aufgeschlagen, die er als Symbol menschlicher Schwäche bezeichnet. Jagt die Boulderfist-Lords und die Schamanen, die ihnen dienen, denn sie würden versuchen, die Horde aus diesen Ländern zu vertreiben."}},faq={{q="Wer schickt Euch aus, um gegen die Anführer der Boulderfist zu kämpfen?",a="Drum Teufel beim Außenposten der Horde Hammerfall im Arathihochland.",al={"wer vergibt zu den waffen","drum teufel quest","wer startet zu den waffen 3"}},{q="Wo befinden sich die Boulderfist-Lords und -Schamanen?",a="Drum Teufel sagt, dass sich diejenigen, die die Angriffe anführen, in den Ruinen von Stromgarde verschanzt haben.",al={"wo sind boulderfist lords","boulderfist schamanen aufenthaltsort","wo man ogre anführer findet"}},{q="Wo fügt sich dieser Schritt in die Reihe ein?",a="Er folgt auf das vorherige Zu den Waffen und ist der letzte Schritt in der Reihe, die mit Talg in Tarrens Mühle beginnt.",al={"was kam vor zu den waffen 3","zu den waffen reihe","hammerfall oger reihe"}},{q="Was soll mit den Anführern der Boulderfist nach Drum Teufels Willen geschehen?",a="Er möchte, dass die Lords und Schamanen, die die Angriffe anführen, als ein letzter schwerer Schlag getötet werden, da sie die Horde aus diesen Ländern vertreiben würden.",al={"warum boulderfist lords töten","warum stromgarde oger angreifen"}}},fp="12,208,21.316.0,47.69.0,51.80.0,40.110.0,56.133.0"}
P.entries["quest:68"] = {n="Die Legende von Stalvan",s="Diese Nachforschung bringt ein vergessenes Kapitel in der düsteren Geschichte von Stalvan Dunstmantel ans Licht. Ein staubiger, ungesendeter Brief aus einer vernachlässigten Fußtruhe in Mondbruch liefert handfeste Beweise dafür, wo er sich aufhielt, bevor seine Spur kalt wurde, und führt zurück zu den Aufzeichnungen von Dunkelhain.",h="Diese Nachforschung bringt ein vergessenes Kapitel in der düsteren Geschichte von Stalvan Dunstmantel ans...",kw={"amtmann daltry","fluch von stalvan","dunkelhain","dämmerwald","staubiger ungesendeter brief","fußtruhe","unglückseliger geist","mistmantle","mondbruch","stalvan"},ang={["class:Mage"]="Der feindselige Schatten, der die Fußtruhe bewacht, nutzt trügerische arkane Werkzeuge wie Verwandlung neben einem lähmenden Fluch, was auf die unnatürlichen Mächte hinweist, die Stalvans Pfad begleiteten.",["class:Priest"]="Die Manifestation eines Unglückseligen Geistes, der an eine einfache Kiste voller Andenken gebunden ist, zeugt von einer qualvollen emotionalen Last, die auch nach dem Tod keine Ruhe fand.",["faction:Alliance"]="Die Enträtselung des Geheimnisses um Stalvan Dunstmantel hilft der gebeutelten Stadt Dunkelhain dabei, die schattenhaften Gestalten zu erfassen, die die Grenzen der Region durchquert haben."},sec={{t="Eine vergessene Spur in Mondbruch",b="Bei der Spurensuche nach Stalvan Dunstmantel bringt eine alte, in Mondbruch versteckte Fußtruhe ein entscheidendes Puzzleteil hervor: einen staubigen, ungesendeter Brief. Mondbruch, einst eine blühende landwirtschaftliche Siedlung, verfiel zu Ruinen und wimmelt nun von Gesetzlosen und rastlosen Gespenstern. Stalvans Anwesenheit hier war kurz genug, um dem Gedächtnis der Allgemeinheit zu entgehen, doch dieses vernachlässigte Schreiben platziert ihn zweifelsfrei in dem Dorf."},{t="Ein Spuk an der Fußtruhe",b="Das Durchwühlen von Stalvans Besitztümern bleibt nicht unbemerkt. Das Öffnen der Truhe lockt einen Unglückseligen Geist aus den Schatten, der entschlossen ist, die zurückgelassenen Geheimnisse zu hüten. Das Gespenst schlägt mit betörender Magie und dem schwächenden Fluch von Stalvan um sich, was darauf hindeutet, dass welches Schicksal den Mann auch immer ereilte, Trauer und dunkle Verzauberung seinen verbliebenen Habseligkeiten schwer anhaften."},{t="Aktualisierung des Stadtregisters",b="Die Überbringung des Briefes über die Grenze nach Dunkelhain liefert Amtmann Daltry die fehlenden Unterlagen, die er benötigt. Obwohl Daltry es seltsam findet, dass der Brief nie verschickt wurde, sind die Beweise unbestreitbar. Da die Verbindung zu Mondbruch bestätigt ist, kann die bürokratische Spur die Nachforschungen schließlich dorthin lenken, wohin Stalvan als Nächstes floh."}},faq={{q="Was befindet sich in der alten Fußtruhe in Mondbruch?",a="In der Fußtruhe liegt ein staubiger, ungesendeter Brief, der während des Aufenthalts von Stalvan Dunstmantel in Mondbruch verfasst wurde. Er dient als greifbarer Beweis für seinen Aufenthalt im Ort, bevor er verschwand.",al={"was habe ich gefunden","inhalt der fußtruhe","stalvans brief"}},{q="Warum greift ein Geist an, wenn die Truhe geöffnet wird?",a="Ein Unglückseliger Geist verweilt nahe Stalvans vergessenen Besitztümern und greift jeden an, der die Truhe stört. Er setzt beunruhigende Magie ein, darunter Furchteffekte, Verwandlungszauber und den anhaltenden Fluch von Stalvan.",al={"unglückseliger geist","warum werde ich angegriffen","geist an der fußtruhe"}},{q="Warum sollte man den Brief zu Amtmann Daltry bringen?",a="Amtmann Daltry verwaltet die städtischen Aufzeichnungen und das Register im Rathaus von Dunkelhain. Er benötigt konkrete Dokumente, um Stalvans frühere Aufenthaltsorte zu bestätigen, bevor er bei der weiteren Nachverfolgung helfen kann.",al={"wer ist amtmann daltry","warum daltry","rathaus von dunkelhain"}},{q="Warum ist es bedeutsam, dass der Brief nie verschickt wurde?",a="Die Tatsache, dass der Brief in einer verlassenen Fußtruhe verstaut und zurückgelassen wurde, deutet auf einen abrupten Aufbruch oder wachsende Paranoia hin und verstärkt die unheimliche Heimlichtuerei um Stalvans Bewegungen.",al={"geheimnis des ungesendeten briefs","warum nicht verschickt"}},{q="Was bewirkt der Fluch von Stalvan?",a="Der Fluch von Stalvan, der von dem Unglückseligen Geist zur Bewachung der Fußtruhe gewirkt wird, ist eine schwächende Verhexung, die zehn Minuten lang alle Hauptattribute seines Opfers verringert.",al={"fluch von stalvan schwächungszauber","fluch des geistes"}},{q="Wohin führt die Spur, nachdem Daltry der Brief übergeben wurde?",a="Sobald Amtmann Daltry das städtische Register mit diesem Beweis aus Mondbruch aktualisiert hat, kann er Eure Nachforschungen auf Stalvans nächsten bekannten Aufenthaltsort lenken.",al={"wie geht es weiter","wohin nach daltry","nächster hinweis"}}},fp="21,277,30.406.0,28.360.1,26.344.0,47.192.0,50.210.0,36.196.0,53.199.0,34.169.0,60.163.0"}
P.entries["quest:680"] = {n="Die echte Bedrohung",s="Im Anschluss an Call to Arms teilt Euch Korin Fel mit, dass ihr Ehemann nicht weiß, warum Hammerfall angegriffen wird, und bittet Euch, den Oger Or'Kalar zu erschlagen und ihr seinen Kopf zu bringen.",h="Im Anschluss an Call to Arms teilt Euch Korin Fel mit, dass ihr Ehemann nicht weiß, warum Hammerfall...",kw={"arathihochland","hammerfall","korin fel","mug'thol","or'kalar","stromgarde","der turm von arathor"},sec={{t="Ein Groll gegen ihren Ehemann",b="Korin Fel sagt, dass Ihr ihrem Ehemann treu dient, er jedoch keine Ahnung hat, warum Hammerfall angegriffen wird. Die Ursache ist Or'Kalar, Mug'thols Marionette in Stromgarde, der ihren Ehemann dafür hasst, dass er ihn vor Jahren besiegt hat, und seinen Tod will. Ihre Vorsehung kündet ihr davon, dass der Oger ihm eine Falle gestellt hat."},{t="Was Korin verbirgt",b="Korin hat die Zeichen der Anwesenheit des Ogers vor ihrem Ehemann verborgen, von dem sie glaubt, dass er unbesonnen losstürmen würde, wenn er wüsste, wo sich Or'Kalar befindet. Stattdessen bittet sie Euch um Hilfe. Ihr werdet Or'Kalar nahe dem Turm von Arathor finden, und sie erwartet, dass sein Tod den Angriffen auf Hammerfall ein Ende setzt."}},faq={{q="Wen versucht Korin Fel zu beschützen?",a="Ihren Ehemann. Ihre Vorsehung kündet ihr davon, dass Or'Kalar ihm eine Falle gestellt hat und der Oger seinen Tod will, weil er ihn vor Jahren besiegte.",al={"korins ehemann","warum korin hilfe braucht"}},{q="Warum greift Or'Kalar Hammerfall an?",a="Korin Fel bezeichnet Or'Kalar als Mug'thols Marionette in Stromgarde, erfüllt von Hass auf ihren Ehemann, der ihn vor Jahren besiegte. Sie sagt, sein Tod würde die Angriffe stoppen.",al={"warum or'kalar korins ehemann hasst","wer ist or'kalar","or'kalar motiv"}},{q="Wo befindet sich Or'Kalar?",a="Korin Fel sagt, dass er sich nahe dem Turm von Arathor befindet.",al={"or'kalar standort","wo man or'kalar findet","or'kalar finden"}},{q="Warum hält Korin die Bedrohung vor ihrem Ehemann geheim?",a="Sie fürchtet, er würde unbesonnen losstürmen, wenn er erführe, wo der Oger ist, weshalb sie ihn vor jeder Spur von Or'Kalar ferngehalten hat.",al={"warum geheim halten","warum or'kalar verbergen","korins geheimnis"}}},fp="15,169,28.274.0,16.281.0,35.124.0,37.162.0,26.47.0,57.125.0"}
P.entries["quest:681"] = {n="Northfold-Anwesen",s="Captain Nials in der Zuflucht bittet um Hilfe gegen das Syndikat, das den Nordhof besetzt hält. Dessen Kontrolle über das Land zwischen den Verteidigern von Stromgarde und Süderstade erschwert das Eintreffen von Nachschub.",h="Captain Nials in der Zuflucht bittet um Hilfe gegen das Syndikat, das den Nordhof besetzt hält.",kw={"captain nials","wegelagerer","soeldner","nordhof","die zuflucht","süderstade","stromgarde","syndikat"},sec={{t="Eine mühsame Verteidigung",b="Stromgarde wurde zwischen den Ogern, dem Syndikat und der Allianz aufgeteilt, und jede Fraktion bekämpft die anderen bis zu einem blutigen Stillstand. Die Streitkräfte der Allianz schwinden, während ihre Feinde erstarken. Die Verteidiger benötigen Hilfe aus Süderstade, doch der Nachschub trifft nur langsam ein."},{t="Das Syndikat auf dem Gutshof",b="Das Syndikat hält das Land zwischen den Verteidigern und Süderstade besetzt. Captain Nials möchte, dass Ihr zu ihrer Basis auf dem Nordhof geht und ihre Wegelagerer und Mercenaries zur Strecke bringt, in der Hoffnung, dass der Druck auf die Nachschubkarawanen nachlässt und mehr durchkommen."}},faq={{q="Warum möchte Captain Nials, dass das Syndikat auf dem Nordhof angegriffen wird?",a="Aus Süderstade muss die Hilfe kommen, doch das Syndikat sitzt auf dem Land dazwischen und den Verteidigern. Nials hofft, dass ihre Tötung in ihrer Basis den Druck auf die Nachschubkarawanen mindern wird.",al={"warum nordhof angreifen","nials ziel","zweck der quest nordhof"}},{q="Wie ist die aktuelle Lage in Stromgarde?",a="Die Oger, das Syndikat und die Allianz haben die einst großartige Stadt unter sich aufgeteilt, und jede Fraktion bekämpft die anderen bis zu einem blutigen Stillstand. Die Streitkräfte der Allianz schwinden, während ihre Feinde erstarken.",al={"stromgarde kriegsstatus","wer kontrolliert stromgarde","zustand von stromgarde"}},{q="Woher stammt der Nachschub der Allianz?",a="Die Verteidiger hoffen auf Hilfe aus der Stadt Süderstade, doch die Kontrolle des Syndikats über das dazwischenliegende Land erschwert den Empfang des Nachschubs.",al={"wer versorgt die zuflucht","nachschub aus süderstade","woher stammen lieferungen"}},{q="Welche Feinde müssen auf dem Gutshof ausgeschaltet werden?",a="Zehn Syndicate Highwaymen und sechs Syndicate Mercenaries, die auf dem Nordhof zu finden sind.",al={"wen auf dem nordhof toeten","nordhof ziele","liste der syndikatfeinde"}}},fp="15,205,20.269.0,26.257.0,70.197.0,44.201.0,44.140.0,49.81.0"}
P.entries["quest:682"] = {n="Abzeichen von Stromgarde",s="In Stromgarde kämpft das Syndikat gegen ein Kontingent der Miliz, und seine Anführer zahlen Gold für jedes Abzeichen, das einem gefallenen Milizsoldaten abgenommen wurde. In der Zuflucht möchte Captain Nials, dass diese Abzeichen geborgen werden.",h="In Stromgarde kämpft das Syndikat gegen ein Kontingent der Miliz, und seine Anführer zahlen Gold für jedes...",kw={"arathi","abzeichen","captain nials","miliz","die zuflucht","stromgarde","syndikat"},sec={{t="Ein Kopfgeld auf Soldaten",b="In Stromgarde befindet sich das Syndikat im Krieg mit einem Kontingent der Miliz. Um ihre Gefolgsleute zum Kampf gegen die besser ausgebildeten Soldaten anzuspornen, zahlen die Anführer des Syndikats Gold für jedes Abzeichen, das einem getöteten Milizsoldaten abgenommen wird. Captain Nials nennt sie Halsabschneider und will nicht zulassen, dass sie Trophäen der tapferen Gefallenen behalten, daher werdet Ihr in den vom Syndikat gehaltenen Teil von Stromgarde geschickt, um nach den Abzeichen zu suchen und sie zur Zuflucht zurückzubringen. Nials möchte, dass das Syndikat begreift, dass es aus den Toten keinen Profit schlagen kann."},{t="Nach der Jagd",b="Nials verspricht, dass den Verwandten der Gefallenen mitgeteilt wird, dass sie im Kampf gestorben sind. Diese Nachricht zu überbringen ist düster, doch Nials hält es für besser, als eine Familie im Ungewissen darüber zu lassen, was aus einem vermissten Verwandten geworden ist."}},faq={{q="Warum will das Syndikat Abzeichen von Stromgarde?",a="Ihre Anführer haben ein Kopfgeld auf die Miliz ausgesetzt: Gold für jedes Abzeichen, das einem gefallenen Milizsoldaten abgenommen wird, um die Gefolgsleute des Syndikats zum Kampf gegen die besser ausgebildeten Truppen anzuspornen.",al={"warum syndikat abzeichen","syndikat kopfgeld stromgarde","warum abzeichen sammeln"}},{q="Wo sind die Abzeichen zu finden?",a="Captain Nials schickt Euch in den Teil von Stromgarde, den das Syndikat kontrolliert, um dort nach den Abzeichen zu suchen.",al={"wo abzeichen finden","stromgarde abzeichen fundort","abzeichen beuteort"}},{q="Wer befiehlt die Bergung der Abzeichen?",a="Captain Nials in der Zuflucht, der nicht will, dass das Syndikat Trophäen von der gefallenen Miliz behält.",al={"wer vergibt stromgarde abzeichen","captain nials abzeichen quest","questgeber stromgarde abzeichen"}}},fp="17,200,20.487.0,14.204.1,46.189.0,27.103.0,39.106.0"}
P.entries["quest:683"] = {n="Sara Balloos Hilfegesuch",s="Sara Balloos Hilfegesuch ist eine bedrückende Botenaufgabe im Namen einer trauernden Zwergenwitwe in Eisenschmiede. Da Sara in ihrem Schmerz nicht in der Lage ist, ihrem Monarchen direkt entgegenzutreten, vertraut sie König Magni Bronzebart ein persönliches Gesuch bezüglich ihres gefallenen Mannes Sully Balloo an.",h="Sara Balloos Hilfegesuch ist eine bedrückende Botenaufgabe im Namen einer trauernden Zwergenwitwe in...",kw={"ehrerbietung von einem könig","dun morogh","eisenschmiede","magni bronzebart","sara balloo","sully balloo","thandol-übergang"},ang={["faction:Alliance"]="Die Vermittlung zwischen trauernden Bürgern und der Führung der Allianz verdeutlicht die persönlichen Opfer, die einfache Leute während der Konflikte zur Erhaltung des Reiches erbringen.",["race:Dwarf"]="Die Bitte einer trauernden Witwe direkt zu Eurem König zu bringen, berührt die tiefe kulturelle Bedeutung, die Zwerge der Steinmetzkunst, der Abstammung und der Würdigung der Opfer ihrer Ahnen beimessen."},sec={{t="Die Bitte einer Witwe",b="Nachdem sie den tragischen letzten Brief erhalten hat, der aus den wässrigen Tiefen des Thandol-Übergangs geborgen wurde, ist Sara Balloo vor Trauer gelähmt. Anstatt das Opfer ihres Mannes Sully in Vergessenheit geraten zu lassen, verfasst sie ein Gesuch, das direkt an den Thron von Eisenschmiede gerichtet ist. Zu sehr von Herzschmerz überwältigt, um selbst vor die höfische Etikette zu treten, vertraut sie das versiegelte Pergament einem geschätzten Streiter der Allianz an, um König Magni Bronzebart in ihrem Namen anzurufen."},{t="Audienz beim König",b="Eine private Petition zum High Seat von Eisenschmiede zu bringen, ist keine alltägliche Pflicht, doch Magni Bronzebart nimmt die tapferen Verteidiger von Khaz Modan persönlich wahr. Nach Erhalt der Nachricht unterbricht der König die Staatsgeschäfte, um die bescheidene Bitte der Witwe eines Soldaten zu lesen, was seine Verbundenheit mit den einfachen Zwergen zeigt, die sein Bergkönigreich erbaut haben und verteidigen."}},faq={{q="Wer ist Sara Balloo?",a="Sara Balloo ist eine Zwergin aus Eisenschmiede, deren Mann, der Soldat Sully Balloo, bei der Tragödie am Thandol-Übergang starb. Sie lebt in der Stadt und hält sein Andenken in Ehren.",al={"sara balloo","wer ist sara"}},{q="Warum möchte Sara, dass ich zum König gehe, anstatt selbst zu gehen?",a="Sara ist von Trauer überwältigt, nachdem sie endlich das endgültige Schicksal ihres Mannes erfahren hat. Sie hat das Gefühl, die Fassung nicht wahren zu können, die bei einem Gesuch an König Magni Bronzebart im High Seat erwartet wird.",al={"warum kann sara nicht gehen","saras trauer"}},{q="Wer war Sully Balloo?",a="Sully Balloo war ein Zwergensoldat, der den Thandol-Übergang verteidigte. Er fiel bei Kämpfen entlang der Brücke und hinterließ seiner Frau einen durchnässten Brief.",al={"sully balloo","saras mann"}},{q="Wo gebe ich Sara Balloos Hilfegesuch ab?",a="Ihr überbringt das Gesuch direkt König Magni Bronzebart im High Seat im Zentrum von Eisenschmiede.",al={"wo ist magni","standort könig magni","abgabeort"}},{q="Was geschieht, nachdem König Magni das Gesuch gelesen hat?",a="Das Lesen von Saras Bitte bewegt König Magni dazu, den gefallenen Soldaten gebührend zu ehren, was direkt in die Quest 'A King's Tribute' übergeht, um ein dauerhaftes Denkmal zu errichten.",al={"questfortsetzung","nächste quest"}},{q="Welche Fraktion kann diese Aufgabe übernehmen?",a="Dieser Botengang ist Mitgliedern der Allianz vorbehalten, da er interne zwergische Angelegenheiten und eine Audienz bei König Magni Bronzebart umfasst.",al={"kann die horde das machen","fraktionsvoraussetzung"}}},fx={ca82ce02={q="Warum möchte Sara Balloo, dass ihr Gesuch an König Magni Bronzebart übermittelt wird?",a="Sara Balloo trauert um den Verlust ihres Mannes, Sully Balloo, der bei der Verteidigung von The Thandol Span fiel. Nachdem sie endlich seinen letzten Brief erhalten hat, der unter der Spannbrücke geborgen wurde, möchte sie, dass König Magni Bronzebart das Opfer von Sully offiziell anerkennt und sein Andenken ehrt. Die Übermittlung dieses Gesuchs ist ihre Art sicherzustellen, dass die Hingabe ihres verstorbenen Mannes an die Allianz in Eisenschmiede in Erinnerung bleibt.",al={"warum will sara balloo dies erledigt haben","sara balloos motiv","warum gesuch an magni schicken"}}},fp="18,262,17.468.0,22.359.1,19.156.0,63.195.0,21.158.0,38.100.0,45.158.1,37.137.0"}
P.entries["quest:684"] = {n="GESUCHT: Marez Cowl",s="GESUCHT: Marez Cowl ist eine Kopfgeldquest der Allianz, die gegen eine hochrangige Agentin des Syndikats ausgerufen wurde, welche sich in den Ruinen von Stromgarde verschanzt hat. Als einflussreiche Beraterin und finstere Hexenmeisterin, die mit Dämonen paktiert, stellt Cowl eine ernste Bedrohung für die Streitkräfte der Allianz dar, die versuchen, das Arathihochland zu sichern.",h="GESUCHT: Marez Cowl ist eine Kopfgeldquest der Allianz, die gegen eine hochrangige Agentin des Syndikats...",kw={"arathihochland","kopfgeld","captain nials","marez cowl","die zuflucht","stromgarde","syndikat","hexenmeister"},ang={["class:Paladin"]="Da sie inmitten der Ruinen eines alten Menschenkönigreichs offen mit dämonischen Wesenheiten paktiert, stellt Cowl einen Frevel gegen das Heilige Licht und die Verteidigung von Stromgarde dar.",["class:Warlock"]="Marez Cowl repräsentiert den dunkleren okkulten Flügel des Syndikats und zeigt, wie politische Abtrünnige bereitwillig auf Dämonenbeschwörungen zurückgreifen, um ihren Einfluss auszuweiten.",["faction:Alliance"]="Die Allianz-Garnison in der Zuflucht unter Captain Nials kämpft verzweifelt um die Rückeroberung von Stromgarde, weshalb hochrangige Ziele des Syndikats wie Marez Cowl oberste strategische Priorität haben."},sec={{t="Ein Preis auf die Führung des Syndikats",b="GESUCHT: Marez Cowl ist ein Kopfgelddekret der Allianz, das erlassen wurde, um eine der wichtigsten Führungspersönlichkeiten des Syndikats im Arathihochland auszuschalten. Marez Cowl dient als hochrangige Beraterin und Einsatzleiterin innerhalb der Organisation und koordiniert deren Aktivitäten in der zerstörten Hauptstadt Stromgarde. Indem sie ein Kopfgeld auf sie aussetzen, wollen die Allianzkommandanten in der Zuflucht die örtliche Befehlsstruktur des Syndikats enthaupten."},{t="Die Hexenmeisterin von Stromgarde",b="Anders als gewöhnliche Räuber oder enteignete Adlige des Syndikats ist Marez Cowl eine Ausüberin dunkler Zauberei. Sie ist als gerissene Hexenmeisterin bekannt, die offen mit dämonischen Mächten paktiert, um ihren Willen durchzusetzen und das Territorium des Syndikats zu verteidigen. Wer sich ihrem Versteck in Stromgarde nähert, muss sich nicht nur Meuchelmördern und Verschwörern stellen, sondern auch den finsteren Wesenheiten, die sie befehligt."}},faq={{q="Wer ist Marez Cowl?",a="Marez Cowl ist eine hochrangige Agentin und Beraterin innerhalb des Syndikats. Weit davon entfernt, eine bloße Fußsoldatin zu sein, besitzt sie beträchtlichen Einfluss innerhalb der kriminellen Organisation und gilt als gerissene, gefährliche Hexenmeisterin, die für ihren Pakt mit dämonischen Mächten bekannt ist.",al={"wer ist marez cowl","marez cowl hintergrund","wer ist sie"}},{q="Wo befindet sich Marez Cowl?",a="Marez Cowl hält sich im vom Syndikat kontrollierten Teil der zerstörten Stadt Stromgarde im Arathihochland auf. Jeder, der Jagd auf sie machen will, muss tief verschanzte kriminelle Streitkräfte überwinden, um ihr Sanktum ausfindig zu machen.",al={"wo man marez cowl findet","marez cowl aufenthaltsort","wo ist marez"}},{q="Wer hat das Kopfgeld auf Marez Cowl ausgesetzt?",a="Das Kopfgeld wird im Namen der im Arathihochland stationierten Militärstreitkräfte der Allianz ausgesetzt. Beaufsichtigt wird es von Captain Nials, der den Stützpunkt der Allianz in der Zuflucht befehligt.",al={"wer hat das kopfgeld auf marez cowl ausgesetzt","wer will marez cowl tot sehen","wer zahlt das kopfgeld"}},{q="Warum ist ein Kopfgeld auf sie ausgesetzt?",a="Sie wird wegen ihrer entscheidenden Führungsrolle im Syndikat und ihrer aktiven Dämonenbeschwörung innerhalb von Stromgarde gesucht. Ihre Anwesenheit stellt eine unmittelbare Bedrohung für die Garnison der Allianz dar, die darum kämpft, das zerstörte Königreich zurückzuerobern.",al={"warum wird marez cowl gesucht","warum kopfgeld auf marez cowl","warum marez cowl toeten"}},{q="Welche Art von Magie wirkt Marez Cowl?",a="Marez ist nicht bloß eine politische Verschwörerin; sie ist eine versierte Hexenmeisterin, die aktiv Dämonen beschwört und mit ihnen verhandelt. Jäger werden ausdrücklich davor gewarnt, äußerste Vorsicht walten zu lassen, wenn sie sich ihr und ihren dämonischen Dienern stellen.",al={"was macht marez cowl gefaehrlich","marez cowl kraefte","ist marez cowl stark"}},{q="Wo gibt man das Kopfgeld für Marez Cowl ab?",a="Sobald Marez Cowl getötet wurde, muss ihr Kopf direkt zu Captain Nials in der Zuflucht gebracht werden, dem primären Außenposten der Allianz im Arathihochland.",al={"wo kopfgeld fuer marez cowl abgeben","wo ist captain nials","marez kopf abgeben"}}},fp="18,312,31.423.0,25.373.0,18.260.0,28.217.0,36.186.0,34.240.0,39.224.0,47.150.0"}
P.entries["quest:685"] = {n="GESUCHT: Falkenstein und Otto",s="Ein von der Stromgarde-Miliz ausgesetztes Kopfgeld gibt Lord Falconcrest, den Anführer der örtlichen Streitkräfte des Syndikats, und seinen tödlichen Leibwächter Otto zum Tode frei. Ihre Ausschaltung versetzt der Stellung der kriminellen Organisation im Arathihochland einen entscheidenden Schlag. Ein Beweis für ihr Ableben muss Captain Nials in der Zuflucht überbracht werden.",h="Ein von der Stromgarde-Miliz ausgesetztes Kopfgeld gibt Lord Falconcrest, den Anführer der örtlichen...",kw={"arathihochland","kopfgeld","captain nials","falconcrest","otto","die zuflucht","stromgarde miliz","syndikat"},ang={["faction:Alliance"]="Lord Falconcrest und seine Agenten des Syndikats bedrohen die Überreste von Stromgarde, was dieses Kopfgeld unerlässlich macht, um die Zuflucht zu sichern und das Hochland zurückzugewinnen.",["race:Human"]="Für die Verteidiger von Stromgarde ist das Niedermetzeln verräterischer Menschenadliger im Syndikat ein persönlicher Kampf, um ihr gefallenes Königreich zu rächen."},sec={{t="Ein verzweifeltes Kopfgeld",b="Die Stromgarde-Miliz hat ein offizielles Kopfgeld auf zwei Schlüsselfiguren im Arathihochland ausgesetzt: Lord Falconcrest und seinen wilden Leibwächter Otto. Ausgehend von der Zuflucht versuchen die bedrängten Verteidiger von Stromgarde, die Kontrolle des Syndikats über ihre angestammten Länder zu brechen. Jäger müssen die Köpfe beider Ziele zu Captain Nials bringen, um die Belohnung einzufordern."},{t="Kommandant und Vollstrecker",b="Lord Falconcrest fungiert als Drahtzieher hinter dem koordinierten Vormarsch des Syndikats in das Arathihochland. Sein Tod stellt einen wichtigen strategischen Sieg für die Allianz dar und verspricht, die Operationen des kriminellen Netzwerks in der Region empfindlich zu stören. An seiner Seite steht Otto, ein brutal effektiver Leibwächter, dessen Klingen bereits Dutzende der verbliebenen Milizsoldaten von Stromgarde niedergestreckt haben."}},faq={{q="Wer ist Lord Falconcrest?",a="Lord Falconcrest ist ein Adliger und Kommandant, der die Operationen des Syndikats im Arathihochland leitet. Seine Anwesenheit organisiert deren opportunistischen Griff nach dem zerbrochenen Königreich von Stromgarde, was seine Beseitigung zu einem primären Ziel für die örtliche Menschenmiliz macht.",al={"wer ist lord falconcrest","falconcrest lore","wer ist falconcrest"}},{q="Wer ist Otto?",a="Otto ist der tödliche persönliche Leibwächter von Lord Falconcrest. Obwohl er kein strategischer Planer wie sein Meister ist, ist er ein wilder Kämpfer, der für die Tötung von Dutzenden Verteidigern von Stromgarde im Hochland verantwortlich ist.",al={"wer ist otto","falconcrest leibwaechter","otto syndikat"}},{q="Warum hat die Stromgarde-Miliz ein Kopfgeld auf sie ausgesetzt?",a="Die Stromgarde-Miliz hat Kopfgelder auf sie ausgesetzt, um die Führung des Syndikats im Arathihochland zu schwächen. Die Ausschaltung von Falconcrest zerschlägt deren regionale Befehlsstruktur, während der Sturz von Otto eine tödliche Bedrohung beseitigt, die viele Kämpfer der Allianz niedergemetzelt hat.",al={"warum kopfgeld auf falconcrest","warum otto und falconcrest toeten","stromgarde kopfgeld"}},{q="Wer bietet die Belohnung für Otto und Falconcrest an?",a="Die Kopfgelder für sowohl Lord Falconcrest als auch Otto werden von Captain Nials entgegengenommen, einem Offizier der Stromgarde-Miliz, der in der Zuflucht im Arathihochland stationiert ist.",al={"wo otto falconcrest abgeben","wer ist captain nials","falconcrest kopfgeld abgabe"}},{q="Was tut das Syndikat im Arathihochland?",a="Das Syndikat besteht aus gefallenen Adligen aus Alterac und Schurkenelementen, die inmitten des Zusammenbruchs des nördlichen Lordaerons nach Land und Reichtum streben. Im Arathihochland sind sie in die Ruinen von Stromgarde vorgedrungen, um dessen überlebenden Verteidigern die Kontrolle zu entreißen.",al={"was ist das syndikat arathi","syndikat rolle arathi"}},{q="Welcher Beweis wird verlangt, um das Kopfgeld einzufordern?",a="Um die Belohnung einzufordern, müssen Jäger die abgetrennten Köpfe von sowohl Lord Falconcrest als auch Otto als unwiderlegbaren Beweis für deren Ableben direkt zu Captain Nials in die Zuflucht bringen.",al={"wohin ottos kopf bringen","beweis fuer kopfgeld"}}},fp="28,329,18.373.0,22.393.0,24.255.0,12.206.0,55.267.0,47.168.0,52.255.0,43.171.0"}
P.entries["quest:686"] = {n="Ehrerbietung von einem König",s="Ehrerbietung von einem König ist eine Allianz-Quest, die von König Magni Bronzebart im High Seat von Eisenschmiede angeboten wird. Tief bewegt von der Trauer von Sara Balloo, deren Ehemann Sully bei der Verteidigung des Thandol-Übergangs fiel, beschließt der König, den gefallenen Soldaten mit einem bleibenden Denkmal zu ehren. Er entsendet einen Abenteurer, um seinen königlichen Auftrag an Großsteinmetz Marmorstein zu überbringen.",h="Ehrerbietung von einem König ist eine Allianz-Quest, die von König Magni Bronzebart im High Seat von...",kw={"eisenschmiede","magni bronzebart","marblesten","denkmal","sara balloo","sully balloo","thandol-übergang"},ang={["faction:Alliance"]="Die Gefallenen am Thandol-Übergang gaben ihr Leben, um für die Allianz entscheidende Nachschubwege zwischen Khaz Modan und den nördlichen Königreichen zu sichern.",["race:Dwarf"]="Diese Aufgabe zeugt von König Magnis Hingabe an sein Volk und beweist, dass selbst der einfachste Zwergenfußsoldat vom Thron nicht vergessen wird."},sec={{t="Die Bürde eines Herrschers",b="Als König Magni Bronzebart das Gesuch von Sara Balloo erhält, weist er die trauernde Witwe nicht ab. Obwohl er einräumt, dass das einfache Volk die brutalen Notwendigkeiten des Krieges oft nur schwer verstehen mag, lastet der Verlust jedes einzelnen Soldaten, der unter dem Banner der Allianz kämpft, schwer auf seinem Gewissen. Unfähig, die düstere Endgültigkeit des Todes an den Frontlinien rückgängig zu machen, beschließt Magni, dafür zu sorgen, dass das Opfer von Sully Balloo niemals in Vergessenheit gerät."},{t="Der Meißel des Steinmetzes",b="Statt leere Floskeln von sich zu geben, entschließt sich der König, ein greifbares Denkmal zu Sullys Ehren errichten zu lassen. Er ernennt den Abenteurer zum Überbringer seines königlichen Willens und schickt ihn quer durch Eisenschmiede, um mit Großsteinmetz Marmorstein zu sprechen. Betraut mit dem persönlichen Auftrag des Königs bereitet sich der Meistersteinmetz darauf vor, das Gedenken an einen gefallenen Verteidiger in Stein zu meißeln."}},faq={{q="Wer war Sully Balloo?",a="Sully Balloo war ein Zwergensoldat, der bei der Verteidigung des Thandol-Übergangs im Kampf für die Allianz sein Leben verlor. Seine Witwe, Sara Balloo, wandte sich an König Magni Bronzebart, nachdem sie von seinem Tod erfahren hatte.",al={"wer ist sully","sully balloo hintergrundgeschichte","wer starb"}},{q="Warum gibt König Magni ein Denkmal in Auftrag?",a="König Magni trägt die Last jedes Zwergenlebens, das in den anhaltenden Kämpfen der Allianz verloren geht. Zwar kann er der Witwe ihren Sully nicht zurückbringen, doch beabsichtigt er, den Mut des Soldaten mit einem bleibenden königlichen Denkmal zu ehren.",al={"warum denkmal bauen","magnis beweggrund","zweck von ehrerbietung von einem könig"}},{q="Wer ist Großsteinmetz Marmorstein?",a="Großsteinmetz Marmorstein ist der oberste Steinmetz von Eisenschmiede, der damit betraut ist, bedeutende städtische und königliche Bauprojekte in der gesamten Stadt umzusetzen. König Magni verlässt sich auf ihn, um das Denkmal für Sully Balloo zu meißeln.",al={"wer ist marblesten","rolle des großsteinmetzes"}},{q="Wo findet diese Quest statt?",a="Die Quest findet vollständig innerhalb von Eisenschmiede statt; sie beginnt am High Seat bei König Magni Bronzebart und führt zu Großsteinmetz Marmorstein an einem anderen Ort in der Hauptstadt.",al={"wo ist diese quest","questort"}},{q="Was geht dieser Quest voraus?",a="Bevor ein Abenteurer diese Quest erhalten kann, muss er 'Sara Balloos Gesuch' abschließen und den herzergreifenden Brief der Witwe direkt an König Magni Bronzebart überbringen.",al={"voraussetzungen","vorherige quest"}},{q="Ist dieses Denkmal nur für Sully Balloo bestimmt?",a="Obwohl es eigens auf den Namen von Sully Balloo in Auftrag gegeben wurde, um seine Witwe Sara zu trösten, versinnbildlicht der Tribut die Hochachtung des Königs vor jedem Zwergenkämpfer, der im Dienste der Allianz sein Leben lässt.",al={"wen ehrt es","ist es nur für sully"}}},fx={["66401eff"]={q="Warum wählt König Magni Bronzebart Euch als Verwalter für den Tribut?",a="Ihr wart die Person, die das herzliche Gesuch von Sara Balloo direkt in den High Seat getragen und ihr persönliches Schicksal vor den Thron gebracht hat. Weil Ihr Euch entschieden habt, dem Kummer einer trauernden Witwe zuzuhören und ihre Worte dem König zu überbringen, betraut Magni Euch damit, die königliche Ehrung durchzuführen, wodurch Ihr zum Verwalter seines Auftrags werdet, anstatt ihn an Palastbürokraten zu delegieren.",al={"warum ich kings tribute","warum schickt euch magni","warum ich"}}},fp="16,352,20.431.0,18.361.0,21.205.0,42.213.0,30.205.0,33.167.0,29.154.0,39.193.0"}
P.entries["quest:687"] = {n="Theldurin der Verirrte",s="Ein Mitglied des Schattenhammerkults bittet Euch darum, Theldurin den Verirrten zu finden, der einst zu ihrem Orden gehörte, den Verstand verlor und mit der Rolle von Myzrael floh. Gerüchte verorten ihn im Ödland.",h="Ein Mitglied des Schattenhammerkults bittet Euch darum, Theldurin den Verirrten zu finden, der einst zu ihrem...",kw={"ödland","gerrig knochengriff","myzrael","rolle von myzrael","theldurin","theldurin der verirrte","twilight's hammer","zaruk"},sec={{t="Der Mann, der die Rolle stahl",b="Theldurin gehörte einst zum Schattenhammerkult, bis sein Verstand schwand und er den Lehren des Ordens den Rücken kehrte. Als er floh, nahm er die Rolle von Myzrael mit sich. Diejenigen, die er zurückließ, konnten ihn nicht einholen."},{t="Gerüchte aus dem Ödland",b="Der Orden hat erfahren, dass Theldurin sich rasend und verrückt im Ödland versteckt. Die Rolle wird für die Rückkehr der Herrin benötigt, und um sie zu erlangen, müsst Ihr zuerst den Mann finden, der sie an sich genommen hat."}},faq={{q="Wer ist Theldurin der Verirrte?",a="Ein ehemaliges Mitglied des Schattenhammerkults, das den Verstand verlor, die Lehren des Ordens ablehnte und mit der Rolle von Myzrael floh.",al={"theldurin hintergrundgeschichte","wer ist theldurin","theldurin lore"}},{q="Warum sucht der Schattenhammerkult nach ihm?",a="Er ist mit der Rolle von Myzrael davongelaufen, die laut dem Orden gefunden werden muss, um die Herrin zurückzuholen.",al={"warum theldurin finden","warum wollen kultisten theldurin"}},{q="Wohin floh Theldurin, nachdem er den Orden verlassen hatte?",a="Dem Orden liegen nur Gerüchte vor, die ihn im Ödland verorten.",al={"wo ist theldurin","theldurin aufenthaltsort lore"}},{q="Was kommt unmittelbar vor dieser Suche?",a="Sie folgt auf Myzraels Verbündete.",al={"vorherige quest theldurin","voraussetzung für theldurin der verirrte"}}},fp="18,185,28.215.0,22.172.0,26.128.0,45.97.0,49.59.0,39.28.0"}
P.entries["quest:688"] = {n="Myzraels Verbündete",s="Myzrael spricht durch den Schlussstein, erklärt, dass sie frei ist, sich jedoch vor ihren Peinigern versteckt hält, und fordert Euch auf, mit Zaruk in Hammerfall zu sprechen, der weiß, wie sie herbeigerufen werden kann.",h="Myzrael spricht durch den Schlussstein, erklärt, dass sie frei ist, sich jedoch vor ihren Peinigern versteckt...",kw={"arathihochland","riesen","hammerfall","schlussstein","myzrael","zaruk"},sec={{t="Frei, aber verborgen",b="Myzrael ruft aus, dass sie frei sei. Vorerst müsse sie ihre Kräfte außer Sichtweite ihrer Peiniger sammeln, denn sollten diese ihr heute gegenübertreten, würden sie sie überwältigen und erneut gefangen setzen. Mit der Zeit, so schwört sie, werde sie sich den Riesen stellen, die sie festhielten, und sie würden es bereuen, sie gefangen gehalten zu haben."},{t="Zaruk von Hammerfall",b="Myzrael nennt Euch einen edlen Verbündeten und sagt, dass sie mit der Zeit wieder Eure Hilfe benötigen werde. Wenn sie bereit sei, werde sie Euch anweisen, sie an die Oberfläche zu beschwören. Vorerst schickt sie Euch zu Zaruk in Hammerfall, der weiß, wie dies vollbracht werden kann."}},faq={{q="Wer schickt Euch zu Zaruk?",a="Myzrael selbst, die durch den Schlussstein spricht, trägt Euch auf, Zaruk in Hammerfall aufzusuchen.",al={"wer gibt myzraels verbündete","questgeber myzraels verbündete","wer spricht durch den schlussstein"}},{q="Warum versteckt sich Myzrael?",a="Sie sagt, dass ihre Peiniger sie überwältigen und erneut gefangen setzen würden, sollten sie ihr nun gegenübertreten, daher hält sie sich verborgen, während sie Kräfte sammelt.",al={"warum kämpft myzrael nicht","warum ist myzrael schwach","warum versteckt sich myzrael"}},{q="Wo ist Zaruk zu finden?",a="In Hammerfall.",al={"zaruk aufenthaltsort","wo ist zaruk","zaruk finden"}},{q="Welche Rolle spielt Zaruk für Myzrael?",a="Myzrael sagt, er wisse, wie sie herbeigerufen werden kann.",al={"warum mit zaruk sprechen","was weiß zaruk","zaruks zweck"}}},fp="16,175,15.274.0,19.217.0,23.85.0,22.123.0,25.14.0,38.46.0"}
P.entries["quest:689"] = {n="Ehrerbietung von einem König",s="König Magni Bronzebart hat ein Denkmal für Sully Balloo in Auftrag gegeben, einen Zwergensoldaten, der bei der Verteidigung des Thandol-Übergangs ums Leben kam. Um den gefallenen Krieger mit bleibender Würde zu ehren, schickt Großsteinmetz Marmorstein Reisende in das Hillsbrad, um makellosen Alteracgranit zu beschaffen.",h="König Magni Bronzebart hat ein Denkmal für Sully Balloo in Auftrag gegeben, einen Zwergensoldaten, der bei...",kw={"alteracgranit","darrow hill","eisenschmiede","magni bronzebart","marmorstein","steinmetz","sully balloo","thandol-übergang"},ang={["faction:Alliance"]="Die Sicherung von Materialien aus Hillsbrad stärkt die Präsenz der Allianz im zerklüfteten Norden und ehrt gleichzeitig einen gewöhnlichen Soldaten, der sein Leben für die gemeinsame Sache gab.",["profession:Mining"]="Bergleute verstehen Marmorsteins wählerischen Blick; die harten, unnachgiebigen Adern von Alteracgranit erfordern erfahrene Hände, um sauber und ohne Risse abgebaut zu werden.",["race:Dwarf"]="Die Ehrung von Sully Balloo berührt den Kern der Zwergenkultur, in der Steinmetzarbeit, militärisches Opfer und unerschütterliche Loyalität gegenüber König Bronzebeard tief miteinander verwoben sind."},sec={{t="Ein königlicher Auftrag",b="Als König Magni Bronzebart entschied, dass der gefallene Soldat Sully Balloo ein bleibendes Denkmal verdient, fiel diese Aufgabe direkt dem besten Handwerker der Eisenschmiede zu, Großsteinmetz Marmorstein. Balloo verlor sein Leben während des Unglücks am Thandol-Übergang, einer lebenswichtigen Schlagader, die die Zwergenlande mit den nördlichen Königreichen verbindet und die unter brutalen Angriffen von Dunkeleisensaboteuren gelitten hat. Für Marmorstein bedeutet die Erfüllung des königlichen Dekrets die Erschaffung einer Skulptur, die sowohl der Zeit als auch dem Krieg trotzen wird, und sicherstellt, dass das Opfer der Zwerge in der Großen Schmiede weder übersehen noch vergessen wird."},{t="Stein des Nordens",b="Ein zwergischer Steinmetzmeister gibt sich für das Projekt eines Königs nicht mit gewöhnlichem Bruchstein zufrieden. Marmorstein besteht darauf, dass Sully Balloos Abbild nur in Alteracgranit festgehalten werden kann, einem dichten, widerstandsfähigen Stein, der für seine Langlebigkeit und saubere Textur geschätzt wird. Die Herausforderung liegt in dessen Beschaffung: Die besten Vorkommen liegen um Darrow Hill in den umkämpften Vorgebirgen des Hügellands. Der Vorstoß tief in den unruhigen Norden ist gefährlich, doch zwergische Steinmetzkunst verlangt Materialien, die des Heldentums, das sie verewigen soll, würdig sind."}},faq={{q="Wer ist Sully Balloo?",a="Sully Balloo war ein Soldat der Allianz, der bei der Verteidigung des Thandol-Übergangs während dessen katastrophaler Sabotage starb. Bewegt von einem Brief seiner trauernden Witwe Sara Balloo, befahl König Magni Bronzebart die Errichtung einer dauerhaften Statue zu seinen Ehren.",al={"sully balloo","wer war sully balloo","sully balloo hintergrund"}},{q="Wer ist Großsteinmetz Marmorstein?",a="Großsteinmetz Marmorstein ist der Bildhauermeister und Steinmetz der Eisenschmiede. Von den dortigen Gemeinschaftsvierteln aus tätig, kümmert er sich um königliche Aufträge und ist stolz darauf, nur mit den besten regionalen Steinen zu arbeiten.",al={"großsteinmetz marmorstein","marmorstein eisenschmiede","wer ist marmorstein"}},{q="Warum wird Alteracgranit benötigt?",a="Alteracgranit wird in den gesamten Östlichen Königreichen für seine außergewöhnliche Dichte, sein feines Korn und seine Widerstandsfähigkeit gegen Erosion gefeiert. Marmorstein besteht darauf, dass nur Stein dieses Kalibers eines königlichen Tributs würdig ist, das die Zeiten überdauern soll.",al={"warum alteracgranit","verwendung von alteracgranit","was ist alteracgranit"}},{q="Wo liegt Darrow Hill?",a="Darrow Hill ist ein hügeliges Gebiet im nördlichen Vorgebirge des Hügellands, direkt unterhalb des Headland und in der Nähe der Grenze zu Alterac, wo Alteracgranit in den Höhlen gefunden wird.",al={"wo liegt darrow hill","darrow hill standort","darrow hill finden"}},{q="Was geschah am Thandol-Übergang?",a="Der Thandol-Übergang, die kolossale Brücke über die Schlucht zwischen dem Sumpfland und dem Arathihochland, erlitt einen Angriff durch Dunkeleisensaboteure, die Sprengstoff platzierten, um die Versorgungsrouten der Allianz zu kappen, was das Leben vieler Verteidiger forderte.",al={"tragödie am thandol-übergang","katastrophe am thandol-übergang","was geschah mit dem thandol-übergang"}},{q="Was passiert, nachdem Ihr den Granit zu Marmorstein gebracht habt?",a="Sobald er mit dem Alteracgranit versorgt wurde, stellt Marmorstein das Denkmal fertig und bittet Euch, König Magni zu berichten, dass es vollendet ist.",al={"nach der abgabe des granits","marmorsteins statuenfortschritt"}}},fx={["1680ec58"]={q="Warum will Großsteinmetz Marmorstein, dass dies erledigt wird?",a="König Magni Bronzebart hat persönlich ein Denkmal in Auftrag gegeben, um den gefallenen Soldaten Sully Balloo zu ehren. Für Großsteinmetz Marmorstein haben königliche Aufträge höchste Priorität und erfordern seine beste Arbeit. Obwohl er das endlose Blutvergießen in ganz Azeroth beklagt, besteht er darauf, nur den feinsten Stein zu verwenden, um einen wirklich epischen, bleibenden Tribut zu schaffen, der dem Wunsch des Königs würdig ist.",al={"warum interessiert das marmorstein","marmorsteins motiv","warum sully balloo monument bauen"}}},fp="16,272,18.565.0,18.498.0,20.234.0,30.213.0,30.242.0,21.161.0,34.232.0,54.131.0"}
P.entries["quest:69"] = {n="Die Legende von Stalvan",s="Diese Besorgung markiert eine entscheidende Wendung bei der Suche nach dem schwer fassbaren Stalvan Dunstmantel und führt die Ermittler aus der Düsternis des Dämmerwalds zurück ins Herz des Königreichs. Ein hastiger, durchgestrichener Eintrag, der im Stadtregister von Dunkelhain entdeckt wurde, weist über den Fluss nach Goldhain. Dieser Papierspur zum belebten Gasthaus \"Zur Höhle des Löwen\" zu folgen, ist der nächste Schritt, um aufzudecken, wohin der geheimnisvolle Hauslehrer gegangen ist.",h="Diese Besorgung markiert eine entscheidende Wendung bei der Suche nach dem schwer fassbaren Stalvan...",kw={"amtmann daltry","dunkelhain","dämmerwald","wald von elwynn","goldhain","gastwirt farley","gasthaus \"zur höhle des löwen\"","stalvan"},ang={["faction:Alliance"]="Die Enträtselung lokaler Geschichten und erkalteter Spuren in den südlichen Gebieten der Allianz erfordert das Reisen zwischen Grenzaußenposten wie Dunkelhain und zentralen Weilern wie Goldhain.",["race:Human"]="Stalvans Schritte nachzuvollziehen führt Euch durch das Kernland des Königreichs Sturmwind und verbindet die heimgesuchten Grenzgebiete des Dämmerwalds wieder mit den vertrauten Annehmlichkeiten des Walds von Elwynn."},sec={{t="Ein Hinweis im Register",b="Bei der Durchsicht der Aufzeichnungen von Dunkelhain bemerkt Amtmann Daltry ein Versäumnis im Stadtregister. Unter einem früheren Eintrag für Stalvan Dunstmantel verbirgt sich ein zweites Ziel, hastig niedergeschrieben und teilweise durchgestrichen, als hätte es sich jemand anders überlegt oder beabsichtigt, seine Bewegungen zu verschleiern. Die Notiz deutet darauf hin, dass Stalvan vorhatte, nach Nordwesten in den Wald von Elwynn zu reisen, genauer gesagt zum Gasthaus \"Zur Höhle des Löwen\"."},{t="Übergang nach Elwynn",b="Die schattigen Haine des Dämmerwalds gegen die sonnigen Straßen von Goldhain einzutauschen, bietet einen krassen Kontrast, doch der Schatten von Stalvans Vergangenheit reicht selbst bis hierher. Das Gasthaus \"Zur Höhle des Löwen\" dient als geschäftiger Knotenpunkt des Walds von Elwynn und heißt Reisende, Händler sowie Soldaten gleichermaßen willkommen. Gastwirt Farley führt die belebte Schankstube, was ihn zur idealen Ansprechperson macht, um sich nach einem gebildeten Wanderer zu erkundigen, der eine Unterkunft suchte."}},faq={{q="Warum führt die Spur nach Goldhain?",a="Amtmann Daltry entdeckte im Register von Dunkelhain unter Stalvans ursprünglichem Eintrag eine zweite, teilweise durchgestrichene Adresse. Sie wies eindeutig darauf hin, dass er auf dem Weg zum Gasthaus \"Zur Höhle des Löwen\" in Goldhain war.",al={"warum goldhain","warum nach goldhain gehen","stalvan in goldhain"}},{q="Wer ist Amtmann Daltry?",a="Amtmann Daltry ist der im Rathaus von Dunkelhain stationierte Archivar. Er führt die örtlichen Register und hilft dabei, historische Dokumente über frühere Bewohner auszugraben.",al={"daltry","wer ist daltry"}},{q="Mit wem spreche ich im Gasthaus \"Zur Höhle des Löwen\"?",a="Ihr müsst direkt mit Gastwirt Farley sprechen, der das Gasthaus \"Zur Höhle des Löwen\" leitet und den Überblick über Reisende und Gäste behält, die Goldhain durchqueren.",al={"mit wem sprechen","kontakt lion's pride","gastwirt goldhain"}},{q="Warum war der Eintrag im Register durchgestrichen?",a="Der Registereintrag war nur teilweise ausradiert, was auf einen überstürzten oder vorsätzlichen Versuch hindeutet, Stalvans Route in den Wald von Elwynn zu verbergen, als er den Dämmerwald verließ.",al={"durchgestrichene notiz","warum durchgestrichen"}},{q="Beinhaltet diese Quest irgendwelche Kämpfe?",a="Nein. Dieser Schritt der Untersuchung besteht rein aus Reisen und Nachforschungen, die Euch sicher vom Rathaus in Dunkelhain zur Schankstube in Goldhain führen.",al={"gibt es kämpfe","muss ich kämpfen"}},{q="Was ist das Gasthaus \"Zur Höhle des Löwen\"?",a="Das Gasthaus \"Zur Höhle des Löwen\" ist der zentrale Knotenpunkt von Goldhain im Wald von Elwynn. Es ist ein bekannter Rastplatz für Reisende auf dem Weg zwischen Sturmwind, Westfall und dem Dämmerwald.",al={"gasthaus \"zur höhle des löwen\"","gasthaus goldhain"}}},fx={f40d5969={q="Warum will Amtmann Daltry, dass Stalvan aufgespürt wird?",a="Als Stadtschreiber von Dunkelhain führt Daltry die Stadtakten und das Register. Nachdem Madame Eva Euch ursprünglich auf die Spur der geheimnisvollen Figur namens Stalvan Dunstmantel gebracht hatte, half Daltry bei der Suche, indem er seine Register durchforstete. Er entdeckte einen übersehenen, teilweise durchgestrichenen Eintrag unter der ersten Adresse und weist Euch an, dem neuen Hinweis nachzugehen, um die Geschichte des schwer fassbaren Mannes zusammenzusetzen.",al={"warum interessiert das daltry","daltrys motiv stalvan","warum stalvan aufspüren"}},["136b3a3d"]={q="Warum schickt Euch Amtmann Daltry nach Goldhain, anstatt selbst zu gehen?",a="Amtmann Daltry ist ein ziviler Beamter, der an das Rathaus von Dunkelhain gebunden ist und dafür verantwortlich ist, Aufzeichnungen zu führen und der lokalen Bevölkerung in einer von Schrecken belagerten Siedlung zu dienen. Eine Reise über den Fluss in den Wald von Elwynn, um Schankwirte zu befragen, liegt außerhalb seines Amtsbereichs und seiner Pflichten, weshalb ein rüstiger Abenteurer viel besser geeignet ist, entfernten Hinweisen nachzugehen.",al={"warum mich schicken","warum geht daltry nicht selbst","warum braucht daltry einen abenteurer"}}},fp="21,405,20.410.0,20.404.0,37.199.0,20.172.0,42.150.0,48.160.0,35.150.0,29.176.0"}
P.entries["quest:690"] = {n="Malins Gesuch",s="Malins Gesuch ist eine Aufgabe der Allianz, die von Erzmagier Malin im Magierviertel von Sturmwind angeboten wird. Malin bittet erfahrene Abenteurer, weit nach Norden zur Zuflucht im Arathihochland zu reisen, wo eine Expedition versucht, wertvolle magische Relikte zu bergen, die beim Fall von Stromgarde zurückgelassen wurden.",h="Malins Gesuch ist eine Aufgabe der Allianz, die von Erzmagier Malin im Magierviertel von Sturmwind angeboten...",kw={"arathihochland","malin","die zuflucht","skuerto","sturmwind","stromgarde","der turm von arathor","trelane","magiersanktum"},ang={["class:Mage"]="Für Magier, die das Magiersanktum besuchen, rettet die Unterstützung Malins unmittelbar kostbare arkane Forschungen und Relikte, die mit dem Erbe der Magier von Arathor verknüpft sind.",["faction:Alliance"]="Die Zuflucht stellt den fragilen, verbliebenen Stützpunkt der Allianz in Arathi dar, wodurch jede aus Sturmwind entsandte Verstärkung entscheidend für den Halt der Region ist.",["race:Human"]="Stromgarde war die Wiege der menschlichen Zivilisation; die Bergung seiner Schätze zu unterstützen, ist für die Söhne und Töchter von Arathor eine Frage der Ehre und des historischen Überlebens."},sec={{t="Die verlorenen Besitztümer eines Meisters",b="Erzmagier Malin, der im Magiersanktum von Sturmwind stationiert ist, handelt im Auftrag seines ehemaligen Meisters, Erzmagier Trelane. Als das kriegerische Königreich Stromgarde in Chaos und Ruinen versank, leistete Trelane am Turm von Arathor verzweifelten Widerstand. Gezwungen, seinen Posten aufzugeben, als die Stadt an feindliche Truppen fiel, ließ Trelane mächtige verzauberte Besitztümer zurück. Bestrebt, diese verlorenen Artefakte zurückzuerlangen, bevor feindliche Hände sie an sich reißen, schickt Malin fähige Söldner nach Norden, um seine Einsatzkräfte vor Ort zu verstärken."},{t="Der bedrängte Außenposten an der Zuflucht",b="Der Weg zur Bergung von Trelanes Relikten führt über die Zuflucht, die bedrängte Bastion der Loyalisten von Stromgarde im zentralen Arathihochland. Malins wichtigster Kontaktmann unter den Verteidigern ist der Zwerg Skuerto. Allerdings wird Die Zuflucht von den umliegenden Gesetzlosen des Syndikats, den Witherbarktrollen und den Boulderfistogern schwer bedrängt. Ankommende Reisende stellen schnell fest, dass Skuerto und die Garnison des Außenpostens viel zu überlastet sind, um ohne sofortige Hilfe einen herzlichen Empfang zu bereiten."}},faq={{q="Wer ist Erzmagier Malin?",a="Erzmagier Malin ist ein erfahrener menschlicher Magier, der im Magiersanktum von Sturmwind residiert. Er war einst ein Lehrling von Erzmagier Trelane aus Stromgarde und koordiniert nun von Sturmwind aus die Bemühungen, die magischen Forschungen seines ehemaligen Meisters zu bergen.",al={"erzmagier malin","wer ist malin","malin sturmwind"}},{q="Warum benötigt Malin Hilfe in Arathi?",a="Stromgarde brach kürzlich unter einer Belagerung zusammen, was Erzmagier Trelane zur Flucht aus dem Turm von Arathor zwang. Malins Agenten in der Region arbeiten daran, Trelanes zurückgelassene magische Relikte zu bergen, sind jedoch überfordert und benötigen Verstärkung.",al={"warum nach arathi","malins auftragsziel","warum arathihochland"}},{q="Wo befindet sich Skuerto?",a="Skuerto ist ein zwergischer Späher, der in der Zuflucht stationiert ist, dem befestigten Lager der Allianz an der Hauptstraße durch das zentrale Arathihochland.",al={"skuerto finden","skuerto standort","wo ist die zuflucht"}},{q="Was geschah mit dem Turm von Arathor?",a="Der Turm von Arathor war eine arkane Redoute innerhalb von Stromgarde. Während des Untergangs des Königreichs versuchte Erzmagier Trelane, die Festung gegen eindringende Schurken des Syndikats und Boulderfistoger zu halten, doch die Verteidigung brach zusammen und er war zur Flucht gezwungen.",al={"fall des turms von arathor","was geschah mit stromgarde","trelanes turm"}},{q="Was geschieht, nachdem man sich bei Skuerto gemeldet hat?",a="Skuerto ist bei Eurer Ankunft überfordert und abweisend und schickt Euch sogleich zu seinen Gefährten in der Zuflucht, um mit der Bergung von Trelanes verstreuten Besitztümern zu beginnen.",al={"malins gesuch folgequest","nächste quest nach malin","skuerto nächste quest"}},{q="Wer ist Erzmagier Trelane?",a="Erzmagier Trelane ist ein prominenter Magier von Stromgarde und der Meister von Erzmagier Malin. Er war einer der wichtigsten Verteidiger der Hauptstadt von Arathi, bevor das Königreich fiel.",al={"erzmagier trelane","wer ist trelane","trelane stromgarde"}}},fx={["5671e9ba"]={q="Warum benötigt Erzmagier Malin für diese Aufgabe einen Abenteurer?",a="Erzmagier Malin ist an seinen Posten im Magiersanktum von Sturmwind weit im Süden gebunden. Obwohl er bereits Agenten in Die Zuflucht im Arathihochland stationiert hat, haben diese berichtet, dass die Lage rund um die gefallene Stadt Stromgarde kritisch ist und Verstärkung erfordert. Ein reisender Abenteurer besitzt die Freiheit, schnell nach Norden zu reisen, und den Kampfgeist, sich in feindselige, umkämpfte Ruinen zu wagen, die offizielle Gesandte nicht so leicht erreichen können.",al={"warum einen abenteurer schicken","warum ich malin","warum geht malin nicht selbst"}}},fp="15,253,26.467.0,37.407.0,22.199.0,35.198.0,25.136.0,38.207.0,40.154.0,24.154.0"}
P.entries["quest:691"] = {n="Das Gewicht in Gold wert",s="In der Zuflucht ist Lehrling Kryten hinter Witherbarkstoßzähnen, Medizinbeuteln und dem Messer eines Schattenjägers her, allesamt Reagenzien für Erzmagier Malin, der ihn und Skuerto entsandte, um sie zu beschaffen. Er bittet Euch, sie bei den Witherbarktrollen im Südosten von Arathi zu suchen.",h="In der Zuflucht ist Lehrling Kryten hinter Witherbarkstoßzähnen, Medizinbeuteln und dem Messer eines...",kw={"lehrling kryten","arathihochland","erzmagier malin","medizinbeutel","die zuflucht","schattenjägermesser","skuerto","witherbark","witherbarkstoßzahn"},sec={{t="Malins Reagenzien",b="Erzmagier Malin entsandte Kryten und Skuerto nach Arathi, um Reagenzien zu sammeln, und Kryten hatte keine Ahnung, wie er sie beschaffen sollte, bis Ihr eintraft. Er benötigt zehn Witherbarkstoßzähne, vier Medizinbeutel und ein Schattenjägermesser. Die Witherbarktrolle sind im Südosten von Arathi beheimatet."},{t="Was die Witherbark bei sich tragen",b="Nach Krytens Nachforschungen sollte jeder Witherbarktroll Stoßzähne besitzen, und die Hexendoktoren tragen die Medizinbeutel bei sich. Das Messer gehört den mächtigsten Schattenjägern, das ihnen überreicht wird, nachdem sie ihre Reifeprüfung abgeschlossen haben. Nur der Kampf wird zeigen, welcher von ihnen eines besitzt."}},faq={{q="Für wen arbeitet Lehrling Kryten?",a="Erzmagier Malin entsandte Kryten und Skuerto nach Arathi, um Reagenzien für ihn zu sammeln.",al={"wer kryten schickte","krytens meister","warum kryten im arathigebirge ist"}},{q="Wo befinden sich die Witherbarktrolle?",a="Im Südosten von Arathi, wo die Witherbarktrolle beheimatet sind.",al={"witherbark aufenthaltsort","wo man witherbark findet"}},{q="Welche Trolle tragen die Medizinbeutel bei sich?",a="Krytens Nachforschungen besagen, dass es die Hexendoktoren der Witherbark sind, die Medizinbeutel bei sich tragen, während jeder Witherbarktroll Stoßzähne besitzen sollte.",al={"medizinbeutel quelle","wer medizinbeutel hat","witherbark medizinbeutel"}},{q="Wie findet Ihr das Schattenjägermesser?",a="Die mächtigsten Witherbarkschattenjäger sollten es besitzen, eine Klinge, die ihnen nach ihren Reifeprüfungen überreicht wird. Welcher von ihnen eines bei sich trägt, wird erst der Kampf offenbaren.",al={"schattenjägermesser aufenthaltsort","wer schattenjägermesser fallen lässt","messer der reifeprüfung"}}},fp="24,263,16.278.0,25.264.0,37.77.0,40.72.0,40.131.0,40.159.0"}
P.entries["quest:692"] = {n="Die verlorenen Fragmente",s="Theldurin der Verirrte ist wegen der Rolle von Myzrael in Panik. Ihre Magie könnte Myzrael an die Oberfläche zerren, doch falls sie bereits frei ist, könnte die Rolle der einzige Weg sein, sie wieder zu binden. Wütende Elementare haben sie zerrissen und streiten um die Überreste, und Ihr werdet losgeschickt, um sie zu sammeln.",h="Theldurin der Verirrte ist wegen der Rolle von Myzrael in Panik.",kw={"ödland","zerknülltes rollenfragment","elementare","myzrael","rolle von myzrael","versengtes rollenfragment","theldurin der verirrte","zerrissenes rollenfragment"},sec={{t="Ein gefährliches Pergament",b="Theldurin der Verirrte ist bei der Erwähnung der Rolle von Myzrael alarmiert und fürchtet, ihre Magie könnte Myzrael an die Oberfläche ziehen. Dann ändert er seine Meinung: Wenn sie bereits entwischt ist oder Kräfte für einen Angriff sammelt, ist die Rolle genau das, was Ihr brauchen werdet, um sie wieder einzufangen."},{t="Von den Elementen zerrissen",b="Die Rolle ist nicht mehr ganz. Wütende Elementare haben sie an sich genommen, in Stücke gerissen und streiten nun um die Fetzen. Ihr seid hinter drei Teilen her, einem zerrissenen, einem zerknüllten und einem versengten, und Theldurin will versuchen, sie zusammenzufügen. Die Diebe streifen durch die Hügel hinter Theldurin."}},faq={{q="Wer schickt Euch aus, um die Rollenfragmente zu sammeln?",a="Theldurin der Verirrte bittet Euch, die Teile der zerstörten Rolle zurückzubringen.",al={"questgeber","wer startet the lost fragments","theldurin quest"}},{q="Was soll die Rolle von Myzrael bewirken?",a="Theldurin sagt, ihre Magie könnte Myzrael an die Oberfläche ziehen. Theldurin glaubt auch, dass sie genau das ist, was Ihr brauchen würdet, um sie wieder einzufangen, falls sie bereits frei ist.",al={"was bewirkt die rolle","rolle von myzrael lore","warum rollenfragmente finden"}},{q="Wo sind die Rollenfragmente?",a="Wütende Elementare haben die Rolle fortgeschleppt, zerrissen und streiten um die Teile. Sie befinden sich in den Hügeln hinter Theldurin.",al={"wer hat die fragmente","wo man die rollenteile findet","ort der rollenfragmente"}},{q="Was kommt vor dieser Quest?",a="Sie folgt auf Eure früheren Begegnungen mit Theldurin dem Verirrten.",al={"vorherige quest","voraussetzung für the lost fragments"}}},fp="18,284,21.279.0,20.262.0,46.77.0,45.159.0,31.122.0,29.57.0"}
P.entries["quest:6921"] = {n="Inmitten der Ruinen",s="Im Auftrag von Je'neu Sancrea am Außenposten von Zoram'gar tauchen Abenteurer der Horde in den überfluteten Tempel der Tiefschwarzen Grotte ein, um einen Fathomkern zu bergen. Der Irdene Ring sucht dieses Relikt, um die finsteren Elementarpläne des eindringenden Schattenhammer-Kults aufzudecken.",h="Im Auftrag von Je'neu Sancrea am Außenposten von Zoram'gar tauchen Abenteurer der Horde in den überfluteten...",kw={"inmitten der ruinen","eschental","tiefschwarze grotte","der irdene ring","tiefenkern","fathomstein","je'neu sancrea","moonshrine ruins","schattenhammer","außenposten von zoram'gar"},ang={["class:Shaman"]="Die Bergung des Fathomkerns dient direkt der Mission des Irdenen Rings, die Geister des Wassers und der Erde davor zu schützen, vom Schattenhammer unterworfen zu werden.",["faction:Horde"]="Indem Ihr Bedrohungen in der Tiefschwarzen Grotte beseitigt, schützt Ihr den Außenposten von Zoram'gar und sichert den umkämpften Stützpunkt der Horde an der Küste von Eschental.",["race:Troll"]="Die Unterstützung von Je'neu Sancrea hilft einem Dunkelspeergenossen, der die Brücke zwischen der Horde und den elementaren Hütern des Irdenen Rings schlägt."},sec={{t="Eine Bedrohung in der Tiefe",b="Der uralte Nachtelfentempel der Tiefschwarzen Grotte, einst Elune geweiht, ist unter die Herrschaft finsterer Mächte gefallen. Tief in seinen überfluteten Gängen haben die Kultisten des Schattenhammers eine Festung errichtet. Am windgepeitschten Ufer des Zoram'gar-Außenpostens in Eschental beobachtet der Dunkelspeerschamane Je'neu Sancrea das wachsende Verderben mit zunehmender Beunruhigung und erkennt, dass der Kult beabsichtigt, die örtlichen Elemente gegen das Land und seine Verteidiger zu unterwerfen."},{t="Der Fathomstein",b="Um den Absichten des Kults entgegenzuwirken, beauftragt Je'neu die Champions der Horde damit, einen Fathomkern aus dem unter Wasser liegenden Fathomstein in den Moonshrine Ruins zu bergen. Wenn er von erfahrenen Schamanen korrekt entschlüsselt wird, offenbart der Kern eine umfassende Chronik der elementaren Strömungen und Störungen. Mit diesem Artefakt in Händen hofft Der Irdene Ring, den Schleier über den Operationen des Schattenhammers zu lüften und die Region vor einer elementaren Katastrophe zu bewahren."}},faq={{q="Wer vergibt die Quest Inmitten der Ruinen?",a="Die Quest wird von Je'neu Sancrea vergeben, einem Trollvertreter des Irdenen Rings, der am Außenposten von Zoram'gar am Zoramstrand im westlichen Eschental stationiert ist.",al={"questgeber","wo quest annehmen","wer startet inmitten der ruinen"}},{q="Was ist ein Fathomkern?",a="Ein Fathomkern ist ein spezielles Artefakt, das in einem versunkenen Fathomstein in den Ruinen ruht. Wenn er von Schamanen gelesen wird, liefert er eine umfassende Geschichte elementarer Aktivitäten und enthüllt, wie die örtlichen Elemente unterworfen und manipuliert werden.",al={"was ist der fathomkern","zweck des fathomsteins","was macht der kern"}},{q="Warum sorgt sich Der Irdene Ring um die Tiefschwarze Grotte?",a="Der Irdene Ring strebt nach dem Gleichgewicht zwischen den natürlichen Elementen. Die Kultisten des Schattenhammers, die die überfluteten Ruinen eingenommen haben, verderben und erzwingen aktiv den Gehorsam der Elemente für ihre finsteren Zwecke, was die Stabilität der gesamten Region bedroht.",al={"motiv des irdenen rings","warum kümmert sich der irdene ring","blackfathom-tiefe kultisten"}},{q="Wo befindet sich der Fathomstein?",a="Der Fathomstein liegt unter Wasser in den Moonshrine Ruins innerhalb der Tiefschwarzen Grotte, sodass Forscher unter die Oberfläche tauchen müssen, um den Kern zu bergen.",al={"wo ist der stein","fathomkern fundort","moonshrine ruins fathomkern"}},{q="Können Allianzspieler diese Quest annehmen?",a="Nein. Die Quest ist exklusiv für die Horde, da Je'neu Sancrea vom Horde-Außenposten Zoram'gar aus agiert und neben seinen Pflichten für den Irdenen Ring auch die strategische Präsenz der Horde in Eschental unterstützt.",al={"nur für die horde","allianz-version","kann allianz inmitten der ruinen machen"}},{q="Welche Gruppe hält die Tiefschwarze Grotte besetzt?",a="Der höhlenartige Tempelkomplex wurde vom Schattenhammer eingenommen, einem apokalyptischen Kult, der sich dem Dienst an finsteren Wesenheiten der Alten Götter verschrieben hat und die Elemente für katastrophale Zwecke missbraucht.",al={"wer ist in blackfathom","feinde in bfd","schattenhammer blackfathom"}}},fx={["139b4a2b"]={q="Warum will Je'neu Sancrea, dass der Tiefenkern geborgen wird?",a="Je'neu Sancrea befürchtet, dass die Kultisten des Schattenhammers, die die Tiefschwarze Grotte besetzt halten, die lokalen Elemente dazu zwingen werden, sich gegen die Region und die Horde zu wenden. Ohne den Tiefenkern ist Der Irdene Ring blind gegenüber den Ritualen und elementaren Störungen, die der Kult tief unter den Ruinen durchführt.",al={"jeneu sancreas motiv","warum fathom core holen","warum amongst the ruins"}}},fp="17,251,20.481.0,16.434.0,38.159.0,22.241.0,58.254.0,34.166.0,37.193.0,42.189.0"}
P.entries["quest:6922"] = {n="Baron Aquanis",s="Nach dem Sieg über das Wasserelementar Baron Aquanis in der Tiefschwarzen Grotte erbeuten Abenteurer eine Seltsame Wasserkugel, die eine verderbte, faulige Flüssigkeit enthält. Zu Je'neu Sancrea vom Irdenen Ring gebracht, liefert das Artefakt entscheidende Beweise für die elementare Verderbnis, die sich unter Eschental ausbreitet. Je'neu glaubt, dass sie beweisen wird, was den Baron verdorben hat, und er wäre nicht überrascht, wenn die Kultisten des Schattenhammers dahinterstecken, die in den versunkenen Ruinen lauern.",h="Nach dem Sieg über das Wasserelementar Baron Aquanis in der Tiefschwarzen Grotte erbeuten Abenteurer eine...",kw={"eschental","baron aquanis","tiefschwarze grotte","der irdene ring","elementare verderbnis","je'neu sancrea","seltsame wasserkugel","schattenhammer","der zoramstrand"},ang={["class:Shaman"]="Der Irdene Ring betrachtet die Verderbnis von Elementargeistern als schwerwiegenden Verstoß gegen die natürliche Ordnung. Die Untersuchung von Baron Aquanis' verdorbenem Zustand ist von zentraler Bedeutung für die Wiederherstellung des elementaren Gleichgewichts.",["faction:Horde"]="Je'neu Sancrea stimmt sich mit Kundschaftern der Horde am Außenposten von Zoram'gar ab und sucht mutige Recken, um die verdorbenen Gewässer zu reinigen, die unter der Küste von Eschental lauern."},sec={{t="Ein verdorbenes Herz",b="Baron Aquanis war kein gewöhnlicher Wassergeist, sondern ein mächtiges Elementar, das durch üble Zauberei in den überfluteten Grotten der Tiefschwarzen Grotte verdorben wurde. Nach seiner Vernichtung hinterlässt das Elementar eine Seltsame Wasserkugel – eine unzerstörbare Kugel, in der eine schwappende, faulige Flüssigkeit schwimmt, die anscheinend die natürliche Essenz der Kreatur aufrechterhalten und verzerrt hat. Der Gegenstand widersteht physischem Schaden und birgt Energien in sich, die für jene, die auf das Gleichgewicht der Elemente eingestimmt sind, zutiefst verstörend wirken."},{t="Studien des Irdenen Rings",b="Je'neu Sancrea, ein am Zoramstrand stationierter Schamane des Irdenen Rings, erkennt das Artefakt sofort als Beweis für unnatürliche Einmischung an. Er und sein Orden vermuten schon lange, dass Baron Aquanis finsteren Mächten zum Opfer gefallen ist, und deuten direkt auf die Kultisten des Schattenhammers, die den versunkenen Tempel besetzen. Durch das Studium der Kugel hofft Je'neu, nicht nur die Schuld des Kults nachzuweisen, sondern auch die genauen dunklen Methoden aufzudecken, mit denen sie die Elementargeister von Azeroth unterjochen und verzerren."}},faq={{q="Was ist Baron Aquanis?",a="Baron Aquanis ist ein mächtiges Wasserelementar, das die unterirdischen Gewässer der Tiefschwarzen Grotte bewohnt. Anstatt frei umherzustreifen, wurde Aquanis von den finsteren Anwendern verdorben und gebunden, die im ruinierten Tempelkomplex hausen.",al={"wer ist aquanis","aquanis boss","baron aquanis lore"}},{q="Was ist die Seltsame Wasserkugel?",a="Die Seltsame Wasserkugel ist eine unzerstörbare Sphäre, die nach dem Sieg über Baron Aquanis zurückbleibt. In ihrem Inneren schwappt eine faulige, eiternde Flüssigkeit umher, die als Quelle der verderbten Energie diente, welche den finsteren Zustand des Elementars nährte.",al={"wasserkugel","seltsame wasserkugel","aquanis questgegenstand"}},{q="Warum will Je'neu Sancrea die Kugel haben?",a="Als Mitglied des Irdenen Rings überwacht Je'neu Sancrea elementare Störungen in ganz Eschental. Er untersucht die Kugel, um zu bestätigen, ob der Schattenhammer hinter der Verderbnis steckt, und um die Rituale zu entschlüsseln, mit denen die Geister verzerrt wurden.",al={"warum zu jeneu bringen","jeneu sancrea zweck"}},{q="Wer steckt hinter der Verderbnis von Baron Aquanis?",a="Die Hauptverdächtigen sind die Kultisten des Schattenhammers, die tief in der Tiefschwarzen Grotte nisten. Ihre Anwesenheit im Tempel passt zu einem Feldzug der Entweihung und dunkler Zwiesprache mit unnatürlichen Wesen.",al={"wer verdarb aquanis","aquanis schattenhammer","kultisten blackfathom"}},{q="Wo befindet sich Je'neu Sancrea?",a="Je'neu Sancrea ist ein Schamane des Irdenen Rings, der am Zoramstrand an der nordwestlichen Küste von Eschental lagert, nahe dem Eingang zum Höhlensystem der Tiefschwarzen Grotte.",al={"wo ist jeneu","aquanis quest abgeben","wo seltsame wasserkugel abgeben"}},{q="Was folgt nach der Abgabe dieser Quest?",a="Die Übergabe der Kugel führt direkt zu weiteren Nachforschungen über die elementare Not der Region und veranlasst Abenteurer dazu, dem Irdenen Ring weiterhin gegen die wachsende Plage beizustehen.",al={"folgequest","elementare not"}}},fp="13,454,17.461.0,27.500.1,22.235.0,32.221.0,39.238.0,46.203.0,32.170.0,39.192.0"}
P.entries["quest:693"] = {n="Zauberstab gegen Faust",s="Skuerto in der Zuflucht hat herausgefunden, wo der erste von Trelanes Gegenständen gelandet ist. Kor'gresh hat Trelanes Zauberstab der Herbeirufung in der Halle der Felsfäuste, und Skuerto möchte, dass er zurückgebracht wird.",h="Skuerto in der Zuflucht hat herausgefunden, wo der erste von Trelanes Gegenständen gelandet ist.",kw={"arathihochland","halle der felsfäuste","korgresh","die zuflucht","skuerto","stromgarde","thandol-übergang","trelane","zauberstab der herbeirufung","wand over fist"},sec={{t="Der Oger und der Zauberstab",b="Nach Eurer Arbeit für Lehrling Kryten hat Skuerto herausgefunden, wo Trelanes erster Gegenstand geblieben ist. Kor'gresh hält ihn in der Halle der Felsfäuste und hat Eisschocks auf seine eigene Sippe geschleudert, um sie auf Linie zu halten. Skuerto vermutet, dass der Oger kurz davor sein muss, alle Kräfte des Zauberstabs zu durchschauen. Die Halle der Felsfäuste liegt südlich der Zuflucht und dann östlich des Thandol-Übergangs."},{t="Skuertos Liste",b="Bei Eurer Rückkehr verbucht Skuerto laut seiner Liste den Zauberstab als einen Gegenstand erledigt und noch drei weitere offen. Die anderen drei befinden sich alle in Stromgarde."}},faq={{q="Wer gibt die Quest Wand over Fist?",a="Skuerto, in der Zuflucht im Arathihochland.",al={"questgeber für wand over fist","wer startet wand over fist","wo bekommt man wand over fist"}},{q="Wo befindet sich Kor'gresh?",a="Kor'gresh ist in der Halle der Felsfäuste, die südlich der Zuflucht und dann östlich des Thandol-Übergangs liegt.",al={"wo ist korgresh","aufenthaltsort von korgresh","korgresh finden"}},{q="Welcher Gegenstand muss geborgen werden?",a="Trelanes Zauberstab der Herbeirufung, der erste von Trelanes Gegenständen. Kor'gresh hat damit Eisschocks auf seine Sippe geschleudert.",al={"welchen gegenstand hat kor'gresh","welcher zauberstab","trelane zauberstab"}},{q="Welche Voraussetzungen sind für diese Quest erforderlich?",a="Sie folgt auf Worth Its Weight in Gold, die Arbeit, die Ihr für Lehrling Kryten geleistet habt.",al={"wand over fist voraussetzungen","voraussetzungen für wand over fist","vorherige quest zu wand over fist"}}},fp="14,183,21.359.0,14.140.1,35.50.0,27.98.0,32.121.0,45.76.0"}
P.entries["quest:694"] = {n="Trelanes Verteidigung",s="Mit dem Zauberstab in der Hand wendet sich Skuerto den Ogern zu, die den Turm von Arathor umgeben. Um die Verteidigungsanlagen des Turms zum Leben zu erwecken, benötigt er einen Azurachat von den Schamanen der Boulderfist, der zu Lehrling Kryten in der Zuflucht gebracht werden muss.",h="Mit dem Zauberstab in der Hand wendet sich Skuerto den Ogern zu, die den Turm von Arathor umgeben.",kw={"lehrling kryten","azurachat","schamane der boulderfist","die zuflucht","skuerto","stromgarde","der turm von arathor","trelane's defenses"},sec={{t="Die Verteidigungsanlagen des Turms",b="Oger umgeben den Turm von Arathor in Stromgarde. Skuerto sagt, dass die Verteidigungsanlagen des Turms aktiviert werden müssen, wenn Ihr eine Chance gegen sie haben und die Gegenstände noch lebend erreichen wollt."},{t="Ein Edelstein als Schlüssel",b="Bestimmte Edelsteine aus dem Turm haben das Gefallen der Schamanen der Boulderfist geweckt, die sie weggeschleppt haben, obwohl Skuerto sagt, dass sie sie nicht lange behalten werden. Bringt einen Azurachat zu Lehrling Kryten in der Zuflucht, der den Zauber kennt, um ihn so zu verzaubern, dass er als Schlüssel fungiert."}},faq={{q="Warum wird ein Azurachat benötigt?",a="Skuerto möchte, dass die Verteidigungsanlagen des Turms aktiviert werden, damit Ihr Euch den Ogern um den Turm von Arathor stellen und die Gegenstände noch lebend erreichen könnt. Verzaubert wird der Edelstein als Schlüssel dienen.",al={"warum azurachat","zweck von trelanes verteidigung","warum den edelstein holen"}},{q="Woher kamen die Azurachate?",a="Die Schamanen der Boulderfist haben sie aus dem Turm von Arathor weggeschleppt und Gefallen an ihnen gefunden.",al={"wer hat die achate gestohlen","woher stammen die edelsteine","ursprung des achats"}},{q="Wer kann den Edelstein verzaubern?",a="Lehrling Kryten in der Zuflucht kennt den Zauber, um den Edelstein so zu verzaubern, dass er als Schlüssel fungiert.",al={"wer verzaubert den achat","krytens rolle","wer verwandelt ihn in einen schlüssel"}}},fp="18,228,20.177.0,15.274.0,29.170.0,37.94.0,24.96.0"}
P.entries["quest:695"] = {n="Des Lehrlings Verzauberung",s="Lehrling Kryten hat den Achat verzaubert, den Ihr ihm von den Boulderfist-Schamanen gebracht habt. Wenn er an einen Sockel am Fuße des Turms gehalten wird, erweckt er die Verteidigung des Turms. Bevor Ihr aufbrecht, schickt er Euch für den Rest zu Skuerto.",h="Lehrling Kryten hat den Achat verzaubert, den Ihr ihm von den Boulderfist-Schamanen gebracht habt.",kw={"lehrling kryten","arathihochland","verzauberter achat","skuerto","turm","trelane"},sec={{t="Ein Schlüssel für den Turm",b="Kryten überreicht Euch den verzauberten Edelstein. Er erklärt, dass das Berühren eines Sockels am Fuße des Turms mit dem Edelstein die Verteidigung des Turms erwecken wird und dass Ihr ihn verwenden solltet, wenn Ihr bereit seid hineinzugehen, um die restlichen Gegenstände von Trelane zu holen. Er wird Eure Rückkehr im Lager erwarten. Sprecht zuerst mit Skuerto, der Euch alles Weitere erklären wird, was Ihr wissen müsst."}},faq={{q="Was ist der Zweck des verzauberten Achats?",a="An einen Sockel am Fuße des Turms gehalten, erweckt er die Verteidigung des Turms. Ihr benutzt ihn, wenn Ihr bereit seid hineinzugehen, um die restlichen Gegenstände von Trelane zu holen.",al={"warum brauche ich den achat","verwendung verzauberter achat","was macht der edelstein"}},{q="Mit wem müsst Ihr sprechen, bevor Ihr das Lager verlasst?",a="Skuerto. Kryten sagt Euch, dass Ihr vor Eurem Aufbruch mit ihm sprechen sollt, da er Euch alles Weitere erklären wird, was Ihr wissen müsst.",al={"mit wem sprechen","wohin als naechstes","wer ist skuerto"}},{q="Wo wird Kryten sein?",a="Er wird Eure Rückkehr im Lager erwarten.",al={"wo ist kryten","kryten wartet"}}},fp="27,225,19.338.0,43.152.0,47.110.0,21.44.0"}
P.entries["quest:696"] = {n="Angriff auf den Turm",s="Da die Verteidigung des Turms erwacht ist, schickt Euch Skuerto in der Zuflucht in den von Ogern besetzten Turm, um Trelanes Phylakterium, Kugel und Ember Agate zu holen. Sie sollten sich in Truhen im Inneren befinden, und Skuerto sagt, dass Malin mehr als erfreut sein wird, wenn Ihr sie zurückbringt.",h="Da die Verteidigung des Turms erwacht ist, schickt Euch Skuerto in der Zuflucht in den von Ogern besetzten...",kw={"arathihochland","angriff auf den turm","malin","oger","die zuflucht","skuerto","trelane","trelanes ember agate","trelanes orb","trelanes phylactery"},sec={{t="In den Turm",b="Nach Krytens Verzauberung sagt Euch Skuerto, wonach Ihr suchen sollt: Trelanes Phylakterium, Kugel und Ember Agate. Die drei Gegenstände sollten sich in Truhen im Inneren des Turms befinden, und es dürfte Euch keine Mühe bereiten, sie selbst zu öffnen, auch wenn die Oger zur Vorsicht mahnen. Die Verteidigung des Turms wird sich nicht von selbst um sie kümmern, und wenn die Oger bemerken, dass Ihr sie bestehlt, werden sie Euch Schmerzen zufügen."},{t="Skuertos Urteil",b="Wenn Ihr die drei Gegenstände zurückbringt, sagt Skuerto, dass Malin sich keine würdigere Person hätte wünschen können, um ihnen hier beizustehen. Malin wird hocherfreut darüber sein zu erfahren, wie vollkommen ihr Vorhaben geglückt ist."}},faq={{q="Wer vergibt diese Aufgabe?",a="Skuerto in der Zuflucht im Arathihochland, sobald Kryten den Edelstein verzaubert hat.",al={"wer vergibt angriff auf den turm","questgeber angriff auf den turm","wo bekommt man angriff auf den turm"}},{q="Welche Gegenstände sollt Ihr beschaffen?",a="Trelanes Phylakterium, Kugel und Ember Agate. Jeder Gegenstand sollte sich in einer Truhe im Inneren des Turms befinden.",al={"gegenstände für angriff auf den turm","welche relikte beschaffen","trelanes gegenstände"}},{q="Was werden die Oger tun?",a="Die Verteidigung des Turms wird sich nicht für Euch um sie kümmern. Wenn die Oger herausfinden, dass Ihr sie bestehlt, werden sie Euch Schmerzen zufügen.",al={"sind die oger gefährlich","turmoger"}},{q="Was geht dem voraus?",a="Es folgt auf An Apprentice's Enchantment, worin Kryten den Edelstein verzaubert und Euch zu Skuerto schickt.",al={"angriff auf den turm voraussetzung","welche quest kommt zuerst"}}},fp="19,246,14.384.0,17.189.1,22.85.0,36.86.0,23.137.0,23.98.0"}
P.entries["quest:6962"] = {n="Leckereien für Altvater Winter",s="Leckereien für Altvater Winter ist eine festliche Feiertagsbitte, die während des Winterhauchfests in Orgrimmar angeboten wird. Die fröhliche Symbolfigur am Stand von Kokelwälder verspürt nach dem Anhören unzähliger Feiertagswünsche Erschöpfung und bittet einen hilfsbereiten Abenteurer um frische Lebkuchen und Milch.",h="Leckereien für Altvater Winter ist eine festliche Feiertagsbitte, die während des Winterhauchfests in...",kw={"lebkuchen","altvater winter","festtagsgewürze","eiskalte milch","orgrimmar","kokelwälder","leckereien für altvater winter","winterhauch"},ang={["faction:Horde"]="Von den geschäftstüchtigen Goblins von Kokelwälder nach Orgrimmar gebracht, verleiht das Fest der rauen Kriegerstadt einen seltenen Moment unbeschwerter, heimeliger Freude.",["profession:Cooking"]="Diese Feiertagstradition bietet Kochanfängern eine einfache Gelegenheit, grundlegendes Backen zu üben und wilde Eier sowie saisonale Gewürze in festliche Lebkuchen zu verwandeln."},sec={{t="Ein müder Schirmherr des Winters",b="Während Altvater Winter in ganz Azeroth den mythischen Geist des Winters und des Überflusses verkörpert, ist die Gestalt, die Besucher im Tal der Stärke begrüßt, ein hart arbeitender Darsteller im Dienst von Kokelwälder. Durch lange Schichten zu sitzen und hoffnungsvollen Bürgern beim Schwärmen von festlichen Leckereien zuzuhören, regt verständlicherweise den Appetit an. Da er es leid ist, bloß über saisonale Köstlichkeiten zu reden, spannt der Altvater gerne vorbeiziehende Reisende ein, um sein Verlangen nach warmem Gebäck und einem kalten Getränk zu stillen."},{t="Kulinarische Festtagsstimmung",b="Die Bitte des Altvaters zu erfüllen, erfordert eine Prise heimischer Kochkunst. Abenteurer müssen Festtagsgewürze beschaffen, die direkt von den Goblin-Händlern von Kokelwälder verkauft werden, kleine Eier von wilden Vögeln in der Wildnis sammeln und klassische Lebkuchen backen. Zusammen mit einem Krug Eiskalter Milch aus einer örtlichen Taverne belohnt die bescheidene Gabe den Bäcker mit Festtagsfreude und einem kleinen Zeichen der Dankbarkeit der Festorganisatoren."}},faq={{q="Wer ist Altvater Winter in Orgrimmar?",a="Er ist ein von Kokelwälder engagierter Schauspieler, der während des Winterhauchfests den legendären Altvater Winter darstellt. An ihrem Feiertags-Handelsstand im Tal der Stärke sitzend, begrüßt er die Bürger der Horde, nimmt Festtagswünsche entgegen und verbreitet saisonale Fröhlichkeit.",al={"wer ist altvater winter","orgrimmar altvater winter","ist er der echte wintervater"}},{q="Nach welchen Leckereien verlangt Altvater Winter?",a="Altvater Winter bittet um fünf frisch gebackene Lebkuchen und eine Portion Eiskalte Milch, um einen langen, anstrengenden Tag voller Feiertagsbesucher zu überstehen.",al={"was möchte er","gewünschte leckereien","welche kekse braucht er"}},{q="Wie stellt man Lebkuchen her?",a="Das Rezept und die festlichen Gewürze werden von Händlern von Kokelwälder rund um den Festtagsstand verkauft. Bäcker kombinieren Festtagsgewürze mit kleinen Eiern von Wildvögeln und backen die Kekse anschließend an einem Kochfeuer.",al={"lebkuchen bekommen","lebkuchenrezept","keks-zutaten"}},{q="Wo gibt es Eiskalte Milch?",a="Eiskalte Milch kann bei nahezu jedem Nahrungsmittel- und Getränkehändler, Gastwirt oder Schankwirt in ganz Orgrimmar sowie in anderen größeren Siedlungen erworben werden.",al={"wo gibt es eiskalte milch","milch kaufen","milchhändler"}},{q="Warum bittet Altvater Winter selbst um Essen?",a="Kindern und Bürgern den ganzen Tag beim Plaudern über Essen, Geschenke und Festlichkeiten zuzuhören, macht den Darsteller ausgesprochen hungrig. Da er seinen Posten im Tal der Stärke nicht ohne Weiteres verlassen kann, bittet er vorbeikommende Abenteurer um eine schnelle Stärkung.",al={"warum will er leckereien","ist altvater winter hungrig"}},{q="Gibt es für diese Quest ein Gegenstück bei der Allianz?",a="Ja. Eine identische Bitte äußert der in Eisenschmiede stationierte Altvater Winter, der während des Fests Champions der Allianz gleichermaßen um Lebkuchen und kalte Milch bittet.",al={"allianz-version","eisenschmiede leckereien"}}},fx={["87543d9b"]={q="Wofür sind die Lebkuchen und die Eiskalte Milch?",a="Smokywood Pastures lässt Altvater Winter den ganzen Tag draußen sitzen, um die Festbesucher zu begrüßen, und die Feiertagsstimmung macht hungrig. Die frischen Lebkuchen und der erfrischende Krug mit Eiskalter Milch sind einfach ein bescheidener, tröstender Snack, um seine Stimmung hochzuhalten, während er sich in Orgrimmar die Feiertagswünsche der Besucher anhört.",al={"warum milch und kekse","verwendung von lebkuchen","eiskalte milch winterhauchfest"}},["1b7dc40f"]={q="Warum bittet Altvater Winter Euch, anstatt die Leckereien selbst zu holen?",a="Altvater Winter sitzt fest auf seinem festlichen Sitz im Tal der Stärke und unterhält Gäste und verbreitet während des Winterhauchfests Feiertagsfreude. Seinen Posten zu verlassen, um einkaufen zu gehen oder Leckereien zu backen, würde die Besucher enttäuschen und die Feierlichkeiten stören, also verlässt er sich darauf, dass vorbeikommende Abenteurer die Besorgungen erledigen.",al={"warum braucht mich altvater winter","warum kann altvater winter keine milch holen","warum abenteurer nach leckereien fragen"}}},fp="30,298,24.478.0,23.452.0,39.285.0,44.177.0,36.224.0,33.144.0,50.248.0,45.180.0"}
P.entries["quest:697"] = {n="Malins Gesuch",s="Skuerto überreicht Euch einen versiegelten Brief für Erzmagier Malin, der sich im Mage Quarter von Sturmwind aufhält. Darin wird Malin mitgeteilt, dass Kryten und Skuerto bald nach Hause zurückkehren werden, und Skuerto ist sich sicher, dass Malin Euch für Eure Hilfe in Arathi reich entlohnen wird.",h="Skuerto überreicht Euch einen versiegelten Brief für Erzmagier Malin, der sich im Mage Quarter von Sturmwind...",kw={"arathihochland","erzmagier malin","kryten","mage quarter","malin's request","versiegelter brief","skuerto","sturmwind"},sec={{t="Ein Brief für den Erzmagier",b="Nach der Arbeit in Arathi händigt Euch Skuerto einen Brief aus, den Ihr nach Sturmwind zurückbringen sollt. Seine Botschaft an Erzmagier Malin im Mage Quarter lautet, dass Kryten und Skuerto bald nach Hause zurückkehren werden. Skuerto zweifelt nicht daran, dass Malin Euch für Eure Hilfe gut entlohnen wird, und verabschiedet Euch mit den Wünschen für eine sichere Reise."},{t="Malin liest den Brief",b="Als Malin den Brief öffnet, weiten sich seine Augen. Er ist hocherfreut und sagt, Trelane werde überglücklich sein. Er vermutet, dass Kryten und Skuerto seine Begeisterung teilen, da sie sich nun auf den Heimweg nach Sturmwind machen."}},faq={{q="Wer schickt Euch mit dem Brief?",a="Skuerto tut dies. Der Brief teilt Malin mit, dass er und Kryten bald nach Hause zurückkehren werden.",al={"wer übergibt den brief","wer startet malins request","malins request questgeber"}},{q="Wo befindet sich Erzmagier Malin?",a="Erzmagier Malin befindet sich im Mage Quarter von Sturmwind.",al={"wo ist erzmagier malin","standort von erzmagier malin","wo abgeben"}},{q="Wer ist Kryten?",a="Kryten ist Skuertos Gefährte im Arathihochland. Skuerto sagt, dass die beiden bald nach Hause zurückkehren werden.",al={"wer ist kryten","kryten arathi"}},{q="Was geht diesem Schritt voraus?",a="Es folgt auf Attack on the Tower, die Arbeit, um die Euch Skuerto am Turm in Arathi gebeten hatte.",al={"vorherige quest","voraussetzung","was führt hierher"}}},fp="15,230,25.296.0,22.199.1,30.74.0,32.51.0,14.102.0,28.85.0"}
P.entries["quest:698"] = {n="Mangelnde Reserven",s="Dar sammelt Vorräte für den Außenposten am Strand im Osten, wo Tok'Kar zwischen Wachschichten und dem Kochen für die Soldaten kaum Zeit übrig hat. Dar bittet Euch, Tok'Kar eine Lieferung Sägezahnfleisch zu bringen.",h="Dar sammelt Vorräte für den Außenposten am Strand im Osten, wo Tok'Kar zwischen Wachschichten und dem Kochen...",kw={"dar","flanke","fleisch","außenposten","sägezahn","sümpfe des elends","tok'kar"},sec={{t="Vorräte für die Küste",b="Dar sammelt Vorräte für den Außenposten am Strand im Osten. Tok'Kar tut dort, was möglich ist, doch Wachschichten und das Kochen für die Soldaten lassen am Tag kaum Zeit. Die Soldaten kochen gern Sägezahnfleisch, wenn sie welches bekommen können, und Dar hatte keine Zeit, ihnen eine weitere Lieferung zu schicken."},{t="Die Wahl des Fleisches",b="Dar warnt Euch davor, die jungen Sägezähne anzurühren, denn die älteren schmecken besser. Die Jungen brauchen ein oder zwei Jahre, um ihre volle Größe zu erreichen. Acht unzubereitete Sägezahnflanken werden verlangt, die zu Tok'Kar in den Sümpfen des Elends gebracht werden sollen."}},faq={{q="Wer verlangt das Sägezahnfleisch?",a="Dar, der Vorräte für den Außenposten am Strand im Osten sammelt.",al={"wer gibt lack of surplus","wer startet lack of surplus","dar sümpfe des elends"}},{q="Wo ist Tok'Kar stationiert?",a="Am Außenposten am Strand im Osten, von dem Dar spricht. Das Fleisch soll dort zu Tok'Kar in den Sümpfen des Elends gebracht werden.",al={"wo ist tok'kar","tokkar aufenthaltsort","tok'kar außenposten"}},{q="Warum braucht Tok'Kar andere, die Fleisch bringen?",a="Zwischen Wachschichten und dem Kochen für die Soldaten bleibt Tok'Kar am Tag kaum Zeit übrig.",al={"warum braucht tok'kar fleisch","warum schickt dar nahrung"}},{q="Welche Sägezähne sollten gejagt werden?",a="Die älteren. Die Jungen sind weniger schmackhaft und brauchen ein oder zwei Jahre, um ihre volle Größe zu erreichen.",al={"welche sägezähne","welche sägezähne lassen fleisch fallen","sägezahnflanke quelle"}},{q="Wie viele Flanken werden benötigt?",a="Acht unzubereitete Sägezahnflanken, die zu Tok'Kar gebracht werden sollen.",al={"wie viele flanken","unzubereitete sägezahnflanke anzahl"}},{q="Was kommt als Nächstes in der Reihe?",a="Ein zweiter Schritt unter demselben Namen folgt.",al={"nächste quest lack of surplus","lack of surplus folgequest"}}},fp="15,216,22.299.0,17.220.0,36.72.0,27.130.0,43.91.0,33.84.0,27.53.0,29.42.0"}
P.entries["quest:6981"] = {n="Der leuchtende Splitter",s="Der leuchtende Splitter ist ein geheimnisvoller, smaragdfarbener Edelstein, der aus den finsteren Tiefen der Höhlen des Wehklagens geborgen wurde. Unter seiner polierten Oberfläche wirbelt eine rauchige Essenz; dieses beunruhigende Relikt treibt Abenteurer dazu, in Ratschet und darüber hinaus nach Antworten zu suchen.",h="Der leuchtende Splitter ist ein geheimnisvoller, smaragdfarbener Edelstein, der aus den finsteren Tiefen der...",kw={"brachland","druiden des giftzahns","smaragdgrüner alptraum","falla weisenwind","leuchtender splitter","ratschet","stotterspritter","die höhlen des wehklagens"},ang={["class:Druid"]="Für Druiden sind der smaragdgrüne Glanz und der rauchige Kern des Splitters ein düsterer Beweis dafür, dass der Smaragdgrüne Alptraum durch ihre gefallenen Brüder in den Höhlen des Wehklagens in die wache Welt einsickert.",["faction:Alliance"]="Selbst fern der Heimat in Kalimdor erkennen die Forscher der Allianz die globale Gefahr, die von der dunklen Macht ausgeht, welche die Natur unter dem Brachland verdirbt.",["faction:Horde"]="Das Geheimnis des Splitters zu lüften, trägt dazu bei, die lebenswichtigen Kreuzungen und Handelsrouten des Brachlands vor unnatürlichen Bedrohungen zu schützen, die in den unterirdischen Quellen schwelen.",["race:Tauren"]="Das Gleichgewicht des Brachlands liegt den Shu'halo am Herzen, und dieses unnatürliche Relikt zu Falla Weisenwind zu bringen, hilft dabei, die Verderbnis zu verstehen, die ihre angestammten Länder vergiftet."},sec={{t="Eine beunruhigende Entdeckung",b="Aus den Tiefen der Höhlen des Wehklagens geborgen, verunsichert der leuchtende Splitter sofort jeden, der ihn in Händen hält. Leuchtend grün und scheinbar fest, birgt er unter seiner kristallinen Oberfläche wogende, nebelartige Schatten. Der Kristall übt eine subtile Anziehungskraft aus, verlangt Aufmerksamkeit und strahlt dabei eine zutiefst beunruhigende Aura aus, die auf die verderbte Natur der schlummernden Druiden und ihres von Alpträumen heimgesuchten Zufluchtsorts hindeutet."},{t="Auf der Suche nach Antworten in Ratschet",b="Im Unklaren über den Ursprung oder die Natur des Steins bringen Abenteurer das Artefakt in die Goblin-Hafenstadt Ratschet. Dort begutachtet der örtliche Ingenieur Stotterspritter die Kuriosität, stellt jedoch schnell fest, dass ihr Ursprung jenseits der Reichweite goblinischer Maschinerie und gewöhnlicher Geologie liegt. Stattdessen verweist er die Suchenden auf die felsigen Bergrücken über den Höhlen, wo die Tauren-Mystikerin Falla Weisenwind über die unruhigen Geister des Brachlands wacht."}},faq={{q="Was ist der Leuchtende Splitter?",a="Es handelt sich um einen verderbten, lumineszierenden grünen Kristall, der tief in den Höhlen des Wehklagens gefunden wird. In seiner glasigen Hülle wirbelt schwacher Rauch, der jeden beunruhigt, der ihn genauer betrachtet.",al={"leuchtender splitter gegenstand","was ist dieser grüne edelstein","splitter aus höhlen des wehklagens"}},{q="Wer kann den Splitter in Ratschet untersuchen?",a="Stotterspritter, ein Ingenieur nahe dem Flugmeister in Ratschet, untersucht den Splitter. Obwohl er Ingenieur und kein Druide ist, erkennt er dessen seltsame Energie und verweist Euch an jemanden mit spiritueller Expertise.",al={"wer in ratschet untersucht splitter","ratschet nsc für splitter","sputtervalve splitter"}},{q="Wo befindet sich Falla Weisenwind?",a="Falla Weisenwind schlägt ihr Lager auf den Berggipfeln direkt über dem Eingang zu den Höhlen des Wehklagens im zentralen Brachland auf.",al={"falla weisenwind standort","wo ist falla","berg über den höhlen des wehklagens"}},{q="Hat Stotterspritter ein Quest-Symbol über dem Kopf?",a="Nein. Stotterspritter zeigt kein aktives Quest-Symbol. Ihr müsst ihn direkt ansprechen und die Dialogoption bezüglich des seltsamen leuchtenden Splitters wählen, um fortzufahren.",al={"sputtervalve kein fragezeichen","kann nicht bei sputtervalve abgeben","sputtervalve verbuggt"}},{q="Warum sieht es so aus, als würde der Splitter Rauch enthalten?",a="Das rauchige Wirbeln im Inneren des Kristalls spiegelt die allgegenwärtige Verderbnis wider, die die Höhlen des Wehklagens heimsucht, direkt verknüpft mit dem Smaragdgrünen Alptraum, der die Gedanken der schlummernden Druiden des Giftzahns befällt.",al={"warum raucht splitter","grüner rauch in edelstein","verderbnis im splitter"}},{q="Wer kann die Questreihe nach Falla Weisenwind abschließen?",a="Sowohl Abenteurer der Horde als auch der Allianz können dieser Questreihe nachgehen. Die Erkenntnisse von Falla Weisenwind führen direkt zur Quest „Alptraum“, die Helden aussendet, um Führung bei ihren jeweiligen Anführern und Ältesten zu suchen.",al={"ist diese quest nur horde","allianz leuchtender splitter","wer bekommt alptraum"}}},fx={["8f9c92be"]={q="Warum müsst Ihr den Leuchtenden Splitter untersuchen?",a="Der leuchtende Splitter ist zutiefst beunruhigend. Fest und doch gefüllt mit wirbelnden, rauchig-grünen Tiefen strahlt er eine unnatürliche Präsenz aus, die nach einer Erklärung verlangt. Nachdem Ihr ihn aus dem Herzen der unruhigen Höhlen des Wehklagens geborgen habt, müsst Ihr verstehen, welche Verderbnis er in sich trägt und welche Bedrohung er für das Brachland darstellen könnte.",al={"warum leuchtenden splitter untersuchen","motiv leuchtender splitter","warum splitter nach ratschet bringen"}}},fp="17,241,22.398.0,26.419.1,26.170.0,37.225.0,32.126.0,52.167.0,47.196.0,54.208.1"}
P.entries["quest:6984"] = {n="Ein Dankeschön von Kokelwälder!",s="Diese festliche Aufgabe markiert den Abschluss der winterlichen Rettungsbemühungen von Smokywood Pastures in Orgrimmar. Nachdem die gestohlenen Leckereien vom Abominable Greench wiederbeschafft wurden, werden Abenteurer vom Goblinhändler Kaymard Kupferzwick dazu angehalten, direkt von Altvater Winter eine offizielle festliche Anerkennung entgegenzunehmen.",h="Diese festliche Aufgabe markiert den Abschluss der winterlichen Rettungsbemühungen von Smokywood Pastures in...",kw={"feast of winter veil","altvater winter","greench","kaymard kupferzwick","orgrimmar","smokywood pastures","tal der stärke","winterhauch"},ang={["faction:Horde"]="Die Feier des Winterhauchs durch die Horde in Orgrimmar verbindet die uralte schamanische Ehrfurcht vor dem Wechsel der Jahreszeiten mit dem lauten Kommerz der Goblins.",["profession:Cooking"]="Die saisonalen Vorräte von Smokywood Pastures sind von zentraler Bedeutung für die Festtagsküche und liefern exotische Rezepte sowie festliche Zutaten, auf die Köche jedes Jahr sehnlichst warten."},sec={{t="Ein geschäftiges Fest",b="Smokywood Pastures ist bestrebt, aus der Stimmung des Feast of Winter Veil Kapital zu schlagen, und vermarktet Leckereien, Rezepte und saisonale Freude in den Hauptstädten von Azeroth. Als ihre Lieferung festlicher Waren in den verschneiten Hügeln des Alteracgebirges entwendet wurde, geriet das Geschäft ins Stocken. Da die Leckereien zurückgeholt und der diebische Greench erledigt sind, sorgt der Händler Kaymard Kupferzwick rasch dafür, dass hilfsbereite Recken die volle unternehmerische Dankbarkeit erfahren – und das in angemessen feierlichem Rahmen."},{t="Audienz bei Altvater Winter",b="Statt einfach einen gewöhnlichen Münzbeutel über die Ladentheke zu reichen, veranlassen die Goblins, dass Altvater Winter die Belohnung höchstpersönlich überreicht. Der festliche Geselle hält Hof neben dem Feiertagsbaum im Tal der Stärke und fungiert sowohl als kultureller Schirmherr wie auch als repräsentatives Aushängeschild der Feierlichkeiten. Er ehrt jene, die die Festtagsvorräte gerettet haben, mit einem saisonalen Segen und einem Kokelwälder Spezialgeschenk."}},faq={{q="Wer schickt mich zu Altvater Winter?",a="Kaymard Kupferzwick, der im Tal der Stärke in Orgrimmar stationierte Vertreter von Smokywood Pastures, schickt Euch zu Altvater Winter, sobald Ihr die gestohlenen Festtagsleckereien des Unternehmens erfolgreich wiederbeschafft habt.",al={"wer startet diese quest","questgeber","kaymard rolle"}},{q="Womit habe ich mir den Dank von Smokywood Pastures verdient?",a="Ihr habt den Abominable Greench im Alteracgebirge aufgespürt und die gestohlenen Festtagsleckereien sichergestellt, wodurch die Lieferkette des Feast of Winter Veil für die Goblins gerettet wurde.",al={"warum danken sie mir","welche leckereien wurden gestohlen","greench hintergrund"}},{q="Wo befindet sich Altvater Winter in Orgrimmar?",a="Er sitzt unter dem großen, geschmückten Winterhauchbaum im Tal der Stärke, direkt neben den Verkaufsständen von Smokywood Pastures.",al={"altvater winter standort","wo ist der weihnachtsmann in org","winterhauchbaum org"}},{q="Wer ist Altvater Winter?",a="In alten Überlieferungen ist Altvater Winter ein elementarer oder mythischer Herold des Jahreszeitenwechsels, der das Land in winterlichen Schnee hüllt. Für das Feast of Winter Veil schlüpfen sterbliche Stellvertreter in seine traditionellen roten Gewänder, um Wohlwollen zu verbreiten und Leckereien an Kinder und Abenteurer zu verteilen.",al={"wer ist altvater winter","ist altvater winter echt","winterhauch lore"}},{q="Was ist Smokywood Pastures?",a="Smokywood Pastures ist ein von Goblins geführtes kulinarisches und landwirtschaftliches Unternehmen. Sie versorgen während des Feast of Winter Veil sowohl die Horde als auch die Allianz mit festlichen Speisen, saisonalen Zutaten und dekorativen Neuheiten.",al={"smokywood pastures lore","wer sind smokywood pastures","goblin feiertagshändler"}},{q="Erhalte ich noch etwas, nachdem ich mit ihm gesprochen habe?",a="Ja. Altvater Winter überreicht Euch im Namen des Unternehmens ein Kokelwälder Spezialgeschenk, und Eure Bemühungen bringen Euch Ansehen beim Steamwheedle-Kartell ein.",al={"questbelohnung","verkleidungsset","postgeschenk"}}},fx={["553cdbb2"]={q="Warum schickt Euch Kaymard Kupferzwick zu Altvater Winter?",a="Kaymard Kupferzwick und Smokywood Pastures möchten Euch für die Bergung ihrer gestohlenen Leckereien belohnen. Indem sie Euch an Altvater Winter verweisen, damit Ihr persönlich ein besonderes Geschenk zum Winterhauchfest erhaltet, zeigen die Goblins ihre Dankbarkeit und wahren gleichzeitig das festliche kommerzielle Wohlwollen der Saison.",al={"warum dankt mir kaymard","kaymard kupferzwicks motiv","warum zu altvater winter schicken"}}},fp="32,308,19.481.0,33.410.0,47.210.0,52.167.0,50.128.0,27.272.0,27.214.0,51.154.0"}
P.entries["quest:699"] = {n="Mangelnde Reserven",s="Tok'Kar und die Soldaten an der Küste sind stationiert, um Steinard vor Murlocs zu beschützen oder eine Warnung zu senden, wenn die Streitmacht zu groß ist. Tok'Kar möchte sechs Klauen von sawtooth snappern und bietet als Dank eine der Waffen des Außenpostens an.",h="Tok'Kar und die Soldaten an der Küste sind stationiert, um Steinard vor Murlocs zu beschützen oder eine...",kw={"klauen","murlocs","sawtooth snapper","steinard","sümpfe des elends","tok'kar"},sec={{t="Waffen für die Küste",b="Da Murlocs an der Küste eine Bedrohung darstellen, sind Tok'Kar und die Soldaten hier postiert, um Steinard zu beschützen oder es zu warnen, wenn die Streitmacht zu groß ist. Das lässt wenig Zeit zum Ausruhen, und Tok'Kar könnte mehr Hilfe gebrauchen. Die Klauen von sawtooth snappern ergeben feine Waffen, wenn sie richtig zubereitet werden. Tok'Kar bittet um sechs davon und bietet im Gegenzug eine der Waffen des Außenpostens an, dankbar für das Fleisch und die Gesellschaft."}},faq={{q="Wer bittet um die Klauen?",a="Tok'Kar, der an der Küste stationiert ist, um Steinard zu beschützen.",al={"wer vergibt lack of surplus","questgeber","tokkar"}},{q="Warum braucht Tok'Kar Klauen von sawtooth snappern?",a="Ihre Klauen ergeben feine Waffen, wenn sie richtig zubereitet werden, und Tok'Kar möchte sechs davon.",al={"warum klauen","zweck der sawtooth snapper","waffenklauen"}},{q="Nach welcher Bedrohung hält der Küstenposten Ausschau?",a="Murlocs an der Küste. Die Soldaten sind dort, um Steinard zu beschützen oder es zu warnen, wenn die Streitmacht zu groß ist.",al={"küstengefahren","murlocangriff steinard","was beobachtet tokkar"}},{q="Wohin führt dies als Nächstes?",a="Threat From the Sea folgt.",al={"what comes next","nächste quest","nach lack of surplus"}}},fp="15,225,21.392.0,23.61.0,45.84.0,45.108.0,26.28.0"}
P.entries["quest:7"] = {n="Säuberung im Koboldlager",s="Säuberung im Koboldlager ist eine frühe militärische Aufgabe, die Marschall McBride neu eingetroffenen Rekruten im Nordhaintal überträgt. Die Mission weist Freiwillige an, das in den nördlichen Wäldern lauernde Koboldunrat auszudünnen, um zu verhindern, dass die aggressiven unterirdischen Aasfresser das Abteigelände überrennen. Sie dient als erste echte Bewährungsprobe eines Initianden bei der Verteidigung der Grenzen des Königreichs Sturmwind.",h="Säuberung im Koboldlager ist eine frühe militärische Aufgabe, die Marschall McBride neu eingetroffenen...",kw={"echokamm","wald von elwynn","kobold","marschall mcbride","nordhain","abtei von nordhain","ungeziefer"},ang={["faction:Alliance"]="Die Unruhen in Nordhain verdeutlichen die Belastung der Kerngebiete Sturmwinds, wo selbst geringfügige Plündererplagen den dringenden Einsatz einer freiwilligen Miliz erfordern.",["race:Human"]="Für die Menschen von Nordhain ist das Zurückschlagen des Koboldunrats eine grundlegende Bürgerpflicht, um die Abtei und das Ackerland vor dem Überranntwerden zu bewahren."},sec={{t="Ein Tal unter Druck",b="Das Nordhaintal war einst eine ruhige Zuflucht für Gebet, Landwirtschaft und die Ausbildung von Novizen, doch in den letzten Jahren wurden Sturmwinds Streitkräfte stark überdehnt. Da der König verschollen ist und die königlichen Garnisonen verstreut sind, drängen wilde Kreaturen und Opportunisten kühn an die Grenzen der Zivilisation vor. Marschall McBride organisiert die örtliche Verteidigung aus dem Inneren der Abtei von Nordhain und verlässt sich auf frische Freiwillige, um die heranrückenden Bedrohungen einzudämmen, bevor sie den Betrieb der Abtei stören oder die umliegenden Weinberge gefährden."},{t="Das Ungeziefer in den Wäldern",b="Kobolde sind von Natur aus feige, kerzenbesessene Höhlenbewohner, die sich gewöhnlich damit begnügen, fernab des direkten Sonnenlichts unterirdische Adern abzubauen. Doch ein ganzer Clan ist bis an die nördliche Baumgrenze von Nordhain vorgedrungen. Bleiben sie unkontrolliert, lässt ihre bloße Überzahl aus Plünderungen offene Überfälle werden. McBrides Befehl, Koboldunrat zur Strecke zu bringen, dient einem doppelten Zweck: Er schwächt ihre Vorhut und stellt auf die Probe, ob ein Rekrut die nötige Entschlossenheit besitzt, um das Reich zu beschützen."}},faq={{q="Wer befiehlt das Ausdünnen des Koboldlagers?",a="Marschall McBride erteilt den Befehl. Er ist in der Abtei von Nordhain stationiert und überwacht im Auftrag von Sturmwind die örtliche Aufnahme von Rekruten sowie die Sicherheit des Tals.",al={"wer vergibt diese quest","questgeber","rolle von marschall mcbride"}},{q="Warum halten sich die Kobolde in den nördlichen Wäldern statt in einer Mine auf?",a="Obwohl Kobolde typischerweise in Bauen und Minen leben, ist ihre Population in Nordhain so dicht geworden, dass sie in den offenen Wald überquillt. Sie haben primitive Lager zwischen den nördlichen Bäumen errichtet und streifen nahe der Grenze des zivilisierten Landes umher.",al={"warum sind kobolde draußen","kobolde an der oberfläche","warum wald"}},{q="Warum gelten diese Kobolde als Bedrohung für Sturmwind?",a="Einzeln betrachtet ist Koboldunrat ängstlich und schwach. In Rotten hingegen sind sie dreiste Diebe, die Reisende überfallen, Vorräte plündern und unverteidigte Außenposten überrennen können – was sich Sturmwind nicht leisten kann, solange sein Militär ohnehin überdehnt ist.",al={"sind kobolde gefährlich","warum ungeziefer töten"}},{q="Wohin führt diese Mission als Nächstes?",a="Nachdem das oberirdische Ungeziefer ausgedünnt wurde, bittet Marschall McBride die Rekruten, tiefer in die Echokammmine vorzudringen, wo das Herz des Koboldbefalls liegt.",al={"welche quest kommt als nächstes","nächster schritt","nach säuberung des lagers"}},{q="Erhält Nordhain regelmäßige Unterstützung durch die königliche Armee?",a="Nein. Aufgrund politischer Spannungen und Truppenknappheit im gesamten Königreich nach dem Verschwinden von König Varian müssen sich örtliche Befehlshaber wie McBride auf zivile Freiwillige, Abenteurer und Rekruten verlassen, um die Grenzsicherheit zu gewährleisten.",al={"wo sind die wachen von sturmwind","warum freiwillige"}},{q="Warum hängen Kobolde so sehr an ihren Kerzen?",a="Kobolde verehren Kerzen als ihren wichtigsten Schutz gegen die erdrückende Dunkelheit unterirdischer Tunnel. Die Flamme bedeutet für sie Sicherheit, Sicht und Besitz, weshalb sie notorisch feindselig reagieren, wenn jemand versucht, sie ihnen wegzunehmen.",al={"warum kerzen","kerzenbesessenheit"}}},fx={["921e514b"]={q="Warum schickt Euch Marschall McBride anstelle der Wachen von Sturmwind?",a="Die königliche Armee von Sturmwind hat ihre Kräfte durch die Bewältigung von Krisen im gesamten Königreich bis aufs Äußerste strapaziert, weshalb das Nordhaintal nur noch von einer Handvoll Wachen besetzt ist. McBride muss seine Soldaten um die Abtei und die Hauptstraßen herum stationiert lassen, um die Verteidigungslinien aufrechtzuerhalten. Da er keine Truppen entbehren kann, um die Wildnis zu patrouillieren, ist er auf fähige neue Rekruten und vorbeikommende Freiwillige angewiesen, um aufkommende Gefahren auszumerzen.",al={"warum keine wachen schicken","warum braucht mcbride mich","warum abenteurer gegen kobolde rekrutieren"}},afae4267={q="Warum will Marschall McBride, dass das Koboldlager gesäubert wird?",a="Ein Koboldclan hat begonnen, die Wälder nördlich der Abtei zu befallen, und Marschall McBride möchte, dass ihre Anzahl verringert wird, bevor sie das Tal überrennen. Sturmwind ist bereits durch Bedrohungen an anderer Stelle belastet, sodass Nordhain sich selbst schützen muss. Obwohl sie einzeln feige sind, werden die Kobolde in Gruppen kühn. Sie jetzt auszudünnen, hält die Siedlung sicher und beginnt die Bemühungen, sie vollständig aus Nordhain zu vertreiben.",al={"warum kobolde ausdünnen","mcbrides motiv kobolde","warum koboldlager säubern"}},["35967b57"]={q="Was ist das Koboldungeziefer, das Ihr jagen sollt?",a="Koboldungeziefer sind die Kundschafter und Aasfresser eines Clans, der in den nördlichen Wald gekrochen ist. Von Natur aus unterirdische, rattenähnliche Humanoide, sind sie für sich genommen feige Diebe, aber sie haben sich in alarmierender Zahl in den Wäldern außerhalb von Nordhain versammelt. Wenn sie nicht aufgehalten werden, bedrohen ihre um sich greifenden Lager Reisende, Obstgärten und die Abtei selbst.",al={"wer ist das koboldungeziefer","was ist koboldungeziefer","ziel koboldungeziefer"}}},fp="19,229,23.429.0,23.359.0,42.123.0,56.202.0,55.197.0,34.145.1,50.184.0,48.164.0"}
P.entries["quest:70"] = {n="Die Legende von Stalvan",s="Dieser Abschnitt der Ermittlung führt Suchende zu einem verlassenen Brief, der vor Jahren im Gasthaus von Goldhain zurückgelassen wurde. Der Spur von Stalvan Dunstmantel zu folgen, führt aus dem Wald von Elwynn hinaus und in das Kanalviertel von Sturmwind.",h="Dieser Abschnitt der Ermittlung führt Suchende zu einem verlassenen Brief, der vor Jahren im Gasthaus von...",kw={"kanäle","verwalter folsom","goldhain","gastwirt farley","gasthaus \"zur höhle des löwen\"","mistmantle","stalvan","sturmwind","unzugestellter brief"},ang={["faction:Alliance"]="Das Geheimnis um Stalvan zu lüften, erfordert eine Reise durch die Kernlande der Allianz, um einer alten Spur vom verschlafenen Weiler Goldhain bis zu den großen Kanälen der Hauptstadt zu folgen.",["race:Human"]="Diese Untersuchung legt die dunkleren Strömungen des Königreichs Sturmwind offen und zeigt, dass die Schrecken, die den Dämmerwald heimsuchen, ihre Wurzeln direkt vor den Toren der Hauptstadt haben."},sec={{t="Schrecken um Mitternacht",b="Als Gastwirt Farley vom Gasthaus \"Zur Höhle des Löwen\" nach Stalvan Dunstmantel gefragt wird, erinnert er sich an eine stürmische Nacht vor vielen Jahren. Ein reisender Bote hatte damals Schutz vor dem strömenden Regen gesucht, nur um gegen Mitternacht in panischer Angst die Treppe hinunterzustürzen. Nur mit seinen Nachtkleidern bekleidet, rannte der Bote geradewegs hinaus in den dunklen Sturm und wurde nie wieder gesehen."},{t="Das zurückgelassene Paket",b="Auf seiner panischen Flucht ließ der Bote seine Tasche und seine persönliche Truhe im oberen Zimmer zurück. Unter der vergessenen Fracht lag ein nie abgeschickter Brief mit dem Namen Stalvan, adressiert an jemanden, der im Kanalviertel von Sturmwind wohnte. Die Truhe blieb am Fuße des Bettes unberührt, bis Farley die Erlaubnis erteilte, sie zu öffnen."},{t="Ein frostiger Empfang",b="Den längst überfälligen Brief nach Sturmwind zu bringen, führt zu Verwalter Folsom, der über Anwesen entlang der Kanäle in der Nähe des Parks wacht. Statt Dankbarkeit für das Überbringen einer vernachlässigten Lieferung hervorzurufen, löst die Erwähnung von Stalvans Namen und der Anblick seiner Handschrift sofortigen Abscheu und Feindseligkeit aus, was auf tief sitzende Skandale rund um den Absender hindeutet."}},faq={{q="Wo wird der unzustellbare Brief aufbewahrt?",a="Der Brief befindet sich in einer Lagertruhe im Obergeschoss des Gasthaus \"Zur Höhle des Löwen\" in Goldhain. Steigt die Treppe hinauf, biegt nach rechts ab und betretet das Schlafzimmer mit dem Bett; die Truhe steht am Fußende des Bettgestells.",al={"brief finden","stalvan truhe fundort","wo ist die truhe"}},{q="Warum wurde der Brief ursprünglich nie zugestellt?",a="Der Bote suchte vor Jahren im Gasthaus \"Zur Höhle des Löwen\" Schutz vor einem Regenguss. Gegen Mitternacht versetzte ihn etwas derart in Schrecken, dass er nur in seiner Nachtwäsche in den Sturm floh und seine Truhe sowie seine Lieferungen zurückließ.",al={"warum verlassener brief","was erschreckte den boten","warum floh der bote"}},{q="Wo finde ich Verwalter Folsom in Sturmwind?",a="Verwalter Folsom steht an den Kanälen in Sturmwind, nahe dem Rand des Parkviertels.",al={"folsom aufenthaltsort","wo ist verwalter folsom","kanalviertel abgabe"}},{q="Warum ist Verwalter Folsom wütend über den Erhalt des Briefes?",a="Folsom erkennt Stalvans Handschrift und Namen sofort wieder und reagiert mit Empörung. Stalvan Dunstmantel hinterließ bittere Erinnerungen und Entrüstung unter den Menschen, die mit seiner Vergangenheit in Sturmwind verbunden waren.",al={"warum ist folsom wütend","folsom reaktion","ihr habt vielleicht nerven"}},{q="Wie hängt das mit den Problemen im Dämmerwald zusammen?",a="Der Stadtrat von Dunkelhain untersucht ein anhaltendes Übel, das mit dem Namen Stalvan Dunstmantel verknüpft ist. Um herauszufinden, wer Stalvan zu Lebzeiten war, müssen seine früheren Reisen und Verbindungen durch den Wald von Elwynn und Sturmwind nachverfolgt werden.",al={"warum dämmerwald quest in goldhain","wie hängt dies mit dämmerwald zusammen"}},{q="Was geschieht, nachdem man Verwalter Folsom den Brief übergeben hat?",a="Verwalter Folsoms schroffe Antwort leitet das Sturmwind-Kapitel der Ermittlung ein und treibt Euch dazu an, Stalvans frühere Anstellung und die düsteren Ereignisse aufzudecken, die sich bei der von ihm bedienten Adelsfamilie zutrugen.",al={"nächster schritt","was folgt nach dieser quest"}}},fx={["1a6ccbd1"]={q="Warum möchte Gastwirt Farley, dass Stalvans Brief zugestellt wird?",a="Gastwirt Farley hat kein persönliches Interesse an Stalvans Angelegenheiten oder dem alten Brief; er hilft Euch lediglich dabei, das Geheimnis zusammenzusetzen, das Ihr untersucht. Wenn Ihr ihn auf Stalvan Dunstmantel ansprecht, erinnert sich Farley an einen verängstigten Boten, der vor Jahren während eines Sturms aus dem Gasthaus \"Zur Höhle des Löwen\" floh und sein Kuriergepäck oben zurückließ. Da er sich daran erinnert, dass ein niemals zugestellter Brief von Stalvan zurückblieb, der an den Kanalviertel von Sturmwind adressiert war, bietet er ihn Euch an, damit Ihr Eurer schwer fassbaren Spur folgen könnt.",al={"warum hilft farley","beweggrund gastwirt farley","warum den brief zustellen"}},b7fa74bd={q="Was ist der niemals zugestellte Brief?",a="Der Brief ist ein altes Schriftstück, das Stalvan Dunstmantel vor Jahren verfasste und das für eine Adresse im Kanalviertel von Sturmwind bestimmt war. Er wurde im Gasthaus \"Zur Höhle des Löwen\" zurückgelassen, als ein Bote in reiner Panik in die Nacht floh und seine Habe in einer Truhe oben einsperrte. Für Eure Ermittlungen dient der Brief als entscheidender physischer Hinweis, der Euch zu Verwalter Folsom in Sturmwind führt, um herauszufinden, mit wem Stalvan in Kontakt stand und was aus ihm wurde.",al={"was ist ein niemals zugestellter brief","stalvan niemals zugestellter brief","was steht im brief"}}},fp="21,218,17.344.0,19.334.0,16.348.1,37.203.0,46.226.0,46.99.0,57.200.0,49.228.0,57.204.1"}
P.entries["quest:700"] = {n="Ehrerbietung von einem König",s="Ehrerbietung von einem König markiert den letzten Schritt bei der Ehrung des Opfers des gefallenen Zwergensoldaten Sully Balloo. Nachdem edler Granit aus den Ruinen von Lordaeron geborgen wurde, meißelt Großsteinmetz Marmorstein auf Geheiß von König Magni Bronzebart ein feierliches Gedenkmonument in Eisenschmiede.",h="Ehrerbietung von einem König markiert den letzten Schritt bei der Ehrung des Opfers des gefallenen...",kw={"ehrerbietung von einem könig","granit","eisenschmiede","lordaeron","magni bronzebart","marblesten","denkmal","sully balloo"},ang={["class:Warrior"]="Magnis Worte ehren unmittelbar die selbstlose Tapferkeit von Frontsoldaten wie Sully Balloo, die im Kampf alles opferten.",["faction:Alliance"]="Das Monument dient als ergreifende Mahnung an den schweren Blutzoll, der während der jüngsten Konflikte in ganz Khaz Modan und den nördlichen Königreichen gefordert wurde.",["race:Dwarf"]="Für Zwerge gehört die Ehrung gefallener Vorfahren in unvergänglichem Stein zu ihren heiligsten kulturellen Traditionen."},sec={{t="Ein in Trauer gemeißeltes Monument",b="König Magni Bronzebart gab ein dauerhaftes Monument in Auftrag, um Sully Balloo zu ehren, einen tapferen Zwerg, der im Dienst für sein Volk sein Leben verlor. Geschaffen von Großsteinmetz Marmorstein aus hochwertigem Granit, der aus den vom Krieg gezeichneten Ländern Lordaerons herangeschafft wurde, steht das vollendete Denkmal in Eisenschmiede als bleibendes Zeugnis für gefallene Soldaten, deren Opfer das Zwergenkönigreich bewahren."},{t="Die Betrachtung eines Herrschers",b="Als ihm die Nachricht von der Fertigstellung des Monuments überbracht wird, sinnt Magni schwermütig über die Grenzen von Stein und Sterblichkeit nach. Während er einräumt, dass behauener Fels niemals wahrhaft dem Leben eines tapferen Zwerges gleichkommen kann, hofft er, dass das Denkmal überdauert, damit künftige Generationen, die Azeroth durchstreifen, niemals die Helden vergessen, die bluteten, um deren Zukunft zu sichern."}},faq={{q="Wer wird durch dieses Monument geehrt?",a="Das Monument wurde zum Gedenken an Sully Balloo errichtet, einen tapferen Zwergensoldaten, der sein Leben opferte, als er mutig für sein Volk und die Allianz kämpfte.",al={"für wen ist dieses denkmal","sully balloo monument","wer starb"}},{q="Warum wurde der Stein aus Lordaeron beschafft?",a="Großsteinmetz Marmorstein benötigte den feinsten Granit, der eines bleibenden königlichen Tributs würdig war. Lordaeron liefert außergewöhnlichen Bruchstein, auch wenn die Region selbst nach der Geißel in Trümmern liegt.",al={"warum stein aus lordaeron","lordaeron graniterz","marblesten stein"}},{q="Wo findet diese Quest statt?",a="Die Quest beginnt bei Großsteinmetz Marmorstein und endet bei König Magni Bronzebart im High Seat von Eisenschmiede.",al={"wo abgeben","wer schließt quest ab"}},{q="Warum gibt König Magni diesen Tribut persönlich in Auftrag?",a="Magni glaubt, dass Herrscher die einfachen Soldaten ehren müssen, die ihre Reiche verteidigen. Er betrachtet Gedenkstein als eine unverzichtbare Mahnung für künftige Generationen an den hohen Preis, den einfache Soldaten für ihre Sicherheit bezahlt haben.",al={"warum kümmert es magni","magni bronzebart sully balloo"}},{q="Was geschieht, nachdem das Denkmal vollendet ist?",a="Der Bericht bei König Magni schließt die Gedenk-Questreihe ab. Die gefertigte Statue verbleibt in Eisenschmiede als feierliches, dauerhaftes Wahrzeichen für Sully Balloo.",al={"was kommt danach","ehrerbietung von einem könig folgequest"}},{q="Welche steinmetzische Bedeutung hat die Statue?",a="Großsteinmetz Marmorstein zählt zu den versiertesten Zwergenhandwerkern in Eisenschmiede. Bei der Bearbeitung des importierten Lordaeron-Granits formte er den rohen Stein im Auftrag des Monarchen zu einem angemessenen nationalen Kunstwerk.",al={"marblestens rolle","großsteinmetz handwerk"}}},fx={["964451bf"]={q="Warum schickt Euch Großsteinmetz Marmorstein zum König?",a="Ihr wart diejenigen, die die gefährliche Reise zu den Ruinen von Lordaeron gewagt haben, um den feinen Granit für die Skulptur zu bergen. Nachdem Ihr den Stein gesichert und den Tribut ermöglicht habt, betraut Großsteinmetz Marmorstein Euch damit, König Magni Bronzebart persönlich die stolze Nachricht zu überbringen, dass Sully Balloos Denkmal fertiggestellt ist.",al={"warum mich zu magni schicken","warum könig magni informieren","warum schickt marmorstein den spieler"}}},fp="16,279,26.381.0,24.333.0,38.142.0,42.209.0,33.116.0,55.206.0,44.143.0,47.209.0"}
P.entries["quest:7003"] = {n="Geschrumpfte Riesen",s="An der Vergessenen Küste von Feralas, nahe den Docks, erklärt Zorbin Fandazzle, dass die Riesen schlecht fürs Geschäft seien. Zorbin hat nach gnomischem Entwurf einen Schrumpfstrahl gebaut, der durch Goblin-Fachwissen verbessert wurde, und überreicht Euch den Ultra-Shrinker, um ihn an den Riesen von Feralas auszuprobieren.",h="An der Vergessenen Küste von Feralas, nahe den Docks, erklärt Zorbin Fandazzle, dass die Riesen schlecht fürs...",kw={"cliff giant","feralas","die vergessene küste","land walker","miniaturisierungsrückstand","ultra-shrinker","geschrumpfte riesen","zorbin fandazzle"},sec={{t="Ein Schrumpfstrahl für die Riesen",b="Zorbin Fandazzle muss etwas gegen die Riesen von Feralas unternehmen, die dem Geschäft keineswegs zuträglich sind, wenn Zorbin hier draußen bleiben soll. Das Hilfsmittel ist eine Variante eines gnomischen Schrumpfstrahls, gefertigt mit dem, was Zorbin stolz als überlegene Goblin-Fortschritte bezeichnet. Um Unannehmlichkeiten wie den Tod zu vermeiden, möchte Zorbin lieber, dass Ihr ihn testet. Ihr sollt den Ultra-Shrinker an Riesen wie Cliff Giants, Deep Striders, Wave Striders, Shore Striders oder Land Walkers anwenden und den Miniaturisierungsrückstand einsammeln, der nach dem Schrumpfen an ihnen zurückbleibt, um ihn zu den Docks zurückzubringen."},{t="Warum Zorbin den Rückstand will",b="Zorbin bezeichnet den Miniaturisierungsrückstand als ein wertvolles Gut im Ingenieurswesen, da er dazu beiträgt, sicherzustellen, dass der Schrumpfstrahler nicht so etwas Enttäuschendes tut wie dem Benutzer um die Ohren zu fliegen. Zorbin fügt dann hinzu, dass dies nur für andere Schrumpfstrahler gelte, nicht für jenen in Euren Händen."},{t="Zurück an den Docks",b="Bei Eurer Rückkehr freut sich Zorbin über den Rückstand und darüber, dass Ihr noch alle wichtigen Gliedmaßen besitzt. Zorbin betont daraufhin, dass der Ultra-Shrinker zu keinem Zeitpunkt riskant gewesen sei, und nennt Euch einen Freund der Goblins überall auf der Welt."}},faq={{q="Wer steckt hinter dem Ultra-Shrinker?",a="Zorbin Fandazzle, zu finden bei den Docks an der Vergessenen Küste in Feralas.",al={"wer vergibt geschrumpfte riesen","zorbin fandazzle questgeber","wo beginnt geschrumpfte riesen"}},{q="Warum möchte Zorbin, dass die Riesen geschrumpft werden?",a="Zorbin sagt, dass die Riesen dem Geschäft keineswegs zuträglich seien, wenn Zorbin hier draußen bleibe, und ein geschrumpfter Riese weitaus handhabbarer sei.",al={"warum riesen schrumpfen","warum riesen schrumpfen feralas","zorbin fandazzle motivation"}},{q="Welche Riesen können geschrumpft werden?",a="Jede Art von Riese in Feralas ist geeignet. Entlang der Vergessenen Küste zählen dazu Cliff Giants, Deep Striders, Wave Striders, Shore Striders und Land Walkers.",al={"welche riesen kann ich schrumpfen","welche riesen zählen","geschrumpfte riesen ziele"}},{q="Was ist Miniaturisierungsrückstand?",a="Man findet ihn an einem Riesen, nachdem er geschrumpft wurde. Zorbin bezeichnet ihn als wertvolles Gut im Ingenieurswesen und sagt, er helfe sicherzustellen, dass der Schrumpfstrahler dem Benutzer nicht um die Ohren fliegt.",al={"warum miniaturisierungsrückstand","was bewirkt rückstand","zorbin zweck des rückstands"}}},fp="13,258,30.547.0,28.261.0,17.213.1,33.71.0,39.129.0,27.154.0,32.170.0"}
P.entries["quest:701"] = {n="Arglist des Raptors",s="Guile of the Raptor ist eine Quest, in der Tor'gan versucht, den schlummernden Kriegergeist in Gor'mul zu wecken. Durch das Erbeuten der Herzen von Highland Fleshstalkers plant Tor'gan, einen verzauberten Gegenstand herzustellen, der von der List und der Raubtierkraft des Raptors erfüllt ist.",h="Guile of the Raptor ist eine Quest, in der Tor'gan versucht, den schlummernden Kriegergeist in Gor'mul zu...",kw={"schlummernder krieger","gor'mul","list des raptors","hochland-fleischpirscher","raptorherzen","tor'gan","krieger"},ang={["class:Warrior"]="Tor'gan versucht, den schlummernden Kriegergeist in Gor'mul wiederzubeleben, indem er die List und Wildheit von Raptoren nutzt, um ihn an kriegerische Stärke zu erinnern.",["faction:Horde"]="Dieses Ritual spiegelt die Traditionen der Horde wider, auf Urzeitbestien und Naturgeister zurückzugreifen, um einem teilnahmslosen oder bekümmerten Kameraden neuen Lebensmut zu schenken."},sec={{t="Das Erwecken des schlummernden Kriegers",b="Tor'gan bemüht sich darum, einen teilnahmslosen Gefährten namens Gor'mul wieder aufzurichten, dessen Kriegergeist in den Schlummer verfallen ist. Anstatt sich auf bloße Überredungskunst zu verlassen, wendet sich Tor'gan der Urmagie zu, um Gor'mul wieder wachzurütteln. Durch das Herstellen eines Amuletts, das mit der Essenz wilder Raubtiere erfüllt ist, hofft er, Gor'muls kriegerische Entschlossenheit neu zu wecken und die Stärke ihrer neuen Macht zu demonstrieren."},{t="Das Herz des Raubtiers",b="Um die Raubtierinstinkte der Wildnis zu kanalisieren, benötigt Tor'gan die Herzen von Highland Fleshstalkers. In schamanischen und urzeitlichen Traditionen trägt das Herz eines listigen Jägers dessen Wildheit und List in sich. Tor'gan webt aus diesen Trophäen sowohl ein physisches Zeichen als auch einen Zauber, mit dem Ziel, Gor'mul direkt mit der List des Raubtiers zu erfüllen, damit er seine wahre Berufung wiederentdecken kann."}},faq={{q="Wer ist Tor'gan?",a="Tor'gan ist eine schamanische oder spirituelle Gestalt, die versucht, Gor'mul zu helfen. In dem Glauben, dass Gor'mul den Kontakt zu seiner inneren Stärke verloren hat, sammelt Tor'gan Reagenzien, um einen mit Bestienmagie erfüllten Gegenstand herzustellen und ihn so wiederzuerwecken.",al={"wer ist tor'gan","torgan","questgeber"}},{q="Wer ist Gor'mul?",a="Gor'mul ist ein Individuum, das seinen Kampfgeist verloren und den Krieger in sich hat einschlummern lassen. Tor'gan beabsichtigt, ihn mit der Essenz eines Urraubtiers zu erfüllen, damit er neue Macht erlebt und sich erhebt, um wieder zu kämpfen.",al={"wer ist gormul","warum gormul helfen","schlummernder krieger"}},{q="Warum benötigt Tor'gan Raptorherzen?",a="Tor'gan benötigt zwölf Raptorherzen, um sowohl einen physischen Talisman als auch die Verzauberung zu fertigen, die nötig ist, um Gor'mul zu erfüllen. Urmagie nutzt oft die Herzen von Raubtieren, um deren angeborene Instinkte, List und Raubtierkraft zu kanalisieren.",al={"warum raptorherzen","wofür sind herzen","raptormagie"}},{q="Woher stammen die Raptorherzen?",a="Die benötigten Herzen werden von Highland Fleshstalkers erbeutet, räuberischen Raptoren, die für ihr unerbittliches Jagdgeschick und ihre List bekannt sind. Tor'gan hält ihre Herzen für mächtig genug, um den Erweckungszauber zu speisen.",al={"woher herzen bekommen","welche raptoren","hochland-fleischpirscher"}},{q="Was bedeutet die List des Raptors?",a="Die List des Raptors repräsentiert die Schläue, die schnellen Reflexe und den tödlichen Instinkt des Raubtiers. Tor'gan glaubt, dass das Kanalisieren dieses spezifischen Wesens Gor'muls Lethargie durchbrechen und seine Kampfinstinkte wiederbeleben wird.",al={"was ist die list des raptors","welche macht","bedeutung der raptorlist"}},{q="Was ist das letztendliche Ziel des Rituals?",a="Tor'gan fertigt den Gegenstand und webt den Zauber mithilfe der gesammelten Herzen, mit dem Ziel, Gor'mul neue Macht zu demonstrieren und seine schlummernde Kriegeridentität zu wecken, damit er seinen Pfad wieder aufnehmen kann.",al={"ist gormul geheilt","was geschieht nach dem ritual","funktioniert es"}}},fp="19,260,29.372.0,25.370.0,15.214.0,15.212.0,36.231.0,37.206.0,42.218.0,40.182.0"}
P.entries["quest:702"] = {n="Arglist des Raptors",s="Nach dem früheren Guile of the Raptor überreicht Euch Tor'gan eine Kugel und schickt Euch zu Gor'mul nach Hammerfall. Ihre Energie birgt die Essenz des Raptors, die Gor'muls Geist anregen und ihm ein neues Ziel geben soll.",h="Nach dem früheren Guile of the Raptor überreicht Euch Tor'gan eine Kugel und schickt Euch zu Gor'mul nach...",kw={"arathihochland","gor'mul","hammerfall","raptorenessenz","tor'gan","torgans kugel"},sec={{t="Tor'gans Kugel",b="Tor'gan gibt Euch eine Kugel, deren Energie Gor'mul mit der Essenz des Raptors erfüllen soll. Er hofft, dass sie den Geist des Kriegers wecken und ihn auf einen neuen Lebensweg führen wird. Sobald Gor'mul wieder er selbst ist, beabsichtigt Tor'gan, ihm den aktuellen Zustand der Horde zu erklären und die Hilfe eines großen Kriegers in den unaufhörlichen Kämpfen zu gewinnen."},{t="Gor'muls Verbitterung",b="Gor'mul empfängt Eure Rückkehr mit Bitterkeit und erklärt, er wolle nichts weniger als noch mehr von Tor'gans Mitleid, während er Euch mit Geschwätz über bunte Schnüre verhöhnt."},{t="Eine seltsame Kraft",b="Dennoch ist die Kugel interessanter, als Gor'mul erwartet hatte, und er bemerkt die seltsame Macht, die von ihr ausgeht."},{t="Der Raptor im Inneren",b="Als Gor'mul die Kugel an sich nimmt, regt sich sein Blut, und die List des Raptors durchströmt ihn. Er fragt sich laut, ob dies der Schamanismus sei, von dem Tor'gan gesprochen habe, und erklärt sich dann für erneuert, während seine Stärke zurückkehrt."}},faq={{q="Wer ist Gor'mul?",a="Gor'mul ist ein niedergeschlagener Krieger in Hammerfall. Tor'gan möchte seine Lebensgeister wecken und ihn auf einen neuen Weg bringen, damit die Horde die Hilfe eines großen Kriegers erhält.",al={"wer ist gormul","gormul lore","was stimmt nicht mit gormul"}},{q="Welchen Zweck erfüllt Tor'gans Kugel?",a="Ihre Energie soll Gor'mul mit der Essenz des Raptors erfüllen, seinen Geist wachrütteln und ihm neuen Lebensmut schenken.",al={"was macht die kugel","zweck von torgans kugel","list-kugel"}},{q="Was ging diesem Schritt voraus?",a="Ein früheres Guile of the Raptor geht voran, und dieser Schritt baut darauf auf.",al={"vorherige quest","voraussetzung"}}},fp="19,206,13.324.0,20.152.0,15.122.1,17.207.1,15.160.0,37.111.0,27.71.0"}
P.entries["quest:7025"] = {n="Leckereien für Altvater Winter",s="Während des Winterhauchfests wird der Darsteller, der in Eisenschmiede die Rolle von Altvater Winter übernimmt, müde und bittet Passanten um einen Festtagsimbiss. Bringt Ihr ihm frisch gebackene Lebkuchenplätzchen und Eiskalte Milch, erhaltet Ihr eine festliche Belohnung und seinen herzlichen Dank.",h="Während des Winterhauchfests wird der Darsteller, der in Eisenschmiede die Rolle von Altvater Winter...",kw={"winterhauchfest","lebkuchenplätzchen","altvater winter","eiskalte milch","eisenschmiede","kokelwälder","leckereien für altvater winter"},ang={["faction:Alliance"]="Eisenschmiede dient als primäres Zentrum der Allianz für die Feierlichkeiten zum Winterhauchfest und lockt Reisende aus den gesamten Östlichen Königreiche zum Festtagsbaum im Siedlungsviertel.",["profession:Cooking"]="Die Quest erfordert einfache Kochkenntnisse, um Kleine Eier und Festtagsgewürze zu festlichen Lebkuchenplätzchen zu verarbeiten.",["race:Dwarf"]="Für Zwerge repräsentiert Altvater Winter eine alte Legende, die mit den Titanen und der Großzügigkeit des Winters verbunden ist, auch wenn es den Mythos auf den Boden der Tatsachen zurückholt, wenn man ihn im Siedlungsviertel Plätzchen essen sieht."},sec={{t="Ein langer Tag auf dem Thron",b="Obwohl das Winterhauchfest seine Wurzeln in uralter Titanenlehre und Zwergenmythen über eine unsterbliche Gestalt hat, die in die Kälte des Winters gehüllt ist, verlassen sich moderne Feierlichkeiten stark auf die kommerzielle Unterstützung der Kokelwälder. Ein gewöhnlicher Zwerg verbringt am Festtagsbaum im Siedlungsviertel von Eisenschmiede erschöpfende Stunden in der Verkleidung von Altvater Winter und nimmt dabei die Festtagswünsche von Bürgern und erwartungsvollen Kindern gleichermaßen entgegen."},{t="Festliche Stimmung backen",b="Nachdem der ansässige Altvater Winter den ganzen Tag lang Geschenkwünsche angehört hat, entwickelt er unweigerlich selbst einen kräftigen Appetit. Anstatt um etwas Extravagantes zu bitten, wünscht er sich eine einfache Stärkung: fünf frisch gebackene Lebkuchenplätzchen, hergestellt mit Festtagsgewürzen, und eine Eiskalte Milch, um sie hinunterzuspülen. Der Tausch bietet einem erschöpften Festtagsarbeiter einen Moment der Erleichterung und verbreitet gute Stimmung in der verschneiten Hauptstadt."}},faq={{q="Wo finde ich Altvater Winter in Eisenschmiede?",a="Altvater Winter sitzt neben dem großen Festtagsbaum und dem Stand der Kokelwälder im Siedlungsviertel von Eisenschmiede, umgeben von festlichen Dekorationen.",al={"wo ist altvater winter","standort altvater winter eisenschmiede","weihnachtsmann eisenschmiede standort"}},{q="Wie stellt man Lebkuchenplätzchen her?",a="Das Rezept wird von Händlern der Kokelwälder in der Nähe von Altvater Winter verkauft. Zum Backen werden Kochkunstfertigkeit, Festtagsgewürze vom Festtagshändler sowie Kleine Eier, die man von Wildtieren erhält, benötigt.",al={"wo bekommt man lebkuchenplätzchen","lebkuchenrezept","wie backe ich plätzchen"}},{q="Wo bekomme ich Eiskalte Milch?",a="Eiskalte Milch kann bei fast jedem Gastwirt, Lebensmittelhändler oder Getränkeverkäufer in den Allianz-Hauptstädten erworben werden, einschließlich der Tavernen in ganz Eisenschmiede.",al={"händler für eiskalte milch","wo kann man milch kaufen","milch eisenschmiede"}},{q="Ist dieser Altvater Winter die echte mythische Figur?",a="Nein, es handelt sich um einen zwergischen Darsteller, der von den Kokelwäldern angeheuert wurde, um die legendäre, mit den Titanen verbundene Figur für die Feierlichkeiten zum Winterhauchfest darzustellen.",al={"ist altvater winter echt","wer ist der typ in eisenschmiede","ist er wirklich altvater winter"}},{q="Was schickt Altvater Winter Euch nach Abschluss der Quest?",a="Sobald Ihr ihm die Plätzchen und die Milch überreicht, überreicht Euch Altvater Winter als kleine Anerkennung für Eure Mühen eine Kokelwälder Geschenkpackung.",al={"belohnung leckereien für altvater winter","post von altvater winter","kokelwälder geschenkpackung"}},{q="Können Horde-Spieler diese spezielle Quest abschließen?",a="Diese spezielle Quest wird Allianz-Spielern in Eisenschmiede angeboten. Mitglieder der Horde haben ihre eigene äquivalente Quest, bei der sie Altvater Winter in Orgrimmar besuchen.",al={"kann die horde diese quest machen","horde leckereien für altvater winter"}}},fx={["4b1f8d0d"]={q="Warum möchte Altvater Winter, dass dies erledigt wird?",a="Altvater Winter sitzt den ganzen Tag in Eisenschmiede, hört sich Festtagswünsche an und begrüßt Besucher, ohne eine Pause zu machen. Während das Festhauchfest jedem anderen Freude bringt, haben ihn all die Reden über Festtagsleckereien erschöpft und hungrig gemacht, also bittet er Euch, ihm einen dringend benötigten Snack zu besorgen.",al={"beweggrund altvater winter kekse","warum möchte altvater winter kekse","warum leckereien für altvater winter"}},a70b2277={q="Wofür ist die Eiskalte Milch?",a="Die Eiskalte Milch ist einfach ein erfrischendes Getränk, um die Portion warme Lebkuchenkekse hinunterzuspülen. Den ganzen Tag Reisende zu begrüßen und festliche Wünsche zuzurufen, macht durstig, und nichts ergänzt süße Festtagsplätzchen besser als ein eiskaltes Getränk.",al={"warum eiskalte milch","milch für altvater winter","zweck eiskalte milch"}},cc125737={q="Wofür sind die Lebkuchenkekse?",a="Die Lebkuchenkekse dienen als persönliche Festtagsleckerei für Altvater Winter selbst. Nachdem er Leckereien verteilt und die Wünsche eines Bürgers nach dem anderen angehört hat, sehnt er sich nach einem traditionellen Festhauchkonfekt, das mit Festtagsgewürzen hergestellt wurde, um seine Energie wieder aufzuladen.",al={"lebkuchenkekse leckereien für altvater","warum lebkuchenkekse","kekse für altvater winter"}},["6bf2696f"]={q="Warum braucht Altvater Winter Euch, anstatt die Leckereien selbst zu besorgen?",a="Altvater Winter kann seinen Posten inmitten der Feierlichkeiten nicht verlassen. Er ist am Baum in Eisenschmiede stationiert, um die Menschenmengen zu begrüßen und für Smokywood Pastures Freude zu verbreiten, was bedeutet, dass er an seinen Platz gebunden ist und auf großzügige Passanten wie Euch angewiesen ist, um Besorgungen für Essen zu machen.",al={"warum braucht altvater winter mich","warum kann altvater winter seine kekse nicht selbst besorgen","warum bittet altvater winter einen abenteurer"}}},fp="29,254,22.401.0,20.427.0,48.152.0,36.212.0,29.152.0,50.150.0,64.134.1,47.154.0"}
P.entries["quest:703"] = {n="Gegrillte Bussardflügel",s="Rigglefuzz schwört auf barbecued buzzard wings, eine reichhaltige Sauce auf würzigem Fleisch. Alles für eine Portion ist vorhanden, bis auf die Flügel selbst. Beschafft genug davon, und Rigglefuzz trennt sich vielleicht von dem Rezept.",h="Rigglefuzz schwört auf barbecued buzzard wings, eine reichhaltige Sauce auf würzigem Fleisch.",kw={"ödland","barbecue","bussard","kochen","rezept","rigglefuzz","flügel"},ang={["profession:Cooking"]="Köche aufgepasst: Das Rezept für das Gericht steht im Angebot."},sec={{t="Ein lokaler Favorit",b="Rigglefuzz ist stolz auf barbecued buzzard wings. Die Sauce ist reichhaltig, das Fleisch würzig, und das Aroma zieht weit zu hungrigen Leuten hinüber. Jede Zutat für eine Portion ist bereits zur Hand, alle bis auf die Flügel. Bringt vier Buzzard Wings, und Rigglefuzz teilt vielleicht das Rezept."}},faq={{q="Wer verlangt die bussardflügel?",a="Rigglefuzz möchte Buzzard Wings, um eine Portion barbecued buzzard wings zuzubereiten.",al={"wer vergibt barbecued buzzard wings","wer ist rigglefuzz","questgeber"}},{q="Was bietet Rigglefuzz als Gegenleistung für die Flügel?",a="Rigglefuzz deutet an, das Rezept zu teilen, wenn Ihr genug Flügel bringt.",al={"was ist die belohnung","was bekomme ich","rezept als belohnung"}},{q="Warum benötigt Rigglefuzz Bussardflügel?",a="Rigglefuzz hat alles andere, was für eine Portion barbecued buzzard wings gebraucht wird, und nur die Flügel fehlen.",al={"warum bussarde","rigglefuzz motiv","warum will rigglefuzz flügel"}},{q="Wie viele Flügel möchte Rigglefuzz?",a="Vier Buzzard Wings.",al={"wie viele bussardflügel","anzahl bussardflügel"}}},fp="23,198,16.268.0,31.74.0,51.65.0,39.109.0,36.19.0"}
P.entries["quest:705"] = {n="Perlentauchen",s="Rigglefuzz, ein Goblin, empfindet das Ödland voller bösartiger Raubtiere und dreister Aasfresser und überlebt, indem er trickreich vorgeht: Blitzbomben verscheuchen die Tierwelt. Der Vorrat an zerstoßenem blauem Perlenstaub geht zur Neige, daher werdet Ihr für mehr zum Finsteren Riff im Schlingendorntal geschickt.",h="Rigglefuzz, ein Goblin, empfindet das Ödland voller bösartiger Raubtiere und dreister Aasfresser und...",kw={"ödland","blaue perle","blitzstrahlbombe","perlen tauchen","rigglefuzz","schlingendorntal","das finstere riff"},ang={["profession:Engineering"]="Ingenieure haben guten Grund, sich für Rigglefuzz' Blitzbomben zu interessieren."},sec={{t="Ein trickreicher kleiner Goblin",b="Das Ödland ist unbarmherzig, und Rigglefuzz gibt zu, als kleiner Goblin unter Raubtieren und Aasfressern Angst zu haben. Rigglefuzz kennt das Rezept für Blitzbomben und setzt sie ein, um die Tierwelt zu verscheuchen. Eine Zutat wird knapp: zerstoßener blauer Perlenstaub."},{t="Perlen aus dem Riff",b="Blaue Perlen stammen von den Muscheln am Finsteren Riff im Schlingendorntal. Rigglefuzz scherzt, dass Ihr besser gutes Schuhwerk tragen solltet, wartet dann im Ödland auf neun Stück davon und verspricht, Eure Mühen lohnenswert zu machen."}},faq={{q="Warum benötigt Rigglefuzz blaue Perlen?",a="Rigglefuzz verwendet zerstoßenen blauen Perlenstaub, um Blitzbomben herzustellen, und der Vorrat geht zur Neige.",al={"rigglefuzz perlen","warum perlen tauchen","warum blaue perlen"}},{q="Wo findet man die blauen Perlen?",a="Sie sind in Muscheln am Finsteren Riff im Schlingendorntal zu finden.",al={"wo sind blaue perlen","fundort blaue perlen","finsteres riff perlen"}},{q="Warum benutzt Rigglefuzz Blitzbomben?",a="Das Ödland ist voller bösartiger Raubtiere und dreister Aasfresser, und Blitzbomben verscheuchen die Tierwelt.",al={"warum blitzstrahlbomben","rigglefuzz verteidigung"}},{q="Wie viele blaue Perlen möchte Rigglefuzz haben?",a="Neun blaue Perlen, zurückgebracht zu Rigglefuzz im Ödland.",al={"anzahl blauer perlen","wie viele perlen"}}},fp="12,269,22.261.0,20.207.0,37.93.0,32.58.0,36.104.0,42.61.0"}
P.entries["quest:706"] = {n="Feuerverzauberungen",s="Sigrun Ironhew, der im Ödland auf Nachricht aus Eisenschmiede wartet, kennt eine Technik, um Waffen mit Feuer zu erfüllen. Dafür wird Blut aus dem noch schlagenden Herzen eines seltenen schwarzen Drachenwelpen benötigt, und die Welpen in der Lethlorklamm sind der Ort, an dem ein solcher zu finden ist.",h="Sigrun Ironhew, der im Ödland auf Nachricht aus Eisenschmiede wartet, kennt eine Technik, um Waffen mit Feuer...",kw={"ödland","herz des schwarzen drachen","feranor steeltoe","feurige lohe","eisenschmiede","die lethlorklamm","scalding whelp","scorched guardian","sigrun ironhew"},ang={["faction:Alliance"]="Sigrun Ironhew wartet auf Nachricht aus Eisenschmiede, und dieses Werk ist für die Allianz gedacht."},sec={{t="Das Handwerk eines Lehrlings",b="Sigrun Ironhew erlernte als Lehrling von Feranor Steeltoe, von dem man zuletzt unter den Schmieden eines Jagdtrupps in Lordaeron hörte, eine besondere Methode, um Waffen mit feurigen Verzauberungen zu erfüllen. Sigrun wartet auf Nachricht aus Eisenschmiede und hat sonst wenig zu tun."},{t="Die Welpen der Lethlorklamm",b="Sigrun gibt nur wenige Einzelheiten über das Verfahren preis, außer dass dafür Blut aus dem noch schlagenden Herzen eines seltenen schwarzen Drachenwelpen erforderlich ist. Bringt Sigrun ein Herz von den Welpen jener Klamm, und die Fertigkeit wird Euch gezeigt werden. Die Scalding Whelps und Scorched Guardians dort sind die Wesen, von denen die Herzen stammen."}},faq={{q="Wer hat Sigrun Ironhew diese Verzauberungstechnik beigebracht?",a="Sigrun erlernte sie als Lehrling von Feranor Steeltoe, von dem man zuletzt in Lordaeron bei der Schmiede eines Jagdtrupps hörte.",al={"sigruns lehrer","wer hat sigrun ausgebildet","feranor steeltoe"}},{q="Welche Komponente wird benötigt, um eine Klinge mit Feuer zu belegen?",a="Blut aus dem Herzen eines seltenen schwarzen Drachenwelpen, das noch schlägt.",al={"was braucht sigrun","schwarzer drachenwelpe herz anforderung","feurige lohe materialien"}},{q="Wo sind die schwarzen Drachenwelpen zu finden?",a="In der Lethlorklamm, im östlichen Ödland.",al={"wo findet man schwarze drachen","lethlorklamm welpen","fundort herz des schwarzen drachen"}},{q="Warum verweilt Sigrun Ironhew im Ödland?",a="Auf Nachricht aus Eisenschmiede wartet Sigrun, und in der Zwischenzeit hält Sigrun nichts anderes beschäftigt.",al={"warum ist sigrun im ödland","sigrun ironhew zweck"}},{q="Welche Kreaturen liefern das benötigte Herz?",a="Die Scalding Whelps und Scorched Guardians der Lethlorklamm.",al={"was droppt das herz eines schwarzen drachen","welche welpen haben herzen"}}},fp="24,242,21.245.0,28.303.0,53.114.0,52.77.0,39.43.0,48.106.0,39.61.0"}
P.entries["quest:708"] = {n="Der Flugschreiber",s="Im Magen eines Riesenkondors im Ödland ist eine metallische schwarze Kiste aufgetaucht, deren Oberfläche stark zerfressen ist, als hätte sie in Säure gelegen. Auf ihrer Unterseite ist unter einem Symbol eine Kennzeichnung eingeprägt: Maschine Nr. 19 – Belagerungsbrigade von Eisenschmiede.",h="Im Magen eines Riesenkondors im Ödland ist eine metallische schwarze Kiste aufgetaucht, deren Oberfläche...",kw={"ödland","schwarze kiste","korrodierte schwarze kiste","riesenkondor","hall of arms","belagerungsbrigade von eisenschmiede","pilot langbart"},ang={["faction:Alliance"]="Die Kiste trägt die Markierungen von Eisenschmiede, und ihre Spur endet in Eisenschmiede."},sec={{t="Aus einem Kondor geborgen",b="Die Lochfraßspuren deuten darauf hin, dass die Kiste eine Ewigkeit im Inneren des Kondors lag, während Säure das Metall zersetzte. Dreht Ihr sie um, seht Ihr ein Symbol auf dem Boden eingeprägt, darunter steht: Maschine Nr. 19 – Belagerungsbrigade von Eisenschmiede. Ihr sollt sie zu Pilot Langbart in die Hall of Arms in Eisenschmiede bringen."}},faq={{q="Woher stammte die korrodierte schwarze Kiste?",a="Sie befand sich im Magen eines Riesenkondors im Ödland und scheint dort sehr lange gelegen zu haben.",al={"woher die kiste stammt","wie die kiste hierher kam","ursprung der schwarzen kiste"}},{q="Welche Markierungen sind auf der Kiste eingeprägt?",a="Auf dem Boden ist ein Symbol eingeprägt, und darunter steht geschrieben: Maschine Nr. 19 – Belagerungsbrigade von Eisenschmiede.",al={"was steht auf der kiste","markierungen auf der schwarzen kiste","inschrift der kiste"}},{q="Wer soll die Kiste erhalten?",a="Pilot Langbart in der Hall of Arms in Eisenschmiede.",al={"wer die kiste erhält","wohin die schwarze kiste kommt","wem die kiste gebracht werden soll"}}},fp="13,226,20.271.0,43.104.0,37.98.0,35.50.0"}
P.entries["quest:71"] = {n="Meldung an Thomas",s="„Meldung an Thomas“ ist eine Quest im östlichen Wald von Elwynn, die sich mit der Untersuchung von Wache Thomas bezüglich der vermissten Wachen von Sturmwind in der Nähe der östlichen Wasserwege befasst. Ein Abenteurer unterstützt Wache Thomas an der östlichen Brücke, indem er das Schicksal seiner vermissten Kameraden untersucht und Bericht über die Lage entlang des Flusses erstattet.",h="„Meldung an Thomas“ ist eine Quest im östlichen Wald von Elwynn, die sich mit der Untersuchung von Wache...",kw={"brücke","wald von elwynn","goldhain","wache thomas","malakai","medaillons","murlocs","rolf"},ang={["faction:Alliance"]="Der Tod von Rolf und Malakai verdeutlicht den verwundbaren Zustand der Grenzen des Wald von Elwynn, wo selbst alltägliche Flusspatrouillen aufgrund von Personalmangel überwältigt werden können.",["race:Human"]="Das Bergen der Medaillons der gefallenen Wachen bietet ein Maß an Ehre und Abschluss für die Soldaten von Sturmwind, die bei der Verteidigung der inneren Straßen des Königreichs starben."},sec={{t="Eine düstere Bestätigung",b="Wache Thomas hält den Übergang zwischen Goldhain und dem Holzfällerlager des Osttals mit nur sehr wenigen Männern. Als zwei seiner Kameraden, Malakai und Rolf, in den Flusslanden verschwanden, bestand die Hoffnung, dass sie lediglich abgeschnitten oder aufgehalten wurden. Die Rückgabe ihrer geborgenen Dienstmedaillons an die Brücke löscht diese Hoffnung aus und bestätigt, dass beide Wachen in der Nähe der Wasserwege erschlagen wurden."},{t="Die Bedrohung am Wasser",b="Monatelang hat die Führung von Sturmwind Murlocs weitgehend als lästige Flussbewohner abgetan und stattdessen Banditeneinsätze und breitere Grenzen des Königreichs priorisiert. Das Abschlachten zweier bewaffneter Wachen von Sturmwind entlang der Binnengewässer zeugt von organisierter Brutalität. Mit dem Beweis in der Hand erkennt Thomas, dass die östliche Grenze von Elwynn vor einem aktiven Angriff steht, was ihn dazu zwingt, eine Reaktion zu fordern, bevor die Holzfällerrouten und Siedlungen überrannt werden."}},faq={{q="Wo steht Wache Thomas?",a="Wache Thomas ist an der Steinbrücke stationiert, die den Fluss im östlichen Wald von Elwynn überquert und die Straße zwischen Goldhain und dem Holzfällerlager des Osttals verbindet.",al={"thomas standort","wache thomas brücke","wo ist wache thomas"}},{q="Wer waren Rolf und Malakai?",a="Rolf und Malakai waren Wachen von Sturmwind, die ausgesandt wurden, um den östlichen Wald von Elwynn zu patrouillieren. Beide wurden von Murlocs überwältigt und getötet, die entlang der Flussufer und des Stonecairn Lake lauerten.",al={"vermisste wachen elwynn","wer war rolf","wer war malakai"}},{q="Warum waren ihre Medaillons notwendig?",a="Die Medaillons dienten als offizielle Identifikation für die Stadtwachen von Sturmwind. Ihre Rückgabe lieferte Wache Thomas den unbestreitbaren Beweis, dass seine vermissten Männer im Dienst gefallen waren.",al={"warum medaillons","zweck der wachenmedaillons"}},{q="Warum ist der Murloc-Angriff so eine große Sache?",a="Murlocs wurden gemeinhin als primitive, feige Plagegeister und nicht als tödliche Bedrohung für ausgebildete Soldaten angesehen. Der Tod von zwei bewaffneten Wachen beweist, dass die Flussstämme mutiger geworden sind und koordinierte Hinterhalte ausführen können.",al={"warum sind murlocs eine bedrohung","sind murlocs gefährlich elwynn"}},{q="Was passiert nach dem Bericht an Thomas?",a="Thomas bittet Euch, einen Bericht über den Tod der Wachen und die wachsende Murloc-Bedrohung zu Marschall Dughan nach Goldhain zu bringen. Dughan warnt, dass die Verteidigung der Region bereits bis an die Grenzen ausgelastet ist.",al={"nächste quest nach meldung an thomas","was tut thomas als nächstes"}},{q="Warum ist Wache Thomas allein an der Brücke postiert?",a="Das Militär von Sturmwind ist im gesamten Reich überlastet, König Varian Wrynn ist verschwunden und die Ressourcen sind knapp. Außenposten wie die östliche Brücke haben nur minimales Personal, um wichtige Transitrouten zu bewachen.",al={"warum ist thomas allein","sturmwind brückenwache allein"}}},fx={d4d51b05={q="Warum die Medaillons an Wache Thomas übergeben?",a="Wache Thomas sandte Patrouillen zum Fluss, doch sie verschwanden ohne ein Wort. Rolf und Malakai gefallen in den Schilf liegen zu finden, gibt eine düstere Gewissheit über ihr Ende. Ihre geborgenen Medaillons an Thomas zurückzugeben, beweist zweifelsfrei, was seinen Männern zugestoßen ist, und warnt ihn vor der tödlichen Murloc-Präsenz entlang des östlichen Wassers.",al={"warum bei thomas melden","warum medaillons zu thomas bringen","zweck der meldung an thomas"}},["3744e02c"]={q="Warum seid Ihr die Person, die die Medaillons an Thomas zurückgibt?",a="Rolf und Malakai sind tot, erschlagen von den Murlocs tief im feindlichen Flussuferdorf. Wache Thomas ist allein an der östlichen Brücke stationiert und kann seinen Posten nicht unbewacht lassen. Als Reisender, der die gefallenen Wachen fand und den Murlocs trotzte, um ihre Abzeichen zu bergen, fällt die Aufgabe an Euch, die düstere Nachricht zurückzubringen.",al={"warum ich bei thomas melden","warum bringe ich die medaillons"}}},fp="16,219,19.300.0,26.390.0,30.144.0,26.154.1,36.133.1,41.180.1,44.185.1,47.196.0"}
P.entries["quest:710"] = {n="Element-Studie: Fels",s="Lotwil Veriatus hat im Ödland Halt gemacht, um an Fesseln der Elementarbindung zu arbeiten. Um einige Offensivzauber und ein paar zusammengebaute Apparate zu testen, benötigt Lotwil kleine Steinsplitter von den niederen Steinelementaren in der Nähe.",h="Lotwil Veriatus hat im Ödland Halt gemacht, um an Fesseln der Elementarbindung zu arbeiten.",kw={"ödland","niedere steinelementare","lotwil veriatus","fesseln der elementarbindung","kleine steinsplitter","das studium der elemente: stein"},ang={["class:Mage"]="Magier sind diejenigen, denen Lotwils Fesseln dienen sollen."},sec={{t="Elementarfesseln",b="Hier im Ödland arbeitet Lotwil Veriatus an einem Projekt: Fesseln der Elementarbindung. Sobald sie fertiggestellt sind, würden sie es Magiern ermöglichen, noch stärkere Elementare für noch größere Zwecke zu beschwören. Um anzufangen, möchte Lotwil zehn kleine Steinsplitter haben, die leicht von den niederen Steinelementaren in den Hügeln unmittelbar westlich erbeutet werden können."}},faq={{q="Wer verlangt nach den Steinsplittern?",a="Lotwil Veriatus, der im Ödland Halt gemacht hat, um an einem Projekt zu arbeiten.",al={"wer gibt diese quest","questgeber","lotwil veriatus"}},{q="Woran arbeitet Lotwil Veriatus?",a="Fesseln der Elementarbindung, die es Magiern ermöglichen sollen, noch mächtigere Elementare zu beschwören.",al={"lotwil projekt","fesseln der elementarbindung","was baut lotwil"}},{q="Warum benötigt Lotwil kleine Steinsplitter?",a="Sie dienen dazu, einige von Lotwils neuesten Offensivzaubern und ein paar zusammengebaute Apparate zu testen.",al={"warum steinsplitter","zweck der splitter","wofür sind splitter"}},{q="Wo findet man die Steinsplitter?",a="Von den niederen Steinelementaren in den Hügeln unmittelbar westlich von Lotwil.",al={"wo splitter finden","fundort niederer steinelementare","steinsplitter quelle"}}},fp="27,221,18.314.0,35.70.0,35.87.0,40.95.0,33.72.0"}
P.entries["quest:711"] = {n="Element-Studie: Fels",s="Lotwil Veriatus lobt Euch als fähiger als alle Lehrlinge von Lotwil zusammen und verlangt nach dem nächsten Schritt der Tests. Diesmal werden drei große Steinplatten benötigt, Stücke, die man am besten bei Felselementaren findet.",h="Lotwil Veriatus lobt Euch als fähiger als alle Lehrlinge von Lotwil zusammen und verlangt nach dem nächsten...",kw={"ödland","große steinplatten","lotwil veriatus","fels elementare","steinplatten","study of the elements: rock"},sec={{t="Größere Stücke",b="Die nächsten Teile von Lotwil Veriatus' Arbeit erfordern mehr Stärke. Felselementare haben größere, robustere Körper, weshalb sie mit größerer Wahrscheinlichkeit Stücke bei sich tragen, die groß genug für die Tests sind. Lotwil schickt Euch weiter nach Westen oder nach Südosten entlang der Ränder der Berge und lässt Euch drei große Steinplatten sammeln. Lotwil braucht eine Weile, um die kleineren Stücke zu testen, die Ihr zuvor gebracht habt."},{t="Lotwils Hoffnungen",b="Lotwils Zauber wirkten auf die kleineren Stücke genau wie vorhergesagt. Wenn das nächste Experiment so gut verläuft wie vorausgesehen, würden die Elementare unter Lotwils Kontrolle alles in den Schatten stellen, was zuvor beschworen wurde."}},faq={{q="Wer schickt Euch los, um die großen Platten zu holen?",a="Lotwil Veriatus, der im Ödland arbeitet.",al={"wer gibt diese quest","lotwil quest","geber von study of the elements"}},{q="Was ging dieser Bitte voraus?",a="Das frühere Study of the Elements: Rock, bei dem Ihr Lotwil kleine Steinsplitter gebracht habt.",al={"vorherige quest","vorheriger schritt","was habe ich zuvor getan"}},{q="Wo sollen sich die Felselementare laut Lotwil befinden?",a="Weiter westlich von Lotwil oder südöstlich entlang der Ränder der Berge.",al={"wo sind die elementare","orte der elementare","wo man steinplatten findet"}},{q="Warum benötigt Lotwil größere Steinplatten?",a="Lotwil benötigt größere Stücke für die nächsten Tests. Felselementare haben größere, kräftigere Körper, sodass ihre Stücke groß genug sind.",al={"warum große steinplatten","zweck der steinplatten","lotwils forschungsziel"}}},fp="27,202,13.360.0,14.194.0,36.48.0,30.88.0,50.70.0,40.126.0"}
P.entries["quest:712"] = {n="Element-Studie: Fels",s="Lotwil Veriatus benötigt noch ein weiteres Teil von den Elementaren des Ödlands: Armschienen der Felsbindung, erbeutet von größeren Felselementaren. Nach Lotwils Einschätzung genügen sie, um die Stärke von Lotwils eigenen Fesseln zu bemessen.",h="Lotwil Veriatus benötigt noch ein weiteres Teil von den Elementaren des Ödlands: Armschienen der Felsbindung...",kw={"ödland","armschienen der felsbindung","größere felselementare","kharanos","lotwil veriatus","lucien","oger","servo"},sec={{t="Die Fesseln bemessen",b="Nach den Steinplatten bittet Lotwil Veriatus um ein letztes Teil von den Elementaren des Ödlands. Armschienen der Felsbindung, erbeutet von größeren Felselementaren, sollten es Lotwil ermöglichen, die Stärke der im Bau befindlichen Fesseln zu beurteilen. Lotwils Hellseherei zeigte eine Gruppe der Elementare im Südwesten nahe einigen Ogern, wenn die Erinnerung nicht trügt. Fünf Armschienen sind erwünscht, damit Reserven vorhanden sind, da Servo berüchtigt dafür ist, Reagenzien und Forschungen zu verlegen."}},faq={{q="Warum benötigt Lotwil die Armschienen?",a="Nach Lotwils Berechnungen genügen die Armschienen der Felsbindung, um die Stärke von Lotwils eigenen Fesseln zu bemessen.",al={"warum armschienen der felsbindung","wofür sind armschienen","lotwil bindungsarmschienen"}},{q="Warum verlangt Lotwil fünf Armschienen?",a="Um Ersatz zu haben, da Servo berüchtigt dafür ist, Lotwils Reagenzien und Forschungen zu verlegen.",al={"warum fünf armschienen","wie viele armschienen","warum ersatz"}},{q="Wo befinden sich die größeren Felselementare?",a="Eine Gruppe von ihnen befindet sich südwestlich von Lotwil nahe einigen Ogern, laut Lotwils Hellseherei. Die Hügel um Camp Cagg sind ihre Heimat.",al={"wo sind felselementare","aufenthaltsort größerer felselementare","wo armschienen finden"}},{q="Was geschieht mit den zuvor gesammelten Steinplatten?",a="Lucien wird die übrigen Platten zurück nach Kharanos bringen, sobald die Arbeit hier getan ist, da sie sich erneut als nützlich erweisen könnten.",al={"was geschah mit steinplatten","lucien steinplatten","kharanos platten"}}},fp="27,219,20.431.0,33.112.0,37.89.0,46.134.0,50.114.0"}
P.entries["quest:713"] = {n="Kühlaufsätze setzen sich durch",s="Lotwil Veriatus möchte eine Phiole Frostöl haben, um die Fesseln zu verstärken, die einen herbeigerufenen Freund in Schach halten sollen. Bro'kin, ein Goblinfreund von Lotwil in Alterac, kann Euch beibringen, es herzustellen.",h="Lotwil Veriatus möchte eine Phiole Frostöl haben, um die Fesseln zu verstärken, die einen herbeigerufenen...",kw={"ödland","bro'kin","coolant heads prevail","frostöl","lotwil veriatus","die ruinen von alterac","fesseln"},sec={{t="Ein lebenswichtiges Kühlmittel",b="Lotwil Veriatus schwört darauf, dass nichts einen Motor oder Zahnräder so sehr vor Überhitzung bewahrt wie Frostöl, und dass sein Wert als Schmiermittel ohnegleichen ist. Es hilft magischen Gegenständen außerdem dabei, ihre Verzauberungen beizubehalten. Eine Phiole würde die magische Kapazität von Lotwils Fesseln erhöhen und sie stark genug machen, um den herbeigerufenen Freund daran zu hindern, alle zu töten."},{t="Bro'kin von Alterac",b="Bro'kin, ein Goblinfreund von Lotwil, kann Euch beibringen, das Öl herzustellen. Bro'kin befindet sich in den Ruinen von Alterac und verkauft von einem Platz oben auf der Mauer der alten Stadt aus."},{t="Wenn das Öl eintrifft",b="Sobald das Öl eintrifft, bezeichnet Lotwil es als das perfekte Kühlmittel für die neuen Armschienen. Lotwil schwört, dass all Lotwils Habseligkeiten an Servo gehen werden, sollten die Verzauberungen nicht ein Jahrhundert lang halten. Lotwil erwartet außerdem, dass die Magier der Versammlung voller Ehrfurcht sein werden, wenn das Werk vollendet ist."}},faq={{q="Warum benötigt Lotwil Veriatus Frostöl?",a="Eine Phiole würde die magische Kapazität von Lotwils Fesseln erhöhen, sodass sie stark genug sind, um den herbeigerufenen Freund daran zu hindern, alle zu töten.",al={"warum frostöl","wofür ist frostöl","lotwil öl"}},{q="Wer weiß, wie man Frostöl braut?",a="Bro'kin, ein Goblinfreund von Lotwil, kann Euch beibringen, es herzustellen. Er befindet sich in den Ruinen von Alterac, oben auf einer Mauer der alten Stadt.",al={"wer lehrt frostöl","wo lernt man frostöl","brokin rezept"}},{q="Was ist das Besondere an Frostöl?",a="Lotwil sagt, dass nichts einen Motor oder Zahnräder so sehr vor Überhitzung bewahrt wie dieses, dass es als Schmiermittel ohnegleichen vorhält und dass es magischen Gegenständen hilft, Verzauberungen beizubehalten.",al={"frostöl eigenschaften","warum frostöl gut ist"}}},fp="21,185,15.338.0,18.158.0,20.268.1,40.141.0,32.124.0,32.171.0"}
P.entries["quest:714"] = {n="Gyro... Was?",s="Nachdem Ihr Lotwil Veriatus das Frostöl aus Coolant Heads Prevail gebracht habt, findet Ihr Lotwil immer noch in eine Apparatur im Ödland vertieft vor. Ein kleiner, aber entscheidender Teil fehlt: ein Gyrochronatom.",h="Nachdem Ihr Lotwil Veriatus das Frostöl aus Coolant Heads Prevail gebracht habt, findet Ihr Lotwil immer noch...",kw={"ödland","apparatur","coolant heads prevail","gyrochronatom","kharanos","lotwil veriatus"},ang={["profession:Engineering"]="Ingenieure können ein Gyrochronatom selbst herstellen."},sec={{t="Ein entscheidender Teil",b="Lotwil Veriatus, abgelenkt von der Arbeit, sagt, Ihr hättet die Arbeit weit über alle Maßstäbe hinaus gut erledigt, und fordert Euch auf, Euch um Arbeit zu bewerben, solltet Ihr Euch jemals in Kharanos begegnen. Dann folgt ein hastiges Greifen nach etwas und die eigentliche Bitte: ein Gyrochronatom. Es ist ein kleines Teil, wie Lotwil zugibt, aber ein entscheidendes. Bringt eines und das Projekt sollte bereit zur Fertigstellung sein."},{t="Die Übergabe",b="Als Ihr das Gyrochronatom übergebt, ergreift Lotwil es mit einem Schrei und sagt, dass die Arbeit wahrhaftig fast getan sei und dieses Projekt im Moment oberste Priorität habe. Das Versprechen, bald fertig zu werden, schwankt jedoch ständig – von ein paar Minuten bis hin zu vielleicht viel länger."}},faq={{q="Wer bittet um das Gyrochronatom?",a="Lotwil Veriatus, der im Ödland an einer Apparatur arbeitet.",al={"wer gibt gyro what","gyro what questgeber","lotwil veriatus ödland"}},{q="Wofür benötigt Lotwil Veriatus das Gyrochronatom?",a="Es ist ein kleines, aber ziemlich entscheidendes Teil, und damit sollte Lotwil bereit sein, das Projekt abzuschließen.",al={"warum gyrochronatom","was baut lotwil"}},{q="Was hat es mit dem Angebot bezüglich Kharanos auf sich?",a="Abgelenkt von der Arbeit sagt Lotwil, dass Ihr Euch gerne um Arbeit bewerben könnt, falls Ihr Euch jemals in Kharanos treffen solltet.",al={"lotwil kharanos","kharanos jobangebot"}},{q="Wo kann man ein Gyrochronatom finden?",a="Ingenieure stellen sie her, und sie können auch bei Ingenieursbedarfshändlern gekauft werden.",al={"wie bekommt man gyrochronatom","gyrochronatom quelle","wo gyrochronatom kaufen"}}},fp="13,193,14.370.0,15.250.1,36.65.0,53.98.0,33.111.0,35.76.0"}
P.entries["quest:716"] = {n="Stein ist besser als Stoff",s="Lucien Tosselwrench weiß, wie geizig Lotwil sein kann, und bietet an, etwas für Eure Mühen herzustellen: verzauberte Armschienen, gefertigt aus den zusätzlichen Steinen, die Ihr gesammelt habt. Was Lucien fehlt, sind Patterned Bronze Bracers eines Schmieds.",h="Lucien Tosselwrench weiß, wie geizig Lotwil sein kann, und bietet an, etwas für Eure Mühen herzustellen...",kw={"ödland","elementarstein","verzauberte armschienen","lotwil veriatus","lucien tosselwrench","patterned bronze bracers"},ang={["profession:Blacksmithing"]="Die bronzenen Armschienen, die Lucien möchte, stammen von einem Schmied."},sec={{t="Ein Dankeschön für Eure Mühen",b="Nach den Prüfungen von Study of the Elements: Rock räumt Lucien Tosselwrench ein, wie geizig Lotwil sein kann, und möchte es bei Euch wiedergutmachen. Lucien war mit den zusätzlichen Steinen beschäftigt, die Ihr gesammelt habt, und kann feine verzauberte Armschienen herstellen. Sie könnten Euch sogar davor bewahren, was Lucien die kommende Gräueltat von Lotwils neuester Erfindung nennt."},{t="Was Lucien benötigt",b="Um die Armschienen fertigzustellen, benötigt Lucien Patterned Bronze Bracers, wie ein Schmied sie herstellt. Lucien warnt, dass es klug ist, nicht lange zu warten, da niemand weiß, was als Nächstes geschieht."}},faq={{q="Wer bietet an, die Armschienen herzustellen?",a="Lucien Tosselwrench bietet im Ödland an, verzauberte Armschienen aus den zusätzlichen Steinen herzustellen, die Ihr gesammelt habt.",al={"wer vergibt stone is better than cloth","questgeber","lucien tosselwrench"}},{q="Warum stellt Lucien diese Rüstung für Euch her?",a="Lucien weiß, wie geizig Lotwil sein kann, und möchte etwas für all Eure Mühen herstellen. Es könnte Euch auch vor Lotwils neuester Erfindung schützen.",al={"warum armschienen herstellen","lucien motiv","lotwil geizig"}},{q="Was benötigt Lucien, um die Armschienen fertigzustellen?",a="Patterned Bronze Bracers, wie sie ein Schmied herstellt.",al={"welcher gegenstand wird benötigt","erforderliche gegenstände","gemusterte bronzearmschienen benötigt"}},{q="Was geht dieser Quest voraus?",a="Sie folgt auf Lotwils dritte Bitte in Study of the Elements: Rock.",al={"vorherige quest","voraussetzung für stone is better than cloth"}}},fp="26,220,28.326.0,17.175.0,32.107.0,40.148.0,53.54.0,29.62.0"}
P.entries["quest:7162"] = {n="Flaggenjagd",s="Flaggenjagd ist ein Initiationsritus, der von Leutnant Haggerdin für Rekruten der Allianz abgehalten wird, die sich der Stormpikegarde in Alterac anschließen wollen. Um eine offizielle Stormpike-Insignie zu erhalten, müssen Anwärter in die von Harpyien heimgesuchten Icewing Caverns vordringen und eine dort aufgestellte Schlachtstandarte bergen. Den eigenen Mut in der Höhle zu beweisen, markiert den ersten Schritt, um in den militärischen Rängen der Expedition aufzusteigen.",h="Flaggenjagd ist ein Initiationsritus, der von Leutnant Haggerdin für Rekruten der Allianz abgehalten wird...",kw={"dun baldar","haggerdin","harpyien","icewing caverns","insignie","flaggenjagd","stormpike","banner der sturmlanzen"},ang={["faction:Alliance"]="Die Stormpike-Expedition stellt das primäre militärische Unterfangen der Allianz in Alterac dar und verbindet archäologische Ambitionen der Zwerge mit der territorialen Verteidigung gegen die Horde.",["race:Dwarf"]="Die Stormpikegarde wird vorwiegend von Zwergen aus Eisenschmiede angeführt, die nach uralten Relikten und Titanengeheimnissen suchen, was diese Prüfung zu einem Eintritt in eine der stolzesten Militäreinheiten Eures Volkes macht."},sec={{t="Ein Maß an Mut",b="Die Stormpikegarde führt einen unerbittlichen Feldzug im Alteractal gegen den Frostwolfklan. Leutnant Haggerdin, der die Streitkräfte vom Lager der Allianz im Alteracgebirge aus koordiniert, weigert sich, unerfahrene Rekruten ohne Prüfung auf das Schlachtfeld zu schicken. Bevor er einem Soldaten einen offiziellen Platz in der Garde gewährt, verlangt Haggerdin einen Beweis für Geschick und Nervenstärke, indem er ihn in die tückischen Icewing Caverns südwestlich von Dun Baldar entsendet."},{t="Die Icewing Caverns",b="Die Prüfung ist vom Konzept her simpel, in ihrer Ausführung jedoch tödlich: Ein Stormpike-Banner steht tief in den unterirdischen Eistunneln aufgestellt. Die Höhlen sind keineswegs leer; grausame Frostharpyien nisten in den froststarren Nischen und zerfleischen unvorsichtige Eindringlinge mit Vorliebe. Mit dem unversehrten Banner zurückzukehren, beweist, dass ein Rekrut gefährliches Gelände durchqueren, brutale Raubtiere überstehen und unter Druck Disziplin wahren kann."},{t="Die Stormpike-Insignie",b="Das Überleben in der Höhle und die Rückbringung der Standarte bringen einem Soldaten die Insignie eines Stormpike-Initianden ein, was ihn offiziell in den Reihen der Expeditionsstreitkräfte willkommen heißt. Wie Haggerdin verspricht, ist die Insignie nicht bloß ein Schmuckstück – sie ist ein Rangabzeichen, das aufgewertet werden kann, sobald sich ein Soldat mehr Ehre auf dem Schlachtfeld verdient, mit dem Ziel legendärer Ehrungen wie dem Eye of Command."}},faq={{q="Wer ist Leutnant Haggerdin?",a="Leutnant Haggerdin ist ein im Alteracgebirge stationierter Offizier der Allianz, der die Rekrutierung und die Anerkennung im Felde für die Stormpikegarde überwacht. Er prüft angehende Kämpfer und belohnt ihre Dienste mit militärischen Insignien.",al={"leutnant haggerdin","haggerdin","wer gibt flaggenjagd"}},{q="Wo befinden sich die Icewing Caverns?",a="Die Icewing Caverns liegen südwestlich der Allianzfeste Dun Baldar in den eisigen Weiten des Alteractals. Es sind labyrinthische, unterirdische Tunnel, die aus Eis und Stein gehauen wurden.",al={"icewing caverns standort","wo sind die icewing caverns","banner standort"}},{q="Welche Bedrohungen lauern in den Icewing Caverns?",a="Die Höhlen werden von wilden Eisharpyien bewohnt. Leutnant Haggerdin warnt Rekruten davor, dass diese wilden Kreaturen nicht zögern werden, Eindringlinge aus dem Hinterhalt anzugreifen und ihnen die Kehle herauszureißen.",al={"harpyien","was ist in den icewing caverns","icewing harpyien"}},{q="Warum verlangt die Stormpikegarde diesen Test?",a="Der Kampf gegen die Frostwolforcs ist brutal und unbarmherzig. Haggerdin besteht darauf, ungeprüfte Rekruten auszusieben, bevor sie an die Hauptfront gelangen, um sicherzustellen, dass jeder Soldat unter ihrem Banner unter widrigen Bedingungen kämpfen kann.",al={"warum flaggenjagd","warum die bannerprüfung machen","stormpike initiation"}},{q="Was ist die Belohnung für den Abschluss der Flaggenjagd?",a="Der Abschluss der Prüfung belohnt den Rekruten mit einer Stormpike-Initiandeninsignie. Haggerdin wertet diese Insignie zu mächtigeren Versionen auf, während der Soldat im Alteractal Ehre ansammelt.",al={"stormpike insignie","eye of command","flaggenjagd belohnung"}},{q="Wer sind die von Haggerdin erwähnten Frostwölfe?",a="Der Frostwolfklan ist ein Orc-Klan, der das Alteractal seit seinem Exil vor Jahrzehnten bewohnt. Die Stormpikegarde betrachtet sie als feindselige Wilde, die den Interessen der Allianz und den Ausgrabungen im Tal im Weg stehen.",al={"frostwolfwilde","wer sind die frostwölfe","frostwolfklan"}}},fx={b9e84d22={q="Was ist der Zweck des Banners der Sturmlanzen in den Höhlen?",a="Das tief in den gefährlichen Eisflügelhöhlen aufgestellte Banner der Sturmlanzen dient als Prüfungsmarkierung für Rekruten, die sich der Expeditionstruppe anschließen wollen. Um es zu beanspruchen, müsst Ihr den bösartigen Harpyien trotzen, die die Höhlen befallen, und den Mut, den Einfallsreichtum und die Entschlossenheit beweisen, die ein wahrer Sturmlanzensoldat benötigt, bevor er jemals das offene Schlachtfeld betritt.",al={"was ist das banner der sturmlanzen","warum banner in den eisflügelhöhlen","zweck banner der sturmlanzen"}}},fp="15,389,20.439.0,19.426.0,22.372.0,28.231.0,30.191.0,46.183.0,47.226.0,53.189.0,47.224.0"}
P.entries["quest:717"] = {n="Erdbeben",s="Garek ist zu dem Schluss gekommen, dass man Blacklash und Hematus nicht zutrauen kann, in ihrem Gefängnis in Lethlor zu verbleiben. Schwarze Drachen sind dort eingezogen und Oger haben das Zeichen der Erde an sich genommen, daher schickt Garek Euch aus, um die Lindwürmer zu befreien und sie zu töten.",h="Garek ist zu dem Schluss gekommen, dass man Blacklash und Hematus nicht zutrauen kann, in ihrem Gefängnis in...",kw={"blacklash","garek","hematus","kirin tor","krasus","die lethlorklamm","runensteine","seal of the earth","zeichen der erde","tremors of the earth"},ang={["faction:Alliance"]="Gareks Bitte ist eine für die Allianz."},sec={{t="Ein versagendes Gefängnis",b="Garek kann nicht mehr sicher sein, dass Blacklash und Hematus eingesperrt bleiben. Schwarze Drachen hausen nun in Lethlor, und Oger haben sich mit dem Zeichen der Erde davonstehlen können. Garek urteilt, dass etwas Härteres nötig ist und die Lindwürmer sterben müssen."},{t="Das Siegel brechen",b="Drei Runensteine halten die Lindwürmer eingesperrt, und nur das Zeichen der Erde kann sie herbeiholen. Ihr setzt das Zeichen an den Pillars of Amethyst, Opal und Diamond ein und platziert die Runensteine dann im Seal of the Earth. Das befreit das Paar, und Ihr erschlagt sie. Garek will Schattenbringers Bindungen, die Ketten von Hematus und das Zeichen der Erde zurückhaben."},{t="Nach der Tat",b="Sobald die Lindwürmer tot sind, erklärt Garek, dass die Kirin Tor aufhören können, sich wegen Lethlors Gefangenen zu sorgen. Garek gedenkt, einem Meister, Krasus, Erfolg zu melden, der sicherlich erfreut sein wird."}},faq={{q="Wer sind Blacklash und Hematus?",a="Lindwürmer, die in Lethlor hinter einem Siegel gefangen gehalten werden.",al={"blacklash und hematus","wer die drachen sind","was in lethlor eingesperrt ist"}},{q="Warum müssen die Lindwürmer getötet werden, anstatt sie weiter eingesperrt zu halten?",a="Garek kann nicht mehr sicher sein, dass sie eingesperrt bleiben. Schwarze Drachen leben nun in Lethlor, und Oger haben das Zeichen der Erde an sich genommen.",al={"warum blacklash töten","warum das gefängnis aufbrechen","warum hematus erschlagen"}},{q="Wie wird das Gefängnis entsiegelt?",a="Drei Runensteine werden mit dem Zeichen der Erde von den Säulen genommen und dann im Seal of the Earth platziert.",al={"wie man seal of the earth öffnet","wie man blacklash beschwört","wie man die drachen befreit"}},{q="Was muss zu Garek zurückgebracht werden?",a="Drei Dinge gehen an Garek zurück: Schattenbringers Bindungen, die Ketten von Hematus und das Zeichen der Erde.",al={"was garek zurückzubringen ist","schattenbringers bindungen","ketten von hematus"}},{q="Was geht dieser Quest voraus?",a="Sie folgt auf das frühere Tremors of the Earth.",al={"vorherige quest","voraussetzung für tremors of the earth"}}},fp="20,225,16.231.0,17.335.0,14.182.1,30.47.0,58.127.0,27.109.0,35.101.0,29.44.0"}
P.entries["quest:718"] = {n="Illusionen",s="Auf ihrer eiligen Flucht von der Ausgrabungsstätte von Uldaman ließ die Gruppe um Sigrun Ironhew Wagen und Kisten zurück. Oger aus Camp Kosh nahmen den Karren mit all ihren Waffen mit, und seither hat die Gruppe keine Nahrung mehr.",h="Auf ihrer eiligen Flucht von der Ausgrabungsstätte von Uldaman ließ die Gruppe um Sigrun Ironhew Wagen und...",kw={"ödland","camp kosh","ausgrabung","mirages","oger","sigrun ironhew","vorratskiste","uldaman"},ang={["faction:Alliance"]="Sigrun Ironhew sucht nach Hilfe der Allianz."},sec={{t="Hungrig im Ödland",b="In ihrer Eile, die Ausgrabungsstätte von Uldaman zu verlassen, ließen Sigrun Ironhew und ihre Gefährten viele Wagen und Vorratskisten zurück. Oger aus Camp Kosh haben sich wie die Geier über die Überreste hergemacht. Sie nahmen den Karren mit all den Waffen der Gruppe mit, und seither hat die Gruppe keine Nahrung mehr. Sigrun gibt zu, dass dies peinlich ist, und bittet Euch, die Vorratskiste wiederzubeschaffen."},{t="Bei Eurer Rückkehr",b="Als Ihr zurückkehrt, gesteht Sigrun, während Eurer Abwesenheit einen Mund voll Sand geschluckt zu haben. Sigrun wechselt rasch das Thema und meint, dass die Gruppe heute Abend losziehen, Nahrung finden und wie die Könige speisen werde."}},faq={{q="Wer ist Sigrun Ironhew?",a="Sigrun Ironhew gehört zu einer Gruppe, die die Ausgrabungsstätte von Uldaman in aller Eile verließ und nun ohne Nahrung im Ödland festsitzt.",al={"sigrun ironhew","wer vergibt mirages","wer ist sigrun"}},{q="Warum hungert Sigruns Gruppe?",a="Oger nahmen den Karren mit all ihren Waffen und dergleichen an sich, und seither konnten sie sich keine Nahrung mehr beschaffen.",al={"warum sind sie hungrig","warum kein essen","sigrun nahrungsproblem"}},{q="Wer hat die zurückgelassenen Vorräte an sich genommen?",a="Die einheimischen Oger aus Camp Kosh, die sich über die zurückgelassene Ausrüstung hergemacht haben.",al={"wer stahl die kiste","oger aus camp kosh","wer nahm waffen"}},{q="Was hofft Sigrun zurückzubekommen?",a="Die Vorratskiste, die in der Eile beim Verlassen der Ausgrabungsstätte zurückgelassen wurde.",al={"vorratskiste","was für sigrun beschaffen"}}},fp="7,205,22.364.0,14.192.1,22.123.0,31.114.0,32.81.0,34.71.0"}
P.entries["quest:719"] = {n="Ein Zwerg und sein Werkzeug",s="Ausgrabungsleiter Roggendol warnt davor, dass überall Dark-Iron-Zwerge herumlaufen, die wie der Shadowforge-Klan aussehen. Sie haben gerade die Ausgrabungsstätte angegriffen, an der Roggendol arbeitete, und Roggendol will die Glücksspitzhacke zurück.",h="Ausgrabungsleiter Roggendol warnt davor, dass überall Dark-Iron-Zwerge herumlaufen, die wie der...",kw={"ödland","dark iron","ausgrabung","hammertoe","glücksspitzhacke","ryedol","shadowforge"},sec={{t="Räuber an der Ausgrabung",b="Dark-Iron-Zwerge des Shadowforge-Klans haben nach Ausgrabungsleiter Roggendols Schilderung die Ausgrabungsstätte angegriffen, an der Roggendol arbeitete. Sie töteten fast jeden, darunter Roggendols Boss Hammertoe, und Roggendol entkam nur knapp mit dem nackten Leben. Die Stätte liegt nördlich von Roggendols Position."},{t="Eine Glücksspitzhacke",b="Roggendol überlegt, wie sich ein Teil der Verlorenen Vorräte zurückgewinnen lässt, vor allem seine Glücksspitzhacke. Einer der Dark Iron muss sie bei sich tragen, auch wenn es jeder von ihnen sein könnte. Roggendol hofft, dass Ihr helft, und wartet südlich von Hammertoes Dig Site."}},faq={{q="Wer ist Ausgrabungsleiter Roggendol?",a="Roggendol arbeitete an einer Ausgrabungsstätte, die von Dark-Iron-Zwergen angegriffen wurde. Er entkam nur knapp und wartet nun südlich von Hammertoes Dig Site.",al={"wer ist ryedol","ausgrabungsleiter roggendol","wer gibt a dwarf and his tools"}},{q="Wer griff das Ausgrabungslager an?",a="Dark-Iron-Zwerge, die aussahen, als gehörten sie zum Shadowforge-Klan.",al={"wer griff die ausgrabung an","wer griff hammertoe an","was griff das lager an"}},{q="Was geschah mit Hammertoe?",a="Hammertoe war Roggendols Boss und gehörte zu denjenigen, die bei dem Angriff getötet wurden.",al={"wer ist hammertoe","ist hammertoe am leben","was geschah mit boss hammertoe"}},{q="Wo befindet sich die Glücksspitzhacke?",a="Roggendol glaubt, dass einer der Dark Iron sie hat, obwohl es jeder von ihnen sein könnte.",al={"wo ist ryedols glücksspitzhacke","wie findet man die spitzhacke","wer hat ryedols spitzhacke"}}},fp="21,189,18.287.0,12.233.0,25.131.0,33.59.0,27.70.0,32.76.0"}
P.entries["quest:72"] = {n="Die Legende von Stalvan",s="Dieser Teil der Untersuchung führt Suchende zu den Canals von Sturmwind, wo Verwalter Folsom über den verbliebenen Besitz der ruinierten Familie Flintridge wacht. Auf der Suche nach Antworten bezüglich des mysteriösen Stalvan Dunstmantel müssen Abenteurer die verpackten Besitztümer des Anwesens durchsuchen und sich dabei unruhigen Geistern stellen, die mit einem vergangenen Massaker verbunden sind.",h="Dieser Teil der Untersuchung führt Suchende zu den Canals von Sturmwind, wo Verwalter Folsom über den...",kw={"canals","verwalter folsom","dämmerwald","flintridge","unglückseliger geist","legende von stalvan","massaker","versiegelte kiste","sturmwind","tilloa"},ang={["class:Priest"]="Die Konfrontation mit dem weinenden Unglückseliger Geist in den Stadtkanälen offenbart das anhaltende Leid unschuldiger Seelen, die vor ihrer Zeit ermordet wurden und Frieden durch das Licht fordern.",["faction:Alliance"]="Die stille Tragödie der Familie Flintridge entfaltet sich direkt in der Hauptstadt des Königreichs und legt offen, wie selbst die behütetsten Adelslinien von Sturmwind gewaltsam vernichtet werden können."},sec={{t="Echos eines Massakers",b="Die Verfolgung von Stalvans Spuren führt aus den schattigen Wäldern des Dämmerwald in das Herz von Sturmwind. Neben den Stadtkanälen kümmert sich Verwalter Folsom um das wenige, das vom Haushalt Flintridge geblieben ist. Laut Folsom diente sein Vater dem Anwesen vor ihm und hatte die grausame Aufgabe, nach einem schrecklichen Gemetzel im Haus das Blut aufzuwischen – eine Tragödie, die irgendwie mit dem Namen Stalvan verknüpft ist."},{t="Die Auktion eines ruinierten Hauses",b="Da das Treuhandvermögen der Flintridges vollständig aufgebraucht ist und die Steuerbeamten des Königreichs bereits kreisen, sind die überlebenden Erbstücke und verpackten Habseligkeiten der Familie für eine Auktion vorgesehen. Alle Andenken und Papiere, die das Blutbad überstanden haben, liegen in Versandkisten gestapelt am Ufer der Kanäle. Um Stalvans Spur aufzudecken, müssen diese versiegelten Kisten aufgebrochen werden, bevor der verbliebene weltliche Besitz des Anwesens an Sammler im ganzen Königreich verstreut wird."},{t="Ein unruhiger Schatten",b="Das Stören der Kisten der Verstorbenen bleibt nicht unbemerkt. Das Trauma der Morde haftet noch immer an diesen geretteten Besitztümern und manifestiert sich als rachsüchtiger Unglückseliger Geist, der jeden angreift, der die Hinterlassenschaften der Familie durchsucht. Diese weinende Erscheinung, von der man glaubt, dass sie das Phantom der jungen Tilloa Flintridge ist, bleibt erbittert an die physischen Relikte ihres abrupt gestohlenen Lebens gebunden."}},faq={{q="Wo kann ich Verwalter Folsom finden?",a="Verwalter Folsom ist entlang der Canals in Sturmwind stationiert und steht neben einem Stapel ausrangierter Versandkisten und Haushaltswaren am Wasserweg.",al={"standort verwalter folsom","wo ist folsom","wo ist verwalter folsom in sturmwind"}},{q="Was ist mit der Familie Flintridge passiert?",a="Die Flintridges waren ein wohlhabender Haushalt, der durch ein plötzliches und bösartiges Massaker auseinandergerissen wurde. Wie die Überlieferungen des Verwalters enthüllen, war das Blutbad so umfangreich, dass Folsoms Vater das Anwesen reinigen musste. Wer dafür verantwortlich war, ist noch nicht klar.",al={"flintridge massaker","was war das massaker","wer tötete die familie flintridge"}},{q="Warum sind die Besitztümer der Familie in Kisten entlang der Kanäle verpackt?",a="Das Treuhandvermögen der Familie Flintridge war nach der Tragödie vollständig aufgebraucht. Aufgrund des Drucks der Steuerbeamten des Königreichs wurden die überlebenden Besitztümer des Anwesens in Kisten verpackt und an den Kanälen aufgestellt, um bei einer Auktion liquidiert zu werden.",al={"warum flintridge gegenstände versteigern","warum sind kisten in den kanälen","flintridge treuhand"}},{q="Warum greift ein Geist an, wenn die Kiste geöffnet wird?",a="Das gewaltsame Trauma des Massakers ließ die Seelen der Opfer an ihre früheren Besitztümer binden. Der Unglückseliger Geist, der erscheint, um die Kisten zu verteidigen, wird weithin als der Schatten von Tilloa Flintridge angesehen, einem der ermordeten Kinder.",al={"unglückseliger geist sturmwind","wer ist der unglückselige geist","warum geist in sturmwind kanälen"}},{q="Wie hängt das mit dem Dämmerwald zusammen?",a="Die Untersuchung begann in Dunkelhain als Vermisstenfall bezüglich Stalvan Dunstmantel. Die Rückverfolgung seiner Geschichte führte zurück zu seiner Zeit als Hauslehrer für die Familie Flintridge in Elwynn und Sturmwind.",al={"stalvan dämmerwald verbindung","warum sind wir für eine dämmerwald quest in sturmwind","legende von stalvan stadtverbindung"}},{q="Was findet Ihr in der versiegelten Kiste?",a="Das Durchsuchen der verpackten Möbel und persönlichen Gegenstände bringt muffige Erbstücke zum Vorschein und, nahe dem Boden, eine herausgerissene Seite aus Stalvans Tagebuch, die zum nächsten Hinweis wird.",al={"was ist in der kiste","versiegelte kiste hinweis","inhalt flintridge kiste"}}},fx={d6eccd2d={q="Warum lässt Verwalter Folsom Euch die Kisten durchsuchen?",a="Verwalter Folsom hat persönlich nicht mehr viel, um das er sich kümmern müsste. Die Stiftung der Familie Flintridge ist völlig versiegt, was ihr verbleibendes Anwesen in Ruinen hinterlässt und ihren letzten Besitz für das Auktionshaus bestimmt, um Steuereintreiber zu befriedigen. Während seine Familie dem Anwesen über Generationen diente – sein Vater hatte das Blut nach dem grausamen Massaker beseitigt –, hat Folsom selbst keinen Grund, die düstere Wahrheit zu verbergen, und gestattet Eurer Neugier einfach, das zu durchwühlen, was übrig geblieben ist.",al={"beweggrund verwalter folsom","warum hilft folsom","warum kisten durchsuchen lassen"}}},fp="21,349,20.405.0,29.431.0,16.377.1,34.153.0,39.231.0,66.215.0,50.234.0,39.192.0,41.163.0"}
P.entries["quest:720"] = {n="Ein Hoffnungsschimmer",s="Eine zerknitterte Karte trägt ein paar mit Kreide gekritzelte Worte: Ein Hilferuf an Roggendol von Hammertoe, der besagt, dass sie Hammertoe nach Uldaman bringen, und um Hilfe bittet. Ausgrabungsleiter Roggendol sollte erfahren, dass Hammertoe Grez lebt.",h="Eine zerknitterte Karte trägt ein paar mit Kreide gekritzelte Worte: Ein Hilferuf an Roggendol von Hammertoe...",kw={"ein zeichen der hoffnung","ödland","kreidenotiz","zerknitterte karte","hammertoe grez","ausgrabungsleiter roggendol","uldaman"},sec={{t="Worte in Kreide",b="Flüchtig mit Kreide auf die zerknitterte Karte gekritzelt ist eine kurze Notiz, unterzeichnet von Hammertoe. Sie ist an Roggendol gerichtet und besagt nur, dass sie Hammertoe nach Uldaman bringen und dass Hilfe benötigt wird. Die Kunde, die Ausgrabungsleiter Roggendol überbracht werden soll, lautet, dass Hammertoe Grez lebt."}},faq={{q="Was steht auf der zerknitterten Karte geschrieben?",a="Eine Notiz in Kreide, gerichtet an Roggendol und unterzeichnet von Hammertoe. Sie besagt, dass sie Hammertoe nach Uldaman bringen, und bittet um Hilfe.",al={"was steht auf der notiz","kreidebotschaft auf karte","text auf zerknitterter karte"}},{q="Wer ist Ausgrabungsleiter Roggendol?",a="Derjenige, für den die Notiz bestimmt ist. Ihr sollt Ausgrabungsleiter Roggendol aufsuchen und ihm mitteilen, dass Hammertoe Grez lebt.",al={"wer ist roggendol","wohin zerknitterte karte bringen"}},{q="Wohin wird Hammertoe Grez der Nachricht zufolge gebracht?",a="Nach Uldaman.",al={"wohin wird hammertoe gebracht","wohin wird grez gebracht"}}},fp="14,206,14.259.0,36.122.0,25.108.0,57.11.0"}
P.entries["quest:723"] = {n="Ein Funken Hoffnung",s="Hammertoe Grez pflegt seine Wunden und schickt Euch mit dem Amulett zu Ausgrabungsleiter Roggendol ins Ödland. Roggendol weiß, wonach Hammertoe suchte und was der Shadowforge-Clan keinesfalls finden darf.",h="Hammertoe Grez pflegt seine Wunden und schickt Euch mit dem Amulett zu Ausgrabungsleiter Roggendol ins Ödland.",kw={"ein zeichen der hoffnung","ödland","hammertoe grez","hammertoes amulett","ursprung","ausgrabungsleiter roggendol","schattenkessel"},sec={{t="Ein Amulett für Roggendol",b="Hammertoe Grez umklammert seine Wunden, hält kurz inne, um sich zu fassen, und bittet Euch dann, Roggendol zu finden und ihm das Amulett zu übergeben. Hammertoe ist sich sicher, dass Roggendol wissen wird, was zu tun ist. Roggendol weiß, dass Hammertoe nach den Ursprüngen ihres Volkes suchte und dass Hammertoe außerdem den Shadowforge-Clan vereiteln wollte, der die Schriftrollen keinesfalls in die Hände bekommen darf."},{t="In Roggendols Händen",b="Als Roggendol Hammertoes Amulett erhält, sagt er, dass die Stimmung besser war, als Hammertoe noch für tot gehalten wurde, da die Gewissheit den Schmerz nur noch verschlimmert. Roggendol bezeichnet das Amulett als Hammertoes Lebenswerk und schwört, dass sein Tod nicht umsonst gewesen sein wird."}},faq={{q="Wer ist Ausgrabungsleiter Roggendol?",a="Ausgrabungsleiter Roggendol ist derjenige, zu dem Ihr Hammertoes Amulett im Ödland bringen sollt. Roggendol weiß, wonach Hammertoe suchte.",al={"ausgrabungsleiter roggendol","wer ist roggendol","wo ist roggendol"}},{q="Was versucht Hammertoe Grez aufzuhalten?",a="Hammertoe wollte den Shadowforge-Clan aufhalten, der die Schriftrollen keinesfalls in die Hände bekommen darf.",al={"hammertoes ziel","schriftrollen der schattenkessel","warum schattenkessel aufhalten"}},{q="Wonach suchte Hammertoe Grez?",a="Laut Hammertoe nach den Ursprüngen ihres Volkes.",al={"hammertoes urspruenge","wonach suchte hammertoe"}},{q="Zu welcher Questreihe gehört dieser Schritt?",a="Dies ist Teil der Reihe, die mit A Sign of Hope begann.",al={"reihe aussicht auf glauben","reihe ein zeichen der hoffnung"}}},fp="17,195,20.348.0,17.246.1,25.126.0,38.100.0,32.52.0,33.57.0"}
P.entries["quest:724"] = {n="Ein Funken Hoffnung",s="Ausgrabungsleiter Roggendol schickt Euch mit Hammertoes Amulett nach Eisenschmiede. Historiker Karnik und Hammertoe arbeiteten zusammen, um die verlorenen Artefakte von Uldaman zu finden, und Roggendol vermutet, dass die Shadowforge herausgefunden haben, dass die beiden mehr wussten, als sie vorgaben.",h="Ausgrabungsleiter Roggendol schickt Euch mit Hammertoes Amulett nach Eisenschmiede.",kw={"ödland","hammertoe","hammertoes amulett","historiker karnik","eisenschmiede","prospect of faith","ausgrabungsleiter roggendol","shadowforge","uldaman"},sec={{t="Eine Nachricht für Eisenschmiede",b="Roggendol überlegt, wer wissen könnte, was als Nächstes zu tun ist, und entscheidet sich für Historiker Karnik, der sich in Eisenschmiede befindet. Ihr sollt Karnik erzählen, was mit Hammertoe geschehen ist, und das Amulett in die Hände des Historikers übergeben. Karnik wird Euch dann mitteilen, was von da an getan werden muss."},{t="Karniks Begrüßung",b="Karnik begrüßt Euch als gewöhnlichen Reisenden, der um seine Zeit bittet, und hat keine übrig, bis das Amulett gezeigt wird. Dann nimmt Karnik die Angelegenheit ernst, verschiebt die Trauer um Hammertoe auf später und zeigt Euch, warum das Amulett so wertvoll ist, indem er Hammertoes Geist herbeiruft."}},faq={{q="Wer startet diese Quest?",a="Ausgrabungsleiter Roggendol im Ödland schickt Euch mit Hammertoes Amulett weiter nach Eisenschmiede.",al={"wer vergibt prospect of faith","prospect of faith questgeber","wo prospect of faith beginnen"}},{q="Wo befindet sich Historiker Karnik?",a="Historiker Karnik befindet sich in Eisenschmiede.",al={"wo ist karnik","historiker karnik aufenthaltsort","karnik eisenschmiede"}},{q="Warum wurde Historiker Karnik ausgewählt?",a="Karnik und Hammertoe arbeiteten zusammen, um die verlorenen Artefakte von Uldaman zu finden, daher vertraut Roggendol darauf, dass Karnik weiß, was zu tun ist.",al={"warum das amulett zu karnik schicken","karnik verbindung"}},{q="Was folgt nach dieser Quest?",a="Karniks Teil der Geschichte wird mit Passing Word of a Threat fortgesetzt.",al={"folgequest nach prospect of faith","was folgt auf prospect of faith"}}},fp="17,239,23.251.0,16.273.1,22.84.0,34.33.0,32.125.0,28.68.0"}
P.entries["quest:725"] = {n="Kunde über die Bedrohung breitet sich aus",s="Historiker Karnik gibt Euch eine versiegelte Nachricht für Berater Belgrum. Ihr sollt Belgrum berichten, was Ihr mitangesehen habt, und fragen, wie Belgrum weiter vorgehen möchte, während Karnik sich an Hammertoes Geist bezüglich der Shadowforge im Ödland wendet.",h="Historiker Karnik gibt Euch eine versiegelte Nachricht für Berater Belgrum.",kw={"berater belgrum","ödland","hammertoe","historiker karnik","eisenschmiede","passing word of a threat","shadowforge"},sec={{t="Nachricht für Berater Belgrum",b="Karnik möchte, dass Ihr Berater Belgrum rasch ausfindig macht, berichtet, was Ihr gesehen habt, und fragt, wie Belgrum weiter vorgehen möchte. Die Nachricht erklärt Näheres. In der Zwischenzeit wird Karnik mit Hammertoes Geist sprechen, in der Hoffnung, dass Hammertoe etwas weiß, das den Machenschaften der Shadowforge im Ödland ein Ende setzen könnte, und kann nur darum beten, dass dem so ist."}},faq={{q="Wer schickt Euch zu Berater Belgrum?",a="Historiker Karnik überreicht Euch eine versiegelte Nachricht und bittet Euch, Berater Belgrum so schnell wie möglich aufzusuchen.",al={"wer startet passing word of a threat","wer vergibt passing word of a threat","karnik quest"}},{q="Was möchte Karnik von Berater Belgrum?",a="Karnik möchte, dass Belgrum berichtet wird, was Ihr mitangesehen habt, und er gefragt wird, wie Belgrum weiter vorgehen möchte. Die Nachricht erklärt Näheres.",al={"warum belgrum aufsuchen","zweck von belgrums brief","warum den brief senden"}},{q="Was macht Historiker Karnik, während Ihr die Nachricht überbringt?",a="Karnik nimmt sich die Zeit, mit Hammertoes Geist zu sprechen, in der Hoffnung, etwas zu erfahren, das dabei hilft, die Shadowforge im Ödland aufzuhalten.",al={"was macht karnik","karniks plan","historiker karnik ödland"}},{q="Welche Quest kommt vor Passing Word of a Threat?",a="Sie folgt auf Prospect of Faith, den Schritt, bei dem Ihr Hammertoes Amulett zu Karnik in Eisenschmiede bringt.",al={"passing word voraussetzung","passing word of a threat vorherige quest","vorherige quest"}}},fp="24,227,24.321.0,33.97.0,43.113.0,58.130.0,49.100.0"}
P.entries["quest:726"] = {n="Kunde über die Bedrohung breitet sich aus",s="Berater Belgrum hat Historiker Karniks Notiz gelesen und schickt Euch mit einer Botschaft im Namen des Königs zu Karnik zurück: Handelt nach dem, was bekannt ist, rasch und entschlossen, und setzt dem Treiben der Schattenschmiede im Ödland ein Ende.",h="Berater Belgrum hat Historiker Karniks Notiz gelesen und schickt Euch mit einer Botschaft im Namen des Königs...",kw={"festung angor","ödland","belgrum","karnik","schattenschmiede","uldaman"},sec={{t="Belgrums Antwort",b="Belgrum liest die Notiz mit geweiteten Augen bis zum Ende und bezeichnet die Kunde als unheilvoll. Ihr sollt zu Karnik zurückkehren und ihm im Namen des Königs ausrichten, dass unverzüglich und entschlossen nach den vorliegenden Erkenntnissen gehandelt werden muss. Die Aktivitäten der Schattenschmiede im Ödland müssen gestoppt werden."},{t="Karniks Erwiderung",b="Karnik begreift die Dringlichkeit als die des Königs selbst und hält einen Plan bereit: Die Schattenschmiede in Uldaman kann durch einen Schlag gegen die Festung Angor gebremst werden, von wo aus sie ihre Operationen leitet."}},faq={{q="Wer schickt Euch zu Karnik zurück?",a="Berater Belgrum, nachdem er Karniks Notiz gelesen hat. Ihr überbringt eine Botschaft im Namen des Königs, rasch und entschlossen zu handeln.",al={"wer den befehl erteilt","belgrums befehle","königliche autorität ödland"}},{q="Was will Belgrum bezüglich der Schattenschmiede unternommen sehen?",a="Belgrum möchte, dass Karnik rasch und entschlossen handelt und dem Treiben der Schattenschmiede im Ödland ein Ende setzt.",al={"was belgrum will","befehl bezüglich schattenschmiede im ödland"}},{q="Was geschah davor?",a="Ihr habt Karniks versiegelte Notiz im früheren Passing Word of a Threat zu Berater Belgrum gebracht, was auf die Schritte von Prospect of Faith folgte.",al={"vorheriger schritt","quest vor passing word of a threat","vorgeschichte ödland"}}},fp="24,221,16.268.0,14.177.1,29.120.0,50.116.0,22.136.0"}
P.entries["quest:727"] = {n="Auf nach Ironforge zu 'Yagyins Zusammenstellung'",s="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen nach Eisenschmiede. In einem Laden in der Forlorn Cavern soll Gerrig Knochengriff Euch für einen der Leute halten, vor denen Theldurin floh, und Ihr sollt Gerrig nach Yagyins Zusammenstellung fragen.",h="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen nach Eisenschmiede.",kw={"ödland","forlorn cavern","gerrig knochengriff","eisenschmiede","siegelzeichen des hammers","theldurin der verirrte","yagyins zusammenstellung"},sec={{t="Ein vor langer Zeit geschriebenes Buch",b="Die Tafel verrät Theldurin viel, aber bei Weitem nicht genug. Yagyin verfasste vor langer Zeit eine Zusammenstellung, und die Leute, vor denen Theldurin floh, bewahren an vielen Orten Abschriften auf, die von ihren Gelehrtesten studiert werden. Theldurin glaubt, dass sie gewaltiges Wissen birgt, das Schutz bieten kann, und möchte, dass sie zurückgebracht wird."},{t="Der Laden in der Forlorn Cavern",b="Gerrig Knochengriff betreibt einen Laden in der Forlorn Cavern von Eisenschmiede. Theldurin gibt Euch das Siegelzeichen des Hammers, um es Gerrig zu zeigen, damit man Euch für einen der ihren hält, und Ihr sollt nach Yagyins Zusammenstellung fragen."},{t="Gerrigs Begrüßung",b="Gerrig warnt Euch, vorsichtig zu sein, was Ihr im Laden berührt, denn Wissen kann tödlich sein. Wenn das Siegelzeichen gezeigt wird, begrüßt Gerrig Euch als Bruder oder Schwester und preist jene, die in der Tiefe weilen."}},faq={{q="Warum will Theldurin Yagyins Zusammenstellung?",a="Die Tafel verrät Theldurin viel, aber nicht genug. Die Zusammenstellung, die Yagyin vor langer Zeit verfasste, birgt gewaltiges Wissen, das Schutz bieten kann, und Theldurin möchte, dass sie zurückgebracht wird.",al={"warum yagyins zusammenstellung gebraucht wird","was ist yagyins zusammenstellung","zweck von yagyins zusammenstellung"}},{q="Wo ist Gerrig Knochengriff?",a="Gerrig Knochengriff befindet sich in einem Laden in Eisenschmiedes Forlorn Cavern.",al={"wo ist gerrig knochengriff","gerrig knochengriff standort","wer ist gerrig"}},{q="Wofür wird das Siegelzeichen des Hammers verwendet?",a="Theldurin gibt es Euch, damit Ihr es Gerrig Knochengriff zeigt, sodass Gerrig Euch für einen der Leute hält, vor denen Theldurin floh.",al={"was bewirkt das siegelzeichen","siegelzeichen des hammers nutzen","warum das siegelzeichen nutzen"}},{q="Wo passt dies in die Reihe?",a="Es folgt auf Solution to Doom, bei Theldurin dem Verirrten, und wird im nächsten Schritt der Reihe fortgeführt.",al={"was kommt vor to ironforge for yagyins digest","reihenfolge der questreihe yagyin"}}},fp="32,204,23.283.0,30.207.0,17.189.1,40.176.0,25.65.0,41.114.0,33.103.0"}
P.entries["quest:728"] = {n="Auf nach Undercity zu 'Yagyins Zusammenstellung'",s="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen in die Unterstadt von Lordaeron. Bewahrer Bel'dugur soll Euch für einen der Leute halten, vor denen Theldurin floh, und Ihr sollt den Bewahrer nach Yagyins Zusammenstellung fragen.",h="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen in die Unterstadt von Lordaeron.",kw={"ödland","bel'dugur","zusammenstellung","hammer","siegelzeichen","theldurin","unterstadt","yagyin"},sec={{t="Ein vor langer Zeit geschriebenes Buch",b="Die Tafel verrät Theldurin viel, aber bei Weitem nicht genug. Yagyin verfasste vor Urzeiten eine Zusammenstellung, und die Leute, vor denen Theldurin floh, bewahren an vielen Orten Abschriften davon auf, wobei ihre Gelehrtesten sie studieren. Theldurin glaubt, dass sie immenses Wissen birgt, das sie beschützen kann, und möchte, dass sie zurückgebracht wird."},{t="Der Bewahrer in der Unterstadt",b="Bewahrer Bel'dugur befindet sich in der Unterstadt von Lordaeron. Theldurin gibt Euch das Siegelzeichen des Hammers, um es dem Bewahrer zu zeigen, damit man Euch für einen der ihren hält, und Ihr sollt nach der Zusammenstellung fragen."},{t="Ein Wort der Warnung",b="Bel'dugur begrüßt Euch als eifrigen Sucher der Sammlung und warnt, dass Wissen den Starken Macht verleiht, die Schwachen jedoch in den Wahnsinn treibt. Sobald das Siegelzeichen vorgezeigt wird, mahnt Bel'dugur Euch, mit solchen Zeichen diskret umzugehen. Einige glauben nicht an die Rechtschaffenheit ihres Gelöbnisses, und andere würden sie scheitern sehen wollen, wenn sie von ihnen wüssten. Diejenigen, die das Gelöbnis teilen, müssen stets vorsichtig, wachsam und geduldig sein."}},faq={{q="Wer schickt Euch in die Unterstadt?",a="Theldurin der Verirrte schickt Euch mit dem Siegelzeichen des Hammers los, um Bewahrer Bel'dugur zu finden.",al={"wer startet diese quest","wer vergibt ab in die unterstadt für yagyins zusammenstellung","questgeber"}},{q="Wozu dient das Siegelzeichen des Hammers?",a="Theldurin gibt es Euch, damit Ihr es Bewahrer Bel'dugur zeigt, sodass der Bewahrer Euch für einen der Leute hält, vor denen Theldurin floh.",al={"siegelzeichen des hammers nutzen","warum brauche ich das siegelzeichen","was bewirkt das siegelzeichen"}},{q="Was ist Yagyins Zusammenstellung?",a="Es ist ein Buch, das Yagyin vor Urzeiten schrieb. Theldurin sagt, dass es immenses Wissen birgt und von den Gelehrtesten der Leute studiert wird, vor denen Theldurin floh.",al={"was ist yagyins zusammenstellung","wer ist yagyin","yagyin buch"}},{q="Wo befindet sich Bewahrer Bel'dugur?",a="Bewahrer Bel'dugur weilt in der Unterstadt von Lordaeron, wo Ihr den Bewahrer findet.",al={"bewahrer bel'dugur aufenthaltsort","wo ist bewahrer bel'dugur zu finden","beldugur unterstadt"}},{q="Was geschah davor?",a="Es folgt auf Solution to Doom.",al={"vorherige quest","was kommt davor","verbindung zu lösung des unheils"}}},fp="36,193,23.279.0,27.192.0,17.394.1,31.85.0,36.119.0,24.143.0,26.80.0,22.28.0"}
P.entries["quest:729"] = {n="Der geistesabwesende Ausgrabungsleiter",s="Archäologin Hollee ist nach Auberdine geflohen, nachdem eine Ausgrabungsstätte an der südlichen Dunkelküste von feindseligen Steingolems überrannt wurde. In schrecklicher Sorge um ihren älteren Kollegen bittet sie Reisende, nach Süden zu eilen und Ausgrabungsleiter Wirrbart zu retten – einen geschätzten zwergischen Gelehrten, der notorisch blind für tödliche Gefahren ist, sobald er in seine Forschungen vertieft ist.",h="Archäologin Hollee ist nach Auberdine geflohen, nachdem eine Ausgrabungsstätte an der südlichen Dunkelküste...",kw={"auberdine","dunkelküste","forscherliga","fossil","golems","greywhisker","hollee","remtravel"},ang={["faction:Alliance"]="Diese Mission unterstreicht die kooperative Präsenz von Forschern aus Eisenschmiede, die versuchen, die unbekannten, uralten Lande ihrer Verbündeten, der Nachtelfen, in Kalimdor zu erforschen.",["race:Dwarf"]="Für Zwerge verkörpert Remtravel die obsessive Neugier und den Tunnelblick der Forscherliga, bereit, für ein unkatalogisiertes Fossil Kopf und Kragen zu riskieren."},sec={{t="Eine gefährliche Grabung",b="Auf Befehl von Meister Greywhisker von der Forscherliga über das Meer entsandt, war Archäologin Hollee begeistert, bei Ausgrabungsleiter Wirrbart in die Lehre zu gehen. In den akademischen Kreisen von Eisenschmiede für seine bahnbrechenden Entdeckungen berühmt, wurde Remtravel ausgesandt, um uralte Ruinen entlang der ungezähmten Küste von Dunkelküste zu untersuchen. Doch während einer Ausgrabung an den scheinbaren Überresten einer uralten, großen Zivilisation brachen gewalttätige Steingolems aus der Erde hervor und überrannten die Grabungsstätte rasch."},{t="Blind für das Verderben",b="Während Hollee in Panik floh, um im Nachtelfen-Hafen von Auberdine Hilfe zu suchen, zuckte Remtravel kaum mit der Wimper. Völlig eingenommen von den Relikten, die er freigelegt hatte, verharrte der betagte Ausgrabungsleiter knietief im Schutt, vollkommen unbeeindruckt von den schwerfälligen Konstrukten, die sein Lager umringten. Jeder, der ihn südlich von Auberdine erreicht, findet ihn nicht etwa vor Angst kauernd vor, sondern über fehlende Steinbürsten und verlegte Fossilien murrend."}},faq={{q="Wer ist Ausgrabungsleiter Wirrbart?",a="Ausgrabungsleiter Wirrbart ist ein gefeierter zwergischer Forscher, der der Forscherliga von Eisenschmiede angehört. Berühmt in den zwergischen Akademien für seine monumentalen Entdeckungen, ist er ebenso berüchtigt für einen extremen Mangel an Situationsbewusstsein, wann immer wertvolle Relikte in der Nähe sind.",al={"remtravel","ausgrabungsleiter remtravel lore","wer ist der ausgrabungsleiter"}},{q="Warum ist Archäologin Hollee in Auberdine?",a="Hollee wurde Remtravel von Meister Greywhisker als Assistentin zugewiesen. Als gefährliche Golems an ihrer Grabungsstätte aus dem Boden brachen, floh sie nach Norden nach Auberdine, um Verstärkung für eine Rettungsaktion zu suchen.",al={"archäologin hollee","hollee auberdine","warum floh hollee"}},{q="Was gruben die Zwerge an der Dunkelküste aus?",a="Die Expedition hatte Hinweise auf eine uralte, hochentwickelte Gesellschaft entdeckt, die unter Dunkelküste begraben lag. Remtravel entdeckte ein mysteriöses Fossil und verschiedene Steinartefakte, bevor die Stätte von unterirdischen Konstrukten überrannt wurde.",al={"was grub remtravel aus","dunkelküste grabungsstätte","remtravel fossil"}},{q="Wo ist Ausgrabungsleiter Wirrbart zu finden?",a="Remtravel befindet sich im südlichen Dunkelküste, inmitten alter Ruinen südlich von Auberdine, umgeben von gefährlichen Golems, während er wie besessen nach seiner Steinbürste und seinem Fossil sucht.",al={"wo ist remtravel","remtravel aufenthaltsort","ausgrabungsleiter remtravel finden"}},{q="Wer schickte diese Expedition nach Dunkelküste?",a="Die Expedition wurde von der Forscherliga in Eisenschmiede organisiert und direkt von Meister Greywhisker angeordnet, der Hollee damit beauftragte, Remtravel bei der Katalogisierung der uralten Wunder der Region zur Hand zu gehen.",al={"wer schickte hollee","meister greywhisker","forscherliga dunkelküste"}},{q="Schwebt Remtravel in tatsächlicher Gefahr?",a="Ja. Feindselige Golems streifen direkt um ihn herum durch die Ruinen. Remtravel ist sich der drohenden Gefahr nicht bewusst, konzentriert sich ganz auf die Katalogisierung seiner Funde und wundert sich, wohin seine Werkzeuge und seine Assistentin verschwunden sind.",al={"ist remtravel tot","remtravel am leben","remtravel helfen"}}},fx={["90475777"]={q="Warum möchte Archäologin Hollee, dass dies erledigt wird?",a="Hollee war begeistert, unter Ausgrabungsleiter Wirrbart zu lernen, einem berühmten Forscher der Forscherliga von Eisenschmiede. Doch als feindselige Golems aus der Ausgrabungsstätte brachen, ließ ihn seine tiefe Zerstreutheit die Gefahr völlig vergessen. Hollee floh nach Auberdine, um Verstärkung zu holen, in der Angst, dass ihr Mentor getötet wird, wenn ihn niemand aus den Ruinen holt.",al={"warum braucht hollee hilfe","beweggrund hollee","warum nach wirrbart suchen"}},["1b9bcac6"]={q="Warum bittet Hollee Euch, nach Wirrbart zu sehen, anstatt selbst zu gehen?",a="Hollee entkam der Ausgrabungsstätte nur knapp mit dem Leben, als sich die Steingolems erhoben. Verängstigt und ohne die kampferprobten Fähigkeiten, sich allein durch die feindseligen Konstrukte zu kämpfen, muss sie sicher in Auberdine bleiben und sich auf fähige, vorbeikommende Abenteurer verlassen, die sich zurück in das Getümmel wagen und nach ihrem Mentor sehen.",al={"warum ich hollee","warum geht hollee nicht zurück","warum hilft auberdine nicht"}}},fp="28,330,14.516.0,17.417.0,28.273.0,41.210.0,46.222.0,40.180.0,38.198.0,30.214.0"}
P.entries["quest:730"] = {n="Ärger in Dunkelküste?",s="Ärger in Dunkelküste? ist eine einleitende Allianz-Quest, die von Chefarchäologe Grauflaum in Darnassus angeboten wird. Besorgt über das wochenlange Schweigen eines Ausgrabungsteams, das über das Meer entsandt wurde, bittet er Reisende, nach Auberdine zu reisen, um dessen Verschwinden zu untersuchen. Sie schlägt eine Brücke zwischen der gelehrten Zwergenexpedition und der wilden, schattigen Küste von Dunkelküste.",h="Ärger in Dunkelküste?",kw={"archäologe","auberdine","dunkelküste","darnassus","forscherliga","greywhisker","hollee","ärger in dunkelküste"},ang={["faction:Alliance"]="Diese Aufgabe zeigt die wachsende Zusammenarbeit zwischen Eisenschmiede und Darnassus und verbindet Reisende zwischen Teldrassil und dem Festland von Kalimdor.",["race:Dwarf"]="Für Zwerge knüpft diese Quest an die Tradition der Forscherliga an, das Wissen der Titanen und die uralte Geschichte auf neuen Kontinenten zu ergründen.",["race:NightElf"]="Nachtelfen blicken auf die Ankunft spitzhackenschwingender Zwergenausgräber in den Ruinen ihrer angestammten Küste womöglich mit vorsichtiger Erheiterung oder stiller Besorgnis."},sec={{t="Eine verstummte Expedition",b="In der prächtigen Nachtelfenhauptstadt Darnassus gehen Zwergenforscher aus Eisenschmiede den uralten Geheimnissen von Kalimdor nach. Chefarchäologe Grauflaum schickte eine Ausgrabungsgruppe über das Wasser nach Dunkelküste, um antike Artefakte zu bergen. Als Wochen vergehen, ohne dass eine einzige Botschaft oder ein Fortschrittsbericht eintrifft, wächst Greywhiskers Sorge, dass seine Feldmannschaft auf Gefahren gestoßen ist, für die sie allein schlecht gerüstet war."},{t="Ausgegrabene Bedrohungen",b="Greywhisker beklagt, dass viele in der Allianz die Zwergenarchäologie lediglich als exzentrisches Hobby abtun. Funde in Khaz Modan haben seine Kollegen jedoch davon überzeugt, dass eine uralte, furchterregende Macht Azeroth von Lordaeron bis Kalimdor bedroht. In den Ruinen von Dunkelküste zu graben ist nicht bloß ein akademisches Unterfangen – es ist der Versuch, historische Kataklysmen und die tiefsitzenden Bedrohungen zu verstehen, die unter uralter Erde begraben liegen."},{t="Kontakt in Auberdine",b="Nachdem sie von Teldrassil über die Meerenge zum Küstenzufluchtsort Auberdine gesegelt sind, finden Reisende Archäologin Hollee, die in der Stadt wartet. Erleichtert darüber, dass der Chefarchäologe Verstärkung geschickt hat, enthüllt Hollee, dass sich die Expedition tatsächlich in einer Notlage befindet, da sie weiter die Küste hinunter bei der Suche nach uralten Relikten in Schwierigkeiten geraten ist."}},faq={{q="Wer startet die Quest Ärger in Dunkelküste?",a="Chefarchäologe Grauflaum bietet die Quest in der Nachtelfenhauptstadt Darnassus an und sucht nach mutigen Abenteurern, die bereit sind, nach seiner verschollenen Mannschaft zu sehen.",al={"wer gibt ärger in dunkelküste","questgeber ärger in dunkelküste","wo bekommt man ärger in dunkelküste"}},{q="Wohin muss ich reisen, um diese Quest abzuschließen?",a="Ihr müsst von Darnassus über das Meer in die Hafenstadt Auberdine in Dunkelküste reisen, wo Ihr Archäologin Hollee antrefft.",al={"wohin muss ich gehen","abgabeort","bei wem abgeben"}},{q="Warum sind Zwergenarchäologen in Darnassus und Dunkelküste?",a="Nach jüngsten Entdeckungen in Khaz Modan begannen Zwergenforscher damit, antike Stätten in ganz Kalimdor zu untersuchen, um Hinweise auf uralte Mächte aufzudecken, die Azeroth bedrohen.",al={"warum sind zwerge in darnassus","zwerge in dunkelküste","zwergenarchäologie kalimdor"}},{q="Was geschieht, nachdem man Archäologin Hollee gefunden hat?",a="Das Gespräch mit Archäologin Hollee in Auberdine führt direkt zu 'The Absent Minded Prospector', worin Ihr darum gebeten werdet, in die Wildnis von Dunkelküste vorzudringen, um Ausgrabungsleiter Wirrbart ausfindig zu machen.",al={"wie geht es weiter","folgequest","nächste quest"}},{q="Warum hat sich die Ausgrabungsmannschaft nicht gemeldet?",a="Das Team stieß bei den Arbeiten vor Ort in Dunkelküste auf unerwartete Gefahren und Rückschläge, wodurch einzelne Mitglieder voneinander getrennt und von jeglicher Kommunikation mit Darnassus abgeschnitten wurden.",al={"was geschah bei der ausgrabung","warum sind sie verschwunden","mannschaft vermisst"}},{q="Auf welche drohende Gefahr bezieht sich Greywhisker?",a="Greywhisker verweist auf in Khaz Modan freigelegte Funde, die auf eine uralte, allgegenwärtige Gefahr hindeuten, die tief in den historischen Ruinen von Azeroth schlummert.",al={"welche uralte bedrohung","greywhisker warnung","khaz modan bedrohung"}}},fx={["0c1ca2fe"]={q="Warum möchte Chefarchäologe Grauflaum, dass dies erledigt wird?",a="Chefarchäologe Grauflaum hat seit Wochen nichts von seinem Ausgrabungsteam in Dunkelküste gehört. Nach bedrohlichen Entdeckungen in Khaz Modan, die eine große und uralte Macht enthüllen, die ganz Azeroth bedroht, kann er es sich nicht leisten, den Kontakt zu seinen Forschern zu verlieren, insbesondere wenn deren Arbeit entscheidend ist, um diese drohenden Gefahren aufzudecken.",al={"beweggrund grauflaum","warum nach dunkelküste schicken","warum ausgrabungsteam finden"}}},fp="21,355,19.426.0,16.439.0,20.335.1,42.153.0,45.134.0,58.172.0,48.181.0,45.167.0,48.149.0"}
P.entries["quest:731"] = {n="Der geistesabwesende Ausgrabungsleiter",s="Tief in den südlichen Ruinen der Dunkelküste weigert sich Ausgrabungsleiter Wirrbart, seine Grabungsstätte ohne einen Fund aufzugeben, den er der Forscherliga vorweisen kann. Trotz seiner schweren Vergesslichkeit und eines Befalls feindseliger Troggs besteht er darauf, ein geheimnisvolles Fossil freizulegen, bevor er sich zurückzieht. Sicherzustellen, dass der zwergische Forscher seine sprunghafte Suche überlebt, sorgt dafür, dass die Nachricht von seiner Unversehrtheit seine Assistentin im heimatlichen Auberdine erreicht.",h="Tief in den südlichen Ruinen der Dunkelküste weigert sich Ausgrabungsleiter Wirrbart, seine Grabungsstätte...",kw={"auberdine","dunkelküste","eskorte","ausgrabung","forscherliga","fossil","hollee","wirrbart","troggs"},ang={["faction:Alliance"]="Wirrbart und seine Funde in Sicherheit zu bringen, wahrt die entscheidende diplomatische und wissenschaftliche Zusammenarbeit zwischen der zwergischen Forscherliga und den Nachtelfen von Teldrassil.",["race:Dwarf"]="Für Zwerge verkörpert Wirrbart sowohl die unermüdliche Leidenschaft als auch die verhängnisvolle Dickköpfigkeit der Forscherliga und zeigt, wie die Hingabe an das uralte Titanenwissen einen Gelehrten für unmittelbare Gefahren blind machen kann.",["race:NightElf"]="Die Kaldorei blicken im Allgemeinen mit Argwohn auf zwergische Ausgrabungen an der Dunkelküste; dass Wirrbart eine Horde gewalttätiger Troggs zutage gefördert hat, bestätigt ihre Befürchtungen, was das Graben zu tief in heiligem Boden angeht."},sec={{t="Eine gefährliche Ausgrabung",b="Wirrbarts Grabung liegt weit im Süden der Dunkelküste, eingebettet in uralte Ruinen, die eigentlich vergessene Geheimnisse bergen sollten. Stattdessen stießen die zwergischen Ausgräber auf Nester wilder Troggs, die die Arbeiter vertrieben und das Lager belagerten. Während die meisten sofort nach Auberdine fliehen würden, versteifte sich Ausgrabungsleiter Wirrbart darauf, seine Funde zu retten. Da er sich weigert, mit leeren Händen abzureisen, begibt er sich geradewegs in die Höhle des Löwen, um ein schwer auffindbares Fossil zu bergen, um die Kosten der Expedition vor der Forscherliga zu rechtfertigen."},{t="Verworrene Erinnerungen und Trogg-Hinterhalte",b="Wirrbart zu beschützen erweist sich als ebenso frustrierend wie gefährlich. Seine zerstreute Art lässt ihn im Kreis über die Ausgrabungsstätte irren, wobei er Pinsel mit Fossilien verwechselt und an Gerüsten sowie verlassenen Zelten vorbeistolpert. Jeder Halt zieht die Aufmerksamkeit aggressiver Troggs auf sich, die in den schattigen Winkeln des Steinbruchs lauern. Erst nachdem die Eskorte Welle um Welle unterirdischer Unholde beseitigt hat, erinnert sich der Gelehrte schließlich daran, wo sich sein Fundstück befindet: Er hat das Fossil bereits Hollee gegeben, und er kehrt vergnügt an die Arbeit zurück."}},faq={{q="Wer ist Ausgrabungsleiter Wirrbart?",a="Ausgrabungsleiter Wirrbart ist ein leitender Feldforscher der zwergischen Forscherliga. An der Dunkelküste stationiert, wurde er mit der Ausgrabung uralter Ruinen entlang der Küste beauftragt, obgleich seine extreme Zerstreutheit ihn regelmäßig in lebensbedrohliche Situationen bringt.",al={"wirrbart","wer ist der ausgrabungsleiter","zerstreuter ausgrabungsleiter typ"}},{q="Warum ist Wirrbart noch immer an der Grabungsstätte?",a="Obwohl die Grabung von Troggs überrannt wurde, weigert sich Wirrbart, ohne greifbaren Beweis für seine Arbeit nach Darnassus zurückzukehren. Er besteht darauf, ein geheimnisvolles Fossil zu bergen, um es der Forscherliga vorzulegen, bevor er überhaupt in Erwägung zieht, das Lager aufzugeben.",al={"warum an der grabungsstätte bleiben","warum ist wirrbart dort","warum ist er nicht geflohen"}},{q="Woher kamen die Troggs?",a="Wie bei vielen zwergischen Ausgrabungen stieß Wirrbarts Team tief in die Erde vor und öffnete unwissentlich unterirdische Hohlräume, die von Troggs bewohnt wurden. Die primitiven Kreaturen drängten scharenweise an die Oberfläche und überrannten gewaltsam Maschinen, Zelte und Arbeiter.",al={"warum gibt es troggs an der dunkelküste","dunkelküste troggs","grabungsstätte troggs"}},{q="Wer ist Archäologin Hollee?",a="Archäologin Hollee ist Wirrbarts Kollegin und Assistentin mit Sitz im Küstenort Auberdine. Bestürzt über das lange Ausbleiben ihres Mentors und wohlvertraut mit seinen vergesslichen Angewohnheiten rekrutiert sie Reisende, um ihn aufzuspüren und seine sichere Rückkehr zu gewährleisten.",al={"hollee","archäologin hollee","wirrbarts assistentin"}},{q="Was geschieht nach dem Finden des Fossils?",a="Nachdem Ihr Wirrbart bei der Durchsuchung der Grabungsstätte geholfen habt, berichtet Archäologin Hollee in Auberdine von seiner Unversehrtheit.",al={"questfortsetzung","was als nächstes","nach wirrbarts eskortierung"}}},fx={["6ea255c4"]={q="Warum möchte Ausgrabungsleiter Wirrbart das Fossil finden?",a="Wirrbart steht unter dem Druck des Kapitels der Forscherliga in Darnassus, zu beweisen, dass er tatsächlich Fortschritte bei der Ausgrabungsstätte gemacht hat. Obwohl er schrecklich verwirrt und geistesabwesend ist, weiß er, dass er greifbare Ergebnisse – insbesondere das geheimnisvolle Fossil und schriftliche Funde – vorzeigen muss, um seine Expedition zu rechtfertigen und seine Vorgesetzten zufrieden zu stellen.",al={"beweggrund wirrbart","warum nach fossil suchen","warum fossil wirrbart finden"}},["4634f683"]={q="Warum braucht Wirrbart Eure Hilfe bei der Suche in der Ausgrabung?",a="Die Ausgrabungsstätte wurde von feindseligen Troggs überrannt, und Wirrbart ist ein zerstreuter Forscher, kein erfahrener Krieger. Er ist völlig darauf fixiert, seine verlorenen Artefakte und Notizen zu bergen, was ihn völlig anfällig für Hinterhalte macht, während er ohne jemanden, der bewaffnet ist und ihm den Rücken freihält, durch die Ausgrabungsstätte irrt.",al={"warum braucht wirrbart eine eskortierung","warum braucht wirrbart schutz","warum nicht alleine suchen wirrbart"}}},fp="28,403,21.528.0,35.518.1,28.259.0,39.243.0,31.239.0,28.256.0,38.98.1"}
P.entries["quest:732"] = {n="Erdbeben",s="Garek hat von Sigrun erfahren, wie sehr Ihr geholfen habt, und bittet seinerseits um Eure Hilfe. Gareks Meister, Krasus von den Kirin Tor, schickte Garek, um aufzuhalten, was auch immer sich in der Lethlorklamm zusammenbraut, und zuerst muss ein gestohlenes Zeichen der Erde gefunden werden.",h="Garek hat von Sigrun erfahren, wie sehr Ihr geholfen habt, und bittet seinerseits um Eure Hilfe.",kw={"festung angor","camp boff","dunkeleisenzwerge","deathwing","garek","kirin tor","krasus","die lethlorklamm","zeichen der erde"},sec={{t="Eine vertrauliche Angelegenheit",b="Garek wurde von Krasus von den Kirin Tor, Gareks Meister, ins Ödland geschickt, um das Unheil aufzuhalten, das sich in der Lethlorklamm zusammenbraut. Der genaue Auftrag kann nicht mitgeteilt werden, nur dass er von großer Bedeutung ist. Eine Bande umherziehender Oger, die hin und wieder in der Nähe von Camp Boff gesichtet wird, hat das Zeichen der Erde an sich genommen, und Garek benötigt es. Bringt es zurück, und Ihr werdet mehr erfahren."},{t="Die wandernden Oger",b="Die Oger ziehen im Ödland von Lager zu Lager, und zunehmende Hitze sowie wirbelnde Winde erschweren es, ihrer Spur zu folgen. Garek hat gehört, dass sie manchmal Camp Boff durchqueren – ein guter Ort zum Suchen, solltet Ihr ihre Fährte verlieren."},{t="Garek erklärt",b="Wenn Ihr mit dem Zeichen zurückkehrt, erzählt Euch Garek, dass Dunkeleisenzwerge der Festung Angor es erschaffen haben, um Deathwings Zwillingsleutnants, die skrupellosen Blacklash und Hematus, zu binden."}},faq={{q="Für wen arbeitet Garek?",a="Gareks Meister ist Krasus von den Kirin Tor, der Garek ins Ödland schickte, um das sich in der Lethlorklamm zusammenbrauende Unheil aufzuhalten.",al={"wer schickte garek","garek meister","krasus ödland"}},{q="Was ist das Zeichen der Erde?",a="Wandernde Oger haben es gestohlen und Garek braucht es zurück. Garek wird mehr erzählen, sobald Ihr es bringt.",al={"zeichen der erde","was ist das zeichen der erde","zeichen der erde lore"}},{q="Wo sind die wandernden Oger zu finden?",a="Sie ziehen zwischen ihren Lagern quer durch das Ödland, und Garek hat gehört, dass sie manchmal Camp Boff durchqueren.",al={"wo sind die oger","oger camp boff","wo ist das zeichen der erde"}},{q="Warum hält Garek den Auftrag geheim?",a="Garek will nicht verraten, worum es sich bei dem Auftrag handelt oder welche Aufgaben er erfordert, nur dass er von entscheidender Bedeutung ist.",al={"warum geheim","garek geheimer auftrag"}}},fp="20,236,19.356.0,19.224.0,14.178.1,25.120.0,30.88.0,39.109.0,42.103.0"}
P.entries["quest:7321"] = {n="Milde Schildkrötensuppe",s="Milde Schildkrötensuppe ist eine kulinarische Aufgabe, die von Christoph Jeffkott in Tarrens Mühle angeboten wird. Der Koch der Verlassenen will die Vorstellung widerlegen, den Untoten fehle es an kulinarischem Talent, indem er eine herzhafte Brühe aus lokalem Schnappkieferfleisch zubereitet. Spieler müssen Süßwasserschildkröten an den Wasserläufen im Vorgebirge des Hügellands und an den Ufern des Lordameresee jagen, um sein geschätztes Rezept zu meistern.",h="Milde Schildkrötensuppe ist eine kulinarische Aufgabe, die von Christoph Jeffkott in Tarrens Mühle angeboten...",kw={"christoph jeffkott","kochkunst","vorgebirge des hügellands","der lordameresee","schnappkiefer","milde schildkrötensuppe","tarrens mühle","schildkrötenfleisch"},ang={["faction:Horde"]="Die Garnison in Tarrens Mühle zu unterstützen bedeutet mehr, als nur ihre Grenzen zu verteidigen; den Proviant und die Moral hochzuhalten, sichert den Stand der Horde im umkämpften Hillsbrad.",["profession:Cooking"]="Diese Aufgabe erlaubt es Köchen, die Milde Schildkrötensuppe zu meistern und die aggressiven Reptilien des Lordameresee und der Flüsse von Hillsbrad in eine stärkende Mahlzeit zu verwandeln.",["race:Undead"]="Christoph Jeffkott verkörpert eine heitere, handwerksorientierte Seite der Verlassenen und beharrt darauf, dass der Tod seine Leidenschaft fürs Kochen nicht getrübt hat."},sec={{t="Gastronomie der Verlassenen",b="Es wird weithin angenommen, dass die Verlassenen die Annehmlichkeiten des Lebens, einschließlich der Kunst des feinen Essens, völlig hinter sich gelassen haben. Christoph Jeffkott, stationiert in Tarrens Mühle, weist diese Annahme entschieden zurück. Er prahlt damit, dass seine reichhaltige, milde Schildkrötensuppe gut genug sei, um Seelen aus dem Jenseits zurückzulocken, und möchte beweisen, dass untote Hände selbst in einem von Pest und Krieg gezeichneten Land zu feiner, herzerwärmender Handwerkskunst fähig sind."},{t="Die Jagd nach den Schnappkiefern",b="Normalerweise sammelte Jeffcoat seine eigenen Zutaten an den Wasserläufen im Vorgebirge des Hügellands und am östlichen Ufer des Lordameresee im benachbarten Alterac. Doch seine Pflichten in Tarrens Mühle und das Vordringen der Streitkräfte der Allianz binden ihn fest. Er verlässt sich auf durchreisende Köche der Horde, um die Schnappkiefer zu jagen, ihr Fleisch zu erbeuten und es zurückzubringen, damit die Kochtradition fortbestehen kann."}},faq={{q="Warum kümmert sich ein Koch der Verlassenen darum, heiße Suppe zuzubereiten?",a="Obwohl die Verlassenen keine Nahrung im selben Maße wie lebende Sterbliche benötigen, sind Persönlichkeiten wie Christoph Jeffkott sehr stolz auf ihr Handwerk. Jeffcoat will das Vorurteil widerlegen, Untoten mangele es an feinem Geschick, und scherzt, seine Spezialbrühe sei gut genug, um Verstorbene wieder zum Leben zu erwecken.",al={"untote kochen","warum suppe kochen","essen untote nahrung"}},{q="Wo findet man Schildkrötenfleisch für dieses Rezept?",a="Schildkrötenfleisch wird von den aggressiven Schnappkiefern erbeutet, die an den Flüssen durch das Vorgebirge des Hügellands und Alterac sowie an den Ufern des Lordameresee heimisch sind.",al={"wo sind schildkröten","fundorte von schildkröten","fundorte von schnappkiefern"}},{q="Warum kann Christoph Jeffkott seine Zutaten nicht selbst sammeln?",a="Jeffcoat gibt an, durch seine Pflichten in Tarrens Mühle gebunden zu sein. Zudem äußert er Verärgerung über die nahen, vordringenden Streitkräfte der Allianz, die persönliche Jagdausflüge weitaus gefährlicher machen.",al={"warum geht christoph nicht","jeffcoat sitzt im dorf fest"}},{q="Ist Kochwissen erforderlich, um diese Quest anzunehmen?",a="Ja. Christoph Jeffkott teilt sein Handwerk und Rezept nur mit anderen Vertretern der Kochkunst, obgleich zu Beginn keine fortgeschrittene Meisterschaft erforderlich ist.",al={"brauche ich kochen","voraussetzung kochkunst"}},{q="Welche Bedeutung hat Tarrens Mühle für die Horde in Hillsbrad?",a="Tarrens Mühle dient als wichtigste Hochburg der Horde im Vorgebirge des Hügellands. Einst ein Menschendorf, fungiert es nun als befestigter Stützpunkt für die Verlassenen und ihre Verbündeten, der häufigen Zusammenstößen mit Süderstade und der regionalen Allianzpräsenz ausgesetzt ist.",al={"was ist tarrens mühle","hintergrund von tarrens mühle"}},{q="Gibt es die Schildkrötensuppe nur für die Horde?",a="Köche der Allianz können das Rezept von einheimischen menschlichen Köchen in Süderstade erwerben, die ebenfalls die hiesigen Schildkrötenbestände nutzen; Christoph Jeffkotts persönliche Quest und Perspektive bleiben jedoch der Horde vorbehalten.",al={"allianz-version","kann die allianz schildkrötensuppe bekommen"}}},fx={["7509a6d7"]={q="Wofür ist das Schildkrötenfleisch?",a="Christoph Jeffkott benötigt das Schildkrötenfleisch, um seine charakteristische beruhigende Schildkrötenbisque zu brauen. Auch wenn Untote vielleicht nicht die Kälte oder den Hunger wie die Lebenden spüren, ist Jeffkott sehr stolz auf sein kulinarisches Handwerk. Er behauptet, sein Geheimrezept sei so gut, dass die Menschen von den Toten zurückkehren würden, nur um eine heiße Schüssel zu genießen.",al={"verwendung schildkrötenfleisch","warum schildkrötenfleisch","wofür wird schildkrötenfleisch verwendet"}},["5469f6c5"]={q="Was sind die Schnappkiefer, die Ihr für diese Bisque jagt?",a="Schnappkiefer sind bösartige Süßwasserschildkröten mit hartem Panzer, die in den Gewässern von Lordaeron heimisch sind, besonders reichlich entlang der Ufer des Lordameresee und der örtlichen Flussufer. Obwohl sie wild und gefährlich für unvorsichtige Reisende sind, liefert ihr zähes Fleisch das entscheidende, reichhaltige Fleisch, das Christoph für seine Bisque benötigt.",al={"schnappkiefer hillsbrad","lordameresee schnappkiefer","wen jage ich"}}},fp="22,366,19.433.0,20.388.0,54.306.0,47.175.0,56.200.0,49.170.0,59.255.0,37.208.0"}
P.entries["quest:733"] = {n="Schnorrerei",s="Sigrun Ironhew benötigt Materialien zum Bau von Verteidigungsanlagen und anderen Notwendigkeiten für das Lager und hat bemerkt, dass die Oger in der Nähe reichlich Altmetall bei sich tragen. Sigrun möchte sieben Stücke davon.",h="Sigrun Ironhew benötigt Materialien zum Bau von Verteidigungsanlagen und anderen Notwendigkeiten für das...",kw={"ödland","die staubspeiergrotte","forscherliga","eisenschmiede","oger","altmetall","scrounging","sigrun ironhew"},sec={{t="Ein Lager mit Materialknappheit",b="Sigrun fällt es schwer, ohne Materialien für Verteidigungsanlagen und andere Notwendigkeiten auszukommen, und der Prospector macht sich Sorgen um den Zustand des kleinen Lagers. Sigrun möchte sich bald an die Arbeit machen und benötigt dafür Altmetall."},{t="Der Ogerschrott",b="Die Oger in der Gegend scheinen gut mit Altmetall versorgt zu sein, was Sigrun vermuten lässt, dass das Gerede über Belagerungsmaschinen im Ödland einen wahren Kern haben könnte. Ihr Hauptlager ist die Staubspeiergrotte, eine weite Reise westlich von Sigruns Lager."}},faq={{q="Wer bittet um das Altmetall?",a="Sigrun Ironhew, die es für den Bau von Verteidigungsanlagen und anderen Notwendigkeiten für das Lager benötigt.",al={"questgeber","wer vergibt scrounging","sigrun"}},{q="Warum benötigt das Lager Altmetall?",a="Sigrun fehlen die Materialien zum Bau von Verteidigungsanlagen und anderen Notwendigkeiten, und der Prospector macht sich Sorgen um den Zustand des Lagers.",al={"warum altmetall benötigt wird","zweck von altmetall","verteidigung"}},{q="Wo ist das Altmetall zu finden?",a="Die Oger in der Gegend tragen es bei sich. Ihr Hauptlager ist die Staubspeiergrotte, eine weite Reise westlich von Sigruns Lager.",al={"fundort von altmetall","wo man altmetall bekommt","ogerlager"}},{q="Was kommt davor?",a="Es folgt auf Mirages.",al={"vorherige quest","scrounging voraussetzung"}}},fp="10,179,25.219.0,16.227.0,34.82.0,35.133.0,35.103.0,23.19.0"}
P.entries["quest:734"] = {n="Das wird schwierig",s="Lotwil Veriatus, der mit einem Satz Fesseln beschäftigt ist, schickt Euch zu Lucien Tosselwrench im Ödland. Lotwil benötigt ein Zahnrad Nr. 5 und möchte, dass es zurückgebracht wird.",h="Lotwil Veriatus, der mit einem Satz Fesseln beschäftigt ist, schickt Euch zu Lucien Tosselwrench im Ödland.",kw={"ödland","zahnrad nr. 5","lotwil veriatus","lucien tosselwrench","fesseln"},sec={{t="Zahnrad Nummer Fünf",b="Lotwil blickt kurz zu Euch auf und beugt sich dann wieder über die Fesseln. Ihr sollt gehen und mit Lucien Tosselwrench sprechen, da Lotwil ein Zahnrad Nr. 5 benötigt und Euch bittet, es zu bringen."},{t="Luciens Urteil",b="Bei der Erwähnung von Zahnrad Nr. 5 ist Lucien Tosselwrench wenig zuversichtlich, wie die Dinge ausgehen werden."}},faq={{q="Wer vergibt diese Quest?",a="Lotwil Veriatus, der an einem Satz Fesseln im Ödland arbeitet.",al={"wer diese quest startet","lotwil veriatus quest","questgeber"}},{q="Was benötigt Lotwil?",a="Ein Zahnrad Nr. 5, um dessen Rückbringung Lotwil Euch bittet, nachdem Ihr mit Lucien Tosselwrench gesprochen habt.",al={"was will lotwil","welches zahnrad","zahnrad 5"}},{q="Mit wem spreche ich wegen des Zahnrads?",a="Lotwil schickt Euch zu Lucien Tosselwrench im Ödland.",al={"wo man zahnrad 5 findet","wer ist lucien","lucien tosselwrench"}}},fp="24,155,15.173.0,16.86.1,21.69.0,22.86.0,32.56.0"}
P.entries["quest:735"] = {n="Der Stern, die Hand und das Herz",s="Gerrig Knochengriff in Eisenschmiede hat ein überzähliges Exemplar von Yagyins Zusammenstellung und trennt sich dafür von drei Gegenständen der Macht. Gerrig will ihre Namen nicht laut aussprechen und schreibt sie stattdessen auf eine Notiz.",h="Gerrig Knochengriff in Eisenschmiede hat ein überzähliges Exemplar von Yagyins Zusammenstellung und trennt...",kw={"knochengriffs notiz","gerrig knochengriff","hand von dagun","eisenschmiede","legacy heart","stern von xil'yeh","yagyins zusammenstellung"},sec={{t="Ein Austausch hinter verschlossenen Lippen",b="Gerrig hört Euch nach Yagyins Zusammenstellung fragen und überlegt, ob Ihr irgendwo eine neue Niederlassung ihres Ordens gründet, entscheidet dann aber, dass es nicht Gerrigs Aufgabe ist, nachzufragen. Gerrig hat ein zusätzliches Exemplar und glaubt, dass jene des Ordens einander beistehen müssen. Als Gegenleistung müssen drei Gegenstände der Macht herbeigebracht werden. Ihre Namen bleiben ungesagt, da womöglich jemand zuhört, und Gerrig schreibt sie auf."},{t="Die drei Gegenstände",b="Die Notiz nennt den Stern von Xil'yeh, die Hand von Dagun und das Legacy Heart. Sie sind es, was Gerrig verlangt, ehe die Zusammenstellung übergeben wird."},{t="Gerrigs Urteil",b="Sobald die Relikte übergeben wurden, nennt Gerrig Euch einfallsreich und glaubt, dass Ihr, sollte die Gründung einer neuen Niederlassung des Ordens wahrhaft Eure Aufgabe sein, diese gut leiten werdet."}},faq={{q="Wer verlangt nach den drei Gegenständen?",a="Gerrig Knochengriff in Eisenschmiede, der als Gegenleistung ein zusätzliches Exemplar von Yagyins Zusammenstellung abzugeben hat.",al={"questgeber","wer startet der stern die hand und das herz","gerrig knochengriff quest"}},{q="Welche drei Gegenstände will Gerrig Knochengriff?",a="Gerrig Knochengriffs Notiz verlangt nach drei Dingen: dem Stern von Xil'yeh, der Hand von Dagun und dem Legacy Heart.",al={"benötigte gegenstände","welche relikte braucht er","knochengriffs notiz gegenstände"}},{q="Warum schreibt Gerrig die Gegenstände auf, anstatt sie laut auszusprechen?",a="Gerrig will ihre Namen nicht aussprechen, weil womöglich jemand zuhört.",al={"warum aufschreiben","warum die geheime notiz","knochengriff flüstern"}},{q="Was ging dem in der Reihe voraus?",a="Es folgt auf To Ironforge for Yagyin's Digest, wo Theldurin der Verirrte Euch zu Gerrig geschickt hat.",al={"vorquest","vorherige quest"}}},fp="32,193,30.378.0,15.134.0,16.163.1,29.89.0,43.106.0,60.67.0,35.89.0"}
P.entries["quest:736"] = {n="Der Stern, die Hand und das Herz",s="The Star, the Hand and the Heart ist eine Quest in Unterstadt, in der Bewahrer Bel'dugur einen angehenden Anführer prüft, der eine neue Niederlassung seines Ordens gründen möchte. Um die unverzichtbare Yagyins Zusammenstellung zu verdienen, muss der Bittsteller drei Gegenstände der Macht aufspüren, deren Namen Bel'dugur nicht laut auszusprechen wagt.",h="The Star, the Hand and the Heart ist eine Quest in Unterstadt, in der Bewahrer Bel'dugur einen angehenden...",kw={"bel'dugurs notiz","bewahrer bel'dugur","orden","the star the hand and the heart","drei gegenstände der macht","unterstadt","yagyins zusammenstellung"},ang={["class:Warlock"]="Die Erlangung von Yagyins Zusammenstellung zum Aufbau einer neuen Schar stellt einen entscheidenden Schritt bei der Erweiterung der Reichweite und der okkulten Meisterschaft Eures dunklen Ordens dar.",["race:Undead"]="Von der Unterstadt aus leitet Bewahrer Bel'dugur Praktizierende der Verlassenen an, die unter den schattigen Türmen der Stadt tiefer in verbotene Riten eintauchen wollen."},sec={{t="Eine Prüfung der Bruderschaft",b="In den schattigen Gängen der Unterstadt wenden sich ehrgeizige Praktizierende, die ihren eigenen Zirkel leiten wollen, an Bewahrer Bel'dugur. Um eine neue Schar zu sammeln und eine Niederlassung ihres Ordens zu eröffnen, benötigt ein angehender Anführer Yagyins Zusammenstellung, einen maßgeblichen Text rituellen Wissens, der von dem Bewahrer gehütet wird. Bel'dugur steht bereit, seinen Mitbruder zu unterstützen, verlangt jedoch einen Beweis der Würdigkeit, bevor er eine solche Autorität gewährt."},{t="Die unausgesprochenen Relikte",b="Bewahrer Bel'dugur trennt sich nicht leichtfertig von Yagyins Zusammenstellung. Er benötigt drei verschiedene Gegenstände der Macht, um seinen Teil des Handels zu erfüllen. Diese Relikte tragen eine so gefährliche oder heilige Bedeutung, dass ihre Namen nicht einmal laut ausgesprochen werden können; Bel'dugur schreibt sie stattdessen auf eine private Notiz. Nur ein Praktizierender, der in der Lage ist, alle drei unausgesprochenen Artefakte aufzuspüren und zu beschaffen, erweist sich als würdig, eine eigene Niederlassung zu gründen."}},faq={{q="Wer ist Bewahrer Bel'dugur?",a="Bewahrer Bel'dugur ist eine okkulte Gestalt mit Wohnsitz in der Unterstadt, die Mitgliedern ihrer dunklen Bruderschaft beisteht. Er hütet mächtiges Wissen und verlangt von Kandidaten, ihre Kompetenz zu beweisen, bevor er ihnen heilige Texte anvertraut.",al={"wer ist bewahrer bel'dugur","bel'dugurs rolle","beldugur unterstadt"}},{q="Was ist Yagyins Zusammenstellung?",a="Yagyins Zusammenstellung ist ein spezialisierter Lehrtext, der für die Gründung und Leitung einer neuen Niederlassung oder das Sammeln einer neuen Schar innerhalb eines geheimnisvollen okkulten Ordens erforderlich ist.",al={"was ist yagyins zusammenstellung","zweck von yagyins zusammenstellung","yagyins zusammenstellung buch"}},{q="Welche Gegenstände fordert Bewahrer Bel'dugur?",a="Bel'dugur benötigt drei bestimmte Gegenstände der Macht. Da ihre Namen zu verboten oder gefährlich sind, um sie laut auszusprechen, hält er sie stillschweigend in einer schriftlichen Notiz fest, damit der Bittsteller sie beschaffen kann.",al={"welche gegenstände braucht bel'dugur","gegenstände auf beldugurs notiz","drei gegenstände der macht"}},{q="Warum werden die Namen der angeforderten Gegenstände nicht laut ausgesprochen?",a="Bewahrer Bel'dugur weist ausdrücklich darauf hin, dass er die Namen dieser drei Relikte nicht laut aussprechen kann, was darauf hindeutet, dass sie eine dunkle, heilige oder unberechenbare Macht besitzen, die Diskretion erfordert.",al={"warum kann bel'dugur die namen der gegenstände nicht aussprechen","kann namen nicht aussprechen","unausgesprochene gegenstandsnamen"}},{q="Was bedeutet es, eine weitere Schar zu sammeln?",a="Das Sammeln einer Schar bezieht sich auf das Rekrutieren von Anhängern und den Aufbau einer funktionierenden, unabhängigen Niederlassung ihrer Bruderschaft, wodurch die Bereitschaft bewiesen wird, andere Praktizierende des Handwerks anzuleiten.",al={"was bedeutet eine schar zu sammeln","eine niederlassung eröffnen","niederlassung unseres ordens"}},{q="Wo ist diese Quest angesiedelt?",a="Die Quest dreht sich um Bewahrer Bel'dugur, der in der unterirdischen Hauptstadt der Verlassenen, der Unterstadt, stationiert ist.",al={"wo findet diese quest statt","bel'dugurs aufenthaltsort","ort der questabgabe"}}},fp="32,291,21.413.0,19.424.0,24.221.0,24.160.0,41.190.0,58.174.0,42.188.0,29.118.0"}
P.entries["quest:737"] = {n="Verbotenes Wissen",s="Yagyins Zusammenstellung wird mit der Warnung übergeben, sie gut vor unfreundlichen Händen zu schützen. Sie soll zu Theldurin dem Verirrten gebracht werden.",h="Yagyins Zusammenstellung wird mit der Warnung übergeben, sie gut vor unfreundlichen Händen zu schützen.",kw={"ödland","verbotenes wissen","der stern das herz und die hand","theldurin der verirrte","yagyins zusammenstellung"},sec={{t="Ein Buch, das brennt",b="Gerrig Knochengriff in Eisenschmiede oder Bewahrer Bel'dugur in Unterstadt übergibt Euch die Zusammenstellung. Ihr werdet ermahnt, sie gut zu hüten und von unfreundlichen Händen fernzuhalten, denn sie birgt viele Wahrheiten, und die Wahrheit neigt dazu zu brennen. Bringt sie zu Theldurin dem Verirrten."},{t="Theldurins Hoffnung",b="Theldurin ruft aus, dass Hoffnung aufkeimt, und sagt, dass Eure Bemühungen sie alle noch retten könnten – mit einem Denkmal, einem Schrein und Eurem Namen, der über Generationen hinweg gepriesen wird. All dies gilt jedoch nur, solange SIE nicht befreit werden, um an die Oberfläche aufzusteigen; in diesem Fall, so Theldurin, sind alle Wurmfutter."}},faq={{q="Welcher Gegenstand muss abgeliefert werden?",a="Yagyins Zusammenstellung, ein Buch, das viele Wahrheiten birgt. Es muss sorgfältig bewacht und vor unfreundlichen Händen geschützt werden.",al={"welches buch ist das","was ist yagyins zusammenstellung","was bringe ich"}},{q="Wer erhält die Zusammenstellung?",a="Die Zusammenstellung ist für Theldurin den Verirrten bestimmt.",al={"wer bekommt das buch","bei wem gebe ich das ab","wohin kommt die zusammenstellung"}},{q="Was ging dem voraus?",a="Es folgt auf den Schritt, bei dem drei Gegenstände im Austausch gegen die Zusammenstellung beschafft wurden.",al={"vorherige quest","was führt hierzu","welche quest kommt vor verbotenes wissen"}}},fp="19,131,17.255.0,16.285.1,32.106.0,24.43.0,22.81.0"}
P.entries["quest:738"] = {n="Sucht Agmond",s="Ausgrabungsleiter Eisenband hat seit Wochen nichts von Prospector Agmond gehört. Agmond leitete die Ausgrabungsstätten im Ödland, und Eisenband möchte, dass Agmond gefunden wird, damit der Bericht abgeholt werden kann.",h="Ausgrabungsleiter Eisenband hat seit Wochen nichts von Prospector Agmond gehört.",kw={"agmond","festung angor","ödland","eisenschmiede","ausgrabungsleiter eisenband"},sec={{t="Ein stummer Prospektor",b="Agmond leitete die Ausgrabungen im Ödland im Südwesten. Eisenband sagt absichtlich „leitete“, denn seit Wochen gibt es keine Nachricht von Agmond. Eisenband möchte, dass Agmond gefunden wird und mit ihm der Bericht. Von Agmond hörte man zuletzt bei der am weitesten südlich gelegenen Ausgrabung des Ödlands, einem kleinen Außenposten jenseits der Festung Angor, und dort sollte die Suche beginnen."},{t="Wo die Spur endet",b="Am Ende der Suche findet Ihr ein Skelett, bei dem es sich um die Überreste von Agmond handeln muss. Der Körper ist zertrümmert und zerschlagen, und die Knochen wurden säuberlich abgenagt."}},faq={{q="Wer ist Prospector Agmond?",a="Agmond leitete die Ausgrabungen im Ödland, südwestlich von Ausgrabungsleiter Eisenband.",al={"wer ist agmond","wer agmond","agmond lore"}},{q="Warum sucht Ausgrabungsleiter Eisenband nach Agmond?",a="Eisenband hat seit Wochen nichts von Agmond gehört und möchte Agmonds Bericht erhalten.",al={"warum find agmond","eisenband sucht nach agmond"}},{q="Wo wurde Prospector Agmond zuletzt vermutet?",a="Bei der am weitesten südlich gelegenen Ausgrabung des Ödlands, einem kleinen Außenposten jenseits der Festung Angor.",al={"agmond aufenthaltsort","wo ist ausgrabungsstätte von agmond","wo war agmond"}},{q="Was geht dem in der Reihe voraus?",a="Es folgt auf Ironband Wants You!",al={"vorherige quest","voraussetzung für find agmond"}}},fp="11,192,19.345.0,20.154.1,25.77.0,46.77.0,45.80.0,36.30.0"}
P.entries["quest:739"] = {n="Murdaloc",s="Agmonds geschundene Überreste liegen im Ödland, und neben der toten Hand ist ein Name in den Sandstein gekritzelt: Murdaloc. Agmonds Mörder soll zur Strecke gebracht und Ausgrabungsleiter Eisenband in Loch Modan Bericht erstattet werden.",h="Agmonds geschundene Überreste liegen im Ödland, und neben der toten Hand ist ein Name in den Sandstein...",kw={"agmond","ödland","loch modan","murdaloc","ausgrabungsleiter eisenband","stonevault bonesnapper","trogg"},sec={{t="Ein Name im Sandstein",b="Agmonds Spur kommt von Westen her, und das über Stein und Sand verschmierte Blut verrät, wie weit der Zwerg kroch, bevor er hier starb. Neben der leblosen Hand steht, in den Sandstein des Ödlands geritzt, ein einziges Wort: Murdaloc. Agmonds Mörder soll getötet werden, zusammen mit einer Reihe von Stonevault Bonesnappern, und die Nachricht ist zu Ausgrabungsleiter Eisenband in Loch Modan zu bringen."},{t="Eisenbands Antwort",b="Eisenband nimmt die Nachricht mit Fassung auf und erinnert sich an Agmond als stark von Arm, grimmig mit dem Hammer und dickköpfig. Eisenband sagt, Agmond sei von verfluchten Troggs getötet worden, und ist sich sicher, dass Agmond auf dem Weg eine ganze Reihe von ihnen mit in den Tod gerissen hat."}},faq={{q="Wer war Agmond?",a="Agmond war ein Zwerg, der für Ausgrabungsleiter Eisenband die Ausgrabungsstätten im Ödland leitete. Eure Suche nach Agmond endete an einem Skelett.",al={"wer ist agmond","agmond lore"}},{q="Wer ist Murdaloc?",a="Murdaloc ist der Name, der neben Agmonds toter Hand in den Sandstein gekritzelt ist. Ihr sollt Agmonds Mörder, Murdaloc, erschlagen.",al={"was ist murdaloc","murdaloc lore"}},{q="Wohin muss der Bericht gebracht werden?",a="Zu Ausgrabungsleiter Eisenband in Loch Modan.",al={"wem berichte ich von murdaloc","wo ist eisenband"}}},fp="8,214,23.361.0,16.226.1,15.137.0,16.116.0,33.37.0"}
P.entries["quest:74"] = {n="Die Legende von Stalvan",s="Dieser Schritt der Ermittlung führt tief in eine alte Kiste mit Erbstücken der Flintridges, die an den Kanälen von Sturmwind zurückgelassen wurde. Beim Durchstöbern der staubigen Relikte kommt eine zerrissene Tagebuchseite zum Vorschein – ein entscheidender handschriftlicher Hinweis auf das frühere Leben von Stalvan Dunstmantel, der zu Marschall Haggard im Wald von Elwynn führt.",h="Dieser Schritt der Ermittlung führt tief in eine alte Kiste mit Erbstücken der Flintridges, die an den...",kw={"dämmerwald","wald von elwynn","unglückseliger geist","marschall haggard","mistmantle","versiegelte kiste","stalvan","zerrissene tagebuchseite"},ang={["faction:Alliance"]="Das Untersuchen alter ungeklärter Fälle im Herzen von Elwynn offenbart, wie unbemerkt zutiefst persönliche Schrecken an den Augen der Marshals von Sturmwind vorbeigehen konnten.",["race:Human"]="Marschall Haggard repräsentiert die alternde Veteranengeneration von Sturmwind, die wichtige Erinnerungen an das Königreich bewahrt, bevor der Erste und Zweite Krieg Familien auseinanderrissen."},sec={{t="Die Vergangenheit ausgraben",b="Beim Durchwühlen einer versiegelten Kiste voller muffiger Erbstücke, alter Jagdtrophäen und Familienporträts entdecken Ermittler eine einzelne zerrissene Tagebuchseite, die unter einer Keramikvase versteckt liegt. Von Stalvan Dunstmantels eigener Hand verfasst, gewährt dieses Überbleibsel einen intimen Einblick in den Geist eines zurückgezogenen Gelehrten, bevor das Unglück geschah."},{t="Das schwindende Augenlicht eines Marshals",b="Marschall Haggard, mittlerweile betagt und von schwindendem Augenlicht geplagt, müht sich ab, die Schrift auf dem mitgenommenen Pergament zu entziffern. Dennoch weckt die markante Handschrift ein beunruhigendes Gefühl in seiner Erinnerung und ruft Dokumente und Vorfälle aus vergangenen Jahren wach, bevor die Dunkelheit sein Augenlicht trübte."}},faq={{q="Wo befindet sich die versiegelte Kiste?",a="Die versiegelte Kiste steht an den Kanälen von Sturmwind direkt hinter Verwalter Folsom inmitten der zusammengepackten Habseligkeiten der Familie Flintridge. Die Seite, die Ihr dort findet, wird anschließend zu Marschall Haggard in den südöstlichen Wald von Elwynn gebracht.",al={"standort der kiste","wo ist die kiste","haggard kiste"}},{q="Was befindet sich in der versiegelten Kiste?",a="Die Kiste enthält staubige Erbstücke, ein Familienporträt, alte Bücher, Jagdtrophäen und eine Keramikvase, unter der eine zerrissene Seite aus Stalvans Tagebuch liegt.",al={"kisteninhalt","was ist in der kiste","zerrissene seite kiste"}},{q="Wer ist Marschall Haggard?",a="Marschall Haggard ist ein ältlicher, pensionierter Offizier von Sturmwind, der einsam im südlichen Wald von Elwynn lebt. Trotz seines schwindenden Augenlichts und seiner Gebrechlichkeit machen ihn seine Erinnerungen an alte Aufzeichnungen und Reisende zu einem entscheidenden Zeugen vergangener Ereignisse.",al={"wer ist haggard","marschall haggard lore","alter marshal elwynn"}},{q="Warum ist diese Tagebuchseite wichtig?",a="Die zerrissene Tagebuchseite ist ein direkter Beweis, der von Stalvan Dunstmantel selbst verfasst wurde. Seine markante Handschrift und die nachhallenden Gedanken helfen dabei, verstreute Berichte aus dem Dämmerwald und Elwynn mit seinem persönlichen Niedergang zu verknüpfen.",al={"warum zerrissene seite wichtig ist","tagebuchseite hinweis","stalvan tagebuch"}},{q="Was geschieht, wenn die Kiste geöffnet wird?",a="Werden die Überbleibsel von Stalvans Vergangenheit aufgewühlt, weckt dies die rastlosen Toten, woraufhin sich ein rachsüchtiger Unglückseliger Geist manifestiert und jene angreift, die versuchen, das Unglück aufzuklären.",al={"unglückseliger geist spawn","geist nach kiste","warum hat mich ein geist angegriffen"}},{q="Wohin führt die Ermittlung als Nächstes?",a="Nachdem Marschall Haggard die zerrissene Seite vorgelegt wurde, weist seine Erinnerung an die Handschrift den Weg der weiteren Ermittlung, um noch mehr erhaltene Fragmente von Stalvans Geschichte zu finden.",al={"nächster schritt","nach zerrissener seite","wohin als nächstes"}}},fp="21,309,19.331.0,24.276.1,34.227.0,32.158.0,23.226.0,35.215.0,38.163.0,39.173.0"}
P.entries["quest:741"] = {n="Der geistesabwesende Ausgrabungsleiter",s="Dieser Botengang befördert ein seltsames versteinertes Exemplar, das an den wilden Stränden der Dunkelküste geborgen wurde, zum Außenposten der Forscherliga in Darnassus. Archäologin Hollee weigert sich, ihren zerstreuten Kollegen im Feld allein zu lassen, und vertraut den Transport des Exemplars stattdessen einem vorbeireisenden Abenteurer an. Die Ankunft des Fossils in der Hauptstadt der Nachtelfen weckt sogleich das rege Interesse von Chefarchäologe Grauflaum.",h="Dieser Botengang befördert ein seltsames versteinertes Exemplar, das an den wilden Stränden der Dunkelküste...",kw={"archäologe","dunkelküste","darnassus","forscherliga","fossil","greywhisker","hollee","remtravel"},ang={["faction:Alliance"]="Diese Aufgabe verdeutlicht die logistische Abhängigkeit der Allianzmitglieder voneinander, da Zwergenforscher auf reisende Abenteurer angewiesen sind, um die abgelegenen Küsten der Dunkelküste und die Höhen von Darnassus sicher miteinander zu verbinden.",["race:Dwarf"]="Das Überbringen von Remtravels Fossil erfüllt den zentralen Auftrag der Forscherliga: die tiefste Vergangenheit der Welt ans Licht zu bringen und den unermesslichen Wert zwergischer Beharrlichkeit zu beweisen.",["race:NightElf"]="Zu beobachten, wie Zwergenausgräber uralte Überreste aus dem heiligen Boden der Dunkelküste zutage fördern, kann befremdlich wirken, doch die Zusammenarbeit mit der Liga stärkt die Bande der Allianz."},sec={{t="Ein Bote zur Hauptstadt",b="Die Ausgrabungen von Ausgrabungsleiter Wirrbart an der nebligen Küste der Dunkelküste haben ein merkwürdiges Fossil zutage gefördert, doch tiefer zu graben ist ihm wichtiger als jedes Protokoll. Da Archäologin Hollee den umherwandernden Ausgräber inmitten der gefährlichen Bestien und feindseligen Kultisten der Küste nicht allein lassen möchte, bleibt sie zurück, um über ihn zu wachen. Damit die Entdeckung dokumentiert werden kann, benötigt sie einen Reisenden der Allianz, der das Exemplar hinauf nach Darnassus bringt, wo die Zwergengilde eine wissenschaftliche Delegation unterhält."},{t="Die Interessen der Zwerge in Kalimdor",b="Zwerge aus Eisenschmiede haben unter dem Banner der Forscherliga in großer Zahl Das große Meer überquert, begierig darauf, uralte Relikte und verlorene Geschichte unter dem Boden von Kalimdor freizulegen. Als er das Artefakt in der Elfenhauptstadt in Empfang nimmt, verliert Chefarchäologe Grauflaum keine Zeit und staunt über Remtravels Talent, uralte Schätze aufzuspüren. Während Nachtelfen ihre Wälder als lebendige Zufluchtsorte betrachten, sieht die Liga die uralten Ländereien als weitreichende archäologische Ausgrabungsstätte, die darauf wartet, entschlüsselt zu werden."}},faq={{q="Was ist das geheimnisvolle Fossil?",a="Es handelt sich um ein unidentifiziertes versteinertes Exemplar, das an der Küste der Dunkelküste von Ausgrabungsleiter Wirrbart freigelegt wurde. Sein hohes Alter und seine seltsame Natur machen es zu einem wertvollen Fund für die in Darnassus stationierten Gelehrten der Forscherliga.",al={"geheimnisvolles fossil","welches fossil ist das","remtravels fossil"}},{q="Warum bleibt Hollee in Dunkelküste zurück?",a="Archäologin Hollee fühlt sich verpflichtet, über Ausgrabungsleiter Wirrbart zu wachen. Er neigt dazu, beim Ausgraben umherzuwandern und Gefahren zu ignorieren, daher weigert sie sich, ihn in der Wildnis allein zu lassen, während seine Entdeckungen nach Darnassus gebracht werden.",al={"warum geht hollee nicht","hollee bleibt","warum hollee bleibt"}},{q="Wer ist Chefarchäologe Grauflaum?",a="Greywhisker ist ein hochrangiger Vertreter der Forscherliga von Eisenschmiede, der die archäologischen Unternehmungen im nördlichen Kalimdor beaufsichtigt. Er operiert von Darnassus aus und untersucht Relikte, die von zwergischen Ausgräbern aus dem Feld zurückgebracht werden.",al={"greywhisker","wer ist greywhisker","chef greywhisker"}},{q="Warum operiert die Forscherliga in Darnassus?",a="König Magni Bronzebart gründete die Forscherliga, um die Ursprünge des Zwergenvolkes und die uralte Geschichte ganz Azeroths zu ergründen. Die freundschaftlichen diplomatischen Beziehungen zu den Nachtelfen ermöglichen es den Zwergengelehrten, Expeditionen von Darnassus aus zu starten, um Kalimdors vergessene Länder zu erforschen.",al={"zwerge in darnassus","forscherliga darnassus","warum sind zwerge hier"}},{q="Wo landet dieses Fossil nach Darnassus?",a="Chefarchäologe Grauflaum begutachtet den Fund in Darnassus, doch Entdeckungen dieser Größenordnung sind dafür bestimmt, katalogisiert oder über die Kanäle der Liga weiter in Richtung des großen Museums in Eisenschmiede geleitet zu werden.",al={"wohin kommt das fossil","nächster schritt für das fossil"}},{q="Wo hat Remtravel das Exemplar gefunden?",a="Remtravel entdeckte das Exemplar an der wilden Küste der Dunkelküste – einem Gebiet voller Schiffswracks, uralter Ruinen und versteinerten Meereslebewesen, die bis in die Zeit vor der Zerschlagung der Welt zurückreichen.",al={"wo wurde das fossil gefunden","remtravels ausgrabungsstätte"}}},fx={c70c2c67={q="Warum möchte Archäologin Hollee, dass das Fossil nach Darnassus geliefert wird?",a="Ausgrabungsleiter Wirrbart möchte seinen Fund sofort untersuchen lassen, aber jemand muss ihn zu ihren Vorgesetzten bringen. Hollee ist entschlossen, Dunkelküste nicht zu verlassen, während Wirrbart in der Wildnis zurückbleibt, also verlässt sie sich darauf, dass Ihr den unbezahlbaren Fund in ihrem Namen direkt zu Chefarchäologe Grauflaum nach Darnassus bringt.",al={"warum fossil nach darnassus schicken","beweggrund hollee","warum fossil zustellen"}}},fp="28,412,24.493.0,29.498.0,30.220.0,41.236.0,39.222.0,52.284.0,46.205.0,38.177.0"}
P.entries["quest:742"] = {n="Die Jagd im Eschental",s="Die Jagd in Eschental ist eine Aufforderung an junge Champions der Horde, die Donnerfels besuchen, und drängt sie nach Norden in das dichte Blätterdach von Eschental. Der Ruf wird von den Herolden der Stadt überbracht und weist Reisende an, sich bei Senani Donnerherz am Splitterholzposten zu melden, um an einer Bewährungsjagd teilzunehmen.",h="Die Jagd in Eschental ist eine Aufforderung an junge Champions der Horde, die Donnerfels besuchen, und drängt...",kw={"eschental","jagd","senani","splintertree","donnerfels","thunderheart","windstrider","der zoramstrand"},ang={["class:Hunter"]="Die ungezähmten Pirscher von Eschental bieten Jägern die Gelegenheit, das Fährtenlesen in dichtem Waldland zu meistern – ganz anders als in den trockenen, offenen Savannen des Südens.",["faction:Horde"]="Der Splitterholzposten und der Zoramstrand sind lebenswichtige Aufmarschgebiete für die nördlichen Nachschublinien der Horde und darauf angewiesen, dass frische Rekruten die wilden Bestien und feindseligen Ureinwohner in Schach halten.",["race:Tauren"]="Für Tauren, die ihre Prüfungen in den offenen Ebenen von Mulgore abgelegt haben, stellt das dichte und schattige Blätterdach von Eschental unter den wachsamen Augen ihrer Stammesgeschwister wie Senani eine ungewohnte, heilige Herausforderung dar."},sec={{t="Ein Ruf vom High Rise",b="In den friedlichen Höhen von Donnerfels halten Läufer die aufstrebende Horde über Gelegenheiten jenseits der Grenzen von Mulgore auf dem Laufenden. Kliffläufer Windschreiter überbringt eine offene Einladung an bewährte Abenteurer, die nach größeren Herausforderungen suchen. Da die Horde tief im uralten Wald nördlich des Brachlands Fuß fasst, sind junge Krieger aufgerufen, jene Außenposten zu verstärken und ihre Überlebensfähigkeiten in einer weitaus raueren Umgebung auf die Probe zu stellen."},{t="Die nördliche Grenze",b="Eschental bedeutet für die Horde sowohl reiche Ressourcen als auch ernste Gefahren. Zwei bedeutende Lager sichern die Präsenz der Fraktion in diesem Gebiet: der Splitterholzposten an der Hauptstraße und ein abgelegener Außenposten an der Westküste am Zoramstrand. Bei der Ankunft am Splitterholzposten geraten eintreffende Rekruten direkt unter die Fittiche von Senani Donnerherz, einer erfahrenen Waldläuferin, die eine gewaltige Jagd organisiert, um die Wildnis zu zähmen und Ruhm für die Horde zu erlangen."}},faq={{q="Wer bietet diese Quest in Donnerfels an?",a="Kliffläufer Windschreiter bietet vorbeikommenden Abenteurern in Donnerfels diese Aufgabe an. Seine Pflicht ist es, fähige Kämpfer auf die Expansionsbemühungen der Horde aufmerksam zu machen und sie zu abgelegenen Außenposten zu leiten, die Hilfe benötigen.",al={"wer startet jagd in eschental","questgeber jagd in eschental","kliffläufer windschreiter"}},{q="Wo befindet sich der Splitterholzposten?",a="Der Splitterholzposten ist eine befestigte Siedlung der Horde im östlichen Eschental. Um ihn zu erreichen, reist geradewegs nach Norden über die Grenze des Brachlands nach Eschental und folgt dann dem östlichen Waldpfad, der tiefer in die Wälder führt.",al={"splintertreeposten standort","weg zum splintertreeposten","wo ist splintertreeposten"}},{q="Wer ist Senani Donnerherz?",a="Senani Donnerherz ist eine erfahrene Tauren-Fährtenleserin, die am Splitterholzposten stationiert ist. Sie koordiniert die Jagdbemühungen in Eschental und stellt die Stärke und Geduld der Horderekruten gegen die einheimischen Raubtiere auf die Probe.",al={"senani donnerherz","wer ist senani","thunderheart nsc"}},{q="Warum jagt die Horde in Eschental?",a="Die Horde treibt eine aktive Expansion nach Eschental voran, um Holz zu sammeln und strategisches Terrain zu sichern. Die Jagd selbst dient dazu, die gefährlichen wilden Tiere auszudünnen, die ihre Lager bedrohen, und ermöglicht es gleichzeitig jungen Abenteurern, ihren Mut in ungewohntem Terrain zu beweisen.",al={"warum jagd in eschental","zweck der jagd in eschental","ziele der horde in eschental"}},{q="Was ist der in der Einsatzbesprechung erwähnte Zoramstrand?",a="Der Zoramstrand ist das Küstenlager der Horde an den äußersten westlichen Gestaden von Eschental mit Blick auf das Meer. Er dient als sekundärer maritimer Stützpunkt und als Bastion gegen Naga und feindselige Waldbewohner.",al={"was ist der zoramstrand","außenposten zoramstrand","zoram außenposten"}},{q="Was geschieht nach der Meldung bei Senani?",a="Sobald Ihr Euch bei Senani Donnerherz meldet, heißt sie Euch im Außenposten willkommen und führt Euch sogleich in die weiteren Jagdaufgaben ein, indem sie Euch anweist, die wildesten Bestien von Eschental aufzuspüren und zu bezwingen.",al={"folgequest nach jagd in eschental","nächste quest nach senani","fortsetzung der jagd"}}},fx={af70e220={q="Warum möchte Kliffläufer Windschreiter, dass Ihr ins Eschental geht?",a="Kliffläufer Windschreiter dient als Herold für die Horde und weist fähige junge Champions den Weg dorthin, wo sie am dringendsten gebraucht werden. Die Horde sichert aggressiv ihre Grenzposten in den ungezähmten Wäldern nördlich des Brachlands, und Jäger wie Senani Donnerherz benötigen frische Rekruten, um ihre Präsenz zu verstärken und in der Wildnis Ruhm zu erlangen.",al={"warum ins eschental schicken","beweggrund von kliffläufer windschreiter","warum will windschreiter das"}}},fp="18,291,28.451.0,21.468.0,39.213.0,35.220.0,27.211.0,38.261.0,51.196.0,39.197.0"}
P.entries["quest:743"] = {n="Windfuriengefahr",s="Windfuriengefahr ist ein Ritus kriegerischer Reife, der von Ruul Adlerklaue im Dorf der Bluthufe angeboten wird. Junge Tauren und Abenteurer der Horde haben die Aufgabe, die wilden Windfurienharpyien zu bekämpfen, die in den südöstlichen Klippen von Mulgore nisten. Die Jagd auf diese wilden Raubtiere dient als grundlegende Prüfung von Geschick und Überlebensfähigkeit, bevor die Reise über die Heimat des Stammes hinausgeht.",h="Windfuriengefahr ist ein Ritus kriegerischer Reife, der von Ruul Adlerklaue im Dorf der Bluthufe angeboten...",kw={"dorf der bluthufe","windfuriengefahr","harpyien","mulgore","ruul adlerklaue","taurenprüfung","windfurien","windfurienkrallen"},ang={["class:Warrior"]="Die Herausforderung von Ruul Adlerklaue ist besonders bedeutsam für angehende Krieger, die lernen müssen, rasche Sturzangriffe zu parieren und heimtückische Luftangreifer mit standhafter Disziplin zu überwältigen.",["faction:Horde"]="Verbündete der Tauren, die sich Ruuls Prüfung stellen, beweisen ihre Hingabe für den Schutz des Kernlandes der Horde und verdienen sich den dauerhaften Respekt des Dorfes der Bluthufe.",["race:Tauren"]="Für junge Tauren ist das Säubern der Windfuriennester sowohl ein Akt zur Verteidigung der Ebenen als auch ein heiliger Übergang ins anerkannte Erwachsenenleben unter den wachsamen Augen der Dorfältesten."},sec={{t="Die Einschätzung eines Lehrers",b="Im Dorf der Bluthufe beobachtet der erfahrene Krieger Ruul Adlerklaue alle Reisenden, die das Herz von Mulgore durchqueren. Von jenen, die das Erwachsenenalter erreichen oder sich für größere Abenteuer bereit zeigen wollen, verlangt Ruul greifbare Beweise für ihre Kampfinstinkte. Das Überleben jenseits der geschützten Täler von Mulgore erfordert Beherrschung gegenüber angriffslustigen, gerissenen Feinden, und Ruul nutzt die wildesten heimischen Raubtiere des Landes, um den Mut eines Jugendlichen zu messen."},{t="Die Bedrohung durch die Windfurien",b="Die Windfurienharpyien nisten am bergigen südöstlichen Rand von Mulgore, abseits der ausgetretenen Pfade, stellen jedoch eine ständige Bedrohung für umherstreifende Wildtiere und einsame Reisende dar. Boshaft und unerbittlich hungrig nach frischem Fleisch verlassen sich diese gefiederten Schrecken auf rasante Sturzflüge und rasiermesserscharfe Klauen. Sie zu besiegen und ihre Krallen zu erbeuten, beweist nicht nur die Macht, eine verankerte Bedrohung zu bezwingen, sondern auch das nötige Tempo, um Angreifern aus der Luft zu begegnen."}},faq={{q="Wer ist Ruul Adlerklaue?",a="Ruul Adlerklaue ist ein erfahrener Taurenkrieger und Lehrer, der im Dorf der Bluthufe lebt. Er unterweist junge Abenteurer und stellt sie auf die Probe, um sicherzustellen, dass sie über die nötige Stärke, die Reflexe und die Tapferkeit verfügen, bevor sie in die weiteren, gefährlicheren Gefilde von Kalimdor aufbrechen.",al={"ruul adlerklaue","wer vergibt windfuriengefahr","ruul"}},{q="Wo sind die Windfurienharpyien in Mulgore zu finden?",a="Die Windfurienharpyien nisten entlang der südöstlichen Berge von Mulgore. Sie errichten ihre einfachen Nester hoch an den Felsen und Hängen der Ausläufer, abseits der Hauptstraße, die durch das Tal führt.",al={"windfurien harpyien aufenthaltsort","wo sind windfurienharpyien","windfurien nest aufenthaltsort"}},{q="Warum gelten die Windfurienharpyien als natürliche Feinde der Tauren?",a="Harpyien sind berüchtigt aggressive, revierbezogene Aasfresser, die jeden angreifen, der ihren Nistplätzen zu nahe kommt. In Mulgore ist die Schar der Windfurien für ihren unstillbaren Appetit auf frisches Fleisch und ihre unerbittliche Aggression gegenüber Reisenden und Weidetieren gleichermaßen bekannt, was sie zu einer dauerhaften Plage der Ebenen macht.",al={"warum tauren gegen harpyien kämpfen","harpyienbedrohung mulgore","windfurien lore"}},{q="Welchen Beweis verlangt Ruul Adlerklaue von der Jagd?",a="Ruul bittet Abenteurer darum, acht Windfurienkrallen direkt von den erschlagenen Harpyien zu beschaffen. Das Abtrennen und Vorzeigen dieser Krallen beweist die Beherrschung der primären natürlichen Waffen der Harpyien.",al={"windfuriengefahr beweis","was man für ruul sammelt","windfurien questziel"}},{q="Warum müssen Abenteurer diese Prüfung ablegen, bevor sie Mulgore verlassen?",a="Ruul betrachtet die wilden Windfurienharpyien als idealen Maßstab für die kriegerische Vorbereitung. Wenn ein Abenteurer dem Tempo, der Wildheit und den Klauen einer Harpyie nicht gewachsen ist, hat er kaum eine Chance gegen die tödlicheren Gefahren, die sich jenseits der schützenden Klippen von Mulgore zusammenbrauen.",al={"zweck der prüfung","warum windfuriengefahr machen","ruuls test"}},{q="Wo liegt das Dorf der Bluthufe?",a="Das Dorf der Bluthufe liegt im Herzen Mulgores nahe dem Stonebullsee, südlich des Großen Tores und von Donnerfels. Es dient als zentraler Knotenpunkt für Kultur, Handel und Ausbildung von reisenden Tauren, die durch die Ebenen ziehen.",al={"bloodhoof standort","wo ist bloodhoof","ruul standort"}}},fx={d8522cbd={q="Warum möchte Ruul Adlerklaue, dass die Windfury-Harpyien gejagt werden?",a="Ruul Adlerklaue ist ein Krieger und Mentor, der damit beauftragt ist, junge Abenteurer auf das Leben jenseits der sicheren Grenzen von Mulgore vorzubereiten. Er sieht die grausamen Windfury-Harpyien als natürliche Prüfung an – ein wahrer Maßstab für Euer kriegerisches Können und Eure Bereitschaft, Euch den härteren Bedrohungen der weiteren Welt zu stellen.",al={"warum harpyien jagen","ruuls beweggrund","grund von ruul adlerklaue"}},["1789ad72"]={q="Wer sind die Windfury-Harpyien?",a="Die Windfury-Harpyien sind wilde, vogelartige Aasfresser, die entlang der Bergvorsprünge südöstlich des Dorfes der Bluthufe nisten. Bösartig und gerissen, haben sie lange Zeit Reisende und die Tierwelt in ganz Mulgore gejagt, getrieben von einem unersättlichen Hunger nach frischem Fleisch und einer natürlichen Feindseligkeit gegenüber den Tauren.",al={"windfury-harpyien","wer sind die windfury","windfury-harpyien in mulgore"}},["29c303b8"]={q="Warum jagt Ruul Adlerklaue die Harpyien nicht selbst?",a="Ruul ist ein Lehrer, dessen Aufgabe im Dorf der Bluthufe darin besteht, die nächste Generation von Verteidigern zu fördern, nicht ihre Schlachten für sie zu schlagen. Diese Aufgabe ist ausdrücklich ein Initiationsritus: Ihr müsst Eure eigene Stärke gegen die Raubtiere von Mulgore beweisen, bevor Ihr als geeignet angesehen werdet, jenseits der Ebenen zu reisen.",al={"warum ich","warum mich schicken","warum macht ruul es nicht selbst"}}},fp="23,364,22.435.0,19.451.0,23.275.0,48.204.0,70.299.0,53.188.0,63.257.0,35.220.0"}
P.entries["quest:744"] = {n="Vorbereitungen auf die Zeremonie",s="Preparation for Ceremony ist eine Tradition der Tauren, bei der es um die Herstellung eines zeremoniellen Kopfschmucks für jemanden geht, der sich darauf vorbereitet, vor Oberhäuptling Cairne Bluthuf zu treten. Um die traditionelle Tracht zu vollenden, müssen leuchtende Federn von gefährlichen Harpyien gesammelt werden, die jenseits von Donnerfels nisten, während die Lederbänder vorbereitet werden.",h="Preparation for Ceremony ist eine Tradition der Tauren, bei der es um die Herstellung eines zeremoniellen...",kw={"cairne bluthuf","zeremonie","federn","harpyie","kopfschmuck","mulgore","vorbereitung auf die zeremonie","tauren","donnerfels"},ang={["faction:Horde"]="Einem Mitstreiter der Horde bei seinen traditionellen zeremoniellen Pflichten beizustehen, ehrt die Bräuche der verbündeten Tauren auf den Hochebenen von Donnerfels.",["race:Tauren"]="Aus natürlichen Materialien gefertigte Kopfschmucke sind tief mit der Ehre der Tauren und Übergangsriten vor dem Oberhäuptling verbunden. Das Mitwirken an der Gestaltung solcher Ornate spiegelt den Gemeinschaftssinn und den Stolz der Stämme von Mulgore wider."},sec={{t="Ehrung des Häuptlings",b="In der Kultur der Tauren ist es ein Anlass von großem Stolz und tiefer Ehrfurcht, vor Oberhäuptling Cairne Bluthuf zu treten. Solche Meilensteine verlangen nach angemessener zeremonieller Kleidung, insbesondere einem traditionellen Kopfschmuck, der sorgfältig aus behandeltem Leder und symbolischem Gefieder gefertigt wird. Die Herstellung dieser Ornate gilt unter Familienmitgliedern als Ehre, die mit großer Sorgfalt darauf achten, dass jeder Bestandteil Würde und Respekt vor dem Anführer der vereinten Stämme widerspiegelt."},{t="Federn der Klippen",b="Die Anfertigung eines zeremoniellen Kopfschmucks erfordert sowohl Geschick als auch bestimmte Materialien. Während geschmeidige Lederriemen gegerbt werden, um das Basisband zu bilden, müssen lange und makellose Federn beschafft werden, um die Krone zu schmücken. Die vogelartigen Harpyien, die in den zerklüfteten Hügeln nördlich und nordwestlich von Donnerfels nisten, liefern Federn von genau der benötigten Größe und Färbung, was Reisende dazu auffordert, sich in feindselige Nester zu wagen, um sie zu bergen."}},faq={{q="Auf welche Zeremonie wird sich vorbereitet?",a="Die Zeremonie markiert das Erscheinen eines Tauren vor Oberhäuptling Cairne Bluthuf. Um diesen ehrenvollen Anlass zu würdigen, fertigt sein Geschwisterteil einen besonderen zeremoniellen Kopfschmuck aus gegerbtem Leder und leuchtenden Federn an.",al={"welche zeremonie ist das","was ist die zeremonie","wer tritt vor bluthuf"}},{q="Wer ist Häuptling Bluthuf?",a="Oberhäuptling Cairne Bluthuf ist der ehrwürdige Oberhäuptling und Anführer der vereinten Stämme der Tauren, der von den hohen Hochebenen von Donnerfels aus herrscht. Vor ihm zu stehen, ist für jeden Tauren eine besondere Ehre.",al={"wer ist häuptling bluthuf","cairne bluthuf","wer ist bluthuf"}},{q="Warum werden Harpyienfedern für den Kopfschmuck benötigt?",a="Der zeremonielle Kopfschmuck erfordert Federn von bestimmter Größe und auffälligem Gefieder – insbesondere azurblau und bronzefarben –, um das traditionelle Design zu vervollständigen, während die Lederriemen gegerbt werden.",al={"warum werden harpyienfedern gebraucht","warum harpyienfedern","warum federn"}},{q="Wo befinden sich die Harpyien?",a="Die Harpyien, die diese Gefiederfedern liefern, hausen in den zerklüfteten Landen weit im Norden und Nordwesten von Donnerfels in Mulgore.",al={"wo leben harpyien","wo man harpyien findet","wo gibt es azurblaue und bronzene federn"}},{q="Welche Rolle spielen Harpyien in Mulgore?",a="Harpyien sind bösartige, vogel-humanoide Kreaturen, die in den felsigen Klippen rund um Mulgore nisten. Abgesehen davon, dass sie eine Bedrohung für Reisende und die Stämme darstellen, macht ihr großes, farbenfrohes Gefieder sie zu einer erstklassigen Quelle für zeremonielle Verzierungen.",al={"warum werden harpyien gejagt","was sind harpyien"}},{q="Wer fertigt den zeremoniellen Kopfschmuck an?",a="Eyahn Eagletalon gerbt die Lederriemen und fertigt den Kopfschmuck an, um seinen Bruder zu ehren, während er sich darauf vorbereitet, vor dem Häuptling zu erscheinen.",al={"wer stellt den kopfschmuck her","wer fertigt den kopfschmuck an"}}},fp="24,307,22.430.0,21.430.0,36.217.0,23.195.0,48.194.0,30.131.0,37.226.0,41.150.0"}
P.entries["quest:745"] = {n="Gemeinsame Nutzung des Landes",s="Diese von Baine Bluthuf im Dorf der Bluthufe vergebene Aufgabe schickt junge Horde-Abenteurer los, um der zerstörerischen Wilderei der hiesigen Bleichmähnengnolle Einhalt zu gebieten. Indem Ihr ihre Gerber, Kürschner und Wilderer dezimiert, schützt Ihr Mulgores Tierwelt und lernt die Taurenphilosophie kennen, im Gleichgewicht mit der Erdenmutter zu leben.",h="Diese von Baine Bluthuf im Dorf der Bluthufe vergebene Aufgabe schickt junge Horde-Abenteurer los, um der...",kw={"baine bluthuf","dorf der bluthufe","gnolle","mulgore","bleichmähne","wilderer","gemeinsame nutzung des landes","kürschner","gerber"},ang={["class:Druid"]="Druiden erkennen, dass unkontrollierte Wilderei den Geist der Ebenen stört, was ein sofortiges Eingreifen erfordert, um die Harmonie des Landes wiederherzustellen.",["class:Hunter"]="Die Kürschner und Wilderer der Bleichmähnen stellen das genaue Gegenteil eines wahren Jägers dar: Sie schlachten wilde Kreaturen mit Grausamkeit und Verschwendung statt mit Respekt ab.",["faction:Horde"]="Baine Bluthuf beizustehen stärkt das Band zwischen neuen Horde-Abenteurern und der Führung der noch jungen Taurennation.",["race:Tauren"]="Für junge Tauren ist es ein wesentlicher Schritt, Baines Ruf zu folgen, um die heilige Pflicht zur Verteidigung von Mulgore und die Wahrung des Gleichgewichts der Erdenmutter zu erlernen."},sec={{t="Ein Land im Ungleichgewicht",b="Die Tauren hegen tiefe Ehrfurcht vor der Natur; sie nehmen von ihr nur das, was zum Überleben nötig ist, und ehren in allen Dingen die Erdenmutter. Die Bleichmähnengnolle, die sich südlich des Dorfes der Bluthufe und in einer Höhle im Westen niedergelassen haben, kennen keinen solchen Respekt. Statt maßvoll zu jagen, schlachten sie die Tierwelt der Ebenen rücksichtslos ab und hinterlassen ausgeweidete Kadaver sowie gestörte Ökosysteme. Für ein Volk, das in Mulgore eine friedliche Heimat aufbauen will, ist dieses maßlose Abschlachten untragbar."},{t="Wenn Worte versagen",b="Baine Bluthuf hoffte zunächst, die Angelegenheit friedlich beizulegen, und versuchte, einen Dialog mit den eindringenden Gnollen zu eröffnen. Die Bleichmähnen wiesen jedes Entgegenkommen ab und antworteten auf Diplomatie mit Feindseligkeit und anhaltender Verwüstung. Da Verhandlungen zwecklos sind, greift Baine zur Gewalt. Junge Krieger werden direkt in ihre Jagdlager geschickt, um die Wilderer, Gerber und Kürschner zur Strecke zu bringen, bevor das Grasland dauerhaften Schaden nimmt."},{t="Der Kreislauf von Leben und Tod",b="Diese Mission dient heranwachsenden Streitern als Übergangsritus und moralische Lehre. Nach der Rückkehr von der Jagd erinnert Baine den Abenteurer daran, dass das Nehmen von Leben niemals aus Bosheit geschehen darf, sondern aus der Notwendigkeit heraus, die Harmonie zu wahren. Leben und Tod bilden einen miteinander verwobenen Kreislauf, in dem das eine ohne das andere nicht gedeihen kann – eine fundamentale Wahrheit, die jeder Beschützer von Mulgore verinnerlichen muss."}},faq={{q="Wer vergibt diese Quest?",a="Baine Bluthuf, der Sohn von Oberhäuptling Cairne Bluthuf, bietet diese Aufgabe im Dorf der Bluthufe im Zentrum von Mulgore an.",al={"questgeber","wer startet gemeinsame nutzung des landes","baine quest"}},{q="Warum haben es die Tauren auf die Bleichmähnengnolle abgesehen?",a="Die Bleichmähnengnolle jagen Mulgores Tierwelt rücksichtslos und dezimieren die Herden, ohne das natürliche Gleichgewicht zu achten. Zudem lehnten sie alle Versuche der Tauren ab, friedlich miteinander zu reden.",al={"warum gnolle töten","bleichmähnen problem","was haben gnolle getan"}},{q="Wo halten sich diese Gnolle auf?",a="Die Bleichmähnen unterhalten Lager südlich des Dorfes der Bluthufe und hausen im Höhlensystem des Bleichmähnenfelsens im Westen.",al={"gnoll orte","bleichmähnenlager","wo findet man bleichmähnen"}},{q="Haben die Tauren zuerst versucht, Frieden zu schließen?",a="Ja. Baine merkt an, dass die Tauren mehrfach versuchten, sich zu verständigen und das Land gemeinsam zu nutzen, doch die Gnolle begegneten jedem Friedensangebot mit Respektlosigkeit und Ablehnung.",al={"haben tauren mit gnollen gesprochen","bleichmähnen diplomatie"}},{q="Welche Lehre möchte Baine hier vermitteln?",a="Baine möchte jungen Verteidigern begreiflich machen, dass Tod und Leben einen unzertrennlichen Kreislauf bilden. Auch wenn das Nehmen eines Lebens manchmal notwendig ist, um das Gleichgewicht zu verteidigen, muss es stets mit tiefem Respekt vor der Erdenmutter geschehen.",al={"baines lehre","bedeutung von gemeinsame nutzung des landes"}},{q="Wer sind die Bleichmähnengnolle?",a="Sie sind ein primitiver, hyänenartiger Stamm aus Mulgore, bekannt für ihr helles Fell, ihre territoriale Aggression und ihre völlige Missachtung der Harmonie der Ebenen.",al={"wer sind die bleichmähnen","bleichmähnenstamm"}}},fx={["901e0c5d"]={q="Gegen wen werdet Ihr bei Sharing the Land ausgesandt?",a="Baine sendet Euch gegen die Palemane-Gnolle, die auf die Ebenen südlich des Dorfes der Bluthufe übergegriffen haben und in einer westlichen Höhle Schutz suchen. Diese Wilderer, Abfleischer und Gerber haben rücksichtslos die Tierwelt von Mulgore abgeschlachtet, ohne Ehrfurcht vor dem Gleichgewicht oder der Erdenmutter. Da sie jedes friedliche Angebot der Tauren gewaltsam zurückgewiesen haben, ist Gewalt das einzige Mittel, das bleibt, um ihre Wilderei zu stoppen.",al={"ziele von sharing the land","wen töte ich bei sharing the land","palemane-gnolle bei sharing the land"}}},fp="16,309,21.523.0,15.429.0,28.396.0,21.114.0,49.178.0,31.122.0,39.155.0,42.222.0,28.160.0"}
P.entries["quest:746"] = {n="Zwergenbuddelei",s="Zwergenbuddelei ist eine Quest in Mulgore, die von Baine Bluthuf im Dorf der Bluthufe vergeben wird. Aus Sorge, dass die Ausgrabungen der Zwerge die einheimischen Bestien erzürnen und die heilige Erde schänden, beauftragt Baine junge Verteidiger der Horde damit, ihre Bemühungen zu sabotieren, indem sie deren Spitzhacken beschlagnahmen und zerschlagen.",h="Zwergenbuddelei ist eine Quest in Mulgore, die von Baine Bluthuf im Dorf der Bluthufe vergeben wird.",kw={"baine bluthuf","dorf der bluthufe","zwerg","schmiede","kodo","mulgore","spitzhacken","prospektor"},ang={["class:Shaman"]="Schamanen verstehen, dass die Störung des Grundgesteins durch unvorsichtige Ausgrabungen das Gleichgewicht der Elemente stört und Unruhe unter den Geistern und Kreaturen des Landes hervorruft.",["faction:Horde"]="Dass mit der Allianz verbündete Zwerge in das Kernland der Horde eindringen, untergräbt den nach dem Dritten Krieg geschlossenen, fragilen Frieden und zeigt eklatante Missachtung für die Grenzen der Stämme.",["profession:Mining"]="Während Bergleute den im Stein verborgenen Reichtum verehren, lassen die Methoden der Zwerge in Mulgore Respekt und Harmonie vermissen und setzen stattdessen auf rücksichtslose Zerstörung.",["race:Tauren"]="Der Körper der Erdenmutter ist heilig, und zuzusehen, wie fremde Eindringlinge sich in Mulgores sanfte Steppen bohren, ist ein Affront, der eine sofortige, entschlossene Antwort verlangt."},sec={{t="Eindringlinge in den Hügeln",b="Nordwestlich des Dorfes der Bluthufe haben Zwergenprospektoren damit begonnen, in den sanften Hügeln von Mulgore eine Ausgrabungsstätte abzustecken. Die Forscherliga und ihre Ausgrabungstrupps suchen in ganz Kalimdor nach Titanenrelikten und irdenen Geheimnissen, doch ihre Operationen nehmen selten Rücksicht auf einheimische Ländereien oder Bräuche. Für die Tauren ist die Erde eine lebendige Mutter, die verehrt werden muss, und nicht ausgebeutet und ausgehöhlt für Steine und Metall."},{t="Verteidigung der heiligen Erde",b="Baine Bluthuf erkennt, dass die Zwergenmaschinerie und die unerbittlichen Sprengungen die zerbrechliche Harmonie der Ebenen bedrohen. Über die physische Zerstörung hinaus versetzt der Lärm die einheimische Tierwelt in Aufruhr und treibt die Kodos der Ebenen in Raserei. Indem sie die Werkzeuge der Prospektoren an deren eigenen Schmieden zerschlagen, hoffen die Tauren, eine deutliche Botschaft zu senden und das Vordringen aufzuhalten, bevor bleibender Schaden entsteht."}},faq={{q="Warum graben Zwerge in Mulgore?",a="Zwergenprospektoren glauben, dass tief in der Erde des zentralen Kalimdor verborgene Geheimnisse und Artefakte liegen. Ihre Missachtung des Stammesgebiets und ihre gewaltsamen Abbaumethoden haben sie jedoch in direkten Konflikt mit den Tauren gebracht.",al={"zwerge in mulgore","warum prospektoren hier sind","zwergenausgrabung mulgore"}},{q="Wer vergibt die Quest Zwergenbuddelei?",a="Die Quest wird von Baine Bluthuf vergeben, dem jungen Sohn von Oberhäuptling Cairne Bluthuf, der sich im Dorf der Bluthufe im Zentrum von Mulgore aufhält.",al={"questgeber zwergen-buddelei","wer startet zwergen-buddelei"}},{q="Warum möchte Baine, dass ihre Werkzeuge zerschlagen und nicht nur gestohlen werden?",a="Baine möchte die Ausrüstung völlig unbrauchbar machen, um die Ausgrabung unverzüglich zu stoppen. Die Zerstörung der Werkzeuge an den Schmieden sendet eine klare symbolische und praktische Botschaft, dass das Land seine Geheimnisse nicht durch rohe Gewalt und Entweihung preisgibt.",al={"warum spitzhacken zerbrechen","zwergenwerkzeuge zerschlagen"}},{q="Wie wirken sich die Grabungen auf die Tierwelt von Mulgore aus?",a="Die lauten Grabungen und das tiefe Aufreißen des Bodens bringen die einheimischen Kreaturen stark auf, insbesondere die massiven Kodos, die durch die Hügel streifen, wodurch friedliche Herden gereizt und aggressiv werden.",al={"wütende kodos","warum bestien wütend sind"}},{q="Wo können die Spitzhacken zerschlagen werden?",a="Die Spitzhacken können an jeder funktionierenden Schmiede zu Schrott gehämmert werden. Spieler können die Schmiede direkt im Ausgrabungslager der Zwerge nutzen oder sie zu den Schmieden in Donnerfels bringen.",al={"wo ist die schmiede","prospektorenspitzhacken an schmiede zerschlagen"}},{q="Hängt diese Quest mit der größeren Präsenz der Forscherliga in Kalimdor zusammen?",a="Ja. Zwergenexpeditionen aus Eisenschmiede haben überall in Kalimdor Außenposten errichtet, darunter in Mulgore, dem Brachland und Süd-Kalimdor, was häufig zu Scharmützeln mit Völkern der Horde um territoriale Souveränität und heilige Stätten führt.",al={"forscherliga mulgore","eisenschmiede in kalimdor"}}},fx={["755e231a"]={q="Wozu dienen die Zerbrochene Werkzeuge?",a="Die Zerbrochene Werkzeuge dienen als greifbarer Beweis dafür, dass Ihr die Operationen der Zwerge gestoppt habt. Anstatt die Goldsucher einfach zu vertreiben oder ihre Ausrüstung zu nehmen, möchte Baine Bluthuf, dass ihre Spitzhacken in einer Schmiede zerschlagen und zu ihm zurückgebracht werden, um sicherzustellen, dass ihre Arbeit eingestellt wird und ein deutliches Zeichen gegen die Entweihung der heiligen Erde gesetzt wird.",al={"zerbrochene werkzeuge","warum zerbrochene werkzeuge","zweck der zerbrochenen werkzeuge"}},["95107d94"]={q="Wer sind die Zwerge, die in Mulgore graben?",a="Es sind Zwergen-Goldsucher, die ein Ausgrabungslager in den nordwestlichen Hügeln von Mulgore errichtet haben. Angetrieben von Gerüchten, dass uralte Geheimnisse unter den Ebenen begraben liegen, suchen sie nach historischen Relikten und Titanenwissen, ohne sich um die spirituelle Entweihung zu scheren, die ihre Steinbrüche dem Land und seiner Tierwelt zufügen.",al={"zwerge in mulgore","wer sind die zwergengräber","goldsucher in mulgore"}}},fp="15,289,24.392.0,26.388.0,35.232.0,36.137.0,63.245.0,52.187.0,31.201.0,75.232.0"}
P.entries["quest:747"] = {n="Die Jagd beginnt",s="Die Jagd beginnt ist ein grundlegender Übergangsritus für junge Abenteurer in Camp Narache auf der Hochwolkenebene. Im Auftrag von Grull Falkenwind werden Initianden ausgesandt, um einheimische Ebenenschreiter zu jagen und das Dorf mit Fleisch und Federn zu versorgen. Die Erfüllung dieser Aufgabe markiert den ersten Schritt, um den Respekt von Häuptling Falkenwind zu erlangen und schließlich Einlass nach Donnerfels zu erhalten.",h="Die Jagd beginnt ist ein grundlegender Übergangsritus für junge Abenteurer in Camp Narache auf der...",kw={"camp narache","häuptling falkenwind","federn","grull falkenwind","die jagd beginnt","mulgore","ebenenschreiter","die hochwolkenebene"},ang={["class:Hunter"]="Das Nachstellen der flinken Ebenenschreiter der Hochwolkenebene dient als früheste praktische Übung in Treffsicherheit, Fährtenlesen und der Ehrerbietung gegenüber den Bestien, die Euer Überleben sichern.",["race:Tauren"]="Für junge Shu'halo ist das Erlegen Eurer ersten Ebenenschreiter auf der Mesa ein essenzieller Übergangsritus, der Euer Band mit dem Land und Eure Pflicht zur Ernährung von Camp Narache bekräftigt."},sec={{t="Der Lebensunterhalt eines Stammes",b="Auf den Höhen der Hochwolkenebene sind Überleben und Tradition eng miteinander verwoben. Die Tauren jagen aus Notwendigkeit, um ihr Volk zu ernähren und zu kleiden, betrachten das Pirschen und die Hetzjagd jedoch zugleich als unverzichtbare Prüfung von Disziplin und sportlichem Geschick. Wenn die Vorräte von Camp Narache zur Neige gehen, setzt die Gemeinschaft auf ihre heranwachsende Jugend, um frisches Ebenenschreiterfleisch zum Kochen und robuste Federn für Stammestrachten zu beschaffen."},{t="Anerkennung verdienen",b="Kein aufstrebender Held verlässt die Hochwolkenebene einfach so in die weiteren Weiten von Mulgore, ohne seinen Wert bewiesen zu haben. Grull Falkenwind dient den Neuankömmlingen als wichtigster Beurteiler ihres Charakters und besteht darauf, dass man seine Fähigkeiten unter Beweis stellt, bevor man vor seinen Vater, Häuptling Falkenwind, tritt. Eine saubere Jagd heimzubringen zeugt nicht nur von Eigenständigkeit, sondern auch von Hingabe zum Wohl des Stammes."}},faq={{q="Wer vergibt diese Quest?",a="Grull Falkenwind bietet diese Aufgabe in Camp Narache an. Er ist der Sohn des Dorfvorstehers, Häuptling Falkenwind, und fungiert als früher Mentor für junge Jäger und Abenteurer auf der Hochwolkenebene.",al={"questgeber","wer startet die jagd beginnt","grull falkenwind"}},{q="Warum werden Ebenenschreiter anstelle anderer Tiere gejagt?",a="Ebenenschreiter kommen auf der gesamten Mesa zahlreich vor und liefern sowohl nahrhaftes Fleisch zur Auffüllung schwindender Nahrungsvorräte als auch beständige Federn, die für traditionelle Taurenkleidung und Verzierungen verwendet werden.",al={"warum ebenenschreiter","ebenenschreiterfleisch und federn","ebenenschreiter jagen"}},{q="Warum muss ich mich beweisen, bevor ich Häuptling Falkenwind gegenübertrete?",a="Die Gesellschaft der Tauren legt großen Wert auf praktischen Nutzen und jagdliches Können. Grull Falkenwind verlangt von Initianden, grundlegende Überlebensfähigkeiten und Loyalität gegenüber dem Dorf zu demonstrieren, bevor ihnen eine Audienz und weiterreichende Pflichten durch den Häuptling gewährt werden.",al={"warum häuptling hawkwind beweisen","häuptling hawkwind anerkennung","warum zuerst jagen"}},{q="Was ist das übergeordnete Ziel dieser Prüfungen auf der Hochwolkenebene?",a="Die Mesa dient als Prüfstein. Sobald ein junger Tauren Häuptling Falkenwind und den Ältesten von Camp Narache seine Fähigkeiten bewiesen hat, gilt er als bereit, in die weiten Ebenen von Mulgore hinabzusteigen und die Hauptstadt Donnerfels zu betreten.",al={"zweck der mesa-prüfungen","warum bin ich auf der die hochwolkenebene","die hochwolkenebene verlassen"}},{q="Was kommt nach dieser Jagd?",a="Das erfolgreiche Zurückbringen des Fleisches und der Federn sichert Grulls Anerkennung und führt direkt zu 'Die Jagd geht weiter', wo Initianden größerem, schwerer fassbarem Wild auf der Mesa nachstellen.",al={"nächste quest","folgequest","was folgt nach die jagd beginnt"}},{q="Jagen Tauren nur zum Überleben?",a="Obgleich Nahrung und Ressourcen wie Leder, Knochen und Federn lebensnotwendig sind, pflegen Tauren die Jagd auch als sportliche Betätigung und spirituelle Einkehr, wodurch sie die Instinkte schärfen, die ihre Stämme wachsam und stark halten.",al={"jagdphilosophie der tauren","jagd zum sport","warum jagen tauren"}}},fx={["395288c5"]={q="Warum möchte Grull Falkenwind, dass dies erledigt wird?",a="Grull Falkenwind sieht Potenzial in Euch und möchte, dass Ihr Euren Wert vor dem Stamm und seinem Vater, Häuptling Falkenwind, beweist. Die Fleischvorräte von Camp Narache sind zur Neige gegangen und das Lager benötigt frische Federn. Indem er Euch aussendet, um sie zu ernten, testet er Euren Jagdinstinkt, während er gleichzeitig die lebensnotwendigen Vorräte des Dorfes wieder auffüllt.",al={"warum will grull ebenenschreiter jagen","beweggrund von grull falkenwind","warum ebenenschreiter für grull jagen"}},f26a5c4f={q="Wozu dient das Ebenenschreiterfleisch?",a="Das Fleisch wird gesammelt, um die schwindenden Nahrungsvorräte von Camp Narache wieder aufzufüllen. Das Überleben auf der Hochwolkenebene erfordert verlässliche Nahrung, und die Jagd auf Ebenenschreiter liefert das frische Fleisch, das benötigt wird, um die jungen Jäger und Ältesten im Lager zu ernähren.",al={"wofür wird ebenenschreiterfleisch benutzt","warum ebenenschreiterfleisch sammeln","nutzen von ebenenschreiterfleisch"}},fb1052a7={q="Wozu dient die Ebenenschreiterfeder?",a="Ebenenschreiterfedern werden von den Tauren von Camp Narache verwendet, um Kleidung und Schmuck herzustellen. Der Stamm verlässt sich auf jeden Teil der Tiere, die sie jagen, und verarbeitet robustes Gefieder zu praktischer Kleidung und Festtagsgewändern, die für das Leben auf der Mesa geeignet sind.",al={"wofür werden ebenenschreiterfedern benutzt","warum ebenenschreiterfedern sammeln","nutzen von ebenenschreiterfedern"}}},fp="15,361,20.383.0,19.382.0,21.181.0,53.182.0,59.252.0,59.239.0,27.181.0,33.203.0"}
P.entries["quest:748"] = {n="Vergiftetes Wasser",s="Vergiftetes Wasser leitet die Bemühungen der Tauren ein, die Verschmutzung der heiligen Brunnen von Mulgore zu beseitigen. Von Mull Donnerhorn im Dorf der Bluthufe beauftragt, sammeln junge Verteidiger der Horde natürliche Bestandteile aus den Ebenen, um ein wiederherstellendes Ritualtotem herzustellen.",h="Vergiftetes Wasser leitet die Bemühungen der Tauren ein, die Verschmutzung der heiligen Brunnen von Mulgore...",kw={"dorf der bluthufe","säuberungstotem","mulgore","mull donnerhorn","ebenenschreiter","vergiftetes wasser","präriewolf","brunnen der winterhufe"},ang={["class:Druid"]="Dass Goblins frische Quellen vergiften, stellt einen direkten Angriff auf das natürliche Gleichgewicht dar und erfordert eine sofortige Reaktion, um die empfindliche Flora und Fauna von Mulgore zu bewahren.",["class:Shaman"]="Die Wiederherstellung verschmutzter Gewässer durch mit Tierkräften erfüllte Totems veranschaulicht das Fundament des Taurenschamanismus: die Zusammenarbeit mit der einheimischen Tierwelt, um elementare Störungen zu heilen.",["race:Tauren"]="Die Schändung des frischen Wassers trifft den Kern der Gaben der Erdenmutter, weshalb das Reinigungsritual eine grundlegende Pflicht für jeden heranwachsenden Tauren in Mulgore darstellt."},sec={{t="Ein geschändetes Land",b="Die grasbewachsenen Ebenen von Mulgore sind den Tauren ein heiliges Land, doch tückische Mächte haben begonnen, ihr lebenswichtiges Lebenselixier zu bedrohen. Mull Donnerhorn, ein im Dorf der Bluthufe stationierter Ältester, entdeckt, dass Goblin-Eindringlinge und ihre Handlanger die kostbaren Wasserbrunnen verunreinigt haben, die die Stämme und die einheimische Tierwelt ernähren. Die Verschmutzung trifft das geistige Herz des nomadischen Volkes, das sich vor Kurzem hier niedergelassen hat, bis ins Mark."},{t="Das Sammeln der Essenz der Natur",b="Um industriellen Schadstoffen entgegenzuwirken, vertraut Mull auf den traditionellen Schamanismus der Tauren statt auf primitive Heilmittel. Die Reinigung des Brunnens der Winterhufe erfordert die Herstellung eines mächtigen Ritualtotems, das mit der Lebenskraft der einheimischen Raubtiere Mulgores erfüllt ist. Er schickt Jäger aus, um in den südwestlichen Ebenen Präriewölfe wegen ihrer Pfoten und ausgewachsene Ebenenschreiter wegen ihrer Krallen aufzuspüren, und nutzt so die Stärke des Landes, um seine eigenen Wunden zu heilen."}},faq={{q="Wer hat die Wasserbrunnen in Mulgore vergiftet?",a="Goblin-Eindringlinge und ihre Mietlinge sind für die Verunreinigung der heiligen Wasserstellen in ganz Mulgore verantwortlich. Ihre zerstörerischen industriellen Aktivitäten und ihre Missachtung des natürlichen Gleichgewichts bedrohen sowohl die Taurenstämme als auch die örtliche Tierwelt.",al={"wer hat die brunnen verunreinigt","wer hat mulgore vergiftet","wer hat das wasser verschmutzt"}},{q="Warum benötigt Mull Donnerhorn Wolfspfoten und Ebenenschreiterkrallen?",a="Mull stellt traditionelle Säuberungstotems aus Teilen einheimischer Bestien Mulgores her. Indem er sich die innewohnenden Geister und die Stärke der Raubtiere der Ebenen zunutze macht, erschafft er einen Fokus, der mächtig genug ist, um ein Wasserreinigungsritual durchzuführen.",al={"warum wolfspfoten","warum ebenenschreiterkrallen","totemmaterialien"}},{q="Auf welchen Brunnen bereitet diese Quest die Reinigung vor?",a="Diese Aufgabe beschafft gezielt Materialien, um das Säuberungstotem für den Brunnen der Winterhufe herzustellen – den ersten in einer Reihe verschmutzter Brunnen, die eine rituelle Reinigung erfordern.",al={"für welchen brunnen ist das","welcher wasserbrunnen"}},{q="Wo befindet sich Mull Donnerhorn?",a="Mull Donnerhorn hält sich im Dorf der Bluthufe auf, der wichtigsten Taurensiedlung im Zentrum von Mulgore an den Ufern des Stonebullsees.",al={"mull donnerhorn standort","wo ist mull","wo vergiftetes wasser abgeben"}},{q="Wo sind die benötigten Wölfe und Ebenenschreiter zu finden?",a="Präriewölfe und erwachsene Ebenenschreiter durchstreifen die wogenden Ebenen südwestlich des Dorfes der Bluthufe.",al={"wo präriewölfe finden","ebenenschreiter standort","jagdgründe"}},{q="Was geschieht, nachdem Mull die Pfoten und Krallen erhalten hat?",a="Mull fügt die gesammelten Bestandteile zu einem Läuterungstotem der Winterhufe zusammen und beauftragt Euch damit, es direkt zum Brunnen der Winterhufe zu tragen, um den Reinigungsritus durchzuführen.",al={"folgequest nach vergiftetes wasser","was mache ich als nächstes"}}},fx={["50414ce1"]={q="Warum möchte Mull Donnerhorn, dass dies erledigt wird?",a="Goblins und ihre Handlanger haben die heiligen Wasserbrunnen in ganz Mulgore vergiftet und treffen damit die Lebensader der Heimat der Tauren. Für Mull Donnerhorn und die Bewohner des Dorfes der Bluthufe lädt das Belassen der Brunnen in diesem Zustand Krankheit ein und entweiht das heilige Gleichgewicht der Erde. Sie zu reinigen ist eine dringende spirituelle und praktische Pflicht.",al={"beweggrund von mull donnerhorn","warum wasserbrunnen reinigen","warum quest poison water"}}},fp="12,238,17.428.0,26.435.0,40.234.0,65.236.0,46.172.0,34.141.0,58.96.0,53.172.0"}
P.entries["quest:749"] = {n="Die Überfallene Karawane",s="Morin Wolkenpirscher weist Reisende an, die Trümmer einer überfallenen Karawane der Venture Company nahe dem Nordufer des Stonebullsees zu untersuchen. Obwohl die Tauren den Konvoi als Vergeltung für gefallene Kameraden in Brand steckten, kehrten Bergungsarbeiter der Goblins zurück, um intakte Fracht zu bergen. Die Untersuchung der überlebenden Versorgungskisten offenbart das wahre industrielle Ausmaß der Operationen der Venture Company in Mulgore.",h="Morin Wolkenpirscher weist Reisende an, die Trümmer einer überfallenen Karawane der Venture Company nahe dem...",kw={"morin wolkenpirscher","mulgore","überfallene karawane","stonebullsee","vorratskiste","venture co","venture company"},ang={["faction:Horde"]="Die ungehinderte Ausbreitung dieses Konzerns in Mulgore bedroht die Stabilität von Donnerfels und zwingt die Späher der Horde dazu, die Logistik der Venture Company zu stören.",["profession:Mining"]="Die robusten Kisten und Logistiknotizen belegen die aggressiven Mineralienvermessungs- und Abbauoperationen, die von der Venture Company in ganz Mulgore betrieben werden.",["race:Tauren"]="Die Schändung der Ebenen durch die Maschinen und Rodungen der Venture Company trifft Eure angestammte Heimat unmittelbar, weshalb die Sicherstellung und Zerstörung ihrer Vorräte für die Verteidigung von Mulgore unerlässlich ist."},sec={{t="Vergeltung am See",b="Die verkohlten Überreste am Nordufer des Stonebullsees sind das Ergebnis eines schnellen Angriffs der Tauren. In Trauer um zwei Gefährten, die bei einem früheren Scharmützel getötet wurden, überfielen Morin Wolkenpirscher und seine Krieger einen bewaffneten Nachschubkonvoi der Venture Company. In der Absicht, das Vorhaben der Eindringlinge zu vernichten, steckten die Tauren die Wagen in Brand und verließen die rauchenden Trümmer in der Annahme, das Feuer würde alles verzehren, was die Goblins transportieren wollten."},{t="Unerledigte Angelegenheiten",b="Die Tauren bemerkten bald, dass Bergungsarbeiter der Venture Company die geschwärzten Trümmer durchsuchten, was darauf hindeutete, dass ihr Feuer die wichtigste Fracht nicht vernichtet hatte. Anstatt blind weitere Leben zu riskieren, schickt Morin Späher aus, um das Wrack zu inspizieren. Inmitten der rußgeschwärzten Trümmer liegen intakte Kisten mit den Insignien der Venture Company Mining Division, gepackt und bestimmt für zentrale Verarbeitungsanlagen."}},faq={{q="Warum wurde die Karawane zerstört?",a="Morin Wolkenpirscher und seine Taurenkrieger lauerten der Karawane auf und steckten sie in Brand – als Vergeltung dafür, dass sie bei einem früheren Zusammenstoß mit der Venture Company zwei ihrer Späher verloren hatten.",al={"wer hat die karawane zerstört","warum brennt die karawane","angriff auf karawane"}},{q="Wo befindet sich die Überfallene Karawane?",a="Die ausgebrannten Wagen befinden sich am Nordufer des Stonebullsees, östlich des Dorfes der Bluthufe in Mulgore.",al={"karawane standort","wo ist die karawane","ort der überfallenen karawane"}},{q="Warum kehren die Goblins zu den Trümmern zurück?",a="Die Venture Company schickte Bergungsarbeiter, da das Feuer nicht ihre gesamte Ladung zerstören konnte. Sie versuchen, robuste Versorgungskisten zu bergen, die für den Weitertransport zu ihren zentralen Verarbeitungsbetrieben gestempelt sind.",al={"warum sind bergungsarbeiter hier","venture co bergungsarbeiter","was wollen die goblins"}},{q="Was befindet sich in den Versorgungskisten?",a="Die Kisten tragen die Insignien der Venture Company Mining Division und enthalten Bodenschätze, die für die Veredelung und Verarbeitung in ihren primären Industrieanlagen gekennzeichnet sind.",al={"kisteninhalt","was ist in der kiste","versiegelte versorgungskiste"}},{q="Wer ist Morin Wolkenpirscher?",a="Morin Wolkenpirscher ist ein Späher und Fährtenleser der Tauren, der östlich des Dorfes der Bluthufe stationiert ist und den Auftrag hat, feindliche Übergriffe im zentralen Mulgore, insbesondere durch die Venture Company, zu überwachen.",al={"wer ist morin","morin wolkenpirscher rolle"}},{q="Was enthüllt diese Karawane über die Venture Company?",a="Sie zeigt, dass die Präsenz der Venture Company in Mulgore kein bloßer Erkundungstrupp ist, sondern ein organisierter industrieller Abbau mit bewaffneten Versorgungslinien und zentralisierten Veredelungsnetzwerken.",al={"venture co präsenz mulgore","warum sind goblins in mulgore"}}},fx={["89fc7cfd"]={q="Warum möchte Morin Wolkenpirscher, dass die Karawanenkisten untersucht werden?",a="Morin und seine Krieger haben den Karawanen-Konvoi der Venture Company beim Stonebullsee überfallen, um gefallene Kameraden zu rächen, die Wagen verbrannt und angenommen, dass das Feuer alles Nützliche vernichten würde. Dass Goblins als Plünderer in den Trümmern wühlten, machte ihn darauf aufmerksam, dass etwas Wertvolles oder Gefährliches die Flammen überlebt haben musste. Er braucht Euch, damit Ihr die Kisten untersucht und erfahrt, was die Venture Company durch Mulgore transportierte und warum sie so begierig darauf ist, es zurückzuholen.",al={"warum karawane untersuchen","beweggrund von morin wolkenpirscher","warum lieferkisten durchsuchen"}}},fp="19,390,23.438.0,19.408.0,30.169.0,37.102.0,46.197.0,33.171.0,26.190.0,56.201.0"}
P.entries["quest:7493"] = {n="Die Reise beginnt erst",s="„Die Reise beginnt erst“ ist eine Quest der Horde, die nach der Niederlage von Onyxia in Orgrimmar für erfahrene Lederverarbeiter angeboten wird. Oberanführer Runthak erkennt das Handwerk des Helden an und vermittelt die seltene Technik, die erforderlich ist, um schützende Umhänge aus den Schuppen der Brutmutter zu fertigen. Dieses lebenswichtige Handwerk bereitet die Horde auf die tödlichen Flammen der Schwarzfelsspitze vor.",h="„Die Reise beginnt erst“ ist eine Quest der Horde, die nach der Niederlage von Onyxia in Orgrimmar für...",kw={"schwarzfels","brutmutter","umhang","lederverarbeitung","runthak","nefarian","onyxia","schuppe"},ang={["faction:Horde"]="Für die Horde ist die Beschaffung schützender Ausrüstung, die aus ihren gefallenen Feinden geschmiedet wird, von entscheidender Bedeutung, um ihre Streitkräfte vor weiteren drakonischen Verheerungen zu bewahren."},sec={{t="Das Vermächtnis einer Brutmutter",b="Der Fall von Onyxia stellt einen Triumph für die Horde dar, markiert jedoch nicht das Ende der Bedrohung, die vom Schwarzen Drachenschwarm ausgeht. Die geschuppte Haut der Brutmutter besitzt eine bemerkenswerte Widerstandskraft gegen drakonische Flammen. Anstatt solche Materialien verkommen zu lassen, sucht die Führung der Horde nach Handwerkern, die in der Lage sind, die Überreste des Drachen in defensive Rüstung zu verwandeln."},{t="Schild gegen Schattenflamme",b="Oberanführer Runthak lehrt begabte Lederverarbeiter, wie man den Onyxiaschuppenumhang zusammennäht. Dieses Wissen ist nicht bloß für Schau oder Prestige gedacht. Tief im Schwarzfels verfügt Onyxias Bruder Nefarian über einen verheerenden, sengenden Atem. Ohne den verzauberten Schutz, den die eigenen Schuppen ihrer Brutmutter bieten, würde jede Vorhut, die sich The Lord of Blackrock stellt, zu Asche verbrannt werden."}},faq={{q="Wer bietet diese Quest an und wo befindet sich die Person?",a="Die Quest wird von Oberanführer Runthak in Orgrimmar vergeben. Er erkennt Champions der Horde an, die über meisterhafte Fertigkeiten in der Lederverarbeitung verfügen und zum Sturz von Onyxia beigetragen haben.",al={"runthak questgeber","wo ist oberanführer runthak","queststart"}},{q="Welche Voraussetzung ist nötig, um diese Quest zu erhalten?",a="Diese Quest wird nur erfahrenen Lederverarbeitern angeboten, welche die triumphale Zeit nach Onyxias Niederlage abgeschlossen haben, wie etwa „Victory for the Horde“ oder „A Most Puzzling Circumstance“.",al={"lederverarbeitung voraussetzung","wie man quest erhält","voraussetzungen"}},{q="Was lehrt Oberanführer Runthak?",a="Oberanführer Runthak unterweist den Lederverarbeiter in der Technik, die erforderlich ist, um den Onyxiaschuppenumhang aus Schuppen herzustellen, die von der gefallenen Brutmutter erbeutet wurden.",al={"questbelohnung rezept","onyxiaschuppenumhang muster","was lerne ich"}},{q="Warum ist der Onyxiaschuppenumhang wichtig?",a="Der Umhang schützt seinen Träger vor dem tödlichen, sengenden Atem von Nefarian, The Lord of Blackrock. Ohne seine einzigartigen schützenden Eigenschaften würde sich die Konfrontation mit dem Meister der Brut als tödlich erweisen.",al={"warum umhang herstellen","zweck des umhangs","nefarian umhang"}},{q="Wer ist The Lord of Blackrock?",a="The Lord of Blackrock ist Nefarian, ein mächtiger schwarzer Drache und Onyxias Bruder, der von den Höhen des Schwarzfels aus Pläne schmiedet, um die sterblichen Völker zu unterwerfen.",al={"wer ist the lord of blackrock","nefarian identität","blackrock lord"}},{q="Warum besagt die Quest, dass die Reise erst begonnen hat?",a="Obwohl Onyxia getötet wurde, ist der größere Krieg gegen den Schwarzen Drachenschwarm und Nefarians Machenschaften im Schwarzfels nur weiter eskaliert.",al={"bedeutung des titels","warum reise erst begonnen"}}},fx={cb1b5404={q="Warum möchte Oberanführer Runthak dies erledigt haben?",a="Oberanführer Runthak strebt die vollständige Vernichtung des Schwarzen Drachenschwarms an. Zwar war Onyxias Niederlage ein gewaltiger Triumph, doch ihre Brut sucht das Reich unter dem Befehl ihres Bruders Nefarian noch immer heim. Indem er die uralte Technik lehrt, schützende Umhänge aus den Schuppen der Brutpflegerin zu schmieden, stellt Runthak sicher, dass die Streiter der Horde über die lebenswichtige Verteidigung verfügen, die erforderlich ist, um Nefarians tödlicher Schattenglamme standzuhalten und den Krieg zu beenden.",al={"warum gibt runthak diese quest","oberanfuehrer runthak motiv","runthak ziel"}}},fp="26,347,22.359.0,27.396.1,49.178.0,49.183.0,33.152.0,40.186.0,29.159.0,57.145.0"}
P.entries["quest:7497"] = {n="Die Reise beginnt erst",s="Diese Quest stellt die hart verdiente Anerkennung eines erfahrenen Handwerkers nach dem Sieg über Onyxia dar. Major Mattingly vermittelt die entscheidende Technik, die zur Herstellung eines Onyxiaschuppenumhangs erforderlich ist, wodurch die sterblichen Überreste der gefallenen Brutpflegerin zu einem unverzichtbaren Schutz gegen ihren Bruder werden.",h="Diese Quest stellt die hart verdiente Anerkennung eines erfahrenen Handwerkers nach dem Sieg über Onyxia dar.",kw={"schwarzer drachenschwarm","der blackrock","lederverarbeitung","major mattingly","nefarian","onyxia","onyxiaschuppenumhang","sturmwind"},ang={["faction:Alliance"]="Diese Quest schlägt eine Brücke zwischen Sturmwinds hart erkämpftem Sieg über Onyxia und der bevorstehenden Offensive gegen ihren Bruder Nefarian im Schwarzfels."},sec={{t="Eine seltene Meisterschaft",b="Während viele Recken für sich beanspruchen können, die Brutpflegerin Onyxia niedergestreckt zu haben, besitzen nur sehr wenige sowohl kriegerische Schlagkraft als auch das meisterhafte Lederverarbeitungsgeschick, um ihre gewaltige Haut zu bearbeiten. Wenn ein Held mit solch vereinten Talenten bei Major Mattingly in Sturmwind vorstellig wird, erkennt der Offizier an, wie unverzichtbar diese Handwerkskünste für die bevorstehenden Schlachten sind."},{t="Schutz gegen den Schwarzen Drachenschwarm",b="Der Tod von Onyxia beendet die Bedrohung durch den Schwarzen Drachenschwarm nicht. Mattingly lehrt den Handwerker, wie man die Schuppen der Brutpflegerin behandelt und zu einem Onyxiaschuppenumhang zusammennäht. Dieses einzigartige Gewand bietet spezialisierten Schutz gegen den verheerenden, brandstiftenden Atem von Onyxias Bruder, Nefarian, dem Herrscher des Schwarzfels."}},faq={{q="Wer bietet die Quest Die Reise beginnt erst an?",a="Major Mattingly in Sturmwind bietet diese Quest Helden der Allianz an, die sich im Feldzug gegen Onyxia bewiesen haben und über meisterhafte Lederverarbeitung verfügen.",al={"wer gibt die reise beginnt erst","wo bekommt man die reise beginnt erst","die reise beginnt erst questgeber"}},{q="Was lehrt diese Quest?",a="Der Abschluss dieser Interaktion lehrt Meisterlederverarbeiter das Rezept zur Herstellung des Onyxiaschuppenumhangs, eines Gegenstands, der speziell aus Onyxias Schuppen gefertigt wird.",al={"welches rezept bekommt man","onyxiaschuppenumhang rezept","belohnung für die reise beginnt erst"}},{q="Warum ist der Onyxiaschuppenumhang notwendig?",a="Der Umhang ist speziell behandelt, um Träger vor dem tödlichen, brandstiftenden Atem von Nefarian, dem Herrscher des Schwarzfels, zu schützen, was ihn im Kampf gegen die verbliebenen Anführer des Schwarzen Drachenschwarms unverzichtbar macht.",al={"warum braucht man onyxiaschuppenumhang","wofür ist onyxiaschuppenumhang","schattenflammenschutz"}},{q="Wer ist der von Major Mattingly erwähnte Herrscher des Schwarzfels?",a="Der Herrscher des Schwarzfels ist Nefarian, ein mächtiger schwarzer Drache und der Bruder von Onyxia. Er herrscht über die Schwarzfelsspitze und setzt die Ränke des Schwarzen Drachenschwarms fort.",al={"wer ist der herrscher von blackrock","wer ist nefarian","mattingly drachenwarnung"}},{q="Warum muss der Held ein Lederverarbeiter sein, um dieses Wissen zu erhalten?",a="Die Techniken, die erforderlich sind, um Drachenschuppen zu gewinnen, zu härten und zu vernähen, ohne ihren angeborenen magischen Schutz zu zerstören, verlangen das fortgeschrittene Fachwissen eines erfahrenen Meisterlederverarbeiters.",al={"warum nur lederverarbeitung","kann jeder diese quest annehmen","lederverarbeitung voraussetzung"}},{q="Beseitigt Onyxias Tod die Bedrohung durch die schwarzen Drachen in Sturmwind?",a="Nein. Obwohl Onyxia selbst bezwungen wurde, beherrscht ihr Bruder Nefarian noch immer den Schwarzfels und schmiedet weiterhin Pläne gegen die Allianz und die sterblichen Völker.",al={"ist sturmwind jetzt sicher","onyxia tot was nun","schwarzer drachenschwarm nach onyxia"}}},fx={b42a6800={q="Warum bietet Euch Major Mattingly dieses Wissen an?",a="Major Mattingly weiß, dass das Töten von Onyxia nur der erste Schlag war. Die Brutmutter ist tot, aber ihre Verwandten bedrohen Azeroth immer noch von den Höhen des Schwarzfels. Um den verbleibenden Schwarzer Drachenschwarm zu eliminieren, müssen Champions die sengenden Flammen von Nefarian selbst überleben. Mattingly teilt diese spezielle Technik, damit die Helden der Allianz schützende Umhänge aus Onyxias Schuppen anfertigen und den Krieg beenden können.",al={"warum bringt mattingly es euch bei","beweggrund von major mattingly","grund von mattingly"}}},fp="26,138,14.214.0,41.241.1,48.138.0,27.101.0,40.99.0,58.153.0,63.118.0,65.131.1"}
P.entries["quest:75"] = {n="Die Legende von Stalvan",s="Diese Untersuchung zu Stalvan Dunstmantel führt aus dem Dämmerwald zu einem abgelegenen Haus im südöstlichen Wald von Elwynn. Marshal Haggard, ein gealterter Veteran, dessen Sehvermögen nachgelassen hat, weist Euch auf eine Truhe im Obergeschoss hin, die ein altes Bündel Papiere enthält, das zurückblieb, als er dort einzog.",h="Diese Untersuchung zu Stalvan Dunstmantel führt aus dem Dämmerwald zu einem abgelegenen Haus im südöstlichen...",kw={"dämmerwald","wald von elwynn","verblasste tagebuchseite","unglückseliger geist","marshal haggard","stalvan"},ang={["faction:Alliance"]="Die Aufdeckung von Stalvans Vermächtnis legt dunkle Kapitel offen, die still innerhalb der ansonsten friedlichen, ländlichen Grenzen von Elwynn verborgen liegen.",["race:Human"]="Stalvans Pfad schlängelt sich durch gewöhnliche Siedlungen der Menschen und dient als warnendes Beispiel für Isolation und Bosheit, die ganz offen verborgen liegen."},sec={{t="Der Dachboden eines Veteranen",b="Marshal Haggard lebt weit ab der Stadt an den südöstlichen Rändern des Wald von Elwynn, nahe der Grenzen zum Dämmerwald und dem Rotkammgebirge. Als er in sein abgeschiedenes Heim zog, fand er im Obergeschoss eine versteckte Truhe voller alter Pergamente. Da sich sein Sehvermögen trübte, gab er jeden Versuch auf, sie zu lesen, und ließ die Dokumente unberührt, bis ein Ermittler kommt, der nach Stalvan fragt."},{t="Lauernde Schatten",b="Die Papiere in der Truhe im Obergeschoss sind kein gewöhnlicher Haushaltsmüll. Das Stören von Stalvans Habseligkeiten bringt regelmäßig ruhelose Magie in Wallung und beschwört einen Unglückseligen Geist herauf, der an Dunstmantels Vergangenheit gebunden ist. Die darin versteckte Tagebuchseite liefert eine direkte Aufzeichnung von Stalvans privaten Schriften und bietet konkrete Beweise dafür, dass der zurückgezogen lebende Gelehrte seine Spuren im Wald von Elwynn hinterließ, bevor er verschwand."}},faq={{q="Wer ist Marshal Haggard?",a="Marshal Haggard ist ein älterer, nahezu blinder Veteran, der ruhig in einer abgelegenen Hütte im südöstlichen Wald von Elwynn lebt. Er bewahrt lang vergessene Papiere auf, die er in seinem Haus entdeckte und die Stalvan Dunstmantel gehörten.",al={"marshal haggard","haggard elwynn","wer ist haggard"}},{q="Warum führte die Spur zurück in den Wald von Elwynn?",a="Hinweise aus Dunkelhain und Mondbruch zeichnen Stalvans Wanderungen durch das südliche Gebiet von Sturmwind nach. Haggards Gehöft enthielt alte Papiere, die Stalvan zurückließ.",al={"warum wald von elwynn","stalvan elwynn","warum zu haggard gehen"}},{q="Was befindet sich in der Truhe im Obergeschoss?",a="Die Truhe enthält eine verblasste Tagebuchseite, die von Stalvan Dunstmantel geschrieben wurde, bewahrt in einem Bündel Pergamente, die Haggard nie richtig untersuchen konnte.",al={"truhe im obergeschoss","verblasste tagebuchseite","was ist in der truhe"}},{q="Warum greift ein Geist an, wenn die Truhe geöffnet wird?",a="Ein Unglückseliger Geist sucht die Relikte von Stalvans ehemaligem Leben heim und manifestiert sich gewaltsam, wenn ein Außenstehender seine persönlichen Schriften und Erinnerungen stört.",al={"unglückseliger geist","warum greift geist an","geist in haggards haus"}},{q="Wie bringt dies die Ermittlung zu Stalvan voran?",a="Die verblasste Seite liefert Beweise aus erster Hand in Stalvans eigener Handschrift und hilft dabei, die Geschichte seiner Vergangenheit zusammenzusetzen.",al={"stalvans geheimnis","was enthüllt die seite","schritt der stalvan-questreihe"}},{q="Warum konnte Marshal Haggard die Papiere nicht selbst lesen?",a="Haggards Augenlicht ist mit dem Alter trüb und schwach geworden, was ihn daran hindert, die kleine oder verwitterte Handschrift auf den verblassten Dokumenten zu entziffern.",al={"haggard blind","warum braucht haggard hilfe"}}},fx={["7284e072"]={q="Warum möchte Marshal Haggard, dass dies erledigt wird?",a="Marshal Haggard ist ein alter Soldat, der im ruhigen Ruhestand lebt, aber er trägt immer noch die Instinkte eines Offiziers des Reiches in sich. Als Ihr kommt, um die Wahrheit über Stalvan Dunstmantel zu erfahren, erinnert er sich an die weggeworfenen Pergamente, die in der Truhe lagen, als er das Haus übernahm. Obwohl er kein persönliches Interesse an dem dunklen Geheimnis hat, möchte er Eure Ermittlungen so gut er kann unterstützen – auch wenn sein nachlassendes Augenlicht ihn daran hindert, die Papiere selbst zu untersuchen.",al={"warum haggard helfen","beweggrund von marshal haggard","warum will haggard das journal"}}},fp="21,280,17.391.0,17.382.1,23.216.0,45.162.0,34.157.0,50.144.0,48.111.1,53.140.0"}
P.entries["quest:750"] = {n="Die Jagd geht weiter",s="The Hunt Continues ist ein früher Übergangsritus, der von Grull Falkenwind in Camp Narache vergeben wird. Er trägt angehenden Jägern auf, Bergcougarpelze aus den südlichen Hügeln zu sammeln, um die Kinder des Stammes einzukleiden und ihre Zelte auszubessern.",h="The Hunt Continues ist ein früher Übergangsritus, der von Grull Falkenwind in Camp Narache vergeben wird.",kw={"camp narache","häuptling falkenwind","grull falkenwind","bergcougarpelze","die hochwolkenebene","tauren-jagd","the hunt continues"},ang={["class:Hunter"]="Diese Aufgabe bekräftigt die zentrale Jagdphilosophie der Ebenen: Tiere zielgerichtet zu erlegen, nur das zu nehmen, was benötigt wird, und Tiere niemals als einfachen Sport oder Trophäen zu betrachten.",["race:Tauren"]="Für junge Tauren beim Coming of Age auf der Hochwolkenebene ist das Lernen, dass jeder Teil einer Bestie dem Stamm dienen muss – von Nahrung über Kleidung bis hin zu Unterkünften –, ein wesentlicher Übergangsritus."},sec={{t="Der Zweck der Jagd",b="In Camp Narache wird jungen Jägern beigebracht, dass das Erlegen einer Bestie niemals ein müßiger Zeitvertreib oder eine Suche nach Trophäen ist. Grull Falkenwind trägt angehenden Abenteurern auf, sich in die südlichen Hügel der Hochwolkenebene zu wagen, um Bergcougars aufzuspüren. Anstatt nur kriegerisches Können zu beweisen, betont die Aufgabe die Verantwortung gegenüber der Gemeinschaft und zeigt, dass wahre Jäger lebenswichtige Vorräte für ihr Volk beschaffen müssen."},{t="Unterkunft für den Stamm",b="Das Leben auf der Hochebene erfordert strapazierfähige Materialien, um den offenen Elementen zu trotzen. Grull erklärt, dass die Cougarfelle dringend benötigt werden, um Kleidung für die Kinder des Stammes zu nähen und abgenutzte Fellzelte in ganz Camp Narache auszubessern. Sich als fähig zu erweisen, diese geschätzten Pelze zu beschaffen, bringt die Dankbarkeit der Ältesten ein, und Grull verspricht, seinem Vater, Häuptling Falkenwind, direkt von den selbstlosen Beiträgen des Jägers zu berichten."}},faq={{q="Warum braucht der Stamm Bergcougarpelze?",a="Die Pelze der Bergcougars sind lebenswichtige praktische Ressourcen für Camp Narache. Grull Falkenwind erklärt, dass die Felle benötigt werden, um warme Kleidung für die Kinder des Stammes herzustellen und die Zelte des Dorfes zu reparieren und zu verstärken.",al={"warum cougars jagen","wofür cougarpelze sind","verwendung von bergcougarpelzen"}},{q="Wer bietet diese Quest an?",a="Die Jagd wird von Grull Falkenwind vergeben, einem prominenten Jäger in Camp Narache und dem Sohn von Häuptling Falkenwind. Er leitet unerfahrene Abenteurer an, die wesentlichen Pflichten zur Unterstützung der Siedlung zu erlernen.",al={"wer vergibt the hunt continues","questgeber camp narache"}},{q="Wo sind die Bergcougars zu finden?",a="Die Bergcougars streifen durch die felsigen Kämme und sanften Hügel direkt südlich von Camp Narache auf der Hochwolkenebene.",al={"wo sind die cougars","standort der bergcougars","wo man bergcougars findet"}},{q="In welcher Verbindung steht Grull Falkenwind zu Häuptling Falkenwind?",a="Grull Falkenwind ist der Sohn von Häuptling Falkenwind, dem Stammesführer in Camp Narache. Grull verspricht, in Eurem Namen mit seinem Vater zu sprechen und von Euren großzügigen Taten zu berichten, wenn Ihr die benötigten Pelze beschafft.",al={"wie man häuptling falkenwind beeindruckt","sohn von häuptling falkenwind"}},{q="Was lehrt diese Jagd über die Tradition der Tauren?",a="Unter den Tauren wird die Jagd niemals als Sport oder Trophäenjagd behandelt. Jedes dem Land entnommene Tier soll die Gemeinschaft ernähren und die Ebenen ehren, indem Fell, Fleisch und Knochen genutzt werden, um das Überleben des Stammes zu sichern.",al={"jagdphilosophie der tauren","warum in mulgore jagen"}},{q="Warum gelten Bergcougarpelze als hochgeschätzt?",a="Cougarpelze sind dick, strapazierfähig und gut geeignet, um den Elementen auf den windgepeitschten Ebenen zu trotzen. Da sie kleinen Kindern Wärme spenden und als Material stark genug sind, um Behausungen auszubessern, werden sie von den Dorfältesten geschätzt.",al={"sind cougarpelze wertvoll","warum cougarpelze geschätzt werden"}}},fp="18,230,23.420.0,21.427.0,46.228.0,22.197.0,37.124.0,54.202.0,49.220.0,55.228.0"}
P.entries["quest:751"] = {n="Die Überfallene Karawane",s="Die Untersuchung eines zerstörten Transports in Mulgore enthüllt, dass goblinische Industrielle einen illegalen Stützpunkt im Gebiet der Tauren errichtet haben. Durch die Sicherstellung von Dokumenten aus einer versiegelten Kiste bestätigen Späher, dass die Venture Company systematisch den mineralischen Reichtum des Landes ausbeutet. Diese Entdeckung veranlasst die Späher der Bluthufe dazu, eine aktive Verteidigung ihrer angestammten Ebenen zu organisieren.",h="Die Untersuchung eines zerstörten Transports in Mulgore enthüllt, dass goblinische Industrielle einen...",kw={"dorf der bluthufe","morin wolkenpirscher","mulgore","späher","überfallene karawane","vorratskiste","venture company","dokumente der venture company"},ang={["class:Druid"]="Druiden halten das Gleichgewicht des Landes für heilig, was den zerstörerischen, raucherfüllten Tagebau der Venture Company zu einer Schändung macht, die gereinigt werden muss.",["faction:Horde"]="Die Horde verlässt sich auf die Loyalität und Stabilität von Mulgore; fremde Handelskartelle gewähren zu lassen, die Hügel zu verwüsten, würde die Sicherheit von Donnerfels selbst gefährden.",["profession:Mining"]="Die hochwertigen Erze, die in der Kiste verpackt sind, beweisen, dass die östlichen Hügel von Mulgore reiche unterirdische Adern verbergen, die von Außenstehenden hastig ausgebeutet werden.",["race:Tauren"]="Für die Tauren ist der Anblick grober Industriemaschinen, die sich in die angestammten Ebenen von Mulgore fressen, eine Beleidigung der Erdenmutter und ein Akt der Aggression gegen ihren neu gewonnenen Frieden."},sec={{t="Beweis der Ausbeutung",b="Das Wrack einer Überfallenen Karawane östlich des Dorfes der Bluthufe erzählt eine beunruhigende Geschichte. In einer versiegelten Vorratskiste befindet sich ein dichtes Depot von abgebautem Erz und Mineralien neben einem gebundenen Bündel von Dokumenten der Venture Company. Dieser Papierkram liefert unwiderlegbare Beweise dafür, dass die gierige Venture Company mit einem unerlaubten Bergbaubetrieb tief in den friedlichen Tälern von Mulgore begonnen hat."},{t="Die Wachsamkeit der Späher",b="Morin Wolkenpirscher und seine Mitstreiter, die Späher, haben ein wachsames Auge auf die Grenzen von Mulgore gehalten, eingedenk fremder Fraktionen, die ihre friedliche Heimat ausbeuten wollen. Die Übergabe der geborgenen Dokumente bestätigt Morins schlimmste Befürchtungen: Rauch, der über den östlichen Ausläufern aufsteigt, signalisiert eine eskalierende kommerzielle Invasion. Den Tauren bleibt keine andere Wahl, als gegen die Schänder vorzugehen, bevor ihre Hügel vollständig ausgehöhlt werden."}},faq={{q="Was befindet sich in der versiegelten Vorratskiste?",a="Das Aufbrechen der Kiste enthüllt eine gepackte Auswahl an abgebautem Erz, Rohmineralien und einem Bündel von Dokumenten der Venture Company, die deren Operationen darlegen.",al={"beute aus vorratskiste","was ist in der kiste","inhalt der kiste"}},{q="Wer ist Morin Wolkenpirscher?",a="Morin Wolkenpirscher ist ein Späher der Tauren, der an der Straße östlich des Dorfes der Bluthufe in Richtung der Grenze zum Brachland stationiert ist und damit beauftragt wurde, Mulgore zu patrouillieren und fremde Bedrohungen aufzuspüren.",al={"wer ist morin","rolle von morin wolkenpirscher","späher morin"}},{q="Warum ist die Venture Company in Mulgore?",a="Die Venture Company versucht rücksichtslos, die reichen natürlichen Ressourcen und mineralischen Erzadern von Mulgore auszubeuten, indem sie sich ohne Rücksicht auf die Erde oder ihre einheimische Bevölkerung in die Hügel gräbt.",al={"warum sind goblins hier","ziel der venture company in mulgore","was wollen die goblins"}},{q="Woher kam die Karawane?",a="Die Karawane gehörte der Venture Company und transportierte abgebautes Erz und operative Unterlagen von ihren Betrieben in den Ausläufern, bevor sie entlang des Pfades zerstört wurde.",al={"wem gehörte die karawane","herkunft der karawane","wer hat die karawane angegriffen"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Mit den Dokumenten in der Hand weist Morin Wolkenpirscher Krieger an, die Führung der Venture Company direkt zu konfrontieren und ihren Bergbaubetrieb in den östlichen Ausläufern zu zerschlagen.",al={"was kommt als nächstes","nächste quest nach überfallene karawane","nachverfolgung der karawane"}},{q="Warum bedroht dies die Tauren?",a="Die Tauren betrachten das Land als heilig und verehren die Erdenmutter. Der rücksichtslose Tagebau und die industrielle Verschmutzung durch die Venture Company schänden aktiv die unberührte Landschaft von Mulgore.",al={"warum kümmert es die tauren","bedrohung durch venture company","bedrohung für mulgore"}}},fp="19,373,24.371.0,21.434.0,39.146.0,26.176.0,38.180.0,32.169.0,40.178.1,34.178.0"}
P.entries["quest:752"] = {n="Eine bescheidene Bitte",s="Eine bescheidene Bitte ist ein früher Pflichtritus, der von Häuptling Falkenwind in Camp Narache vergeben wird. Während sich der Häuptling um dringliche Stammesangelegenheiten auf der Hochwolkenebene kümmert, bittet er einen jungen Abenteurer, nach Südosten aufzubrechen und nach seiner betagten Mutter am örtlichen Wasserbrunnen zu sehen. Die Bitte unterstreicht gemeinschaftliche Verantwortung, Ehrfurcht vor den Ältesten und die alltägliche Harmonie, die für die Lebensweise der Tauren unerlässlich ist.",h="Eine bescheidene Bitte ist ein früher Pflichtritus, der von Häuptling Falkenwind in Camp Narache vergeben...",kw={"eine bescheidene bitte","camp narache","häuptling falkenwind","großmutter falkenwind","mulgore","die hochwolkenebene","wasserbrunnen"},ang={["faction:Horde"]="Die ruhige, pastorale Natur der Aufgaben in Narache unterstreicht, wie sehr die friedvolle Gemeinschaftsphilosophie der Tauren im Kontrast zur raueren, aufs Überleben ausgerichteten Härte der übrigen noch jungen Horde steht.",["race:Tauren"]="Für junge Tauren-Krieger beweist das Befolgen des Rufs des Häuptlings die grundlegenden Lehren der Erdenmutter: Respekt vor den Ältesten und unerschütterliche Hingabe an das gemeinsame Wohl des Stammes."},sec={{t="Gemeinschaftliche Harmonie und Pflicht",b="Im Schatten von Camp Narache wird von jedem Stammesmitglied erwartet, seinen Teil beizutragen und an der Harmonie des Lebens teilzuhaben. Für junge Tauren, die das Coming of Age durchlaufen, bemisst sich die Stammespflicht nicht allein am kriegerischen Können gegen Borstennacken oder Raubtiere; sie beginnt mit grundlegender sozialer Verantwortung. Häuptling Falkenwind lebt dieses Ethos unmittelbar vor: Durch administrative und verteidigende Führung an seinen Posten gebunden, setzt er sein Vertrauen in angehende Abenteurer, um über die schutzbedürftigen Ältesten der Gemeinschaft zu wachen."},{t="Der Brunnen südöstlich von Narache",b="Mulgores Hochwolkenebene ist auf lebenswichtige natürliche Wasserbrunnen angewiesen, die außerhalb der Grenzen des Lagers verstreut liegen. Früh am Morgen verließ Großmutter Falkenwind das Dorf unbeaufsichtigt, um frisches Wasser aus der südöstlichen Quelle zu holen. In einem Land, das von territorialen Wildtieren und vordringenden Bristleback-Borstennacken durchstreift wird, erregt eine Älteste, die stundenlang ausbleibt, leise Besorgnis und veranlasst Falkenwind dazu, Hilfe zu entsenden, um sicherzustellen, dass sie unversehrt ist."}},faq={{q="Wer bietet diese Quest an und wo finde ich ihn?",a="Häuptling Falkenwind, der Anführer von Camp Narache auf der Hochwolkenebene in Mulgore, bietet die Quest an. Er steht im zentralen Pavillon des Lagers und beaufsichtigt die lokalen Angelegenheiten.",al={"wer vergibt eine bescheidene bitte","wo quest annehmen","häuptling falkenwind standort"}},{q="Wo befindet sich Großmutter Falkenwind?",a="Großmutter Falkenwind befindet sich kurz südöstlich von Camp Narache und versorgt den Wasserbrunnen auf der tiefer gelegenen Ebene der Hochebene.",al={"großmutter falkenwind standort","wo ist die mutter","wasserbrunnen standort"}},{q="Warum sieht Häuptling Falkenwind nicht selbst nach seiner Mutter?",a="Häuptling Falkenwind muss in Camp Narache bleiben, um dringende Stammesangelegenheiten zu beaufsichtigen und junge Krieger anzuleiten. Als Häuptling stützt er sich auf die kollektive Verantwortung des Stammes und vertraut aufstrebenden Abenteurern, sich an seiner statt um die dörflichen Belange zu kümmern.",al={"warum kann häuptling nicht gehen","warum sieht falkenwind nicht nach","häuptling falkenwind beschäftigt"}},{q="Ist Großmutter Falkenwind am Brunnen in Gefahr?",a="Während auf den umliegenden Ebenen aggressive Berglöwen und Schreiter hausen, wird Großmutter Falkenwind wohlbehalten am Brunnen angetroffen – angenehm überrascht, dass jemand den weiten Weg auf sich genommen hat, um nach einer Ältesten zu sehen.",al={"ist sie in sicherheit","wird großmutter angegriffen","gefahr am wasserbrunnen"}},{q="Welche kulturelle Bedeutung hat diese Quest für die Tauren?",a="Die Kultur der Tauren legt immensen Wert auf Familie, gemeinschaftlichen Zusammenhalt und die Ehrfurcht vor den Ältesten. Die Quest lehrt junge Helden, dass wahre Stärke in bescheidenem Dienen und dem Schutz der Sippe wurzelt, anstatt persönlichem Ruhm nachzujagen.",al={"tauren kultur eine bescheidene bitte","warum ist dies eine bescheidene bitte","tauren älteste"}},{q="Was geschieht, nachdem Großmutter Falkenwind gefunden wurde?",a="Sobald Ihr mit Großmutter Falkenwind sprecht, schließt sie die Aufgabe ab und bittet um weitere Unterstützung beim Zurücktragen der gefüllten Wasserkanne ins Lager.",al={"folgequest","eine bescheidene bitte folgequest","was tun nachdem mutter gefunden"}}},fx={b1d313d3={q="Warum möchte Häuptling Falkenwind, dass Ihr nach seiner Mutter seht?",a="Seine betagte Mutter verließ Camp Narache früh am Morgen, um Wasser aus dem Brunnen im Südosten zu holen, und sie ist schon sehr lange fort. Das Leben der Tauren beruht auf gemeinschaftlicher Verantwortung und gegenseitiger Fürsorge, und obwohl sich Falkenwind um ihr Wohlergehen sorgt, halten ihn seine Pflichten als Häuptling im Lager fest.",al={"warum will falkenwind das erledigt haben","beweggrund von häuptling falkenwind","warum nach großmutter falkenwind sehen"}}},fp="13,384,25.486.0,29.432.0,47.166.0,38.125.0,55.242.0,46.215.0,64.231.0,48.151.0"}
P.entries["quest:753"] = {n="Eine bescheidene Bitte",s="Eine bescheidene Bitte ist ein einleitender Dienstbarkeitsritus auf der Hochwolkenebene, bei dem eine Älteste die Demut und den Fleiß eines angehenden Abenteurers auf die Probe stellt. Indem junge Tauren frisches Brunnenwasser über die Ebenen zu Camp Naraches Anführer tragen, lernen sie, dass der Dienst an ihrem Volk mit den einfachsten Pflichten beginnt.",h="Eine bescheidene Bitte ist ein einleitender Dienstbarkeitsritus auf der Hochwolkenebene, bei dem eine Älteste...",kw={"camp narache","häuptling falkenwind","großmutter falkenwind","eine bescheidene bitte","mulgore","die hochwolkenebene","riten der erdenmutter","wasserkanne"},ang={["faction:Horde"]="Die Lehren der Familie Hawkwind verdeutlichen, wie die Tauren Zusammenhalt und Überleben in Mulgore sichern und einen friedvollen, doch unbeugsamen Eckpfeiler von Thralls Horde bilden.",["race:Tauren"]="Das Holen von Wasser für Eure Ältesten verkörpert die grundlegende Taurentugend der Fürsorge für die Gemeinschaft und beweist, dass Ihr bereit seid, den Pfad der Erdenmutter zu beschreiten."},sec={{t="Vitalität der Jugend",b="Großmutter Falkenwind ist in ihrem langen Leben schon viele Pfade beschritten, und während ihr Geist ungebrochen bleibt, tragen ihre Beine sie nicht mehr mit der Schnelligkeit ihrer Jugend über die Ebenen. Sie hält sich in der Nähe des Wasserbrunnens am südlichen Rand der Hochwolkenebene auf und widmet sich ihren Aufgaben mit geduldiger Entschlossenheit. Wenn aufstrebende Verteidiger des Stammes ihren Weg kreuzen, lenkt sie deren jugendliche Energie auf praktische Bedürfnisse der Gemeinschaft und gibt ihnen so die Möglichkeit, ihren Wert durch Dienst statt durch Gewalt zu beweisen."},{t="Dienst am Stamm",b="Die Aufgabe verlangt vom Initianden, einen gefüllten Wasserkrug zurück nach Nordwesten nach Camp Narache zu schleppen und ihn direkt dem Anführer der Siedlung, Häuptling Falkenwind, zu überreichen, der zufällig der Sohn der Großmutter ist. In der Taurengesellschaft erfordert das Überleben auf den kargen Ebenen von Mulgore geteilte Arbeit und verlässliche Vorräte an frischem Wasser. Den Ältesten der Gemeinschaft Respekt zu erweisen, indem man ihre Lasten schultert, gilt als Grundstein dafür, ein wahrer Beschützer des Stammes zu werden."},{t="Ein Pfad gen Donnerfels",b="Häuptling Falkenwind sieht mehr als nur eine erledigte Pflicht, wenn ein junger Wanderer eintrifft und Wasser von seiner Mutter bringt. Nach den Bräuchen der Tauren beginnt die Bereitschaft eines Individuums, sich in fernen Ländern für sein Volk einzusetzen, mit Demut und der ungefragten Hilfsbereitschaft. Indem der Initiand diese stille Disziplin beweist, fällt er dem Häuptling ins Auge und verdient sich die Empfehlung für die uralten Riten der Erdenmutter – jene wahren spirituellen Prüfungen, die die Tore nach Donnerfels öffnen."}},faq={{q="Wer ist Großmutter Falkenwind?",a="Großmutter Falkenwind ist eine Älteste der Familie Hawkwind, die am Brunnen auf der Hochwolkenebene anzutreffen ist. Sie ist die Mutter des Anführers von Camp Narache, Häuptling Falkenwind, und leitet junge Tauren an, Demut und die Werte des Stammes zu erlernen.",al={"großmutter falkenwind","wer vergibt eine bescheidene bitte","hawkwind älteste"}},{q="Wo befindet sich der Wasserbrunnen?",a="Der Wasserbrunnen liegt südöstlich von Camp Narache auf den grasbewachsenen Ebenen der Hochwolkenebene. Krüge mit frischem Brunnenwasser stehen daneben bereit, damit Reisende und Lagerpfleger sie zurücktragen können.",al={"wasserbrunnen standort","wo ist der brunnen","wasserkrug finden"}},{q="Wer ist Häuptling Falkenwind?",a="Häuptling Falkenwind ist der Häuptling, der die Aufsicht über Camp Narache auf der Hochwolkenebene führt. Er leitet die Ausbildung und die spirituellen Riten junger Tauren und bereitet sie darauf vor, auszuziehen und dem gesamten Stamm in Mulgore zu dienen.",al={"häuptling falkenwind","wer ist der häuptling","camp narache anführer"}},{q="Warum wird diese Pflicht als wichtige Prüfung betrachtet?",a="Die Taurenkultur legt großen Wert auf Demut, den Beistand innerhalb der Gemeinschaft und den Respekt vor den Ältesten. Das Erfüllen unscheinbarer, alltäglicher Aufgaben zeigt, dass einem Abenteurer der Erhalt seines Volkes am Herzen liegt und nicht bloß persönlicher Ruhm im Kampf.",al={"warum wasser tragen","warum eine bescheidene bitte","ist diese quest wichtig"}},{q="Was folgt nach dem Abschluss von Eine bescheidene Bitte?",a="Der Abschluss dieser Aufgabe beweist Eure Disziplin gegenüber Häuptling Falkenwind, der Euch daraufhin anweist, die Riten der Erdenmutter zu beschreiten – eine Reihe traditioneller Herausforderungen, die alle Tauren beim Erwachsenwerden meistern müssen.",al={"was kommt danach","nächste quest","nach eine bescheidene bitte"}},{q="Wohin führt dieser Pfad letztendlich?",a="Den Respekt der Ältesten in Camp Narache zu erlangen, bereitet Euch darauf vor, die abgelegene Hochebene hinter Euch zu lassen, in die weiten Ebenen von Mulgore hinauszuziehen und schließlich die hohen Hochebenen der Hauptstadt Donnerfels anzusteuern.",al={"zukünftiges ziel","wohin gehen wir","ziel donnerfels"}}},fx={["57bce500"]={q="Warum möchte Großmutter Falkenwind, dass dies erledigt wird?",a="Großmutter Falkenwind gibt zu, dass ihren alternden Beinen die frühere Kraft fehlt, was einfache tägliche Aufgaben rund um die Hochwolkenebene langsam und ermüdend macht. Wichtiger noch, sie betrachtet diesen routinemäßigen Botengang als eine wichtige moralische Lektion für Euch. Das Liefern von lebensnotwendigem Trinkwasser an ihren Sohn, Häuptling Falkenwind, dient als erste Prüfung, um zu sehen, ob Ihr die Bescheidenheit, Geduld und den Gemeinschaftsgeist besitzt, die von einem wahren Diener des Stammes erwartet werden.",al={"beweggrund von großmutter falkenwind","warum wasser zu häuptling falkenwind bringen","warum eine demütige aufgabe"}},b511fd77={q="Wozu dient die Wasserkanne?",a="Die Wasserkanne ist ein einfaches Tongefäß, das frisch aus dem Brunnen auf der Hochwolkenebene geschöpft wurde, um Camp Narache mit sauberem Wasser zu versorgen. Der Transport testet Eure Hingabe zu gemeinschaftlichen Aufgaben und stellt sicher, dass selbst angehende Abenteurer den Wert der Unterstützung ihrer Verwandten lernen, bevor sie nach größerem militärischen Ruhm streben.",al={"zweck der wasserkanne","warum wasserkanne","was ist die kanne"}},["19ad5d96"]={q="Warum bittet Großmutter Falkenwind Euch, anstatt es selbst zu tun?",a="Großmutter Falkenwind ist alt und gibt zu, dass ihre Beine nicht mehr die frühere Kraft haben, was bedeutet, dass das Tragen schwerer Kannen sie weitaus mehr Zeit kostet als früher. Wenn ein körperlich fähiger Neuling wie Ihr sich ihr nähert, ergreift sie die Gelegenheit, sowohl ihre eigene Last zu erleichtern als auch Eure Bereitschaft zu testen, unglamouröse, alltägliche Arbeit für das Lager zu verrichten.",al={"warum nicht großmutter","warum mich um wasser bitten","warum kann falkenwind kein wasser holen"}}},fp="13,288,21.500.0,20.469.0,27.468.0,28.220.0,32.178.0,22.203.0,47.236.0,42.202.0,37.209.0"}
P.entries["quest:754"] = {n="Winterhufsäuberung",s="Winterhufsäuberung ist ein Ritus, der Horde-Abenteurern von Mull Donnerhorn im Dorf der Bluthufe anvertraut wird. Nachdem goblinische Machenschaften die örtlichen Quellen verunreinigt haben, muss ein geweihter Totem in das Territorium der Venture Company getragen werden, um den Brunnen der Winterhufe zu reinigen. Die Wiederherstellung dieser Quelle ist ein entscheidender erster Schritt, um die vergifteten Gewässer im zentralen Mulgore zu heilen.",h="Winterhufsäuberung ist ein Ritus, der Horde-Abenteurern von Mull Donnerhorn im Dorf der Bluthufe anvertraut...",kw={"dorf der bluthufe","reinigung","mulgore","mull donnerhorn","gift","totem","venture company","wasserbrunnen","winterhoof"},ang={["class:Druid"]="Die unmittelbare Rückkehr durstiger Wildtiere an die gereinigte Quelle mitzuerleben, beweist die grundlegende Notwendigkeit, die Natur zu heilen, wo immer die Zivilisation sie zu zerstören droht.",["class:Shaman"]="Geister durch Totems zu kanalisieren, um unnatürliche industrielle Schändungen rückgängig zu machen, verkörpert den eigentlichen Sinn der schamanischen Verbindung mit den Elementargewässern.",["faction:Horde"]="Die Sicherung von Mulgores Frischwasserversorgung stabilisiert das Kernland der neu angesiedelten Tauren und stärkt den südlichen Pfeiler der jungen Horde.",["race:Tauren"]="Die Brunnen von Mulgore sind heilige Lebensspender, geschenkt von der Erdenmutter; sie gegen die Gier der Goblins zu verteidigen, ist für jeden Tauren sowohl bürgerliche Pflicht als auch heilige Verpflichtung."},sec={{t="Ein geschändetes Land",b="Die grasbewachsenen Ebenen von Mulgore sind auf ein empfindliches Netzwerk uralter Wasserbrunnen angewiesen, um sowohl das Wild als auch die verstreuten Taurenstämme zu versorgen. Vor Kurzem drangen skrupellose industrielle Söldner der Venture Company in die sanften Hügel südöstlich des Dorfes der Bluthufe vor. Ihre Aktivitäten haben das örtliche Grundwasser verseucht, sodass der Brunnen der Winterhufe faulig und giftig zurückblieb. Wilde Tiere meiden das verdorbene Wasser, und die nahegelegenen Lager stehen vor einer drohenden Krise, falls sich die Verderbnis weiter im Erdreich ausbreitet."},{t="Das Ritual des reinigenden Wassers",b="Um dem industriellen Unrat entgegenzuwirken, schnitzt und verzaubert Mull Donnerhorn ein rituelles Reinigungstotem, das mit den Segnungen der Erdenmutter erfüllt ist. Um dieses Heilmittel abzuliefern, muss man sich jedoch an bewaffneten Schlägern der Venture Company vorbeiwagen, die ihren Anspruch auf die Quelle erhoben haben. Indem ein Abenteurer das Totem direkt an der Brunnenfassung aufstellt, bannt er den fauligen Abfluss, sodass wieder sauberes, lebensspendendes Wasser aus den Tiefen der Erde aufsteigen kann."}},faq={{q="Wo befindet sich der Brunnen der Winterhufe?",a="Der Brunnen der Winterhufe befindet sich in den Hügeln südöstlich des Dorfes der Bluthufe in Mulgore. Er wird schwer von Goblinarbeitern und Söldnern im Dienst der Venture Company patrouilliert.",al={"wasserbrunnen von winterhoof standort","wo ist der winterhoof-brunnen","winterhoof-brunnen finden"}},{q="Warum wurde der Wasserbrunnen vergiftet?",a="Die Venture Company errichtete in der Nähe Bergbau- und Ausgrabungsstätten, wodurch giftige Industrieabwässer und Abfälle direkt in den Grundwasserleiter sickern konnten, was die natürliche Quelle für die heimische Tierwelt und die Tauren ungenießbar machte.",al={"wer hat das wasser vergiftet","warum ist der brunnen verschmutzt","venture company brunnen"}},{q="Wer ist Mull Donnerhorn?",a="Mull Donnerhorn ist ein geistlicher Ältester, der im Dorf der Bluthufe stationiert ist. Im tiefen Einklang mit dem Wohl der Erde fertigt er zeremonielle Totems an, um die Umweltzerstörung durch äußere Eindringlinge rückgängig zu machen.",al={"wer ist mull","mull donnerhorn rolle"}},{q="Was geschieht, nachdem der Brunnen gereinigt wurde?",a="Sobald der Brunnen der Winterhufe wieder klares Wasser führt und Wildtiere gefahrlos daraus trinken, lenkt Mull Donnerhorn Eure Aufmerksamkeit auf andere bedrohte Brunnen in Mulgore, beginnend mit dem Totem der Donnerhörner.",al={"was kommt danach","nach säuberung von winterhoof","was tut mull als nächstes"}},{q="Wer sind die Wachen am Brunnen?",a="Der Brunnen ist von Arbeitern und Mietlingen besetzt, die bei der Venture Company angestellt sind – einem skrupellosen, von Goblins geführten Syndikat, das Länder ohne Rücksicht auf das lokale Ökosystem ihrer natürlichen Ressourcen beraubt.",al={"wer bewacht den winterhoof-brunnen","welche feinde sind am brunnen"}},{q="Wie funktioniert das Reinigungstotem?",a="Das Totem, geschnitzt nach heiligen Riten und Schutzritualen der Tauren, schöpft aus Naturgeistern und den Segnungen der Erdenmutter, um unnatürliche chemische Schadstoffe aus dem Quellursprung zu tilgen.",al={"reinigungstotem lore","wie funktioniert mulls totem"}}},fx={["16ee77f0"]={q="Warum möchte Mull Donnerhorn, dass der Brunnen der Winterhufe gereinigt wird?",a="Der Brunnen der Winterhufe ist lebenswichtig für das Gleichgewicht und das Überleben von Mulgore. Sein Wasser wurde verschmutzt, was sowohl die örtliche Tierwelt als auch die Stämme, die davon abhängen, bedroht. Mull Donnerhorn hat ein geweihtes Reinigungstotem vorbereitet, aber seine Kraft muss direkt zum Ort des Geschehens gebracht werden, um das Wasser zu heilen und die Harmonie im Land wiederherzustellen.",al={"warum den brunnen von winterhoof reinigen","beweggrund von mull donnerhorn","warum wasser von winterhoof reinigen"}}},fp="20,358,16.505.0,30.432.0,43.191.0,32.227.0,24.205.0,40.212.1,31.195.0,34.192.0"}
P.entries["quest:7541"] = {n="Dienst an der Horde",s="Der mit Juwelen besetzte Anhänger befindet sich nun bei Zor Einbaum in Orgrimmar, überbracht nach „Bericht an Zor“, und Zor hat noch ein weiteres Wort für Euch.",h="Der mit Juwelen besetzte Anhänger befindet sich nun bei Zor Einbaum in Orgrimmar, überbracht nach „Bericht an...",kw={"düstermarschen","anhänger","bericht an zor","dienst für die horde","zor einbaum"},sec={{t="Zor Einbaum in Orgrimmar",b="Ihr habt den mit Juwelen besetzten Anhänger zu Zor Einbaum in Orgrimmar gebracht, und der Anhänger befindet sich nun bei Zor. Kehrt zu Zor Einbaum zurück, und es gibt noch mehr darüber zu hören, was Ihr für die Horde getan habt."},{t="Zors letztes Wort",b="Zor sagt, dass die Gelehrten Zeit brauchen werden, um den Anhänger zu studieren. Für Euren Dienst für die Horde bietet Zor ein kleines Zeichen der Anerkennung an und sagt, dass das, was Ihr getan habt, Euch und der Horde Ehre bringt."}},faq={{q="Wer hat den Anhänger jetzt?",a="Zor Einbaum in Orgrimmar, nachdem Ihr ihn von Nazeer Bloodpike in Brackenwall dorthin gebracht habt.",al={"wer nimmt den anhänger","wer vergibt diese quest","rolle von zor einbaum"}},{q="Was kommt vor dieser Quest?",a="Sie folgt auf „Bericht an Zor“, wo Ihr den mit Juwelen besetzten Anhänger zu Zor Einbaum gebracht habt.",al={"welche quest ging voraus","dienst für die horde voraussetzung","vorherige quest"}}},fp="20,126,25.185.0,15.186.1,24.99.0,29.77.0"}
P.entries["quest:755"] = {n="Riten der Erdenmutter",s="Rites of the Earthmother markiert den Beginn der spirituellen Reise eines Initianden auf der Hochwolkenebene. Angeleitet von Häuptling Falkenwind suchen Reisende Seher Grauzunge in den südlichen Hügeln von Camp Narache auf. Das Absolvieren dieser ehrwürdigen Zeremonien gilt als eine entscheidende Übergangsprüfung für heranwachsende Tauren.",h="Rites of the Earthmother markiert den Beginn der spirituellen Reise eines Initianden auf der Hochwolkenebene.",kw={"camp narache","häuptling falkenwind","erdenmutter","die hochwolkenebene","rites of the earthmother","seher grauzunge","tauren"},ang={["class:Druid"]="Druidische Anwärter beginnen ihren Pfad der Harmonie mit der Natur, indem sie die heilige Führung der Stammesältesten und Seher respektieren.",["class:Shaman"]="Für angehende Schamanen ist das Ablegen von Riten, die von Stammessehern gesegnet wurden, ein wesentlicher erster Schritt zur Zwiesprache mit den Elementen und den Geistern von Mulgore.",["faction:Horde"]="Das Verständnis dieser heiligen Prüfungen bietet Einblick in das spirituelle Herz der Tauren-Verbündeten, die sich vor kurzem der Horde angeschlossen haben.",["race:Tauren"]="Die Rites of the Earthmother stellen die grundlegende spirituelle Reise für junge Tauren dar und prüfen ihre Bereitschaft, ihrem Stamm zu dienen und die Erdenmutter zu ehren."},sec={{t="Die Schwelle der Prüfungen",b="Auf der Hochwolkenebene weist Häuptling Falkenwind junge Tauren, die sich beweisen wollen, Seher Grauzunge zu. In den ruhigen Hügeln direkt südlich von Camp Narache wohnend, beaufsichtigt Grauzunge die spirituellen Anfänge der Jugend. Diese einfache Reise markiert die formelle Schwelle zwischen dem alltäglichen Lagerleben und den ernsten Verpflichtungen, die der Brauch des Stammes verlangt."},{t="Die Erdenmutter annehmen",b="Die Erdenmutter steht im Mittelpunkt der Schöpfungsmythen und des täglichen Lebens der Tauren. Ihre Riten dienen als heilige Prüfungen der Reife, Widerstandskraft und spirituellen Tiefe. Wie Seher Grauzunge alle mahnt, die an seiner Zuflucht ankommen, ist der Antritt der Rites of the Earthmother kein leichtes Unterfangen und erfordert völlige Hingabe an die Traditionen der Hochebene."}},faq={{q="Wer vergibt die Quest Rites of the Earthmother?",a="Die Quest wird von Häuptling Falkenwind in Camp Narache vergeben, der junge Abenteurer anweist, Seher Grauzunge in den umliegenden Hügeln aufzusuchen.",al={"wer startet rites of the earthmother","questgeber"}},{q="Wo kann ich Seher Grauzunge finden?",a="Seher Grauzunge weilt in den Hügeln direkt südlich von Camp Narache auf der Hochwolkenebene von Mulgore.",al={"wo ist seher grauzunge","standort von grauzunge","grauzunge finden"}},{q="Was sind die Rites of the Earthmother?",a="Die Rites of the Earthmother sind traditionelle heilige Übergangsprüfungen, die von jungen Tauren abgelegt werden, um ihre Weisheit, Stärke und Hingabe an ihr Volk und ihren Glauben zu beweisen.",al={"was sind rites of the earthmother","lore der prüfungen der erdenmutter"}},{q="Wer ist Seher Grauzunge?",a="Seher Grauzunge ist ein angesehener spiritueller Ältester, der südlich von Camp Narache weilt und die Initianden durch die heiligen Prüfungen der Erdenmutter leitet und beaufsichtigt.",al={"wer ist seher grauzunge","rolle von grauzunge"}},{q="Wer ist Häuptling Falkenwind?",a="Häuptling Falkenwind ist der Stammesführer über Camp Narache auf der Hochwolkenebene, dessen Aufgabe es ist, junge Tauren vorzubereiten, bevor er sie zu den Sehern schickt.",al={"wer ist häuptling falkenwind","rolle von falkenwind"}},{q="Was ist erforderlich, um diese Aufgabe abzuschließen?",a="Ihr müsst lediglich von Camp Narache aus nach Süden in die Hügel reisen und mit Seher Grauzunge sprechen, um Eure Bereitschaft für die Prüfungen zu bekunden.",al={"was muss ich tun","wie schließt man die quest ab"}}},fp="24,304,27.356.0,25.352.0,45.141.0,33.108.0,38.172.0,23.157.0,22.155.0,39.135.0"}
P.entries["quest:756"] = {n="Totem der Donnerhörner",s="Totem der Donnerhörner ist eine Aufgabe, die von Mull Donnerhorn im Dorf der Bluthufe vergeben wird, um ein heiliges Säuberungstotem herzustellen. Um die von Goblins verursachte Verschmutzung zu bekämpfen, die sich in den Wasserbrunnen von Mulgore ausbreitet, müssen junge Streiter der Horde natürliche Klauen von den Raubtieren der Ebenen sammeln, um die ungezähmte Kraft des Landes in rituelles Holz zu binden.",h="Totem der Donnerhörner ist eine Aufgabe, die von Mull Donnerhorn im Dorf der Bluthufe vergeben wird, um ein...",kw={"dorf der bluthufe","reinigung","pumaklauen","flachlandberglöwe","mulgore","mull donnerhorn","präriepirscher","pirscherklauen","totem der donnerhörner","wasserbrunnen"},ang={["class:Hunter"]="Das Sammeln der Klauen erfordert ein Verständnis für die einheimischen Pirschjäger der Ebenen sowie die Ehrung der Beute, um das Ökosystem zu bewahren.",["class:Shaman"]="Die totemistische Wiederherstellung beruht darauf, die lebendigen Geister des Landes anzurufen, um Wasser zu reinigen, das durch unnatürliche, rücksichtslose Ausbeutung verdorben wurde.",["race:Tauren"]="Die Verteidigung der Grundwasservorkommen von Mulgore gegen fremde Ausbeutung ist eine heilige Stammespflicht und spiegelt das Gebot der Erdenmutter wider, im Gleichgewicht zu leben, anstatt zu plündern."},sec={{t="Die Jagd auf die Raubtiere der Ebenen",b="Da die industrielle Ausbeutung durch die Venture Company die kostbaren Wasserquellen von Mulgore vergiftet, arbeitet Mull Donnerhorn fieberhaft an Gegenmitteln. Die Erschaffung des Läuterungstotems der Donnerhörner erfordert die natürlichen Essenzen der fokussiertesten Jäger der Ebenen: Präriepirscher und Flachlandberglöwen. Indem man die Krallen dieser Raubtiere erbeutet, die östlich und westlich des Dorfes der Bluthufe umherstreifen, leitet das Ritual die rohe, unverdorbene Raubtierkraft der Tierwelt direkt in das Totem."},{t="Das Wesen der Jagd",b="Die Tradition der Tauren sieht einen tiefen Unterschied zwischen der Jagd zur Nahrungssuche oder für das spirituelle Gleichgewicht und der rücksichtslosen Plünderung durch die Goblins. Mull betont, dass die Reinheit, mit der einheimische Raubtiere jagen, unerlässlich ist, um die verdorbene Erde zu reinigen. Wo die Maschinerie der Goblins die Quellen mit Öl und Industrieabfällen schändet, liefert die natürliche Kraft der mit dem Land ringenden Bestien den spirituellen Katalysator, der zur Wiederherstellung des Brunnens der Donnerhörner benötigt wird."}},faq={{q="Warum benötigt Mull Donnerhorn Raubtierklauen?",a="Mull nutzt die Klauen von Präriepirschern und Flachlandberglöwen, um den reinen, ungezähmten Raubtiergeist der Ebenen in ein Säuberungstotem zu leiten. Er glaubt, dass der reine Geist natürlicher Jäger der künstlichen, industriellen Verderbnis entgegenwirkt.",al={"warum klauen","zweck von pirscherklauen","zweck von berglöwenklauen"}},{q="Wer verdirbt das Wasser in Mulgore?",a="Die in Mulgore operierenden Goblins der Venture Company verschmutzen Land und Wasser. Ihre rücksichtslose Rohstoffförderung und Bohranlagen leiten giftigen Schlamm in das Grundwasser, das die Brunnen der Stämme speist.",al={"wer hat den brunnen verseucht","warum ist der brunnen vergiftet","was vergiftete mulgore"}},{q="Wo sind die Präriepirscher und Flachlandberglöwen zu finden?",a="Beide Bestien streifen durch die offenen Ebenen von Zentral-Mulgore, vor allem verteilt über die sanften Savannen direkt östlich und westlich des Dorfes der Bluthufe.",al={"pirscher aufenthaltsort","wo man berglöwen findet","fundorte von berglöwenkrallen"}},{q="Was geschieht nach der Herstellung des Thunderhorn-Totems?",a="Sobald Mull das Totem mithilfe der Klauen geschnitzt und verzaubert hat, schickt er Euch direkt zum verseuchten Brunnen der Donnerhörner, um das Reinigungsritual durchzuführen und das Gift zu vertreiben.",al={"was als nächstes","nach thunderhorn-totem","totem folgequest"}},{q="Wie hängt dies mit der vorangegangenen Säuberung am Brunnen der Winterhufe zusammen?",a="Dies ist Teil der fortlaufenden Bemühungen der Stämme, die heiligen Gewässer von Mulgore zu bewahren. Der Brunnen der Winterhufe wurde zuerst gereinigt, und nun bedroht die Verunreinigung den Thunderhorn-Brunnen weiter nördlich.",al={"winterhoof verbindung","vorherige totemquest"}},{q="Warum verwenden die Tauren nicht einfach pflanzliche Heilmittel anstelle von Tierkrallen?",a="Das rituelle Handwerk der Tauren stützt sich auf unterschiedliche elementare und physische Aspekte der Natur. Die scharfe Reinheit von Spitzenprädatoren liefert eine aktive, widerständige spirituelle Kraft, die speziell erforderlich ist, um die aggressiven Industriegifte der Goblins zu durchdringen.",al={"warum keine kräuter","schamanische totemmaterialien"}}},fx={cb047e40={q="Warum möchte Mull Donnerhorn, dass dies getan wird?",a="Der Brunnen der Donnerhörner wird stündlich stärker verseucht, vergiftet durch rücksichtslose Goblin-Operationen in der Nähe. Mull Donnerhorn muss ein heiliges Läuterungstotem herstellen, um den Brunnen zu reinigen, bevor sich die Verderbnis weiter durch die Erde ausbreitet und seinem Volk schadet.",al={"warum mull dies möchte","mull donnerhorns motiv","warum thunderhorn totem fertigen"}},["43953f1d"]={q="Gegen welche Kreaturen werdet Ihr wegen der Krallen ausgesandt?",a="Ihr werdet ausgesandt, um die wilden Raubtiere zu jagen, die durch die Ebenen von Mulgore streifen: die Präriepirscher und Flachlandpumas. Diese Bestien durchstreifen die Gebiete östlich und westlich des Dorfes der Bluthufe auf natürliche Weise und leben und jagen als Teil des natürlichen Gleichgewichts des Landes.",al={"was jage ich","wer sind die ziele","beute für thunderhorn totem"}}},fp="17,307,28.469.0,22.465.0,46.237.0,39.200.0,58.146.0,50.174.1,66.195.0,72.236.0"}
P.entries["quest:757"] = {n="Ritus der Kraft",s="Der Ritus der Kraft ist die einleitende Prüfung der traditionellen Riten der Erdenmutter, die von jungen Tauren in Camp Narache absolviert wird. Um ihren Mut und ihre Entschlossenheit bei der Verteidigung des Stammes zu beweisen, müssen die Initianden die vordringenden Stacheleber der Bristleback in der Dornrankenklamm dezimieren und Häuptling Falkenwind ihre Gürtel überbringen.",h="Der Ritus der Kraft ist die einleitende Prüfung der traditionellen Riten der Erdenmutter, die von jungen...",kw={"dornrankenklamm","bristleback","camp narache","häuptling falkenwind","erdenmutter","mulgore","stacheleber","ritus der kraft","seher grauzunge"},ang={["faction:Horde"]="Die Verteidigung der Mesa sichert eines der wichtigsten Rekrutierungsgebiete der Horde und gewährleistet, dass junge Krieger und Schamanen ungestört heranreifen können, um dem neuen Bündnis beizustehen.",["race:Tauren"]="Jeder junge Taure beginnt seine Reise mit diesen uralten Riten und beweist seine Bereitschaft, sein Volk vor der Bedrohung durch die Stacheleber zu schützen, bevor er Die Hochwolkenebene verlässt."},sec={{t="Die erste Prüfung",b="Für einen jungen Tauren, der die Anerkennung der Stammesältesten und die spätere Aufnahme in Donnerfels anstrebt, ist der Abschluss der Riten der Erdenmutter eine unverzichtbare Pflicht. Der von Seher Grauzunge aufgetragene Ritus der Kraft dient dabei als erste Prüfung. Er verlangt körperlichen Mut und entschlossenes Handeln zur Verteidigung von der Hochwolkenebene und prüft, ob ein Initiand den Todfeinden des Stammes ohne Zögern entgegentreten kann."},{t="Die Bedrohung durch die Bristleback",b="Der für diese Prüfung gewählte Schauplatz ist die Dornrankenklamm, eine dornengestrüppüberwucherte Schlucht östlich von Camp Narache, die von den Stachelebern der Bristleback besetzt ist. Diese aggressiven Eindringlinge dringen unaufhörlich in das angestammte Land ein, überfallen Jagdtrupps aus dem Hinterhalt und plündern im Schutz der Dunkelheit die Vorräte des Lagers. Sie zu erschlagen und ihre Gürtel zu erbeuten, dient sowohl als Beweis des Mutes als auch als notwendige Maßnahme zur Sicherung der Siedlung."}},faq={{q="Was ist der Zweck des Ritus der Kraft?",a="Er bildet das Fundament der Riten der Erdenmutter und soll den Mut eines jungen Tauren im Kampf auf die Probe stellen. Indem feindliche Bedrohungen für das Lager beseitigt werden, verdient sich ein Initiand das Recht, auf dem Weg zu wahrhaftigem Respekt in Donnerfels voranzuschreiten.",al={"warum ritus der kraft absolvieren","ritus der kraft lore","zweck des ritus der kraft"}},{q="Wer vergibt und bewertet diese Prüfung?",a="Seher Grauzunge erteilt dem Initianden den Auftrag und legt die spirituellen sowie praktischen Anforderungen der Prüfung dar. Sobald zwölf Gürtel der Bristleback gesammelt wurden, muss der Beweis der Tapferkeit direkt bei Häuptling Falkenwind in Camp Narache vorgelegt werden.",al={"wer gibt ritus der kraft","wo ritus der kraft abgeben"}},{q="Wo befindet sich die Dornrankenklamm?",a="Die Dornrankenklamm liegt direkt östlich von Camp Narache auf der Hochwolkenebene. Es ist eine dornige Schlucht, in der es von feindseligen Stachelebern der Bristleback wimmelt.",al={"wo ist dornrankenklamm","dornrankenklamm ort"}},{q="Warum geraten die Bristleback ins Visier?",a="Die Bristleback dringen in die angestammten Jagdgründe des Stammes ein. Sie verüben wiederholt Hinterhalte auf Taurenjäger und stehlen im Schutz der Dunkelheit Vorräte aus Camp Narache, was sie zu direkten Feinden des Stammes macht.",al={"warum bristleback töten","was haben die stacheleber getan"}},{q="Warum sammelt man Gürtel statt anderer Trophäen?",a="Gürtel dienen als greifbare Zeichen besiegter Krieger. Sie beweisen, dass der Initiand den Stachelebern im Nahkampf gegenüberstand und ausgewachsene Kämpfer zur Strecke brachte, anstatt lediglich aus der Ferne Beute zu machen.",al={"warum bristleback-gürtel","warum gürtel"}},{q="Was folgt nach dem Abschluss des Ritus der Kraft?",a="Das Bestehen des Ritus der Kraft beweist die eigene Tapferkeit und qualifiziert den Initianden für die darauffolgenden Riten der Erdenmutter, womit der traditionelle Weg zum Erwachsenenalter und zum spirituellen Ansehen innerhalb des Stammes fortgesetzt wird.",al={"was kommt nach ritus der kraft","nächster ritus der erdenmutter"}}},fx={f38315d5={q="Warum schickt Euch Seher Grauzunge zu den Borstennacken?",a="Seer Grauzunge führt die Jugend von Camp Narache durch die heiligen Rites of the Earthmother. Für Eure erste Prüfung muss er Eure kämpferische Entschlossenheit gegen eine reale und dringende Gefahr für den Stamm testen. Die Borstennacken-Stacheleber dringen in die Ländereien der Tauren ein, überfallen Jäger und stehlen im Schutz der Dunkelheit. Indem er Euch schickt, um sie zu konfrontieren, stellt Grauzunge sicher, dass Ihr Euer Volk beschützt, während Ihr Eure Stärke beweist und Euch den Respekt des Stammes verdient.",al={"warum möchte grauzunge dies","seher grauzunges motiv","warum rite of strength"}},e0dd8e68={q="Warum werdet Ihr ausgesandt, diese Prüfung allein zu absolvieren?",a="Die Rite of Strength ist ein persönlicher Initiationsritus, keine einfache Aufgabe für die Garnison. Während Stammeskrieger den Außenposten bewachen, muss jeder junge Tauren unabhängig Tapferkeit und kämpferische Fähigkeiten demonstrieren, bevor er in Donnerfels als Erwachsener anerkannt wird. Die Prüfung verlangt, dass Ihr Euch den Feinden Eures Volkes selbst stellt, damit die Ältesten wissen, dass Ihr den Stamm verteidigen könnt, wenn Ihr dazu gerufen werdet.",al={"warum ich rite of strength","warum keine wachen zu borstennacken","warum muss ich gegen borstennacken kämpfen"}}},fp="16,303,15.399.0,22.404.0,44.234.0,34.237.0,37.150.0,40.223.0,44.196.0,49.201.0"}
P.entries["quest:758"] = {n="Donnerhornsäuberung",s="Donnerhornsäuberung ist ein wichtiger spiritueller Ritus in Mulgore, der Reisende damit beauftragt, den verdorbenen Brunnen der Donnerhörner zu reinigen. Ausgerüstet mit einem von Mull Donnerhorn vorbereiteten rituellen Totem stellen Abenteurer die verseuchte Quelle wieder her, die für den örtlichen Stamm überlebenswichtig ist. Eine erfolgreiche Reinigung erntet die tief empfundene Anerkennung der Ahnen von Thunderhorn.",h="Donnerhornsäuberung ist ein wichtiger spiritueller Ritus in Mulgore, der Reisende damit beauftragt, den...",kw={"ahnengeister","dorf der bluthufe","säuberungstotem","erdenmutter","mulgore","mull donnerhorn","donnerhornsäuberung","brunnen der donnerhörner"},ang={["class:Druid"]="Das Säubern vergifteter Gewässer hält die Ausbreitung der Verderbnis im Ökosystem von Mulgore auf und bewahrt die natürliche Harmonie der Ebenen.",["class:Shaman"]="Die Ahnenenergie durch Totems zu leiten, um verdorbene natürliche Quellen zu heilen, ist das ureigenste Fundament der schamanischen Berufung.",["faction:Horde"]="Den Tauren bei ihren heiligen Quellen beizustehen, stärkt das Band zwischen der jungen Horde und ihren stolzen Verbündeten, den Shu'halo.",["race:Tauren"]="Die Wiederherstellung der heiligen Quellen ehrt die Erdenmutter und schützt Eure Sippe, während sie sich eine dauerhafte, friedliche Heimat in Mulgore aufbaut."},sec={{t="Eine vergiftete Lebensader",b="Die Wasserbrunnen in den weiten Ebenen von Mulgore sind lebenswichtige Lebensadern für die nomadischen Taurenstämme, die das Grasland vor Kurzem besiedelt haben. Wenn üble Gifte diese unterirdischen Quellen verseuchen, drohen sowohl der Tierwelt als auch den nahe gelegenen Siedlungen verheerende Folgen. Der Brunnen der Donnerhörner, nördlich des Dorfes der Bluthufe gelegen, ist dieser Verunreinigung zum Opfer gefallen und bedarf eines gezielten spirituellen Eingreifens, um das bedrängte Land zu heilen."},{t="Ahnenreinigung",b="Um der Verderbnis entgegenzuwirken, fertigt Mull Donnerhorn ein geweihtes Säuberungstotem an, das von spiritueller Kraft erfüllt ist. Indem Abenteurer dieses Relikt direkt zu den vergifteten Wassern bringen, können sie die Macht der Ahnen in die Quelle leiten, die Giftstoffe zerstreuen und das unberührte natürliche Gleichgewicht wiederherstellen. Mull erhält eine direkte Bestätigung für den Erfolg der Tat, als ihn die Geister der Ahnen von Thunderhorn im Traum aufsuchen, um ihre anhaltende Dankbarkeit zum Ausdruck zu bringen."}},faq={{q="Wo befindet sich der Brunnen der Donnerhörner?",a="Der Brunnen der Donnerhörner liegt in den Ebenen nördlich des Dorfes der Bluthufe in Mulgore. Er dient als eine von mehreren lebenswichtigen Wasserstellen, die die örtlichen Taurenclans versorgen.",al={"wasserbrunnen von thunderhorn standort","wo ist der brunnen","wo totem benutzen"}},{q="Wer leitet dieses Reinigungsritual ein?",a="Mull Donnerhorn leitet den Ritus ein. Man findet ihn im Dorf der Bluthufe, wo er daran arbeitet, spezialisierte Totems herzustellen, um Mulgores bedrängte Umwelt zu heilen.",al={"wer gibt quest","mull donnerhorn standort","questgeber"}},{q="Warum müssen die Wasserbrunnen in Mulgore gereinigt werden?",a="Die Brunnen in ganz Mulgore sind einer unnatürlichen Vergiftung und Verderbnis zum Opfer gefallen, die das empfindliche Gleichgewicht der Ebenen und das Überleben der Taurenstämme bedroht, welche auf sauberes Wasser angewiesen sind.",al={"warum brunnen säubern","was ist mit dem wasser passiert","warum brunnen vergiftet"}},{q="Woher weiß Mull, dass das Ritual erfolgreich war?",a="Nach Vollendung des Ritus am Brunnen erscheinen die Geister der Ahnen des Thunderhorn-Clans Mull direkt im Traum, preisen die Taten des Abenteurers und überbringen den Dank der Ahnen.",al={"ahnentraum","woher mull es weiß","brunnen gereinigt ergebnis"}},{q="Was folgt auf die Säuberung des Brunnens von Thunderhorn?",a="Die Reinigung des Brunnens von Thunderhorn ist Teil einer umfassenderen Bestrebung zum Schutz von Mulgores Quellen. Als Nächstes schickt Mull Reisende weiter, um einer anderen bedrängten Region beizustehen, indem sie das Totem der Wildmähnen errichten.",al={"wie geht es weiter","folgequest nach thunderhorn","wildmane-totem als nächstes"}},{q="Was ist das Läuterungstotem der Donnerhörner?",a="Das Läuterungstotem der Donnerhörner ist ein rituell geschnitzter spiritueller Fokus, der von Mull Donnerhorn eigens dafür vorbereitet wurde, die verdorbenen Wasser des angestammten Brunnens seines Clans zu reinigen.",al={"säuberungstotem","was ist der totemgegenstand","mulls totem"}}},fx={da3030fe={q="Warum benötigt Mull Donnerhorn Euch, um den Brunnen zu reinigen?",a="Mull Donnerhorn hat den rituellen Fokus gefertigt, doch die Reinigung heiligen Bodens ist ein Ritus des Dienstes und der Ehre für aufstrebende Champions unter den Tauren und ihren Verbündeten. Indem Ihr das Läuterungstotem der Donnerhörner selbst zum verseuchten Brunnen tragt, beweist Ihr Eure Hingabe an die Erdenmutter und die Ahnengeister seines Clans und verdient Euch die Gunst und Führung der Ahnen, die über die Gewässer wachen.",al={"warum ich für mull donnerhorn","warum schickt mull euch","warum läuterungsritual durchführen"}}},fp="21,345,18.422.0,19.447.0,44.167.0,36.161.0,48.196.0,45.184.0,51.191.0,40.180.0"}
P.entries["quest:759"] = {n="Totem der Wildmähnen",s="Totem der Wildmähnen stellt die dritte und letzte Stufe in Mull Donnerhorns Bemühungen dar, reinigende Totems für Mulgores vergiftete Brunnen herzustellen. Um den Wildmane-Brunnen wiederherzustellen, erfordert das Ritual Opfergaben von den wildesten natürlichen Raubtieren des Gebiets: den Präriewolfalphatieren.",h="Totem der Wildmähnen stellt die dritte und letzte Stufe in Mull Donnerhorns Bemühungen dar, reinigende Totems...",kw={"dorf der bluthufe","mulgore","mull donnerhorn","präriewolf alpha","donnerfels","totem","wasserbrunnen","wildmane"},ang={["class:Hunter"]="Das Aufspüren der gerissenen Alphawölfe rund um die hohen Klippen stellt den Respekt eines Jägers vor der Wildnis und ihren schärfsten Raubtieren auf die Probe.",["class:Shaman"]="Schamanen schätzen die feinsinnigen Riten, die nötig sind, um Raubtiertotems mit dem Element Wasser in Einklang zu bringen und giftige Fäulnis auszutreiben.",["race:Tauren"]="Die Reinigung der Brunnen der Ahnen unterstreicht die Verpflichtung der Tauren, Störungen des ökologischen Gleichgewichts zu beheben und die von der Erdenmutter geforderten Opfer zu ehren."},sec={{t="Der letzte Brunnen",b="Nachdem die Materialien zur Weihe der Totems für die Brunnen der Winterhufe und der Thunderhorn beschafft wurden, verbleibt in Zentralmulgore nur noch eine heimgesuchte Quelle: der Wildmane-Brunnen. Das vergiftete Wasser in den Ebenen bedroht sowohl wandernde Wildtiere als auch Siedlungen und verlangt nach mächtigen Urzutaten, um das natürliche Gleichgewicht der Erde wiederherzustellen."},{t="Die Stärke des Raubtiers",b="Um der mächtigen Verderbnis entgegenzuwirken, die in den nördlichen Gewässern verweilt, benötigt Mull Donnerhorn ein Opfer der Wildheit. Präriewolfalphatiere durchstreifen das Grasland, insbesondere rund um die hoch aufragenden Klippen unterhalb von Donnerfels. Das Sammeln ihrer Zähne leitet die unerbittliche Entschlossenheit und Widerstandskraft von Mulgores Spitzenjägern direkt in die Herstellung des reinigenden Totems."},{t="Opfer und Gleichgewicht",b="In der spirituellen Tradition der Tauren birgt die Nutzung der Kreaturen des Landes emotionales und elementares Gewicht. Mull betrachtet das Sammeln von Alphazähnen nicht als Eroberung, sondern als düstere Notwendigkeit, bei der das Opfer von Mulgores Raubtieren hilft, die geschlagenen Wasser der Erdenmutter zu heilen."}},faq={{q="Wofür wird das Totem der Wildmähnen benötigt?",a="Das Totem wird von Mull Donnerhorn hergestellt, um den Wildmane-Brunnen zu reinigen, die letzte verseuchte Wasserquelle, die die Tauren von Mulgore bedroht.",al={"warum totem der wildmähnen herstellen","totem der wildmähnen zweck"}},{q="Warum werden speziell Zähne von Präriewolfalphatieren benötigt?",a="Die Reinigung der tiefen Verseuchung am Wildmane-Brunnen erfordert die Bündelung der wilden, unnachgiebigen Stärke eines Spitzenräubers. Die Zähne der Rudelführer liefern die notwendige Urkraft.",al={"warum wolfszähne","prärie alphazähne zweck"}},{q="Wo findet man Präriewolfalphatiere in Mulgore?",a="Präriewolfalphatiere durchstreifen die nördlichen Ebenen von Mulgore und schleichen gewöhnlich durch das Grasland rund um den Fuß von Donnerfels.",al={"präriewolf alpha ort","wo prärie alphas finden"}},{q="Wer stellt das Totem her?",a="Mull Donnerhorn, ein im Dorf der Bluthufe stationierter Ältester und Seher, fertigt jedes reinigende Totem an, nachdem ein Initiant die erforderlichen Opfergaben gesammelt hat.",al={"wer stellt das totem her","totem questgeber"}},{q="Was folgt auf die Herstellung des Wildmane-Totems?",a="Sobald Mull Donnerhorn das Totem aus den Alphazähnen zusammengefügt hat, werdet Ihr damit nach Norden geschickt, um die eigentliche Reinigung am Wildmane-Brunnen durchzuführen.",al={"was kommt danach","totem der wildmähnen folgequest"}},{q="Wie spiegelt dieses Ritual den Glauben der Tauren wider?",a="Die Tauren betrachten das Nehmen eines tierischen Lebens als feierlichen Austausch mit der Natur. Mull erkennt das Opfer der Wölfe sowohl mit Trauer über ihren Tod als auch mit Stolz auf ihre Rolle bei der Heilung der Erde an.",al={"tauren philosophie totem","mull donnerhorn überzeugungen"}}},fx={["054e923c"]={q="Warum möchte Mull Donnerhorn, dass das Wildmane Totem hergestellt wird?",a="In Mulgore muss nur noch ein korrumpierter Brunnen gereinigt werden – derjenige, der zum Wildmähnen-Clan gehört. Mull Donnerhorn hat sich der Reinigung der heiligen Brunnen der Erdenmutter verschrieben, und die Herstellung dieses letzten Läuterungstotems unter Verwendung des Raubtiergeistes des Landes ist wesentlich für den Abschluss des heiligen Ritus und die Wiederherstellung von reinem Wasser für den Stamm.",al={"warum mull wildmane totem will","mull donnerhorns motiv","warum wildmane totem herstellen"}},["2aa23a29"]={q="Wofür wird der Präriealphazahn verwendet?",a="Die Zähne des Präriewolf-Alphas repräsentieren das Opfer und die wilde Vitalität der Spitzenprädatoren von Mulgore. Mull Donnerhorn bindet acht dieser Reißzähne in das Wildmane Totem, damit dessen Geist die natürliche Ordnung besänftigen und das Ritual stärken kann, das benötigt wird, um die Verderbnis aus dem Brunnen der Wildmähnen zu tilgen.",al={"nutzung präriealphazahn","wofür sind präriealphazähne","zähne für wildmane totem"}},eb5f4bd0={q="Warum jagt Ihr Präriewolf-Alphas?",a="Ihr werdet ausgesandt, um Präriewolf-Alphas zu jagen, die dominanten Rudelführer, die die Ebenen rund um die Basis von Donnerfels durchstreifen. Ihre Stärke und Wildheit verkörpern das natürliche Gleichgewicht der Ebenen und liefern die wirkungsvolle Essenz, die Mull Donnerhorn für das letzte Wasser-Reinigungsritual benötigt.",al={"warum präriewolf-alphas töten","ziel präriewolf-alpha","hinter wem seid ihr her"}}},fp="14,272,14.339.0,23.367.0,21.277.0,38.141.0,55.192.0,47.130.0,21.146.0,48.147.0,44.199.0"}
P.entries["quest:76"] = {n="Die Jaspismine",s="Nach der Entdeckung, dass Kobolde die Tiefenschachtmine überrannt haben, beauftragt Marschall Dughan Späher damit, die weiter östlich gelegene Jaspismine zu untersuchen. Das Erreichen des Ortes bestätigt das Schlimmste: Der Befall hat sich über Elwynns lebenswichtige Mineraladern ausgebreitet und überfordert die verbliebenen Verteidiger von Sturmwind maßlos.",h="Nach der Entdeckung, dass Kobolde die Tiefenschachtmine überrannt haben, beauftragt Marschall Dughan Späher...",kw={"azora","dughan","elwynn","fargodeep","goldhain","jasperlode","kobold","mine","späher"},ang={["faction:Alliance"]="Der gleichzeitige Verlust von Fargodeep und Jasperlode offenbart, wie fragil Sturmwinds Kerngebiete in Ermangelung zentraler königlicher Unterstützung geworden sind.",["profession:Mining"]="Für einen Bergmann ist es ein bitterer Anblick, reiche unterirdische Adern von Ungeziefer überrannt zu sehen. Jasperlodes Stollen bergen wertvolle Vorkommen, doch um sie abzubauen, muss man sich durch Schwärme revierbesessener Kobolde kämpfen.",["race:Human"]="Menschliche Späher erleben den schleichenden Zusammenbruch von Elwynns ländlicher Infrastruktur aus erster Hand, während die Ressourcen der Grenzgebiete direkt vor den Toren der Hauptstadt verloren gehen."},sec={{t="Ein zweiter Einfall",b="Nachdem Beweise dafür gesichert wurden, dass Kobolde die Tunnel der Tiefenschachtmine südlich von Goldhain überschwemmt hatten, fürchtete Marschall Dughan, dass dieser Befall kein Einzelfall war. Die Jaspismine, eingebettet in die felsigen Ausläufer nordöstlich des Turms von Azora, stellt eine weitere entscheidende Quelle für Rohstein und Metall für das Königreich dar. Da er keine regulären Wachen von Sturmwind von der Patrouille in der Stadt abziehen kann, verlässt sich Dughan auf unabhängige Abenteurer, die nach Osten vordringen und bestätigen sollen, ob auch dieser Ort den kerzentragenden unterirdischen Plagen anheimgefallen ist."},{t="Überdehnte Verteidigung",b="Die Aufklärung tief in den Kammern von Jasperlode offenbart, dass Kobolde die menschlichen Bergleute vollständig verdrängt haben, indem sie sich eingegraben und die finsteren Gänge befestigt haben. Für Marschall Dughan ist dieser finstere Bericht ein weiterer Schlag in einer eskalierenden Krise. Da König Varian Wrynn verschollen ist und königliche Truppen den abgelegenen Gebieten vorenthalten werden, fehlt es der örtlichen Garnison an den nötigen Truppenstärken, um die Minen zu säubern, was das Herz des Königreichs wirtschaftlich aushungert und geografisch einengt."}},faq={{q="Wo befindet sich die Jaspismine?",a="Die Mine liegt in den nördlichen Ausläufern des östlichen Walds von Elwynn. Um sie zu erreichen, reist auf der Hauptstraße an Goldhain vorbei nach Osten, bis Ihr den Turm von Azora erreicht, und wendet Euch dann nach Norden in die Hügel.",al={"wo ist jasperlode","jaspismine standort","wie man jasperlode findet"}},{q="Warum benötigt Marschall Dughan einen Späher, anstatt Wachen zu entsenden?",a="Die Wache von Sturmwind in Elwynn ist aufgrund des politischen Stillstands in der Hauptstadt und des Verschwindens von König Varian Wrynn personell stark unterbesetzt. Da die örtlichen Truppen vollauf damit beschäftigt sind, Höfe und Städte vor Banditen und Gnollen zu schützen, muss sich Marschall Dughan auf zivile Späher verlassen.",al={"warum abenteurer entsenden","warum keine wache von sturmwind","wo sind die wachen"}},{q="Warum übernehmen Kobolde Elwynns Minen?",a="Kobolde sind von Natur aus Höhlengräber, die sich von unterirdischen Mineraladern und feuchten Höhlen angezogen fühlen. Als die militärische Präsenz von Sturmwind schwand, wurden die Kreaturen kühner und drängten aggressiv in von Menschen betriebene Ausgrabungsstätten wie Tiefenschacht und Jasperlode, um Gold, Erz und Territorium für sich zu beanspruchen.",al={"warum kobolde in jasperlode","was wollen kobolde","grund für koboldplage"}},{q="Was geschieht nach der Erkundung der Jaspismine?",a="Sobald Ihr Marschall Dughan über den Fall von Jasperlode Bericht erstattet, erkennt er die düstere Realität an, dass Elwynn an mehreren Fronten belagert wird. Da die östlichen Minen nun bestätigt verloren sind, richtet sich seine Aufmerksamkeit auf das westliche Elwynn, wo die Weststromgarnison unter starkem Druck durch die Flusstatzengnolle steht.",al={"wie geht es nach jasperlode weiter","folgequest jasperlode"}},{q="Warum ist der Verlust der Jaspismine für Sturmwind von Bedeutung?",a="Die Minen von Elwynn liefern Roherz und Stein, die für den Erhalt von Sturmwinds Wirtschaft sowie das Schmieden von Waffen und Rüstungen benötigt werden. Der Verlust sowohl der Tiefenschachtmine als auch der Jaspismine bringt den Mineralabbau zum Stillstand und beeinträchtigt die Erholungsbemühungen des Königreichs empfindlich.",al={"warum jasperlode wichtig ist","bedeutung von jasperlode"}},{q="Wem gehört der nahegelegene Turm von Azora?",a="Der Turm von Azora ist ein kleiner Magierturm an der östlichen Straße im Wald von Elwynn, der von Theocritus, dem Erzmagier von Azora, geleitet und von den Dienern von Azora betrieben wird. Er dient Reisenden als Orientierungspunkt auf dem Weg in die östlichen Ausläufer.",al={"was ist der turm von azora","wer lebt im turm von azora"}}},fx={a973508b={q="Warum möchte Marschall Dughan, dass die Jaspismine erkundet wird?",a="Nachdem bereits bestätigt wurde, dass Kobolde die The Fargodeep Mine überrannt haben, fürchtet Marschall Dughan, dass der Befall kein isolierter Vorfall ist. Er muss wissen, ob sich die Bedrohung auch nach Osten zur Jaspismine ausgebreitet hat. Die Sicherung der Ressourcenversorgung von Elwynn und das Verständnis des vollen Ausmaßes der heraufziehenden Gefahr sind entscheidend für die Verteidigung der Ortschaft Goldhain und den Schutz der wichtigen Handelsrouten von Sturmwind.",al={"dughans motiv jaspismine","warum jaspismine auskundschaften","warum muss dughan jaspismine untersucht haben"}}},fp="19,132,18.387.0,21.391.0,37.177.0,63.237.0,43.203.0,48.235.0,60.196.0,35.231.0"}
P.entries["quest:760"] = {n="Wildmähnensäuberung",s="Wildmähnensäuberung bildet den Höhepunkt der rituellen Bemühungen der Tauren, die lebenswichtigen Wasserstellen von Mulgore zu reinigen. Von Mull Donnerhorn im Dorf der Bluthufe beauftragt, bringen Helden das fertige Totem der Wildmähnen nach Norden, um den letzten vergifteten Brunnen zu läutern. Das Zurückdrängen der Schadstoffe der Goblins stellt das Gleichgewicht der Ebenen wieder her und sichert die traditionelle Lebensgrundlage der Taurenstämme.",h="Wildmähnensäuberung bildet den Höhepunkt der rituellen Bemühungen der Tauren, die lebenswichtigen...",kw={"dorf der bluthufe","säuberung","erdenmutter","mulgore","mull donnerhorn","totem","venture company","wasserbrunnen","wildmane"},ang={["class:Druid"]="Die Beseitigung der Umweltzerstörung durch die Goblins spiegelt direkt den cenarischen Auftrag wider, verheerte Ökosysteme zu heilen und fruchtbare Weiden zu schützen.",["class:Shaman"]="Der Einsatz ritueller Totems zur Beseitigung mechanischer Verschmutzung veranschaulicht die schamanische Pflicht, die Harmonie zwischen den natürlichen Elementen und den lebenden Gemeinschaften zu wahren.",["race:Tauren"]="Die Wiederherstellung der drei uralten Brunnen von Mulgore ist ein grundlegender Übergangsritus, der die Hingabe eines jungen Kriegers an die Bewahrung der Gaben der Erdenmutter beweist."},sec={{t="Die Reinigung der Gabe der Erdenmutter",b="Wasser ist das heilige Lebenselixier in den sonnenüberfluteten Ebenen von Mulgore, das die Herden, den Boden und die nomadischen Stämme erhält, die sich unlängst um Donnerfels gesammelt haben. Als die Venture Company und vordringende Goblins begannen, dieses Grundwasser mit giftigen Industrieabwässern zu verseuchen, erkannten die Ältesten der Tauren eine existenzielle Bedrohung. Nach der Reinigung der Brunnen der Winterhufe und Thunderhorn ist der Brunnen der Wildmähnen die dritte und letzte verdorbene Stätte, die spirituelles Eingreifen erfordert."},{t="Das Totem der Wildmähnen",b="Aus bestimmten Elementen gefertigt, die in der gesamten Region gesammelt wurden, kanalisiert das Läuterungstotem der Wildmähnen die wiederherstellende Kraft der Ahnengeister und der elementaren Erde. Das Aufstellen des Totems neben den fauligen Gewässern nördlich von Donnerfels zerstreut die üblen Chemikalien, zieht die Giftstoffe heraus und belebt den natürlichen Fluss. Durch den Abschluss des Rituals bewahren die Tauren ihr Volk vor Krankheiten und senden eine unmissverständliche Botschaft, dass die Schändung ihres heiligen Landes nicht geduldet wird."}},faq={{q="Warum wurde der Brunnen der Wildmähnen vergiftet?",a="Die Unternehmungen der Goblins, angetrieben von industrieller Gier und Holzfällerei, leiteten üble Gifte und chemische Abfälle in Mulgores unterirdische Gewässer, was die einheimische Tierwelt und die Stammeslager gleichermaßen bedrohte.",al={"wer hat den brunnen vergiftet","warum ist der brunnen schmutzig","goblingift"}},{q="Wo befindet sich der Brunnen der Wildmähnen?",a="Der Brunnen der Wildmähnen liegt in den Ebenen direkt nördlich der hoch aufragenden Mesas von Donnerfels.",al={"wildmane brunnen ort","wo ist der wildmane brunnen","wildmane brunnen finden"}},{q="Wer leitet dieses Reinigungsritual ein?",a="Mull Donnerhorn, ein Ältester im Dorf der Bluthufe, leitet Euch bei der Erschaffung der Totems an und schickt Euch aus, um die Brunnen zu reinigen.",al={"wer vergibt säuberung von wildmane","questgeber","mull donnerhorn ort"}},{q="Welche anderen Brunnen sind Teil dieser Reinigungsbemühungen?",a="Der Brunnen von Wildmane ist der dritte in einer Reihe von drei lebenswichtigen Wasserquellen, nach dem Brunnen der Winterhufe und dem Brunnen der Donnerhörner, die beide weiter südlich liegen.",al={"andere brunnen","mulgore brunnen","winterhoof thunderhorn brunnen"}},{q="Wie funktioniert das Säuberungstotem?",a="Das Totem ist von Ahnenmagie und gereinigten Naturelementen erfüllt und leitet wiederherstellende spirituelle Energie in den Grundwasserspiegel, um die Schadstoffe der Goblins zu neutralisieren.",al={"mechanik des säuberungstotems","wie reinigt das totem wasser"}},{q="Was bedeutet der Abschluss dieses Rituals für das Dorf der Bluthufe?",a="Die Säuberung der drei Brunnen garantiert allen Stämmen in Zentralmulgore sicheres Trinkwasser und erfüllt die heilige Pflicht der Tauren, die Erdenmutter von industrieller Ausbeutung zu heilen.",al={"ausgang der quest","warum die brunnen säubern","bedeutung tauren lore"}}},fx={["119d5a48"]={q="Warum möchte Mull Donnerhorn, dass der Brunnen der Wildmähnen gereinigt wird?",a="Mull Donnerhorn wacht über das spirituelle Gleichgewicht und die lebenswichtigen Ressourcen von Mulgore. Die üblen Operationen der Venture Company vergifteten die kostbaren Wasserquellen des Landes und bedrohten das Überleben der Stämme und ihrer Herden. Der Brunnen der Wildmähnen ist der letzte der drei alten Brunnen, die noch verseucht sind, und seine Reinigung ist unerlässlich, um die Erdenmutter zu heilen und sicheres Trinkwasser für das Dorf der Bluthufe und Donnerfels zu sichern.",al={"mull donnerhorns motiv","warum brunnen der wildmähnen reinigen","warum liegen mull die brunnen am herzen"}},b4cee6a1={q="Was ist das Läuterungstotem der Wildmähnen?",a="Das Läuterungstotem der Wildmähnen ist ein rituell vorbereitetes Hilfsmittel, das von Mull Donnerhorn gefertigt wurde, um Ahnen- und Erdgeister zu kanalisieren. Wenn es am verseuchten Brunnen der Wildmähnen nördlich von Donnerfels aktiviert wird, stößt das Totem den giftigen Schlamm aus, der von Goblin-Umweltverschmutzern hinterlassen wurde, reinigt den Grundwasserleiter und versetzt die Quelle in ihren natürlichen, ursprünglichen Zustand zurück.",al={"nutzung läuterungstotem der wildmähnen","was ist das wildmane totem","zweck läuterungstotem"}}},fp="18,371,33.509.0,18.481.0,41.206.0,41.104.0,36.139.0,54.153.0,34.166.0,60.179.0"}
P.entries["quest:761"] = {n="Sturzfliegerjagd",s="Sturzfliegerjagd ist ein Ritus des Fährtenlesens und der Treffsicherheit, der von Harken Windtotem im Dorf der Bluthufe angeboten wird. Um ihre Schläue und Geduld unter Beweis zu stellen, werden Jäger und Reisende herausgefordert, den schwer fassbaren Vögeln über die wogenden Ebenen von Mulgore nachzustellen. Mit ihren makellosen Trophäenkielfedern zurückzukehren, beweist sowohl Hingabe an die Jagd als auch Respekt vor den natürlichen Prüfungen der Erdenmutter.",h="Sturzfliegerjagd ist ein Ritus des Fährtenlesens und der Treffsicherheit, der von Harken Windtotem im Dorf...",kw={"dorf der bluthufe","harken windtotem","mulgore","sturzflieger","sturzfliegerjagd","tauren prüfung","trophäensturzfliegerkiel"},ang={["class:Druid"]="Das Verfolgen von Sturzfliegern über die windgepeitschten Hochebenen bringt Druiden in engere Verbindung mit den Raubvögeln, die das Gleichgewicht an Mulgores Himmel aufrechterhalten.",["class:Hunter"]="Die Jagd bietet eine frühe Lehrstunde darin, fliegende Beute im Blick zu behalten, Verhaltensmuster einzuschätzen und präzise Schläge gegen wachsame Raubtiere auszuführen.",["race:Tauren"]="Für taurische Heranwachsende und Wanderer ist die Jagd auf die schnellen Sturzflieger von Mulgore ein ehrwürdiger Übergangsritus, der die Fährtenleserinstinkte schärft und althergebrachte Jagdbräuche hochhält."},sec={{t="Eine Prüfung scharfer Augen",b="Die grasbewachsenen Steppen von Mulgore wimmeln von Bestien, doch nur wenige stellen die Instinkte eines Verfolgers so auf die Probe wie der einheimische Sturzflieger. Diese großen Raubvögel verschmelzen nahtlos mit dem Horizont und den Ebenen, während sie über einem kreisen oder knapp über das hohe Gras hinweggleiten. Anders als schwerfällige Ebenenschreiter oder grasende Kodos erfordern Sturzflieger höchste Konzentration und flinke Füße, um sie einzuholen, was ihre Jagd zu einer traditionellen Bewährungsprobe für jüngere Jäger macht, die sich ihr Ansehen unter den Stämmen verdienen wollen."},{t="Abzeichen der Jagd",b="Für Harken Windtotem geht es beim Sammeln von Trophäenkielfedern weniger um das Ausdünnen der Tierwelt als vielmehr um das Fördern von Disziplin. In der Kultur der Tauren bedeutet das Tragen von Trophäen einer hart erkämpften Pirsch Schläue und Ausdauer. Den Ältesten im Dorf der Bluthufe diese unversehrten Kielfedern zu präsentieren, zeichnet einen Abenteurer als fähig aus, die Gemeinschaft zu ernähren und zu verteidigen, und beweist, dass seine Hufe schnell und seine Sinne scharf genug sind, um die weite Welt zu meistern."}},faq={{q="Was ist der Zweck der Sturzfliegerjagd für Harken Windtotem?",a="Harken Windtotem beauftragt Jäger damit, Sturzflieger durch Mulgore zu verfolgen, um ihre Schläue, Schnelligkeit und Hingabe zu prüfen. Das Zurückbringen intakter Trophäenkielfedern dient als anerkannter Beweis für das Geschick eines Jägers und bringt Ehre unter den Tauren des Dorfes der Bluthufe ein.",al={"warum sturzflieger jagen","harken windtotem quest zweck","sturzfliegerjagd zweck"}},{q="Wo trifft man typischerweise auf Sturzflieger?",a="Sturzflieger sind über die gesamten offenen Ebenen von Mulgore verteilt zu finden, wo sie über den Prärien kreisen oder außerhalb von Siedlungen wie dem Dorf der Bluthufe das Gras nach Beute absuchen.",al={"wo sind sturzflieger","sturzflieger orte mulgore","sturzflieger finden"}},{q="Warum gilt die Jagd auf Sturzflieger als knifflig?",a="Anders als Herdentiere, die gemeinsam über das Flachland ziehen, sind Sturzflieger schnelle, wachsame Raubvögel, die weit verstreut und aufmerksam bleiben. Ihnen nachzustellen, erfordert scharfe Augen, um ihre Flugbahnen zu erkennen, und schnelle Schritte, um sie zur Strecke zu bringen, bevor sie entkommen.",al={"warum sind sturzflieger schwer zu fangen","sturzflieger verhalten"}},{q="Was bedeuten die Trophäenkielfedern für die Tauren?",a="In den Traditionen der Tauren stehen Trophäensturzfliegerkielfedern für Geduld, scharfe Augen und eine erfolgreiche Jagd. Sie vorzuweisen zeigt, dass ein Jäger die nötigen Instinkte besitzt, um für den Stamm zu sorgen und ihn zu beschützen.",al={"trophäensturzfliegerkielfeder bedeutung","bedeutung von kielfedern"}},{q="Wer ist Harken Windtotem?",a="Harken Windtotem ist ein angesehener Bewohner des Dorfes der Bluthufe aus den Reihen der Tauren, der Neuankömmlinge und angehende Jäger beobachtet und ihren Einfallsreichtum durch traditionelle Prüfungen in den Ebenen bewertet.",al={"wer vergibt sturzfliegerjagd","harken windtotem lore"}},{q="Beeinträchtigt diese Jagd das Gleichgewicht der Natur in Mulgore?",a="Die Tauren betrachten die Jagd als heiligen Dialog mit der Erdenmutter und nicht als wahlloses Abschlachten. Das Sammeln von Kielfedern ist eine maßvolle Prüfung der Disziplin, die die Klugheit der Beute ehrt und gleichzeitig das Stammesgleichgewicht wahrt.",al={"ist sturzfliegerjagd überjagung","sturzflieger gleichgewicht mulgore"}}},fx={["0d785fcd"]={q="Warum schickt Harken Windtotem einen Außenstehenden, anstatt selbst Swoops zu jagen?",a="Harken Windtotem schickt Euch nicht, weil er nicht jagen kann, sondern um Euren Wert zu testen. Für Tauren erfordert das Verfolgen der listigen Swoops über die Ebenen scharfe Augen, Geduld und schnelle Hufe. Indem er Euch die Aufgabe überträgt, ihre Federn zurückzubringen, gibt Harken Euch die Gelegenheit, Euer Können und Eure Entschlossenheit im Dorf der Bluthufe unter Beweis zu stellen und zu zeigen, dass Ihr ein Jäger von echtem Wert seid.",al={"warum schickt man mich swoop jagen","warum braucht harken mich","warum kann harken keine swoops jagen"}}},fp="13,385,19.466.0,18.451.0,59.252.0,39.172.0,41.246.0,48.215.0,24.192.0,55.222.0"}
P.entries["quest:762"] = {n="Ein Botschafter des Bösen",s="Historiker Karnik möchte, dass Botschafter Infernus aus der Festung Angor zur Strecke gebracht wird. Ihr sollt in das Ödland zurückkehren und Berater Belgrum in Eisenschmiede den Beweis für die Tötung überbringen.",h="Historiker Karnik möchte, dass Botschafter Infernus aus der Festung Angor zur Strecke gebracht wird.",kw={"berater belgrum","botschafter infernus","festung angor","ödland","historiker karnik","eisenschmiede","ragnaros","shadowforge","uldaman"},sec={{t="Der Botschafter in der Festung Angor",b="Ragnaros selbst entsandte Botschafter Infernus zur Festung Angor, um die Shadowforge zu beaufsichtigen, während sie in Uldaman nach verlorenen Artefakten suchen. Der Blutzoll an Zwergenleben war bereits schwer und wird immer schlimmer. Karnik wagt nicht zu vermuten, wie viele Artefakte die Shadowforge finden und gegen Eisenschmiede einsetzen könnten. Ihr sollt in das Ödland zurückkehren, Infernus vernichten und Belgrum den Beweis Eures Sieges bringen. Die Zeit drängt, da Ragnaros nicht darauf warten wird, dass sie sich vorbereiten."},{t="Belgrums Dank",b="Belgrum lobt Eure Hingabe an Eisenschmiede und das Zwergenvolk und wird Karnik Nachricht von Eurem Erfolg zukommen lassen. Es wird auch Hilfe in das Ödland geschickt, um die Ausgrabungsstätte zurückzuerobern. Belgrum hat im Namen von König Bronzebeard noch eine weitere Bitte an Euch."}},faq={{q="Wer ist Botschafter Infernus?",a="Ragnaros selbst entsandte Infernus zur Festung Angor, um die Shadowforge zu beaufsichtigen, während sie in Uldaman nach verlorenen Artefakten suchen.",al={"wer ist infernus","infernus lore","hintergrund botschafter infernus"}},{q="Wo ist Botschafter Infernus?",a="In der Festung Angor im Ödland.",al={"wo man botschafter infernus findet","aufenthaltsort von botschafter infernus","wo ist infernus"}},{q="Warum möchte Karnik, dass Botschafter Infernus vernichtet wird?",a="Die Suche der Shadowforge in Uldaman hat bereits viele Zwergenleben gekostet, und Karnik fürchtet, dass die Artefakte, die sie finden, gegen Eisenschmiede eingesetzt werden könnten.",al={"warum botschafter infernus getötet werden soll","was infernus in uldaman macht","bedrohung eisenschmiede ödland"}},{q="Wer vergibt und beendet diese Quest?",a="Historiker Karnik in Eisenschmiede vergibt sie, und Ihr bringt den Beweis des Sieges zu Berater Belgrum in Eisenschmiede.",al={"wer startet an ambassador of evil","wer beendet an ambassador of evil","questgeber an ambassador of evil"}},{q="Welcher Beweis wird verlangt?",a="Botschafter Infernus' Armschienen, die Berater Belgrum als Beweis Eures Sieges vorgelegt werden.",al={"was von infernus benötigt wird","beweis botschafter infernus","infernus armschienen"}}},fp="21,169,32.452.0,16.254.1,27.119.0,29.35.0,51.146.0,30.103.0,21.79.0"}
P.entries["quest:763"] = {n="Riten der Erdenmutter",s="Riten der Erdenmutter markiert den Übergang eines jungen Tauren aus der abgelegenen Hochwolkenebene in die weiten Ebenen von Mulgore. Nachdem Ihr Euren Mut in Camp Narache bewiesen habt, schickt Euch Häuptling Falkenwind mit einem geschnitzten Totem nach Norden ins Dorf der Bluthufe, um die uralten Prüfungen unter Baine Bluthuf fortzusetzen.",h="Riten der Erdenmutter markiert den Übergang eines jungen Tauren aus der abgelegenen Hochwolkenebene in die...",kw={"baine bluthuf","dorf der bluthufe","cairne bluthuf","camp narache","häuptling falkenwind","mulgore","riten der erdenmutter","falkenwinds totem"},ang={["faction:Horde"]="Die traditionellen Riten stärken die Einheit des Stammes in ganz Mulgore und stellen sicher, dass neue Verteidiger der Horde sowohl über kriegerisches Können als auch über eine tiefe spirituelle Erdung verfügen.",["race:Tauren"]="Jeder junge Tauren muss den Pfad der Erdenmutter beschreiten, um den Ältesten seinen Wert zu beweisen und seinen Platz unter den vereinten Stämmen zu finden."},sec={{t="Das Verlassen der Mesa",b="Seit Generationen stellen junge Tauren ihre Stärke in der sicheren Wiege von Camp Narache auf der Hochwolkenebene auf die Probe. Das Bestehen der anfänglichen Prüfungen beweist, dass man die Disziplin und die Entschlossenheit besitzt, um zu überleben, doch die heiligen Riten der Erdenmutter verlangen weit mehr als das Überleben gegen die heimische Tierwelt. Häuptling Falkenwind erkennt, wann ein Initiand den geschützten Jagdgründen der Mesa entwachsen ist und in die größere Gemeinschaft eintreten muss."},{t="Ein Zeichen für Baine",b="Um die Reise zwischen Narache und den zentralen Siedlungen zu überbrücken, übergibt Euch Häuptling Falkenwind ein handgeschnitztes Totem als Zeichen der Vorstellung. Während Ihr dieses Emblem den gewundenen Pfad hinab ins Dorf der Bluthufe tragt, stellt Ihr Euch Baine Bluthuf vor, dem jungen Häuptling des Dorfes und Sohn des Obersten Häuptlings Cairne Bluthuf. Das Totem dient als Zeugnis Eurer Bereitschaft für die Riten des Geistes und der Weisheit, die vor Euch liegen."}},faq={{q="Was ist der Zweck dieser Quest?",a="Sie dient als Übergangsritus, der Euch aus dem Startgebiet von Camp Narache herausführt und Euch ins Dorf der Bluthufe leitet, wodurch Ihr mit dem nächsten Kapitel der zeremoniellen Prüfungen der Tauren verbunden werdet.",al={"warum riten der erdenmutter machen","was macht diese quest","zweck der quest"}},{q="Wer ist Baine Bluthuf?",a="Baine Bluthuf ist der Sohn des Obersten Häuptlings Cairne Bluthuf. Er führt das Dorf der Bluthufe an und dient als angesehener lokaler Häuptling, der die fortlaufenden geistigen und kriegerischen Prüfungen der jungen Tauren beaufsichtigt.",al={"wer ist baine","baine geschichte","sohn von cairne"}},{q="Was ist Falkenwinds Totem?",a="Es ist ein von Häuptling Falkenwind aus Camp Narache handgeschnitztes Holz-Totem. Es dient als offizielles Beglaubigungsschreiben und Siegel der Anerkennung, das Baine Bluthuf beweist, dass Ihr Euch Hawkwinds Segen verdient habt, um weitere Riten aufzunehmen.",al={"falkenwinds totem","hawkwinds totem","geschnitztes totem"}},{q="Welche Riten folgen danach?",a="Nach Eurer Ankunft im Dorf der Bluthufe und dem Treffen mit Baine erhaltet Ihr die Aufgabe für den Ritus der Vision, der Eure spirituelle Einstimmung durch heilige Ahnenvisionen auf die Probe stellt.",al={"nächste riten","was kommt danach","nächste quest"}},{q="Wo liegt das Dorf der Bluthufe?",a="Das Dorf der Bluthufe liegt nördlich von Camp Narache an den Ufern des Stonebullsees im zentralen Mulgore. Reisende müssen lediglich der Hauptstraße von der Mesa hinab nach Norden folgen.",al={"wo liegt bloodhoof","wie man bloodhoof findet","weg nach bloodhoof"}},{q="Warum müssen die Riten der Erdenmutter abgeschlossen werden?",a="Die Riten der Erdenmutter sind zutiefst heilige Traditionen unter den Tauren. Das Bestehen aller Stufen der Riten beweist körperliche Stärke, spirituelle Verbundenheit und Weisheit und bringt dem Initianden die wahre Anerkennung durch die Ältesten von Donnerfels ein.",al={"warum erdenmutter riten","zweck der tauren prüfungen","riten der erdenmutter geschichte"}}},fx={["4a33bb81"]={q="Warum schickt Euch Häuptling Falkenwind ins Dorf der Bluthufe?",a="Häuptling Falkenwind hat Euch durch die Einführungsprüfungen der Hochwolkenebene geführt, doch Camp Narache kann Euch nichts mehr lehren. Um die heiligen Rites of the Earthmother abzuschließen und die Anerkennung der Ältesten von Donnerfels zu gewinnen, müsst Ihr Eure Erfahrungen in den weiteren Ebenen von Mulgore erweitern. Indem er Euch mit seinem geschnitzten Totem zu Baine Bluthuf schickt, überträgt Falkenwind die Verantwortung für Euer spirituelles und körperliches Wachstum an einen Anführer, der Eure Bereitschaft für das wahre Erwachsenenalter testen kann.",al={"warum nach bloodhoof schicken","häuptling falkenwinds motiv","warum rites of the earthmother"}},["9c980781"]={q="Warum müsst Ihr das Totem selbst überbringen?",a="Die Reise ist kein Botengang, sondern ein wesentlicher Bestandteil Eures Initiationsritus. Die geschützten Grenzen der Hochwolkenebene zu verlassen und der offenen Straße nach Mulgore zu folgen, beweist Eure Unabhängigkeit und Ausdauer. Indem Ihr das Falkenwinds Totem mit Euren eigenen Händen überreicht, ermöglicht Ihr es Baine Bluthuf, Euch anzusehen, Falkenwinds persönliche Empfehlung, die in das Holz geschnitzt ist, zu erkennen und Euren Charakter aus erster Hand zu beurteilen.",al={"warum nehme ich das totem","warum kann falkenwind keinen boten schicken","warum ich für rites of the earthmother"}}},fp="24,305,16.421.0,17.420.0,34.199.0,23.201.0,30.219.0,27.170.0,35.185.0,44.246.0"}
P.entries["quest:764"] = {n="Die Venture Company",s="Die Untersuchung einer überfallenen Karawane der Venture Company in Mulgore bringt einen aggressiven Aufmarsch von Goblins der Venture Company ans Licht, die sich in die östlichen Hügel graben. Nachdem ihre offiziellen Anträge auf Schürfrechte rundweg abgelehnt worden waren, beschloss die Gesellschaft, die Erde der Erdenmutter dennoch abzubauen, was Morin Wolkenpirscher dazu veranlasste, eine tödliche Vergeltung in Auftrag zu geben.",h="Die Untersuchung einer überfallenen Karawane der Venture Company in Mulgore bringt einen aggressiven...",kw={"goblin","schürfrechte","morin wolkenpirscher","mulgore","überfallene karawane","venture co","mine der venture co","venture company"},ang={["faction:Horde"]="Die Verteidigung Mulgores gegen kommerzielle Ausbeutung festigt Eure Hingabe zum Schutz des Volkes von Cairne Bluthuf, während sie daran arbeiten, ihre neue Heimat zu sichern.",["profession:Mining"]="Die Venture Company operiert rein durch rücksichtslose Ausbeutung, spart an allen Ecken und destabilisiert das Land, ohne jede Rücksicht auf das natürliche Gleichgewicht oder sichere Bergbaukunst.",["race:Tauren"]="Für die Tauren ist die Erdenmutter heilig. Der Tagebau der Venture Company ist nicht nur Hausfriedensbruch, sondern eine gewaltsame Schändung ihrer angestammten Heimat, die eine sofortige, gewaltsame Vertreibung rechtfertigt."},sec={{t="Industrielles Eindringen",b="Die Tauren von Mulgore verehren das Land als eine Erweiterung der Erdenmutter und schätzen seine unberührten Ebenen und die ausgeglichene Tierwelt. Als die Venture Company an die Stämme herantrat, um Schürfrechte für Sprengungen und Ausgrabungen nach Roherz in den sanften Hügeln zu erbitten, wurden ihre Gesuche kategorisch abgewiesen. Unbeirrt von den Erlassen der Stämme oder territorialer Souveränität schmuggelte das unerbittliche Kartell schwere Maschinen, Arbeiter und Vorarbeiter direkt in Mulgores östliche Bergkämme, um dort illegalen Bergbau zu betreiben."},{t="Eine unmissverständliche Botschaft",b="Taurenkundschafter wie Morin Wolkenpirscher wissen, dass man geschäftlicher Gier mit diplomatischen Appellen nicht mehr beikommen kann, sobald die Hacken den Fels berühren. Gestützt auf Dokumente, die aus einer überfallenen Karawane der Venture Co. geborgen wurden und den Bergbaubetrieb der Gesellschaft belegen, entsendet Morin Champions der Horde, um sowohl die peitschenschwingenden Zuchtmeister als auch die Arbeiter an den Bohrern niederzustrecken. Dieser blutige Vergeltungsschlag soll der Venture Company vor Augen führen, dass der Preis für das unbefugte Betreten des Landes bei Weitem zu hoch ist."}},faq={{q="Warum ist die Venture Company in Mulgore?",a="Die Venture Company errichtete einen illegalen Außenposten samt Mine an den östlichen Hängen von Mulgore, um Mineralien und natürliche Ressourcen abzubauen. Nachdem die Tauren ihnen offizielle Schürfrechte verweigert hatten, ignorierte das Kartell die Autorität des Stammes und nahm den Betrieb trotzdem auf.",al={"warum sind goblins in mulgore","venture co mulgore motiv","was will die venture co"}},{q="Wer erteilte den Befehl zum Angriff auf die Bergleute?",a="Morin Wolkenpirscher, ein Taure, der nahe dem Dorf der Bluthufe Wache hält, erteilt diesen Befehl. Er betrachtet die Weigerung des Kartells, die Ablehnung des Stammes zu akzeptieren, als einen direkten Übergriff, der physische Gewalt statt weiterer Worte verlangt.",al={"wer vergibt diese quest","morin wolkenpirscher rolle","questgeber"}},{q="Wo befindet sich die Mine der Venture Company?",a="Die Hauptmine der Venture Company liegt in den Ausläufern östlich der Überfallenen Karawane und vom Dorf der Bluthufe. Eine kleinere Ansammlung von Mitarbeitern der Gesellschaft ist außerdem in einem Außenposten anzutreffen, der sich in die Klippen nordöstlich der nördlichen Aufzüge von Donnerfels schmiegt.",al={"standort der mine der venture co","wo sind die aufseher","wo findet man die venture co"}},{q="Haben die Tauren je versucht, mit den Goblins zu verhandeln?",a="Ja. Die Venture Company ersuchte die Tauren um formelle Schürfrechte in Mulgore. Die Stammesführer weigerten sich, ihnen den Tagebau auf ihrem angestammten Land zu gestatten, doch die Goblins entschieden sich kurzerhand dafür, einfach ohne Erlaubnis zu graben.",al={"haben tauren bergbau erlaubt","schürfrechte mulgore","haben goblins um erlaubnis gefragt"}},{q="Gehören diese Goblins zum Steamwheedle-Kartell?",a="Nein. Die Venture Company ist ein unabhängiges, notorisch räuberisches Industriekartell, das sich von neutralen Handelsgruppen wie dem Steamwheedle-Kartell unterscheidet. Wo immer sie Ressourcen ausbeuten, pflegen sie feindselige Beziehungen zur einheimischen Bevölkerung.",al={"sind das goblins aus ratschet","ist venture co freundlich","fraktion der venture company"}},{q="Wie hängt das mit den überfallenen Karawanen zusammen?",a="Die überfallene Karawane war ein Konvoi der Venture Company, der von den Tauren zerstört wurde. Die aus den Trümmern geborgenen Kisten und Dokumente der Bergbaudivision enthüllten die Operationen der Gesellschaft in Mulgore und veranlassten diesen Schlag gegen ihre Mine.",al={"karawanenverbindung","hat die venture co karawanen angegriffen","verbindung zu die überfallene karawane"}}},fx={f6df914e={q="Warum möchte Morin Wolkenpirscher, dass die Venture Company angegriffen wird?",a="Der Venture Company wurden offiziell die Bergbaurechte in Mulgore verweigert, doch sie ignorierten die Ablehnung und begannen ungeachtet dessen, Ausrüstung aufzubauen und Arbeiter einzusetzen. Morin Wolkenpirscher kann es nicht zulassen, dass sie das Land verwüsten und seine natürlichen Ressourcen ungehindert plündern. Da Diplomatie und direkte Ablehnungen ihre Gier nicht beeinflussen konnten, glaubt er, dass die Tauren eine unmissverständliche, nachdrückliche Botschaft übermitteln müssen, dass Hausfriedensbruch und Diebstahl nicht toleriert werden.",al={"morin wolkenpirschers motiv","warum venture company angreifen","warum will morin, dass venture company getötet wird"}},eda5096c={q="Gegen wen werdet Ihr ausgesandt, um in der Mine zu kämpfen?",a="Ihr werdet gegen die Aufseher und Arbeiter der Venture Company ausgesandt, die bei ihrer Bergbauoperation im östlichen Mulgore stationiert sind. Diese Goblins und angeheuerten Arbeiter graben tief in die heiligen Hügel, um die Erde ohne Erlaubnis des Stammes von Mineralien zu befreien, angeführt von profitorientierten Vorarbeitern, die die aggressive, illegale Expansion des Unternehmens durchsetzen.",al={"ziele der venture company quest","wer sind die arbeiter der venture company","gegen wen kämpfe ich in der mine"}}},fp="15,339,20.472.0,23.485.0,38.269.0,40.215.0,42.253.0,54.219.0,50.237.0,46.224.0"}
P.entries["quest:765"] = {n="Vorsteher Zischelspross",s="Vorsteher Zischelspross ist ein hochrangiger Aufseher der Venture Company, der in den Minenstollen von Mulgore stationiert ist. Beauftragt von Morin Wolkenpirscher, den kalkulierten Plünderungen des Goblinschiffs ein Ende zu setzen, betreten Abenteurer der Horde die Mine, um ihn auszuschalten und sein detailliertes Klemmbrett zu bergen.",h="Vorsteher Zischelspross ist ein hochrangiger Aufseher der Venture Company, der in den Minenstollen von...",kw={"klemmbrett","fizsprocket","mine","morin wolkenpirscher","mulgore","vorsteher","venture co"},ang={["faction:Horde"]="Den Tauren gegen die vordringenden Plünderer des Konzerns beizustehen, festigt den Schutz der Horde über die neu beanspruchten Kernlande in Kalimdor.",["race:Tauren"]="Der offene Plan der Venture Company, Euren Stamm zu vertreiben und die heilige Erde auszuplündern, macht die Tötung von Fizsprocket zu einem Akt lebenswichtiger Gebietsverteidigung."},sec={{t="Ein Komplott gegen die Ebenen",b="Dokumente, die aus einer zerstörten Karawane der Venture Company geborgen wurden, enthüllten, dass die Venture Company nicht bloß nach Erz grub – sie schmiedete gezielt Pläne, die Tauren gänzlich aus Mulgore zu vertreiben. Durch die Entwurzelung der Einheimischen strebte das gierige Unternehmen ungehinderte Freiheit an, um die sanften Hügel und tiefen unterirdischen Adern jeder natürlichen Ressource zu berauben."},{t="Schlag gegen den Vorarbeiter",b="Morin Wolkenpirscher, erzürnt über die gegen sein Volk geplanten Gräueltaten des Unternehmens, schickt Recken in die Mine der Venture Company, die sich direkt östlich der zerstörten Handelswagen befindet. Tief in den rechten Tunneln versteckt und von Arbeitern sowie Unterbossen umgeben, leitet Vorsteher Zischelspross die Operationen. Fizsprocket niederzustrecken und sein Klemmbrett an sich zu nehmen, zerschlägt die lokale Koordination und liefert entscheidende Informationen über die zukünftigen Pläne der Gesellschaft."}},faq={{q="Wer ist Vorsteher Zischelspross?",a="Vorsteher Zischelspross ist ein Boss der Venture Company, der die Operationen in den Minenstollen im östlichen Mulgore leitet. Er beaufsichtigt die Arbeiter, die die Erde aufreißen, und führt die Strategien des Unternehmens aus, die darauf abzielen, ihre Aktivitäten in der gesamten Region auszuweiten.",al={"fizsprocket","wer ist fizsprocket","fizsprocket lore"}},{q="Warum will Morin Wolkenpirscher Fizsprocket tot sehen?",a="Morin entdeckte bei einer überfallenen Karawane Dokumente, die bewiesen, dass die Venture Company plante, die Tauren aus Profitgier aus ihrer angestammten Heimat zu vertreiben. Fizsprocket ist der direkte Aufseher, der diese kalkulierten Ausbeutungspläne ausführt.",al={"warum fizsprocket töten","motivation von morin wolkenpirscher"}},{q="Wo befindet sich Vorsteher Zischelspross?",a="Er befindet sich in der Mine der Venture Company direkt östlich von Die überfallene Karawane in Mulgore. Folgt im Inneren der Mine dem Tunnel ganz rechts zu einer Kammer, in der er inmitten von Arbeitern und Vorstehern steht.",al={"wo ist fizsprocket","standort fizsprocket mine","karte fizsprocket"}},{q="Welchen Beweis verlangt Morin für Fizsprockets Niederlage?",a="Morin Wolkenpirscher verlangt Fizsprockets persönliches Klemmbrett, das Geschäftsbücher und Aufzeichnungen enthält, die weitere Absichten der Venture Company in Mulgore aufdecken könnten.",al={"beweis des todes","fizsprockets klemmbrett"}},{q="Warum ist die Venture Company in Mulgore?",a="Die Venture Company ist ein skrupelloses Handelskartell, das darauf aus ist, unberührtes Land von Holz, Mineralien und wertvollen unterirdischen Reichtümern zu befreien, völlig ungeachtet der einheimischen Bewohner oder des ökologischen Gleichgewichts.",al={"venture co mulgore","warum sind goblins in mulgore"}},{q="Vertreibt der Tod von Fizsprocket die Venture Company vollständig?",a="Nein. Während Fizsprockets Ableben die lokale Führung empfindlich stört und Morin Wolkenpirscher lebenswichtige Notizen über ihre Pläne liefert, bleibt die Venture Company eine anhaltende Bedrohung, die sich in Mulgores Hügeln eingenistet hat.",al={"ist venture co fort","nach fizsprockets tod"}}},fp="22,298,25.371.0,21.456.1,30.251.0,50.232.0,40.207.0,54.160.0,38.219.0,67.204.0"}
P.entries["quest:766"] = {n="Mazzranach",s="Maur Regenrufer im Dorf der Bluthufe ist dem giftigen Biss von Mazzranach zum Opfer gefallen, einem legendären Schreiter, der schon vor einer Generation seinen Großvater terrorisierte. Von Fieber und fiebrigen Albträumen geplagt, benötigt der Taure ein wirksames Heilmittel aus der Tierwelt Mulgores, bevor die Infektion sein Leben fordert.",h="Maur Regenrufer im Dorf der Bluthufe ist dem giftigen Biss von Mazzranach zum Opfer gefallen, einem...",kw={"dorf der bluthufe","flachlandberglöwe","maur regenrufer","mazzranache","mulgore","schreiter","präriewolf","sturmvogel"},ang={["class:Hunter"]="Das Aufspüren von Präriewölfen, Berglöwen, Schreitern und Sturmvögeln in Mulgore bietet eine praktische Lektion darin, die Ebenen zu lesen und die besondere Tierwelt der Savanne zu verstehen.",["faction:Horde"]="Das Dorf der Bluthufe vor den rauen Gefahren Mulgores zu schützen, ist von entscheidender Bedeutung, um Frieden und Stabilität in der Heimat der Tauren zu sichern.",["race:Tauren"]="Das Heilmittel, das Maur herstellt, spiegelt den uralten Brauch der Tauren wider, Arzneien direkt aus der Flora und Fauna der Erdenmutter zu schöpfen."},sec={{t="Ein Erbe der Ebenen",b="Jahrelang hielt Maur Regenrufer Mazzranach für kaum mehr als eine schreckliche Familiengeschichte, die sein Großvater weitergegeben hatte. Der alte Taure sprach von einem ungewöhnlich wilden Schreiter mit glühend roten Augen, rasiermesserscharfen Krallen und einem giftigen Biss, der der friedlichen Natur der meisten Wildtiere Mulgores widersprach. Als Maur dem Biest auf dem offenen Grasland begegnete, erwies sich die Legende als allzu wahr; schwer verwundet schaffte er es nur mit Mühe zurück in Sicherheit."},{t="Wettlauf gegen die Infektion",b="Das Gift der Kreatur wirkt rasch und verursacht hohes Fieber sowie albtraumhafte Wahnvorstellungen. Um das Gift zu neutralisieren, bevor es tödlich endet, setzt die traditionelle Medizin der Tauren auf die Lebenskraft der einheimischen Tiere. Maur benötigt ein Präriewolfherz, den Oberschenkelknochen eines Flachlandberglöwen, eine Schreiterschuppe und einen Sturmvogelmuskelmagen. Durch die Kombination der Essenzen dieser unterschiedlichen Jäger und Aasfresser kann er ein Gebräu herstellen, das in der Lage ist, das Fortschreiten der Nekrose aufzuhalten und ihn wieder gesundzupflegen."}},faq={{q="Was ist Mazzranach?",a="Mazzranach ist ein berüchtigter Schreiter, der das Grasland von Mulgore durchstreift. Anders als gewöhnliche Schreiter ist er für sein leuchtendes Gefieder, dämonisch rote Augen, wilde Krallen und einen ungewöhnlich giftigen Biss bekannt. Er terrorisiert Reisende bereits über mehrere Generationen hinweg.",al={"wer ist mazzranache","welche art tier ist mazzranache","mazzranache geschichte"}},{q="Wer ist Maur Regenrufer?",a="Maur Regenrufer ist ein Taure, der im Dorf der Bluthufe lebt. Als er Mulgore durchquerte, wurde er von Mazzranach überfallen und in die Schulter gebissen, was ihn mit einer lebensbedrohlichen, giftigen Infektion ans Bett fesselte.",al={"maur regenrufer","wer vergibt diese quest","wer ist der kranke taure"}},{q="Warum benötigt Maur Teile von vier verschiedenen Tieren?",a="Traditionelle Heilmittel der Tauren nutzen die natürlichen Stärken und geistigen Essenzen der Steppentiere, um starke Gifte zu neutralisieren. Das Herz eines Wolfs, das dichte Mark eines Berglöwenknochens, eine Schreiterschuppe und der Muskelmagen eines Sturmvogels ergeben zusammen ein Gegengift, das stark genug ist, um Mazzranachs Gift entgegenzuwirken.",al={"warum wolfsherz berglöwenknochen","warum tierische zutaten","zutaten mazzranache heilmittel"}},{q="Hat Maurs Großvater Mazzranach getötet?",a="Nein. Maurs Großvater kämpfte vor Jahren gegen den wilden Schreiter, konnte ihn jedoch nicht besiegen. Er überlebte nur knapp und gab warnende Erzählungen über dessen leuchtende Farben und bösartige Angriffe an seine Nachkommen weiter.",al={"hat großvater mazzranache besiegt","maur großvater mazzranache","wer kämpfte früher gegen mazzranache"}},{q="Verlangt diese Quest, Mazzranach selbst zu jagen?",a="Nein. Maurs vordringlichste Priorität ist es, das Fieber zu überleben. Die Aufgabe konzentriert sich ganz auf das Sammeln der Komponenten, die für die Herstellung seines Heilmittels nötig sind, und nicht auf die Jagd nach dem legendären Vogel.",al={"töte ich mazzranache","wo ist mazzranache","mazzranache jagen"}},{q="Wo liegt das Dorf der Bluthufe?",a="Das Dorf der Bluthufe liegt im Herzen von Mulgore, südlich von Donnerfels und direkt östlich des Stonebullsees. Es dient als Hauptsiedlung für junge Krieger der Tauren, die in die weiten Ebenen aufbrechen.",al={"wo liegt bloodhoof","bloodhoof standort"}}},fx={["3b88d77e"]={q="Warum möchte Maur Regenrufer, dass dies getan wird?",a="Maurs Leben steht unmittelbar auf dem Spiel. Während er die Ebenen von Mulgore bereiste, kreuzte er den Weg von Mazzranache, einem legendären Prärieläufer, der bekanntermaßen seinen Großvater terrorisierte. Die Kreatur fügte Maur einen wilden, giftigen Biss in die Schulter zu. Ein schwächendes Fieber hat eingesetzt, das wahnsinnige Albträume verursacht und sich stetig in seinem Körper ausbreitet. Ohne die tierischen Zutaten, die für die Herstellung eines medizinischen Heilmittels benötigt werden, wird ihn die wütende Infektion bald töten.",al={"maur regenrufers motiv","warum maur regenrufer helfen","was ist mit maur passiert"}},ce37bf7e={q="Warum braucht Maur einen Außenstehenden, anstatt sich selbst zu heilen?",a="Maur ist zu schwer verletzt und fiebrig, um selbst die Bestien von Mulgore zu jagen. Mazzranaches giftiger Biss hat ihn mit Delirium und Erschöpfung außer Gefecht gesetzt und ihn an das Dorf der Bluthufe gefesselt. Da die Zeit knapp wird, bevor die Infektion tödlich endet, muss er sich auf vorbeiziehende Reisende verlassen, um die schnellen Pumas, Swoops, Wölfe und Prärieläufer aufzuspüren, die für sein Heilmittel benötigt werden.",al={"warum kann maur die teile nicht holen","warum braucht maur euch","warum ich für mazzranache"}}},fp="11,313,22.471.0,20.462.0,20.251.0,23.208.0,52.303.0,40.198.0,55.180.0,35.193.0"}
P.entries["quest:767"] = {n="Ritus der Vision",s="Der Ritus der Vision ist eine entscheidende Reifeprüfung im Rahmen der Riten der Erdenmutter, die die spirituelle Reife eines jungen Abenteurers auf die Probe stellt. Initiiert von Baine Bluthuf, weist die Quest Anwärter an, den Rat des Dorfsehers Zarlman Zwillingsmond einzuholen. Diese Reise anzutreten ist unerlässlich für jeden, der den Segen und den Respekt der Ältesten auf den Plateaus von Donnerfels erlangen möchte.",h="Der Ritus der Vision ist eine entscheidende Reifeprüfung im Rahmen der Riten der Erdenmutter, die die...",kw={"baine bluthuf","dorf der bluthufe","mulgore","ritus der vision","riten der erdenmutter","tauren prüfung","donnerfels","zarlman zwillingsmond"},ang={["class:Druid"]="Mit den Visionen der Erdenmutter in Zwiesprache zu treten, bekräftigt unmittelbar die druidische Berufung, aufmerksam auf die Weisheit und das Flüstern der lebendigen Welt zu lauschen.",["class:Shaman"]="Zarlman Zwillingsmond aufzusuchen und den Pfad der Visionen zu beschreiten, steht in tiefem Einklang mit der schamanischen Pflicht, weltliche Belange mit dem Willen der Ahnen ins Gleichgewicht zu bringen.",["faction:Horde"]="Das Durchführen dieser traditionellen heiligen Riten beweist Eure Loyalität und Eure kulturelle Ehrerbietung gegenüber den Ältesten der Tauren, die die Führung der Horde mitgestalten.",["race:Tauren"]="Der Ritus der Vision ist ein unverzichtbarer kultureller Meilenstein für jeden jungen Tauren und markiert Euren Übergang zu einem vertrauenswürdigen Verteidiger und Geisterwandler der Stämme."},sec={{t="Ein heiliger Meilenstein",b="Seit Generationen wenden sich die nomadischen Tauren an die Erdenmutter, um ihr Volk über die Ebenen von Kalimdor zu leiten. Nun innerhalb der sicheren Grenzen von Mulgore versammelt, bleiben ihre spirituellen Traditionen das Fundament ihrer Gesellschaft. Der Ritus der Vision ist eine der uralten Prüfungen, die als Riten der Erdenmutter bekannt sind. Während frühere Prüfungen die körperliche Stärke eines Initianten und seine Verbindung zur Jagd testen, verlangt der Ritus der Vision eine innere Reise, die junge Tauren und geehrte Verbündete dazu anleitet, direkt mit den Geistern in Zwiesprache zu treten."},{t="Die Führung des Sehers",b="Bevor eine spirituelle Vision gesucht werden kann, muss ein Initiant von jemandem vorbereitet werden, der von uralter Weisheit erfüllt ist. Im Dorf der Bluthufe fällt diese Verantwortung dem verehrten Schamanen Zarlman Zwillingsmond zu. Von Baine Bluthuf damit betraut, Reisende vorzubereiten, besitzt Zarlman den geschärften Blick, um jene zu erkennen, die den Pfad der Ahnen beschreiten, und reicht die vorbereitenden Riten und heiligen Vorkehrungen dar, die nötig sind, um den Schleier der physischen Welt zu durchdringen."}},faq={{q="Was ist der Ritus der Vision?",a="Der Ritus der Vision ist ein heiliges Ritual innerhalb der Riten der Erdenmutter. Er soll den spirituellen Blick eines Abenteurers weiten, ihm erlauben, mit Ahnengeistern in Zwiesprache zu treten, und seine spirituelle Reife vor den Ältesten von Donnerfels unter Beweis stellen.",al={"ritus der sicht quest","was ist ritus der sicht","ritus der sicht lore"}},{q="Wer beginnt diese Quest?",a="Die Quest wird von Baine Bluthuf vergeben, dem Sohn des Obersten Häuptlings Cairne Bluthuf. Baine wacht über das Dorf der Bluthufe und weist würdige Reisende an die spirituellen Ältesten des Dorfes weiter.",al={"wer vergibt ritus der sicht","ritus der sicht questgeber"}},{q="Wer ist Zarlman Zwillingsmond?",a="Zarlman Zwillingsmond ist ein erfahrener Taurenschamane und der spirituelle Anführer des Dorfes der Bluthufe. Er bereitet Reisende und Initianten vor, die sich heiligen Prüfungen wie dem Ritus der Vision unterziehen möchten.",al={"wer ist zarlman","zarlman two moons lore"}},{q="Warum sind die Riten der Erdenmutter für die Tauren wichtig?",a="Die Riten der Erdenmutter stellen einen traditionellen Übergangsritus für heranwachsende Tauren dar. Ihr erfolgreicher Abschluss zeugt von körperlicher Tüchtigkeit, spiritueller Einstimmung und einem beständigen Respekt vor dem Land, wodurch man sich die Ehre der hohen Ältesten verdient.",al={"riten der erdenmutter bedeutung","warum riten der erdenmutter"}},{q="Können Nicht-Tauren den Ritus der Vision bestreiten?",a="Ja. Verbündeten der Horde, die durch Mulgore reisen und das Vertrauen des Stammes der Bluthufe gewinnen, ist es gestattet, den Pfad der Erdenmutter zu beschreiten und so der taurischen Tradition Respekt zu erweisen, um im Gegenzug die Gunst der Ältesten zu erlangen.",al={"können orcs ritus der sicht machen","nicht tauren erdenmutter"}},{q="Wo findet diese Prüfung statt?",a="Die Prüfung beginnt im Dorf der Bluthufe, einer bedeutenden Taurensiedlung nahe den Ufern des Stonebullsees im zentralen Mulgore, südlich von Donnerfels.",al={"wo ist ritus der sicht","ritus der sicht ort"}}},fx={["1fa313da"]={q="Warum möchte Baine Bluthuf, dass Ihr die Rite of Vision unternehmt?",a="Baine Bluthuf bereitet Euch darauf vor, den Pfad Eurer Vorfahren zu beschreiten und Euren Wert für das Volk der Tauren zu beweisen. Wenn Ihr in Mulgore erwachsen werdet, müsst Ihr die heiligen Rites of the Earthmother unternehmen, um mit den Geistern zu kommunizieren, Ehrfurcht vor dem Land zu lernen und letztlich den Respekt der Ältesten in Donnerfels zu verdienen. Baine weist Euch an den Dorfmystiker Zarlman Zwillingsmond, damit Ihr die spirituelle Prüfung ordnungsgemäß beginnen könnt.",al={"warum schickt baine euch zur rite of vision","baine bluthufs motiv rite of vision","warum die rite of vision durchführen"}}},fp="14,381,23.535.0,19.443.0,27.255.0,22.205.0,25.190.0,61.255.0,44.208.0,33.154.0"}
P.entries["quest:768"] = {n="Leder sammeln",s="Leder sammeln ist eine unkomplizierte Handwerksanfrage von Veren Tallstrider auf den Anhöhen von Donnerfels. Um die Hauptstadt zu versorgen und junge Jäger auf die Probe zu stellen, tauscht Veren ein Bündel gegerbter leichter Lederhäute gegen gefertigte Waren ein. Dies unterstreicht die tief verwurzelte Tradition der Tauren, die Früchte der Jagd in den Ebenen in lebenswichtige Kleidung und Rüstung zu verwandeln.",h="Leder sammeln ist eine unkomplizierte Handwerksanfrage von Veren Tallstrider auf den Anhöhen von Donnerfels.",kw={"leder sammeln","lederverarbeitung","leichtes leder","mulgore","tauren jagd","donnerfels","veren tallstrider"},ang={["class:Hunter"]="Jäger, die sich in die Ebenen von Mulgore hinauswagen, sind von Natur aus geschickt darin, Beute aufzuspüren und die leichten Häute zu gewinnen, die Veren benötigt.",["faction:Horde"]="Die Versorgung der Handwerker in Donnerfels mit Rohstoffen stärkt die junge Hauptstadt, während sie ihre Verteidigung und Handelsnetze festigt.",["race:Tauren"]="Für Jäger der Tauren ist es eine lebenswichtige, über Generationen weitergegebene kulturelle Pflicht, das erlegte Tier zu ehren, indem man seine Haut zu nützlichen Waren verarbeitet."},sec={{t="Die Versorgung von Donnerfels",b="In der neu besiedelten Hauptstadt auf den hohen Mesas von Mulgore gehen Handwerkskunst und Überleben Hand in Hand. Veren Tallstrider verarbeitet Felle zu Kleidung und schützender Rüstung, die von der wachsenden Bevölkerung von Donnerfels benötigt werden. Anstatt alles selbst zu erlegen, ermutigt er junge Abenteurer, die in die Ebenen aufbrechen, ihre Beute mitzubringen, und verwandelt so die alltägliche Jagd in einen ehrenvollen Dienst an der Gemeinschaft."},{t="Der Weg der Jagd",b="Für die Tauren ist die Jagd auf Bestien in den Graslanden kein Sport; sie ist ein ehrenvolles Bestreben, das den Stamm ernährt, kleidet und schützt. Veren Tallstrider sucht nach Jägern, die danach streben, ihrem Clan Ehre zu erweisen, und verlangt ausdrücklich nach leichtem Leder, das der einheimischen Tierwelt abgezogen wurde. Im Austausch für zwölf gut erhaltene Häute belohnt er den Jäger mit robusten Waren und stärkt so die gegenseitige Unterstützung, die die Gesellschaft der Tauren zusammenhält."}},faq={{q="Wer ist Veren Tallstrider?",a="Veren Tallstrider ist ein Lederverarbeiter, der in Donnerfels lebt. Er stellt Kleidungsstücke sowie schützende Rüstungen für das Volk der Tauren her und tauscht seine fertigen Werke mit Jägern, die ihm frische Felle aus den Ebenen bringen.",al={"veren tallstrider","wer gibt leder sammeln","leder questgeber donnerfels"}},{q="Was benötigt Veren Tallstrider?",a="Veren benötigt zwölf Stück Leichtes Leder, erbeutet von den Bestien, die Mulgore und benachbarte Gebiete durchstreifen, um Waren für Donnerfels herzustellen.",al={"leder sammeln anforderungen","was veren bringen","leder sammeln materialien"}},{q="Wo findet diese Quest statt?",a="Die Quest beginnt und endet bei Veren Tallstrider auf der Spitze von Donnerfels, erfordert jedoch für ihren Abschluss die Jagd auf wilde Bestien in den darunterliegenden Graslanden.",al={"wo ist veren tallstrider","leder sammeln standort"}},{q="Warum legen die Tauren so viel Wert auf die Jagd nach Bestien?",a="Die Kultur der Tauren begreift die Jagd als ein heiliges Gleichgewicht mit der Erdenmutter. Jeder Teil eines erlegten Tieres wird genutzt: Das Fleisch ernährt den Stamm, während Knochen und gegerbte Häute zu Werkzeugen, Zelten und strapazierfähiger Rüstung verarbeitet werden.",al={"tauren jagdkultur","warum leder jagen","tauren leder lore"}},{q="Kann jeder Abenteurer der Horde diese Aufgabe übernehmen?",a="Ja, jeder der Horde treue Reisende, den Veren für gewillt hält, seinen Mut in den Ebenen unter Beweis zu stellen, kann ihm beim Sammeln von Leder behilflich sein.",al={"wer kann leder sammeln","ist leder sammeln nur horde"}},{q="Was geschieht, sobald das Leder abgeliefert ist?",a="Veren begutachtet die Qualität der Häute, lobt den Jäger für seine Arbeit und überreicht im fairen Tausch ein gefertigtes Ausrüstungsteil.",al={"leder sammeln abgeben","belohnung veren tallstrider"}}},fx={cd30155e={q="Wofür wird Leichtes Leder verwendet?",a="Das Leder wird zu unverzichtbaren Kleidungsstücken, schützender Rüstung und nützlichen Waren für die Tauren verarbeitet, die hoch oben auf den Plateaus von Donnerfels leben, sowie zu Ausrüstung, die im Handel für reisende Jäger hergestellt wird.",al={"verwendung von leichtem leder","gebrauch von leichtem leder","wie nutzt veren leichtes leder"}},["1249c214"]={q="Warum möchte Veren Tallstrider Leichtes Leder?",a="Veren Tallstrider ist ein Lederer, der Kleidung und Rüstungen für die Bewohner von Donnerfels fertigt. Um die Stadt zu versorgen und sein Handwerk aufrechtzuerhalten, ist er darauf angewiesen, dass Jäger hochwertige Felle aus den Ebenen von Mulgore bringen.",al={"warum veren leder braucht","veren tallstriders motiv","warum leichtes leder für veren"}}},fp="17,360,24.407.0,19.436.0,25.210.0,33.153.0,33.147.0,61.219.0,45.137.0,43.128.0"}
P.entries["quest:769"] = {n="Kodobalgtasche",s="Kodobalgtasche ist eine Handwerksquest, die von Veren Tallstrider angeboten wird, einem geschickten Lederverarbeiter der Tauren auf den hohen Mesas von Donnerfels. Im Austausch gegen grundlegende Handwerksmaterialien gibt er die traditionelle Technik der Ebenen weiter, mit der aus robuster Tierhaut strapazierfähige Reisetaschen genäht werden. Sie dient als frühe Reifeprüfung für angehende Lederer in Mulgore.",h="Kodobalgtasche ist eine Handwerksquest, die von Veren Tallstrider angeboten wird, einem geschickten...",kw={"grober faden","kodo","kodobalgtasche","lederverarbeitung","leichtes leder","mulgore","donnerfels","veren tallstrider"},ang={["faction:Horde"]="Die Handwerker von Donnerfels liefern unverzichtbare logistische Güter, die Jäger, Späher und Krieger der Horde im gesamten zentralen Kalimdor ausgerüstet halten.",["race:Tauren"]="Für die Shu'halo ist das Erlernen der Herstellung zuverlässiger Ausrüstung aus dem mächtigen Kodo ein wesentlicher Schritt, um die Gaben der Erdenmutter zu ehren und die Gebräuche der Ahnen zu bewahren."},sec={{t="Eine Lektion auf der Mesa",b="Auf den Handwerksebenen von Donnerfels hält Veren Tallstrider die langjährige nomadische Tradition aufrecht, bei der von der Jagd nichts verschwendet wird. Um seine Unterweisung zu erhalten, muss ein aufstrebender Lederverarbeiter ihm gegerbtes Leichtes Leder und festes Garn vorlegen. Indem sie ihre Kompetenz mit grundlegenden Materialien unter Beweis stellen, beweisen Lehrlinge, dass sie bereit sind, Waren herzustellen, die tauglich sind, Überlebensausrüstung durch die rauen Weiten von Kalimdor zu tragen."},{t="Geist des Kodos",b="Für die Tauren ist das Kodo ein Sinnbild für Ausdauer, Stärke und unerschütterliche Entschlossenheit. Seine dicke Haut schützt vor Dornen, beißendem Wind und Tierkrallen gleichermaßen. Das Fertigen von Taschen und Kleidungsstücken aus Kodohaut ist nicht bloß ein zweckmäßiger Akt, sondern ein Ausdruck der Ehrfurcht vor dem Tier, das die Shu'halo über zahllose Generationen hinweg durch die Ebenen von Mulgore ernährt und getragen hat."}},faq={{q="Wer bietet die Quest für die Kodobalgtasche an?",a="Die Quest wird von Veren Tallstrider angeboten, einem Lederverarbeitungslehrer und Händler der Tauren in Donnerfels.",al={"questgeber","wo man die quest für die kodobalgtasche bekommt","standort von veren tallstrider"}},{q="Wer ist berechtigt, diese Aufgabe anzunehmen?",a="Nur Abenteurer, die in Lederverarbeitung ausgebildet sind und mindestens Lehrlingsfertigkeitsstufe 10 erreicht haben, können diese Ausbildungsaufgabe von Veren Tallstrider erhalten.",al={"wer kann diese quest annehmen","questvoraussetzungen","berufsvoraussetzung"}},{q="Welche Materialien benötigt Veren Tallstrider?",a="Er benötigt vier Stück Leichtes Leder und vier Rollen Grober Faden, um seine Handwerksvorräte aufzufüllen, bevor er sein Muster weitergibt.",al={"welche gegenstände werden benötigt","materialien für kodobalgtasche","questabgabe-gegenstände"}},{q="Warum gilt Kodohaut für Handwerker der Tauren als bedeutsam?",a="Kodos verkörpern Widerstandskraft und körperliche Stärke – Eigenschaften, die von den Tauren tief geschätzt werden. Die Herstellung langlebiger Ausrüstung aus ihren Häuten ehrt den Geist der Kreatur und bietet Reisenden, die die Ebenen durchqueren, zugleich robusten Nutzen.",al={"warum kodohaut","bedeutung des kodos für tauren","wichtigkeit des kodos"}},{q="Was lehrt Veren Tallstrider nach dem Abschluss?",a="Nach Erhalt der Vorräte vermittelt Veren dem Handwerker das Spezialwissen, das für das Nähen einer Kodobalgtasche erforderlich ist.",al={"questbelohnung","was erhalte ich","taschenmuster"}},{q="Wo können die erforderlichen Materialien beschafft werden?",a="Leichtes Leder wird durch das Kürschnern von niedrigstufigen Tieren in ganz Mulgore und den angrenzenden Gebieten gewonnen, während Grober Faden direkt bei Handwerks- und Schneiderbedarfshändlern gekauft werden kann.",al={"wo man leichtes leder bekommt","wo man groben faden bekommt"}}},fx={c94273ea={q="Warum möchte Veren Tallstrider, dass dies erledigt wird?",a="Veren Tallstrider ist stolz darauf, die nächste Generation von Tauren-Lederern auszubilden. Mulgores Kodo-Bestien werden für ihre Stärke und Ausdauer verehrt, und die Herstellung einer traditionellen Tasche aus ihren Häuten ist eine grundlegende Fertigkeit. Indem er Euch bittet, Arbeitsmaterialien für sein Handwerk zu sammeln, stellt Veren Eure Hingabe und Euren Einfallsreichtum auf die Probe, bevor er die Techniken des Handwerks weitergibt.",al={"warum möchte veren tallstrider leder","motiv von veren tallstrider","grund für kodo hide bag aufgabe"}},["1f62e959"]={q="Wozu dient das Leichte Leder?",a="Leichtes Leder dient als grundlegendes Handelsgut, das Veren Tallstrider als Gegenleistung für seinen Unterricht benötigt. Das Arbeiten mit gegerbten Häuten ist der Kern der Tauren-Lederverarbeitung, und die Bereitstellung von hochwertigem Leder beweist, dass Ihr die Grundlagen der Tierhautbehandlung beherrscht, bevor Ihr lernt, wie man spezialisierte Behältnisse wie Kodo Hide Bags näht.",al={"wofür wird leichtes leder verwendet","warum leichtes leder bringen","zweck von leichtem leder"}},["7d0f7d7f"]={q="Wozu dient der Grobe Faden?",a="Grober Faden ist ein wesentlicher Bestandteil der Schneiderei und Lederverarbeitung, der dazu verwendet wird, dicke Häute zusammenzubinden. Um langlebige Rucksäcke zu konstruieren, die den Ebenen von Mulgore standhalten, benötigt ein Handwerker robustes Garn, das bei starker Belastung oder rauem Wetter nicht reißt.",al={"warum grober faden","zweck von grobem faden","wofür ist grober faden"}}},fp="13,362,20.426.0,18.388.0,35.113.0,39.149.0,46.133.0,59.224.0,50.125.0,46.176.0"}
P.entries["quest:77"] = {n="Eine schwierige Situation",s="Gilveradin Sunchaser besitzt die Originalverpackung für die Hinterland-Honigwelle, nach der Dran Droffers sucht, und wird gegen eine Gebühr von zwei zusätzlichen Flaschen beim Verpacken helfen. Die Flaschen befinden sich in Kisten rund um die verlassene Basis der Horde nahe Skulk Rock.",h="Gilveradin Sunchaser besitzt die Originalverpackung für die Hinterland-Honigwelle, nach der Dran Droffers...",kw={"dran droffers","gilveradin sunchaser","hinterland","hinterland-honigwelle","schlicke","skulk rock","schleime"},sec={{t="Eine Frage der Verpackung",b="Dran Droffers sucht nach der Honigwelle, und Gilveradin Sunchaser hat die Originalverpackung dafür. Die Hilfe ist nicht umsonst: Gilveradin verlangt für die Mühe zwei zusätzliche Flaschen. Zehn Flaschen Hinterland-Honigwelle müssen gesammelt und ins Lager zurückgebracht werden."},{t="Ruinen von Skulk Rock",b="Die Kisten stehen um die verlassene Basis der Horde nahe Skulk Rock herum. Üble Schlicke und Schleime klammern sich an die Ruinen, und Gerüchten zufolge führt eine Art Meisterschleim sie an."}},faq={{q="Wer möchte die Hinterland-Honigwelle verpackt haben?",a="Dran Droffers ist derjenige, der nach der Honigwelle sucht, und Gilveradin Sunchaser hat die Originalverpackung dafür, die für Maltons Vater bestimmt ist.",al={"wer braucht die honigwelle","dran droffers honigwelle","für wen ist die verpackung"}},{q="Was verlangt Gilveradin für das Verpacken?",a="Gilveradin verlangt als Gebühr zwei zusätzliche Flaschen der Honigwelle. Zehn Flaschen müssen aus den Kisten geborgen werden.",al={"warum 10 flaschen","gilveradin gebühr","warum so viel honigwelle"}},{q="Wo werden die Kisten mit Hinterland-Honigwelle aufbewahrt?",a="Sie befinden sich in Kisten rund um die verlassene Basis der Horde nahe Skulk Rock im Hinterland.",al={"fundort honigwelle","wo ist die honigwelle","skulk rock kisten"}},{q="Was befindet sich im verlassenen Lager bei Skulk Rock?",a="Üble Schlicke und Schleime klammern sich an die Ruinen, und Gerüchten zufolge führt ein Meisterschleim sie an.",al={"skulk rock monster","was ist bei skulk rock","skulk rock schleime"}}},fp="18,243,21.259.0,19.159.0,48.140.0,46.115.0,54.86.0,44.82.0"}
P.entries["quest:770"] = {n="Der Dämonennarbenumhang",s="Der Dämonennarbenumhang ist ein zerfetzter Pelz, der vom legendären weißen Wolf Ghost Howl erbeutet wurde, welcher die Grasebenen von Mulgore durchstreift. Gezeichnet von einer bleibenden Wunde, die ihm bei vergangenen Zusammenstößen mit der Brennenden Legion zugefügt wurde, dient der Pelz als Beweis für die Erlösung der Bestie von ihren Qualen. Ihn zu den Ältesten im Dorf der Bluthufe zu bringen, schließt die Geschichte einer tragischen lokalen Legende ab.",h="Der Dämonennarbenumhang ist ein zerfetzter Pelz, der vom legendären weißen Wolf Ghost Howl erbeutet wurde...",kw={"brennende legion","dämonennarben-umhang","geisterheuler","mulgore","skorn wolkenweiß","weißer wolf"},ang={["class:Druid"]="Druiden betrachten den von Dämonen gezeichneten Pelz als eine düstere Mahnung daran, dass das Land und seine wilden Bewohner noch immer ungeheilte Wunden von der dämonischen Invasion von Kalimdor tragen.",["class:Hunter"]="Das Aufspüren eines einsamen, narbenbedeckten Alphatiers wie Ghost Howl ist ein wesentlicher Übergangsritus, der hohes Lob und das Geschenk eines Meisterjägers vom Ältesten Skorn Wolkenweiß einbringt.",["race:Tauren"]="Für die Shu'halo ist die Jagd auf Ghost Howl kein Akt der Grausamkeit oder Eroberung, sondern ein feierliches Ritual, um einer gequälten Kreatur Frieden von der anhaltenden Verderbnis der Brennenden Legion zu gewähren."},sec={{t="Ein Relikt teuflischer Wunden",b="Ghost Howl ist ein scheuer weißer Wolf, der in ganz Mulgore sowohl für seine Wildheit als auch für sein klagendes Heulen bekannt ist. Wenn er erschlagen wird, hinterlässt das Tier einen Pelz, der sichtbar von übler dämonischer Verderbnis gezeichnet ist. Diese verbliebenen Spuren gehen auf die verzweifelten Kämpfe des Wolfes gegen die eindringenden Dämonen der Brennenden Legion zurück – eine Konfrontation, die Ghost Howl sowohl an Körper als auch an Geist verwundet zurückließ, lange nachdem der Dritte Krieg sein Ende fand."},{t="Frieden für einen gequälten Geist",b="Die Tauren von Mulgore hegen tiefen Respekt für die wilden Tiere ihrer Heimat und verehren sie als Kinder der Erdenmutter. Die Übergabe des mit Narben gezeichneten Umhangs an Skorn Wolkenweiß im Dorf der Bluthufe bestätigt das Ende des gequälten Raubtiers. Skorn erkennt das immense Geschick an, das nötig ist, um Ghost Howl aufzuspüren und zu besiegen, und verleiht der düsteren Hoffnung Ausdruck, dass der gepeinigte Geist des Wolfes im Tode endlich Frieden gefunden hat."}},faq={{q="Was ist der Dämonennarben-Umhang?",a="Es ist der zerfetzte Balg, der von Ghost Howl erbeutet wurde, einem legendären weißen Wolf in Mulgore. Der Pelz ist sichtbar von Teufelsenergien aus einer alten Schlacht gegen die Brennende Legion gezeichnet.",al={"was ist der dämonennarbenumhang","dämonennarben-umhang gegenstand","geisterheuler balg"}},{q="Woher stammten die Dämonennarben auf dem Umhang?",a="Ghost Howl erlitt seine Wunden bei Zusammenstößen gegen die Brennende Legion, als die dämonischen Invasoren während des Dritten Krieges durch Kalimdor vordrangen.",al={"warum hat geisterheuler narben","wie bekam geisterheuler narben","geisterheuler legion"}},{q="Zu wem bringe ich den Umhang?",a="Bringt den Umhang zu Skorn Wolkenweiß, einem älteren Tauren-Jäger, der im Dorf der Bluthufe in Mulgore weilt.",al={"wo gebe ich den dämonennarbenumhang ab","wer will den dämonennarbenumhang","skorn wolkenweiß abgabe"}},{q="Warum liegt Skorn Wolkenweiß etwas an Ghost Howl?",a="Skorn Wolkenweiß ist ein Jäger im Ruhestand, der Ghost Howl als eine gewaltige Bestie anerkennt, die schwer unter dämonischer Verderbnis litt. Er respektiert das Geschick, das erforderlich ist, um eine solche Kreatur zu erlegen, und hofft, dass ihr Geist endlich ruhen kann.",al={"skorn wolkenweiß lore","warum will skorn geisterheuler"}},{q="Wo ist Ghost Howl zu finden?",a="Ghost Howl ist ein seltener weißer Wolf, der die wogenden Ebenen von Mulgore durchstreift und üblicherweise auf den offenen Feldern im Norden oder Zentrum zwischen der Hochwolkenebene und Donnerfels gesichtet wird.",al={"wo ist geisterheuler zu finden","geisterheuler aufenthaltsort","geisterheuler spawn"}},{q="Warum hoffen die Tauren, dass der Geist des Wolfes Frieden findet?",a="Die Kultur der Tauren legt Wert auf Harmonie mit der Natur und Ehrfurcht vor den Geistern der Wildnis. Da die dämonische Verderbnis unendliche Qualen über Ghost Howls Leben brachte, wird seine Niederlage als eine gnadenvolle Erlösung zurück zur Erdenmutter betrachtet.",al={"tauren-glaube geisterheuler","geisterheuler geist"}}},fp="23,378,21.424.0,27.421.0,32.174.0,49.141.0,28.104.0,48.224.0,26.172.0,53.220.0"}
P.entries["quest:7701"] = {n="GESUCHT: Vorarbeiter Maltorius",s="Ein Steckbrief verkündet, dass Aufseher Maltorius, ein abtrünniger Agent der Thoriumbruderschaft und neu angeworbener Kommandant der Dunkeleisen-Besatzung der Schlackengrube im Kessel, sterben soll. Auf Befehl von Aufseher Oilfist muss sein Kopf als Beweis zu Ausguck Captain Lolo Longstriker zurückgebracht werden.",h="Ein Steckbrief verkündet, dass Aufseher Maltorius, ein abtrünniger Agent der Thoriumbruderschaft und neu...",kw={"kopfgeld","kessel","lolo longstriker","aufseher maltorius","aufseher oilfist","sengende schlucht","die schlackengrube","thoriumbruderschaft"},sec={{t="Ein Preis auf einen Verräter",b="Aufseher Maltorius, ein verräterischer Dunkeleisenzwerg, ist in den Tiefen der Schlackengrube des Kessels zu finden. Der Befehl lautet, ihn zu erschlagen, seinen Kopf zu nehmen und ihn für das Kopfgeld zu Ausguck Captain Lolo Longstriker zurückzubringen."}},faq={{q="Wer ist Aufseher Maltorius?",a="Ein verräterischer Dunkeleisenzwerg. Der Aushang bezeichnet ihn als abtrünnigen Agenten der Thoriumbruderschaft und als neu angeworbenen Kommandanten der Dunkeleisen-Besatzung der Schlackengrube im Kessel.",al={"maltorius lore","wer ist maltorius","hintergrundgeschichte von aufseher maltorius"}},{q="Wo ist Aufseher Maltorius zu finden?",a="Unten in der Schlackengrube, die zum Kessel gehört.",al={"maltorius aufenthaltsort","wo ist maltorius","wie man aufseher maltorius findet"}},{q="Wer befahl den Tod von Aufseher Maltorius?",a="Aufseher Oilfist, der auf dem Aushang als derjenige genannt wird, der den Befehl erteilt hat.",al={"wer das kopfgeld ausgesetzt hat","wer maltorius tot sehen will","wer den mord befohlen hat"}},{q="Wer nimmt den Beweis für Maltorius' Tod entgegen?",a="Ausguck Captain Lolo Longstriker in der Sengenden Schlucht. Der Kopf von Maltorius ist der verlangte Beweis.",al={"bei wem maltorius kopf abzugeben ist","wohin maltorius kopf gebracht werden soll","lolo longstriker aufenthaltsort"}}},fp="26,274,20.217.0,26.162.0,38.52.0,44.71.0,40.97.0"}
P.entries["quest:7704"] = {n="Look at the Size of It!",s="Ihr seid in den Besitz eines riesigen, verzierten Kissens gelangt, das einst Chambermaid Pillaclencher gehörte. Evonice Sootsmoker in der Sengenden Schlucht wird es mit Sicherheit haben wollen.",h="Ihr seid in den Besitz eines riesigen, verzierten Kissens gelangt, das einst Chambermaid Pillaclencher...",kw={"chambermaid pillaclencher","evonice sootsmoker","look at the size of it","kissen","sengende schlucht"},sec={{t="Ein Kissen für Evonice",b="Das Kissen, das Chambermaid Pillaclencher verwahrte, gehört nun Euch. Evonice Sootsmoker wird es sicherlich unbedingt in die Finger bekommen wollen. Bringt es zu ihr in die Sengende Schlucht und seht, was sie Euch für Eure Mühen anbietet."}},faq={{q="Wer möchte Chambermaid Pillaclenchers Kissen haben?",a="Evonice Sootsmoker in der Sengenden Schlucht, von der erwartet wird, dass sie es unbedingt haben möchte.",al={"zu wem bringe ich das kissen","evonice sootsmoker kissen","wohin kommt das kissen"}},{q="Woher stammt dieses Kissen?",a="Es gehörte Chambermaid Pillaclencher und ist riesig und verziert.",al={"kissen beute","wer hinterlässt das kissen","chambermaid kissen"}},{q="Wo ist Evonice Sootsmoker zu finden?",a="In der Sengenden Schlucht.",al={"evonice aufenthaltsort","wo ist evonice sootsmoker","evonice sengende schlucht"}}},fp="23,156,20.196.0,45.68.0,33.69.0,38.21.0"}
P.entries["quest:771"] = {n="Ritus der Vision",s="Der Ritus der Vision ist eine grundlegende spirituelle Prüfung für junge Tauren, die von der Hochwolkenebene in das weitere Mulgore hinausziehen. Um den Schleier zu durchdringen und die Führung der Geister ihrer Ahnen zu empfangen, müssen die Initianden unter den wachsamen Augen von Zarlman Zwillingsmond im Dorf der Bluthufe natürliche Reagenzien sammeln, um das Wasser der Seher zu brauen.",h="Der Ritus der Vision ist eine grundlegende spirituelle Prüfung für junge Tauren, die von der Hochwolkenebene...",kw={"bernsteinkorn","dorf der bluthufe","erdenmutter","mulgore","ritus der vision","wasser der seher","brunnensteine","zarlman zwillingsmond"},ang={["class:Druid"]="Druiden hegen eine tiefe Ehrfurcht vor Bernsteinkorn und Brunnensteinen, da sie in ihnen direkte Manifestationen der Flora und der lebensspendenden Wasserläufe sehen, die das Gleichgewicht von Mulgore aufrechterhalten.",["class:Shaman"]="Schamanen erkennen in der Zubereitung des Wassers der Seher ein traditionelles Erdungsritual, das den Geist darauf einstimmt, ungesehene Elemente wahrzunehmen, bevor man direkt mit Geistern spricht.",["race:Tauren"]="Für Tauren ist der Ritus der Vision ein wesentlicher kultureller Meilenstein, der einen angehenden Krieger, Jäger oder Mystiker an das spirituelle Erbe der Erdenmutter und der Ahnen bindet."},sec={{t="Die Reagenzien des Landes",b="Bevor eine Vision gewährt werden kann, muss der Initiand ein tiefes Verständnis für die natürlichen Gaben Mulgores beweisen. Zarlman Zwillingsmond weist die Suchenden an, Brunnensteine nahe den heiligen Gemeinschaftsbrunnen und Bernsteinkorn unter den Wurzeln der uralten Bäume Mulgores zu sammeln. Diese Naturelemente sind nicht bloß physische Objekte; für die Tauren bergen sie die verborgene Magie und das Lebensblut der Erdenmutter, bereit, für das Ritual kanalisiert zu werden."},{t="Das Brauen des Wassers der Seher",b="Sobald sie gesammelt sind, verbindet Zarlman die Steine und das Bernsteinkorn zu dem mächtigen Wasser der Seher. Neben der Stammesflamme des Dorfes getrunken, klärt dieser zeremonielle Trank den Geist und beschwört einen ätherischen Führer herauf. Dieser Erscheinung über die Ebenen zu folgen, bildet das wahre Herzstück des Ritus und stellt die Fähigkeit des Initianden auf die Probe, zwischen der physischen Welt und dem spirituellen Flüstern des Landes zu wandeln."}},faq={{q="Was ist der Zweck des Ritus der Vision?",a="Der Ritus der Vision ist eine spirituelle Prüfung für heranwachsende Tauren, die ihren Weg suchen. Durch die Zubereitung und das Trinken des Wassers der Seher lernt der Initiand, mit Geistern zu kommunizieren und den Omen der Ahnen über die Ebenen von Mulgore zu folgen.",al={"was ist der ritus der sicht","warum ritus der sicht","zweck des ritus der sicht"}},{q="Wer ist Zarlman Zwillingsmond?",a="Zarlman Zwillingsmond ist ein Schamane und Seher der Tauren im Dorf der Bluthufe. Er überwacht spirituelle Prüfungen junger Abenteurer, bereitet Ritualtränke wie das Wasser der Seher zu und deutet die Zeichen der Erdenmutter.",al={"wer ist zarlman","zarlman two moons rolle","questgeber zarlman"}},{q="Wo findet man Brunnensteine und Bernsteinkorn?",a="Brunnensteine werden vom Boden nahe den Süßwasserbrunnen gesammelt, die über ganz Mulgore verteilt sind. Bernsteinkorn findet sich am Fuße der großen, weit ausladenden Bäume, die die umliegende Graslandschaft prägen.",al={"bernsteinkorn fundort","brunnensteine fundort","reagenzien für ritus der sicht"}},{q="Was geschieht nach dem Trinken des Wassers der Seher?",a="Das Trinken des Tranks am Stammesfeuer öffnet die spirituelle Sicht des Trinkenden und offenbart einen geisterhaften Tierführer. Der Suchende muss diesem Geist über die Ebenen folgen, um die nächste Stufe seiner heiligen Reise zu enthüllen.",al={"wie geht ritus der sicht weiter","wasser der seher wirkung","folgequest visionssuche"}},{q="Warum verehren die Tauren Wasserbrunnen so tief?",a="Wasser ist das Lebensblut von Mulgore und eine kostbare Gabe der Erdenmutter. Die Brunnen dienen als heilige Zentren der Gemeinschaft, die sowohl das Land als auch seine Herden nähren, wodurch die neben ihnen gesammelten Steine spirituell aufgeladen sind.",al={"wasserbrunnen der tauren","warum brunnen heilig sind","mulgore wasser"}},{q="Führt diese Quest zu weiteren Riten?",a="Ja. Diese Aufgabe ist Teil einer mehrstufigen Zeremonie. Sobald Zarlman das Wasser der Seher zubereitet hat, müssen Initianden es trinken, der erscheinenden Vision folgen und sich den Ältesten in ganz Mulgore vorstellen.",al={"nächste quest bei ritus der sicht","ist ritus der sicht eine questreihe","questreihe tauren riten"}}},fx={["6b13f1a7"]={q="Warum möchte Zarlman Zwillingsmond, dass dies erledigt wird?",a="Als Stammschamane ist Zarlman Zwillingsmond dafür verantwortlich, vielversprechende junge Abenteurer durch die heiligen Traditionen der Tauren zu führen. Er kann Euch nicht einfach spirituelle Weisheit verleihen; Ihr müsst Euch die Gunst der Erdenmutter und Eurer Vorfahren verdienen, indem Ihr direkt am Ritual teilnehmt, angefangen damit, die heiligen Elemente des Landes selbst zu sammeln.",al={"motiv von zarlman zwillingsmond","warum schickt euch zarlman","grund für zarlmans rite of vision"}},cc7474fb={q="Wozu dienen die Quellsteine?",a="Quellsteine werden aus den heiligen Wasserquellen in ganz Mulgore gesammelt. Durchdrungen von der natürlichen Magie der reinsten Quellen der Erdenmutter, dienen sie als eine der wichtigsten Reagenzien, die Zarlman Zwillingsmond benötigt, um das mystische Wasser der Seher zu brauen.",al={"zweck der quellsteine","warum quellsteine nötig","verwendung von quellsteinen"}},["4efb8f2d"]={q="Wozu dient das Bernsteinkorn?",a="Das von den mächtigen Bäumen in ganz Mulgore gefallene Bernsteinkorn trägt die natürliche Essenz der Flora des Landes in sich. Kombiniert mit Quellsteinen und von Zarlman Zwillingsmond aufgebrüht, liefert es die magischen Eigenschaften, die erforderlich sind, um das Wasser der Seher zu brauen, wodurch Ihr Visionen der Vorfahren erhaltet.",al={"zweck von bernsteinkorn","wofür wird bernsteinkorn verwendet","warum bernsteinkorn sammeln"}},["761f0189"]={q="Warum müsst Ihr die Reagenzien sammeln und nicht Zarlman Zwillingsmond?",a="Die Rite of Vision ist eine individuelle Prüfung spirituellen Wachstums, keine routinemäßige Aufgabe. Um mit den Geistern zu kommunizieren, müsst Ihr Ehrfurcht und Harmonie mit dem Land demonstrieren, indem Ihr seine natürlichen Segnungen mit Euren eigenen Händen sucht. Jemand anderen die Reagenzien sammeln zu lassen, würde den heiligen Zweck der Prüfung zunichtemachen.",al={"warum muss ich bernsteinkorn sammeln","warum sammelt zarlman keine quellsteine","warum ich rite of vision"}}},fp="14,335,24.476.0,30.397.0,42.238.0,25.234.0,42.210.0,51.214.1,47.219.0,38.207.1"}
P.entries["quest:772"] = {n="Ritus der Vision",s="Der Ritus der Vision ist der spirituelle Höhepunkt einer uralten Prüfung, der sich junge Tauren im Dorf der Bluthufe unterziehen. Indem sie das heilige Wasser der Seher neben dem Stammesfeuer trinken, beschwören die Initianden einen geisterhaften Führer herauf, der sie ihrem Schicksal entgegenleitet.",h="Der Ritus der Vision ist der spirituelle Höhepunkt einer uralten Prüfung, der sich junge Tauren im Dorf der...",kw={"dorf der bluthufe","geisterwolf","mulgore","ritus der vision","seher wiserunner","stammesfeuer","wasser der seher","zarlman zwillingsmond"},ang={["class:Druid"]="Der Ritus stärkt die Ehrfurcht vor der Natur und die spirituelle Demut vor der Führung von Tiergestalten.",["class:Shaman"]="Einem Vorfahren-Geisterwolf zu folgen ist eine frühe Lektion im Wandeln zwischen den Welten und festigt das Band eines Schamanen mit den Geistern, welche die Horde leiten.",["race:Tauren"]="Für junge Tauren ist der Ritus der Vision ein zutiefst heiliger Übergang ins Erwachsenenalter, der die Gemeinschaft mit den Ahnen und den Gehorsam gegenüber spiritueller Führung beweist."},sec={{t="Das Wasser der Seher",b="Nachdem die notwendigen rituellen Kräuter gesammelt und die anfänglichen Glaubensprüfungen bestanden wurden, erhält ein Initiand das Wasser der Seher vom Schamanen des Dorfes, Zarlman Zwillingsmond. Dieser mächtige Trank muss vor dem lodernden Stammesfeuer im Herzen des Dorfes der Bluthufe eingenommen werden. Wenn es mit konzentriertem und ehrerbietigem Geist getrunken wird, erweitert das heilige Wasser die Wahrnehmung des Trinkenden über die physische Sicht hinaus und überbrückt den Schleier zwischen der materiellen Ebene und dem Geisterreich."},{t="Dem Geisterwolf folgen",b="Beim Trinken des Gebräus entlassen die Flammen eine ätherische Erscheinung: einen uralten Geisterwolf. Der Geist spricht nicht und kämpft nicht, sondern trabt lautlos nach Nordwesten über die wogenden Ebenen von Mulgore. Ein wahrer Initiand muss seinem stillen Pfad folgen und seiner Reise weit weg vom Dorf und tief in die felsigen Hügel nachspüren, wo der Einsiedler Seher Wiserunner in abgeschiedener Meditation verweilt."},{t="Ein Weg zur Weisheit",b="Das Erreichen von Seher Wiserunner am Eingang seiner Berghöhle besiegelt den erfolgreichen Abschluss der Vision. Diese Reise über die grasbewachsenen Hügel stellt die Geduld eines Initianden, sein Vertrauen in die Führung der Vorfahren und seine Einstimmung auf die Erdenmutter auf die Probe. Das Bestehen dieses Ritus gewährt dem jungen Abenteurer das Recht, die ultimative Prüfung des Erwachsenwerdens abzulegen: den Ritus der Weisheit."}},faq={{q="Was geschieht, wenn ich das Wasser der Seher trinke?",a="Wenn es in der Nähe des Stammesfeuers im Dorf der Bluthufe getrunken wird, öffnet das Wasser Eure spirituellen Sinne. Kurz nach dem Trinken erscheint ein geisterhafter Wolf vor den Flammen, um Euren Weg zu leiten.",al={"wie funktioniert wasser der seher","wasser der seher trinken","was bewirkt das wasser"}},{q="Wohin führt mich der Geisterführer?",a="Der geisterhafte Wolf trabt vom Dorf der Bluthufe aus nach Nordwesten über die Hügel von Mulgore und führt direkt zu einer felsigen Höhle, in der Seher Wiserunner lebt.",al={"wohin geht der geisterwolf","zu wem führt der wolf","wolf zielort"}},{q="Wer ist Zarlman Zwillingsmond?",a="Zarlman Zwillingsmond ist ein bedeutender Taurenschamane im Dorf der Bluthufe, der damit beauftragt ist, Initianden durch Ahnenriten und heilige Gebräue auf das spirituelle Erwachsenenalter vorzubereiten.",al={"wer vergibt ritus der sicht","zarlman zwillingsmond rolle"}},{q="Wer ist Seher Wiserunner?",a="Seher Wiserunner ist ein älterer Taurenmystiker, der in Einkehr in den Klippen nordwestlich des Dorfes der Bluthufe lebt. Initianden, die ihrer Geistervision folgen, finden ihn, um die Prüfung abzuschließen.",al={"wer ist wiserunner","seher in höhle mulgore"}},{q="Warum muss das Wasser in der Nähe des Stammesfeuers getrunken werden?",a="Das Stammeslagerfeuer dient als heiliger Anker für die Vorfahrengeister des Dorfes der Bluthufe. Die Kombination aus seinen geweihten Flammen und dem heiligen Wasser ermöglicht es der Vision, in die wache Welt überzutreten.",al={"warum stammesfeuer","lagerfeuer ritus der sicht"}},{q="Welcher Ritus folgt auf den Ritus der Vision?",a="Nach Abschluss des Ritus der Vision bei Seher Wiserunner werden Initianden angewiesen, den Ritus der Weisheit anzutreten, die letzte spirituelle Prüfung ihrer frühen Reise in Mulgore.",al={"folgequest nach ritus der sicht","was kommt danach"}}},fx={["659b3713"]={q="Warum möchte Zarlman Zwillingsmond, dass ich die Rite of Vision durchlaufe?",a="Als Schamane des Dorfes der Bluthufe führt Zarlman Zwillingsmond junge Tauren auf den heiligen Pfaden ihrer Vorfahren. Nachdem Ihr die Komponenten für das Wasser der Seher gesammelt habt, präsentiert er nun den Trank, damit Ihr direkt mit den Geistern kommunizieren, Eure Vision erleben und den nächsten Schritt auf dem Weg zur Entdeckung Eures Schicksals innerhalb des Stammes tun könnt.",al={"warum rite of vision","motiv von zarlman zwillingsmond","zweck der rite of vision"}},b8c8221c={q="Warum muss ich dieses Ritual selbst durchführen?",a="Die Rites of the Earthmother sind zutiefst persönliche Prüfungen der Reife und des spirituellen Erwachens. Kein Wächter oder Ältester kann den Pfad der Geister für Euch beschreiten; nur Euer eigener Geist kann die Führung erhalten, die dazu bestimmt ist, Euren Platz und Zweck unter dem Volk der Tauren zu enthüllen.",al={"warum muss ich die rite durchführen","warum ich für die rite of vision","warum kann niemand anderes die rite durchführen"}}},fp="14,249,22.467.0,24.371.0,16.362.0,49.192.0,36.150.0,25.171.0,23.189.0,49.197.0,41.173.0"}
P.entries["quest:7721"] = {n="Treibstoff fürs Schrumpfen",s="An der Vergessenen Küste von Feralas hat Zorbin Fandazzle wider besseres Wissen eine Ingenieurswerkstatt eröffnet, und die einheimischen Elementare sind eine Plage. Sie sind jedoch auch eine ideale Quelle roher Energie zur Verfeinerung des Ultra-Shrinker, und die Wasserelementarkerne sind genau das, was Zorbin will.",h="An der Vergessenen Küste von Feralas hat Zorbin Fandazzle wider besseres Wissen eine Ingenieurswerkstatt...",kw={"feralas","die vergessene küste","sea elemental","sea spray","ultra-shrinker","wasserelementarkern","zorbin fandazzle"},sec={{t="Kraft aus der Brandung",b="Zorbin Fandazzle verflucht die unkontrollierten Mächte des Elementarismus und bezeichnet die Elementare der Küste als Plagegeister. Dennoch hält Zorbin sie auch für eine ideale Quelle roher Energie bei der Verfeinerung des Ultra-Shrinker. Zorbin möchte, dass Ihr den Sea Elementals und Sea Sprays der Küste eine Abreibung verpasst, ihre Wasserelementarkerne behaltet und sie zu Zorbin an die Anlegestelle bringt."},{t="Zorbins Dank",b="Zorbin ist erfreut: Die Kerne werden die Arbeit für einige Zeit am Laufen halten, und an der Küste gibt es nun weniger Elementare. Zorbin fügt hinzu, dass die Eröffnung der Werkstatt an dem wohl denkbar schlechtesten Ort ein Grund gewesen sei, nachts zu weinen. Zorbin zeigt sich mit einer Bezahlung dankbar, auch wenn dies Zorbins Finanzen strapaziert."}},faq={{q="Wer bittet um die Elementarkerne?",a="Zorbin Fandazzle, der an der Vergessenen Küste von Feralas nahe der dortigen Anlegestelle eine Ingenieurswerkstatt betreibt.",al={"wer gibt fuel for the zapping","zorbin fandazzle questgeber","wer startet fuel for the zapping"}},{q="Warum benötigt Zorbin Fandazzle Wasserelementarkerne?",a="Zorbin betrachtet die einheimischen Elementare als eine ideale Quelle roher Energie zur Verfeinerung des Ultra-Shrinker, und es sind die Wasserelementarkerne, die Zorbin will.",al={"warum wasserelementarkerne","wofür werden kerne verwendet","ultra-shrinker treibstoff"}},{q="Wo werden die Elementarkerne gesammelt?",a="Zorbin möchte, dass sie von den Sea Elementals und den Sea Sprays erbeutet werden, die an der Vergessenen Küste von Feralas umherstreifen.",al={"wo kerne zu finden sind","sea elemental aufenthaltsort","wo sind sea sprays"}}},fp="20,273,19.352.0,15.310.1,38.103.0,53.154.0,39.108.0"}
P.entries["quest:7722"] = {n="Was zum Fluxus?!",s="Meisterschmied Burninate berichtet, dass Maltorius, als er ihren Clan verließ, ihr Rezept für feurigen Fluxus mitnahm, das mehr wert sei als ein makelloser Arkankristall. Burninate möchte die Geheimpläne zurück und ist sich sicher, dass sie sich in der Nähe von Maltorius befinden, tief in der Schlackengrube.",h="Meisterschmied Burninate berichtet, dass Maltorius, als er ihren Clan verließ, ihr Rezept für feurigen Fluxus...",kw={"burninate","der kessel","feuriger fluxus","maltorius","pläne","sengende schlucht","die schlackengrube"},sec={{t="Das gestohlene Rezept",b="Meisterschmied Burninate bezeichnet Maltorius als Verräter, der den Clan mit dem Rezept für feurigen Fluxus verlassen hat. Burninate würde wetten, dass das Rezept mit Maltorius' neuer Beförderung bei den Dunkeleisenzwergen einherging, und verlangt die Rückgabe der Geheimpläne."},{t="In die Schlackengrube",b="Burninate ist sich sicher, dass die Pläne nicht weit von Maltorius entfernt sind, unten in den Tiefen der Schlackengrube. Geheimpläne: Feuriger Fluxus ist das, was Burninate zurückgebracht haben möchte."}},faq={{q="Wer stahl das Rezept für feurigen Fluxus?",a="Maltorius, den Meisterschmied Burninate als Verräter an ihrem Clan bezeichnet.",al={"wer hat das rezept gestohlen","wer hat die pläne an sich genommen","what the flux verräter"}},{q="Wo befinden sich die Geheimpläne?",a="Burninate glaubt, dass sie sich nahe bei Maltorius befinden, tief in der Schlackengrube des Kessels.",al={"wo sind die pläne","fundort geheimpläne feuriger fluxus","wo findet man die pläne für feurigen fluxus"}},{q="Wer verlangt die Wiederbeschaffung der Pläne?",a="Es ist Burninate, ein Meisterschmied, der sie zurückhaben möchte.",al={"wer vergibt what the flux","what the flux questgeber"}},{q="Warum sind die Pläne für Burninate von Bedeutung?",a="Burninate erklärt, dass das Rezept für feurigen Fluxus mehr wert sei als ein makelloser Arkankristall und das eigene Geheimnis des Clans war.",al={"warum ist feuriger fluxus wichtig","bedeutung des rezepts für feurigen fluxus"}}},fp="14,241,17.224.0,17.159.0,36.69.0,27.80.0,39.53.0,37.120.0"}
P.entries["quest:7723"] = {n="Verdammt seien diese fetten Finger",s="Hansel Bleihand in der Sengenden Schlucht kann wegen geschwollener Finger keine Prügel mehr wie früher austeilen. Hansel bittet Euch, stattdessen die schweren Kriegsgolems für ihn zu verprügeln.",h="Hansel Bleihand in der Sengenden Schlucht kann wegen geschwollener Finger keine Prügel mehr wie früher...",kw={"der kessel","dicke finger","hansel bleihand","schwere kriegsgolems","sengende schlucht","thelsamar blood sausages"},sec={{t="Finger wie Würstchen",b="Hansel Bleihand sagt, dass das Klima in der Schlucht mit seiner dünnen Luft Hansels Finger anschwellen lässt, bis sie riesigen Thelsamar Blood Sausages ähneln. Infolgedessen kann Hansel keine Prügel mehr wie gewohnt austeilen und benötigt Euch, damit Ihr Euch stattdessen um Hansels Angelegenheiten kümmert."},{t="Erster Punkt auf der Liste",b="Als Erstes auf Hansels Tagesordnung stehen die schweren Kriegsgolems der Schlucht, von denen Hansel will, dass sie ordentlich vermöbelt werden. Zwanzig von ihnen sollen zerstört werden. Sie durchstreifen die Gebiete um den Kessel, und Ihr kehrt zu Hansel zurück, sobald genug gefallen sind."}},faq={{q="Wer ist Hansel Bleihand?",a="Jemand in der Sengenden Schlucht, dessen geschwollene Finger ihn am Kämpfen hindern, sodass er Euch bittet, das Verprügeln zu übernehmen.",al={"hansel bleihand","wer vergibt verflucht seien diese dicken finger","wer ist der questgeber"}},{q="Warum kann Hansel die Golems nicht persönlich bekämpfen?",a="Hansel macht das Klima und die dünne Luft der Schlucht dafür verantwortlich, dass seine Finger anschwellen, die er mit riesigen Thelsamar Blood Sausages vergleicht.",al={"warum sind hansels finger dick","dicke finger lore","hansel geschwollene hände"}},{q="Mit welchen Feinden muss fertiggeworden werden?",a="Zwanzig schwere Kriegsgolems.",al={"welche feinde bekämpfe ich","was will hansel tot sehen"}},{q="Wo befinden sich die schweren Kriegsgolems?",a="Sie durchstreifen die Gebiete um den Kessel in der Sengenden Schlucht.",al={"wo sind die golems","schwere kriegsgolems aufenthaltsort"}}},fp="23,169,21.266.0,17.223.0,25.111.0,47.134.0,29.24.0,39.62.0"}
P.entries["quest:7724"] = {n="Feurige Bedrohung!",s="Hansel Bleihand sagt, dass jedes Mal, wenn er sich einen Moment ausruhen und über sein Leben nachdenken möchte, die Obrigkeit ihm eine weitere Aufgabe überträgt. Große Lavaspinnen sorgen in der Sengenden Schlucht für Aufruhr, und er möchte, dass Ihr zwanzig von ihnen tötet.",h="Hansel Bleihand sagt, dass jedes Mal, wenn er sich einen Moment ausruhen und über sein Leben nachdenken...",kw={"feurige bedrohung","grosse lavaspinnen","hansel bleihand","oilfist","sengende schlucht","spinnen"},sec={{t="Eine weitere Aufgabe für Hansel",b="Hansel Bleihand beklagt sich darüber, dass die Obrigkeit ihn nie in Frieden lässt. Große Lavaspinnen sorgen für Aufruhr, und es wäre ihm lieber, wenn Ihr das Töten übernahmt statt er."},{t="Die Großen Lavaspinnen",b="Oilfist sagt, die Spinnen verschießen Feuer aus einer unangenehmen Stelle, was die Kinder verstört. Hansel verlangt, dass zwanzig Große Lavaspinnen getötet werden, und man findet sie auf den Hochebenen und an den Lavaseen der Sengenden Schlucht."}},faq={{q="Wer schickt Euch zu den Spinnen?",a="Hansel Bleihand in der Sengenden Schlucht, der auf einen ruhigen Moment gehofft hatte und dem eine weitere Aufgabe übertragen worden war.",al={"questgeber","wer vergibt quest","hansel"}},{q="Warum müssen die Spinnen getötet werden?",a="Große Lavaspinnen sorgen für Aufruhr, und Oilfist sagt, die Art und Weise, wie sie Feuer verschießen, verstöre die Kinder.",al={"warum spinnen toeten","was haben spinnen getan","spinnenproblem"}},{q="Wer erzählte Hansel von den Spinnen?",a="Oilfist, der sagt, dass die Spinnen Feuer aus einer unangenehmen Stelle verschießen.",al={"wer hat sich ueber spinnen beschwert","oilfist"}},{q="Wie viele Große Lavaspinnen müssen getötet werden?",a="Hansel verlangt, dass zwanzig erledigt werden.",al={"wie viele spinnen","spinnenanzahl"}}},fp="13,236,22.170.0,24.214.0,32.101.0,37.104.0,34.63.0,45.38.0"}
P.entries["quest:7725"] = {n="Und wieder unter den geschrumpften Riesen",s="Zorbin Fandazzle weiß, dass Ihr bereits Rückstände gesammelt habt, kann aber stets mehr gebrauchen. Der Ultra-Schrumpfer steht Euch erneut zur Verfügung, um ihn bei den Riesen von Feralas einzusetzen, und Zorbin wartet an den Docks der Vergessenen Küste. Zorbin kann dieses Mal bei weitem nicht so viel zahlen, verspricht jedoch, von Euren Diensten zu berichten.",h="Zorbin Fandazzle weiß, dass Ihr bereits Rückstände gesammelt habt, kann aber stets mehr gebrauchen.",kw={"feralas","die vergessene küste","riesen","miniaturisierungsrückstand","steamwheedle cartel","ultra-schrumpfer","zorbin fandazzle"},sec={{t="Eine Zugabe für den Ultra-Schrumpfer",b="Zorbin Fandazzle räumt ein, dass Ihr bereits Rückstände gesammelt habt, bezeichnet dies jedoch als Zugabe und sagt, dass stets Platz für mehr ist. Zorbin bittet Euch, die Riesen in Feralas noch einmal mit dem Ultra-Schrumpfer zu zappen und zehn Miniaturisierungsrückstände von den geschrumpften Riesen zu den Docks der Vergessenen Küste zu bringen. Da Zorbin im Gegenzug bei weitem nicht so viel anbieten kann, lautet das Angebot, Eure Dienste unter Goblin-Freunden zu preisen, die recht große Ohren haben."},{t="Zorbins Dank",b="Zorbin ist überglücklich, dass Ihr erneut geholfen habt, auch wenn das Geld geringer ausfällt, als Ihr es gewohnt seid. Zorbin beteuert, dass die Kunde von Euren großen Taten für das Goblindom bereits durch die Machtzentren des Steamwheedle Cartels hallt."}},faq={{q="Wer bittet um mehr Rückstände?",a="Zorbin Fandazzle, der an den Docks der Vergessenen Küste in Feralas wartet.",al={"questgeber","standort von zorbin","wer vergibt nochmals riesen zappen"}},{q="Was ging dem voraus?",a="Es folgt auf Zapped Giants, Eure erste Runde beim Sammeln von Rückständen für Zorbin Fandazzle.",al={"voraussetzung","vorherige quest","was mache ich zuerst"}},{q="Wie werden die Rückstände gesammelt?",a="Zorbins Ultra-Schrumpfer wird auf jede Art von Riese in Feralas gerichtet, um ihn zu schrumpfen, und die Rückstände finden sich bei den geschrumpften Riesen.",al={"wie man rückstand erhält","miniaturisierungsrückstand","wie man riesen schrumpft"}},{q="Wo sind die Riesen zu finden?",a="Die Riesen sind entlang der Westküste von Feralas zu finden.",al={"standort der riesen","wo sind feralas-riesen","riesen der vergessenen küste"}},{q="Wird Zorbin ein andermal weitere Rückstände annehmen?",a="Zorbin sagt, dass stets mehr Rückstände gebraucht werden können, daher seid Ihr herzlich eingeladen, mit einer weiteren Zehnerreihe zurückzukehren.",al={"ist das wiederholbar","kann ich nochmals riesen zappen wiederholen","wiederholbare riesenquest"}}},fp="28,289,32.448.0,15.232.1,26.68.0,22.85.0,28.128.0,27.56.0,43.103.0"}
P.entries["quest:7726"] = {n="Neuer Treibstoff fürs Schrumpfen",s="Zorbin Fandazzle benötigt weitere Wasserelementarkerne. Die Eröffnung eines Ladens an der Vergessenen Küste ist ein mühsames Unterfangen, daher wird die Bezahlung geringer ausfallen, doch Zorbin verspricht, jedem in Hörweite von Eurer Hilfe zu berichten, und sagt, es gäbe Freunde im Cartel.",h="Zorbin Fandazzle benötigt weitere Wasserelementarkerne.",kw={"feralas","die vergessene küste","sea elemental","sea spray","steamwheedle cartel","wasserelementarkern","zorbin fandazzle"},sec={{t="Mehr vom Selben",b="Zorbin Fandazzle scherzt über die Heldentat, Schleim aus dem Inneren elementarer Wesen zu sammeln, und fragt sich, ob Ihr mehr vom Selben wollt. Melodramatik beiseite, benötigt Zorbin tatsächlich weitere Wasserelementarkerne. Die Errichtung des Ladens hier ist ein verzweifeltes Geschäft, daher gibt es als Gegenleistung wenig zu geben, aber Zorbin verspricht, jedem in Hörweite zu erzählen, wie Ihr geholfen habt, und sagt, man solle darauf vertrauen, weil Zorbin Leute im Cartel kenne. Sechs Kerne werden verlangt, die von Sea Elementals und Sea Sprays an der Vergessenen Küste erbeutet und zu Zorbin nahe der Anlegestelle gebracht werden sollen."},{t="Zorbins Dank",b="Zorbin ist erfreut und räumt ein, dass die Münzen vielleicht nicht das Meiste sind, was Ihr je für eine solche Arbeit erhalten werdet. Den Kameraden von Zorbin im Steamwheedle Cartel wird von Euren Bemühungen berichtet werden, und wenn Ihr noch mehr zu tun wünscht, hat Zorbin einen fortlaufenden Bedarf an weiteren Kernen und ähnlichen Dingen."}},faq={{q="Wer bittet um die Wasserelementarkerne?",a="Zorbin Fandazzle, zu finden am Steg an der Vergessenen Küste von Feralas.",al={"wer gibt diese quest","wer ist zorbin fandazzle","wo ist zorbin"}},{q="Woher stammen die Wasserelementarkerne?",a="Sie werden von Sea Elementals und Sea Sprays an der Vergessenen Küste von Feralas erbeutet.",al={"wo droppen kerne","wasserelementarkern fundort","welche feinde lassen kerne fallen"}},{q="Warum benötigt Zorbin Fandazzle weitere Kerne?",a="Zorbin sagt lediglich, dass mehr Wasserelementarkerne benötigt werden, während er darum kämpft, einen Laden an der Küste aufzubauen.",al={"warum will zorbin kerne","zorbin fandazzle motiv","wofür sind die kerne"}},{q="Was geschah davor?",a="Es folgt auf Fuel for the Zapping, als Ihr zum ersten Mal Elementarkerne für Zorbin gesammelt habt.",al={"vorherige quest","vorbedingung quest","welche quest kommt zuerst"}}},fp="22,235,16.548.0,15.260.1,44.70.0,45.84.0,42.117.0,22.84.0"}
P.entries["quest:7727"] = {n="Incendosaurier? Was-auch-immer-Saurier?",s="Hansel Bleihand sagt, seine Ballenzehen hätten Ballenzehen, und mit seinen Füßen in solch einem Zustand könne er niemanden töten. Scrange und Burninate haben ihm aufgetragen, die Incendosaurier der Schlackengrube zu beseitigen, daher schickt er stattdessen Euch, um zwanzig zu erschlagen.",h="Hansel Bleihand sagt, seine Ballenzehen hätten Ballenzehen, und mit seinen Füßen in solch einem Zustand könne...",kw={"burninate","kessel","hansel bleihand","incendosaurier","scrange","sengende schlucht","die schlackengrube"},sec={{t="Ballenzehen auf Ballenzehen",b="Hansel Bleihand ist in keiner Verfassung zu kämpfen. Scrange und Burninate haben ihm aufgetragen, die Incendosaurier zu töten, damit Expeditionsteams in die Lavateiche der Schlackengrube hinabsteigen und sie erkunden können. Hansel überträgt die Arbeit auf Euch."},{t="Die Lavateiche",b="Die Incendosaurier bevölkern die Lavateiche unten in der Schlackengrube, innerhalb des Kessels. Hansel verlangt, dass zwanzig erschlagen werden, und möchte Euch nicht eher wiedersehen, bis Ihr dies vollbracht habt."}},faq={{q="Wer ist Hansel Bleihand?",a="Er ist derjenige, der Euch diese Aufgabe in der Sengenden Schlucht gibt. Scrange und Burninate haben ihm aufgetragen, sich um die Incendosaurier zu kümmern, aber mit seinen Ballenzehen kann er das nicht.",al={"hansel bleihand","wer ist der questgeber","wer vergibt diese quest"}},{q="Warum müssen die Incendosaurier beseitigt werden?",a="Scrange und Burninate wollen, dass Expeditionsteams die Lavateiche der Schlackengrube erkunden. Die Incendosaurier dort verursachen angeblich allerlei Probleme.",al={"warum incendosaurier töten","zweck der incendosaurier","warum die schlackengrube säubern"}},{q="Wo sind die Incendosaurier zu finden?",a="Unten in den Lavateichen der Schlackengrube, innerhalb des Kessels.",al={"ort der incendosaurier","wo ist die schlackengrube","wo sind die lavateiche"}},{q="Warum jagt Hansel sie nicht selbst?",a="Seine Ballenzehen hätten Ballenzehen, sagt er, und seine Füße seien in viel zu schlechtem Zustand für jegliche Jagd.",al={"warum kämpft hansel nicht","hansels füße","hansel ballenzehen"}}},fp="43,227,20.221.0,14.166.0,25.152.0,47.154.0,33.60.0,35.89.0"}
P.entries["quest:7728"] = {n="GESTOHLEN: Schmiedewindform und ein Ausguck-Handfernrohr",s="Ein Aushang listet zwei gestohlene Gegenstände auf: eine Dunkeleisenwindform und ein Ausguck-Handfernrohr. Die Thoriumbruderschaft ist sich sicher, dass skrupellose, eifersüchtige Dunkeleisenzwerge der Sengenden Schlucht sie an sich genommen haben, und wer auch immer sie findet, soll sie gegen Bezahlung zu Zuchtmeister Scrange bringen.",h="Ein Aushang listet zwei gestohlene Gegenstände auf: eine Dunkeleisenwindform und ein Ausguck-Handfernrohr.",kw={"dunkeleisen","scrange","sengende schlucht","schmieden","fernrohr","thoriumbruderschaft","windform"},sec={{t="Gestohlene Waren",b="Der Aushang bezeichnet das Fernrohr als feines Werkzeug für Ausgucker und die Windform als unersetzliches Schmiedewerkzeug. Alles, was man weiß, ist, dass Dunkeleisenzwerge sie definitiv an sich genommen haben. Wer auch immer sie findet, soll sie zu Zuchtmeister Scrange zurückbringen."}},faq={{q="Wer hat den Aushang angebracht?",a="Der Aushang spricht von der Thoriumbruderschaft, die sich sicher ist, dass Dunkeleisenzwerge die Gegenstände an sich genommen haben.",al={"wer die gestohlenen gegenstände will","wer diese quest vergeben hat","questgeber gestohlene schmiedewindform"}},{q="Wer hat die Werkzeuge gestohlen?",a="Die Thoriumbruderschaft ist sich sicher, dass es skrupellose und eifersüchtige Dunkeleisenzwerge der Sengenden Schlucht waren.",al={"wer die windform genommen hat","wer das fernrohr gestohlen hat","wer die gestohlenen gegenstände hat"}},{q="Wer erhält die wiederbeschafften Gegenstände?",a="Zuchtmeister Scrange in der Sengenden Schlucht.",al={"wo gebe ich das ab","wer ist zuchtmeister scrange","wer das fernrohr bekommt"}},{q="Wozu dienen die gestohlenen Gegenstände?",a="Die Windform ist ein unersetzliches Schmiedewerkzeug und das Fernrohr ist ein wertvolles Beobachtungswerkzeug für Ausgucker.",al={"was ist eine schmiedewindform","warum die bruderschaft die windform will","was das fernrohr bewirkt"}}},fp="46,258,12.236.0,22.100.0,20.106.0,33.40.0,30.115.0"}
P.entries["quest:7729"] = {n="STELLE ZU VERGEBEN: Erledige die Konkurrenz",s="Ein Aushang verkündet, dass Zuchtmeister Scrange fähige Hände sucht, um die Konkurrenz in der Sengenden Schlucht auszudünnen. Die Arbeit besteht darin, Dark Iron Taskmasters und Dark Iron Slavers zu erschlagen, bis Eure Kleidung blutig genug ist, und dann zu Scrange zurückzukehren.",h="Ein Aushang verkündet, dass Zuchtmeister Scrange fähige Hände sucht, um die Konkurrenz in der Sengenden...",kw={"culling the competition","dark iron slaver","dark iron taskmaster","job opportunity","sengende schlucht","zuchtmeister scrange"},sec={{t="Eine offene Stelle",b="Scrange möchte, dass Bewerber durch die Schlucht ziehen und die Dark Iron Taskmasters und Dark Iron Slavers abschlachten, die sie antreffen: jeweils fünfzehn von ihnen. Kehrt zurück, wenn Eure Kleidung blutig genug ist. Ihr werdet wissen, wann das der Fall ist, und Ihr sollt nicht fragen."}},faq={{q="Wer bietet diesen Auftrag an?",a="Zuchtmeister Scrange in der Sengenden Schlucht, der Hilfe beim Ausdünnen der Konkurrenz sucht.",al={"wer bietet diese quest an","wer will die zuchtmeister tot sehen","wer ist zuchtmeister scrange"}},{q="Welche Feinde müssen erschlagen werden?",a="Fünfzehn Dark Iron Taskmasters und fünfzehn Dark Iron Slavers.",al={"was muss ich toeten","ziele fuer job opportunity","wer ist die konkurrenz"}},{q="Woran erkennt Scrange, dass die Arbeit getan ist?",a="Am Zustand Eurer Kleidung. Scrange wird Euch mit und ohne sie wiegen, um sicherzugehen.",al={"wie toetungen beweisen","blutige kleidung anforderung","wie prueft scrange"}}},fp="40,242,16.243.0,25.80.0,28.60.0,39.86.0"}
P.entries["quest:773"] = {n="Ritus der Weisheit",s="Der Ritus der Weisheit ist die abschließende Prüfung der traditionellen Riten der Erdenmutter, die von jungen Abenteurern in Mulgore abgelegt werden. Nachdem sie ihren Blick durch den Ritus der Vision gereinigt haben, reisen die Bittsteller zu den heiligen Begräbnisstätten der Teufelsfelsen, um mit einem Vorfahrengeist Zwiesprache zu halten und den Segen der Toten zu empfangen.",h="Der Ritus der Weisheit ist die abschließende Prüfung der traditionellen Riten der Erdenmutter, die von jungen...",kw={"vorfahrengeist","mulgore","teufelsfelsen","ritus der weisheit","riten der erdenmutter","seher wiserunner","donnerfels","wasser der seher"},ang={["class:Druid"]="Der Ritus demonstriert das Gleichgewicht zwischen der lebendigen Welt und dem ewigen Kreislauf, über den die Erdenmutter wacht, und verankert junge Druiden in ihrer Pflicht gegenüber dem Land.",["class:Shaman"]="Die direkte Zwiesprache mit einem Vorfahrengeist bekräftigt die grundlegende schamanische Pflicht, die Toten zu ehren und den Geistern, die über Mulgore wachen, die Treue zu halten.",["race:Tauren"]="Für die Shu'halo ist der Erhalt des Mantels von den Ahnen bei den Teufelsfelsen der Höhepunkt des Übergangs ins vollwertige Erwachsenenalter und der Akzeptanz unter den Ältesten des Stammes."},sec={{t="Die Prüfung der Teufelsfelsen",b="Nachdem sie ihre Wahrnehmung durch den Ritus der Vision geklärt haben, werden junge Beschützer östlich von Donnerfels zu den Teufelsfelsen geschickt. Diese uralte Begräbnisstätte birgt die irdischen Überreste und verweilenden Geister jener, die kämpften und starben, um ein friedliches Dasein in Mulgore zu erkämpfen. Das Bestehen der Prüfung erfordert es, sich der Ruhestätte mit gebührender Ehrfurcht und Einkehr zu nähern und sich allen territorialen Bedrohungen zu stellen, die die Hügel durchstreifen, um den Rat der geehrten Toten zu suchen."},{t="Die Übergabe des Mantels",b="Auf dem Gipfel der Teufelsfelsen ist die Zwiesprache mit dem Vorfahrengeist keine Prüfung kriegerischer Stärke, sondern spiritueller Bereitschaft und Kontinuität. Die dort ruhenden Geister repräsentieren die Generation, die an der Seite von Cairne Bluthuf kämpfte, um Donnerfels zu gründen und die Stämme zu schützen. Durch den Empfang ihres Segens erbt der Bittsteller offiziell die feierliche Pflicht, die Stadt zu verteidigen, und verdient sich seinen Platz als anerkannter Erwachsener und Verteidiger, der würdig ist, Donnerfels mit Stolz zu betreten."}},faq={{q="Was ist der Zweck des Ritus der Weisheit?",a="Der Ritus der Weisheit vollendet die Riten der Erdenmutter und verbindet die visionäre Einkehr der Jugend mit den feierlichen Pflichten des Erwachsenseins. Indem Bittsteller den Segen der Geister der Ahnen erlangen, beweisen sie, dass sie die Opfer derer respektieren, die vor ihnen kamen, und bereit sind, Donnerfels zu verteidigen.",al={"warum ritus der weisheit machen","was bringt ritus der weisheit","ritus der weisheit zweck"}},{q="Wer schickt Euch auf den Ritus der Weisheit?",a="Seher Wiserunner in seiner Höhle nordwestlich des Dorfes der Bluthufe sendet Initianden auf diese Prüfung aus, sobald sie den Ritus der Vision erfolgreich abgeschlossen und vom Wasser der Seher getrunken haben.",al={"wer gibt ritus der weisheit","wo starte ich ritus der weisheit"}},{q="Wo findet Ihr den Vorfahrengeist?",a="Der Vorfahrengeist befindet sich bei den Teufelsfelsen, einer uralten Begräbnisstätte der Tauren, die in den felsigen Klippen direkt östlich von Donnerfels liegt.",al={"vorfahrengeist ort","wo ist der geist","wo finde ich den vorfahrengeist"}},{q="Warum ist der Ritus der Vision zuerst erforderlich?",a="Nur jene, die vom Wasser der Seher getrunken und deren geistiger Blick gereinigt wurde, sind in der Lage, die uralten Geister bei den Teufelsfelsen wahrzunehmen und ihren Segen zu empfangen.",al={"warum erst sicht machen","ritus der sicht voraussetzung","wasser der seher anforderung"}},{q="Was geschieht nach Abschluss des Ritus der Weisheit?",a="Nachdem sie die Gunst der Ahnen erlangt haben, werden die Initianden angewiesen, ihre offizielle Reise auf die Anhöhen von Donnerfels anzutreten.",al={"wie geht es nach dem ritus der weisheit weiter","folgequest nach ritus der weisheit"}},{q="Welche Kreaturen bedrohen die Stätten der Teufelsfelsen?",a="Der heilige Friedhof bei den Teufelsfelsen wurde von aggressiven Gnollen der Bleichmähnen heimgesucht, die entlang der felsigen Pfade lauern, welche zur uralten Begräbnisstätte hinaufführen.",al={"feinde bei den teufelsfelsen","was bewacht die teufelsfelsen","gnolle bei den teufelsfelsen"}}},fx={["740e2883"]={q="Warum schickt Euch Seher Wiserunner auf die Rite of Wisdom?",a="Seher Wiserunner führt vielversprechende junge Tauren durch die traditionellen Rites of the Earthmother. Nachdem er gesehen hat, wie Ihr die durch das Wasser der Seher gewährte Vision überstanden habt, schickt er Euch zu den Teufelsfelsen, damit Ihr den Segen der Vorfahren empfangen könnt. Für Wiserunner und die Ältesten stellt dieses Ritual sicher, dass nur diejenigen, die spirituell vorbereitet und von den Vorfahren anerkannt sind, in Donnerfels als Beschützer des Stammes willkommen geheißen werden.",al={"motiv von seher wiserunner","warum rite of wisdom","warum schickt ihr mich zur rite of wisdom"}},["8728f84f"]={q="Warum müsst Ihr gehen, anstatt dass Seher Wiserunner selbst geht?",a="Die Rite of Wisdom ist eine persönliche Prüfung des Übergangs, keine Besorgung, die jemand anderes für Euch erledigen kann. Um unter den Ältesten Akzeptanz zu finden und das Recht zu erlangen, Donnerfels zu betreten, müsst Ihr persönlich den Vorfahrengeist an den Teufelsfelsen aufsuchen und die spirituelle Klarheit demonstrieren, die Ihr durch das Wasser der Seher gewonnen habt. Die Pflicht, die Stadt zu schützen, kann nur direkt Euch übertragen werden.",al={"warum ich zur rite of wisdom","warum geht seher wiserunner nicht selbst","warum muss ich den vorfahrengeist aufsuchen"}}},fp="14,321,22.468.0,18.492.0,42.310.0,36.186.0,39.137.0,41.175.0,49.138.0,49.160.0"}
P.entries["quest:7730"] = {n="Zukk'ash-Plage",s="In Camp Mojache hat Hadoken Swiftstrider Kunde von insektenartigen Kreaturen, den Zukk'ash, südlich der Gnolle erhalten. Wenn sie die Gnolle in Raserei versetzen, stellen sie eine ebenso große Bedrohung dar wie die Gnolle, vielleicht sogar eine größere. Ihr werdet in ihre Heimat, Die Gewundene Tiefe, geschickt, um ihre Reihen zu lichten und zwanzig Chitinpanzer zurückzubringen.",h="In Camp Mojache hat Hadoken Swiftstrider Kunde von insektenartigen Kreaturen, den Zukk'ash, südlich der...",kw={"camp mojache","panzer","feralas","gnolle","hadoken swiftstrider","insekten","die gewundene tiefe","zukk'ash"},sec={{t="Der Feind südlich der Gnolle",b="Hadoken Swiftstrider glaubt, dass es sich bei dem Feind südlich der Gnolle um ein Volk insektenartiger Kreaturen handelt. Ob sie denken können, spielt für Hadoken kaum eine Rolle. Wenn sie die Gnolle gegen Camp Mojache in Raserei treiben, stellen sie eine ebenso große Gefahr dar wie die Gnolle selbst, oder gar eine noch größere. Ihr sollt tief in ihren Aufenthaltsort vordringen, der als Die Gewundene Tiefe bekannt ist, und ihre Reihen lichten. Die Chitinpanzer von zwanzig Zukk'ash sollen Euer Beweis sein, und Hadoken möchte hören, was Ihr vorfindet."},{t="Hadokens Urteil",b="Als Ihr zurückkehrt, ist Hadoken erfreut. Nur eine groß angelegte Invasion wird die Präsenz der Zukk'ash beenden können, doch Ihr habt dem Lager Zeit verschafft, um eine angemessene Strategie zu entwickeln. Die Chitinpanzer werden analysiert, da das Lager alles über diese Kreaturen in Erfahrung bringen muss. Dies hat sich unglücklicherweise zu einem weit größeren Problem entwickelt, als irgendjemand erwartet hatte."}},faq={{q="Wer schickt Euch hinter den Zukk'ash her?",a="Hadoken Swiftstrider in Camp Mojache in Feralas.",al={"questgeber","hadoken swiftstrider","wer startet heimsuchung der zukk'ash"}},{q="Was sind die Zukk'ash?",a="Hadoken glaubt, dass sie ein Volk insektenartiger Kreaturen südlich der Gnolle sind. Ob sie denken können, spielt für Hadoken keine Rolle, nur dass sie womöglich die Gnolle in Raserei versetzen.",al={"was sind zukk'ash","zukk'ash-insekten","ungeziefer der gewundenen tiefe"}},{q="Wo ist Die Gewundene Tiefe?",a="Dort hausen die Zukk'ash-Insekten, südlich der Gnolle.",al={"ort der gewundenen tiefe","wo ist die gewundene tiefe","wo sind die insekten"}},{q="Warum möchte Hadoken Zukk'ash-Chitinpanzer?",a="Hadoken möchte die Chitinpanzer als Beweis für Euer Werk gegen die Zukk'ash.",al={"warum panzer","nutzen von zukk'ash-panzern","zweck der panzer"}}},fp="20,317,27.474.0,17.347.1,33.49.0,22.185.0,27.60.0,41.79.0"}
P.entries["quest:7731"] = {n="Zornstachel",s="Beim Auskundschaften der Gewundenen Tiefe sichtete einer von Hadoken Swiftstriders Spähern ein riesiges Insekt, weit größer als die anderen, das durch das zerklüftete Terrain streift. Es hat den Namen Stinglasher erhalten, und Hadoken möchte, dass es erlegt wird und seine Sekretdrüsen nach Camp Mojache gebracht werden.",h="Beim Auskundschaften der Gewundenen Tiefe sichtete einer von Hadoken Swiftstriders Spähern ein riesiges...",kw={"camp mojache","feralas","drüsen","hadoken swiftstrider","insekt","stinglasher","die gewundene tiefe","zukk'ash"},sec={{t="Ein Riese unter den Insekten",b="Ein Späher in der Gewundenen Tiefe sah ein Insekt, das viel größer als die anderen war und durch das zerklüftete Terrain streifte. Es scheint zudem eine Aura auszustrahlen, die es vom Rest abhebt. Es hat den Namen Stinglasher erhalten. Seine Innereien wären von unschätzbarem Wert für Untersuchungen, während Hadoken herauszufinden versucht, wie man mit dieser neuen Bedrohung umgeht, daher möchte Hadoken, dass seine Sekretdrüsen herausgeschnitten und direkt nach Camp Mojache gebracht werden."},{t="Hadokens Dank",b="Hadoken ist äußerst beeindruckt. Sollte Stinglasher tatsächlich eines der stärksten unter den Insekten sein, wird sich die Untersuchung der Bestie mit der Zeit als wertvoll erweisen, und Hadokens Aufgabe ist es sicherzustellen, dass sich das Lager lange genug verteidigt, um daraus Nutzen zu ziehen. Ein Münzkopfgeld wird überreicht, verbunden mit dem Dank des gesamten Lagers."}},faq={{q="Wer schickt Euch hinter Stinglasher her?",a="Hadoken Swiftstrider in Camp Mojache in Feralas.",al={"questgeber","wer vergibt stinglasher","hadoken swiftstrider"}},{q="Wo ist Stinglasher zu finden?",a="Stinglasher streift durch das zerklüftete Terrain der Gewundenen Tiefe.",al={"stinglasher aufenthaltsort","wo ist stinglasher","aufenthaltsort der gewundenen tiefe"}},{q="Was unterscheidet Stinglasher von den anderen Insekten?",a="Ein Späher berichtete von einem Insekt von riesenhafter Größe, und es scheint eine Aura auszustrahlen, die den restlichen fehlt.",al={"warum stinglasher","was ist stinglasher","stinglasher aura"}},{q="Warum möchte Hadoken Stinglashers Drüsen?",a="Hadoken sagt, die Erforschung seiner Innereien wäre von unschätzbarem Wert, während ein Plan gegen diese neue Bedrohung ausgearbeitet wird.",al={"warum drüsen sammeln","zweck von stinglashers drüsen"}}},fp="11,274,25.401.0,16.278.1,32.49.0,27.68.0,56.89.0,43.105.0"}
P.entries["quest:7732"] = {n="Bericht über die Zukk'ash",s="Hadoken Swiftstrider sagt, Ihr hättet Euch gegen die Zukk'ash-Insekten, die Camp Mojache bedrohen, doppelt hervorgetan, doch die Gefahr sei noch lange nicht gebannt. Ein letzter Gefallen für die Horde: Bringt ein Dokument, das alles über die Zukk'ash In-Erfahrung-Gebrachte festhält, nach Orgrimmar zu Zilzibin Drumlore.",h="Hadoken Swiftstrider sagt, Ihr hättet Euch gegen die Zukk'ash-Insekten, die Camp Mojache bedrohen, doppelt...",kw={"camp mojache","drag","feralas","hadoken swiftstrider","orgrimmar","silithid","zilzibin drumlore","zukk'ash report"},sec={{t="Ein Dokument für die Gasse",b="Hadoken Swiftstrider besitzt ein Dokument, das alles festhält, was das Lager über die Zukk'ash-Insekten in Erfahrung gebracht hat. Die Gefahr, die von ihnen ausgeht, ist noch lange nicht gebannt, und Hadoken bittet Euch, es nach Orgrimmar zu bringen. Dort, in der Gasse, lebt Zilzibin Drumlore, ein Experte für fremdartige Kreaturen wie diese, und Hadoken hofft, dass das bisher gesammelte Wissen von Nutzen sein wird."},{t="Das Urteil des Experten",b="Zilzibin hat den Bericht bereits erwartet. Er bezeichnet die Kreaturen, denen Ihr gegenüberstandet, als eine uralte Bedrohung, die die Horde beharrlich ignoriert, und sagt, Hadoken sei weise gewesen, sowohl den Bericht als auch Euch zu schicken. Die Zukk'ash seien nichts anderes als Kreaturen namens Silithiden. Manche halten sie für ein geistloses Ärgernis, doch Zilzibin versichert Euch, dass sie eine weit schlimmere Bedrohung darstellen als alles, was die Allianz aufbieten könnte."}},faq={{q="Wer schickt den Bericht nach Orgrimmar?",a="Hadoken Swiftstrider in Camp Mojache in Feralas überreicht Euch das Dokument.",al={"wer vergibt zukkash report","wer startet zukkash report","questgeber"}},{q="Wem wird der Bericht überbracht?",a="Zilzibin Drumlore, der in der Gasse von Orgrimmar weilt.",al={"wohin geht der bericht","wer erhaelt zukkash report","drumlore standort"}},{q="Warum wird das Dokument nach Orgrimmar gebracht?",a="Zilzibin Drumlore ist ein Experte für fremdartige Kreaturen wie die Zukk'ash, und Hadoken hofft, dass das vom Lager gesammelte Wissen von Nutzen sein wird.",al={"warum nach orgrimmar senden","zweck des berichts"}},{q="Was ging dieser Lieferung voraus?",a="Sie folgt auf Eure Bemühungen gegen die Zukk'ash-Insekten in Zukk'ash Infestation und Stinglasher.",al={"vorherige quests","voraussetzungen"}}},fp="15,267,23.347.0,20.377.1,34.71.0,32.59.0,39.142.0,31.94.0"}
P.entries["quest:7733"] = {n="Beste Qualität",s="Pratt McGrubben hat von Häuten gehört, die noch besser als die letzten sind. Oben im Norden von Feralas, im Inneren der Wutschrammfeste, streift eine weitere Schar von Yetis umher, die zäher sind als jene, denen Ihr zuvor gegenüberstandet. Zehn ihrer Häute werden in der Mondfederfeste gesucht.",h="Pratt McGrubben hat von Häuten gehört, die noch besser als die letzten sind.",kw={"mondfederfeste","feralas","verbesserte qualität","pratt mcgrubben","wutschrammfeste","thorium","yetihaut","yetis"},sec={{t="Eine zähere Schar von Yetis",b="Nach Das Zeichen der Qualität hat Pratt McGrubben einen Hinweis auf einen noch edleren Vorrat an Häuten ausfindig gemacht. Oben im Norden von Feralas, im Inneren der Wutschrammfeste, lebt eine weitere Schar von Yetis, die zäher sind als jene, denen Ihr zuvor gegenüberstandet. Pratt McGrubben wird für zehn ihrer Häute fürstlich bezahlen, die zur Beilegung der Angelegenheit zur Mondfederfeste zurückgebracht werden. Sollten sie der Qualität der Feralnarbenhäute entsprechen, könnten sie sich als so widerstandsfähig wie Thorium erweisen."},{t="Pratts Dank",b="Die Häute sind sogar noch besser als erhofft. Pratt McGrubben sieht bereits, dass sie deutlich härter werden, sobald sie richtig gehärtet sind, und überreicht Euch zum Dank eine der neuesten Schöpfungen."}},faq={{q="Wer verlangt die Häute der Wutschrammyetis?",a="Pratt McGrubben in der Mondfederfeste in Feralas.",al={"wer gibt verbesserte qualität","verbesserte qualität questgeber","pratt mcgrubben"}},{q="Wo leben die Wutschrammyetis?",a="Im Inneren der Wutschrammfeste im Norden von Feralas.",al={"aufenthaltsort der wutschrammyetis","wo ist die wutschrammfeste","wo man wutschrammhaut bekommt"}},{q="Wie viele Häute werden gesucht?",a="Pratt McGrubben verlangt zehn Häute der Wutschrammyetis.",al={"wie viele yetihäute","verbesserte qualität benötigte gegenstände"}},{q="Was ging dem voraus?",a="Es folgt auf Das Zeichen der Qualität, als Ihr Euch um die erste Schar von Yetis gekümmert habt.",al={"vorquest","welche quest führt zu verbesserte qualität","vorherige quest"}}},fp="16,238,25.430.0,14.171.1,38.54.0,34.47.0,26.47.0,22.78.0"}
P.entries["quest:7734"] = {n="Beste Qualität",s="Jangdor Swiftstrider hat von Bälgen gehört, die noch besser sind als die letzten. Oben im Norden von Feralas, im Inneren der Wutschrammfeste, streift eine weitere Schar von Yetis umher, die zäher sind als jene, denen Ihr zuvor gegenüberstandet. Zehn ihrer Bälge werden in Camp Mojache gesucht.",h="Jangdor Swiftstrider hat von Bälgen gehört, die noch besser sind als die letzten.",kw={"camp mojache","feralas","verbesserte qualität","jangdor swiftstrider","wutschrammfeste","wutschrammyeti","yetibälge"},sec={{t="Eine zähere Schar von Yetis",b="Nach The Mark of Quality hat Jangdor Swiftstrider einen Hinweis auf einen noch feineren Vorrat an Bälgen erhalten. Oben im Norden von Feralas, im Inneren der Wutschrammfeste, lebt eine weitere Schar von Yetis, die zäher sind als jene, denen Ihr zuvor gegenüberstandet. Jangdor Swiftstrider wird für zehn ihrer Bälge gut bezahlen, wenn sie nach Camp Mojache gebracht werden, um die Angelegenheit abzuschließen. Sollten sie der Qualität der Bälge der Feral Scar entsprechen, könnten sie sich als so widerstandsfähig wie Thorium erweisen."},{t="Jangdors Dank",b="Die Bälge sind sogar noch besser als erhofft. Jangdor Swiftstrider erkennt bereits, dass sie nach ordentlichem Gerben viel härter werden, und überreicht Euch zum Dank eine der neuesten Schöpfungen."}},faq={{q="Wer verlangt die Bälge der Wutschrammyetis?",a="Jangdor Swiftstrider, in Camp Mojache in Feralas.",al={"wer vergibt verbesserte qualität","questgeber verbesserte qualität","jangdor swiftstrider"}},{q="Wo leben die Wutschrammyetis?",a="Im Inneren der Wutschrammfeste, im Norden von Feralas.",al={"aufenthaltsort der wutschrammyetis","wo liegt die wutschrammfeste","woher bekommt man wutschrammbälge"}},{q="Wie viele Bälge werden gesucht?",a="Jangdor Swiftstrider verlangt zehn Bälge der Wutschrammyetis.",al={"wie viele yetibälge","benötigte gegenstände für verbesserte qualität"}},{q="Was ging dem voraus?",a="Es folgt auf The Mark of Quality, als Ihr es mit der ersten Schar von Yetis aufgenommen habt.",al={"vorquest","welche quest führt zu verbesserte qualität","vorherige quest"}}},fp="16,233,25.430.0,16.176.1,38.49.0,34.47.0,26.52.0,22.78.0"}
P.entries["quest:7735"] = {n="Makelloser Yetibalg",s="Ihr seid in den Besitz eines Yetibalgs gelangt, der ungewöhnlich dick und zäh ist – zäher noch als jeder andere, den Ihr bei den Yetis von Rage Scar gesehen habt. Pratt McGrubben bei der Mondfederfeste sucht nach Yetibälgen, und dieser hier könnte sein Interesse wecken.",h="Ihr seid in den Besitz eines Yetibalgs gelangt, der ungewöhnlich dick und zäh ist – zäher noch als jeder...",kw={"mondfederfeste","feralas","pratt mcgrubben","makelloser yetibalg","rage scar","yetipelz"},sec={{t="Ein Balg der besonderen Art",b="Dieser Balg ist makellos und deutlich dicker sowie robuster als die Bälge, die man von den Yetis von Rage Scar erbeutet. Pratt McGrubben bei der Mondfederfeste in Feralas möchte Yetibälge kaufen, daher lohnt es sich, ihm diesen zu bringen."},{t="Pratts Reaktion",b="Pratt ist verblüfft und fragt sich laut, ob dies der großartigste Yetibalg sein könnte, den es überhaupt gibt. Pratt wird Euch dafür bezahlen – mehr, als ein einzelner Balg für gewöhnlich einbringt – und glaubt, dass sich daraus etwas ganz Besonderes herstellen lässt."}},faq={{q="Wer möchte den Makellosen Yetibalg?",a="Pratt McGrubben bei der Mondfederfeste in Feralas, der Yetibälge kaufen möchte.",al={"wer nimmt makelloser yetibalg","wohin bringe ich den yetibalg","pratt mcgrubben yetibalg"}},{q="Was macht diesen Balg besonders?",a="Er ist ungewöhnlich dick und zäh und übertrifft sogar die Bälge, die von den Yetis von Rage Scar stammen.",al={"herkunft von makelloser yetibalg","was macht den balg besonders","feralas yetibalg"}},{q="Wo befindet sich Pratt McGrubben?",a="Bei der Mondfederfeste in Feralas.",al={"wo ist pratt mcgrubben","wohin makelloser yetibalg bringen"}}},fp="18,230,26.223.0,16.201.1,33.87.0,29.89.0,25.37.0"}
P.entries["quest:7736"] = {n="Nachschub an feurigem Fluxus: Königsblut",s="Nach What the Flux? widmet sich Meisterschmied Burninate dem Auffüllen des schwindenden Vorrats an feurigem Fluxus in der Sengenden Schlucht. Burninate verlangt nach Incendosaurierschuppen, Königsblut und Kohle und nimmt alles an, was Ihr erübrigen könnt.",h="Nach What the Flux?",kw={"burninate","kohle","feuriger fluxus","incendosaurier","königsblut","sengende schlucht","thoriumbruderschaft"},sec={{t="Feuriger Fluxus gesucht",b="Meisterschmied Burninate hat keine Zeit für müßiges Geschwätz. Der feurige Fluxus geht zur Neige, und Burninate verlangt nach Incendosaurierschuppen, Königsblut und Kohle: zwei Schuppen, vier Königsblut und Kohle. Burninate nimmt alles an, was Ihr anbieten könnt."}},faq={{q="Wer verlangt nach diesen Waren?",a="Meisterschmied Burninate in der Sengenden Schlucht, der die Waren persönlich entgegennimmt.",al={"wer vergibt diese quest","burninate feuriger fluxus","wo abgeben"}},{q="Welche Materialien möchte Burninate haben?",a="Zwei Incendosaurierschuppen, vier Königsblut und etwas Kohle.",al={"welche gegenstände brauche ich","materialien für feurigen fluxus","burninate gegenstände abgeben"}},{q="Was ging dieser Anfrage voraus?",a="Der Schritt namens What the Flux?, den Burninate Euch zuvor gab.",al={"voraussetzung für diese quest","vorherige quest feuriger fluxus","what the flux voraussetzung"}},{q="Warum möchte Burninate diese Waren haben?",a="Burninate sagt, dass der Vorrat an feurigem Fluxus schwindet, und möchte ihn wieder auffüllen.",al={"warum feuriger fluxus","burninate motivation"}}},fp="44,214,17.224.0,25.78.0,35.55.0,30.69.0,36.78.0"}
P.entries["quest:7738"] = {n="Perfekter Yetibalg",s="Ihr habt einen Yetibalg gefunden, der wohl perfekt sein könnte: bemerkenswert dick und zäh, weit über dem, was die Yetis von Rage Scar einbringen. In Camp Mojache sucht Jangdor Swiftstrider nach Yetibälgen.",h="Ihr habt einen Yetibalg gefunden, der wohl perfekt sein könnte: bemerkenswert dick und zäh, weit über dem...",kw={"camp mojache","feralas","jangdor swiftstrider","perfekter yetibalg","rage scar","yetifell"},sec={{t="Ein Balg, den man herzeigen sollte",b="Der Balg ist deutlich dicker und robuster als jene von den Yetis von Rage Scar. In Camp Mojache in Feralas möchte Jangdor Swiftstrider Yetibälge kaufen, daher lohnt es sich, diesen dorthin zu bringen."},{t="Jangdors Urteil",b="Jangdor ist erfreut und bezeichnet ihn als den feinsten Yetibalg, den er je gesehen hat. Eine angemessene Belohnung ist angebracht, mehr als er gewöhnlich für einen einzelnen Balg bezahlt, und er ist zuversichtlich, dass sich daraus etwas Besonderes herstellen lässt."}},faq={{q="Wer interessiert sich für den Perfect Yeti Hide?",a="Jangdor Swiftstrider in Camp Mojache in Feralas, der Yetibälge kaufen möchte.",al={"wer will den balg","wer gibt perfekten yetibalg ab","jangdor yetifell"}},{q="Warum gilt dieser Balg als besonders?",a="Er ist ungewöhnlich dick und zäh und könnte durchaus perfekt sein, besser als die Bälge von Rage Scars Yetis.",al={"warum ist er perfekt","was macht den balg besonders"}},{q="Wo befindet sich Jangdor Swiftstrider?",a="In Camp Mojache in Feralas.",al={"wo ist jangdor swiftstrider","wohin mit perfektem yetibalg"}}},fp="17,187,20.194.0,17.205.1,43.78.0,36.103.0,30.27.0"}
P.entries["quest:775"] = {n="Reise nach Donnerfels",s="Reise nach Donnerfels ist die abschließende Pilgerreise, die das Ende der Prüfungen eines jungen Helden in ganz Mulgore markiert. Nachdem Der Abenteurer die heiligen Riten der Erdenmutter unter der Führung der Geister vollendet hat, wird ihm eine Audienz beim Obersten Häuptling der Tauren, Cairne Bluthuf, gewährt.",h="Reise nach Donnerfels ist die abschließende Pilgerreise, die das Ende der Prüfungen eines jungen Helden in...",kw={"vorfahrengeist","cairne bluthuf","high rise","reise nach donnerfels","mulgore","riten der erdenmutter","donnerfels"},ang={["faction:Horde"]="Die Bereitschaft der Tauren, jedes verbündete Volk willkommen zu heißen, das ihre heiligen Traditionen vollendet, zeugt von dem gegenseitigen Respekt, der die junge Horde zusammenhält.",["race:Tauren"]="Für einen jungen Tauren ist das Vortreten vor Cairne Bluthuf nach Abschluss der Riten der Erdenmutter die entscheidende Schwelle zum Erwachsenenalter und zur Stammeshundsehre."},sec={{t="Ein abgeschlossener Übergangsritus",b="Bevor irgendein Reisender oder junger Krieger wahrhaft behaupten kann, sich in Mulgore bewiesen zu haben, muss er sich den uralten Riten der Erdenmutter unterziehen. Diese Prüfungen testen Stärke, Weitsicht und Weisheit auf den wogenden Ebenen und an den Ahnenstätten des Landes. Sobald der Vorfahrengeist den letzten Ritus anerkennt, gilt der Initiand als würdig, die Stadt Donnerfels nicht bloß als Besucher zu betreten, sondern als geehrter Verteidiger des Volkes der Tauren."},{t="Aufstieg zum High Rise",b="Die Quest führt den Reisenden von der heiligen Stätte, an der die Geister wandeln, direkt zu den aufragenden Höhen von Donnerfels. Hoch oben auf den Mesas gelegen, ist die Stadt ein aus rotem Stein gemeißelter Zufluchtsort des Friedens, getragen von weit gespannten Seilbrücken und gewaltigen Holzaufzügen. Dort, auf dem High Rise, erwartet Oberster Häuptling Cairne Bluthuf jene persönlich, die den Pfad der Ahnen beschritten haben."}},faq={{q="Wer schickt Euch auf diese Reise?",a="Die Quest wird von einem Vorfahrengeist verliehen, nachdem Ihr den Ritus der Weisheit abgeschlossen habt, den letzten Schritt der traditionellen Riten der Erdenmutter.",al={"wer vergibt quest","vorfahrengeist quest","questgeber"}},{q="Wo finde ich Cairne Bluthuf?",a="Cairne Bluthuf residiert auf dem High Rise, der zentralen erhöhten Mesa in Donnerfels, die die umliegenden roten Hochebenen und Ebenen überblickt.",al={"cairne aufenthaltsort","wo ist cairne","donnerfels anführer"}},{q="Welche Bedeutung hat der Abschluss dieser Quest?",a="Sie dient als feierlicher Abschluss der einleitenden Abenteuer in Mulgore. Indem Ihr Euch Cairne vorstellt, werdet Ihr von der Führung der Tauren vollends anerkannt und seid bereit, Pflichten in der gesamten Horde zu übernehmen.",al={"warum cairne besuchen","bedeutung der riten","bedeutung der reise nach donnerfels"}},{q="Vollenden nur Tauren diese Reise?",a="Obwohl es sich um einen zutiefst traditionellen Übergangsritus der Tauren handelt, wird jedem Mitglied der Horde, das seine Hingabe durch die Riten der Erdenmutter beweist, dieselbe Ehre zuteil und die Audienz beim Obersten Häuptling gewährt.",al={"können orcs das machen","wer kann reise nach donnerfels machen","völker"}},{q="Was geschieht nach dem Gespräch mit Cairne?",a="Cairne heißt Euch in seiner Heimat willkommen, würdigt Eure Taten und weist Euch den Weg zu den größeren Konflikten, denen sich die Horde in Kalimdor gegenübersieht.",al={"nächste quest","was nach cairne","nach reise nach donnerfels"}},{q="Wie erreicht man den High Rise in Donnerfels?",a="Nehmt die großen mechanischen Aufzüge von den Ebenen unten hinauf zu den Mesas und überquert dann die Seil- und Holzbalkenbrücken, die zur zentralen Plattform des High Rise führen, wo die Hütte des Häuptlings steht.",al={"weg zum high rise","wie man zu cairne kommt","donnerfels aufzüge"}}},fx={["74afb15b"]={q="Warum schickt Euch der Vorfahrengeist nach Donnerfels?",a="Indem Ihr die Prüfungen in ganz Mulgore überlebt und mit den Geistern kommuniziert habt, habt Ihr Eure Weisheit, Stärke und Hingabe durch die Rites of the Earthmother bewiesen. Der Vorfahrengeist schickt Euch nach Donnerfels, damit Eure Taten vom Volk der Tauren und ihrem höchsten Anführer, Cairne Bluthuf, anerkannt werden können. Vor dem Hochhäuptling zu stehen markiert Eure formelle Aufnahme in ihre Gesellschaft als geehrter Champion.",al={"warum schickt euch der vorfahrengeist","motiv des vorfahrengeists","warum zu cairne gehen"}},c86a41a9={q="Warum müsst Ihr die Nachricht selbst an Cairne Bluthuf überbringen?",a="Die Rites of the Earthmother sind eine heilige persönliche Prüfung. Der Vorfahrengeist ist ein jenseitiger Führer, der an die heiligen Stätten von Mulgore gebunden ist und nicht in der Lage oder gewillt ist, irdische Berichte zu überbringen. Da es Euer Geist und Eure Entschlossenheit waren, die getestet wurden, gebührt die Ehre, Euch selbst bei Hochhäuptling Cairne Bluthuf vorzustellen, allein Euch.",al={"warum ich zu cairne","warum muss ich cairne besuchen","warum muss ich cairne bluthuf sehen"}}},fp="26,296,27.451.0,26.407.0,30.141.0,34.138.0,50.216.0,37.208.0,38.141.0,48.197.0"}
P.entries["quest:776"] = {n="Riten der Erdenmutter",s="Diese Prüfung, die direkt von Oberhäuptling Cairne Bluthuf auferlegt wird, beauftragt aufstrebende Helden damit, das gewaltige Kodobiest Arra'chea in den Ebenen von Mulgore zur Strecke zu bringen. Auch wenn ein Initiant die traditionellen Übergangsriten abgeschlossen haben mag, erwartet Cairne von seinem Volk, dass es seine Stärke, seine Fährtenlesekunst und seine Hingabe an den Stamm fortwährend unter Beweis stellt. Die Rückkehr mit Arra'cheas Horn beweist, dass ein Abenteurer bereit ist, der größeren Horde jenseits der Mesas zu dienen.",h="Diese Prüfung, die direkt von Oberhäuptling Cairne Bluthuf auferlegt wird, beauftragt aufstrebende Helden...",kw={"arra'chea","arrachea","bloodhoof","cairne","erdenmutter","horn","jagd","kodo","mulgore","donnerfels"},ang={["class:Hunter"]="Das Nachstellen eines einsamen, wandernden Ungetüms wie Arra'chea in den goldenen Ebenen verkörpert die uralten Jagdphilosophien, die taurische Fährtenlesermeister über Generationen hinweg weitergeben.",["faction:Horde"]="Das Erlegen von Arra'chea liefert unverzichtbare Nahrung, Leder und Materialien für Donnerfels und verdeutlicht die gemeinschaftliche Überlebensmentalität, die die noch junge Horde zusammenhält.",["race:Tauren"]="Vor Cairne Bluthuf zu treten, um das Horn von Arra'chea zu beanspruchen, ist der ultimative Übergangsritus für einen jungen Shu'halo, der beweist, dass Eure Tüchtigkeit sowohl Eure Ahnen als auch die Herden von Mulgore ehrt."},sec={{t="Der Maßstab eines Häuptlings",b="Das Erreichen von Donnerfels markiert für einen Tauren das Ende der einfachen Jugend, doch Oberhäuptling Cairne Bluthuf lässt junge Jäger sich nicht auf ihren Lorbeeren ausruhen. Für Cairne ist das Verdienen eines Platzes auf den hohen Klippen lediglich der Beginn der eigenen Verantwortung gegenüber den Vereinten Taurenstämmen. Anstatt die Initianten gegen unbedeutendes Ungeziefer auszusenden, verlangt er den Beweis echten Geschicks im Feld: das Aufspüren und die saubere Erlegung einer der berühmtesten wandernden Bestien von Mulgore."},{t="Die Jagd nach Arra'chea",b="Die Beute ist Arra'chea, ein gewaltiger, legendärer Kodo, dessen weite Wanderung durch das goldene Gras nordöstlich von Donnerfels führt. Um eine solche Kreatur zu fällen, braucht es mehr als rohe Gewalt; es erfordert geduldiges Pirschen durch die offene Savanne und Respekt vor einem Titanen der Ebenen. Die Rückkehr mit Arra'cheas Horn auf die High Rise bringt nicht nur persönlichen Ruhm, sondern auch Vorräte für die Stadt, da Cairne umgehend Kürschner und Sammler entsendet, um sicherzustellen, dass nichts von der heiligen Bestie verschwendet wird."}},faq={{q="Wer vergibt diese Quest?",a="Oberhäuptling Cairne Bluthuf selbst vergibt diese Aufgabe von seinem Sitz auf der High Rise von Donnerfels.",al={"questgeber","wer vergibt riten der erdenmutter","cairne quest"}},{q="Was ist Arra'chea?",a="Arra'chea ist ein furchterregender, berühmter Kodo, der die Ebenen von Mulgore durchstreift. Sein mächtiges Horn dient als Beweis für die Fährtenlesekunst und die kriegerische Tüchtigkeit eines Jägers.",al={"wer ist arrachea","was ist arrachea","arrachea lore"}},{q="Wo kann man Arra'chea finden?",a="Arra'chea zieht für gewöhnlich auf einem weiten Rundweg nordöstlich der Klippen von Donnerfels umher und durchstreift langsam im Uhrzeigersinn Die wogenden Ebenen.",al={"wo ist arrachea","arrachea aufenthaltsort","arrachea route"}},{q="Warum verlangt Cairne diese Jagd, nachdem die früheren Riten bereits abgeschlossen wurden?",a="In der Kultur der Tauren bedeutet das anfängliche Verdienen des eigenen Platzes nicht das Ende der Pflicht. Cairne lehrt, dass Stärke, Demut und jagdliches Geschick fortwährend unter Beweis gestellt werden müssen, um das Überleben des Stammes zu sichern.",al={"warum diese quest machen","warum arrachea töten","sinn der riten"}},{q="Was geschieht mit Arra'cheas Körper, nachdem das Horn genommen wurde?",a="Im Einklang mit den Traditionen der Tauren, ihre Beute zu ehren, sendet Cairne einen Sammeltrupp aus, um das Fleisch und das Leder der erlegten Bestie zu bergen, damit die Jagd Donnerfels mit Nahrung und Kleidung versorgt.",al={"arrachea fleisch","was passiert mit dem kodo","kadavar lore"}},{q="Ist dies dieselbe Quest wie die frühen Riten zu Beginn?",a="Nein. Während die frühen Prüfungen in Camp Narache einem Initianten die grundlegenden Riten der Erdenmutter beibringen, ist diese abschließende Prüfung in Donnerfels Cairnes persönlicher Test Eures anhaltenden Wertes als Jäger.",al={"riten der erdenmutter unterschiede","welche riten quest","camp narache riten"}}},fx={d7a516d7={q="Wozu dient das Horn von Arra'chea?",a="Das Horn dient als physischer Beweis Eurer erfolgreichen Jagd. Die Tradition der Tauren legt großen Wert auf die Fähigkeiten, mächtige Bestien aufzuspüren und zu erlegen, und das direkte Überreichen von Arra'cheas Horn an Hochhäuptling Cairne Bluthuf beweist, dass Ihr über die nötigen Fähigkeiten verfügt, um für Euer Volk zu sorgen und es zu beschützen.",al={"gebrauch des horns von arra'chea","warum das horn von arra'chea nehmen","zweck des horns von arra'chea"}},a7e696eb={q="Warum schickt Cairne Bluthuf Euch und nicht die Stadtwachen?",a="Diese Jagd ist keine Aufgabe der Verteidigung oder des einfachen Ressourcensammelns – es ist eine traditionelle Prüfung. Obwohl Ihr die anfänglichen Rites of the Earthmother bestanden haben mögt, um Donnerfels zu erreichen, erwartet Cairne von jedem Jäger des Stammes, dass er seinen Wert und seine Eigenständigkeit kontinuierlich durch große Taten beweist, anstatt sich auf vergangenen Leistungen auszuruhen.",al={"warum schickt ihr mich","warum keine wachen für arra'chea schicken","warum braucht cairne mich"}}},fp="24,439,21.449.0,22.491.0,21.108.0,18.161.0,27.154.0,78.183.0,57.183.0,50.204.0"}
P.entries["quest:777"] = {n="Das wird schwierig",s="Lucien Tosselwrench überreicht Euch Zahnrad #5 für Lotwil Veriatus und sucht Deckung, wobei er Euch einlädt mitzukommen.",h="Lucien Tosselwrench überreicht Euch Zahnrad #5 für Lotwil Veriatus und sucht Deckung, wobei er Euch einlädt...",kw={"ödland","zahnrad 5","lotwil veriatus","lucien tosselwrench","fesseln","das wird nicht leicht"},sec={{t="Hinter der Deckung",b="Lucien übergibt das Zahnrad und fordert Euch auf, es zu Lotwil Veriatus zu bringen. Lucien wird hinter einer Deckung warten, und Ihr könnt Euch ihm gerne anschließen. Als Ihr Lotwil erreicht, der immer noch über die Fesseln gebeugt ist, streckt er eine Hand aus und wackelt ungeduldig mit den Fingern nach dem Zahnrad."},{t="Geschichte schreiben",b="Lotwil nimmt das Zahnrad, bezeichnet es als perfekt und weist Euch an zurückzutreten, während Vorbereitungen getroffen werden, um weitere Geschichte zu schreiben. Lotwil arbeitet fieberhaft weiter."}},faq={{q="Wer übergibt das Zahnrad für Lotwil?",a="Lucien Tosselwrench gibt Euch Zahnrad #5, damit Ihr es zu Lotwil Veriatus bringt.",al={"wer übergibt das zahnrad","woher bekommt man zahnrad 5","lucien zahnrad"}},{q="Wohin geht Lucien?",a="Lucien begibt sich in Deckung und sagt, dass Ihr Euch ihm gern anschließen könnt.",al={"warum versteckt sich lucien","lucien deckung"}},{q="Was macht Lotwil, als Ihr das Zahnrad bringt?",a="Lotwil arbeitet an einem Satz Fesseln und streckt, ohne aufzusehen, ungeduldig eine Hand nach dem Zahnrad aus.",al={"was macht lotwil","lotwil fesseln","lotwil fortschritt"}}},fp="24,106,12.254.0,14.158.1,34.65.0,21.58.0,44.105.0"}
P.entries["quest:778"] = {n="Das wird schwierig",s="Lotwil Veriatus erklärt die Fesseln für fertiggestellt und fordert Lucien, Servo und Euch auf, Zeuge zu sein, als ein mächtiger Elementar beschworen wird.",h="Lotwil Veriatus erklärt die Fesseln für fertiggestellt und fordert Lucien, Servo und Euch auf, Zeuge zu sein...",kw={"ödland","elementar","fam'retor guardian","lotwil veriatus","lucien","servo","shackles of elemental binding"},sec={{t="Ein bahnbrechender Tag",b="Lotwil ruft aus, dass die Fesseln fertig sind und die Zeit gekommen ist, und fordert Lucien und Servo auf, zusammen mit Euch Zeuge zu sein. Lotwil präsentiert die Fesseln als perfekte Kombination aus Alchemie, Ingenieurskunst und dem Arkanen und beabsichtigt, an einem Tag, der für alle Anwesenden zu einem bahnbrechenden Tag erklärt wird, einen mächtigen Elementar zu beschwören."},{t="Nach der Beschwörung",b="Das Ergebnis entspricht nicht dem, was Lotwil erwartet hat, und Lotwil bittet Euch, die Shackles of Elemental Binding zurückzuholen, nachdem der Fam'retor Guardian besiegt wurde. Danach ist Lotwil unsicher, was schiefgelaufen ist, ist aber froh darüber, dass die Magie zur Hand war, um die Kreatur auf die Ebene zurückzuschicken, von der sie stammte."}},faq={{q="Wer ist Lotwil Veriatus?",a="Lotwil Veriatus ist der Schöpfer der Shackles of Elemental Binding, in denen Alchemie, Ingenieurskunst und das Arkane vereint sind. Lucien und Servo sind zusammen mit Lotwil im Ödland.",al={"wer ist lotwil","lotwil veriatus"}},{q="Was sind die Shackles of Elemental Binding?",a="Sie sind die Fesseln, die Lotwil gerade fertiggestellt hat, eine Kombination aus Alchemie, Ingenieurskunst und dem Arkanen, zur Verwendung bei einem mächtigen Elementar, den Lotwil zu beschwören gedenkt.",al={"was sind die fesseln","shackles of elemental binding"}},{q="Wen ruft Lotwil auf, Zeuge zu sein?",a="Lotwil fordert Lucien und Servo auf, zusammen mit Euch Zeuge der Beschwörung zu sein.",al={"wer ist lucien","wer ist servo"}},{q="Was geht diesem Schritt voraus?",a="Es folgt auf den Schritt, in dem Ihr Zahnrad Nr. 5 zu Lotwil gebracht habt.",al={"vorherige quest","was dazu führte"}}},fp="24,134,20.317.0,19.287.1,23.181.0,43.162.0,37.85.0,28.58.0"}
P.entries["quest:7781"] = {n="Der Herrscher des Schwarzfels",s="Der Herrscher des Schwarzfels ist eine Quest der Allianz, die durch das Erbeuten des abgetrennten Kopfes des schwarzen Drachen Nefarian im Pechschwingenhort initiiert wird. Die Übergabe dieser monströsen Trophäe an Hochlord Bolvar Fordragon in Burg Sturmwind verkündet den Untergang des Meisters vom Schwarzfels. Sie markiert einen der größten militärischen Triumphe, den die Allianz in der jüngeren Geschichte gefeiert hat.",h="Der Herrscher des Schwarzfels ist eine Quest der Allianz, die durch das Erbeuten des abgetrennten Kopfes des...",kw={"der schwarzfels","pechschwingenhort","hochlord bolvar fordragon","kopf von nefarian","der herrscher des schwarzfels","nefarian","burg sturmwind"},ang={["faction:Alliance"]="Die Präsentation des Kopfes des schwarzen Drachen Nefarian ist eine der größten militärischen Errungenschaften der Allianz und zerschlägt die Pläne des Drachenschwarms gegen die Gebiete der Menschen entscheidend.",["race:Human"]="Sturmwind hat unzählige Einfälle und Komplotte erlitten, die vom Schwarzfels aus inszeniert wurden; seinen besiegten Meister zu sehen, verschafft dem Reich lang ersehnte Vergeltung und Erleichterung."},sec={{t="Ein Denkmal des Sieges",b="Nefarian, der tückische Brutmeister des Schwarzer Drachenschwarm und Herrscher der oberen Schwarzfelsspitze, hat lange Zeit einen schrecklichen Schatten über die umliegenden Menschenkönigreiche geworfen. Ihn zu erschlagen ist nicht nur ein Akt des Überlebens; es repräsentiert die völlige Zerschlagung seiner verdrehten Experimente und Intrigen. Seinen kolossalen, kampfgezeichneten Kopf zurück nach Sturmwind zu bringen, dient als unbestreitbarer Beweis dafür, dass der Herrscher des Schwarzfels durch die Hände der größten Helden der Allianz sein Ende gefunden hat."},{t="Audienz in Burg Sturmwind",b="Die grausige Trophäe wird direkt zu Hochlord Bolvar Fordragon gebracht, der das Königreich vom Thronsaal von Burg Sturmwind aus regiert. Die plötzliche Ankunft des abgetrennten Kopfes eines Drachen im königlichen Hof schockiert die Zuschauer und gebietet sofortigen Respekt. Für ein Königreich, das bereits unter internen politischen Streitigkeiten und externen Bedrohungen leidet, sorgt dieser Sieg für einen gewaltigen Anstieg der Moral und einen unvergesslichen Eintrag in die Annalen der Geschichte der Allianz."}},faq={{q="Worum geht es in der Quest „Der Herrscher des Schwarzfels“?",a="Diese Quest beginnt, wenn Abenteurer den Kopf von Nefarian im Pechschwingenhort erbeuten. Sie weist den Sieger an, die monumentale Trophäe zurück in die Stadt Sturmwind zu bringen und sie Hochlord Bolvar Fordragon im Namen des Königreichs zu überreichen.",al={"quest der herrscher des schwarzfels","quest kopf von nefarian allianz","kopf von nefarian sturmwind"}},{q="Wer ist Nefarian?",a="Nefarian ist ein großer schwarzer Drache und der Sohn von Deathwing. Von den Höhen des Pechschwingenhorts innerhalb der Schwarzfels aus herrschend, befehligte er die Schwarzfelsorcs und führte finstere Experimente durch, um den chromatischen Drachenschwarm zu erschaffen.",al={"wer ist nefarian","der herrscher des schwarzfels","nefarian hintergrundgeschichte"}},{q="Wer ist Hochlord Bolvar Fordragon?",a="Hochlord Bolvar Fordragon ist der Paladin, der Sturmwind als Regent in der Abwesenheit von König Varian Wrynn regiert, im Thronsaal von Burg Sturmwind Hof hält und über den jungen Prinz Anduin Wrynn wacht.",al={"bolvar fordragon","wer ist bolvar","hochlord bolvar"}},{q="Warum wird diese Trophäe nach Burg Sturmwind gebracht?",a="Nefarians Herrschaft im Schwarzfels stellte eine tödliche Bedrohung für das Königreich Sturmwind und den gesamten südlichen Kontinent dar. Die Trophäe direkt zur militärischen Führung des Königreichs zu bringen, bestätigt die Vernichtung des Drachen und ermöglicht es dem Reich, sich hinter der heldenhaften Tat zu vereinen.",al={"warum sturmwind","warum den kopf zum keep bringen","warum bolvar"}},{q="Was passiert nach der Übergabe des Kopfes an Bolvar?",a="Hochlord Bolvar Fordragon ist erstaunt über diese Leistung und erklärt, dass dieser Triumph dauerhaft in der Geschichte festgehalten wird. Dies führt direkt zur nachfolgenden Phase des Ereignisses, in der der Kopf öffentlich für ganz Sturmwind sichtbar montiert wird.",al={"was passiert als nächstes","der herrscher des schwarzfels teil 2","abgabe kopf von nefarian"}},{q="Wirkt sich die Abgabe dieses Kopfes auf die ganze Stadt aus?",a="Ja. Wenn der Kopf von Nefarian in die Hauptstadt gebracht und über den Stadttoren gehisst wird, signalisiert dies allen anwesenden Bürgern und Soldaten den Untergang des Drachen und erfüllt die Verteidiger von Sturmwind mit triumphaler Entschlossenheit.",al={"stadtstärkungszauber","rallying cry","stärkungszauber kopf von nefarian"}}},fx={["150c64a2"]={q="Warum ist es wichtig, den Kopf von Nefarian nach Sturmwind zu bringen?",a="Nefarian war der schwarze Drache, der die Bedrohungen aus der Schwarzfelsspitze orchestrierte, sterbliche Königreiche manipulierte und direkt vor Sturmwinds Haustür monströse Armeen erschuf. Die Ablieferung seines abgetrennten Kopfes an Hochlord Bolvar Fordragon ist der unwiderlegbare Beweis dafür, dass der Schrecken der Brut gebrochen ist, was der Allianz einen monumentalen Sieg beschert, der gefeiert und dem gesamten Reich präsentiert werden kann.",al={"warum kopf von nefarian nach sturmwind bringen","motiv kopf von nefarian","warum nefarian-kopf abliefern"}},["7e2ee731"]={q="Warum müsst Ihr den Kopf nach Sturmwind bringen und nicht die königlichen Wachen?",a="Ihr und Eure Gefährten habt Euch durch den Pechschwingenhort gekämpft und den Drachenfürsten höchstpersönlich erschlagen. Diese grausige Trophäe in die Burg Sturmwind zu tragen, ist Euer Recht als die Champions, die ihn besiegt haben. So stellt Ihr sicher, dass Hochlord Bolvar Fordragon die Nachricht aus erster Hand von den Helden erhält, die das Biest tatsächlich zur Strecke gebracht haben.",al={"warum muss ich nefarians kopf abliefern","warum nicht königliche wachen nefarian-kopf","warum ich nefarian-trophäe"}}},fp="21,273,21.325.0,26.302.0,42.167.0,16.211.0,33.197.0,45.238.0,45.176.0,48.190.0"}
P.entries["quest:7782"] = {n="Der Herrscher des Schwarzfels",s="Diese Quest stellt den abschließenden Höhepunkt der Kampagne gegen die Streitkräfte im Schwarzfels dar. Nach der Berichterstattung bei Grand Admiral Jes-Tereth in Burg Sturmwind werden Helden ins Tal der Helden gewiesen, wo Feldmarschall Steinsteg ein öffentliches Gedenken an den Stadttoren koordiniert, damit die gesamte Allianz es sehen kann.",h="Diese Quest stellt den abschließenden Höhepunkt der Kampagne gegen die Streitkräfte im Schwarzfels dar.",kw={"schwarzfels","drachentöter","nefarian","rallying cry","steinsteg","sturmwind","das tal der helden"},ang={["class:Warrior"]="Die gewaltige kriegerische Inspiration, die der Rallying Cry of the Dragonslayer verleiht, beflügelt Kämpfer, die ausziehen, um das Reich zu verteidigen.",["faction:Alliance"]="Das Zurschaustellen von Nefarians Kopf im Tal der Helden eint alle Völker der Allianz und erinnert die Bürger von Eisenschmiede, Darnassus und Gnomeregan daran, dass die dunklen Mächte, die die Östlichen Königreiche heimsuchen, gebrochen werden können.",["race:Human"]="Für das Königreich Sturmwind bannt der Sieg über den Meister des Schwarzfels eine existenzielle drakonische Bedrohung, die direkt an seiner nördlichen Grenze lauerte."},sec={{t="Der Triumph einer Stadt",b="Die Kampagne gegen den Schwarzfelsklan und die Brut des Schwarzen Drachenschwarms gipfelt in einer öffentlichen Zurschaustellung des Sieges. Nach der Präsentation von Nefarians abgetrenntem Kopf in Burg Sturmwind schickt Hochlord Bolvar Fordragon die Champions quer durch die Stadt ins Tal der Helden. Dort wartet Feldmarschall Steinsteg darauf, die grausige Trophäe entgegenzunehmen und stadtweite Feierlichkeiten einzuleiten."},{t="Die Allianz sammeln",b="Wenn Feldmarschall Steinsteg den abgetrennten Kopf von Nefarian auf den großen Bögen von Sturmwinds Haupteingang hisst, spürt die gesamte Stadt die Wirkung. Die Zurschaustellung wird vom Rallying Cry of the Dragonslayer begleitet und inspiriert Stadtverteidiger, angereiste Würdenträger und einfache Bürger gleichermaßen mit dem Wissen, dass die Brut von Deathwing einen katastrophalen Schlag erlitten hat."}},faq={{q="Was geschieht, wenn Ihr diese Quest abschließt?",a="Feldmarschall Steinsteg hängt den abgetrennten Kopf von Nefarian hoch oben an den steinernen Torbogen im Tal der Helden. Dies löst den Buff Rallying Cry of the Dragonslayer in ganz Sturmwind aus und stärkt das Kampfgeschick aller befreundeten Spieler und Wachen.",al={"nefarian kopf quest abgabe","was macht steinsteg","rallying cry auslöser"}},{q="Wer ist Feldmarschall Steinsteg?",a="Feldmarschall Steinsteg ist eine ranghohe Militäroffizierin der Armee von Sturmwind, die im Tal der Helden nahe dem Eingang nach Sturmwind stationiert ist. Sie organisiert das öffentliche Gedenken an bedeutende militärische Triumphe, einschließlich des Hissens der Köpfe besiegter drakonischer Bedrohungen.",al={"steinsteg","feldmarschall steinsteg"}},{q="Warum schickt Hochlord Bolvar Fordragon Euch hierher?",a="Nachdem er im Thronsaal die Bestätigung über Nefarians Niederlage erhalten hat, befiehlt Bolvar Euch, die Nachricht zu den Stadttoren zu bringen, damit das Militär der Allianz den Sieg öffentlich zur Schau stellen kann, um die Moral in der gesamten Hauptstadt zu heben.",al={"bolvar","warum ins tal der helden"}},{q="Wirkt sich diese Abgabe auf die gesamte Stadt aus?",a="Ja. Wenn Steinsteg die Trophäe entgegennimmt, hallt eine große Proklamation durch Sturmwind und der Rallying Cry of the Dragonslayer wird auf jeden innerhalb der Stadtgrenzen gewirkt.",al={"world buff nefarian","bekommt sturmwind den buff"}},{q="Wo befindet sich das Tal der Helden?",a="Das Tal der Helden ist der prächtige Eingangsdamm nach Sturmwind, gesäumt von hoch aufragenden Statuen zu Ehren der Helden des Zweiten Krieges, die das Dunkle Portal durchschritten.",al={"tal der helden standort","wo ist steinsteg"}},{q="Wer war der „Herrscher des Schwarzfels“?",a="Der Herrscher des Schwarzfels ist der schwarze Drache Nefarian, Sohn von Deathwing und Herrscher über die oberen Spitzen des Schwarzfels.",al={"wer ist der herrscher des schwarzfels","identität von nefarian"}}},fx={["3a42f3f3"]={q="Warum schickt Bolvar Euch, anstatt selbst zu gehen?",a="Ihr und Eure Gefährten wart die Champions, die den Höhen des Pechschwingenhorts getrotzt und Nefarian besiegt haben. Als Sieger gebührt Euch die Ehre, den abgetrennten Kopf des Drachen der militärischen Führung von Sturmwind zu präsentieren und den stadtweiten Triumph auszulösen.",al={"warum schickt ihr mich","warum nicht bolvar","warum muss ich den kopf überbringen"}}},fp="21,257,16.350.1,21.302.0,42.221.1,33.240.0,49.213.1,40.161.1,38.164.0,32.124.2"}
P.entries["quest:7783"] = {n="Der Herrscher des Schwarzfels",s="Diese Quest markiert den Höhepunkt des Angriffs auf den Pechschwingenhort und beauftragt Champions damit, den abgetrennten Kopf von Nefarian nach Orgrimmar zurückzubringen. Das Überbringen der monströsen Trophäe an Kriegshäuptling Thrall sichert den Beweis, dass die Brut des Schwarzen Drachenschwarms gebrochen wurde. Es ist ein Moment monumentalen Triumphs für die Horde gegen einen ihrer tückischsten Feinde.",h="Diese Quest markiert den Höhepunkt des Angriffs auf den Pechschwingenhort und beauftragt Champions damit, den...",kw={"schwarzfels","pechschwingenhort","deathwing","drachentöter","thrall","nefarian","orgrimmar","schlachtruf"},ang={["class:Warrior"]="Den massiven, abgetrennten Schädel eines Drachenlords zum Kriegshäuptling selbst zu tragen, gehört zu den höchsten Zeichen kriegerischen Ruhms.",["faction:Horde"]="Das Niederschlagen von Nefarian stellt die Ehre der Horde wieder her und befreit die Schwarzfels-Region aus dem Griff eines Drachen, der die abtrünnige Dunkle Horde versklavte.",["race:Orc"]="Für die Orcs bedeutet die Überreichung von Nefarians Kopf an Thrall die Vergeltung gegen die Bestie, die Rend Schwarzfaust wie eine Marionette lenkte und Orc-Clans für seine Experimente versklavte."},sec={{t="Eine Trophäe des Ruins",b="Nefarian, der Drahtzieher des Pechschwingenhorts und Brutleiter der schwarzen Drachen in den Östlichen Königreichen, ist endlich gefallen. Sein kolossaler, narbenbedeckter Kopf dient als unbestreitbarer Beweis für sein Ableben. Für die Krieger der Horde ist es ein Akt unbestreitbaren Ruhms, eine derart monumentale Beute aus den brennenden Höhen des Schwarzfels' und über Das große Meer nach Durotar zu schaffen."},{t="Das Urteil des Kriegshäuptlings",b="Die Trophäe wird Kriegshäuptling Thrall direkt überreicht. Thrall kennt die Verderbnis im Schwarzfels besser als fast jeder andere, da er sein Volk aus den Internierungslagern befreite und es vom dämonischen Blutrausch der alten Horde wegführte. Zu sehen, wie der Sohn von Deathwing niedergestreckt wurde, bestätigt Jahre des Kampfes und bricht die grausame Herrschaft des dunklen Drachen über die Orcs des Schwarzfelsklans."},{t="Schatten des Vaters",b="Während Nefarians Tod die verdrehten genetischen Experimente des Schwarzen Drachenschwarms beendet, beseitigt sein Sturz nicht jede Gefahr. Beim Anblick des enthaupteten Drachen bemerkt Thrall, dass Deathwing sich gewiss bei der Nachricht von der Vernichtung seines Sohnes regt. Der Sieg ist real, aber er dient als eindringliche Mahnung an die größeren Schrecken, die unter der Oberfläche der Welt schlummern."}},faq={{q="Wer ist Nefarian?",a="Nefarian ist ein großer schwarzer Drache und der Sohn von Deathwing. Von seinem Hochsitz tief im Pechschwingenhort auf dem Schwarzfels führte er verdrehte Experimente durch, um den chromatischen Drachenschwarm zu erschaffen, und manipulierte sterbliche Völker – insbesondere die Dunkle Horde –, damit sie seinen Befehlen gehorchten.",al={"nefarian hintergrundgeschichte","wer ist nefarian","schwarzer drachenlord"}},{q="Warum wird die Trophäe an Thrall übergeben?",a="Thrall ist der Kriegshäuptling der Horde. Er führte die Orcs aus den Internierungslagern und weg vom dämonischen Blutrausch der Alten Horde, daher gehört der Beweis, dass der Drache, der die Schwarzfels-Orcs und die Dunkle Horde versklavte, gefallen ist, in seine Hände.",al={"warum thrall","wer erhält den kopf"}},{q="Was passiert in Orgrimmar, wenn der Kopf abgegeben wird?",a="Wenn der Kopf von Nefarian zurückgebracht und in Orgrimmar aufgestellt wird, findet eine stadtweite Feier statt. Der gesamten Hauptstadt wird der Rallying Cry of the Dragonslayer gewährt, was die Kampfeskraft aller nahegelegenen Mitglieder der Horde steigert.",al={"kopf-buff","orgrimmar world buff","schlachtruf buff"}},{q="Hat diese Quest ein Gegenstück bei der Allianz?",a="Ja, Helden der Allianz schließen eine passende Quest ab, die ebenfalls 'Der Herrscher des Schwarzfels' heißt, und überbringen den Kopf von Nefarian an Hochlord Bolvar Fordragon in Burg Sturmwind, um ihrer Stadt denselben Segen zu verleihen.",al={"allianz-version","allianz-gegenstück"}},{q="Warum ist Deathwing ein Anlass zur Sorge?",a="Deathwing ist Nefarians Vater und der Patriarch des Schwarzen Drachenschwarms. Seinen Sohn zu besiegen beseitigt nicht die Gefahr, die von dem Drachenvater ausgeht.",al={"der böse regt sich","wer ist der böse"}},{q="Woher stammt der Kopf?",a="Die Quest beginnt mit dem Erbeuten des Kopf von Nefarian direkt von Nefarians Leichnam, nachdem man ihn auf dem Gipfel des Pechschwingenhorts besiegt hat.",al={"wie man kopf von nefarian erhält","quest-starter-gegenstand"}}},fx={d14146dc={q="Warum muss der Kopf von Nefarian nach Orgrimmar gebracht werden?",a="Das gewaltige, von Kämpfen gezeichnete Haupt des gefallenen Drachen zu bergen, liefert den unbestreitbaren Beweis, dass der Meister der Schwarzfelsspitze besiegt wurde. Eine solch monströse Trophäe zurück nach Orgrimmar zu bringen, demonstriert die überlegene Macht der Horde, feiert einen monumentalen Sieg über den Schwarzen Drachenschwarm und ermöglicht es dem Rat des Kriegshäuptlings zu bestätigen, dass Nefarians verdrehte Experimente im Berg endlich ein Ende gefunden haben.",al={"warum den kopf von nefarian bringen","motiv für kopf von nefarian","warum kopf an etrigg geben"}}},fp="21,364,16.380.0,23.395.0,21.372.1,16.273.0,38.243.0,53.225.0,44.200.0,27.147.0,30.135.0"}
P.entries["quest:7784"] = {n="Der Herrscher des Schwarzfels",s="Diese Quest markiert die endgültige Übergabe von Nefarians abgetrenntem Kopf an die Anführer von Orgrimmar. Nachdem Thrall der Untergang des schwarzen Drachen bewiesen wurde, werden die Champions zu Hochfürst Saurfang in das Tal der Stärke geschickt, um die Trophäe vor der gesamten Horde zur Schau zu stellen.",h="Diese Quest markiert die endgültige Übergabe von Nefarians abgetrenntem Kopf an die Anführer von Orgrimmar.",kw={"pechschwingenhort","thrall","kopf von nefarian","saurfang","orgrimmar","nefarian","tal der stärke"},ang={["faction:Horde"]="Die öffentliche Zurschaustellung von Nefarians Kopf festigt Thralls neue Ordnung und beweist die Macht der erneuerten Horde gegenüber dem schwarzen Drachen, der die Orcs des Schwarzfels manipulierte.",["race:Orc"]="Für die Orcs bietet das Miterleben des Falls jenes Drachen, der den Schwarzfelsklan unterjocht hielt, eine tiefe Katharsis, die einen unehrenhaften Schatten von ihrem Volk nimmt."},sec={{t="Eine Trophäe für die Horde",b="Nachdem der schwarze Drache Nefarian auf dem Pechschwingenhort erschlagen wurde, wird sein Kopf als Beweis für seine Niederlage nach Orgrimmar gebracht. Kriegshäuptling Thrall bestätigt den Fall des Sohnes von Deathwing, bevor er den Sieger zu Hochfürst Saurfang in das Tal der Stärke schickt. Dort werden die grausamen Überreste dafür vorbereitet, öffentlich zur Schau gestellt zu werden, was Feinden als Warnung und der wahren Horde als Sammelruf dient."},{t="Das Erbe einfordern",b="Nefarian beherrschte die Höhen des Schwarzfels und unterwarf die Schwarzfelsorcs sowie die Dunkle Horde seinem Willen. Indem sie ihn niederstreckt und seinen Kopf im Tal der Stärke hoch hisst, versetzt Kriegshäuptling Thralls Horde dem Schwarzen Drachenschwarm einen schweren Schlag, und Saurfang ruft ganz Orgrimmar dazu auf, im Rallying Cry of the Dragonslayer zu schwelgen."}},faq={{q="Was ist der Zweck dieser Quest?",a="Sie dient als abschließende Abgabe für das Erschlagen von Nefarian. Nachdem Ihr Thrall den Beweis erbracht habt, meldet Ihr Euch bei Hochfürst Saurfang im Tal der Stärke von Orgrimmar, um Ehrungen zu empfangen und den abgetrennten Kopf öffentlich zur Schau stellen zu lassen.",al={"was bewirkt diese quest","lord of blackrock abgabe","warum zu saurfang gehen"}},{q="Wer ist Hochfürst Saurfang?",a="Hochfürst Saurfang ist ein erfahrener Orc-Krieger und einer der größten Champions der Horde, der im Tal der Stärke in Orgrimmar stationiert ist, wo er den Kopf entgegennimmt und ihn für alle sichtbar anbringen lässt.",al={"wer ist saurfang","rolle von hochfürst saurfang"}},{q="Warum wird Nefarians Kopf zur Schau gestellt?",a="Das Anbringen des Kopfes des schwarzen Drachen beweist zweifelsfrei, dass der Herrscher des Schwarzfels gefallen ist. Es stärkt die Moral der Verteidiger von Orgrimmar, und der Rallying Cry of the Dragonslayer wird auf jeden in der Stadt gewirkt.",al={"warum nefarians kopf anbringen","nefarian kopf ausstellung orgrimmar"}},{q="Wer war Nefarian?",a="Nefarian war ein großer schwarzer Drache und ein Sohn von Deathwing. Vom Pechschwingenhort auf dem Schwarzfels aus befehligte er die Schwarzfelsorcs sowie die Dunkle Horde und züchtete den chromatic dragonflight heran.",al={"wer war nefarian","nefarian lore"}},{q="Wo befindet sich Hochfürst Saurfang?",a="Saurfang hält im Tal der Stärke Wache, dem zentralen Eingangsviertel von Orgrimmar.",al={"wo ist saurfang","saurfang aufenthaltsort"}},{q="Welche Rolle spielt Thrall dabei?",a="Kriegshäuptling Thrall nimmt den Kopf zuerst entgegen. Sobald er Nefarians Tod bestätigt hat, schickt er Euch zu Saurfang, damit die Trophäe offiziell angebracht wird.",al={"warum thrall","thralls beteiligung"}}},fp="21,264,22.393.0,19.348.1,34.226.0,30.206.0,38.233.0,17.190.0,40.95.0,35.139.0"}
P.entries["quest:78"] = {n="Die Legende von Stalvan",s="Dieser Botengang markiert einen Wendepunkt bei der Aufdeckung der Geschichte von Stalvan Dunstmantel und führt Ermittler aus dem Wald von Elwynn zurück in die schattenhafte Stadt Dunkelhain. Geleitet von Marshal Haggards Erinnerungen an seine Dienstzeit bringt Ihr eine geborgene Tagebuchseite zu Schankwart Smitts in die Scarlet Raven Tavern, um die unheimliche Handschrift zu identifizieren.",h="Dieser Botengang markiert einen Wendepunkt bei der Aufdeckung der Geschichte von Stalvan Dunstmantel und...",kw={"dunkelhain","dämmerwald","elwynn","tagebuch","marshal haggard","dunstmantel","scarlet raven tavern","stalvan","schankwart smitts"},ang={["faction:Alliance"]="Die Quest unterstreicht die tiefen Bande zwischen ehemaligen Verteidigern des Reiches und verbindet pensionierte Gardisten von Sturmwind mit Hütern der Gemeinschaft im gesamten Kingdom of Stormwind.",["race:Human"]="Dieser Schritt enthüllt die finsteren Erinnerungen, die in menschlichen Siedlungen lauern, und zeigt, wie vergangene Tragödien in Elwynn und Dunkelhain nicht begraben bleiben wollen."},sec={{t="Eine Spur des Marshals",b="Nachdem eine verwitterte, zerrissene Tagebuchseite aus Marshal Haggards Truhe im Wald von Elwynn geborgen wurde, kann der pensionierte Kommandant die verblasste Schrift aufgrund seines nachlassenden Augenlichts nicht lesen. In der Erkenntnis, dass die Spur zurück über den Fluss führt, erinnert sich Haggard an seine Vergangenheit als Befehlshaber der Stormwind Guard und daran, wie er Abende in der Scarlet Raven Tavern in Dunkelhain verbrachte. Er weist Euch an Schankwart Smitts, einen Schankwirt, dessen lange Dienstzeit ihn zu einem inoffiziellen Hüter der lokalen Geschichte und Gerüchte gemacht hat."},{t="Rückkehr zur Scarlet Raven",b="Bei Eurer Rückkehr durch die düsteren Wälder des Dämmerwalds legt Ihr Smitts hinter seinem Tresen das verblasste Manuskript vor. Smitts wird sofort milder, als er den Namen seines alten Bekannten Haggard hört, wenngleich er den schwindenden Gesundheitszustand des Veteranen beklagt. Als sein Blick auf das Pergament fällt, weicht das gelassene Auftreten des Schankwirts augenblicklich hellem Entsetzen: Er erkennt die unverwechselbare Schrift ohne jeden Zweifel wieder, was die Ermittlung der grauenhaften Wahrheit über Stalvans Wahnsinn näher bringt."}},faq={{q="Warum schickt mich Marshal Haggard nach Dunkelhain zurück?",a="Marshal Haggard altert und ist nahezu blind, was ihn daran hindert, die geborgene Tagebuchseite selbst zu untersuchen. Er erinnert sich daran, dass Schankwart Smitts von der Scarlet Raven Tavern ein Experte für die lokalen Überlieferungen und die Geschichte war, als Haggard bei der Stormwind Guard diente, was Smitts zur idealen Person macht, um die Schrift zu identifizieren.",al={"warum nach dunkelhain","haggard nach dunkelhain","warum smitts"}},{q="Wo befindet sich Schankwart Smitts?",a="Schankwart Smitts betreibt die Bar in der Scarlet Raven Tavern, die sich auf der Ostseite von Dunkelhain im Dämmerwald befindet.",al={"wo ist smitts","smitts standort","scarlet raven tavern standort"}},{q="Welchen Gegenstand bringt Ihr zu Schankwart Smitts?",a="Ihr bringt eine verblasste Tagebuchseite, einen Auszug aus Stalvan Dunstmantels verlorenem Tagebuch, der zuvor gesichert in Marshal Haggards Truhe gefunden wurde.",al={"welcher gegenstand","verblasste tagebuchseite","stalvan tagebuchseite"}},{q="Erkennt Schankwart Smitts die Handschrift?",a="Ja. In dem Moment, in dem Smitts die verblasste Seite betrachtet, erkennt er die Handschrift mit deutlicher Beunruhigung wieder, und dieses Wiedererkennen liefert der Suche nach Stalvan ihren nächsten Hinweis.",al={"kennt smitts die schrift","smitts reaktion auf tagebuch"}},{q="Woher kennt Smitts Marshal Haggard?",a="Smitts bewirtete Haggard vor Jahren, als Haggard Patrouillen der Stormwind Guard in den Dämmerwald anführte und für Getränke häufig in der Scarlet Raven Tavern einkehrte.",al={"smitts haggard beziehung","woher smitts haggard kennt"}},{q="Was folgt als Nächstes bei der Suche nach Stalvan?",a="Bringt die verblasste Tagebuchseite zu Smitts in die Scarlet Raven Tavern und folgt der Spur, die er liefert.",al={"was kommt als nächstes","nächster schritt stalvan","stalvan reihe fortsetzen"}}},fx={bf062962={q="Warum möchte Marshal Haggard, dass dies erledigt wird?",a="Marshal Haggard kann die verblasste Tagebuchseite nicht lesen, weil sein Augenlicht nachlässt. Er erinnert sich an Schankwart Smitts als einen alten Bekannten mit fundiertem Wissen über die lokale Geschichte und bittet Euch, ihm die Seite in Dunkelhain zu überbringen.",al={"warum möchte haggard dies erledigt haben","motiv von marshal haggard","warum helfen stalvan zu finden"}},c297959a={q="Warum schickt Marshal Haggard Euch, anstatt selbst zu gehen?",a="Haggard ist ein alter, pensionierter Marshal, der in Isolation lebt und rapide sein Augenlicht verliert. Die Wege durch den Wald sind gefährlich, und ihm fehlen einfach die Jugend und die körperliche Ausdauer, um zurück über die Grenze in den Dämmerwald zu wandern. Er verlässt sich auf einen fähigen Reisenden wie Euch, um seine Besorgung zu erledigen und die Tagebuchseite seinem alten Bekannten zu zeigen.",al={"warum kann haggard nicht gehen","warum braucht haggard mich","warum besucht haggard smitts nicht"}}},fp="21,343,23.491.0,27.485.1,51.311.0,35.119.0,44.152.0,49.164.0,37.145.0,42.99.0"}
P.entries["quest:780"] = {n="Die Kampfeber",s="Die Kampfeber ist eine Jagdquest im Rahmen eines Übergangsritus, die von Grull Falkenwind in Camp Narache vergeben wird. Junge Tauren sind damit beauftragt, die bösartigen, für den Krieg ausgebildeten Eber der Dornrankenklamm zu dezimieren, um das Stammesland zu verteidigen und die Jugend der Siedlung zu ernähren.",h="Die Kampfeber ist eine Jagdquest im Rahmen eines Übergangsritus, die von Grull Falkenwind in Camp Narache...",kw={"kampfeber","dornrankenklamm","bristleback","camp narache","grull falkenwind","mulgore","quilboar","die hochwolkenebene"},ang={["class:Hunter"]="Die Konfrontation mit Bestien, die von den Bristlebacks auf Bosheit abgerichtet wurden, lehrt junge Jäger den scharfen Kontrast zwischen der natürlichen Tierwelt und Tieren, die zu Kriegswaffen verzerrt wurden.",["profession:Cooking"]="Die Bitte nach Flanken und Schnauzen unterstreicht das grundlegende kulinarische Ethos der Tauren: Grobes, zähes Fleisch kann immer zu herzhaften, nahrhaften Eintöpfen ausgekocht werden.",["race:Tauren"]="Diese Aufgabe verkörpert das Gleichgewicht der Tauren, die Gebiete der Earth Mother zu verteidigen und gleichzeitig sicherzustellen, dass nichts im Kampf Errungenes verschwendet wird, indem die Kriegstiere der Feinde in Nahrung für die Kälber des Lagers verwandelt werden."},sec={{t="Eine Bedrohung an der Grenze",b="Östlich der Hochwolkenebene liegt die Dornrankenklamm, eine von Dornen überwucherte Narbe, die von den Bristleback-Quilboar gehalten wird. Da die Spannungen zwischen den Shu'halo und den Quilboar zu einem offenen Krieg eskalieren, haben die Bristlebacks bösartige Kampfeber abgerichtet, um die Grenzen der Tauren zu sondieren und ihre traditionellen Jagdgründe zu terrorisieren. Wenn sie nicht aufgehalten werden, bedrohen diese aggressiven Bestien nicht nur die Wildpfade, sondern die Sicherheit von Camp Narache selbst."},{t="Den Stamm ernähren",b="Für die Tauren dient die Jagd sowohl der defensiven Notwendigkeit als auch dem gemeinschaftlichen Lebensunterhalt. Grull Falkenwind weist die Initianden an, die Schnauzen und Flanken der getöteten Kampfeber zurückzubringen. Selbst Bestien, die von Quilboarhänden abgerichtet wurden, werden nicht verschwendet; ihr Fleisch und Knorpel werden verwertet, um einen deftigen Eintopf für die Jugend des Stammes zuzubereiten, wodurch eine Waffe der Quilboar in Nahrung für die nächste Generation von Tauren-Verteidigern verwandelt wird."}},faq={{q="Warum greifen die Kampfeber die Hochebene an?",a="Die Kampfeber wurden von den Bristleback-Quilboar, die die Dornrankenklamm bewohnen, gezielt gezüchtet und abgerichtet. Die Quilboar nutzen sie als Stoßtiere, um die Tauren zu bedrängen und in die Stammesjagdgründe der Hochwolkenebene einzudringen.",al={"kampfeber aggression","warum kampfeber feindselig sind","angreifende kampfeber"}},{q="Wer schickt Spieler auf diese Jagd?",a="Grull Falkenwind, ein prominenter Jäger und Ältester, der in Camp Narache stationiert ist, leitet junge Tauren durch die abschließenden Prüfungen ihrer frühen Ausbildung.",al={"questgeber die kampfeber","wer gibt die quest die kampfeber","rolle von grull falkenwind"}},{q="Wo sind die Kampfeber zu finden?",a="Sie streifen in der Nähe und innerhalb der Dornrankenklamm umher, einer zerklüfteten Schlucht direkt östlich von Camp Narache am östlichen Rand der Hochwolkenebene.",al={"kampfeber fundort","wo sind kampfeber","eber der dornrankenklamm"}},{q="Was geschieht mit dem von den Ebern gesammelten Fleisch?",a="Die Kampfeberflanken und -schnauzen werden nach Camp Narache zurückgebracht, um zu einem Eintopf für die Kinder und Ältesten der Siedlung eingekocht zu werden, ganz im Sinne der Taurentradition, das Erlegte vollständig zu verwerten.",al={"verwendung von kampfeberflanken","wofür ist eberfleisch","ebereintopf"}},{q="Wie fügt sich diese Quest in den lokalen Quilboar-Konflikt ein?",a="Sie dient als frühe Einführung in den offenen Krieg zwischen den Tauren und dem Stamm der Bristleback. Das Dezimieren ihrer Kriegstiere lichtet die Bestien, die die Jagdgründe der Tauren heimsuchen, und sendet eine klare Botschaft an die Bristlebacks der Dornrankenklamm.",al={"krieg zwischen tauren und quilboar","bristleback-konflikt","quilboar-lore"}},{q="Welche Quest geht Die Kampfeber voraus?",a="Ihr geht The Hunt Continues voraus, eine frühere Aufgabe von Grull Falkenwind, die sich auf das Kennenlernen der Jagdgründe der Hochwolkenebene konzentriert.",al={"die kampfeber voraussetzung","vorherige quest die kampfeber","the hunt continues questreihe"}}},fx={b70ec92c={q="Warum will Grull Falkenwind, dass die The Battleboars getötet werden?",a="Die The Battleboars sind aus der Dornrankenklamm vorgedrungen und direkt in die angestammten Jagdgründe des Stammes der Hochwolkenebene eingedrungen. Von den Bristleback-Quilboar darauf gezüchtet und trainiert, bösartig zu sein, bedroht ihre wachsende Aggression direkt Camp Narache. Grull Falkenwind beabsichtigt, den Bristlebacks eine deutliche Nachricht zu senden, indem er ihre Kriegstiere dezimiert und die Jagdbeute gleichzeitig als Nahrung für die Stammesjugend verwendet.",al={"warum sollen the battleboars sterben","grull falkenwind the battleboars motiv","warum the battleboars mulgore töten"}},["58a19c3f"]={q="Was sind The Battleboars?",a="The Battleboars sind wilde Bestien, die von den Bristleback-Quilboar aus der Dornrankenklamm aufgezogen und trainiert werden. Im Gegensatz zu den wilden Bergpumas und Ebenenschreitern, die in der Hochwolkenebene heimisch sind, wurden diese Eber gezielt auf Krieg und Bosheit abgerichtet und dienen als lebende Waffen im fortwährenden Kampf der Bristlebacks gegen die Tauren.",al={"wer sind die the battleboars","was sind the battleboars","the battleboars hintergrundwissen"}}},fp="15,237,22.418.0,17.402.0,43.234.0,31.147.0,32.137.0,50.191.0,57.242.0,36.132.0"}
P.entries["quest:7807"] = {n="Spendet Wolle",s="A Donation of Wool ist eine von den Gnomeregangnomen organisierte Materialbeschaffung, um lebensnotwendige Textilvorräte zu sammeln. Die vertriebenen Gnome, die aus ihrer technologischen Heimatstadt entwurzelt wurden, sind auf sechzig Stück Wollstoff von großzügigen Abenteurern aus dem gesamten Reich angewiesen, um ihre Gemeinschaft zu versorgen. Ein Beitrag zu dieser Hilfsaktion bringt formelle Anerkennung unter den Gnomenflüchtlingen ein.",h="A Donation of Wool ist eine von den Gnomeregangnomen organisierte Materialbeschaffung, um lebensnotwendige...",kw={"stoffsammlung","eine spende von wolle","gnom","gnomeregan","gnomeregangnome","textilien","wollstoff"},ang={["faction:Alliance"]="Die Bereitstellung von Rohstoffen für die verbannten Gnome stärkt die Solidarität innerhalb der Allianz und hilft, einen wichtigen Verbündeten zu unterstützen, der aus seiner Heimat in den Bergen vertrieben wurde.",["profession:Tailoring"]="Schneider, die Wollstoff sammeln oder weben, verfügen über einen reichlichen Vorrat an Textilien, den Flüchtlingspopulationen für grundlegende Kleidungsstücke und Vorräte dringend benötigen.",["race:Gnome"]="Für vertriebene Gnome trägt das Sammeln von Wolle dazu bei, Eure entwurzelten Verwandten neu zu versorgen, während sie darum ringen, außerhalb von Gnomeregan zu überleben und den Wiederaufbau voranzutreiben."},sec={{t="Die Bedürfnisse eines vertriebenen Volkes",b="Nach dem Fall von Gnomeregan an eindringende Troggs und radioaktiver Verseuchung sahen sich die überlebenden Gnome aus ihrer hochtechnisierten Metropole vertrieben. Als Flüchtlinge, die vor allem von ihren zwergischen Vettern in Eisenschmiede aufgenommen wurden, stehen die Gnomeregangnome vor gewaltigen logistischen Herausforderungen. Regelmäßige Materialbeschaffungen für grundlegende Güter wie Stoff sind unverzichtbar, um ihr Volk zu kleiden, zu versorgen und zu organisieren, während sie fernab ihrer angestammten Hallen überleben."},{t="Die Textilbeschaffung",b="Um einzelne Wohltäter nicht zu überfordern, fordern die Organisatoren der Sammlung exakt sechzig Stück Wollstoff pro Freiwilligem an. Durch die Bündelung bescheidener Beiträge aus dem gesamten Reich können die Vertriebenen die für Bettzeug, Verbände und Kleidung benötigten Textilmengen zusammentragen, ohne einem einzelnen Lieferanten eine untragbare Last aufzuerlegen. Im Gegenzug bieten die Gnome jedem, der bereit ist, ihre Wiederaufbaubemühungen zu unterstützen, formelle Anerkennung unter ihrem Volk an."}},faq={{q="Warum benötigen die Gnomeregangnome Wollstoff?",a="Die Gnomeregangnome führen eine Ressourcensammlung durch, um grundlegende Textillager aufzubauen. Nachdem sie aus ihrer Heimatstadt vertrieben wurden, benötigt ihr Volk grundlegende Materialien wie Wollstoff, um ihre Flüchtlingsbevölkerung und laufende Vorhaben aufrechtzuerhalten.",al={"warum wolle","wofür ist die wolle","zweck der wollspende"}},{q="Wie viel Wollstoff wird benötigt?",a="Die Spendensammlung sieht einen einmaligen Beitrag von sechzig Stück Wollstoff pro Spender vor. Die Organisatoren kalkulieren, dass der Erhalt dieser festgelegten Menge von Einzelpersonen aus dem gesamten Reich ihren gesamten Versorgungsbedarf angemessen decken wird.",al={"wie viel wolle","spendenmenge","benötigte wolle"}},{q="Wer organisiert diese Spendensammlung?",a="Vertreter der Gnomeregangnome koordinieren die Textilsammlung und nehmen Spenden im Namen der vertriebenen Gnombevölkerung entgegen, die derzeit bei ihren Verbündeten Schutz sucht.",al={"wer nimmt spende an","wer nimmt wolle an","spendenempfänger"}},{q="Kann man Wollstoff mehr als einmal spenden?",a="Die Anforderung ist auf einen einmaligen Beitrag von sechzig Stück von jedem Spender begrenzt. Die Vertriebenen merken an, dass ihre gegenwärtigen Vorräte nur diese feste Menge von Euch benötigen, da sie auf einen breiteren Kreis von Spendern aus dem gesamten Reich zählen, um ihr Kontingent zu erfüllen.",al={"kann ich erneut spenden","ist es wiederholbar","weitere wollspenden"}},{q="Welche Anerkennung bieten die Gnomeregangnome an?",a="Die Bereitstellung von sechzig Stück Wolle bringt die volle Anerkennung und Dankbarkeit der Gnomeregangnome ein und beweist Eure Loyalität sowie Unterstützung für ihr vertriebenes Volk in Zeiten der Krise.",al={"gnomeregangnome ansehen","gnomenruf","anerkennung der vertriebenen"}},{q="Warum befinden sich die Gnome derzeit im Exil?",a="Die Gnome waren gezwungen, nach einer verheerenden Katastrophe und einer Trogg-Invasion aus ihrer unterirdischen Heimat Gnomeregan zu fliehen, wodurch sie als Flüchtlinge auf provisorische Lager, Unterstützung durch Verbündete und Materialbeschaffungen angewiesen sind.",al={"warum gnome im exil sind","wo ist gnomeregan","gnomen-flüchtlingskrise"}}},fp="18,365,26.459.0,17.448.0,45.241.0,30.243.0,38.178.0,41.252.0,48.188.0,38.229.0"}
P.entries["quest:781"] = {n="Angriff auf Camp Narache",s="Angriff auf Camp Narache ist eine entscheidende Entdeckung, die in der Stacheleberhöhle der Dornrankenklamm gemacht wird. Eine schmutzbefleckte Karte enthüllt, dass der aggressive Stamm der Borstennacken aktiv eine organisierte Belagerung von Camp Narache plant. Die Übergabe dieser Pläne an Häuptling Falkenwind warnt Camp Narache rechtzeitig vor, um Hilfe aus dem Dorf der Bluthufe herbeizurufen.",h="Angriff auf Camp Narache ist eine entscheidende Entdeckung, die in der Stacheleberhöhle der Dornrankenklamm...",kw={"angriffspläne","dorf der bluthufe","dornrankenklamm","borstennacken","camp narache","häuptling falkenwind","schmutzbefleckte karte","stacheleber","die hochwolkenebene"},ang={["faction:Horde"]="Den Stützpunkt der Tauren in Mulgore zu bewahren stellt sicher, dass die Horde ihren lebenswichtigen südlichen Anker im zentralen Kalimdor behält.",["race:Tauren"]="Für junge Tauren-Krieger, die ihre frühesten Riten auf der Mesa bestreiten, beweist das Abfangen dieser Karte Eure Loyalität gegenüber Eurem Stamm und schützt Eure Sippe vor einem plötzlichen Massaker."},sec={{t="Ein Komplott im Gestrüpp",b="Beim Kundschaften tief in den Höhlen der Dornrankenklamm entdecken junge Tauren-Abenteurer eine einfache, schmutzbefleckte Karte, die auf dem felsigen Boden liegt. Bei näherer Betrachtung offenbart das Pergament gezielte taktische Markierungen der Borstennackenstacheleber. Anstatt bloße opportunistische Scharmützel zu führen, koordinieren die Stacheleber eine groß angelegte, langwierige Belagerung von Camp Narache."},{t="Warnung an den Häuptling",b="Die Angriffspläne zurück nach Camp Narache zu bringen, liefert Häuptling Falkenwind entscheidende Informationen. Da er die ernste Bedrohung für das relativ unverteidigte Lager und seine jungen Initianden erkennt, bereitet Hawkwind vor, eine Nachricht ins Dorf der Bluthufe zu senden, um Verstärkung anzufordern. Die abgefangene Karte verwandelt einen potenziell verheerenden Hinterhalt in eine vorbereitete Verteidigung."}},faq={{q="Wo sind die Angriffspläne der Borstennacken zu finden?",a="Die Pläne stammen von einer schmutzbefleckten Karte im Inneren einer Höhle in der Dornrankenklamm, gleich einen Pfad rechts von Häuptling Sharptusks Hütte hinauf.",al={"kartenfundort","wo ist schmutzbefleckte karte","die pläne finden"}},{q="Wer erhält die Angriffspläne der Borstennacken?",a="Die Pläne müssen direkt bei Häuptling Falkenwind im Zentrum von Camp Narache abgegeben werden.",al={"bei wem abgeben","wer bekommt die karte","questbeender"}},{q="Warum haben es die Borstennackenstacheleber auf Camp Narache abgesehen?",a="Der Stamm der Borstennacken versucht, die Tauren von der Hochwolkenebene zu vertreiben und die Jagdgründe sowie die heiligen Ebenen von Mulgore für die eigene Art zurückzufordern.",al={"warum camp narache angreifen","motive der stacheleber mulgore","belagerung der borstennacken"}},{q="Wie plant Häuptling Falkenwind, der Belagerung zu begegnen?",a="Dank der frühzeitigen Warnung durch die abgefangene Karte beabsichtigt Häuptling Falkenwind, die Brüder im Dorf der Bluthufe zu rufen, um die Mesa zu verstärken und den Angriff abzuwehren.",al={"hawkwinds plan","verstärkung camp narache"}},{q="Erfordert diese Quest, vor dem Aufheben der Karte mit jemandem zu sprechen?",a="Nein. Die Quest beginnt direkt bei der Schmutzbefleckten Karte, die auf dem Höhlenboden in der Dornrankenklamm liegt, und verwandelt sich nach dem Aufheben in die Schlachtpläne.",al={"queststarter","schmutzbefleckte karte starter","angriff auf camp narache starten"}},{q="Was passiert, wenn Camp Narache fällt?",a="Camp Narache ist der wichtigste Zufluchtsort für junge Tauren-Krieger und Übergangsriten; sein Verlust würde die Sicherheit der Hochwolkenebene gefährden und Mulgores spirituelle Ausbildungsstätten abschneiden.",al={"bedeutung von camp narache","warum narache verteidigen"}}},fp="22,330,22.393.0,21.361.0,45.143.0,42.85.0,56.152.0,50.168.0,69.149.0,35.185.0"}
P.entries["quest:7810"] = {n="Meister der Arena",s="Gehört mehr dazu, die Arena zu meistern, als dies? Short John Mithril, der Pirat hinter dem Gurubashi-Event, hat vielleicht die Antwort, und Ihr findet ihn in der Stranglethorn Arena.",h="Gehört mehr dazu, die Arena zu meistern, als dies?",kw={"arena master","gurubashi","pirat","short john mithril","arena der gurubashi","schlingendorntal"},sec={{t="Auf der Suche nach dem Piraten",b="Was auch immer Ihr bei Gurubashi erlangt habt, scheint das Meistern der Arena nach mehr zu verlangen. Short John Mithril, der Pirat, der dort die Wettkämpfe organisiert, weiß vielleicht Genaueres. Sucht nach ihm in der Stranglethorn Arena."},{t="Short Johns Wort",b="Short John Mithril sagt Euch, dass ein einzelnes Schmuckstück zu wenig ist, um Euch zum Meister der Arena zu machen. Nun, sagt er, kommt die wahre Prüfung Eures Stahls."}},faq={{q="Mit wem muss ich sprechen?",a="Short John Mithril, der Pirat hinter dem Gurubashi-Event.",al={"mit wem muss ich sprechen","arena master abgabe","wohin gehen"}},{q="Wo ist Short John Mithril?",a="In der Stranglethorn Arena, bei Gurubashi im Schlingendorntal.",al={"gurubashi standort","wo ist die arena der gurubashi","arena standort"}},{q="Was wird darüber angedeutet, Meister der Arena zu sein?",a="Nur, dass das Meistern der Arena anscheinend mehr erfordert, als Ihr bisher getan habt, und dass der Pirat hinter dem Gurubashi-Event es wissen könnte.",al={"wie man arena master wird","bin ich schon arena master"}}},fp="12,177,18.212.0,17.149.1,28.58.0,28.63.0,47.135.0"}
P.entries["quest:78124"] = {n="Nar'thalas Almanac",s="Der Nar'thalas Almanac ist ein seltenes wissenschaftliches Manuskript über antike magische Studien, das von Archivaren gesucht wird, um die Sammlung ihrer Library zu erweitern. Die Bergung des Bandes bringt verlorenes arkanes Wissen in sichere Hände, wo Forscher seine vergessenen Erkenntnisse studieren können.",h="Der Nar'thalas Almanac ist ein seltenes wissenschaftliches Manuskript über antike magische Studien, das von...",kw={"almanac","arkan","buch","library","magische werke","nar'thalas","narthalas","foliant"},ang={["class:Mage"]="Magier verstehen den immensen wissenschaftlichen Wert geborgener Texte über antike arkane Traditionen, was Beiträge zur magischen Sammlung der Library besonders bedeutsam macht.",["faction:Alliance"]="Gelehrte und Kuratoren, die in den Archiven der Allianz arbeiten, verlassen sich auf unternehmungslustige Abenteurer, um seltene Manuskripte aufzuspüren und das gesammelte Wissen des Reiches zu erweitern.",["race:NightElf"]="Nar'thalas war einst ein antikes Zentrum kaldoreischer arkaner Gelehrsamkeit, bevor die Zerschlagung die alte Welt zerriss, was einen Almanach mit diesem Namen zu einem ergreifenden Bindeglied zur antiken Nachtelfengeschichte macht."},sec={{t="Ein Relikt antiker Studien",b="Der Nar'thalas Almanac ist ein seltener Foliant über arkane Studien, der aus den alten Traditionen der Nachtelfengelehrsamkeit vor der Zerschlagung stammt. Für die Hüter bedeutender Archive rettet die Sicherung eines solchen Textes jahrhundertealtes Wissen vor der Vergessenheit und fügt den Regalen ein wichtiges Stück Geschichte hinzu. Abenteurer, die diese lange vernachlässigten Werke entdecken, helfen dabei, die Kluft zwischen vergessener Antike und modernem wissenschaftlichen Verständnis zu überbrücken."},{t="Erweiterung der Archive",b="Archivare und Forscher suchen unablässig nach verlorenen Abhandlungen, Feldnotizen und Chroniken, die über ganz Azeroth verstreut sind. Wird der Nar'thalas Almanac in eine eigene Library gebracht, stellt dies sicher, dass er geschützt, katalogisiert und studiert wird, anstatt in Ruinen zu verrotten oder in unvorsichtige Hände zu geraten. Jeder gerettete Band bietet Gelehrten neue Einblicke in die arkanen Künste vergangener Zeitalter."}},faq={{q="Was ist der Nar'thalas Almanac?",a="Der Nar'thalas Almanac ist ein antikes Manuskript magischer Gelehrsamkeit, das von Kuratoren gesucht wird, um die historischen Archive einer Library zu bereichern. Abenteurer, die solche seltenen Werke bergen, übergeben sie in wissenschaftliche Obhut, damit ihre erhaltenen Erkenntnisse katalogisiert werden können.",al={"was ist der narthalas almanac","quest narthalas almanac","almanac informationen"}},{q="Wer sammelt den Nar'thalas Almanac?",a="Der Almanach wird den Gelehrten der Library überreicht, die an antiken magischen Texten und historischen Archiven interessiert sind. Diese Kuratoren suchen aktiv nach Ergänzungen, um ihr gemeinsames institutionelles Wissen über das arkane Erbe der Welt zu erweitern.",al={"wer will den almanac","wohin kommt der almanac","almanac abgeben"}},{q="Worauf bezieht sich der Name Nar'thalas?",a="Nar'thalas war ein antikes Zentrum der Kaldorei für Gelehrsamkeit und magische Studien aus der Zeit vor der Großen Zerschlagung. Überlebende Texte, die mit diesem Namen in Verbindung stehen, stellen Fragmente der Arkanmagie und des Wissens der Elfen vor der Zerschlagung dar.",al={"was ist narthalas","narthalas geschichte","wo ist narthalas"}},{q="Warum werden magische Texte für die Library gesammelt?",a="Viele historische Aufzeichnungen und magische Abhandlungen wurden über ganz Azeroth verstreut, gingen verloren oder liegen in Ruinen begraben. Gelehrte verlassen sich auf geborgene Schriften, um ihr Verständnis arkaner Strömungen zu erweitern und fragile Aufzeichnungen vor dem vollständigen Verlust zu schützen.",al={"warum magische werke sammeln","zweck der bibliothek","warum buecher wichtig sind"}},{q="Können andere magische Werke zur Library gebracht werden?",a="Gelehrte begrüßen alle geborgenen Abhandlungen, Folianten oder vergessenen Manuskripte, die Aufschluss über arkane Theorie und antike Geschichte geben, und suchen beständig nach Ergänzungen, um ihre Regale zu bereichern.",al={"weitere magische buecher","andere folianten","mehr texte"}},{q="Ist der Nar'thalas Almanac gefährlich in der Handhabung?",a="Der Almanach stellt eher eine zusammengetragene Studienaufzeichnung als ein unberechenbares verbotenes Artefakt dar. Er dient in erster Linie als wertvolles Nachschlagewerk für Historiker und Praktizierende, die historische Magie studieren.",al={"ist der almanac gefaehrlich","enthaelt der almanac dunkle magie","sicher zu lesen"}}},fp="18,251,24.420.0,22.377.0,31.251.0,41.223.0,39.219.0,54.238.0,50.182.0,46.201.0"}
P.entries["quest:78143"] = {n="Secrets of the Dreamers",s="Secrets of the Dreamers beauftragt Abenteurer damit, seltene magische Schriften zu bergen, um wissenschaftliche Archive zu bereichern. Durch die Abgabe dieser entdeckten Abhandlungen helfen Forscher den Gelehrten einer Library, ihre Sammlung alten Wissens zu erweitern.",h="Secrets of the Dreamers beauftragt Abenteurer damit, seltene magische Schriften zu bergen, um...",kw={"arkan","traeumer","library","magische werke","gelehrte","secrets of the dreamers","folianten"},ang={["class:Druid"]="Angesichts des Verweises auf die Träumer besitzen Schriften, die mit Naturmagie und dem Smaragdgrünen Traum verknüpft sind, eine tiefe Bedeutung für Praktizierende der cenarischen Künste.",["class:Mage"]="Gelehrte Arkanisten sind einzigartig dafür geeignet, obskure Folianten und magische Texte in ganz Azeroth aufzuspüren, um institutionelle Archive zu bereichern.",["faction:Alliance"]="Gelehrte der Allianz, insbesondere jene, die große Archive hüten, verlassen sich auf abenteuerlustige Champions, um verlorenes Wissen an gefährlichen Orten zu bergen."},sec={{t="Bergung vergessenen Wissens",b="Die Quest Secrets of the Dreamers beinhaltet das Bergen seltener magischer Texte und historischer Abhandlungen aus dem gesamten Reich. Gelehrte, die sich der Aufzeichnung von Azeroths arkanen Geheimnissen widmen, verlassen sich auf reisende Abenteurer, um vergessene Werke auszugraben und sie sicher in die Archive zu bringen. Anstatt kostbares Wissen in uralten Ruinen oder privaten Horten verkümmern zu lassen, stellen diese Sammelbemühungen sicher, dass entscheidendes Wissen erforscht und für künftige Generationen bewahrt wird."},{t="Erweiterung der Archive",b="Nach der Abgabe dieser Abhandlungen integrieren die Archivare sie in ihre ständigen Sammlungen und erweitern so das Verständnis des Archivs über magische Phänomene. In einer Library wie dieser suchen Forscher ständig nach obskuren Manuskripten, die von allem Möglichen handeln, vom Smaragdgrünen Traum bis hin zur arkane Theorie. Die Arbeit ist nie ganz abgeschlossen, und die Gelehrten bleiben begierig auf jede weitere magische Schrift, die im Feld entdeckt wird."}},faq={{q="Was ist der Zweck der Quest Secrets of the Dreamers?",a="Secrets of the Dreamers ist eine Quest, die sich auf das Bergen magischer Werke und obskuren Wissens konzentriert, um eine wissenschaftliche Sammlung zu erweitern. Abenteurer beschaffen relevante Materialien draußen in der Welt und geben sie ab, um die Archive von Forschern zu bereichern.",al={"was ist secrets of the dreamers","secrets of the dreamers quest","was tut man in dieser quest"}},{q="Wer sammelt diese magischen Texte?",a="Die Quest wird von einem Gelehrten angenommen und abgegeben, der die Sammlung einer Library beaufsichtigt und reisende Abenteurer darum bittet, magische Werke herbeizuschaffen.",al={"wer will secrets of the dreamers","wer vergibt diese quest","wo secrets of the dreamers abgeben"}},{q="Wo werden die geborgenen Werke aufbewahrt?",a="Die geborgenen Schriften werden direkt den wachsenden Archiven einer institutionellen Bibliothek hinzugefügt, wodurch sichergestellt wird, dass seltenes Wissen und magische Entdeckungen für Gelehrte und Forscher der Allianz katalogisiert und aufbewahrt werden.",al={"was ist die sammlung","fuer welche bibliothek ist das","wohin kommen die buecher"}},{q="Worauf bezieht sich der Titel mit „den Träumern“?",a="Die Träumer bezieht sich traditionell auf die druidischen Praktizierenden, die auf den Smaragdgrünen Traum eingestimmt sind, oder auf uralte schlafende Wesenheiten, die an den Schlummer der Natur gebunden sind. Magische Werke, die ihre Geheimnisse bergen, bewahren geheimnisvolle urtümliche Macht.",al={"wer sind die traeumer","lore der traeumer","warum heisst es traeumer"}},{q="Könnt Ihr nach Abschluss der Quest weitere magische Werke bringen?",a="Die Archivare begrüßen fortlaufende Beiträge ausdrücklich. Wann immer Ihr auf Euren Reisen zusätzliche magische Werke entdeckt, die der Sammlung zugutekommen könnten, seid Ihr dazu angehalten, sie vorbeizubringen, um die weiteren Forschungen zu unterstützen.",al={"kann ich weitere buecher abgeben","ist dies wiederholbar","weitere magische werke"}},{q="Warum ist das Sammeln dieser magischen Schriften für Gelehrte wichtig?",a="Bibliotheken und Forscher in der gesamten Allianz versuchen fortwährend, ihr Verständnis arkaner, natürlicher und obskurer Arkana zu erweitern. Verlorene oder verstreute Abhandlungen enthalten Erkenntnisse, die Gelehrten helfen, die tiefere Geschichte und die Geheimnisse der Welt aufzudecken.",al={"warum magische buecher sammeln","warum braucht die bibliothek magische folianten"}}},fp="23,228,25.462.0,22.421.0,57.238.0,33.142.0,37.199.0,47.217.0,59.220.0,63.250.0"}
P.entries["quest:7815"] = {n="Schnappkiefer, Alter!",s="Im Hinterland kann Katoom der Angler aus Revantusk kaum eine Angelschnur im Wasser halten, da Salzwasserschnappkiefer sie immer wieder zerreißen und seinen Köder stehlen. Er will fünfzehn der Schildkröten tot sehen.",h="Im Hinterland kann Katoom der Angler aus Revantusk kaum eine Angelschnur im Wasser halten, da...",kw={"angler","koeder","angeln","hinterland","katoom","revantusk","schnappkiefer","schildkroeten"},sec={{t="Ärger an der Leine",b="Katoom ermahnt Euch, Euch nicht von den großen Augen der Schnappkiefer täuschen zu lassen, und bezeichnet die Schildkröten als eine Plage. Seinen Erzählungen nach kann er nicht einmal fünf Minuten lang angeln, ehe eine von ihnen seine Schnur zerreißt und sich mit seinem Köder davonmacht. Er bittet Euch als Gefallen für ihn und seine Nachbarn im Dorf darum, die ganze Brut auszulöschen; die Zahl liegt bei fünfzehn."}},faq={{q="Wer bittet Euch darum, die Schildkröten zu jagen?",a="Katoom der Angler, ein Fischer aus Revantusk im Hinterland.",al={"wer gibt schnappkiefer mon","questgeber schnappkiefer mon","katoom der angler"}},{q="Warum will Katoom, dass die Salzwasserschnappkiefer getötet werden?",a="Katoom berichtet, dass sie seine Angelschnur zerreißen und seinen Köder stehlen, sodass er nicht einmal fünf Minuten lang in Ruhe angeln kann.",al={"warum schnappkiefer toeten","schildkroetenplage","warum schildkroeten toeten revantusk"}},{q="Wie viele Schnappkiefer müssen erlegt werden?",a="Fünfzehn Salzwasserschnappkieferschildkröten.",al={"wie viele schildkroeten","anzahl schnappkiefer","anzahl schnappkiefer mon"}}},fp="14,199,19.333.0,33.60.0,51.109.0,35.34.0"}
P.entries["quest:7816"] = {n="Gammerita, Alter!",s="Katoom der Angler aus Revantusk im Hinterland hat seinen besten Köder an Gammerita verloren, das Oberhaupt der Salzwasserschnappkiefer. Ihr werdet gebeten, sie zu finden und ihn zurückzuholen.",h="Katoom der Angler aus Revantusk im Hinterland hat seinen besten Köder an Gammerita verloren, das Oberhaupt...",kw={"angler","gammerita","hinterland","katoom","köder","revantusk","schnappkiefer","schildkröte"},sec={{t="Ein Dieb unter den Schildkröten",b="Katoom beschreibt Gammerita als keine gewöhnliche Schildkröte: Sie führt die Salzwasserschnappkiefer an, und Katoom brandmarkt sie als Diebin. Sie riss seinen besten Köder von der Schnur, und seitdem beißen die Fische nicht mehr so an wie früher."},{t="Den Köder zurückholen",b="Katoom möchte, dass Ihr Gammerita findet und den Köder aus ihrem Magen holt. Gammerita hält sich an der Küste unter den anderen Schildkröten auf."},{t="Katooms Hoffnungen",b="Wenn er den Köder wieder in der Hand hat und weniger Schnappkiefer in der Nähe sind, erwartet Katoom, dass die Fische haufenweise anbeißen."}},faq={{q="Wer ist Katoom der Angler?",a="Ein Fischer aus Revantusk im Hinterland, der Euch bittet, Gammerita zu jagen.",al={"wer ist katoom","katoom revantusk","katoom aufenthaltsort"}},{q="Was ist Gammerita?",a="Eine Schildkröte, anders als die anderen, die die Salzwasserschnappkiefer anführt und die Katoom als Diebin bezeichnet.",al={"wer ist gammerita","was ist gammerita","gammerita schildkröte"}},{q="Warum will Katoom Gammerita tot sehen?",a="Gammerita riss Katooms besten Köder von der Schnur, und seitdem beißen die Fische nicht mehr so wie zuvor. Katoom will den Köder aus ihrem Magen zurückhaben.",al={"warum gammerita töten","was hat gammerita gestohlen","katoom motiv"}},{q="Wo ist Gammerita zu finden?",a="An der Küste, wo sie sich bei den anderen Salzwasserschnappkieferschildkröten aufhält.",al={"wo ist gammerita","gammerita aufenthaltsort","gammerita finden"}}},fp="15,177,25.216.0,21.128.0,14.100.1,25.73.0,18.91.0,36.145.0,29.79.0"}
P.entries["quest:782"] = {n="Zerbrochene Allianzen",s="In Kargath möchte Gorn die Ehre der Horde nach ihrem Bündnis mit Deathwing wiederherstellen. Der Oger Boss Tho'grun, der angeheuert wurde, um bei der Beschaffung des Zeichens der Erde zu helfen, wandte sich gegen die Horde und behielt es für sich, und Ihr sollt es in Camp Boff zurückholen.",h="In Kargath möchte Gorn die Ehre der Horde nach ihrem Bündnis mit Deathwing wiederherstellen.",kw={"ödland","blacklash","camp boff","deathwing","gorn","hematus","kargath","die lethlorklamm","zeichen der erde","tho'grun"},sec={{t="Eine angeheuerte Truppe wendet sich ab",b="Während des Zweiten Krieges stand die Horde an der Seite des Drachen Deathwing. Blacklash und Hematus, zwei seiner Leutnante, wurden schließlich weit im Osten in der Lethlorklamm weggesperrt. Gorn vertritt die Ansicht, dass diese verdorbenen Verbündeten von einst zum Schweigen gebracht werden müssen, wenn die Ehre der Horde wiederhergestellt werden soll. Um das Gefängnis der Drakes zu öffnen, benötigte die Horde das Zeichen der Erde und heuerte Ogermöldner unter Boss Tho'grun an, um bei der Suche zu helfen. Tho'grun wandte sich gegen sie, überwältigte sie und behielt es für sich."},{t="Camp Boff",b="Gorn schickt Euch südöstlich von Kargath nach Camp Boff, um Tho'grun zu töten und das Zeichen der Erde zurückzubringen. Gorn wird froh sein, Tho'grun tot zu sehen, und sagt, dass die Oger nicht mehr Teil der Horde sind."},{t="Was das Zeichen öffnet",b="Da Tho'grun tot ist, erwartet Gorn, dass die Oger in Unordnung geraten – ein kleiner Sieg, der zu einem größeren führt. Mit dem Zeichen in den Händen der Horde kann das Gefängnis der schwarzen Drakes in Lethlor geöffnet werden, was sie aus ihrer endlosen Gefangenschaft befreit, aber zu ihrem Untergang führt."}},faq={{q="Wer ist Gorn?",a="Gorn ist die Persönlichkeit der Horde in Kargath, die Euch nach dem Zeichen der Erde schickt und die Ehre der Horde wiederherstellen will, indem sie deren verdorbene Verbündete von einst zum Schweigen bringt.",al={"wer gibt zerbrochene bündnisse","gorn kargath","gorn lore"}},{q="Warum will Gorn den Tod von Boss Tho'grun?",a="Die Horde heuerte Tho'grun und seine Ogermöldner an, um bei der Beschaffung des Zeichens der Erde zu helfen. Tho'grun wandte sich gegen sie, überwältigte sie und behielt es.",al={"warum tho'grun töten","tho'grun verrat","boss tho'grun lore"}},{q="Wo liegt Camp Boff?",a="Camp Boff liegt südöstlich von Kargath.",al={"camp boff ort","wo ist tho'grun","boss tho'grun finden"}},{q="Was ist das Zeichen der Erde?",a="Es ist ein Schlüssel, der benötigt wird, um das Gefängnis der Drakes in der Lethlorklamm zu entriegeln.",al={"zeichen der erde","was bewirkt zeichen der erde"}},{q="Welche Drachen sind in der Lethlorklamm eingesperrt?",a="Blacklash und Hematus, zwei von Deathwings Leutnanten aus der Zeit des Bündnisses der Horde mit ihm im Zweiten Krieg.",al={"wer ist in der lethlorklamm","blacklash und hematus","deathwing leutnante"}}},fp="16,236,18.475.0,9.196.0,19.252.1,12.158.0,38.142.0,19.36.0,30.72.0,47.119.0"}
P.entries["quest:7828"] = {n="Die Pirsch auf die Pirscher",s="Jäger Markhor aus dem Dorf Revantusk im Hinterland bezeichnet die Silvermane-Wölfe als eine der schlimmsten Gefahren für die Jäger des Dorfes. Ihr werdet gebeten, den Spieß umzudrehen und die Jäger zu jagen.",h="Jäger Markhor aus dem Dorf Revantusk im Hinterland bezeichnet die Silvermane-Wölfe als eine der schlimmsten...",kw={"wölfe im hinterland","jäger markhor","revantusk","silvermane howler","silvermane stalker","stalking the stalkers"},sec={{t="Wölfe im Versteck",b="Markhor verweist auf die vielen Trolle, die die Wildnis des Hinterlands bereits gefordert hat, und zählt die Silvermane-Wölfe zu den größten Gefahren für Revantusks Jäger. Die Wölfe lauern versteckt im Gebüsch und im Schutz des Geländes und schlagen zu, sobald der Augenblick günstig ist. Markhor will das nicht unbeantwortet lassen und drängt Euch, wie ein Silvermane zu denken, die Jagd auf die Jäger zu eröffnen und jeden Einzelnen von ihnen zur Strecke zu bringen."},{t="Was Markhor verlangt",b="Markhor verlangt den Tod von fünfzehn Silvermane Stalkern und fünfzehn Silvermane Howlern. Markhor fügt hinzu, dass die Wölfe draußen in der Wildnis des Hinterlands lauern."},{t="Revantusks Dank",b="Sobald es vollbracht ist, dankt Markhor Euch im Namen der Revantusk für das, was Ihr ihnen gegeben habt."}},faq={{q="Wer verlangt die Jagd auf die Wölfe?",a="Jäger Markhor aus dem Dorf Revantusk im Hinterland.",al={"wer vergibt stalking the stalkers","questgeber stalking the stalkers","markhor quest"}},{q="Warum stellen die Silvermane-Wölfe eine solche Bedrohung dar?",a="Markhor zählt sie zu den größten Gefahren für Revantusks Jäger: Sie verbergen sich im Gebüsch sowie im Gelände und schlagen zu, sobald sich die Gelegenheit bietet, und viele Trolle sind bereits draußen in der Wildnis umgekommen.",al={"warum silvermane-wölfe töten","bedrohung durch silvermane-wölfe","warum wölfe im hinterland dezimieren"}},{q="Welche Wölfe müssen dezimiert werden?",a="Fünfzehn Silvermane Stalker und fünfzehn Silvermane Howler.",al={"welche wölfe getötet werden müssen","ziele von stalking the stalkers","wolfarten im hinterland"}},{q="Wo sind diese Wölfe zu finden?",a="Markhor berichtet, dass sie draußen in der Wildnis des Hinterlands lauern.",al={"wo sind silvermane-wölfe zu finden","ort der silvermane stalker","ort der silvermane howler"}}},fp="21,202,16.414.0,17.144.0,18.92.1,37.65.0,44.207.0,31.59.0,29.52.0"}
P.entries["quest:7829"] = {n="Jagt die Wilden",s="Jäger Markhor aus dem Dorf Revantusk im Hinterland bezeichnet die wilden Eulenbestien als einige der widerspenstigsten Kreaturen der Region und bittet Euch, zwanzig von ihnen zu töten.",h="Jäger Markhor aus dem Dorf Revantusk im Hinterland bezeichnet die wilden Eulenbestien als einige der...",kw={"hinterland","jagt die wilden","jäger markhor","eulenbestien","revantusk","wilde eulenbestie"},sec={{t="Klauen und Schnäbel",b="Markhor beschreibt die wilden Eulenbestien als einige der widerspenstigeren Kreaturen des Hinterlands und sagt, die Klauen und Schnäbel der Bestien hätten Revantusk viele gute Krieger gekostet. Markhor will, dass jede, die Ihr seht, getötet wird, bis Ihr kein Blutvergießen mehr ertragen könnt, und dann wird der von Euch geleistete Beitrag gewogen und beurteilt. Zwanzig müssen fallen."},{t="Den Geist klären",b="Markhors Rat für die Jagd ist es, den Geist von unreinen Gedanken zu klären und eins mit der Wildnis zu werden. Die Eulenbestien befinden sich draußen in der Wildnis des Hinterlands."},{t="Markhors Urteil",b="Nach der Jagd ernennt Markhor Euch zu einem würdigen Freund der Revantusk."}},faq={{q="Wer bietet diese Jagd an?",a="Jäger Markhor aus dem Dorf Revantusk im Hinterland.",al={"wer vergibt jagt die wilden","jagt die wilden questgeber","jäger markhor quest"}},{q="Warum möchte Markhor, dass die wilden Eulenbestien getötet werden?",a="Markhor bezeichnet sie als widerspenstig und sagt, dass sie mit ihren Klauen und Schnäbeln viele gute Revantuskkrieger das Leben gekostet haben.",al={"warum wilde eulenbestien töten","grund für die jagd auf eulenbestien","warum jagt die wilden"}},{q="Wo sind die wilden Eulenbestien zu finden?",a="Markhor sagt, sie hausen in der Wildnis des Hinterlands.",al={"standort der wilden eulenbestien","wo sind wilde eulenbestien","eulenbestien im hinterland"}},{q="Wie viele wilde Eulenbestien müssen getötet werden?",a="Zwanzig wilde Eulenbestien.",al={"wie viele eulenbestien zu töten sind","jagt die wilden anforderung"}}},fp="16,172,15.335.0,17.143.0,18.67.1,21.65.0,50.109.0,40.49.0,40.24.0"}
P.entries["quest:783"] = {n="Die Bedrohung von innen",s="Die Bedrohung von innen markiert den Beginn des Dienstes für Verteidiger, die dem Ruf von Sturmwind im Nordhaintal folgen. In die Abtei von Nordhain geschickt, um sich bei Marschall McBride zu melden, erfahren frische Freiwillige, dass das Militär des Königreichs im Ausland gebunden ist, wodurch die lokalen Garnisonen ohne zivile Hilfe mit den inneren Unruhen überfordert sind.",h="Die Bedrohung von innen markiert den Beginn des Dienstes für Verteidiger, die dem Ruf von Sturmwind im...",kw={"die bedrohung von innen","abtei","wald von elwynn","marschall mcbride","nordhain","rekrutierung","wache von sturmwind","freiwillige"},ang={["faction:Alliance"]="Die Quest unterstreicht die Belastung, der die Große Allianz ausgesetzt ist: Das Aufrechterhalten militärischer Verpflichtungen in fernen Territorien macht selbst die sichersten Kernlande anfällig für einen inneren Zusammenbruch.",["race:Human"]="Da Nordhain das Starttal für menschliche Verteidiger ist, stellt die Befolgung von Marschall McBrides Ruf Euer erstes offizielles Gelöbnis dar, Eure Heimat und das Königreich Sturmwind zu beschützen."},sec={{t="Ein überdehntes Königreich",b="Das Nordhaintal war einst ein friedlicher Rückzugsort für Gebet, Landwirtschaft und monastische Studien. Heute dient es als vorderste Verteidigungslinie gegen innere Unruhen im Wald von Elwynn. Die regulären Streitkräfte von Sturmwind wurden weiträumig an fernen Fronten stationiert, sodass das Kernland der Hauptstadt gefährlich unterbesetzt ist. Da kaum offizielle Soldaten vor Ort stationiert sind, muss die Wache von Sturmwind jeden gewillten Freiwilligen rekrutieren, der die Tore der Abtei erreicht."},{t="Der Ruf des Marshals",b="In der Abtei von Nordhain koordiniert Marschall McBride die Verteidigung des Tals angesichts wachsender regionaler Probleme. Während Gefahren aus Übersee die Allianz aus der Ferne bedrohen, nutzen gesetzlose Banditen, wucherndes Ungeziefer und unterirdische Plagen das Machtvakuum direkt vor der Haustür des Königreichs. Wer diesem Ruf folgt, tritt umgehend in den Militärdienst ein, der mit der Sicherung der unmittelbaren Umgebung der Abtei beginnt, bevor die tiefergehende Fäulnis bekämpft werden kann, die im Wald von Elwynn Wurzeln schlägt."}},faq={{q="Was ist der Zweck dieser Quest?",a="Sie dient als einleitender Ruf für neu eingetroffene Rekruten im Nordhaintal. Ihr werdet angewiesen, die Abtei von Nordhain zu betreten und Euch direkt bei Marschall McBride zu melden, um Euch an den örtlichen Verteidigungsbemühungen zu beteiligen.",al={"bedrohung von innen quest","was ist diese quest","nordhain intro quest"}},{q="Wer ist Marschall McBride?",a="Marschall McBride ist der leitende Offizier der Wache von Sturmwind, der in der Abtei von Nordhain stationiert ist. Er überwacht die Verteidigung des Tals, koordiniert die Rekruten und verteilt Aufgaben, um die Bedrohungen im umliegenden Umland einzudämmen.",al={"marschall mcbride","wer ist mcbride","abtei kommandant"}},{q="Warum rekrutiert Sturmwind Freiwillige, anstatt reguläre Soldaten zu entsenden?",a="Die stehenden Heere von Sturmwind wurden auf fernen Feldzügen im Ausland eingesetzt, um die Interessen der Allianz zu schützen. Diese schwere Verpflichtung in Übersee hinterlässt die Garnisonen im Kernland kritisch unterbesetzt, was die lokalen Befehlshaber dazu zwingt, auf neu eingetroffene Abenteurer und Freiwillige zurückzugreifen, um ihre eigene Heimat zu verteidigen.",al={"warum freiwillige","wo sind die wachen","warum ist sturmwind unterbesetzt"}},{q="Welche Bedrohungen plagen derzeit das Nordhaintal?",a="Das Tal steht unter gleichzeitigem Druck: aggressive Kobolde, die die nahegelegenen Minen und Hügel heimsuchen, kranke oder räuberische Schädlinge, die die umliegenden Weinberge befallen, sowie organisierte Banden von Gesetzlosen, die die geschwächte lokale Garnison ausnutzen.",al={"bedrohungen im tal","was greift nordhain an","nordhain probleme"}},{q="Wohin führt dieser Auftrag als Nächstes?",a="Die Meldung bei Marschall McBride schaltet mehrere unmittelbare Aufgaben rund um Nordhain frei, die Rekruten dazu anweisen, Überfälle der Kobolde in den Hügeln abzuwehren, lokalen Bauern und Arbeitern zu helfen sowie die wachsende Präsenz organisierter Banditen zu untersuchen.",al={"folgequest","was kommt nach bedrohung von innen","mcbride folgequest"}},{q="Warum wird die Abtei von Nordhain als militärischer Kommandoposten genutzt?",a="Obwohl die Abtei von Nordhain eine heilige Stätte des Glaubens und der Gelehrsamkeit ist, machen ihre befestigten Steinmauern und die zentrale Lage sie zum einzigen praktischen Stützpunkt im Tal. Als die örtliche Ordnung ins Wanken geriet, errichtete die Wache von Sturmwind ihren Verwaltungssitz direkt in ihren Hallen.",al={"warum militär in abtei","nordhain kirche militär","heilige abtei soldaten"}}},fx={["2039075b"]={q="Warum schickt Euch Deputy Willem zu Marschall McBride?",a="Deputy Willem ist vor der Abtei von Nordhain stationiert, um kampffähige Neuankömmlinge so schnell wie möglich zu überprüfen. Da das Militär des Königreichs überlastet ist und mehrere Krisen die Grenzen von Nordhain bedrohen, muss er jeden fähigen Freiwilligen ordnungsgemäß zum Dienst einberufen. Anstatt selbst Missionen zuzuweisen, schickt Willem Euch direkt zu seinem befehlshabenden Offizier, Marschall McBride, damit Ihr formell eingewiesen und dort eingesetzt werden könnt, wo die Verteidigung des Tals am meisten wackelt.",al={"warum mit mcbride sprechen","willem motiv","warum mit mcbride reden"}}},fp="15,247,24.347.0,18.360.0,34.131.0,23.173.0,75.173.0,54.175.0,37.171.0,62.226.0"}
P.entries["quest:7830"] = {n="Die Gefallenen rächen",s="Jäger Markhor aus Revantusk berichtet, dass die Wildhammer Greifen dazu abrichten, Trolle zu töten, und er will, dass die älteren Greifen der Region, die Skylords, vernichtet werden. Ihr sollt einen Razorbeak Skylord töten und ihm dessen Feder bringen.",h="Jäger Markhor aus Revantusk berichtet, dass die Wildhammer Greifen dazu abrichten, Trolle zu töten, und er...",kw={"avenging the fallen","greif","hinterland","jäger markhor","razorbeak skylord","revantusk","skylord-feder","wildhammer"},sec={{t="Das Töten der Skylords",b="Markhor, ein Jäger aus Revantusk im Hinterland, ist verbittert darüber, dass die Wildhammer Greifen dazu abrichten, Trolle zu töten. Ihnen wird Gerechtigkeit widerfahren, verspricht er, doch zuerst möchte er, dass Ihr Euch gegen die älteren Greifen der Region wendet, die Skylords. Tötet einen und kehrt mit seiner Feder zurück. Der Razorbeak Skylord ist eine seltene Art, die sich vor allem in der Wildnis des Hinterlands aufhält, und Markhor gibt ihm die Schuld daran, mörderischen Nachwuchs heranzuzüchten."},{t="Die Feder begutachtet",b="Markhor betrachtet die Feder und fragt sich laut, wie viele Jäger die Bestie wohl verschlungen hat, bevor sie durch Eure Hände ihre gerechte Strafe fand."}},faq={{q="Wer bietet diese Jagd an?",a="Jäger Markhor bietet sie in Revantusk im Hinterland an.",al={"questgeber","wer gibt avenging the fallen","markhor standort"}},{q="Warum will Jäger Markhor, dass ein Skylord getötet wird?",a="Markhor berichtet, dass die Wildhammer Greifen dazu abrichten, Trolle zu töten, und er will, dass die älteren Greifen der Region, die Skylords, vernichtet werden. Er sagt, der Razorbeak Skylord sei eine seltene Art, die mörderischen Nachwuchs heranzüchtet.",al={"warum razorbeak skylord töten","warum skylord töten","warum greifen jagen"}},{q="Wo ist ein Razorbeak Skylord zu finden?",a="Markhor sagt, diese seltene Art halte sich in der Wildnis des Hinterlands auf.",al={"skylord standort","wo ist razorbeak skylord","skylord-feder standort"}},{q="Was muss zu Markhor zurückgebracht werden?",a="Tötet einen Razorbeak Skylord und kehrt mit seiner Feder zu Markhor zurück.",al={"welchen gegenstand brauche ich","avenging the fallen ziel","skylord beute"}}},fp="19,229,20.422.0,18.119.1,21.67.0,47.206.0,39.67.0,37.62.0"}
P.entries["quest:7839"] = {n="Schläger der Vilebranch",s="Schmied Slagtree aus Revantusk berichtet, dass Vilebranch-Trolle das Dorf überfallen und seine Werkzeuge gestohlen haben. Er besitzt zwar Ersatzwerkzeuge, doch das gestohlene Set war das Geschenk eines gutherzigen Gnoms, der ihm als jungem Orc das Leben rettete, und er möchte es zurückhaben.",h="Schmied Slagtree aus Revantusk berichtet, dass Vilebranch-Trolle das Dorf überfallen und seine Werkzeuge...",kw={"agol'watha","hinterland","markhor","revantusk","shaol'watha","skulk rock","slagtrees verlorene werkzeuge","schmied slagtree","vilebranch"},sec={{t="Ein Geschenk von einem Gnom",b="Vilebranch-Trolle überfielen Revantusk und stahlen Schmied Slagtrees Werkzeuge. Er verfügt zwar über Ersatzwerkzeuge, doch das gestohlene Set war das Geschenk eines gutherzigen Gnoms, der ihm als jungem Orc das Leben rettete. Er erklärt Euch, dass ihm die Werkzeuge die Welt bedeuten, und bittet Euch, sie wiederzubeschaffen."},{t="Wo die Werkzeuge gesehen wurden",b="Slagtree berichtet, Markhor habe gemeldet, die Werkzeuge in der Nähe der Tempel von Agol'watha und Shaol'watha im Nordosten des Hinterlands gesehen zu haben. Er fügt hinzu, dass Ihr auch Skulk Rock absuchen solltet, und warnt davor, dass die Vilebranch-Trolle der Region skrupellos und mörderisch sind."}},faq={{q="Warum sind diese gestohlenen Werkzeuge für Schmied Slagtree so wichtig?",a="Das Set war das Geschenk eines gutherzigen Gnoms, der Slagtree als jungem Orc das Leben rettete. Er besitzt zwar Ersatzwerkzeuge, doch diese bedeuten ihm laut eigener Aussage die Welt.",al={"warum slagtree seine werkzeuge wichtig sind","slagtrees verlorene werkzeuge lore","warum slagtrees werkzeuge besonders sind"}},{q="Wer stahl die Werkzeuge aus Revantusk?",a="Vilebranch-Trolle überfielen das Dorf und stahlen Schmied Slagtrees Werkzeuge.",al={"wer die werkzeuge genommen hat","wer slagtrees werkzeuge gestohlen hat"}},{q="Wohin wurden die verschwundenen Werkzeuge gebracht?",a="Markhor sah sie in der Nähe der Tempel von Agol'watha und Shaol'watha im Nordosten des Hinterlands. Slagtree rät zudem, Skulk Rock abzusuchen.",al={"wo slagtrees werkzeuge sind","wo man die werkzeuge findet","slagtrees werkzeugfundort"}},{q="Wer berichtete, die Werkzeuge nach dem Überfall gesehen zu haben?",a="Markhor ist derjenige, der Slagtree Nachricht darüber überbrachte, wo die Werkzeuge gesichtet wurden.",al={"wer die werkzeuge gesehen hat","wer die gestohlenen werkzeuge gemeldet hat"}}},fp="20,243,19.273.0,25.258.0,58.157.0,43.71.0,35.141.0,45.74.0"}
P.entries["quest:784"] = {n="Vernichtet die Verräter",s="Vernichtet die Verräter ist ein militärischer Schlag der Horde, der von Gar'Thok in Klingenhügel angeordnet wurde, um Burg Tiragarde von menschlichen Invasoren zurückzuerobern. Streitkräfte der Kul Tiraner unter Lieutenant Benedict haben die Festung wieder besetzt und damit den brüchigen Frieden zwischen Durotar und Theramore direkt verletzt. Die Ausschaltung ihrer Garnison ist entscheidend für die Sicherung der Ostküste der Heimat der Orcs.",h="Vernichtet die Verräter ist ein militärischer Schlag der Horde, der von Gar'Thok in Klingenhügel angeordnet...",kw={"daelin prachtmeer","durotar","gar'thok","kul tiras","lieutenant benedict","marinesoldaten","klingenhügel","matrosen","burg tiragarde","vernichtet die verräter"},ang={["faction:Horde"]="Die Besetzung von Burg Tiragarde durch die Kul Tiraner ist ein andauernder Akt der Feindseligkeit direkt vor der Haustür von Durotar. Die Beseitigung von Benedicts Streitkräften zeigt, dass die Horde ihre neu gegründete Heimat vor fremden Flotten verteidigen kann.",["race:Orc"]="Orcs achten den mit Jaina am Hyjal geschlossenen Waffenstillstand, aber Kul Tiras weckt bittere Erinnerungen an den Zweiter Krieg. Die Abwehr von Benedicts Marinesoldaten ist eine Frage des Überlebens und des Stolzes auf die eigenen Vorfahren.",["race:Troll"]="Burg Tiragarde liegt unangenehm nah an der Siedlung der Dunkelspeere in Sen'jin. Die Vertreibung dieser feindseligen Seeleute schützt direkt das verwundbare neue Zuhause der Trolle."},sec={{t="Ein gebrochener Waffenstillstand",b="Als Thrall die Horde über das große Meer nach Kalimdor führte, schloss er ein unsicheres Bündnis mit Jaina Prachtmeer, um die Brennende Legion am Hyjal zu besiegen. Dieser Frieden wurde gebrochen, als Jainas entfremdeter Vater, Großadmiral Daelin Prachtmeer, mit der gewaltigen Flotte von Kul Tiras eintraf. Er gab allen Orcs die Schuld an den Gräueltaten der Alten Horde, marschierte in Durotar ein und eroberte Stützpunkte an der Küste, darunter Burg Tiragarde. Obwohl Daelin schließlich bei Theramore getötet wurde, weigern sich die Überreste seiner Flotte, irgendeinen Pakt zu achten oder ihren Hass aufzugeben."},{t="Benedicts Wiederaufleben",b="Nach dem Fall des Großadmirals war Burg Tiragarde kurzzeitig gefallen, doch Reservisten von Kul Tiras unter Lieutenant Benedict haben die Festung seitdem wieder eingenommen. Von dieser befestigten Stellung zwischen Klingenhügel und Sen'jin aus belästigen die Matrosen und Marinesoldaten Reisende und bedrohen die Zugänge vom Meer im Osten. Gar'Thok betrachtet ihre verschanzte Position als unmittelbare Gefahr für die Sicherheit von Durotar und ruft die Krieger der Horde dazu auf, direkt gegen das Kommando von Benedict vorzugehen."}},faq={{q="Warum greifen die Menschen der Kul Tiraner Durotar an?",a="Es handelt sich um Überreste der Expeditionsflotte, die unter dem Kommando von Großadmiral Daelin Prachtmeer stand. Der Admiral weigerte sich, eine friedliche Koexistenz zwischen Menschen und Orcs zu akzeptieren, und versuchte, Durotar vollständig auszulöschen. Selbst nach seinem Tod besetzen seine Loyalisten weiterhin befestigte Küstenposten wie Burg Tiragarde, um der Horde zu trotzen.",al={"warum sind menschen in durotar","kul tiras greift an","hintergrund burg tiragarde menschen"}},{q="Wer ist Lieutenant Benedict?",a="Lieutenant Benedict ist der kommandierende Offizier der Reservisten von Kul Tiras, die derzeit Burg Tiragarde halten. Nach der Niederlage von Großadmiral Proudmoore sammelte Benedict die überlebenden Marines und Matrosen, um die Küstenbefestigung zurückzuerobern und beharrliche Operationen gegen die Orcs zu starten.",al={"wer ist benedict","hintergrund lieutenant benedict","anführer burg tiragarde"}},{q="Unterstützt Jaina Prachtmeer diese Menschen?",a="Nein. Jaina schloss einen Pakt des gegenseitigen Überlebens mit Kriegshäuptling Thrall und stellte sich aktiv gegen den aggressiven Kreuzzug ihres Vaters, um den Frieden zu bewahren. Die Truppen, die Burg Tiragarde halten, sind abtrünnige Überreste von Kul Tiras, die die Diplomatie von Theramore ablehnen und Jainas Waffenstillstand als Verrat betrachten.",al={"unterstützt jaina sie","bündnis theramore kul tiras","jaina prachtmeer tiragarde"}},{q="Warum werden sie als 'Verräter' bezeichnet?",a="Gar'Thok betrachtet sie als Verräter, weil ihre Invasion direkt gegen die diplomatische Vereinbarung verstieß, die Thrall und Jaina Prachtmeer trafen, um Archimonde im Dritter Krieg zu besiegen. Ihre anhaltende militärische Präsenz im souveränen Gebiet der Horde widerspricht den nach dem Krieg auf Kalimdor festgelegten Grenzen.",al={"warum verräter","wer hat wen verraten","bedeutung verräter"}},{q="Wo befindet sich Burg Tiragarde?",a="Burg Tiragarde liegt an der Ostküste von Durotar, südlich von Klingenhügel und nordöstlich von Sen'jin. Ihre hohen Steinmauern überblicken die Küstengewässer und bieten den Invasoren eine strategische Basis in der Nähe der Siedlungen der Horde.",al={"standort burg tiragarde","wo liegt burg tiragarde","wo findet man benedict"}}},fx={["6a077d02"]={q="Warum will Gar'Thok, dass Burg Tiragarde geräumt wird?",a="Gar'Thok überwacht die Verteidigung von Klingenhügel und dem östlichen Durotar. Die Wiederbesetzung von Burg Tiragarde durch feindselige Kräfte der Kul Tiraner bedroht direkt die Sicherheit der Heimat der Orcs und missachtet den Frieden, der zwischen Thrall und Jaina Prachtmeer geschlossen wurde. Wenn man zulässt, dass eine bewaffnete menschliche Festung an der Küste von Durotar weiterbesteht, setzt man nahegelegene Siedlungen und Nachschubwege einer unmittelbaren Invasionsgefahr aus.",al={"gar'thok motiv","warum burg tiragarde räumen","gar thok warum menschen angreifen"}},["902328ad"]={q="Wen sollt Ihr in Burg Tiragarde ausschalten?",a="Ihr habt den Auftrag, die überlebenden Seestreitkräfte der Kul Tiraner zu zerschlagen, die Burg Tiragarde besetzt halten: Seeleute, Marinesoldaten und ihren befehlshabenden Offizier, Lieutenant Benedict. Diese Soldaten stellen die Überreste der Flotte von Großadmiral Daelin Prachtmeer dar und halten einen nicht genehmigten, bewaffneten Brückenkopf tief im souveränen Gebiet der Horde.",al={"wer in burg tiragarde töten","wer sind die ziele","ziele bezwingen"}}},fp="22,366,17.559.0,21.469.0,43.323.0,27.292.0,43.277.0,32.304.0,32.240.0"}
P.entries["quest:7840"] = {n="Lards vergessene Brotzeit",s="Lard aus dem Dorf Revantusk im Hinterland ist hungrig und verängstigt. Ein Vilebranch schlug Lard während eines privaten Picknicks, und Lard floh ohne das Mittagessen. Ihr werdet gebeten, es von einer Insel im Norden zu holen.",h="Lard aus dem Dorf Revantusk im Hinterland ist hungrig und verängstigt.",kw={"hinterland","insel","lard","mittagessen","picknick","revantusk","vilebranch"},sec={{t="Ein unterbrochenes Picknick",b="Lard picknickte an einem geheimen Ort, als ein Vilebranch, in Lards Erzählung hässlich und gemein, Lard mit einem großen Stock schlug. Lard rannte nach Revantusk und ließ das Mittagessen zurück. Nun ist Lard hungrig und hat Angst, zurückzukehren."},{t="Die Insel im Norden",b="Der Picknickplatz liegt auf einer Insel im Norden. Lard hofft, dass Ihr dorthin geht, das Mittagessen findet und es zurückbringt, während Ihr Euch vor den Vilebranch-Trollen in Acht nehmt."},{t="Lards Dank",b="Das Mittagessen erweist sich als eine riesige Fleischkeule. Lard schlingt sie hinunter, dankt Euch und verspricht Euch einen besonderen Picknickkorb für Eure Hilfe."}},faq={{q="Wer ist Lard?",a="Ein Bewohner von Revantusk im Hinterland, hungrig und verängstigt, nachdem ein Vilebranch Lard mit einem großen Stock geschlagen hat.",al={"lard hinterland","wer ist lard","lard revantusk"}},{q="Wo hat Lard sein Mittagessen verloren?",a="An einem versteckten Picknickplatz auf einer Insel im Norden.",al={"wo ist lards mittagessen","lard picknickplatz","lards geheimer ort"}},{q="Warum hat Lard sein Essen zurückgelassen?",a="Ein Vilebranch schlug Lard während des Picknicks mit einem großen Stock, und Lard rannte ohne das Mittagessen zurück nach Revantusk.",al={"warum ist lard geflohen","wer griff lard an"}},{q="Worauf solltet Ihr auf der Insel achten?",a="Lard nennt die Vilebranch-Trolle als die Gefahr auf der Insel.",al={"vilebranch auf der insel","gefahren auf lards insel"}}},fp="19,213,20.211.0,20.153.0,13.136.1,12.114.0,30.50.0,35.107.0,44.61.0"}
P.entries["quest:7841"] = {n="Eine Botschaft an die Wildhämmer",s="In Revantusk im Hinterland berichtet Otho Moji'ko, dass die Wildhammer Pakte mit den Feinden der Trolle schließen, und diesmal sind die Hochelfen ihre Partner. Otho möchte den Wildhammerzwergen eine Botschaft im Blut der Highvale-Hochelfen an der Quel'Danil-Hütte übermitteln.",h="In Revantusk im Hinterland berichtet Otho Moji'ko, dass die Wildhammer Pakte mit den Feinden der Trolle...",kw={"hochbrunn","hinterland","nachricht an die wildhämmer","otho moji'ko","die quel'danil-hütte","revantusk","wildhammer"},sec={{t="Eine Botschaft in Blut",b="Die Wildhammer schmieden neue Allianzen mit den Feinden der Trolle, und dieses Mal sind die Hochelfen ihre Partner. Otho Moji'ko spuckt bei diesem Gedanken aus. Den Zwergen gebührt eine Nachricht, geschrieben im Blut ihrer neuen Freunde: Schwingt die Klingen gegen jeden Highvale-Hochelfen, dem Ihr begegnet, und hinterlasst die Leichen als Warnung. Highvale Outrunners, Scouts, Marksmen und Rangers versammeln sich an der Quel'Danil-Hütte im Nordwesten des Hinterlands."},{t="Kunde in Revantusk",b="Wenn Ihr zurückkehrt, verkündet Otho, dass auch die Revantusk neue Allianzen schmieden, und lobt Eure Arbeit."}},faq={{q="Wer bietet diese Quest an?",a="Otho Moji'ko, der in Revantusk steht.",al={"wer gibt nachricht an die wildhämmer","otho moji'ko quest"}},{q="Wo befinden sich die Highvale-Hochelfen?",a="Sie versammeln sich an der Quel'Danil-Hütte im Nordwesten des Hinterlands.",al={"quel'danil-hütte standort","wo sind hochelfen von hochbrunn","wo findet man späher von hochbrunn"}},{q="Warum möchte Otho Moji'ko, dass die Hochelfen angegriffen werden?",a="Otho sagt, dass die Wildhammer Pakte mit den Feinden der Trolle schließen und nun mit den Hochelfen zusammenarbeiten. Otho möchte den Wildhammerzwergen eine Botschaft übermitteln, geschrieben im Blut der Hochelfen.",al={"warum quel'danil angreifen","warum hochelfen im hinterland töten"}},{q="Welche Highvale-Elfen sollen laut Otho niedergemetzelt werden?",a="Highvale Outrunners, Scouts, Marksmen und Rangers an der Quel'Danil-Hütte.",al={"welche elfen von hochbrunn","schütze von hochbrunn","waldläufer von hochbrunn"}}},fp="25,280,18.421.0,25.107.1,22.46.0,42.63.0,51.208.0,48.70.0"}
P.entries["quest:7842"] = {n="Eine weitere Botschaft an die Wildhämmer",s="Nach der ersten Nachricht sagt Otho Moji'ko in Revantusk, dass die Wildhammer und ihre Greifen einander so nahestehen wie ein Troll und eine Gefährtin. Ekelhaft, aber es kann gegen sie verwendet werden. Otho möchte, dass Greifen im Hinterland für ihre Federn getötet werden.",h="Nach der ersten Nachricht sagt Otho Moji'ko in Revantusk, dass die Wildhammer und ihre Greifen einander so...",kw={"greif","hinterland","long elegant feather","otho moji'ko","revantusk","wildhammer"},sec={{t="Eine Nachricht aus Federn",b="Nach den Hochelfen von Highvale hat Otho Moji'ko eine weitere Botschaft zu überbringen. Man sagt, die Wildhammer und ihre Greifen stünden sich so nahe wie ein Troll und eine Gefährtin, was Otho ekelhaft findet, aber nützlich. Tötet die Greifen, denen Ihr im Hinterland begegnet, und sammelt ihre Long Elegant Feathers. Es ist bekannt, dass Greifen dort in jeder Region leben. Aus den Federn wird Otho die letzte Nachricht herstellen."},{t="Othos Freude",b="Otho erwartet, dass die letzte Nachricht die Wildhammer abschreckt oder sie andernfalls sehr, sehr wütend macht. Otho freut sich darüber, dass noch ein Schritt bleibt, bevor die Wildhammer einsehen, dass man sich mit Trollen nicht anlegen kann."}},faq={{q="Wer vergibt diese Quest?",a="Otho Moji'ko, der in Revantusk steht.",al={"wer vergibt another message to the wildhammer","another message questgeber","otho mojiko"}},{q="Warum will Otho Moji'ko Greifenfedern?",a="Otho sagt, die Wildhammer und ihre Greifen stünden sich so nahe wie ein Troll und eine Gefährtin, und will das gegen sie verwenden. Die Federn werden in die letzte Botschaft einfließen.",al={"warum greifenfedern","warum greifen im hinterland töten"}},{q="Wo sind Greifen zu finden?",a="Es ist bekannt, dass Greifen in jeder Region des Hinterlands leben.",al={"greifen orte hinterland","wo sind greifen im hinterland"}},{q="Was geschah vor dieser Nachricht?",a="Sie folgt auf Message to the Wildhammer, worin Otho Hochelfen von Highvale als Warnung an die Zwerge abschlachten ließ.",al={"was kommt vor another message to the wildhammer","message to the wildhammer reihe"}}},fp="33,244,21.388.0,15.199.1,21.46.0,44.160.0,28.62.0,30.116.0"}
P.entries["quest:7843"] = {n="Die letzte Botschaft an die Wildhämmer",s="Otho Moji'ko gibt Euch einen Speer, der mit Blut getränkt und mit Greifenfedern gebunden ist. Ihr sollt ihn nach Nistgipfel im Westen des Hinterlands bringen und ihn neben dem Brunnen im Herzen der Stadt in die Erde rammen.",h="Otho Moji'ko gibt Euch einen Speer, der mit Blut getränkt und mit Greifenfedern gebunden ist.",kw={"nistgipfel","greifenfedern","hinterland","otho moji'ko","revantusk","speer","wildhammer"},sec={{t="Ein Speer für Nistgipfel",b="Im Anschluss an Another Message to the Wildhammer überbringt Euch Otho Moji'ko die finale Botschaft: einen Speer, der mit Blut getränkt und mit Greifenfedern gebunden ist. Tragt ihn nach Nistgipfel und pflanzt ihn mitten im Zentrum der Stadt neben dem Brunnen ein, um den Zwergen zu zeigen, dass die Trolle es ernst meinen. Otho hofft, dass Ihr lebend zurückkehrt, und warnt vor wütenden Wildhammerzwergen und aufrührerischem Allianz-Volk."},{t="Othos Hoffnung",b="Otho wünscht, er hätte die Gesichter der Zwerge gesehen, und fragt sich laut, ob sie wohl ihre Taschen packen und die Stadt verlassen. Otho verspricht Euch das große Mojo für die Tat."}},faq={{q="Wer schickt Euch aus, um den Speer einzupflanzen?",a="Otho Moji'ko, der in Revantusk steht.",al={"questgeber","wer gibt die quest","otho mojiko"}},{q="Wo muss der Speer eingepflanzt werden?",a="Neben dem Brunnen im Herzen von Nistgipfel, im Westen des Hinterlands.",al={"speerort","wo platziert man den speer","nistgipfel brunnen"}},{q="Woraus besteht die finale Botschaft?",a="Aus einem Speer, der mit Blut getränkt und mit Greifenfedern gebunden ist.",al={"was ist der speer","greifenfedern speer","die letzte botschaft gegenstand"}},{q="Was ging dem in der Reihe voraus?",a="Es folgt auf Another Message to the Wildhammer, worin Otho nach Greifenfedern verlangte, um diese finale Botschaft herzustellen.",al={"vorherige quest","voraussetzungen","wildhammer botschaft reihe"}}},fp="35,215,22.361.0,11.167.1,33.46.0,32.75.0,34.56.0,35.115.0"}
P.entries["quest:7844"] = {n="Kannibalistische Vettern",s="Mystikerin Yayo'jin aus Revantusk bezeichnet die Trolle der Vilebranch als verkommenes Pack, das andere Trolle und Humanoide jagt. Da Zul'jin nicht da ist, um sie zu vernichten, bittet sie Euch, ihre Scalper und Soothsayer nahe den Tempeln im Nord-Nordosten zu vernichten.",h="Mystikerin Yayo'jin aus Revantusk bezeichnet die Trolle der Vilebranch als verkommenes Pack, das andere...",kw={"agol'watha","kannibalische vettern","mystikerin yayo'jin","revantusk","skalpierer","shaol'watha","wahrsager","vilebranch","zul'jin"},sec={{t="Drei Stämme, ein Land",b="Drei Trollstämme leben im Hinterland, und Mystikerin Yayo'jin sagt, dass sie, abgesehen davon, Trolle im selben Land zu sein, wenig gemein haben. Sie bezeichnet die Vilebranch, passend benannt, als verkommenes Pack, das andere Trolle und Humanoide jagt. Zul'jin hätte sie mit Leichtigkeit ausgelöscht, doch Zul'jin ist nicht da, und die Revantusk sind auf sich allein gestellt."},{t="Wo die Vilebranch sich versammeln",b="Yayo'jin bittet Euch, die Scalper und Soothsayer der Vilebranch zu vernichten, die bei den Tempeln von Shaol'watha und Agol'watha im Nord-Nordosten des Hinterlands zu finden sind."},{t="Yayo'jins Lob",b="Bei Eurer Rückkehr erklärt Yayo'jin, dass selbst Zul'jin es nicht hätte besser machen können."}},faq={{q="Wer bietet diese Quest an?",a="Mystikerin Yayo'jin, die in Revantusk steht.",al={"questgeber kannibalische vettern","wer vergibt kannibalische vettern","mystikerin yayojin"}},{q="Warum will Yayo'jin, dass die Vilebranch vernichtet werden?",a="Sie bezeichnet die Vilebranch als verkommenes Pack, das andere Trolle und Humanoide jagt, und sagt, dass es an Euch liegt, den Unrat der Region zu vernichten.",al={"warum revantusk gegen vilebranch kaempfen","kannibalismus der vilebranch","konflikt zwischen revantusk und vilebranch"}},{q="Wo sind die Vilebranch-Trolle zu finden?",a="Um die Tempel von Shaol'watha und Agol'watha im Nord-Nordosten des Hinterlands.",al={"shaolwatha standort","agolwatha standort","wo sind vilebranch-wahrsager"}},{q="Welche Vilebranch will Yayo'jin vernichtet sehen?",a="Scalper der Vilebranch und Soothsayer der Vilebranch.",al={"kannibalische vettern ziele","wen toete ich fuer kannibalische vettern"}},{q="Wo ist Zul'jin?",a="Vorerst nicht im Hinterland. Yayo'jin sagt, wenn Zul'jin da wäre, würde er die Vilebranch mit Leichtigkeit auslöschen, aber er ist nicht da, sodass die Revantusk auf sich allein gestellt sind.",al={"ist zuljin hier","wo ist zuljin hinterland","status von zul'jin"}}},fp="21,258,22.361.0,27.176.0,17.79.1,22.49.0,48.137.0,41.86.0,46.47.0,17.180.0"}
P.entries["quest:7845"] = {n="Die Entführung des Älteren Torntusk",s="Primal Torntusk von Revantusk berichtet, dass Vilebranch-Wilde ihren Gefährten, den Älteren Torntusk, bei einem kühnen mitternächtlichen Überfall verschleppt haben. Spione berichten, dass er noch lebt und auf der Spitze von Jintha'Alor gefangen gehalten wird, und sie bittet Euch, ihn zu retten.",h="Primal Torntusk von Revantusk berichtet, dass Vilebranch-Wilde ihren Gefährten, den Älteren Torntusk, bei...",kw={"älterer torntusk","hakkar","hexx","hinterlands","jintha'alor","primal torntusk","revantusk","torntusk","vilebranch"},sec={{t="Ein mitternächtlicher Überfall",b="Vilebranch-Wilde überfielen Revantusk um Mitternacht und entführten den Älteren Torntusk, den Gefährten von Primal Torntusk. Ihre Spione berichten, dass er noch am Leben ist, ein Gefangener auf der Spitze von Jintha'Alor, der Hauptstadt der Vilebranch im südlichen Hinterlands. Primal Torntusk fürchtet, dass das Dorf seinen Verlust nicht verkraften könnte."},{t="Der gesichtslose Blutgott",b="Man hört, dass Vile Priestess Hexx den Gefangenen für ein Opfer an Hakkar vorbereitet, den gesichtslosen Blutgott."},{t="Sobald Ihr ihn erreicht",b="Als Ihr den Älteren erreicht, werdet Ihr aufgefordert, schnell zu handeln, da die Wachen inzwischen sicherlich von Eurer Ankunft wissen."}},faq={{q="Wer hat den Älteren Torntusk entführt?",a="Vilebranch-Wilde entführten ihn bei einem kühnen mitternächtlichen Überfall auf Revantusk.",al={"wer hat ältesten torntusk entführt","wer hat torntusk verschleppt","entführer von torntusk"}},{q="Wo wird der Ältere Torntusk festgehalten?",a="Ihre Spione berichten, dass er auf der Spitze von Jintha'Alor gefangen gehalten wird, der Hauptstadt der Vilebranch im südlichen Hinterlands.",al={"aufenthaltsort von ältestem torntusk","wo ist älterer torntusk","wo wird torntusk gefangen gehalten"}},{q="Welches Schicksal erwartet den Älteren Torntusk auf der Spitze von Jintha'Alor?",a="Man hört, dass Vile Priestess Hexx ihn für ein Opfer an Hakkar vorbereitet, den gesichtslosen Blutgott.",al={"warum wurde torntusk gefangen genommen","was wollen die vilebranch von torntusk","hexx opferung torntusk"}},{q="Wer ist Primal Torntusk?",a="Primal Torntusk ist die Gefährtin des Älteren Torntusk, und sie bittet Euch, ihn zu retten.",al={"wer ist primal torntusk","gefährte von primal torntusk"}}},fp="25,211,15.283.0,22.101.0,18.100.1,24.73.0,35.103.0,49.93.0,23.76.0"}
P.entries["quest:7846"] = {n="Erlangt den Schlüssel!",s="Älterer Torntusk wird in Jintha'Alor in Ketten gefangen gehalten. Er sagt, Hitah'ya the Keeper habe den Schlüssel zu seinen Fesseln und befinde sich gut bewacht in der nahen Höhle, und er bittet Euch, sie zu töten und ihn zurückzubringen.",h="Älterer Torntusk wird in Jintha'Alor in Ketten gefangen gehalten.",kw={"älterer torntusk","hinterland","hitah'ya the keeper","jintha'alor","recover the key","revantusk","fesselschlüssel"},sec={{t="Die Höhle der Hüterin",b="Nach Kidnapped Elder Torntusk! findet Ihr Älteren Torntusk gefesselt in Ketten in Jintha'Alor. Hitah'ya the Keeper besitzt den Schlüssel zu seinen Fesseln und befindet sich gut bewacht in der nahen Höhle. Älterer Torntusk bittet Euch, sie zu töten und den Schlüssel zu beschaffen, damit sich seine Fesseln lösen, denn nur dann kann er nach Hause gehen."},{t="Älterer Torntusks Dank",b="Mit dem Schlüssel in der Hand erhebt sich Älterer Torntusk. Er dankt Euch und sagt, die Revantusk werden von Euren Taten erfahren."}},faq={{q="Wer besitzt den Schlüssel zu Älterer Torntusks Fesseln?",a="Hitah'ya the Keeper besitzt den Schlüssel. Älterer Torntusk sagt, sie befinde sich in der nahen Höhle und werde gut bewacht.",al={"wer hat den schlüssel","hitah'ya die hüterin","wo ist der fesselschlüssel"}},{q="Wo wird Älterer Torntusk gefangen gehalten?",a="Älterer Torntusk wird in Jintha'Alor gefangen gehalten.",al={"wo ist älterer torntusk","torntusk aufenthaltsort","jintha'alor torntusk"}},{q="Warum benötigt Älterer Torntusk den Schlüssel?",a="Der Schlüssel öffnet die Fesseln an seinen Bindungen. Nur dann, so sagt er, wird er frei sein, um nach Hause zurückzukehren.",al={"warum der fesselschlüssel","wofür ist der schlüssel"}}},fp="16,194,17.293.0,23.114.1,47.101.0,29.38.0,37.95.0"}
P.entries["quest:7847"] = {n="Rückkehr zu Primal Torntusk",s="Älterer Torntusk bittet Euch, zu seiner Gefährtin, Primal Torntusk, im Dorf der Revantusk zurückzukehren und ihr zu sagen, dass er nach Hause kommt.",h="Älterer Torntusk bittet Euch, zu seiner Gefährtin, Primal Torntusk, im Dorf der Revantusk zurückzukehren und...",kw={"älterer torntusk","hinterland","jintha'alor","primal torntusk","revantusk"},sec={{t="Neuigkeiten für seine Gefährtin",b="Älterer Torntusk ist von seinen Fesseln befreit und bittet Euch, nach Revantusk zurückzukehren. Dort sollt Ihr seiner Gefährtin, Primal Torntusk, sagen, dass er nach Hause kommt."},{t="Das Dorf ist dankbar",b="Primal Torntusk sagt, dass Ihr den Revantusk treue Dienste erwiesen habt und dass das Dorf Euch zu tiefem Dank verpflichtet ist."}},faq={{q="Wer schickt Euch auf diese Reise?",a="Älterer Torntusk bittet Euch, seiner Gefährtin die Nachricht von seiner Rettung zu überbringen.",al={"wer startet return to primal torntusk","älterer torntusk questgeber"}},{q="Wo befindet sich Primal Torntusk?",a="Primal Torntusk befindet sich in Revantusk im Hinterland.",al={"wo ist primal torntusk","primal torntusk aufenthaltsort","wo return to primal torntusk abgeben"}},{q="Was soll ich Primal Torntusk sagen?",a="Dass Älterer Torntusk nach Hause kommt.",al={"was primal torntusk sagen","torntusk nachricht"}},{q="Was geschah vor dieser Reise?",a="Sie folgt auf Recover the Key!, nach den früheren Bemühungen, die mit Kidnapped Elder Torntusk! begannen.",al={"vorherige quest","primal torntusk questreihe"}}},fp="25,121,17.160.0,23.112.1,30.68.0,33.59.0,43.35.0,30.93.0"}
P.entries["quest:7849"] = {n="Die getrennten Brüder",s="Jäger Markhor in Revantusk hat seinen Zwillingsbruder Malkhor verloren, der von den Vilebranch bei demselben Überfall verschleppt wurde, bei dem auch Torntusks Gefährtin entführt wurde. Malkhor fand ein schnelles, brutales Ende, und seine sterblichen Überreste wurden an die Schlämme und Wölfe der Vilebranch verfüttert. Markhor sagt, das Leben seines Bruders sei nicht mehr zu retten, doch seine Seele könne noch gerettet werden, und er bittet Euch, die sterblichen Überreste zu bergen.",h="Jäger Markhor in Revantusk hat seinen Zwillingsbruder Malkhor verloren, der von den Vilebranch bei demselben...",kw={"knochen","hinterland","jintha'alor","malkhor","markhor","revantusk","schädel","vilebranch","yayo'jin"},sec={{t="Der Verlust eines Zwillings",b="Markhor sagt, dass viele im Dorf geliebte Menschen an die Wildnis verloren haben, und sein eigener Verlust ist Malkhor, sein Zwilling. Die Vilebranch verschleppten Malkhor während des Überfalls, bei dem auch Torntusks Gefährtin entführt wurde. Malkhor war es nicht bestimmt zu leben, und seine Entführer brachten ihm einen schnellen, brutalen Tod."},{t="Wo die sterblichen Überreste liegen",b="Die Vilebranch verfütterten das, was von Malkhor übrig war, an ihre Schlämme und Wölfe. Eine mit Schlämmen gefüllte Abfallgrube und ein Wolfsbau liegen beide nahe der Spitze des Tempels von Jintha'Alor. Seine Knochen ruhen inmitten einer Schlammgrube nahe der obersten Ebene, und sein Schädel liegt auf der obersten Ebene selbst. Markhor beabsichtigt, die sterblichen Überreste zu Yayo'jin zu bringen, die sie für ein ordentliches Begräbnis vorbereiten wird."}},faq={{q="Wer war Jäger Malkhor?",a="Malkhor war der Zwillingsbruder von Jäger Markhor. Die Vilebranch verschleppten ihn während des Überfalls, bei dem auch Torntusks Gefährtin entführt wurde, und brachten ihm einen schnellen, brutalen Tod.",al={"wer ist malkhor","markhors bruder","malkhor lore"}},{q="Wohin wurden Malkhors sterbliche Überreste gebracht?",a="Die Vilebranch verfütterten seine sterblichen Überreste an ihre Schlämme und Wölfe. Sein Schädel liegt auf der obersten Ebene von Jintha'Alor, und seine Knochen befinden sich in einer Schlammgrube nahe dieser obersten Ebene.",al={"wo sind die knochen","wo ist malkhors schädel","jintha'alor überreste"}},{q="Wer wird Malkhor für das Begräbnis vorbereiten?",a="Markhor sagt, er werde die sterblichen Überreste zu Yayo'jin bringen, die sie für ein ordentliches Begräbnis vorbereiten wird.",al={"begräbnis für malkhor","wer ist yayojin","yayo'jin"}},{q="Warum braucht Markhor die Knochen zurück?",a="Markhor kann das Leben seines Bruders nicht mehr retten, aber er sagt, dass die Seele seines Bruders noch gerettet werden kann. Dafür möchte er, dass die sterblichen Überreste geborgen werden.",al={"warum überreste bergen","malkhors seele retten","seine seele retten"}}},fp="18,361,13.263.0,21.369.0,25.159.0,35.158.0,36.93.0,41.141.0"}
P.entries["quest:7850"] = {n="Dunkle Gefäße",s="Primal Torntusk in Revantusk berichtet, dass die Vilebranch mit einer übernatürlichen Wildheit kämpfen, dem Werk der üblen Zauberwirkerkünste von Vile Priestess Hexx. In ganz Jintha'Alor liegen dunkle Gefäße mit verdorbenem Blut, die eine finstere Magie ausstrahlen, welche dem gesichtslosen Blutgott gehört. Torntusk bittet Euch, sie zu stehlen und zurückzubringen, damit das Verderben beseitigt werden kann.",h="Primal Torntusk in Revantusk berichtet, dass die Vilebranch mit einer übernatürlichen Wildheit kämpfen, dem...",kw={"blutgott","dunkle gefäße","jintha'alor","primal torntusk","revantusk","verdorbenes blut","vile priestess hexx","vilebranch"},sec={{t="Der Zorn der Vilebranch",b="Wo immer Ihr in Jintha'Alor umhergeht, werdet Ihr Gefäße mit verdorbenem Blut finden. Sie strahlen die dunkle Macht des gesichtslosen Blutgottes aus, die die Vilebranch stärkt und sie in den Wahnsinn treibt. Torntusk glaubt, dass das Entwenden der Gefäße und das Beseitigen ihres Verderbens den Griff des Blutgottes auf sie lockern wird."},{t="Nach der Rückkehr der Gefäße",b="Mit den Gefäßen in Händen ist die finstere Energie, die die Vilebranch antreibt, gebrochen, wenn auch nur vorerst. Torntusk ermahnt Euch, stets wachsam gegenüber dem Bösen zu bleiben, da eine gefallene Priesterin bald durch eine andere ersetzt wird."}},faq={{q="Wer vergibt die Quest Dunkle Gefäße?",a="Primal Torntusk vergibt sie in Revantusk im Hinterland.",al={"wer gibt dunkle gefäße","dunkle gefäße questgeber"}},{q="Wo befinden sich die verdorbenen Gefäße?",a="Dunkle Gefäße mit verdorbenem Blut können in ganz Jintha'Alor im Hinterland gefunden werden.",al={"wo sind dunkle gefäße","fundort gefäße mit verdorbenem blut","verdorbenes blut finden"}},{q="Warum sind die Vilebranch-Trolle so wild?",a="Primal Torntusk gibt den üblen magischen Wirrnissen von Vile Priestess Hexx die Schuld. Die Gefäße mit verdorbenem Blut tragen zudem die Macht des gesichtslosen Blutgottes in sich, die die Vilebranch stärkt und in den Wahnsinn treibt.",al={"warum sind vilebranch verrückt","vilebranch wahnsinn","vilebranch wildheit"}},{q="Was plant Primal Torntusk mit den Gefäßen zu tun?",a="Torntusk plant, das Verderben von ihnen zu entfernen, um den Griff des gesichtslosen Blutgottes auf die Vilebranch zu lockern.",al={"warum die gefäße sammeln","was geschieht mit den blutgefäßen"}}},fp="12,353,19.303.0,24.210.1,33.66.0,38.85.0,43.203.0,54.113.0"}
P.entries["quest:786"] = {n="Vereitelung der Kolkaraggression",s="Vereitelung der Kolkaraggression ist eine wichtige Verteidigungsmission der Horde, die vom Späher Lar Lauerzahn nahe Sen'jin vergeben wird. Spieler erhalten den Auftrag, die Kolkarklippe zu infiltrieren, um drei Sätze koordinierter Invasionspläne zu vernichten, bevor der Zentaurenklan die jungen Siedlungen von Durotar überfallen kann.",h="Vereitelung der Kolkaraggression ist eine wichtige Verteidigungsmission der Horde, die vom Späher Lar...",kw={"durotar","kolkar","kolkarklippe","lar lauerzahn","orgrimmar","sen'jin","vereitelung der kolkaraggression","das tal der prüfungen"},ang={["faction:Horde"]="Das Stoppen der Kolkar-Offensive bewahrt die junge Horde davor, direkt vor der Schwelle ihrer neuen Heimat einen zermürbenden Gebietskrieg an mehreren Fronten führen zu müssen.",["race:Orc"]="Im Tal der Prüfungen vollziehen junge Orcs ihre Riten des Erwachsenwerdens, weshalb eine Zentaurenaggression dort eine existenzielle Beleidigung der orcischen Kriegerkultur darstellt.",["race:Troll"]="Nachdem sie bereits ihre uralte Inselheimat verloren haben, können es sich die Dunkelspeere nicht leisten, dass Sen'jin von marodierenden Zentauren überrannt wird."},sec={{t="Eine drohende Invasion",b="Beim Auskundschaften des westlichen Durotar schlich sich der Trollfährtenleser Lar Lauerzahn im Schutz der Nacht in die Kolkarklippe. Was er entdeckte, war alarmierend: Die Kolkar-Zentauren führten nicht bloß unorganisierte Überfälle an der Küste durch, sondern koordinierten eine ehrgeizige, dreigliedrige Invasion, die direkt auf die Heimat der Orcs und Dunkelspeere abzielte. Die Kriegsfürsten der Zentauren teilten ihre Schlachtstrategien unter drei verschiedenen Anführern auf, um das Tal der Prüfungen, Sen'jin und die Gates of Orgrimmar selbst anzugreifen."},{t="Schlag in die Schluchten",b="Um katastrophale Kämpfe in den trockenen roten Schluchten von Durotar abzuwenden, werden Rekruten tief in die Kolkarklippe geschickt, um der Schlange den Kopf abzuschlagen. Das Infiltrieren des staubigen Lagers und das Verbrennen der drei Angriffsschriftrollen zerschlägt die Befehlskette der Zentauren. Während Lar Lauerzahn zuversichtlich bleibt, dass die Horde jede Großinvasion unweigerlich zerschmettern würde, erspart die Zerstörung dieser Dokumente den Verteidigern Durotars ein kostspieliges Blutvergießen, solange ihre junge Nation noch um Halt ringt."}},faq={{q="Wer bietet die Quest Vereitelung der Kolkaraggression an?",a="Die Quest wird von Lar Lauerzahn vergeben, einem Späher der Dunkelspeer, der direkt außerhalb von Sen'jin an den südlichen Klippen von Durotar stationiert ist.",al={"questgeber","wer gibt die quest","lar lauerzahn aufenthaltsort"}},{q="Welche Ziele planen die Kolkar-Zentauren anzugreifen?",a="Die Schlachtpläne der Kolkar skizzieren eine koordinierte, dreistufige Offensive, die auf das Tal der Prüfungen, Sen'jin und die Hordehauptstadt Orgrimmar abzielt.",al={"zentauren ziele","was sind die angriffspläne","drei ziele"}},{q="Wo befindet sich die Kolkarklippe?",a="Die Kolkarklippe ist ein sonnendurchfluteter Schluchtenkomplex, der westlich über den felsigen Kämmen von Sen'jin im südlichen Durotar liegt.",al={"kolkarklippe standort","wo ist die klippe","zentaurendorf durotar"}},{q="Wo sind die Angriffspläne in der Klippe zu finden?",a="Die drei Schriftrollen mit den Invasionsplänen befinden sich im Besitz von drei verschiedenen Anführern der Kolkar, die unterschiedliche Lagerplätze in der Klippe bewachen.",al={"fundorte der angriffspläne","wo sind die schriftrollen","anführer der kolkar"}},{q="Warum wollen die Kolkar in Durotar einmarschieren?",a="Die Kolkar sind ein aggressiver, expansiver Zentaurenklan, der in den trockenen Gebieten von Kalimdor beheimatet ist. Sie betrachten die ankommenden Orcs und Dunkelspeer als Eindringlinge, die ihr Territorium und ihre Jagdgründe verletzen.",al={"warum greifen zentauren an","zentauren motiv","kolkar hintergrund"}},{q="Was geschieht, nachdem die Pläne zerstört wurden?",a="Die Zerstörung der Dokumente verhindert eine koordinierte Belagerung, stürzt die taktische Offensive der Kolkar ins Chaos und bewahrt Durotars zerbrechliche Siedlungen vor plötzlicher Verwüstung.",al={"quest nachwirkungen","stoppt der zentaurenangriff"}}},fx={a839716d={q="Warum will Lar Lauerzahn, dass die Angriffspläne zerstört werden?",a="Lar Lauerzahn hat die Kolkarklippe ausgekundschaftet und herausgefunden, dass die Zentauren eine dreizackige Invasion planen, die auf Sen'jin, das Tal der Prüfungen und Orgrimmar selbst abzielt. Obwohl die Horde einen solchen Angriff letztendlich zerschlagen würde, will Lauerzahn ihre Operationspläne verbrennen lassen, um die Invasion zu stoppen, bevor sie beginnt, und den Verteidigern von Durotar unnötiges Blutvergießen und Störungen ersparen.",al={"warum angriffspläne zerstören","lar lauerzahn motiv","warum kolkar-aggressionen vereiteln"}},["4d134dbe"]={q="Wer sind die Kolkar-Zentauren in der Kolkarklippe?",a="Die Kolkar sind ein brutaler Zentaurenclan, der eine Festung in den Klippen entlang des westlichen Bergrückens von Durotar errichtet hat. Sie sind wild und territorial, hegen tiefen Hass auf die neu angekommenen Orcs und Dunkelspeertrolle, starten regelmäßig Überfälle aus ihrem Lager und schmieden Pläne, um die Horde vollständig aus der Region zu vertreiben.",al={"wer sind die kolkar hier","kolkarklippe zentauren","warum sind kolkar in durotar"}}},fp="27,294,18.498.0,20.475.0,49.137.0,55.154.0,29.121.0,49.157.0,41.207.0,43.179.0"}
P.entries["quest:7861"] = {n="GESUCHT: Üble Priesterin Hexx und ihre Diener",s="Primal Torntusk hat befohlen, Vile Priestess Hexx und ihre Diener ihrer gerechten Strafe zuzuführen, und ein stattlicher Preis erwartet jeden, der die Priesterin und ihre elitäre Aman'zasi-Garde bezwingt. Ihr werdet sie auf den Höhen von Jintha'Alor im Hinterland finden.",h="Primal Torntusk hat befohlen, Vile Priestess Hexx und ihre Diener ihrer gerechten Strafe zuzuführen, und ein...",kw={"aman'zasi","hexx","hinterland","jintha'alor","primal torntusk","revantusk","vile priestess hexx","vilebranch"},sec={{t="Ein Schlag gegen Jintha'Alor",b="Primal Torntusk hat befohlen, dass Vile Priestess Hexx und ihre Diener ihrer gerechten Strafe zugeführt werden. Die Ziele sind die Priesterin selbst und die Aman'zasi-Wachen, ihre Elite. Auf den Höhen von Jintha'Alor, im Hinterland, sind sie zu finden. Sobald sie erschlagen sind, erstattet Ihr Torntusk in Revantusk Bericht."}},faq={{q="Wer hat das Kopfgeld auf Vile Priestess Hexx ausgesetzt?",a="Der Ruf zu den Waffen wurde auf Befehl von Primal Torntusk erlassen, und jedem, der die Priesterin und ihre Garde bezwingt, wird ein stattlicher Preis geboten.",al={"wer will hexx tot sehen","wer hat dieses kopfgeld ausgesetzt","questgeber für priesterin hexx"}},{q="Wo sind Vile Priestess Hexx und ihre Wachen zu finden?",a="Sie sind auf den Höhen von Jintha'Alor im Hinterland zu finden.",al={"wo ist hexx","aufenthaltsort von vile priestess hexx","aufenthaltsort der wachen der aman'zasi"}},{q="Wer muss getötet werden, um das Kopfgeld zu erfüllen?",a="Die Priesterin Hexx selbst, zusammen mit ihrer Aman'zasi-Elitegarde der Vilebranch.",al={"ziele des hexx-kopfgelds","wen man für hexx töten muss"}},{q="Wo wird das Kopfgeld abgegeben?",a="Meldet Euch bei Primal Torntusk in Revantusk, sobald die Priesterin und ihre Garde erschlagen sind.",al={"wo man das hexx-kopfgeld abgibt","aufenthaltsort von primal torntusk"}}},fp="43,226,23.300.0,46.131.0,54.51.0,40.83.0,30.90.0"}
P.entries["quest:7862"] = {n="Offener Posten: Wachbefehlshaber von Revantusk",s="Guard Captain Malkhor ist verschollen, und die Wache von Revantusk benötigt einen neuen Hauptmann. Jeder, der den Posten haben möchte, muss Berserker, Shadow Hunter, Blood Drinker und Soul Eater der Vilebranch vernichten und anschließend Primal Torntusk im Hinterland eine Bewerbung überbringen.",h="Guard Captain Malkhor ist verschollen, und die Wache von Revantusk benötigt einen neuen Hauptmann.",kw={"berserker","blood drinker","wachhauptmann","malkhor","revantusk","shadow hunter","soul eater","torntusk","vilebranch"},sec={{t="Ein unbesetzter Posten",b="Ein Ruf zu den Waffen verkündet, dass Guard Captain Malkhor verschollen ist, sodass die Wache von Revantusk wieder einmal ohne Hauptmann dasteht. Wer sie anführen möchte, ist dazu aufgerufen, die im Aushang beschriebene Arbeit zu verrichten und danach eine Bewerbung an Primal Torntusk zu schicken."},{t="Den eigenen Wert beweisen",b="Ein Bewerber soll vier Arten der Vilebranch vernichten: Berserker, Shadow Hunter, Blood Drinker und Soul Eater. Sobald das getan ist, kehrt zu Primal Torntusk in Revantusk zurück."}},faq={{q="Warum ist die Stelle des Guard Captains unbesetzt?",a="Guard Captain Malkhor ging verloren, und laut der Bekanntmachung ist das Amt des Hauptmanns von Revantusk wieder unbesetzt.",al={"warum wachhauptmann offen ist","was ist mit malkhor passiert","wer war vorheriger hauptmann"}},{q="Wer nimmt die Bewerbung entgegen, sobald die Feinde erschlagen sind?",a="Bewerbungen gehen an Primal Torntusk in Revantusk.",al={"bei wem gebe ich das ab","wo bewerbung einreichen","wer beurteilt die bewerber"}},{q="Welche Feinde müssen besiegt werden, um sich zu qualifizieren?",a="Bewerber müssen Berserker, Shadow Hunter, Blood Drinker und Soul Eater der Vilebranch vernichten.",al={"welche vilebranch getoetet werden muessen","stellenausschreibung ziele","wen toete ich fuer wachhauptmann"}}},fp="47,255,13.235.0,13.183.0,42.95.0,56.57.0,42.98.0"}
P.entries["quest:787"] = {n="Die neue Horde",s="Die neue Horde ist eine einleitende Aufgabe im Tal der Prüfungen, die vom Kriegerveteranen Etrigg vergeben wird. Sie weist frische Rekruten an, sich bei Gornek im Höhlenbau zu melden, um ihre Ausbildung zu beginnen. Durch diesen kurzen Ruf teilt Etrigg seinen persönlichen Lebensweg und Thralls richtungsweisende Vision für eine geläuterte Horde.",h="Die neue Horde ist eine einleitende Aufgabe im Tal der Prüfungen, die vom Kriegerveteranen Etrigg vergeben...",kw={"brennende legion","durotar","etrigg","gornek","neue horde","der höhlenbau","thrall","das tal der prüfungen"},ang={["faction:Horde"]="Diese Aufgabe fasst das Gründungsethos von Thralls Herrschaft zusammen: ein vollständiger Bruch mit der dämonischen Knechtschaft zugunsten von Ehre, Überleben und dem Erbe der Ahnen.",["race:Orc"]="Für junge Orcs, die das Tal der Prüfungen betreten, verkörpert Etrigg das lebendige Gedächtnis der tragischen Vergangenheit ihres Volkes und ihrer Erlösung unter Thrall.",["race:Troll"]="Die Dunkelspeere trainieren Seite an Seite mit den Orcs im Tal der Prüfungen, da sie Thralls Vision von gemeinsamem Überleben und Ehre angenommen haben."},sec={{t="Die Rückkehr eines Veteranen",b="Etrigg steht auf Befehl von Kriegshäuptling Thrall im Tal der Prüfungen, um die neuesten Hoffnungsträger der Horde zu beurteilen und anzuleiten. Nachdem er die Alte Horde nach dem Zweiten Krieg desillusioniert von ihrer Verderbnis durch die Brennende Legion verlassen hatte, lebte Etrigg im stillen Exil, bis er von Menschen gefangen genommen wurde. Von Thrall gerettet, entschied er sich zurückzukehren, nachdem er vom Traum des jungen Kriegshäuptlings erfahren hatte: eine ehrenhafte Horde, verwurzelt im Schamanismus der Ahnen und völlig losgelöst von dämonischen Meistern."},{t="Meldung im Höhlenbau",b="Bevor ein Rekrut sich über die rauen Schluchten des Tals der Prüfungen hinauswagen darf, muss er seinen Mut unter Beweis stellen. Etrigg schickt die Neuankömmlinge in die schattige Höhle namens Der Höhlenbau, um mit Gornek zu sprechen. Auch wenn Gornek selten ein Blatt vor den Mund nimmt, was den rohen Zustand der eintreffenden Aspiranten angeht, sorgt seine Aufsicht dafür, dass nur diejenigen in die weiteren Gebiete von Durotar vordringen dürfen, die Disziplin und das Überleben meistern."}},faq={{q="Wer ist Etrigg?",a="Etrigg ist ein alternder Orc-Veteran, der die Verderbnis der Alten Horde unter dem Einfluss der Brennenden Legion aus erster Hand miterlebte. Desillusioniert zog er sich in ein selbstgewähltes Exil in Lordaeron zurück. Nachdem er von Menschen gefangen genommen und anschließend von Thrall befreit worden war, schwor er Thralls neu formierter Horde die Treue und hilft nun dabei, die Rekrutenausbildung im Tal der Prüfungen zu beaufsichtigen.",al={"wer ist etrigg","etrigg hintergrundgeschichte","etrigg lore"}},{q="Warum spricht Etrigg von der „Neuen Horde“?",a="Die ursprüngliche Horde wurde unter dem Einfluss der Brennenden Legion durch dämonische Blutgier manipuliert und versklavt. Thralls Neue Horde wurde geschmiedet, um die dämonische Kontrolle abzuschütteln, die traditionellen schamanistischen Pfade wiederzubeleben und eine ehrenhafte, autonome Zukunft für die Orcs und ihre Verbündeten in Kalimdor aufzubauen.",al={"was ist die neue horde","unterschied zwischen alter und neuer horde","bedeutung neue horde"}},{q="Wo befindet sich Gornek?",a="Gornek ist direkt am Eingang des Höhlenbaus stationiert, der markanten Höhle, die in die nördliche Felswand des Tals der Prüfungen gehauen ist.",al={"wo ist gornek","gornek finden","gornek standort"}},{q="Was geschieht nach der Meldung bei Gornek?",a="Gornek nimmt Euch als einen von Etriggs Rekruten an und gibt Euch Eure ersten Feldaufträge, indem er Euch zur Verteidigung des Tals einsetzt und Eure Bereitschaft prüft, der Horde zu dienen.",al={"folgequest nach die neue horde","was macht gornek","gornek quest"}},{q="Warum ging Etrigg ins Exil?",a="Etrigg verließ die Horde, weil er von der dämonischen Verderbnis und dem sinnlosen Abschlachten angewidert war, die von den Hexenmeistern im Dienste der Brennenden Legion während der früheren Kriege herbeigeführt wurden.",al={"warum ging etrigg fort","etrigg exil grund","etrigg dämonische verderbnis"}},{q="Warum werden Rekruten im Tal der Prüfungen ausgebildet?",a="Das Tal der Prüfungen bietet eine abgelegene, raue Umgebung in Durotar, in der junge Orcs und verbündete Neuankömmlinge unter dem wachsamen Auge erfahrener Ausbilder gefährlichen Bestien und Skorpiden entgegentreten können, bevor sie in die weite Welt hinausziehen.",al={"warum tal der prüfungen","zweck des tals der prüfungen","ausbildung im tal der prüfungen"}}},fx={["42eb0b46"]={q="Warum schickt Euch Etrigg zu Gornek?",a="Kriegshäuptling Thrall hat Etrigg damit beauftragt, die Ausbildung aller neuen Rekruten zu beaufsichtigen, die im Tal der Prüfungen ankommen. Während Etrigg Neuankömmlinge begrüßt und ihnen die Ideale einer von dämonischer Verderbnis befreiten Horde vermittelt, kümmert sich Gornek um die praktischen, handfesten Aufgaben, die notwendig sind, um Euch zu prüfen und abzuhärten. Etrigg schickt Euch zu ihm, damit Eure Prüfung und Ausbildung offiziell beginnen kann.",al={"warum gornek aufsuchen","etrigg motiv","warum bei gornek melden"}}},fp="13,299,18.465.0,20.397.0,15.378.0,44.288.0,24.139.0,39.181.0,23.179.0,49.232.0"}
P.entries["quest:789"] = {n="Stich des Skorpiden",s="Sting of the Scorpid ist eine frühe Prüfung, die Gornek den Rekruten der Horde in The Den im Tal der Prüfungen auferlegt. Novizen werden herausgefordert, giftige Skorpidarbeiter nordwestlich des Lagers zu jagen und zehn Schwänze zurückzubringen, um ihre Kampfbereitschaft zu beweisen. Die Aufgabe dient als entscheidende Lektion darin, Gefahren auf dem Schlachtfeld zu überleben und selbst die kleinsten Widersacher zu respektieren.",h="Sting of the Scorpid ist eine frühe Prüfung, die Gornek den Rekruten der Horde in The Den im Tal der...",kw={"gegengift","durotar","gornek","skorpid","skorpidarbeiter","stich des skorpions","the den","das tal der prüfungen","gift"},ang={["class:Warrior"]="Gornek betrachtet die Skorpidjagd als grundlegende Lektion in kriegerischer Entschlossenheit und erinnert die Krieger daran, dass entschlossene Schläge harte Panzer brechen und dass Arroganz gegenüber kleineren Feinden zur Niederlage führt.",["race:Orc"]="Für junge Orcs, die im Tal der Prüfungen das Erwachsenenalter erreichen (Coming of Age), ist die Jagd auf giftige Skorpide eine wesentliche, von Gornek überwachte Prüfung der Ausdauer und der Aufmerksamkeit auf dem Schlachtfeld.",["race:Troll"]="Dunkelspeertrolle, die an der Seite der Horde im Tal der Prüfungen trainieren, müssen sich ebenfalls im Kampf gegen die heimischen Skorpide beweisen, bevor sie tiefer nach Durotar vordringen."},sec={{t="Trial of the Stinger",b="In der sonnenverbrannten Schlucht des Tals der Prüfungen stellt Gornek neue Rekruten der Horde auf die Probe, indem er sie gegen die einheimische Tierwelt antreten lässt. Die giftigen Skorpide, die den trockenen Boden nordwestlich von The Den durchstreifen, haben erfahrene Krieger und ungeschickte Initianden gleichermaßen gedemütigt. Um ihre Kampftauglichkeit unter Beweis zu stellen, müssen sich junge Streiter in die Felsen wagen, Skorpidarbeiter erschlagen und mit zehn ihrer abgetrennten Schwänze als Beweis ihres Könnens zurückkehren."},{t="Venom and Vigilance",b="Obwohl sie tödlich sind, liefern die giftigen Räuber auch die Rettung für verletzte Initianden. The Den unterhält Vorräte an Gegengift, das direkt aus extrahiertem Skorpidgift gebraut wird, um gefallene Novizen zu behandeln. Abgesehen vom Überleben des Giftes betont Gornek eine grundlegende taktische Wahrheit: Im Chaos der Schlacht ist Arroganz fatal, und selbst der kleinste Feind besitzt genug tödliches Gift, um einen mächtigen Krieger zu Fall zu bringen."}},faq={{q="Wer vergibt Sting of the Scorpid?",a="Gornek, der Kampfmeister, der die Ausbildung der Novizen in The Den im Tal der Prüfungen überwacht, betraut junge Krieger und Abenteurer mit dieser Prüfung.",al={"wer vergibt stich des skorpions","skorpion-questgeber","gornek-quest"}},{q="Wo befinden sich die Skorpide?",a="Skorpidarbeiter hausen in großer Zahl direkt nordwestlich von The Den im Tal der Prüfungen und durchstreifen das karge, rote Schluchtengelände.",al={"wo man skorpide findet","skorpion-standort","tal der prüfungen skorpide"}},{q="Was verlangt Gornek von der Jagd?",a="Gornek fordert zehn Scorpid Worker Tails als greifbaren Beweis dafür, dass ein Rekrut den giftigen Bestien gegenübergetreten ist und siegreich aus dem Kampf hervorging.",al={"was lassen skorpide fallen","skorpion-questgegenstand","skorpionschwänze"}},{q="Wie wird das Gegenmittel für Skorpidgift hergestellt?",a="Das Gegenmittel gegen Skorpidstiche wird direkt aus Gift gebraut, das aus den Stacheln der Kreaturen selbst gewonnen wird. The Den hält reichlich Vorräte bereit, um Novizen zu versorgen, die ihre Beute unterschätzen.",al={"skorpiongift-heilmittel","gegegengift-lore","wie skorpion-gegengift hergestellt wird"}},{q="Welche Lektion sollen die Rekruten nach Gorneks Willen lernen?",a="Gornek nutzt die Jagd, um angehenden Kämpfern beizubringen, dass jeder Gegner, ob groß oder klein, tödliches Potenzial besitzt. Überheblichkeit im Kampf gegen scheinbar unbedeutende Kreaturen kann sich schnell als verhängnisvoll erweisen.",al={"gorneks lektion","warum skorpide jagen","zweck der skorpion-prüfung"}},{q="Bietet Gornek nach dieser Jagd weitere Ausbildung an?",a="Nach der Übergabe der Schwänze erklärt Gornek, dass er Euch in The Den nichts mehr beizubringen hat, und schickt Euch weiter nach Durotar, um Euren Dienst für die Horde fortzusetzen.",al={"was nach stich des skorpions kommt","gorneks nächste quest","lehrt gornek mehr"}}},fp="20,352,20.421.0,19.399.0,33.141.0,31.130.0,39.136.0,46.187.0,47.192.0,51.159.0"}
P.entries["quest:79"] = {n="Die Legende von Stalvan",s="Diese Quest markiert den Moment, in dem sich verstreute Gerüchte über Stalvan Dunstmantel zu einem unleugbaren Beweis für ein brutales Verbrechen verdichten. Schankwart Smitts übergibt seit Langem verborgene schlammverschmierte Tagebuchseiten und verweist den Ermittler direkt an The Night Watch-Kommandantin Althea Schwarzhaupt.",h="Diese Quest markiert den Moment, in dem sich verstreute Gerüchte über Stalvan Dunstmantel zu einem...",kw={"dunkelhain","dämmerwald","schwarzhaupt","untersuchung","dunstmantel","schlammverschmiertes tagebuch","the night watch","smitts","stalvan"},ang={["class:Paladin"]="Lange begrabene Morde ans Licht zu bringen, erfüllt die Berufung eines Paladins und fordert Rechenschaft für unschuldige Leben, die in den Schatten des Dämmerwalds gewaltsam ausgelöscht wurden.",["class:Rogue"]="Das Zusammensetzen von Handschriftproben aus Gasthäusern und verstaubten Truhen spiegelt die geduldige Detektivarbeit wider, die oft nötig ist, um einer schwer fassbaren Beute nachzustellen.",["faction:Alliance"]="Die Untersuchung zeigt, wie sehr die südlichen Gebiete auf umherziehende Helden der Allianz angewiesen sind, um Recht und Ordnung durchzusetzen, wenn die offizielle Unterstützung Sturmwinds gänzlich ausbleibt."},sec={{t="Ein Durchbruch in Dunkelhain",b="Jahrelang blieb das grausame Schicksal einer durchreisenden Adelsfamilie eine unaufgeklärte Tragödie im Dämmerwald. Schankwart Smitts und Marshal Haggard, damals ein Anführer der Wache von Sturmwind, untersuchten seinerzeit den Ort des Massakers und entdeckten eine Handvoll zerrissener, schlammverschmierter Tagebuchseiten. Ohne Handschriftproben oder bestätigende Dokumente blieben die Notizen liegen, unfähig, den Einsiedler, der gerüchteweise in der Wildnis hausen sollte, offiziell zu belasten. Die in Elwynn, Westfall und dem Dämmerwald gesammelten Beweise verbinden die Handschrift schließlich mit Stalvan Dunstmantel und verwandeln das Stadtgeplauder in einen glasklaren Mordfall."},{t="Der Gang zur Wache",b="Dunkelhain lebt unter ständiger Belagerung durch Untote, wilde Bestien und noch schlimmere Schrecken, die durch das düstere Dickicht streifen. Kommandantin Althea Schwarzhaupt hat wenig Geduld für Schauermärchen oder haltlose Verdächtigungen, wenn das Überleben ihrer Stadt am seidenen Faden hängt. Das Überbringen dieser schlammverschmierten Seiten schlägt die Brücke zwischen ruhender Vergangenheit und unmittelbarer militärischer Gerechtigkeit. Konfrontiert mit handfesten Beweisen für ein Massaker auf dem Boden des Dämmerwalds sieht sich The Night Watch endlich gezwungen, Stalvan Dunstmantel nicht länger nur als exzentrischen Eremiten oder Schauergestalt abzutun, sondern als gefährlichen Flüchtigen anzuerkennen, der Vergeltung verlangt."}},faq={{q="Welche Beweise besaß Schankwart Smitts die ganze Zeit über?",a="Vor Jahren schloss sich Smitts Haggard an, um die Ermordung durchreisender Adliger zu untersuchen. Sie bargen damals zerrissene, schlammverschmierte Tagebuchseiten vom Tatort, doch fehlten ihnen bis jetzt passende Handschriftproben, um zu beweisen, dass Stalvan Dunstmantel der Verfasser war.",al={"smitts tagebuchseiten","schlammverschmierte tagebuchseiten","was fand smitts"}},{q="Warum meldete Smitts dies Kommandantin Schwarzhaupt nicht früher?",a="Ohne Beweise, welche die Handschrift auf den schlammverschmierten Seiten mit dem zurückgezogen lebenden Hauslehrer verknüpften, hielten Smitts und Haggard lediglich vage Bruchstücke in den Händen. Kommandantin Schwarzhaupt unbestätigte Gerüchte vorzutragen, wäre als nutzlose Verschwendung der knappen Zeit von The Night Watch abgetan worden.",al={"warum so lange warten","warum die seiten geheim halten","warum sagte smitts der wache nichts"}},{q="Wer ist Kommandantin Althea Schwarzhaupt?",a="Kommandantin Althea Schwarzhaupt ist die Anführerin von The Night Watch, der bedrängten Stadtmiliz, die dafür verantwortlich ist, Dunkelhain zu beschützen und auf den Straßen des Dämmerwalds Patrouille gegen die Untoten und Raubtiere des Waldes zu reiten.",al={"wer ist schwarzhaupt","rolle von althea schwarzhaupt","kommandantin von dunkelhain"}},{q="Welches Massaker fand im Dämmerwald statt?",a="Eine durchreisende Adelsfamilie wurde einige Jahre zuvor im Dämmerwald niedergemetzelt. Während Gerüchte auf ihren ehemaligen Hauslehrer Stalvan Dunstmantel hindeuteten, fehlten den örtlichen Ermittlern zunächst die eindeutigen Beweise, die für eine Anklage erforderlich gewesen wären.",al={"welches massaker","ermordung von adligen","wer wurde ermordet"}},{q="Wie fügt sich dieser Schritt in die Gesamtermittlung ein?",a="Dieser Schritt stellt den Übergang von privaten Nachforschungen zu formeller Justiz dar. Nachdem Ihr Register, Schulunterlagen und Familienkisten in drei Gebieten durchkämmt habt, übergebt Ihr die gesammelten Beweise den örtlichen Behörden, um Maßnahmen gegen Stalvan zu legitimieren.",al={"schritt der stalvan-questreihe","wie weit fortgeschritten ist dies","ist dies das ende der quest"}},{q="Warum zögert The Night Watch so sehr, alte Verbrechen zu untersuchen?",a="Dunkelhain droht tagtäglich die unmittelbare Vernichtung durch umherwandernde Monstrositäten, Worgenrudel und Spinnen. Kommandantin Schwarzhaupt muss jeden verfügbaren Wächter auf das nackte Überleben ansetzen, weshalb ungelöste Altfälle unumstößliche Beweise erfordern, bevor sie Personal entbehren kann.",al={"warum ist schwarzhaupt beschäftigt","verteidigungspriorität von dunkelhain","prioritäten der nachtwache"}}},fx={["3928db26"]={q="Warum will Schankwart Smitts, dass Ihr mit Kommandantin Schwarzhaupt sprecht?",a="Smitts verfolgt die Legende von Stalvan Dunstmantel schon seit Jahren im Stillen, seitdem besuchende Adlige vor Dunkelhain abgeschlachtet wurden. Als er und Haggard damals den grausamen Tatort untersuchten, fanden sie schlammverschmierte Tagebuchseiten, konnten sie aber mangels Handschriftproben nicht mit dem Einsiedler im Wald in Verbindung bringen. Jetzt, da Eure Nachforschungen Proben zutage gefördert haben, die Stalvans Urheberschaft beweisen, besitzt Smitts endlich unwiderlegbare Beweise für die Identität des Mörders. Er möchte, dass Ihr die Wahrheit unverzüglich präsentiert, damit die Verteidiger der Stadt den Mörder offiziell zur Rechenschaft ziehen können.",al={"warum schickt smitts mich zu ebonlocke","schankwart smitts motiv","warum jetzt ebonlocke informieren"}},["225fd2ad"]={q="Warum schickt Smitts Euch, anstatt dies selbst zu melden?",a="Smitts führt die Bar in der Scarlet Raven Tavern und besaß nur ein paar lose Fragmente des ursprünglichen Gemetzels. Ihr seid die Person, die tatsächlich die Spur durch den Wald von Elwynn, Westfall und den Dämmerwald verfolgt und die Briefe und Tagebücher geborgen hat, die die Handschrift mit Stalvan Dunstmantel in Verbindung bringen. Weil Ihr die entscheidenden Hinweise entdeckt habt, die das gesamte Puzzle zusammenfügen, muss Kommandantin Schwarzhaupt den vollständigen Bericht aus erster Hand von der Person hören, die ihn bewiesen hat.",al={"warum spricht smitts nicht mit ebonlocke","warum stalvan-bericht durch mich","warum berichte ich ebonlocke"}}},fp="21,266,27.595.0,22.573.1,51.232.0,61.273.0,34.199.0,37.217.0,56.266.0,62.245.0"}
P.entries["quest:79007"] = {n="... and that note you found",s="'... and that note you found' beginnt an der erlöschenden Glut eines kürzlich verlassenen, mit Vorräten übersäten Lagerplatzes. In der Asche liegt ein versengtes, welliges Pergament mit einem Rätsel über das Finden eines 'Zwillingslandes'. Da keine weiteren Anhaltspunkte übrig sind, bietet der verkohlte Fetzen den einzigen Hinweis auf das, was zurückgelassen wurde.",h="'...",kw={"... and that note you found","verbrannte notiz","verkohlte notiz","glimmende asche","kürzliches feuer","verstreute vorräte","zwillingsland"},sec={{t="Glut in der Wildnis",b="Neben dem verblassenden Glimmen eines kürzlichen Lagerfeuers und verstreuten Vorräten liegt ein beschädigtes, welliges Stück Papier. Wer auch immer hier verweilte, ist vor kurzem aufgebrochen und hinterließ nur abkühlende Glut und ein Pergamentfragment, das den Flammen nur knapp entging. Die Szenerie deutet auf Eile oder eine plötzliche Störung hin, da die Vorräte den Elementen ausgesetzt zurückgelassen wurden."},{t="Ein kryptisches Rätsel",b="Der erhaltene Pergamentfetzen enthält eine einzige rätselhafte Anweisung: 'Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.' Da weder Unterschrift noch Koordinaten oder weiterer Kontext das Feuer überstanden haben, dient der verkohlte Fetzen als einziger Wegweiser für jeden, der darüber stolpert."}},faq={{q="Was steht auf der am Lagerplatz gefundenen Notiz?",a="Die verkohlte, wellige Notiz enthält eine kryptische Botschaft: 'Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.' Sie dient als einziger Hinweis, der am verlassenen Lagerplatz zurückgelassen wurde.",al={"was auf der notiz steht","notiztext","verbrannte notiz"}},{q="Wer hat die Notiz zurückgelassen?",a="Der Verfasser bleibt unbekannt. Sie wurde zwischen verstreuten Vorräten neben der erlöschenden Glut eines kürzlichen Lagerfeuers entdeckt, was darauf hindeutet, dass derjenige, der die Notiz schrieb oder bei sich trug, kürzlich aufbrach oder in aller Eile fliehen musste.",al={"woher die notiz stammt","wer die notiz verfasst hat","wer das feuer entfacht hat"}},{q="Worauf bezieht sich 'das Zwillingsland'?",a="Die Notiz spricht rätselhaft von einem 'Zwillingsland' und weist den Leser an, einen passenden oder gespiegelten Ort zu suchen. Das verkohlte Fragment liefert keine weitere Erklärung, sodass seine Bedeutung für Reisende ein ungelöstes Rätsel bleibt.",al={"was ist zwillingsland","zwillingsland hinweis"}},{q="Wie folgt Ihr den Hinweisen auf der Notiz?",a="Ohne ein klares Ziel auf einer Karte sind die verkohlten Überreste der Notiz Euer einziger Wegweiser. Um ihrem Rätsel zu folgen, müsst Ihr nach einem Land oder Ort suchen, der der kryptischen Beschreibung der Notiz gleicht.",al={"was mit der notiz zu tun ist","wohin diese quest führt"}},{q="Warum wurde der Lagerplatz verlassen?",a="Der Ort weist Anzeichen eines plötzlichen Aufbruchs oder einer Störung auf; verstreute Vorräte blieben neben erlöschender Glut zurück. Außer dem erhaltenen, welligen Papierfetzen sind keine weiteren identifizierenden Ausrüstungsgegenstände oder Spuren vorhanden.",al={"wer die vorräte zurückgelassen hat","verstreute vorräte lagerplatz"}},{q="Gibt es noch andere Hinweise am Feuer?",a="Am Lagerfeuer sind keine weiteren Schriftstücke oder Markierungen intakt geblieben. Die Flammen haben fast alles zerstört und ließen nur das wellige Papierfragment als verbliebenes Zeugnis dessen zurück, wer auch immer dort gerastet hat.",al={"ob das feuer sonst noch etwas enthüllt","lagerplatz hinweise"}}},fp="27,318,18.339.0,16.289.0,45.187.0,25.212.0,35.221.0,40.196.0,31.206.0,38.190.0"}
P.entries["quest:79008"] = {n="... und diese Notiz, die Ihr gefunden habt.",s="Diese versengte Notiz wurde in der Glut eines erlöschenden Lagerfeuers in Westfall entdeckt und hinterlässt einen kryptischen, einsamen Hinweis. Ihre angesengte Botschaft deutet auf ein Ziel hin, das anderswo in der Welt wartet, und fordert jeden, der sie findet, dazu auf, ein „Zwillingsland“ aufzusuchen.",h="Diese versengte Notiz wurde in der Glut eines erlöschenden Lagerfeuers in Westfall entdeckt und hinterlässt...",kw={"versengte notiz","lagerfeuer","verkohlte notiz","glut","notiz","zwillingsland","westfall"},ang={["class:Rogue"]="Das Entziffern kryptischer Hinweise, die an verborgenen Lagerplätzen hinterlassen wurden, liegt all jenen im Blut, die von Gerüchten, Geheimnissen und verborgenen Botschaften leben.",["faction:Alliance"]="Für Abenteurer, die versuchen, die Ordnung in Westfall wiederherzustellen, stellen ein unidentifiziertes Lager und eine rätselhafte Chiffre ein weiteres Mysterium dar, das sich an der Grenze des Königreichs entfaltet."},sec={{t="Ein erlöschendes Feuer",b="Inmitten der verlassenen Felder, geplünderten Gehöfte und windgepeitschten Ebenen von Westfall stoßen Reisende häufig auf die Lager von Landstreichern, Gesetzlosen oder verzweifelten Vagabunden. Doch dieser kleine Lagerplatz wurde in aller Eile oder Heimlichkeit verlassen; seine Vorräte blieben zurück und seine Glut glimmt noch schwach. Inmitten der verstreuten Überreste liegt ein versengter Pergamentstreifen, der die Flammen überstanden hat."},{t="Die kryptische Botschaft",b="Die versengte Notiz trägt nur zwei kurze Sätze: „Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.“ In Geheimnisse gehüllt, dienen die Worte sowohl als rätselhaftes Gleichnis als auch als Einladung, die von den trostlosen Feldern von Westfall weg zu einem anderen Reich weist, das durch Namen, Geografie oder Schicksal verbunden ist."}},faq={{q="Was steht auf der Notiz?",a="Auf der versengten Notiz steht: „Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.“ Sie ist der einzige Hinweis, der an dem verlassenen Lagerplatz zurückgelassen wurde.",al={"notiztext","was steht auf der notiz","worte auf der versengten notiz"}},{q="Wo wird diese Notiz gefunden?",a="Die Notiz wird inmitten der Überreste eines kürzlich erloschenen Feuers und verstreuter Vorräte in der Wildnis von Westfall entdeckt.",al={"fundort der notiz","wo ist die notiz","lagerfeuer standort"}},{q="Wer hat das Lagerfeuer hinterlassen?",a="Der Urheber bleibt unbekannt. Wer auch immer das Feuer entzündete, ist erst vor Kurzem aufgebrochen und hat verstreute Vorräte sowie die versengte Botschaft in der Glut hinterlassen.",al={"wer hat die notiz hinterlassen","lagerfeuer besitzer","verfasser der notiz"}},{q="Worauf bezieht sich „das Zwillingsland“?",a="Die Formulierung ist ein Rätsel, das auf eine andere Region in der Welt verweist, die das Land, in dem sie gefunden wurde, widerspiegelt oder eine Verbindung zu ihm teilt – auch wenn die verkohlte Notiz keine weitere Erklärung liefert.",al={"bedeutung zwillingsland","was ist das zwillingsland","wo ist das zwillingsland"}},{q="Warum wurde die Notiz verbrannt?",a="Die Notiz war in der Glut des Feuers versengt und verkohlt, was darauf hindeutet, dass jemand entweder versucht hat, sie in Eile zu vernichten, oder sie achtlos zurückgelassen hat, als die Flammen erloschen.",al={"warum wurde sie verbrannt","wollte jemand die notiz verbrennen","verkohlte notiz"}},{q="Steht dies in Verbindung mit der Bruderschaft der Defias?",a="Obwohl Westfall von der Bruderschaft der Defias und mittellosen Hausbesetzern überrannt wird, deutet die kryptische Natur der Botschaft auf etwas Geheimnisvolleres hin als gewöhnliche Räubernachrichten.",al={"defias notiz","ist es defias","lagerfeuer der bruderschaft"}}},fp="27,124,12.304.0,19.241.0,23.142.0,25.97.0,22.142.0,35.146.0,24.143.0,44.163.0"}
P.entries["quest:79091"] = {n="Archmage Antonidas: The Unabridged Autobiography",s="Bei dieser Quest geht es darum, die umfassenden persönlichen Memoiren von Erzmagier Antonidas zu bergen, dem verehrten verstorbenen Anführer der Kirin Tor. Dieser seltene Foliant, der ursprünglich in den großen Archiven von Eisenschmiede untergebracht war, bietet unersetzliche Einblicke in die Geschichte von Dalaran und hohe arkane Gelehrsamkeit.",h="Bei dieser Quest geht es darum, die umfassenden persönlichen Memoiren von Erzmagier Antonidas zu bergen, dem...",kw={"antonidas","arkan","erzmagier antonidas","autobiografie","dalaran","hall of explorers","eisenschmiede","kirin tor","library","magier"},ang={["class:Mage"]="Erzmagier Antonidas war einer der bedeutendsten Anführer der Kirin Tor und ein Vorbild arkaner Gelehrsamkeit. Das Studium seines Lebens und seiner persönlichen Schriften bietet unverzichtbare Einblicke für jeden Praktizierenden der arkanen Künste.",["faction:Alliance"]="Antonidas war eine Stütze der Allianz von Lordaeron gegen die Orc-Horde und die Geißel, was seine persönlichen Memoiren zu einem geschätzten historischen Dokument in den gesamten Ländern der Allianz macht.",["race:Dwarf"]="Der Foliant stammt aus der großen Bibliothek in der Hall of Explorers in Eisenschmiede, auch wenn die Gelehrten, die ihn in Empfang nehmen, unbesorgt darüber scheinen, die Zwergenarchivare eines solchen seltenen Bandes zu berauben.",["race:Human"]="Antonidas war ein verehrter menschlicher Erzmagier, der die Kirin Tor und Dalaran durch den Zweiten und Dritten Krieg führte, was seine ungekürzte Autobiografie zu einem kostbaren Stück menschlicher Geschichte macht."},sec={{t="Die Worte des Großmagus",b="Erzmagier Antonidas gehörte zu den brillantesten Köpfen Azeroths und diente über Jahrzehnte als ehrwürdiger Anführer der Kirin Tor und Herrscher von Dalaran. Seine ungekürzte Autobiografie schildert seinen Aufstieg durch die Ränge der Violetten Zitadelle, seine Beherrschung des Arkanen und seine Führung während der stürmischen Epochen des Zweiten und Dritten Krieges. Für Gelehrte und Praktizierende der Magie bieten Antonidas' Erinnerungen aus erster Hand ein unvergleichliches Fenster in Dalarans innere Abläufe und die arkanen Künste."},{t="Aus der Großen Bibliothek von Eisenschmiede",b="Bevor es an seinen neuen Bestimmungsort gelangte, ruhte dieses seltene Manuskript in der großen Bibliothek von Eisenschmiede, wo es neben uralten Titanenrelikten und Zwergengeschichten in der Hall of Explorers aufbewahrt wurde. Die Zwerge besitzen riesige Sammlungen von Texten, die aus Ruinen und fremden Königreichen in ganz Azeroth zusammengetragen wurden, was ihre Archive zu einer Fundgrube für seltene Literatur macht. Doch arkane Gelehrte andernorts brennen darauf, solche Werke für ihre eigenen Sammlungen zu beanspruchen, zuversichtlich, dass die geschäftigen Zwergenarchivare einen einzelnen fehlenden Band niemals bemerken werden."}},faq={{q="Wer war Erzmagier Antonidas?",a="Erzmagier Antonidas war der langjährige Anführer der Kirin Tor und Herrscher des magischen Stadtstaates Dalaran. Als legendärer Meister des Arkanen diente er während des Zweiten Krieges als wichtiger Ratsherr der Allianz von Lordaeron und warnte König Terenas vor der Seuche, bevor er während des Dritten Krieges bei der Verteidigung von Dalaran fiel.",al={"wer war antonidas","erzmagier antonidas lore","antonidas hintergrundgeschichte"}},{q="Was ist die ungekürzte Autobiografie?",a="Es ist die umfassende, ungekürzte Autobiografie, die von Erzmagier Antonidas selbst verfasst wurde und sein Leben, seine Gelehrsamkeit und seine Führung innerhalb von Dalaran beschreibt. Angesichts seines Status als Oberhaupt der Kirin Tor stellen seine persönlichen Schriften ein unschätzbares historisches und magisches Zeugnis dar.",al={"was ist dieses buch","ungekürzte autobiografie buch","antonidas foliant"}},{q="Woher stammte dieses Buch?",a="Der Band wurde aus der Bibliothek in Eisenschmiede beschafft, die in der Hall of Explorers der Zwergenfeste untergebracht ist. Zwergische Forscher und Archivare tragen regelmäßig historische und magische Texte aus den gesamten östlichen Kontinenten zusammen.",al={"woher stammt das buch","kam dies aus eisenschmiede","eisenschmiede bibliotheksbuch"}},{q="Warum wird nach diesem Buch gesucht?",a="Gelehrte und Bibliothekare suchen ständig nach mächtigen oder historischen magischen Texten, um ihre Archive zu erweitern und arkanes Wissen zu bewahren, insbesondere nach Werken legendärer Magier, die andernfalls verloren gehen oder in fremden Sammlungen verborgen bleiben könnten.",al={"warum magische bücher sammeln","wer will antonidas buch","warum will die bibliothek dies"}},{q="Was geschah mit Erzmagier Antonidas?",a="Erzmagier Antonidas kam während des Dritten Krieges ums Leben, als der gefallene Prinz Arthas Menethil und die Geißel in Dalaran einmarschierten. Antonidas errichtete eine mächtige magische Barriere, um die Stadt und ihre Geheimnisse zu verteidigen, doch Arthas durchbrach die Verteidigung und streckte ihn nieder, um das Buch von Medivh an sich zu reißen.",al={"ist antonidas gestorben","wie starb antonidas","was geschah mit antonidas"}},{q="Wird die Bibliothek von Eisenschmiede bemerken, dass das Buch verschwunden ist?",a="Der Empfänger tut jegliche Sorge darüber, dass die Zwerge sein Fehlen bemerken könnten, beiläufig ab und überlegt, dass die weitläufigen Archive von Eisenschmiede groß genug sind, dass ein einzelner fehlender Foliant wahrscheinlich völlig unbemerkt bleibt.",al={"wird eisenschmiede das buch vermissen","diebstahl aus der bibliothek von eisenschmiede"}}},fp="48,290,28.497.0,35.523.0,27.321.0,37.277.0,30.229.0,36.240.0,36.282.0,51.204.0"}
P.entries["quest:79092"] = {n="Archmage Theocritus' Research Journal",s="Archmage Theocritus' Research Journal ist ein arkaner Band, der die Untersuchungen des Meistermagiers des Turms von Azora dokumentiert. Den Gelehrten der Library von Eisenschmiede überbracht, fügt das Tagebuch dem großen Zwergenarchiv wertvolle magische Erkenntnisse hinzu.",h="Archmage Theocritus' Research Journal ist ein arkaner Band, der die Untersuchungen des Meistermagiers des...",kw={"arkanes wissen","erzmagier theocritus","eisenschmiede","library von eisenschmiede","forschungstagebuch","theocritus","turm von azora"},ang={["class:Mage"]="Gelehrte des Arkanen schätzen geborgene Notizen von prominenten Persönlichkeiten wie Erzmagier Theocritus, dessen Forschung dazu beiträgt, historische magische Abhandlungen in den Archiven von Eisenschmiede zu sichern.",["faction:Alliance"]="Die Sicherung seltener Texte und Tagebücher bereichert die große Wissensstätte im Herzen von Eisenschmiede für alle Gelehrten der Allianz."},sec={{t="Feldnotizen eines Meisters",b="Erzmagier Theocritus ist in der gesamten Allianz als geschätzter Zauberkundiger bekannt, der am Turm von Azora in den östlichen Ausläufern des Walds von Elwynn stationiert ist. Über Jahre einsamer Studien hinweg untersuchte Theocritus seltsame Artefakte, Leylinien-Anomalien und nahegelegene magische Bedrohungen und hielt seine Erkenntnisse in detaillierten Tagebüchern fest. Einen solchen Band zu bergen, stellt eine seltene Gelegenheit dar, die persönlichen Beobachtungen eines hochrangigen Erzmagiers der Kirin Tor zu studieren."},{t="Erweiterung der Archive von Eisenschmiede",b="Die Explorers' League und die Hüter der Library von Eisenschmiede unterhalten eine der bedeutendsten Archivsammlungen auf dem Kontinent. Indem Abenteurer Archmage Theocritus' Research Journal in ihre Obhut übergeben, stellen sie sicher, dass seine arkanen Erkenntnisse sicher aufbewahrt und neben den historischen Bänden von Khaz Modan katalogisiert werden. Die Bibliothekare heißen jede weitere magische Entdeckung herzlich willkommen, die ihr kollektives Wissen erweitern kann."}},faq={{q="Was ist Archmage Theocritus' Research Journal?",a="Es ist ein wissenschaftliches Forschungstagebuch des Magiers Erzmagier Theocritus, das bei der Library von Eisenschmiede abgegeben wurde, um arkanes Wissen zu bewahren und die Archive zu erweitern.",al={"theocritus tagebuch abgabe","was ist theocritus tagebuch"}},{q="Wer ist Erzmagier Theocritus?",a="Erzmagier Theocritus ist ein renommierter menschlicher Magier, der im Turm von Azora im Wald von Elwynn lebt und alte magische Störungen und Artefakte erforscht.",al={"wer ist theocritus","erzmagier theocritus lore"}},{q="Wohin wird dieses Tagebuch gebracht?",a="Das Tagebuch wird zu den Archivaren in der Library in Eisenschmiede gebracht, die seltene Dokumente und magische Manuskripte für ihre Sammlung zusammentragen.",al={"wo theocritus tagebuch abgeben","wer will theocritus tagebuch"}},{q="Warum möchte die Library dieses Tagebuch?",a="Die Gelehrten der Library von Eisenschmiede versuchen, arkanes Wissen zu bewahren und seltene Abhandlungen von Meisterzauberern zu studieren, um ihre historischen Aufzeichnungen zu erweitern.",al={"warum magische tagebücher sammeln","zweck von theocritus tagebuch"}},{q="Können weitere magische Werke an die Library geliefert werden?",a="Ja, die Kuratoren ermutigen Abenteurer dazu, weiterhin nach verlorenen magischen Werken und historischen Texten auf der ganzen Welt zu suchen, um ihre Archivsammlung zu unterstützen.",al={"weitere tagebücher zum abgeben","gibt es andere bücher für die library"}},{q="Welche Art von Forschung ist in dem Tagebuch enthalten?",a="Das Tagebuch enthält Notizen und Beobachtungen, die von Erzmagier Theocritus während seiner umfassenden Untersuchungen magischer Phänomene und arkaner Kunde zusammengetragen wurden.",al={"was steht in theocritus tagebuch","inhalt von theocritus tagebuch"}}},fp="37,255,22.448.0,32.432.0,46.166.0,27.149.0,30.146.0,39.157.0,51.154.0,50.151.0"}
P.entries["quest:79093"] = {n="Rumi of Gnomeregan: The Collected Works",s="Rumi of Gnomeregan: The Collected Works beinhaltet das Bergen und Abgeben eines zusammengestellten Bandes gnomischer Schriften, um die Sammlung einer Library zu erweitern. Durch das Überbringen dieser seltenen Texte unterstützen Abenteurer Gelehrte dabei, wertvolles historisches und magisches Wissen vor dem Verlust zu bewahren.",h="Rumi of Gnomeregan: The Collected Works beinhaltet das Bergen und Abgeben eines zusammengestellten Bandes...",kw={"gesammelte werke","gnomeregan lore","gnomische schriften","library","magische werke","rumi of gnomeregan"},ang={["class:Mage"]="Gelehrte des Arkanen schätzen seltene und kuriose Schriften, die aus ganz Azeroth geborgen wurden, insbesondere Werke, die das kollektive Verständnis magischer Theorie und Geschichte erweitern.",["faction:Alliance"]="Die Gelehrten und Kuratoren der Allianz bemühen sich fortwährend darum, wertvolle Literatur und magische Texte für das gemeinsame Wissen der Allianz zu bergen und zu schützen.",["race:Gnome"]="Für Gnome, die ihre Kultur und intellektuellen Errungenschaften nach dem Fall von Gnomeregan bewahren wollen, ist die sichere Archivierung der gesammelten Schriften von Denkern wie Rumi eine lebenswichtige Angelegenheit ihres Erbes."},sec={{t="Bewahrung gnomischen Gedankenguts",b="Rumi of Gnomeregan: The Collected Works stellt ein Bestreben dar, bemerkenswerte gnomische Literatur und intellektuelle Errungenschaften zu bewahren. Nach dem verheerenden Verlust von Gnomeregan an den Troggbefall wurde ein Großteil des schriftlichen Erbes der Gnome zerstreut, verschüttet oder von der Zerstörung bedroht. Gelehrte und Archivare, die in Bibliotheken und Bildungsstätten wirken, suchen aktiv nach überlebenden Manuskripten, Abhandlungen und zusammengestellten Schriften, um sicherzustellen, dass die Weisheit und der Erfindungsreichtum gnomischer Denker nicht der Zeit anheimfallen."},{t="Archivarische Bergung",b="Wenn Abenteurer diese gesammelten Bände im Feld entdecken und den Archiven überbringen, reihen Kuratoren sie eifrig in ihre wachsenden Bestände ein. Archivare betrachten jedes geborgene Manuskript als eine Erweiterung des kollektiven Verständnisses und ermutigen Reisende, weitere magische oder historische Texte herbeizubringen, die sie entdecken. Durch diese Beiträge bleibt das Wissen für Gelehrte, Magier und Historiker zugänglich, die sich darum bemühen, Azeroths wissenschaftliches Vermächtnis zu schützen."}},faq={{q="Was ist Rumi of Gnomeregan: The Collected Works?",a="Rumi of Gnomeregan: The Collected Works ist eine Aufgabe, die das Bergen und Beisteuern einer bemerkenswerten Zusammenstellung gnomischer Schriften umfasst. Ein Abenteurer überbringt diese literarischen Materialien einem Gelehrten, der die Sammlung einer Library aufbaut, um sicherzustellen, dass wertvolles Wissen bewahrt und studiert wird.",al={"rumi of gnomeregan quest","was ist rumi of gnomeregan","wer ist rumi"}},{q="Wo werden diese gesammelten Werke abgeliefert?",a="Die gesammelten Werke werden bei einem Kurator oder Gelehrten abgegeben, der die Sammlung einer Library pflegt. Die Empfänger suchen nach bedeutenden Schriften und magischen Abhandlungen, um ihre Archive zu erweitern.",al={"wo gebe ich werke von rumi ab","wer nimmt rumi-bücher an","rumi-sammlung abgabe"}},{q="Warum möchte die Bibliothek diese gesammelten Werke?",a="Gelehrte und Archivare tragen aktiv seltene Texte, historische Abhandlungen und magische Manuskripte aus aller Welt zusammen, um sicherzustellen, dass grundlegende Forschungsarbeiten bewahrt werden, insbesondere Schriften, die aus Gnomeregan stammen.",al={"warum rumi-bücher sammeln","zweck von rumi of gnomeregan","warum bibliothek rumi will"}},{q="Wer ist Rumi of Gnomeregan?",a="Rumi of Gnomeregan ist ein intellektueller oder magischer Autor, dessen zusammengestellte Schriften von Archivaren gesucht werden. Da Gnomeregan weitgehend überrannt ist, stellen überlebende Sammlungen gnomischen Gedankenguts und Wissens wertvolle Zeugnisse ihrer Gelehrtentraditionen dar.",al={"wer war rumi of gnomeregan","rumi lore","rumi autor"}},{q="Können danach weitere Bücher in die Bibliothek gebracht werden?",a="Ja, die Archivare begrüßen zusätzliche Entdeckungen. Kuratoren ermutigen Abenteurer dazu, weiterhin nach seltenen oder bedeutenden magischen Abhandlungen und historischen Werken zu suchen, die der Sammlung hinzugefügt werden können.",al={"gibt es weitere bücher zu finden","kann ich mehr texte bringen","weitere magische werke bibliothek"}},{q="Wer kann diese Aufgabe abschließen?",a="Die Aufgabe wird von Abenteurern der Allianz übernommen, die Gelehrte beim Schutz historischer und arkaner Literatur unterstützen. Jeder, der diese wertvollen Texte birgt, kann sie den Archiven vorlegen, um die wissenschaftliche Forschung zu unterstützen.",al={"rumi quest voraussetzungen","wer kann werke von rumi abgeben","rumi nur allianz"}}},fp="39,281,26.517.0,17.482.0,48.284.0,42.186.0,48.216.0,26.252.0,52.202.0,27.216.0"}
P.entries["quest:79095"] = {n="The Apothecary's Metaphysical Primer",s="The Apothecary's Metaphysical Primer ist ein spezialisierter magischer Text, der von Kuratoren gesucht wird, um wissenschaftliche Archive zu bereichern. Seine Abgabe hilft dabei, seltene alchemistische und arkane Theorien für Forscher und Zauberwirker zu bewahren.",h="The Apothecary's Metaphysical Primer ist ein spezialisierter magischer Text, der von Kuratoren gesucht wird...",kw={"alchemie","apotheker","unterstadt","library","magische werke","metaphysische fibel","foliant"},ang={["class:Mage"]="Praktizierende der arkanen Künste schätzen metaphysische Fibeln für ihre tiefen Einblicke in magische Theorien, alchemistische Wechselwirkungen und die grundlegenden Gesetze des Zauberwirkens.",["faction:Horde"]="Gelehrte und Abenteurer der Horde unterstützen Owen Thadd in Unterstadt, indem sie seltene Abhandlungen bergen, um die arkanen Bestände der Bibliothek zu verstärken."},sec={{t="Die Erwerbung eines Gelehrten",b="The Apothecary's Metaphysical Primer ist ein wissenschaftlicher Text, der esoterische und magische Prinzipien behandelt. Kuratoren, die ihre Archive erweitern möchten, begrüßen die Übergabe solcher Abhandlungen und fügen die Fibel direkt ihrer Arbeitskollektion magischer Referenzmaterialien hinzu."},{t="Erweiterung der Archive",b="Die Bewahrung spezialisierter Abhandlungen ist für Bibliotheken wie die Sammlung von Owen Thadd in Unterstadt von entscheidender Bedeutung. Durch die Übergabe seltener Fibeln über arkane und alchemistische Theorien tragen Forscher dazu bei, dass seltene metaphysische Erkenntnisse sicher archiviert und für Forscher zugänglich gemacht werden, anstatt in der Wildnis verloren zu gehen."}},faq={{q="Was ist The Apothecary's Metaphysical Primer?",a="The Apothecary's Metaphysical Primer ist ein seltener wissenschaftlicher Text, der von Kuratoren gesucht wird, um ihre Sammlung magischer Literatur zu bereichern und ihr Verständnis der metaphysischen Wissenschaften zu vertiefen.",al={"was ist the apothecaries metaphysical primer","metaphysical primer quest","was ist dieses buch"}},{q="Wer möchte diese Fibel überbracht bekommen?",a="Der Band wird zu Owen Thadd in Unterstadt gebracht, der nach magischen Werken und arkanen Abhandlungen sucht, um das Wissen für Forscher und Zauberwirker zu bewahren.",al={"wer moechte dieses buch haben","wo gebe ich die fibel ab","wer nimmt die fibel an"}},{q="Warum sammelt die Bibliothek solche Werke?",a="Bibliotheken und Archive tragen metaphysische und magische Werke zusammen, um ihren Wissensbestand systematisch zu erweitern und Gelehrte, Alchemisten und Arkanisten beim Studium arkaner Prinzipien zu unterstützen.",al={"warum moechte die bibliothek die fibel","zweck des sammelns der fibel","warum magische buecher sammeln"}},{q="Könnt Ihr der Bibliothek weitere magische Werke bringen?",a="Gelehrte, die mit der Katalogisierung magischer Literatur betraut sind, begrüßen jede weitere arkane und wissenschaftliche Entdeckung, die Ihr macht und die zu ihren Archiven beitragen kann.",al={"gibt es weitere buecher zum abgeben","kann ich andere buecher bringen","weitere bibliotheksbuecher"}},{q="Welche Art von Wissen ist in einer metaphysischen Fibel enthalten?",a="In der magischen Gelehrsamkeit befasst sich die Metaphysik mit der grundlegenden Natur magischer Energien, den unsichtbaren Kräften, die die Realität bestimmen, und der Art und Weise, wie physische Reagenzien mit arkanen Kräften interagieren.",al={"was bedeutet metaphysisch wotlk classic","metaphysik lore wow","was ist apotheker-metaphysik"}},{q="Wer hat The Apothecary's Metaphysical Primer verfasst?",a="Der genaue Apotheker, der das Werk verfasste, wird in den Aufzeichnungen nicht namentlich erwähnt, doch Apotheker und Gelehrte stellen häufig Fibeln zusammen, die praktische Alchemie, Kräutermischungen und mystische Formeln zusammenfassen.",al={"wer schrieb die apothekerfibel","autor der apothekerfibel","wer ist der apotheker"}}},fp="36,212,23.268.0,22.307.0,45.186.0,40.154.0,45.185.0,48.154.0,56.182.0,47.198.0"}
P.entries["quest:79096"] = {n="Ataeric: On Arcane Curiosities",s="Bei Ataeric: On Arcane Curiosities geht es darum, geborgene magische Schriften abzugeben, um die Sammlung eines Gelehrtenarchivs zu erweitern. Durch das Zusammentragen obskurer Texte und Abhandlungen aus dem Feld versuchen Forscher, ihr Verständnis der arkanen Studien zu vertiefen und mystisches Wissen zu bewahren.",h="Bei Ataeric: On Arcane Curiosities geht es darum, geborgene magische Schriften abzugeben, um die Sammlung...",kw={"arkan","arkane kuriositäten","ataeric","library","magische werke","gelehrte"},ang={["class:Mage"]="Magier hegen ein natürliches Interesse an arkaner Forschung, was Beiträge zu wissenschaftlichen Bibliotheken und die Bergung magischer Abhandlungen für ihr Handwerk direkt relevant macht.",["race:Dwarf"]="Zwergische Gelehrte und die Explorers' League legen großen Wert auf das Zusammentragen schriftlicher Aufzeichnungen, Artefakte und esoterischen Wissens."},sec={{t="Bewahrung arkanen Wissens",b="Gelehrte und Archivare in ganz Azeroth verlassen sich auf wandernde Abenteurer, um seltene Wälzer und vergessene Abhandlungen von gefährlichem Boden zu bergen. Bei dieser Aufgabe sucht ein Forscher gezielt nach magischen Schriften, um das Verständnis einer Institution für die arkanen Künste zu erweitern. Jeder geborgene Band hilft dabei, mystische Praktiken zusammenzufügen, die andernfalls verstreut oder verloren bleiben könnten."},{t="Ein wachsendes Archiv",b="Nach Erhalt der Kuriositäten gliedert der Kurator sie direkt in den Bestand des Archivs ein. Anstatt den Erwerb als abgeschlossen zu betrachten, hält die Bibliothek einen ständigen Aufruf für alle weiteren in der Welt entdeckten magischen Schriften aufrecht, um sicherzustellen, dass ihre Sammlung parallel zur laufenden Forschung weiter anwächst."}},faq={{q="Was ist der Zweck dieser Quest?",a="Ataeric: On Arcane Curiosities stellt die Abgabe eines wissenschaftlichen oder magischen Textes an einen Sammler dar, der den Fundus einer Bibliothek an esoterischem Wissen erweitern möchte.",al={"was ist diese quest","ataeric quest","abgabe von arkane kuriositäten"}},{q="Wer sammelt diese arkanen Schriften?",a="Ataeric ist der Verfasser der Abhandlung. Sie wird bei einem Forscher oder Kurator abgegeben, der magische Werke und seltene Bände sammelt, um die Archive einer Library zu bereichern.",al={"wer will das","wer bekommt das buch","wer ist ataeric"}},{q="Welche Bibliothek profitiert von diesen Kuriositäten?",a="Der Text wird gesucht, um eine akademische Sammlung zu erweitern, was der gelehrten Library zugutekommt, die das Werk aufnimmt.",al={"welche bibliothek ist das","wohin kommen diese bücher"}},{q="Gibt es noch weitere magische Werke zu sammeln?",a="Der Gelehrte ermutigt Abenteurer ausdrücklich dazu, alle weiteren magischen Werke herbeizuschaffen, die sie auf ihren Reisen entdecken, um ihren Wissensschatz kontinuierlich zu erweitern.",al={"kann man mehr abgeben","wiederholbare magische werke","mehr bücher für bibliothek"}},{q="Warum sucht die Bibliothek nach arkanen Kuriositäten?",a="Gelehrte suchen fortwährend nach seltenen Abhandlungen, um die Feinheiten des Arkanen besser zu verstehen und historisches, mystisches Wissen zu bewahren.",al={"was erforscht die bibliothek","warum arkane bücher sammeln"}},{q="Warum ist die Bergung arkaner Werke wichtig?",a="Arkane Texte enthalten oft unbeständiges oder obskures Wissen, weshalb ihre Verwahrung und Erforschung in einer eigens dafür vorgesehenen Bibliothek dem Verbleib im Feld vorzuziehen ist.",al={"ist das gefährlich","risiko arkaner magie"}}},fp="30,271,27.371.0,20.321.0,34.164.0,35.154.0,46.110.0,40.169.0,45.136.0,41.165.0"}
P.entries["quest:79097"] = {n="Baxtan: On Destructive Magics",s="Baxtan: On Destructive Magics ist eine wissenschaftliche Abgabe-Quest, bei der ein Abenteurer Baxtans Abhandlung über zerstörerische Zauber bei einem Gelehrten der Library abliefert. Die Bergung solcher Werke hilft den Archivaren der Library dabei, ihr Verständnis unbeständiger arkaner Energien zu erweitern.",h="Baxtan: On Destructive Magics ist eine wissenschaftliche Abgabe-Quest, bei der ein Abenteurer Baxtans...",kw={"arkan","baxtan","buch","zerstörerische magien","library","magie","band"},ang={["class:Mage"]="Wissenschaftliche Abhandlungen über zerstörerische Magie sind von natürlichem Interesse für Magier, die das Gleichgewicht zwischen arkaner Macht und zerstörerischen Kräften studieren.",["class:Warlock"]="Praktizierende, die sich mit unbeständigen oder verbotenen Mächten befassen, erkennen das akademische Interesse an, das Gelehrte daran haben, zerstörerische Arkana zu verstehen.",["faction:Alliance"]="Die Erweiterung des Wissens, das in den Bibliotheken der Allianz aufbewahrt wird, stärkt das wissenschaftliche Fundament der gesamten Allianz."},sec={{t="Ein Wälzer der verheerenden Künste",b="Die Quest steht für die fortwährenden Bemühungen der Gelehrten, arkanes Wissen zu katalogisieren und zu bewahren. Wenn Abenteurer Texte entdecken, die die unbeständige Natur zerstörerischer Magien ergründen, stellt ihre Übergabe in sorgfältige akademische Obhut sicher, dass die Macht und Gefahr solcher Künste verstanden wird, anstatt verloren zu gehen."},{t="Die Pflege des Wissens der Library",b="Die Library dient als Aufbewahrungsort für Geschichte, Wissenschaft und das Arkane. Ihr Gelehrter beaufsichtigt den Erwerb seltener Bände und heißt Reisende willkommen, die vergessene Abhandlungen aus gefährlichen Winkeln der Welt bergen, um das kollektive Wissen der Library zu erweitern."}},faq={{q="Was ist die Quest 'Baxtan: On Destructive Magics'?",a="Diese Quest beinhaltet die Übergabe von Baxtans Abhandlung über zerstörerische Magie an einen Gelehrten der Library und leistet damit einen Beitrag zur Sammlung magischer Werke.",al={"was ist baxtan: on destructive magics","was ist diese quest","baxtan quest"}},{q="Wer ist Baxtan?",a="Baxtan ist der Autor der Abhandlung On Destructive Magics. Der Gelehrte, der sie entgegennimmt, ist derjenige, der bedeutende Wälzer und magische Abhandlungen für die Library sammelt.",al={"wer ist baxtan","baxtan nsc","wo ist baxtan"}},{q="Nach welchen Arten von Büchern sucht Baxtan?",a="Der Gelehrte der Library sucht nach wissenschaftlichen und magischen Werken, die die Sammlung bereichern können, und begrüßt jede weitere Abhandlung über Magie, die in der Welt entdeckt wird.",al={"welche art von büchern möchte baxtan","baxtans büchersammlung","mehr bücher für baxtan"}},{q="Wo landet dieses magische Wissen?",a="Die gesammelten Texte werden in die Sammlung der Library aufgenommen, die sie entgegennimmt, wodurch das Wissen über die arkanen und gefährlichen Künste für Studienzwecke bewahrt wird.",al={"wohin kommt das buch","welche bibliothek","eisenschmiede bibliothekssammlung"}},{q="Warum sammelt die Library Werke über zerstörerische Magie?",a="Gelehrte katalogisieren zerstörerische Magien, um die Gefahren, theoretischen Mechanismen und Erscheinungsformen mächtiger Arkanenergien besser zu verstehen.",al={"warum zerstörerische magie studieren","zerstörerische magien lore"}},{q="Könnt Ihr Baxtan weitere magische Werke bringen?",a="Ja. Der Gelehrte lädt Abenteurer dazu ein, weiterhin alle weiteren magischen Werke zu bringen, die sie entdecken, was auf ein fortlaufendes Bestreben zur Sammlung von Überlieferungen hinweist.",al={"gibt es weitere quests für baxtan","kann man mehr bücher abgeben"}}},fp="29,263,22.297.0,27.261.0,50.141.0,14.166.0,42.158.0,41.150.0,56.138.0,43.141.0"}
P.entries["quest:791"] = {n="Akzeptiert Euer Schicksal",s="Akzeptiert Euer Schicksal ist eine einführende Aufgabe, die von Furl Hohnbraue auf dem Wachturm von Klingenhügel mit Blick auf Klingenhügel angeboten wird. Zu alt, um an vorderster Front zu kämpfen, bittet der vernarbte Veteran junge Abenteurer der Horde darum, Segeltuch von den örtlichen menschlichen und zentaurenhaften Feinden zu erbeuten, damit er Ausrüstung herstellen kann, die ihnen auf ihrer Reise hilft.",h="Akzeptiert Euer Schicksal ist eine einführende Aufgabe, die von Furl Hohnbraue auf dem Wachturm von...",kw={"segeltuchreste","akzeptiert euer schicksal","durotar","furl hohnbraue","kolkar","klingenhügel","wachturm von klingenhügel","tiragarde"},ang={["faction:Horde"]="Jeder junge Soldat in Durotar verlässt sich auf erfahrene Veteranen wie Furl Hohnbraue, die Neuankömmlinge daran erinnern, dass es bedeutet, die Horde zu ehren, jede Pflicht zu erfüllen, die die Heimat erfordert – sei es das Bewachen eines Außenpostens oder das Nähen von Segeltuch.",["profession:Tailoring"]="Furl demonstriert praktische, robuste Grenzland-Schneiderei, indem er weggeworfenes schweres Segeltuch von menschlichen Invasoren und Zentauren-Plünderern in langlebige Wildnis-Überlebensausrüstung verwandelt.",["race:Orc"]="Furl verkörpert die ältere Generation von Orcs, die sich von der dämonischen Verderbnis befreiten, mit Thrall das Meer überquerten und nun ihre letzten Jahre dem Heranwachsen der Zukunft ihrer jungen Nation widmen."},sec={{t="Die Berufung eines Veteranen",b="Furl Hohnbraue ist ein Veteran des Dritten Krieges, der während der Erschließung von Durotar und der verzweifelten Verteidigung am Hyjal an der Seite von Kriegshäuptling Thrall marschierte. Mittlerweile durch Alter und alte Verletzungen verlangsamt, führt er seine Axt nicht mehr im Kampf. Stattdessen hält er vom Wachturm von Klingenhügel aus stetige Wache, schlägt bei Übergriffen Alarm und unterstützt die nächste Generation von Verteidigern."},{t="Erbeutetes Segeltuch",b="Da Alarmrufe mit dem Signalhorn seltener werden, während der Zugriff der Horde auf die Region erstarkt, verbringt Furl seine Stunden damit, praktische Ausrüstung herzustellen. Robustes Segeltuch ist in den trockenen Canyons von Durotar schwer zu finden, wird jedoch sowohl von den Kul Tiranern an der Ostküste als auch von den nomadischen Kolkar-Zentauren, die die Ebenen durchstreifen, im Überfluss mitgeführt. Das Erbeuten von Stoffetzen dieser feindlichen Streitkräfte liefert Furl den nötigen Stoff, um nützliche Taschen für aktive Späher zu nähen."}},faq={{q="Wer ist Furl Hohnbraue?",a="Furl Hohnbraue ist ein alternder Orc-Veteran, der im Wachturm über Klingenhügel stationiert ist. Er kämpfte während der Gründung von Durotar an der Seite von Thrall und stand in den vereinten Reihen, die Archimonde am Hyjal zu Fall brachten. Da er nicht mehr an vorderster Front kämpfen kann, dient er als Ausguck und nutzt seine freie Zeit, um Feldausrüstung für junge Krieger der Horde herzustellen.",al={"wer ist furl","furl hohnbraue hintergrundgeschichte","wer vergibt akzeptiert euer schicksal"}},{q="Wo kann man Segeltuchfetzen in Durotar finden?",a="Segeltuchfetzen werden von den Kul Tiranern gesammelt, die Burg Tiragarde an Durotars Küste besetzen, sowie von den Kolkar-Zentauren, die in den Ebenen lagern. Beide Fraktionen führen schwere gewebte Materialien mit sich, die aus ihren Lagern und Besitztümern geborgen werden können.",al={"wo gibt es segeltuchfetzen","wer droppt segeltuchfetzen","fundorte segeltuchfetzen"}},{q="Wo befindet sich der Wachturm, an dem Furl steht?",a="Furls Wachturm thront auf den hohen felsigen Klippen direkt nordwestlich von Klingenhügel. Ein gewundener Pfad hinter der Siedlung führt hinauf zum Gipfel, auf dem der hölzerne Ausguck steht.",al={"wo ist furl hohnbraue","wachturm von klingenhügel standort","wachturm von klingenhügel finden"}},{q="Was stellt Furl aus den Segeltuchfetzen her?",a="Furl näht die gesammelten Segeltuchfetzen zu einer robusten Mehrzwecktasche zusammen. Für junge Abenteurer, die durch Durotar reisen, ist zusätzlicher Stauraum für Proviant, Rationen und erbeutete Waffen unerlässlich, um in der rauen Wildnis zu überleben.",al={"was stellt furl her","wofür wird das segeltuch gebraucht","belohnung segeltuchfetzen"}},{q="Warum stellt ein alter Krieger Taschen her, anstatt zu kämpfen?",a="Jahrzehnte unerbittlicher Kämpfe haben Furls Körper gezeichnet, sodass er der im Feld geforderten Schnelligkeit und Stärke nicht mehr gewachsen ist. Anstatt seinen Ruhestand zu beklagen, findet er Ehre darin, über Klingenhügel zu wachen und Ausrüstung herzustellen, die jüngere Kämpfer direkt befähigt, das Reich zu verteidigen.",al={"warum schneidert furl","warum bleibt furl im turm","warum kämpft furl nicht"}},{q="In welchem Krieg hat Furl gekämpft?",a="Furl kämpfte während des Dritten Krieges unter Kriegshäuptling Thrall und nahm an der Besiedlung von Durotar sowie der entscheidenden Schlacht um den Hyjal gegen die Brennende Legion teil. Stolz erinnert er sich daran, dem Kriegsschrei während des vorübergehenden, notwendigen Waffenstillstands zwischen der Horde, den Nachtelfen und der Allianz gefolgt zu sein, um Archimonde zu besiegen.",al={"furls schlachtengeschichte","was hat furl früher getan","archimonde furl"}}},fp="17,302,19.390.0,16.458.0,22.359.0,44.251.0,46.190.0,44.239.0,56.310.0,27.327.0"}
P.entries["quest:79192"] = {n="Trittsteine",s="Trittsteine ist eine Untersuchung, die durch eine verwitterte Notiz ausgelöst wird, welche in der rauen Wildnis des Brachlands angeschlagen ist. Das bekritzelte Pergament besagt, dass zwei Kuriere Lieferungen für die Neue Seuche transportiert hätten, und bezeichnet ihr Schicksal als einfache Apothekerunfälle. Der mysteriöse Verfasser drängt jeden, der sie findet, dazu, eine abgelegene Bergzuflucht an der Grenze zu Desolace aufzusuchen.",h="Trittsteine ist eine Untersuchung, die durch eine verwitterte Notiz ausgelöst wird, welche in der rauen...",kw={"desolace","söldner","berge","neue seuche","notiz","königliche apothekervereinigung","trittsteine","brachland"},ang={["class:Rogue"]="Das Aufspüren anonymer Informanten und das Überprüfen verdeckter Treffpunkte in der Abgeschiedenheit zwischen Desolace und dem Brachland ist für jene, die mit Dolchen und Geheimdienstberichten handeln, zur zweiten Natur geworden.",["faction:Horde"]="Wanderer der Horde im Brachland müssen entscheiden, ob Geflüster über tödliche Seuchenlieferungen auf dem Boden Kalimdors eine Bedrohung für ihre Ländereien und Bündnisse darstellt.",["race:Undead"]="Für Reisende der Verlassenen ist jede unerlaubte Erwähnung der Königlichen Apothekervereinigung und ihrer Seuchenforschung eine dringende Sicherheitsangelegenheit – oder eine gefährliche Verschwörung aus den eigenen Reihen."},sec={{t="Eine Notiz in der Wildnis",b="Wahllos an eine Holzplanke in einem abgelegenen Lager geheftet, sticht die Botschaft inmitten der unbarmherzigen Elemente des Brachlands hervor. Lagerplätze wie dieser erleben oft einen stillen Wechsel von Söldnern, Halsabschneidern und Herumtreibern, die weit entfernt von den neugierigen Blicken des Wegekreuzes oder Ratschets vorübergehend Schutz suchen. Die zerrissene Notiz durchbricht augenblicklich das alltägliche Gerede der Wildnis und bietet eine Einladung voller Intrigen und finsterer Untertöne."},{t="Geflüster über die Neue Seuche",b="Der Verfasser der Notiz berichtet, dass zwei Agenten Lieferungen für die Neue Seuche transportiert hätten, und bezeichnet ihr Schicksal als einfache Apothekerunfälle. Kuriere, die hochgradig flüchtige Seuchenmittel durch Kalimdor schmuggeln, gehen immense Risiken ein, und der Verfasser bietet ein lauschiges Plätzchen in den Bergen zwischen dem Brachland und Desolace als sicheren Ort für ein Gespräch an."}},faq={{q="Wovon handelt die in Trittsteine gefundene Notiz?",a="Die Notiz enthüllt, dass Kuriere, die mit der Neuen Seuche der Verlassenen verknüpfte Materialien transportierten, ein plötzliches Ende fanden. Der Verfasser nennt dies einfache Apothekerunfälle, bietet jedoch einen Treffpunkt in den Bergen an, um die Angelegenheit in Sicherheit zu besprechen.",al={"trittsteine notiz","worum geht es in der notiz","trittsteine questtext"}},{q="Wohin führt Euch die Notiz?",a="Der Verfasser lädt den Leser zu einem versteckten Lager hoch in den Bergen ein, die das Brachland und Desolace voneinander trennen – weit abseits der regulären Patrouillenrouten und Handelswege.",al={"wohin gehen bei trittsteine","lauschiges plätzchen berge","trittsteine standort"}},{q="Was ist die im Brief erwähnte Neue Seuche?",a="Die Neue Seuche ist das tödliche Gebräu, das in Unterstadt von der Königlichen Apothekervereinigung der Verlassenen entwickelt wird. Bestimmt dazu, sowohl die Geißel als auch lebende Feinde auszulöschen, sind ihre Erprobung und die Kurierreisen über die Kontinente von großer Geheimhaltung und tödlicher Gefahr geprägt.",al={"was ist die neue seuche","königliche apothekervereinigung seuche","apotheker lieferungen"}},{q="Wer hat die an der Planke befestigte Notiz geschrieben?",a="Die Botschaft wurde anonym an einer groben Holzplanke in einem abgelegenen Lager hinterlassen. Der Verfasser wird nicht namentlich genannt und bietet lediglich ein lauschiges Plätzchen in den Bergen zwischen dem Brachland und Desolace als sicheren Ort für ein Gespräch an.",al={"wer schrieb die notiz","trittsteine verfasser","wer wartet in den bergen"}},{q="Warum sollten Kuriere der Verlassenen in Kalimdor sein?",a="Apotheker der Verlassenen sammeln häufig exotische Gifte, Sporen und Reagenzien von der rauen Flora und Fauna in ganz Kalimdor und koordinieren Lieferungen über Außenposten der Horde sowie Routen durch die Wildnis.",al={"verlassene im brachland","warum neue seuche in kalimdor","apotheker im brachland"}},{q="Warum werden für solche Notizen abgelegene Lager genutzt?",a="Das Brachland ist weitläufig und außerhalb der größeren Siedlungen kaum kontrolliert. Neutrale Wegstationen, Rastplätze für Söldner und Lager Gesetzloser ermöglichen es Reisenden, Schmugglern und Informanten, diskrete Botschaften zu hinterlassen, ohne die Aufmerksamkeit der Horde oder regionaler Wachposten auf sich zu ziehen.",al={"abgelegenes lager lore","söldnerlager brachland"}}},fp="15,374,19.427.0,26.331.1,56.229.0,35.175.0,47.261.0,39.206.0,51.192.0,51.273.0"}
P.entries["quest:792"] = {n="Üble Familiare",s="Üble Familiare ist eine frühe Aufgabe, die Zureetha Fernblick neu eingetroffenen Recken im Tal der Prüfungen erteilt. Während sie die Prüfungen des Tals überwachte, entdeckte Zureetha einen heimtückischen Koven der Burning Blade, der sich in einer nahe gelegenen Höhle versteckt hält. Um deren plötzlicher Ausbreitung Einhalt zu gebieten, werden Rekruten ausgesandt, um die dämonischen Familiare zu jagen, die in die rote Erde von Durotar vordringen.",h="Üble Familiare ist eine frühe Aufgabe, die Zureetha Fernblick neu eingetroffenen Recken im Tal der Prüfungen...",kw={"burning blade","koven der brennenden klinge","durotar","wichtel","der höhlenbau","das tal der prüfungen","üble familiare","zureetha fernblick"},ang={["class:Warlock"]="Hexenmeister der Orcs und Trolle müssen sich der Realität abtrünniger Schattenwirker stellen, die dämonische Pakte zur Zerstörung missbrauchen, anstatt Teufelsenergien für das Überleben der Horde zu bändigen.",["faction:Horde"]="Die Burning Blade stellt eine der unmittelbarsten internen Bedrohungen für Durotar dar, da sie versucht, die junge Horde von innen heraus zu zersetzen, bevor diese ihre Souveränität fest etablieren kann.",["race:Orc"]="Für Orcs, die sich darum bemühen, Thralls Absage an die dämonische Sklaverei zu ehren, ist das Auffinden von Teufelsverderbnis auf ihrem heiligen Übungsgelände eine bittere Erinnerung daran, dass das Erbe des Schattenrats noch immer schwelt."},sec={{t="Ein Schatten im Tal",b="Das Tal der Prüfungen soll ein Übungsgelände sein, auf dem junge Orcs und Dunkelspeer ihre Stärke, Disziplin und Loyalität zu Thralls Horde unter Beweis stellen. Es sollte Rekruten eigentlich gegen einheimische Raubtiere wie Skorpide und Eber auf die Probe stellen, nicht gegen dämonische Verderbnis. Doch verborgen in einer Höhle im Nordosten haben Agenten, die sich Burning Blade nennen, direkt vor den wachsamen Augen der Aufseher des Tals einen geheimen Koven errichtet."},{t="Das Ausdünnen der Wichtel",b="Zureetha Fernblick, eine Ausbilderin, die entsandt wurde, um Neuankömmlinge nahe dem Höhlenbau anzuleiten, bemerkte die feine Verderbnis, noch bevor sie die Schlucht überwältigen konnte. Geringere dämonische Kreaturen, bekannt als Üble Familiare, strömen aus dem Höhleneingang, schleudern Feuer und bedrohen jeden, der sich zu nah heranwagt. Bevor die Horde die im Verborgenen lauernden Meister ausmerzen kann, erhalten junge Rekruten den Auftrag, diese niederen Diener niederzustrecken, um das Tal zu sichern."}},faq={{q="Wer vergibt die Quest Üble Familiare?",a="Zureetha Fernblick vergibt die Quest. Sie ist direkt vor dem Eingang zum Höhlenbau im Zentrum des Tals der Prüfungen stationiert.",al={"üble familiare questgeber","wer gibt üble familiare","wo man üble familiare annimmt"}},{q="Was sind Üble Familiare?",a="Üble Familiare sind kleine, wichtelartige dämonische Kreaturen, die von den Kultisten der Burning Blade beschworen und gebunden wurden. Sie dienen als geringe Diener und Haustiere, die mit Feuer nach Eindringlingen werfen.",al={"was sind üble familiare","üble familiare lore","üble familiare mobtyp"}},{q="Wo befindet sich der Koven der Brennenden Klinge?",a="Der Koven schmiegt sich in eine Höhle im Nordosten des Tals der Prüfungen, jenseits der umherstreifenden Mottled Boars und Scorpid Workers.",al={"koven der burning blade ort","wo ist koven der burning blade","höhle im tal der prüfungen"}},{q="Warum befindet sich die Burning Blade im Tal der Prüfungen?",a="Die Burning Blade ist ein verdeckt operierender Kult, der sich der Untergrabung von Thralls neuer Horde und der Verbreitung dämonischer Verderbnis verschrieben hat. Die Infiltration des Tals der Prüfungen erlaubt es ihnen, im Verborgenen zu lauern und die jüngste Kämpfergeneration der Horde zu bedrohen.",al={"warum ist die burning blade hier","motive der burning blade","was will die burning blade"}},{q="Was geschieht nach dem Abschluss von Üble Familiare?",a="Sobald die Familiare vor der Höhle dezimiert wurden, schickt Euch Zureetha Fernblick in die Höhle hinein, um dem Anführer des Kults entgegenzutreten und ein Medaillon der Brennenden Klinge zu bergen.",al={"folgequest üble familiare","was kommt nach üble familiare","quest medaillon der burning blade"}},{q="Muss ich tief in die Höhle hineingehen, um die Familiare zu finden?",a="Nein. Obwohl sie im Inneren der Höhle hausen, wimmelt es vor dem Eingang und auf dem Boden der Schlucht direkt vor der Höhlenmündung von Üblen Familiaren.",al={"sind üble familiare in der höhle","wo üble familiare töten","üble familiare farmen"}}},fx={edfaf791={q="Warum will Zureetha Fernblick, dass die Vile Familiars getötet werden?",a="Zureetha Fernblick kam in das Tal der Prüfungen, um neue Rekruten anzuleiten, entdeckte aber eine wachsende Verderbnis direkt vor der Haustür der Horde. Der geheime Koven der Brennenden Klinge hat in den nahegelegenen Höhlen einen versteckten Koven errichtet, und ihre beschworenen Wichtel breiten sich über das ganze Tal aus. Um die Prüfungsgründe zu schützen und die dämonische Verderbnis zu tilgen, bevor sie sich weiter ausbreitet, muss sie deren Vorhut beseitigen.",al={"warum vile familiars töten","zureetha fernblick motivation","warum will zureetha die vile familiars tot sehen"}},["67a24c10"]={q="Warum schickt Euch Zureetha, anstatt sich selbst um die Vertrauten zu kümmern?",a="Ihr seid im Tal der Prüfungen, um Euch als würdig zu erweisen, der Horde zu dienen. Während Zureetha die Reaktion gegen die geheimen Kultisten koordiniert und außerhalb von The Den Wache hält, dient Euer Entsenden einem doppelten Zweck: Es schränkt den dämonischen Befall ein, der das Tal bedroht, und dient gleichzeitig als wichtige Feuertaufe gegen die dunkleren Mächte, die Euer Volk untergraben.",al={"warum schickt sie mich","warum kämpft zureetha nicht selbst","warum muss ich die familiars töten"}}},fp="14,360,22.441.0,16.434.0,35.126.0,24.175.0,41.139.0,49.232.0,45.174.1,57.140.0"}
P.entries["quest:79236"] = {n="Cherry for Your Thoughts?",s="In Beutebucht sucht eine Söldnerin namens Tokal nach einem Getränk im Austausch für die Wahrheit hinter den jüngsten Angriffen auf Außenposten von Menschen und Zwergen. Während Gerüchte mit dem Finger auf die Horde zeigen, beharrt Tokal darauf, dass ihre Gruppe im Rahmen eines privaten Söldnervertrags handelte.",h="In Beutebucht sucht eine Söldnerin namens Tokal nach einem Getränk im Austausch für die Wahrheit hinter den...",kw={"beutebucht","kirschen für eure gedanken","kirschgrog","marschall","söldner","plünderung","privatauftrag","tokal"},ang={["faction:Alliance"]="Mitglieder der Allianz werden mit Interesse vernehmen, dass die Angreifer, die Lager von Menschen und Zwergen heimsuchten, nicht unter der Autorität der Horde handelten, sondern von einem privaten Auftraggeber angeworben wurden.",["faction:Horde"]="Abenteurer der Horde können in Tokals Geständnis Genugtuung finden, das klarstellt, dass die gegen Lager der Allianz verübten Angriffe private Söldnerverträge und keine offizielle Aggression der Horde waren."},sec={{t="Das Geflüster in Beutebucht",b="Im geschäftigen Hafen von Beutebucht hält sich eine Person namens Tokal bedeckt und hält Ausschau nach den Gesetzeshütern. Eine Reihe aggressiver Überfälle verwüstete kürzlich Lager von Menschen und Zwergen, was Gerüchte nährte, die Horde habe die Angriffe inszeniert. Wenn sich ihr Reisende nähern, die eindeutig nicht für den ermittelnden Marschall arbeiten, widerspricht Tokal der weit verbreiteten Darstellung rasch und bietet im Austausch für ein Getränk eine andere Version der Ereignisse an."},{t="Private Söldner",b="Tokal räumt bereitwillig ein, an der Plünderung von Außenposten von Menschen und Zwergen beteiligt gewesen zu sein, bestreitet jedoch entschieden, dass die Überfälle im Namen der Horde verübt wurden. Stattdessen behauptet sie, ihre Bande habe unter einem privaten Vertrag für eine ungenannte dritte Partei gehandelt. Bevor sie den vollständigen Bericht darüber enthüllt, wer die Operation finanzierte und warum, besteht sie darauf, dass man ihr einen erfrischenden Kirschgrog bringt."}},faq={{q="Wer ist Tokal?",a="Tokal ist eine Agentin oder Söldnerin, die im Piratenhafen von Beutebucht Zuflucht gesucht hat. Angesichts der Nachforschungen zu den jüngsten Überfällen auf Siedlungen der Menschen und Zwerge bietet sie jedem, der bereit ist, ihr einen Kirschgrog zu kaufen, an, die ganze Geschichte darüber zu erzählen, für wen sie gearbeitet hat.",al={"wer ist tokal","tokal beutebucht","kirschgrog questgeber"}},{q="Warum möchte Tokal einen Kirschgrog?",a="Tokal zögert, die heiklen Einzelheiten ihrer früheren Verträge preiszugeben, solange sie auf dem Trockenen sitzt. Ihr einen Kirschgrog zu spendieren, lockert ihre Zunge und veranlasst sie zu erklären, wer die Überfälle gegen die Lager der Allianz privat finanzierte.",al={"warum kirschgrog kaufen","kirschgrog tokal","was will tokal"}},{q="War die Horde für die Plünderung der Lager der Menschen und Zwerge verantwortlich?",a="Laut Tokal wurden die Überfälle auf die Lager der Menschen und Zwerge nicht von der Horde befohlen. Während Gerüchte behaupteten, die Horde sei verantwortlich gewesen, beharrt sie darauf, dass ihre Gruppe unter einem privaten Söldnervertrag arbeitete.",al={"wer heuerte tokal an","griff horde allianz-lager an","steckte horde hinter den überfällen"}},{q="Warum sorgt sich Tokal wegen eines Marschalls?",a="Tokal fürchtet die Verfolgung durch einen Marschall, der die Plünderung von Siedlungen der Menschen und Zwerge untersucht. Sie achtet sorgfältig darauf, dass jeder, der sich ihr in Beutebucht nähert, kein Agent ist, der geschickt wurde, um sie vor Gericht zu bringen.",al={"wer ist der marschall","versteckt sich tokal vor dem marschall","marschall sucht tokal"}},{q="Woher bekommt Ihr Kirschgrog für Tokal?",a="Kirschgrog ist ein Getränk, das von Tavernenwirten und Barkeepern in Beutebucht bezogen werden kann. Tokal einen Humpen dieses Getränks zu bringen, erfüllt ihre Forderung und bewegt sie dazu, ihre Geschichte preiszugeben.",al={"wo gibt es kirschgrog","kirschgrog fundort","beutebucht grog"}},{q="Warum hält sich Tokal in Beutebucht auf?",a="Beutebucht dient als neutraler Freibeuterhafen außerhalb der strikten Gerichtsbarkeit sowohl der Allianz als auch der Horde. Für eine Söldnerin, die nach der Plünderung von Lagern der Menschen und Zwerge untertaucht, bietet sie ein ideales Versteck.",al={"warum ist tokal in beutebucht","tokal versteck"}}},fp="25,253,25.465.0,19.385.1,13.261.0,34.209.0,68.211.0,37.204.0,39.194.0,34.217.0"}
P.entries["quest:793"] = {n="Zerbrochene Allianzen",s="Gorn schickt Euch in die Lethlorklamm im äußersten Osten des Ödlands, wo die schwarzen Drakes Blacklash und Hematus durch das Seal of the Earth gebunden liegen. Dies folgt auf das erste Broken Alliances.",h="Gorn schickt Euch in die Lethlorklamm im äußersten Osten des Ödlands, wo die schwarzen Drakes Blacklash und...",kw={"schwarzer drachenschwarm","blacklash","schwarzfelsorcs","gorn","hematus","die lethlorklamm","siegel der erde","zeichen der erde"},sec={{t="Drei Runensteine",b="Drei Runensteine halten das Seal of the Earth verschlossen. Jeder ruht in einer Säule der Lethlorklamm: Diamant, Opal und Amethyst. Das Zeichen der Erde, das Gorn Euch gibt, zieht die Steine hervor und öffnet das Siegel. Zahllose Drakes haben sich in der Klamm niedergelassen, und Blacklash und Hematus sind furchterregend. Gorn will beide tot sehen und verlangt die Rückbringung ihrer Fesseln."},{t="Was Gorn daraus schließt",b="Gorn sagt, der Schwarze Drachenschwarm sei nach wie vor mit den abtrünnigen Schwarzfelsorcs verbündet, und sowohl Drachen als auch Orcs müssten gezügelt oder vertrieben werden. Sobald Blacklash und Hematus tot sind, kann die Horde ihren Blick nach Westen zur Schwarzfelsspitze richten."}},faq={{q="Wer vergibt diese Quest?",a="Gorn vergibt sie als nächsten Schritt nach dem ersten Broken Alliances.",al={"broken alliances questgeber","gorn aufenthaltsort","wer gibt broken alliances"}},{q="Wo befindet sich die Lethlorklamm?",a="Reist an das äußerste östliche Ende des Ödlands. Zahllose Drakes haben sich in der Klamm niedergelassen.",al={"die lethlorklamm lage","wie man zur lethlorklamm gelangt","wo ist die lethlorklamm"}},{q="Wie befreit Ihr Blacklash und Hematus?",a="Das Zeichen der Erde zieht aus jeder der drei Säulen einen Runenstein hervor. In das Seal of the Earth eingesetzt, befreien diese Steine beide Drakes.",al={"wie man blacklash beschwört","siegel der erde","säulen aus diamant opal amethyst"}},{q="Was muss zu Gorn zurückgebracht werden?",a="Die Fesseln von Blacklash, die Ketten von Hematus und das Zeichen der Erde, sobald beide Drakes tot sind.",al={"broken alliances abgabegegenstände","was gorn zurückhaben will","fesseln von blacklash"}}},fp="16,183,16.352.0,21.238.1,21.65.0,32.94.0,38.136.0,34.102.0"}
P.entries["quest:794"] = {n="Medaillon der Brennenden Klinge",s="Diese von der Hexenmeisterin Zureetha Fernblick vergebene Aufgabe führt junge Initianden der Horde tief in die Höhle vom Koven der Brennenden Klinge im Tal der Prüfungen. Dort müssen die Spieler einen verborgenen Kultisten stellen und ein Artefakt dunkler Magie namens Medaillon der Brennenden Klinge bergen. Die Mission enthüllt, dass dämonische Verderbnis direkt vor den Augen der Horde Wurzeln schlägt.",h="Diese von der Hexenmeisterin Zureetha Fernblick vergebene Aufgabe führt junge Initianden der Horde tief in...",kw={"burning blade","koven","durotar","medaillon","der höhlenbau","das tal der prüfungen","hexenmeister","yarrog baneshadow","zureetha fernblick"},ang={["class:Shaman"]="Die Bergung des verdorbenen Relikts hilft Zureetha Fernblick dabei, dämonische Verderbnis aufzudecken, die das Land von Durotar besudelt.",["class:Warlock"]="Die Konfrontation mit Yarrog dient als drastische Mahnung an die Gefahren unkontrollierter Dämonenanbetung abseits der gebilligten, sorgsam gehüteten Pakte unter Thralls Herrschaft.",["faction:Horde"]="Die Mission stellt die letzte Prüfung für junge Rekruten dar und besiegelt ihre Reife, in die weite Wildnis von Durotar aufzubrechen, um die junge Nation zu verteidigen.",["race:Orc"]="Die Jagd auf Yarrog Baneshadow verdeutlicht den inneren Kampf der neuen Horde, den anhaltenden dämonischen Makel der alten Pfade direkt in ihren Ausbildungsstätten auszumerzen."},sec={{t="Eine verborgene Bedrohung im Tal",b="Während junge Orcs und Trolle im Tal der Prüfungen grundlegende Prüfungen des Kampfes und Überlebens bestehen, lauert eine heimtückische Bedrohung in den Schatten. Durch ihre Weissagungen spürt die Hexenmeisterin Zureetha Fernblick, dass die üblen Familiare, die die nördlichen Klippen heimsuchen, lediglich die Vorhut einer dunkleren Präsenz sind. Tief in einer nahen Höhle hat der Kult der Burning Blade einen geheimen Koven errichtet, der dunkle Künste praktiziert und gefährliche Relikte dämonischer Macht birgt."},{t="Die Konfrontation mit Yarrog Baneshadow",b="Das Medaillon selbst befindet sich in den Klauen von Yarrog Baneshadow, einem Orc-Hexenmeister, der als Agent der Burning Blade agiert. Verborgen auf einem erhöhten Felsvorsprung tief im unterirdischen Bau befehligt Yarrog Teufelsbestien und dunkle Magie, fernab der wachsamen Blicke der Aufseher des Tals. Ihn niederzustrecken und das Medaillon an sich zu nehmen, zerschlägt die lokale Führung des Kults, bevor sich ihre Rituale weiter ins Herz von Durotar ausbreiten können."},{t="Der verbleibende Schatten",b="Die Sicherung des Talismans bestätigt Zureetha Fernblicks schlimmste Befürchtungen. Auch wenn der Koven im Tal der Prüfungen zerschlagen wurde, ist das Medaillon der Beweis dafür, dass die Burning Blade mit System und Absicht vorgeht. Der Einfluss des Kults reicht weit über das Ausbildungsgelände hinaus – ein Zeichen dafür, dass sich die heranwachsende Horde noch weitaus größeren dämonischen Verschwörungen in ganz Durotar stellen muss."}},faq={{q="Wo finde ich den Koven der Brennenden Klinge?",a="Der Koven der Brennenden Klinge befindet sich in einer Höhle in den Klippen nördlich und westlich vom Höhlenbau im Tal der Prüfungen, umgeben von wichtelartigen üblen Familiaren.",al={"ort der kovenhöhle","wo ist die höhle","burning blade höhle tal der prüfungen"}},{q="Wer hat das Medaillon der Brennenden Klinge bei sich?",a="Das Medaillon wird von Yarrog Baneshadow getragen, einem abtrünnigen Orc-Kultisten tief in der Höhle, der sich auf einem erhöhten Felsvorsprung hinter einem seichten Wasserbecken aufhält.",al={"wer droppt das medaillon","yarrog baneshadow","medaillon mob"}},{q="Was ist die Burning Blade?",a="Die Burning Blade ist ein verräterischer Kult teufelsverderbter Orcs und Hexenmeister, die sich dämonischen Mächten verschrieben haben und aus verborgenen Höhlen und Lagern aktiv gegen Thralls neue Horde konspirieren.",al={"wer ist die burning blade","burning blade kult","was ist die burning blade"}},{q="Warum ist das Medaillon so wichtig für Zureetha Fernblick?",a="Zureetha hat das Medaillon durch ihre Weissagungen erspäht. Es dient als Machtgegenstand, der die dunklen Rituale des Kults speist, und liefert den unumstößlichen Beweis dafür, dass dämonische Agenten das Tal der Prüfungen infiltrieren.",al={"warum will zureetha es","was ist das medaillon","zureetha fernblick medaillon"}},{q="Bedeutet Yarrogs Niederlage das Ende des Kults in Durotar?",a="Nein. Während Yarrogs Ableben die Höhle im Tal der Prüfungen säubert, warnt Zureetha davor, dass dieser Koven nur eine kleine Zelle darstellt und die Burning Blade weit größere Pläne für Durotar verfolgt.",al={"ist die burning blade vernichtet","sind sie fort","nach medaillon der burning blade"}},{q="Was geschieht nach Abgabe des Medaillons?",a="Nachdem Ihr Euren Wert durch das Töten von Yarrog und die Bergung des Relikts bewiesen habt, werdet Ihr als bereit angesehen, das Tal der Prüfungen zu verlassen, und erhaltet die Anweisung: Bericht erstatten in Sen'jin an der Südküste Durotars.",al={"folgequest","was kommt danach","nach dieser quest"}}},fx={["29893710"]={q="Wofür ist das Medaillon der Brennenden Klinge?",a="Durch ihre Weissagungen identifizierte Zureetha Fernblick das Medaillon als ein mächtiges Objekt schwarzer Magie, das tief im Koven der Brennenden Klinge aufbewahrt wird. Es befindet sich im Besitz von Yarrog Baneshadow und dient als Artefakt dämonischer Macht und als Emblem des bleibenden Einflusses des Schattenrates direkt vor der Haustür der Horde.",al={"zweck des medaillons der brennenden klinge","was bewirkt das medaillon der brennenden klinge","warum ist das medaillon mächtig"}}},fp="23,363,29.453.0,29.434.1,20.361.1,40.168.0,44.165.0,26.180.0,54.208.0,53.189.0,44.190.0"}
P.entries["quest:79974"] = {n="Wet Job",s="Wet Job ist eine Quest, bei der es darum geht, einen Notfallreservevorrat zu entdecken, der hoch an einem Berghang zurückgelassen wurde. Für eine überstürzte Flucht vorbereitet und in der Nähe eines malerischen Felsvorsprungs verborgen, wird das geborgene Vorratslager durch ausgeklügelte zwergische Handwerkskunst geschützt.",h="Wet Job ist eine Quest, bei der es darum geht, einen Notfallreservevorrat zu entdecken, der hoch an einem...",kw={"zwergische ingenieurskunst","adlernest","kuriertasche","berghang","pergament","reservevorrat","vorräte","wet job"},ang={["class:Rogue"]="Das Konzept, verborgene Notfallvorräte für den Fall einer überstürzten Flucht anzulegen, ist denjenigen, die in den Schatten leben, zur zweiten Natur geworden.",["profession:Engineering"]="Das Versteck zeugt vom Erfindungsreichtum zwergischer Ingenieurskunst und dient als verlässlicher Notfallvorrat, der in zerklüftetem Gelände verborgen ist.",["race:Dwarf"]="Zwergische Handwerkskunst wird bei der Bergung des Vorratslagers gepriesen, was die beständige Qualität ihres bergischen Kunsthandwerks unterstreicht."},sec={{t="Ein Notfallvorrat",b="Wer unter gefährlichen Bedingungen operiert, weiß, dass man niemals ohne einen Ausweichplan reist. Wet Job beinhaltet das Aufspüren eines Reservevorrats, der in zerklüfteten Höhen verborgen zurückgelassen wurde. Als Notfallmaßnahme für den Fall verwahrt, dass eine schnelle Flucht erforderlich wird, liegt dieses Vorratslager zur Bergung bereit, sollten Pläne schiefgehen."},{t="Das Adlernest",b="Die Wegbeschreibung weist direkt auf einen malerischen Bergausguck hin, der poetisch als aus den Wasserfällen der Zeit gehauen beschrieben wird. Hoch auf dieser Felswand befindet sich das, was als das Adlernest bezeichnet wird. Dort liegt, teilweise in der Erde vergraben, eine verwitterte Kuriertasche, die Proviant und Pergament durch verlässliche zwergische Handwerkskunst vor den Elementen schützt."}},faq={{q="Worum geht es in der Quest Wet Job?",a="Wet Job ist eine Quest, bei der es um die Bergung eines verborgenen Notfallvorrats geht, der im Gelände versteckt liegt. Die Person, die das Versteck vorbereitet hat, sorgte dafür, Vorräte zu sichern, falls sie kurzfristig fliehen müsste.",al={"was ist wet job","quest wet job","was für eine quest ist wet job"}},{q="Wer hat den Reservevorrat hinterlassen?",a="Das Versteck wurde von jemandem angelegt, der eine Notfallreserve für den Fall vorbereitete, dass er in Eile fliehen müsste. Die Bergung offenbart eine Kuriertasche, gebettet mit Pergament und Vorräten, gefertigt mit bemerkenswerter zwergischer Ingenieurskunst.",al={"wer hat das versteck hinterlassen","wessen vorräte sind das","wer hat den reservevorrat versteckt"}},{q="Wo ist das Versteck verborgen?",a="Der Hinweis deutet auf einen malerischen Berghang hin, der als aus den Wasserfällen der Zeit gehauen beschrieben wird, und weist Suchende gezielt zu einem Adlernest hoch an der Felswand, wo eine Kuriertasche aus dem Erdreich ragt.",al={"wo ist das versteck","ort von wet job","ort von adlernest"}},{q="Was befindet sich in der Kuriertasche?",a="Das Freilegen der vergrabenen Kuriertasche offenbart lebenswichtige Vorräte zusammen mit einem verstauten Pergament, geschützt durch bemerkenswert widerstandsfähige zwergische Handwerkskunst.",al={"was befindet sich im versteck","gegenstände von wet job","was findet man"}},{q="Warum heißt die Aufgabe Wet Job?",a="Während der Titel oft verdeckte oder heikle Feldeinsätze impliziert, knüpft er hier direkt an die Landmarken des Berges an, umrahmt von Mist, Wasserfällen der Zeit und feuchter Erde, die die Tasche verbirgt.",al={"warum heißt es wet job","bedeutung des namens wet job"}},{q="Inwiefern ist zwergische Ingenieurskunst im Spiel?",a="Nach dem Freilegen und Öffnen des Verstecks werden die Konstruktion und Zuverlässigkeit des Vorrats als Wunderwerk zwergischer Ingenieurskunst gepriesen, gebaut, um das Vergraben im Freien zu überstehen.",al={"verbindung zur zwergischen ingenieurskunst","ist das von zwergen"}}},fp="7,246,18.303.0,16.356.0,32.206.0,27.218.0,26.221.0,35.155.0,31.186.0,36.165.0"}
P.entries["quest:79975"] = {n="Eagle's Fist",s="Eagle's Fist dreht sich um einen kryptischen Brief, der in einem Werkzeugkasten an einem nebligen, hoch gelegenen Aussichtspunkt entdeckt wurde. Die Notiz enthüllt einen einsamen Wachposten, der aus Loyalität zu den Alten Königreichen sowie zu Adler und Faust über eine verwitterte Barrikade wacht. Obwohl das Lagerfeuer vor Kurzem noch geschürt wurde, brach der Wächter in aller Eile auf.",h="Eagle's Fist dreht sich um einen kryptischen Brief, der in einem Werkzeugkasten an einem nebligen, hoch...",kw={"barrikade","lagerfeuer","eagle's fist","gefalteter brief","ausguck","alte königreiche","fallschirmgleiter","werkzeugkasten"},ang={["profession:Engineering"]="Die Notiz des Wachpostens hebt den Ort als idealen Startpunkt für einen Fallschirmgleiter hervor, was die Aufmerksamkeit von Ingenieuren weckt, die Luftaufklärung und mechanisches Fliegen zu schätzen wissen."},sec={{t="Ein verborgener Ausguck",b="Versteckt in einem unscheinbaren Werkzeugkasten an einem malerischen Aussichtspunkt liegt ein sorgfältig gefalteter Brief. Der Verfasser sinnt über die beherrschende Stellung des hohen Aussichtspunkts nach und bemerkt, wie dieser Ort es einem ermöglicht, das Geschehen zu kontrollieren oder mit einem Fallschirmgleiter über die Landschaft zu gleiten. Von nebliger Gischt befeuchtet, bietet der einsame Posten eine unglaubliche Aussicht über geschichtsträchtige Lande."},{t="Loyalität zu den Alten Königreichen",b="Der Verfasser der Notiz bekundet eine tiefe, dauerhafte Loyalität zu „Adler und Faust“ und merkt an, dass ein angemessener Dienst an dieser Sache gebührenden Abstand verlangt. Obwohl er einräumt, dass die örtliche Barrikade verfallen ist – ganz ähnlich wie die Alten Königreiche, die sie einst vor Gefahren schützte –, schwört der standhafte Wächter, den Posten niemals wahrhaft aufzugeben."},{t="Ein überstürzter Aufbruch",b="Wer auch immer diesen Aussichtspunkt besetzt hielt, ist in Eile aufgebrochen. Besucher, die den Posten entdecken, finden ein Lagerfeuer vor, das erst kürzlich mit frischem Holz geschürt wurde, doch der Wachposten ist spurlos verschwunden und hat lediglich die Werkzeuge, die glimmende Glut und den kryptischen Brief hinterlassen."}},faq={{q="Was ist Eagle's Fist?",a="Eagle's Fist ist eine Begegnung, die sich um einen versteckten Werkzeugkasten mit einem sorgfältig gefalteten Brief an einem malerischen, nebligen Aussichtspunkt mit Blick auf eine alte Barrikade dreht. Sie markiert das Lager eines mysteriösen Spähers, der vor Kurzem geflohen ist.",al={"was ist eagle's fist","quest eagle's fist","was ist das für eine quest"}},{q="Wer hat den im Werkzeugkasten gefundenen Brief verfasst?",a="Der Verfasser ist ein nicht identifizierter Späher oder Wachposten, der den Alten Königreichen und einer als Adler und Faust bekannten Gemeinschaft oder Loyalität treu ergeben ist. Er hält eine einsame Wacht an der baufälligen Barrikade.",al={"wer hat die notiz geschrieben","wer hat den brief hinterlassen","autor des briefes im werkzeugkasten"}},{q="Worauf bezieht sich „Adler und Faust“?",a="Der Brief bezieht sich auf die Loyalität zu „Adler und Faust“, die Distanz verlangt, um ihr am besten zu dienen. Während die genaue Organisation rätselhaft bleibt, ist sie mit der Verteidigung der Überreste der Alten Königreiche verbunden.",al={"was ist der adler und die faust","bedeutung von adler und faust","wer ist adler und faust"}},{q="Warum ist das Lager verlassen?",a="Der Späher brach eilig auf und hinterließ ein Lagerfeuer, das frisch mit neuem Holz versorgt worden war. Sein Verbleib bleibt unbekannt, obwohl der Ort als hervorragender Absprungpunkt für den Einsatz eines Fallschirmgleiters gelobt wurde.",al={"wohin ist der späher gegangen","warum sind sie aufgebrochen","wer hat das lagerfeuer geschürt"}},{q="Welche Barrikade wird verteidigt?",a="Der Verfasser beklagt, dass die Barrikade schon bessere Tage gesehen hat, und vergleicht ihren abgenutzten Zustand mit den gefallenen Alten Königreichen der Menschheit, die sie einst verteidigte, schwört jedoch, ihre Bewachung niemals aufzugeben.",al={"welche barrikade","welche alten königreiche","lore zur barrikade"}},{q="Was für ein Aussichtsposten ist das?",a="Der Aussichtspunkt zeichnet sich durch unglaubliche Panoramablicke und durch Gischt feuchte Luft aus, was auf eine hohe Klippe oder einen Aussichtspunkt in der Nähe eines gewaltigen Wasserfalls oder tosenden Flusses hindeutet.",al={"wo befindet sich das","warum gibt es gischt","ort von eagle's fist"}}},fp="12,314,14.373.0,27.351.0,17.260.1,21.224.0,42.189.0,40.196.0,30.194.0,33.186.0,34.159.0"}
P.entries["quest:79976"] = {n="This Must Be The Place",s="This Must Be The Place markiert die Stelle eines kürzlich verlassenen Lagers, dessen Bewohner erst wenige Augenblicke zuvor verschwand. Eine zurückgelassene zerrissene Notiz enthüllt, dass der mysteriöse Verfasser seine Arbeit in den Untergrund verlegt hat, um sie vor den falschen Händen zu bewahren.",h="This Must Be The Place markiert die Stelle eines kürzlich verlassenen Lagers, dessen Bewohner erst wenige...",kw={"verlassenes lager","ausrüstungsrucksack","versteck","schlafsack","this must be the place","zerrissene notiz","untergrund"},sec={{t="Ein überstürzter Aufbruch",b="An diesem abgelegenen Ort hat sich ein überstürzter Aufbruch abgespielt, an dem ein unbekannter Reisender kürzlich sein Lager abgebrochen hat. Alles, was bleibt, ist ein unzureichend gesicherter Schlafsack, der sich unter den Füßen abrollt, schwere Plane, die über verschiedener Ausrüstung gebündelt ist, und ein kleiner Papierfetzen, der gerade groß genug abgerissen wurde, um für eine eilige Abschiedsbotschaft zu reichen. Wer auch immer hier lagerte, verschwand Augenblicke, bevor ihn jemand einholen konnte."},{t="In den Untergrund",b="Die zurückgelassene Botschaft enthüllt, dass der Verfasser beschloss, seine Arbeit wieder in den Untergrund zu verlegen, um sicherzustellen, dass sie nicht in die falschen Hände gerät. Es bleibt eine offene Frage, ob die Notiz einen endgültigen Abschied darstellt oder einen subtilen Hinweis auf die nächste geheime Zuflucht des Forschers, der seine verlassene Ausrüstung für denjenigen zurückließ, der auf den Ort stieß."}},faq={{q="Wer hat die zerrissene Notiz geschrieben?",a="Die Identität des Verfassers wird in der Notiz nicht genannt. Der Schreiber erklärt lediglich, dass er beschlossen hat, seine Arbeit in den Untergrund zu verlegen, um zu verhindern, dass sie in die falschen Hände gerät, und dabei ein verlassenes Lager und Ausrüstung zurücklässt.",al={"wer hat die notiz geschrieben","verfasser der notiz","wer hat die botschaft hinterlassen"}},{q="Welche Arbeit wird in den Untergrund verlegt?",a="Die genaue Natur der Arbeit des Verfassers bleibt unenthüllt. Er erwähnt lediglich, wieder in den Untergrund zu gehen, um seine Forschung oder Schöpfungen vor nicht näher genannten Widersachern zu schützen, die sie missbrauchen könnten.",al={"welche arbeit im untergrund","warum arbeit in den untergrund verlegen","welche arbeit"}},{q="Wohin ging der Bewohner des Lagers?",a="Wer auch immer den Ort bewohnte, packte in aller Eile zusammen und schlich sich nur Augenblicke vor dem Eintreffen anderer davon. Sein Ziel ist unbekannt, obwohl seine Notiz darauf hindeutet, dass er möglicherweise in ein anderes abgelegenes Versteck umgezogen ist.",al={"habe ich sie verpasst","wohin sind sie gegangen","wo ist der verfasser"}},{q="Was wurde am Lager zurückgelassen?",a="Der Reisende ließ einen unzureichend gesicherten Schlafsack zurück, der sich am Boden entrollt, schwere Plane, die über verschiedener Ausrüstung zusammengerollt ist, und einen weggeworfenen Rucksack mit diverser Ausrüstung.",al={"was wurde zurückgelassen","vorräte im lager","was war im rucksack"}},{q="Ist dies ein Hinweis, der zu einem weiteren Versteck führt?",a="Der zerrissene Papierfetzen lässt es offen, ob es sich dabei um Abschiedsworte oder um eine absichtliche Spur handelt, die zur nächsten unterirdischen Zuflucht des Verfassers führt.",al={"gibt es ein weiteres versteck","nächstes lager","weitere hinweise"}},{q="Wer sind die in der Notiz erwähnten 'falschen Hände'?",a="Die Notiz gibt nicht an, wer die 'falschen Hände' sind. Der Verfasser fürchtete eindeutig Verfolgung oder Diebstahl, was zu einem überstürzten Rückzug führte, bevor seine Bemühungen gefährdet werden konnten.",al={"wer sind die falschen hände","bedeutung falsche hände","wer verfolgt den verfasser"}}},fp="22,241,17.385.0,20.363.1,24.233.0,37.193.0,37.204.0,37.187.0,42.157.0,48.168.0"}
P.entries["quest:79980"] = {n="Scramble",s="Scramble ist eine versteckte Schatzsuche, die Abenteurer anweist, Koordinaten an einer steilen Klippe hinabzufolgen. Geleitet von der Notiz eines Plünderers graben Reisende eine vergrabene Kuriertasche aus, die Überlebensvorräte und ein schmutziges Pergament enthält.",h="Scramble ist eine versteckte Schatzsuche, die Abenteurer anweist, Koordinaten an einer steilen Klippe...",kw={"versteck","steilhang","kuriertasche","pergament","scramble","lager","vorräte"},sec={{t="Der Pfad nach Norden",b="Eine kryptische Nachricht führt jeden Reisenden, der klug genug ist, sie zu finden, zu einem versteckten Vorratslager. Der Verfasser hinterlässt informelle Ermutigungen neben präzisen Wegbeschreibungen: Marschiert einhundert Schritte genau nach Norden eine tückische Klippe hinab, um Vorräte freizulegen, die zurückgelassen wurden, um einen Reisenden am Laufen zu halten."},{t="Ausgraben der Kuriertasche",b="Folgt man den Anweisungen die steile Felswand hinab, kommt eine vergrabene Kuriertasche zum Vorschein. Aus dem Dreck ausgegraben, enthält die Tasche praktische Überlebensvorräte neben einem weiteren schmutzigen Pergament, das darin verstaut ist, was darauf hindeutet, dass diese kurze Kletterei Teil einer größeren Spur ist."}},faq={{q="Was ist die Quest Scramble?",a="Scramble ist eine Pfad-Quest für Plünderer, die einen Abenteurer zu einem versteckten Überlebenslager führt. Eine schriftliche Notiz weist jeden, der sie findet, an, nach Norden eine tückische Klippe hinabzumarschieren, um vergrabene Vorräte zu bergen.",al={"quest scramble","was ist scramble","versteck scramble"}},{q="Wo befindet sich das versteckte Versteck?",a="Den Anweisungen zufolge ist das Lager etwa einhundert Schritte genau nach Norden vergraben, gelegen an einer steilen Klippe. Es erfordert trittsicheres Vorgehen, um es zu erreichen, ohne die Felswand hinabzustürzen.",al={"wo ist das versteck","wie man das versteck findet","ort des verstecks"}},{q="Wer hat die Notiz und das Versteck hinterlassen?",a="Die genaue Identität des Verfassers bleibt ungenannt. Der Schreiber hinterließ formlose, praktische Notizen, die für einen Entdecker gedacht waren, um dessen Notvorräte zu finden und zu bestätigen, dass das Versteck unversehrt geblieben ist.",al={"wer schrieb die scramble notiz","wer hat das versteck hinterlassen","scramble autor"}},{q="Was befindet sich im vergrabenen Versteck?",a="Das Freilegen des Verstecks offenbart eine vergrabene Kuriertasche, die Überlebensvorräte und ein zwischen der Ausrüstung verstautes schmutziges Pergament enthält.",al={"scramble belohnungen","was ist im scramble lager","tascheninhalt"}},{q="Was ist das schmutzige Pergament, das bei den Vorräten gefunden wurde?",a="Das schmutzige Pergament steckt zusammen mit den Vorräten in der vergrabenen Kuriertasche und wird entdeckt, wenn die Tasche aus dem Boden gezogen wird.",al={"schmutziges pergament scramble","was steht auf dem pergament","scramble notiz"}},{q="Welche Gefahren birgt das Erreichen des Lagers?",a="Die Hauptgefahr besteht darin, den steilen Abstieg an der Klippe nach Norden zu bewältigen, wo ein Fehltritt zu gebrochenen Knöcheln oder schweren Stürzen führen kann.",al={"gefahr scramble","klippe scramble","scramble steilküste"}}},fp="8,230,19.287.0,28.257.1,27.196.0,34.200.0,32.193.0,32.125.0,52.139.0,48.143.0"}
P.entries["quest:8"] = {n="Ein Schurkenhandel",s="Ein scheinbar beiläufiger Gefallen für Calvin Montague in Todesend schickt einen Reisenden auf den Weg zur Taverne Zur Galgenschlinge in Brill. Der Auftrag besteht darin, unter dem Deckmantel eines gewöhnlichen Kurierdienstes eine geheimnisvolle, unadressierte Botschaft zu Gastwirtin Renee zu bringen.",h="Ein scheinbar beiläufiger Gefallen für Calvin Montague in Todesend schickt einen Reisenden auf den Weg zur...",kw={"brill","calvin montague","todesend","galgenschlinge","gastwirtin renee","unscheinbarer brief","schurke","tirisfal"},ang={["class:Rogue"]="Calvin Montagues privater Kurierauftrag gewährt einen Einblick in die informellen Geschäfte, die rund um Todesend und Brill abgewickelt werden.",["faction:Horde"]="Die Lieferung führt geradewegs nach Brill und macht neu eingetroffene Verbündete mit dem regionalen Zentrum der Verwaltung und Erholung der Verlassenen in Tirisfal vertraut.",["race:Undead"]="Für kürzlich auferstandene Verlassene markiert dieser Auftrag ihre allererste Reise weg von der Sicherheit des Friedhofs von Todesend hin zum geschäftigen Knotenpunkt Brill."},sec={{t="Ein freundlicher Kurier",b="Calvin Montague faulenzt inmitten der feierlichen Gräber und verfallenen Kapellen von Todesend und gibt sich als erschöpfter Kämpfer aus, der von zu vielen Geißelzombies und kriechenden Spinnen geplagt wird. Er behauptet, er brauche lediglich Hilfe beim Überbringen einer Botschaft nach Brill, und vertraut vorbeikommenden Abenteurern einen unbeschrifteten Brief an. Sein lockeres Auftreten und das Versprechen einer großzügigen Münzbelohnung lassen die Aufgabe wie nichts weiter als einen harmlosen Gefallen erscheinen, der frisch erweckte Verlassene zur Hauptsiedlung der Region weisen soll."},{t="Die Taverne Zur Galgenschlinge",b="Die Straße führt ostwärts durch die verdorbenen Bäume von Tirisfal, am Coldhearth-Anwesen vorbei, bis sie die Siedlung Brill erreicht. Hinter der Theke der örtlichen Taverne begrüßt Gastwirtin Renee Neuankömmlinge zunächst mit einem beunruhigend sonnigen Gemüt und sorgt sich um das Wohl ihrer Gäste. Sobald sie jedoch Montagues Korrespondenz erhält, bricht ihre Gastfreundschaft augenblicklich in sich zusammen. Sie lässt ihre erzwungenen Höflichkeiten fallen, täuscht vor, Nachricht von einer geliebten Mutter erhalten zu haben, schilt dann den Kurier wegen Schnüffelei und verlangt, dass er etwas kauft oder verschwindet. Die anschließende Rückkehr zu Calvin hält eine weitere Überraschung bereit: Anstatt die versprochene Bezahlung friedlich zu begleichen, fordert er den Kurier zu einem Duell heraus."}},faq={{q="Wer ist Calvin Montague?",a="Calvin Montague ist ein Schurke in Todesend, der neu erwachte Reisende bittet, einen Brief zu Gastwirtin Renee in Brill zu bringen. Er stellt dies als einfachen Gefallen dar und verspricht eine gute Bezahlung.",al={"calvin montague","wer gibt a schurke deal","questgeber"}},{q="Was befindet sich im Unscheinbaren Brief?",a="Der genaue Inhalt des Briefes ist nicht überliefert. Calvin übergibt dem Kurier eine unbeschriftete Nachricht zur Zustellung an Gastwirtin Renee in Brill.",al={"inhalt des unscheinbaren briefs","was steht im brief","calvins brief"}},{q="Warum verhält sich Gastwirtin Renee so seltsam?",a="Renee leitet die Taverne in Brill und besteht darauf, dass ihre Korrespondenz privat ist. Ihre Reaktion auf die Lieferung lässt sich herausfinden, indem man ihr Montagues Brief überbringt.",al={"gastwirtin renee verhalten","warum tut renee nur so","renee ausrede mutter"}},{q="Bezahlt Calvin Montague tatsächlich für die Lieferung?",a="Montague verspricht, für die Lieferung gut zu bezahlen. Renee bietet Nahrung oder Wasser an, sobald der Brief sie erreicht; kehrt danach zu Calvin zurück, um die Verhandlungen über seine versprochene Bezahlung fortzusetzen.",al={"hat calvin mich betrogen","wo ist mein geld","montague belohnung"}},{q="Wo liegt Brill?",a="Brill liegt nordöstlich von Todesend. Reisende folgen der Hauptstraße nach Osten aus dem Starttal heraus, halten sich hinter dem Coldhearth-Anwesen rechts und überqueren eine überdachte Brücke in die Siedlung.",al={"wegbeschreibung nach brill","straße nach brill","weg nach brill"}},{q="Was geschieht, nachdem man Renee den Brief übergeben hat?",a="Die Folgequest ist eine weitere Quest namens „Ein Schurkenhandel“. Kehrt zu Calvin Montague in Todesend zurück, um Eure Verhandlungen mit ihm fortzusetzen.",al={"folgequest","a schurke deal folgequest","was tun nach renee"}}},fx={df83fdd9={q="Warum will Calvin Montague, dass der Brief zugestellt wird?",a="Calvin Montague behauptet, er habe mehr als seinen gerechten Anteil an geistlosen Zombies und Spinnen rund um Todesend bekämpft und brauche einfach jemanden, der einen Botengang für ihn erledigt. Anstatt selbst den Weg nach Brill zurückzulegen, bietet er Euch eine hohe Belohnung dafür an, seinen versiegelten, unscheinbaren Brief direkt an Gastwirtin Renee zu übergeben.",al={"calvin montague motiv","warum brief an renee schicken","warum will calvin das erledigt haben"}}},fp="14,250,18.483.0,23.691.1,23.180.0,38.130.0,40.160.0,51.182.0,23.181.0,46.130.1"}
P.entries["quest:80"] = {n="Die Legende von Stalvan",s="Dieser entscheidende Schritt bei den Ermittlungen zu Stalvan Dunstmantel bringt die gesammelten Beweise vor die Behörden von Dunkelhain. Mit einer blutbefleckten Tagebuchseite in den Händen weist Kommandantin Althea Schwarzhaupt den Ermittler an, Amtmann Daltry aufzusuchen, um die Handschrift ein für alle Mal zu beglaubigen.",h="Dieser entscheidende Schritt bei den Ermittlungen zu Stalvan Dunstmantel bringt die gesammelten Beweise vor...",kw={"althea schwarzhaupt","blutbefleckte tagebuchseite","amtmann daltry","dunkelhain","dämmerwald","die legende von stalvan","the night watch","stalvan dunstmantel"},ang={["faction:Alliance"]="Die Ermittlung verdeutlicht, wie Grenzstädte wie Dunkelhain danach streben, Recht, Ordnung und zivile Register zu wahren, obwohl sie von Untoten und schattenhaften Bestien belagert werden.",["race:Human"]="Für Menschen der südlichen Königreiche berührt diese Quest die miteinander verwobenen Tragödien, die den Adel von Sturmwind, die Siedler des Dämmerwalds und die verstreuten Herrenhäuser von Elwynn miteinander verbinden."},sec={{t="Das Netz zieht sich zu",b="Auf den Spuren der Tagebuchseiten, die im gesamten Dämmerwald und den umliegenden menschlichen Territorien geborgen wurden, hält The Night Watch schließlich scheinbar erdrückende Beweise gegen den flüchtigen Hauslehrer Stalvan Dunstmantel in den Händen. Kommandantin Althea Schwarzhaupt hegt schon seit geraumer Zeit Verdacht gegen den Mann, doch für ein formelles Urteil bedarf es absoluter Gewissheit. Eine einzelne blutbefleckte Seite reicht nicht aus, um ein Urteil zu fällen, solange nicht zweifelsfrei bewiesen ist, dass das makabre Gekritzel tatsächlich aus Stalvans eigener Hand stammt."},{t="Das Auge des Amtmanns",b="Um die Lücke zwischen Verdacht und Gewissheit zu schließen, stützt sich The Night Watch auf Dunkelhains Stadtarchivar, Amtmann Daltry. Da Daltry das städtische Register seit Jahren führt, hat er unzählige Geschäftsbücher und Unterschriften begutachtet, was ihn zu einer Koryphäe bei der Identifizierung von Handschriften macht. Der direkte Abgleich der neu entdeckten Tagebuchseite mit Stalvans historischen Unterschriften in den Unterlagen der Stadt liefert die endgültige, unumstößliche Übereinstimmung, die nötig ist, um seinen finsteren Abstieg und seine Schuld zu bestätigen."}},faq={{q="Warum benötigt Kommandantin Schwarzhaupt die Bestätigung von Amtmann Daltry?",a="Kommandantin Althea Schwarzhaupt möchte sicherstellen, dass Stalvans Schuld über jeden Zweifel erhaben festgestellt ist, bevor sie endgültige Maßnahmen ergreift. Amtmann Daltry verwaltet das Register von Dunkelhain und besitzt umfangreiche Erfahrung bei der Begutachtung von Unterschriften, wodurch er wie kein anderer qualifiziert ist, um zu überprüfen, ob die blutbefleckte Seite mit Stalvans Handschrift in den Stadtakten übereinstimmt.",al={"warum daltry","warum handschrift prüfen","funktion von amtmann daltry"}},{q="An welcher Stelle der Handlung von „Die Legende von Stalvan“ ordnet sich dieser Schritt ein?",a="Dies ist das elfte Kapitel der langwierigen Ermittlung. Es findet unmittelbar nach dem Fund der blutbefleckten Tagebuchseite statt und dient als abschließende Überprüfung der Beweise, bevor The Night Watch entschlossen gegen Stalvan vorgeht.",al={"welcher teil ist das","wie weit in der reihe","reihenfolge der stalvan-questreihe"}},{q="Wo in Dunkelhain befindet sich Amtmann Daltry?",a="Amtmann Daltry ist im Rathaus von Dunkelhain zu finden, wo er die lokalen Aufzeichnungen und Besitzregister für die Gemeinschaft verwaltet.",al={"aufenthaltsort von daltry","wo ist amtmann daltry","daltry finden"}},{q="Welche Beweise hat der Ermittler nach Dunkelhain gebracht?",a="Der Ermittler trägt eine blutbefleckte Tagebuchseite bei sich, die während der laufenden Suche nach Stalvans Verbleib geborgen wurde. Die Schrift beschreibt seine finsteren Gedanken und Erlebnisse, erfordert jedoch einen Schriftvergleich mit den offiziellen Akten.",al={"was sind die beweise","welche seite ist das","lore zur blutbefleckten seite"}},{q="Bestätigt Amtmann Daltry, dass die Handschrift von Stalvan stammt?",a="Ja. Beim Abgleich der blutbefleckten Seite mit den Unterschriften im Stadtregister bestätigt Daltry, dass die Schrift übereinstimmt, was Schwarzhaupt die Gewissheit verschafft, die sie vor den abschließenden Schritten haben wollte.",al={"stimmt die handschrift überein","ist es stalvan","hat stalvan es geschrieben"}},{q="Warum ist The Night Watch so vorsichtig damit, Stalvan zu beschuldigen?",a="Selbst im zerrütteten, abgeschiedenen Wald des Dämmerwalds ist The Night Watch bestrebt, die gesetzliche Ordnung aufrechtzuerhalten. Einen ehemaligen Gelehrten schrecklicher Verbrechen zu bezichtigen, erfordert konkrete, nachprüfbare Beweise statt bloßer Gerüchte oder Vermutungen.",al={"warum beweise nötig sind","warum stalvan nicht einfach töten","schwarzhaupts verdacht"}}},fx={["5aad2c8f"]={q="Warum lässt Euch Kommandantin Althea Schwarzhaupt die Seite zu Amtmann Daltry bringen?",a="Kommandantin Schwarzhaupt ist für die Verteidigung des Dämmerwalds und von Dunkelhain verantwortlich und hält Wache über die Umgebung der Siedlung, während Ihr die Feldforschung zu Stalvan Dunstmantel betrieben habt. Da Ihr ihr die blutbefleckte Tagebuchseite direkt gebracht habt, ist es am schnellsten, wenn Ihr sie zu Amtmann Daltry im Rathaus bringt, um die Schrift zu überprüfen, während sie im Dienst bleibt.",al={"warum ich ebonlocke","warum spricht ebonlocke nicht mit daltry","warum zu daltry geschickt"}}},fp="21,281,15.511.0,15.474.1,62.349.0,62.242.0,43.125.0,54.237.0,55.190.1,58.219.0"}
P.entries["quest:804"] = {n="Sarkoth",s="Nachdem ein Abenteurer den verwundeten Troll Hana'zua durch das Erschlagen des monströsen Skorpids Sarkoth gerächt hat, muss er die Nachricht von seiner Notlage zurück zum Den bringen. Gornek muss verständigt werden, damit Rettung den geschwächten Späher erreicht, bevor seine giftigen Wunden sein Leben fordern.",h="Nachdem ein Abenteurer den verwundeten Troll Hana'zua durch das Erschlagen des monströsen Skorpids Sarkoth...",kw={"dunkelspeer","durotar","gornek","hana'zua","sarkoth","skorpid","the den","das tal der prüfungen"},ang={["faction:Horde"]="Die New Horde baut auf dem gegenseitigen Überleben in einem rauen, unbarmherzigen Land auf; keinen Kameraden zurückzulassen, ist ein Grundprinzip, das von den ersten Schritten eines Initianten an gelehrt wird.",["race:Orc"]="Die Kultur der Orcs schätzt persönliche Stärke, doch einzustehen, um die Ehre eines kampfunfähigen Verbündeten zu verteidigen, beweist das Herz eines wahren Kriegers.",["race:Troll"]="Die junge Allianz zwischen dem Darkspear tribe und Thralls Orcs wird durch Taten der Brüderlichkeit gestärkt, wie etwa die Rettung Hana'zuas vor einem langsamen Gifttod."},sec={{t="Die Notlage eines Spähers",b="Gestrandet auf den hohen Klippen des Tals der Prüfungen fand sich der Dunkelspeer-Späher Hana'zua von Gift getroffen wieder, unfähig, ohne Hilfe über die tückischen Pfade zurückzukehren. Obwohl an Sarkoth – dem gefürchteten Skorpid, der ihn bezwang – Rache geübt wurde, kann Stolz allein einen vergifteten Krieger nicht über die dürren Steine tragen. An seinen Felsen gebunden, ist er darauf angewiesen, dass ein vorbeikommender Initiant die Nachricht hinab zum Ausbildungslager bringt."},{t="Ehre im Den",b="Die Rückkehr zu Gornek beim Den schließt die Prüfung ab. Gornek erkennt die Bedrohung durch Sarkoth sofort und organisiert rasch Hilfe für Hana'zua. In den Augen der Horde-Befehlshaber verkörpert es wahre Ehre, das eigene Training zu unterbrechen, um einen gestürzten Fremden zu rächen und zu retten, was den Wert eines Initianten beweist, lange bevor er in das eigentliche Durotar auszieht."}},faq={{q="Wer ist Hana'zua und warum sitzt er fest?",a="Hana'zua ist ein junger Dunkelspeer-Trollspäher, der sich in die Höhen des Tals der Prüfungen wagte und von dem monströsen Skorpid Sarkoth überfallen und vergiftet wurde. Zu schwach, um den Abstieg allein zu bewältigen, benötigt er Rettung.",al={"hanazua","wer ist hanazua","warum ist der troll verletzt"}},{q="Wer ist Gornek?",a="Gornek ist ein Orc-Aufseher, der beim Den im Tal der Prüfungen stationiert ist. Er beurteilt neue Rekruten, teilt Überlebensaufgaben zu und koordiniert Hilfe, wenn Initianten in der Schlucht auf tödliche Bedrohungen stoßen.",al={"gornek","wo ist gornek","anführer des den"}},{q="Was ist Sarkoth?",a="Sarkoth ist ein berüchtigter, übergroßer Skorpid, der in den felsigen Klippen über dem Tal der Prüfungen haust. Sein Gift und seine schiere Wildheit machen ihn zu einer legendären Gefahr während der Prüfungen junger Orcs und Trolle.",al={"sarkoth bestie","was für ein monster ist sarkoth"}},{q="Überlebt Hana'zua seine Wunden?",a="Gornek verspricht, dass Hana'zua unverzüglich Hilfe geschickt wird, sobald er Euren Bericht hört. Was danach aus dem Späher wird, ist nicht überliefert.",al={"überlebt der troll","geht es hanazua gut","hanazua gerettet"}},{q="Warum lobt Gornek diese Tat so sehr?",a="Das Überleben der Prüfungen wird erwartet, doch Eure eigenen Aufgaben beiseitezustellen, um für die Ehre eines Fremden zu kämpfen und dessen Überleben zu sichern, verkörpert die Grundwerte, die die New Horde in ihren Kriegern zu schmieden sucht.",al={"warum kümmert sich gornek","gornek ehrenrede"}},{q="Wo befindet sich der Den?",a="Der Den ist die zentrale Ausbildungshöhle und der Sammelplatz im Herzen des Tals der Prüfungen im südwestlichen Durotar.",al={"wo ist der den","den lage durotar"}}},fx={["88c1d5d5"]={q="Warum bittet Euch Hana'zua, Gornek Bericht zu erstatten?",a="Obwohl die Rache für seine Niederlage gegen Sarkoth Hana'zuas Entschlossenheit zu überleben gestärkt hat, lassen ihn seine schweren Wunden völlig bewegungsunfähig im Tal zurück. Er kann den Weg zurück nach The Den aus eigener Kraft nicht zurücklegen. Indem er Euch mit der Nachricht über seine missliche Lage schickt, hofft er, dass Gornek Hilfe schickt, bevor er seinen Verletzungen oder den Elementen erliegt.",al={"warum zu gornek geschickt","hanazua motiv","warum gornek informieren"}},["66b1c5a1"]={q="Warum kann Hana'zua nicht selbst zu The Den zurückkehren?",a="Hana'zua wurde während seiner Prüfung von Sarkoth verprügelt und für tot zurückgelassen. Er hat nicht die Kraft zu stehen, geschweige denn, alleine über den sengenden Canyonboden zurück in Sicherheit zu kriechen. Da keine anderen Krieger in der Nähe sind, um ihm zu helfen, seid Ihr seine einzige Rettungsleine, um Gornek zu informieren, bevor es zu spät ist.",al={"warum braucht hanazua hilfe","warum kann hanazua nicht gehen","warum ich hanazua"}}},fp="7,254,16.425.0,16.363.0,39.228.0,14.201.0,16.197.0,33.142.1,43.198.0,25.125.0"}
P.entries["quest:805"] = {n="Bericht erstatten in Sen'jin",s="Bericht erstatten in Sen'jin markiert den Moment, in dem junge Initianden der Horde das abgeschiedene Tal der Prüfungen hinter sich lassen, um die Dunkelspeer vor den Umtrieben eines Dämonenkults zu warnen. Von Zureetha Fernblick entsandt, überbringen Boten Meister Gadrin die Nachricht von der Burning Blade und erfahren dabei, dass Schattenmagie bereits die nahegelegenen Küsten bedroht.",h="Bericht erstatten in Sen'jin markiert den Moment, in dem junge Initianden der Horde das abgeschiedene Tal der...",kw={"burning blade","dunkelspeer","durotar","die echoinseln","meister gadrin","sen'jin","das tal der prüfungen","zureetha fernblick"},ang={["faction:Horde"]="Diese Aufgabe veranschaulicht das unverzichtbare Zusammenwirken der Gründungsvölker von Thralls Horde, die gegenseitig Erkenntnisse austauschen, um ihre jungen Siedlungen zu beschützen.",["race:Orc"]="Für junge Orcs ist der Aufbruch aus dem Tal der Prüfungen zur Unterstützung der Dunkelspeer eine frühe Prüfung von Ehre und Solidarität gegenüber den Verbündeten, die Thrall über das große Meer hinweg beigestanden haben.",["race:Troll"]="Die Rückkehr nach Sen'jin konfrontiert Abenteurer der Dunkelspeere unmittelbar mit der Vertreibung ihres Volkes und dem anhaltenden Kampf um die Rückeroberung der Echoinseln."},sec={{t="Den Höhlenbau verlassen",b="Nachdem sie ihren Kampfesmut bewiesen und dunkle Medaillons vom Koven der Brennenden Klinge im Tal der Prüfungen geborgen haben, werden die Novizen für bereit für die weite Welt erklärt. Zureetha Fernblick erkennt, dass die dämonische Präsenz auf dem heiligen Prüfungsfeld kein isoliertes Ärgernis ist, sondern das Symptom einer schleichenden Fäulnis in ganz Durotar. Sie schickt die jungen Abenteurer nach Osten am Ausgang der Schlucht vorbei und nach Süden zur Küste, um den Stamm der Dunkelspeer zu warnen."},{t="Schatten über der Küste",b="In der Küstensiedlung Sen'jin angekommen, überbringen die Reisenden ihre Warnung an Meister Gadrin, den älteren Hexendoktor, der die Dunkelspeer im Exil anleitet. Obwohl Gadrin bestätigt, dass die Burning Blade selbst noch nicht bis an die Strände des Dorfes vorgestoßen ist, enthüllt er, dass dunkle Magie ganz in der Nähe auf den Echoinseln Fuß gefasst hat. Der Bericht verdeutlicht, wie zerbrechlich der Halt der jungen Horde noch immer ist: Während Verbündete herbeieilen, um einander beizustehen, treffen uralter Verrat innerhalb des Stammes und dämonische Verderbnis sie gleichzeitig an ihren Flanken."}},faq={{q="Warum schickt Zureetha Fernblick Leute aus dem Tal der Prüfungen fort?",a="Nachdem sie dämonische Aktivitäten im Tal der Prüfungen aufgedeckt hat, befürchtet Zureetha Fernblick, dass der Kult der Burning Blade eine organisierte Bedrohung für ganz Durotar darstellt. Sie schickt bewährte Initianden aus dem Tal hinaus, um verbündete Siedlungen zu warnen und herauszufinden, wie weit der Einfluss des Kults bereits reicht.",al={"warum tal der prüfungen verlassen","warum nach senjin","zureetha fernblick befehle"}},{q="Wer ist Meister Gadrin?",a="Meister Gadrin ist ein älterer Hexendoktor und geistiger Anführer der Dunkelspeer in Sen'jin. Er dient Häuptling Vol'jin als Berater, kümmert sich um die Belange des Stammes und stellt sich den Gefahren, die über ihrer vorübergehenden Zuflucht an der Küste drohen.",al={"meister gadrin geschichte","wer ist gadrin"}},{q="Hat die Burning Blade Sen'jin angegriffen?",a="Nein, die Burning Blade hat Sen'jin nicht direkt angegriffen. Allerdings berichtet Meister Gadrin, dass ganz ähnliche dunkle Magie und Verrat unweit auf den Echoinseln Wurzeln geschlagen haben, sodass den Trollen eine eigene unmittelbare Gefahr droht.",al={"ist burning blade in senjin","kult in senjin"}},{q="Wo liegt Sen'jin?",a="Sen'jin liegt östlich hinter dem Hauptausgang der Schlucht des Tals der Prüfungen und dann nach einer Biegung nach Süden an der Weggabelung entlang der Südostküste von Durotar.",al={"weg nach senjin","senjin richtung"}},{q="Welche Bedrohung auf den Echoinseln erwähnt Meister Gadrin?",a="Meister Gadrin sorgt sich wegen des finsteren Verrats durch Zalazane, einen befreundeten Hexendoktor der Trolle, der mit tückischen Verhexungen seine eigenen Brüder versklavte, die Kontrolle über die Echoinseln an sich riss und die überlebenden Dunkelspeer an die Küste des Festlands vertrieb.",al={"echoinseln probleme","was geschah auf den echoinseln"}},{q="Was geschieht nach dem Bericht an Meister Gadrin?",a="Nachdem er Euren Bericht angehört und von der eigenen Notlage der Trolle erzählt hat, bittet Gadrin Euch um Hilfe gegen die Gefahren an der Küste, während weitere Befehle Euch nach Nordwesten zu Orgnil Narbenseele in Klingenhügel führen.",al={"folgequest nach bericht erstatten in senjin","was tun nach gadrin"}}},fx={["54845e0f"]={q="Warum schickt Euch Zureetha Fernblick zu Meister Gadrin anstatt zu einer Wache?",a="Ihr habt die Brennende Klinge persönlich in ihrem Koven im Tal der Prüfungen konfrontiert und Beweise für ihre Anwesenheit geborgen. Nachdem Ihr Eure Loyalität und Stärke durch Eure Prüfungen bewiesen habt, seid Ihr der qualifizierteste Bote, um Meister Gadrin einen Augenzeugenbericht über die Infiltration des Kults zu liefern.",al={"warum schickt sie mich","warum ich zureetha","warum kein läufer nach senjin"}}},fp="25,322,15.449.0,22.510.1,70.285.0,21.259.0,47.227.0,33.168.0,57.234.0,46.216.0"}
P.entries["quest:806"] = {n="Dunkle Stürme",s="Dunkle Stürme ist eine kritische Aufgabe, die Euch von Orgnil Narbenseele in Klingenhügel übertragen wurde, um einen abtrünnigen Hexenmeister zu Fall zu bringen, der das Land korrumpiert. Ein Goblin namens Fizzle Darkstorm hat sich im Auftrag des tückischen Burning Blade-Kults im Donnergrat verschanzt. Ihn auszuschalten ist entscheidend, um Durotar vor einem dämonischen Wiederaufleben zu schützen, bevor sich die Kultisten weiter ausbreiten.",h="Dunkle Stürme ist eine kritische Aufgabe, die Euch von Orgnil Narbenseele in Klingenhügel übertragen wurde...",kw={"burning blade","dunkle stürme","durotar","fizzle darkstorm","zischels klaue","orgnil narbenseele","klingenhügel","donnergrat"},ang={["class:Shaman"]="Die dunklen Riten, die von Fizzle und seinen Schergen praktiziert werden, stören die natürlichen Geister des Donnergrats, regen seine Bestien auf und fordern, dass das elementare Gleichgewicht wiederhergestellt wird.",["class:Warlock"]="Fizzle Darkstorm demonstriert die rücksichtslose Gefahr unkontrollierter Teufelshingabe und macht ihn zu einer Schande und einer Gefahr, die disziplinierte Praktizierende der Horde nicht tolerieren können.",["faction:Horde"]="Sicherzustellen, dass das Herz von Durotar vor dämonischer Subversion geschützt bleibt, ermöglicht es der jungen Horde, ihre Verteidigung nach außen zu richten, anstatt von innen heraus zu kollabieren.",["race:Orc"]="Die Burning Blade repräsentiert die dunkle Vergangenheit, die die Orcs jeden Tag zu überwinden kämpfen. Die Eliminierung von Kultisten-Infiltratoren wie Fizzle ist für die Bewahrung von Thralls freier Nation unerlässlich."},sec={{t="Eine Bedrohung im Grat",b="Während junge Verteidiger der Horde die Grenzen von Durotar patrouillieren, schwelt direkt unter ihrer Aufsicht eine interne Korruption. Orgnil Narbenseele, der von Klingenhügel aus Ermittlungen durchführt, entdeckte, dass der Donnergrat im Nordwesten unter den Einfluss dunkler Schattenmagie geraten ist. Die Schlucht wimmelt von Burning Blade-Kultisten, die Unheil und Chaos über die lokale Tierwelt und das Land bringen."},{t="Fizzle Darkstorm",b="Die Kultistenaktivitäten im Grat werden von Fizzle Darkstorm geleitet, einem opportunistischen Goblin-Hexenmeister, der mit der Burning Blade verbündet ist. Anstatt Handelsinteressen oder Kartellen zu dienen, nutzt Fizzle die Teufelsmacht direkt im Dienste der subversiven Agenda des Kults. Ihn zu töten und Fizzles Klaue zu bergen, beweist Orgnil, dass die unmittelbare Führung des Kults in der Schlucht gebrochen wurde."},{t="Den Kult ausrotten",b="Die Burning Blade repräsentiert alles, was Thralls neue Horde hinter sich lassen will: dämonische Knechtschaft, rücksichtslose Korruption und blutrünstigen Wahnsinn. Fizzle zu Fall zu bringen entfernt einen aktiven Verschwörer aus dem Landesinneren von Durotar, signalisiert aber auch, dass der Schatten über der Heimat der Orcs weit tiefer reicht als nur isolierte Lager."}},faq={{q="Wer ist Fizzle Darkstorm?",a="Fizzle Darkstorm ist ein Goblin-Hexenmeister, der im Namen des Burning Blade-Kults operiert. Er und seine kultischen Anhänger haben im Donnergrat Zuflucht gesucht und verbreiten dämonisches Chaos in der gesamten Schlucht, bis Orgnil Narbenseele seine Hinrichtung fordert.",al={"wer ist fizzle","fizzle darkstorm hintergrundgeschichte","fizzle goblin"}},{q="Wo befindet sich der Donnergrat?",a="Der Donnergrat ist eine zerklüftete Schlucht im nordwestlichen Durotar, nördlich von Klingenhügel und südwestlich von Orgrimmar. Er ist bekannt dafür, dass er von blitzgeladenen Bestien und Lagern der Burning Blade-Kultisten überrannt wird.",al={"wo ist der donnergrat","standort donnergrat","donnergrat finden"}},{q="Warum ist die Burning Blade in Durotar?",a="Die Burning Blade versucht, Thralls Horde zu untergraben und die dämonische Vorherrschaft über die Orcs wiederherzustellen. Sie operieren heimlich aus versteckten Schluchten, Höhlen und Canyons in ganz Durotar, um Korruption von innen heraus zu säen.",al={"burning blade in durotar","warum sind kultisten in durotar","motive der burning blade"}},{q="Warum will Orgnil Narbenseele ausgerechnet Fizzles Klaue?",a="Orgnil benötigt einen unmissverständlichen Beweis dafür, dass der Hexenmeister ausgeschaltet wurde. Die Rückkehr mit Fizzles Klaue bestätigt, dass das Oberhaupt der Kultisten-Kabale im Donnergrat keine Operationen mehr leiten kann.",al={"warum fizzles klaue","bedeutung von fizzles klaue","todesnachweis fizzle"}},{q="Was passiert, nachdem Fizzle getötet wurde?",a="Die Niederlage von Fizzle beseitigt die unmittelbare Bedrohung im Donnergrat und veranlasst Orgnil Narbenseele dazu, Euch zum Schamanen Margoz zu schicken, der mehr über die Korruption der Burning Blade weiß, um weitere Verschwörungen der Burning Blade aufzudecken.",al={"was folgt auf dunkle stürme","dunkle stürme fortsetzung","nächste quest nach dunkle stürme"}},{q="Warum würde ein Goblin für die Burning Blade arbeiten?",a="Während viele Goblins durch Handelskartelle nach Gold streben, werden einige von der rohen Macht, dem Einfluss und den dunklen Künsten der Schattenmagie angelockt. Fizzle wandte sich der Teufelshexerei zu und verlieh seine rücksichtslose List direkt den Kultisten.",al={"goblin bei der burning blade","warum ist fizzle beim kult","fizzle hexenmeister"}}},fx={["18f009de"]={q="Warum will Orgnil Narbenseele, dass Fizzle Darkstorm eliminiert wird?",a="Orgnil befürchtet, dass sich die Verderbnis und der dämonische Einfluss der Brennenden Klinge unkontrolliert ausbreiten werden, wenn man ihnen auch nur einen kleinen Stützpunkt in Durotar zugesteht. Fizzle Darkstorm und sein Koven haben sich auf dem Donnergrat verschanzt und säen aktiv Chaos direkt vor der Haustür der jungen Orc-Heimat. Sie sofort niederzuschlagen verhindert, dass eine umfassende dämonische Infiltration Fuß fasst.",al={"warum fizzle darkstorm töten","orgnil narbenseele motiv","warum die quest dark storms"}}},fp="11,352,21.362.0,16.385.0,20.328.1,24.237.0,31.216.0,36.211.0,57.194.0,35.221.1,46.223.0"}
P.entries["quest:808"] = {n="Minshinas Schädel",s="Meister Gadrin aus Sen'jin wird von den verzweifelten Schreien seines verstorbenen Bruders, Minshina, heimgesucht. Nachdem er auf den Echoinseln vom schurkischen Hexendoktor Zalazane erschlagen und dunkler Magie unterworfen wurde, bleibt Minshinas Seele in seinem eigenen abgetrennten Schädel gefangen. Um den gefallenen Troll zu befreien, müsst Ihr Zalazanes Ritualplatz infiltrieren, das Relikt zurückholen und seinen Geist aus ewiger Qual erlösen.",h="Meister Gadrin aus Sen'jin wird von den verzweifelten Schreien seines verstorbenen Bruders, Minshina...",kw={"kreis der macht","dunkelspeer","die echoinseln","gadrin","minshina","sen'jin","schädel","voodoo","zalazane"},ang={["class:Priest"]="Priester verstehen die tiefe Heiligkeit der verstorbenen Seele und erkennen den Schrecken der rituellen Nekromantie, die einen gefallenen Bruder daran hindert, ewigen Frieden zu finden.",["class:Shaman"]="Schamanen verehren die Geister der Ahnen; das Brechen von Zalazanes Kreis, um eine gefolterte Seele zu befreien, stellt das Gleichgewicht zwischen der Geisterwelt und den Lebenden wieder her.",["faction:Horde"]="Die Unterstützung von Meister Gadrin ehrt das Band zwischen der Neuen Horde und dem Stamm der Dunkelspeere und beweist, dass der Kummer eines Verbündeten von allen geteilt wird.",["race:Troll"]="Für einen Dunkelspeertroll ist die Bergung von Minshinas Schädel eine heilige Pflicht gegenüber Familie und Stamm, die einen Schlag gegen Zalazanes Pervertierung der rituellen Ahnentraditionen darstellt."},sec={{t="Ein Flehen aus den Schatten",b="Meister Gadrin dient als einer der spirituellen Anker des Stammes der Dunkelspeere in Sen'jin, doch sein Geist wird von dunklen Visionen gequält. Sein Bruder Minshina wurde zum Opfer von Zalazanes Verrat, als der wahnsinnige Hexenmeister die Kontrolle über die Echoinseln übernahm. Minshina kam während des Konflikts ums Leben, doch nach Trolltradition und Voodoo-Mystik gewährt der physische Tod nicht immer Frieden. Minshinas gequälte Stimme spricht in Gadrins Träumen und fleht um Erlösung von einem Schicksal, das schlimmer als der Tod ist."},{t="Zalazanes Kreis der Macht",b="Zalazane tötet seine ehemaligen Brüder nicht einfach nur; er fängt ihre Seelen ein, um seine dunkle Zauberei anzutreiben. Minshinas Essenz wurde rituell an seinen eigenen Schädel gebunden, der nun inmitten eines blasphemischen Kreises der Macht auf der größten der Echoinseln ruht. Bewacht von verfluchten Trollen und in rituelles Kerzenlicht getaucht, dient der Schädel als Fokus für das verdrehte Mojo des Verräters. Solange er sich innerhalb des Kreises befindet, bleibt Minshina ein ewiger Gefangener von Zalazanes Willen."},{t="Freiheit im Tod",b="Um Minshina zu retten, muss ein tapferer Champion die Gewässer östlich von Sen'jin zu den südlichen Ausläufern der Echoinseln überqueren, in den Ritualkreis eindringen und den Schädel dem Einfluss des Hexendoktors entziehen. Die Rückgabe der Überreste an Meister Gadrin durchbricht die dunklen Fesseln, sodass Minshinas dankbarer Geist kurzzeitig Gestalt annehmen, sich verbeugen und schließlich in das Reich der Ahnen aufbrechen kann."}},faq={{q="Wer war Minshina?",a="Minshina war der Bruder von Meister Gadrin, dem prominenten Hexendoktor und Ältesten, der in Sen'jin lebt. Er wurde während des Aufstands auf den Echoinseln von Zalazane ermordet, der seine Überreste anschließend mit dunkler Zauberei schändete.",al={"minshina identität","wer ist minshina","gadrins bruder"}},{q="Warum ist Minshinas Geist in seinem Schädel gefangen?",a="Zalazane nutzt dunkles Voodoo und Hexenmeistermagie, um die Geister erschlagener Dunkelspeertrolle zu versklaven. Indem er Minshinas Seele direkt an seinen physischen Schädel band und diesen in einen rituellen Kreis der Macht legte, verwehrte Zalazane ihm den Übergang ins Jenseits und machte sich seinen Geist untertan.",al={"warum schädel gefangen","zalazanes seelenfalle","minshinas seele"}},{q="Wo befindet sich der Kreis der Macht?",a="Die Ritualstätte befindet sich auf einem Hügel auf der südlichsten und größten der Echoinseln, vor der Südostküste von Durotar. Sie ist an rituellen Kerzen, tanzenden verfluchten Trollen und zur Schau gestellten Schädeln zu erkennen.",al={"wo ist der schädel","ort des kreises der macht","fundort von minshinas schädel"}},{q="Was geschieht, wenn der Schädel nach Sen'jin zurückgebracht wird?",a="Sobald Meister Gadrin den Schädel erhält, zerspringen die nekromantischen Fesseln. Minshinas geisterhafte Gestalt erscheint vor seinem Bruder und dem The Adventurer, verneigt sich in Dankbarkeit und verschwindet, um friedlich bei den Ahnen zu ruhen.",al={"abgabe der quest","was passiert mit minshina","erscheint minshina"}},{q="Wer ist Zalazane und warum hat er das getan?",a="Zalazane war einst ein angesehener Hexendoktor des Stammes der Dunkelspeere. Von Machtgier in den Wahnsinn getrieben, wandte er sich gegen seinen Stamm, nutzte Flüche, um seine Brüder und Schwestern geistig zu kontrollieren, und vertrieb die verbliebenen Dunkelspeerflüchtlinge auf das Festland von Durotar.",al={"wer ist zalazane","warum ist zalazane böse","zalazane hintergrundgeschichte"}},{q="Warum kann Gadrin den Schädel nicht selbst zurückholen?",a="Meister Gadrin ist entscheidend dafür, Sen'jin zusammenzuhalten. Zwischen der Führung der jungen Dunkelspeer, der Beratung des Häuptlings Vol'jin und dem aktiven Entgegenwirken von Zalazanes sich ausbreitenden Flüchen entlang der Küste kann Gadrin die Siedlung nicht ungeschützt lassen.",al={"warum geht gadrin nicht selbst","gadrins aufgaben"}}},fx={["5583848b"]={q="Wozu wird Minshinas Schädel benutzt?",a="Minshinas Schädel dient als magisches Gefäß, das die gefangene Essenz von Meister Gadrins ermordetem Bruder enthält. Zalazane platzierte ihn innerhalb eines rituellen Machtkreises auf der größten der Echoinseln und benutzte niederträchtige Zauberei, um Minshinas Geist selbst über den Tod hinaus zu versklaven. Den Schädel vom dunklen Altar zu entfernen, stört die Bindungsmagie des Hexenmeisters und erlaubt es Gadrin, die Seele seines Bruders endlich zu befreien, sobald Ihr ihn sicher nach Sen'jin zurückgebracht habt.",al={"was ist minshinas schädel","zweck von minshinas schädel","minshinas schädel gegenstand"}},["2001e9be"]={q="Warum will Meister Gadrin, dass dies getan wird?",a="Meister Gadrin wird von den Schreien seines Bruders Minshina gequält, der in seinen Träumen nach ihm ruft. Minshina wurde auf den Echoinseln von dem verräterischen Hexendoktor Zalazane getötet, aber der Tod brachte keinen Frieden. Zalazane hat Minshinas Seele direkt an seinen abgetrennten Schädel gebunden und ihn in dunkle Magie verstrickt. Gadrin kann es nicht ertragen, den Geist seines Bruders zur ewigen Sklaverei verdammt zu wissen, und er braucht verzweifelt jemanden, der den Griff des Hexenmeisters bricht und Minshina ewige Ruhe gewährt.",al={"warum braucht gadrin minshinas schädel","meister gadrin motiv","warum minshina befreien"}}},fp="16,388,23.481.0,26.459.0,16.402.1,17.226.0,46.270.0,37.212.0,63.214.1,39.246.0,44.254.0"}
P.entries["quest:809"] = {n="Ak'Zeloth",s="Ak'Zeloth ist eine frühe Horde-Quest, die vom Hexenmeister Neeru Fireblade tief aus Orgrimmars Kluft der Schatten vergeben wird. Angetrieben von Beweisen für eine verbleibende dämonische Verderbnis entsendet Neeru Abenteurer in das Brachland, um sich mit seinem an der Grenze stationierten Feldkontakt zu treffen.",h="Ak'Zeloth ist eine frühe Horde-Quest, die vom Hexenmeister Neeru Fireblade tief aus Orgrimmars Kluft der...",kw={"ak'zeloth","brachland","burning blade","die kluft der schatten","the demon seed","glutnebelgipfel","fernwacht","neeru fireblade"},ang={["class:Warlock"]="Hexenmeister, die mit Neeru Fireblades Lehren vertraut sind, dürften aufhorchen, wenn sein eigener Gehilfe die Aufforderung hinterfragt, ein dämonisches Relikt zu zerstören.",["faction:Horde"]="Die Sicherung der Fernwacht und die Säuberung des Glutnebelgipfels sind von entscheidender Bedeutung, um die entstehenden Handels- und Transportwege zu schützen, die Durotar mit dem Brachland verbinden.",["race:Orc"]="Orcs haben erbittert gekämpft, um dem Griff der Brennenden Legion zu entkommen, weshalb jedes Anzeichen des Burning-Blade-Kults und dämonischer Relikte vor ihrer Haustür eine akute Bedrohung darstellt."},sec={{t="Eine Spur der Schatten",b="Nach der Entdeckung eines Halsbands mit Insignien der Burning Blade in Durotar behauptet Neeru Fireblade, dämonische Überreste zu jagen, die die neu angesiedelte Horde bedrohen. Indem er sich als Wächter gegen Dämonenverderbnis präsentiert, schickt Neeru Abenteurer in die dürren Weiten des Brachlands und warnt davor, dass sich ein finsterer Kult um ein Artefakt von abscheulicher Macht schart, das als The Demon Seed bekannt ist."},{t="Der Kontakt am Außenposten",b="Um den Schlag gegen den Kult zu koordinieren, müssen Abenteurer Ak'Zeloth aufsuchen, Neerus Gehilfen, der nahe der Fernwacht an der Grenze zwischen Durotar und dem Brachland stationiert ist. Doch bei der Ankunft begegnet Ak'Zeloth der Mission mit leisem Skeptizismus und sinnt offen darüber nach, warum sein Meister tatsächlich den Untergang des Artefakts anstreben sollte, bevor er Anweisungen dazu erteilt, wie mit The Demon Seed auf dem Glutnebelgipfel umzugehen ist."}},faq={{q="Wer vergibt diese Quest?",a="Die Quest wird von Neeru Fireblade vergeben, einem Hexenmeister, der in der schattigen Höhle der Kluft der Schatten unter Orgrimmar haust, unmittelbar nachdem Ihr ihm ein Halsband der Burning Blade überreicht habt.",al={"queststarter","wo man ak'zeloth erhaelt","neeru fireblade quest"}},{q="Wo befindet sich Ak'Zeloth?",a="Ak'Zeloth befindet sich direkt vor der Fernwacht, genau an der östlichen Grenze des Brachlands, wo die Brücke von Durotar herüberführt.",al={"ak'zeloth standort","wo ist ak'zeloth","ak'zeloth finden"}},{q="Was ist The Demon Seed?",a="The Demon Seed ist ein unheilvolles Artefakt dämonischer Macht, das sich in den Händen des Burning-Blade-Kults auf dem Glutnebelgipfel befindet, einem unheilvollen Berg im nördlichen Brachland.",al={"the demon seed lore","was ist die saat"}},{q="Warum findet Ak'Zeloth Neerus Befehle merkwürdig?",a="Ak'Zeloth erklärt sich nicht näher. Er bemerkt lediglich, dass es merkwürdig sei, dass Neeru die Zerstörung von The Demon Seed wünscht, und erklärt sich dann bereit, Euch zu sagen, wie man sie entfernt.",al={"warum ak'zeloth ueberrascht ist","seltsame reaktion ak'zeloth"}},{q="Welche Quest folgt auf diese?",a="Das Gespräch mit Ak'Zeloth führt unmittelbar zur Quest „The Demon Seed“, die Euch damit beauftragt, den Glutnebelgipfel zu erklimmen, um das verderbende Relikt zu neutralisieren.",al={"folgequest nach ak'zeloth","ak'zeloth folgequest"}},{q="Ist diese Quest Teil der Questreihe der Burning Blade?",a="Ja. Sie dient als wichtige Brücke, die die in Durotar aufgedeckten lokalen Verschwörungen der Kultisten mit den umfassenderen, organisierten Aktivitäten des Kults verbindet, der sich im Brachland festgesetzt hat.",al={"burning blade questreihe","orgrimmar kult quest"}}},fx={["91b6b00f"]={q="Warum möchte Neeru Fireblade, dass The Demon Seed zerstört wird?",a="Neeru Fireblade behauptet, dass er sich seit der Niederlage der Brennenden Legion dem Ausrotten der verbliebenen dämonischen Verderbnis in den Ländern der Orcs widmet. Als Ihr ihm ein Halsband des Kults der Burning Blade brachtet, erklärte er, dass dies seine schlimmsten Befürchtungen bestätigte. Neeru zufolge zieht der Kult seine Stärke aus The Demon Seed auf dem Gipfel des Glutnebelgipfel, und das Zerschlagen dieses dämonischen Relikts ist entscheidend, um ihren dunklen Einfluss auf die Horde zu stoppen.",al={"neeru fireblade motiv","warum the demon seed zerstören","warum schickt neeru euch"}}},fp="9,278,17.373.0,19.390.1,21.184.0,27.143.0,23.156.0,47.152.1,28.158.0,50.161.0"}
P.entries["quest:812"] = {n="Heilmittel benötigt",s="Gestrandet an den schroffen Klippen im Nordwesten von Durotar liegt der Dunkelspeertroll Rhinag, vergiftet von einem Giftschwanzskorpid. Da ihm kaum Zeit bleibt, bevor das Toxin ihn dahinrafft, ist er auf einen Boten angewiesen, der nach Orgrimmar eilt und ein Heilmittel von Kor'ghan beschafft.",h="Gestrandet an den schroffen Klippen im Nordwesten von Durotar liegt der Dunkelspeertroll Rhinag, vergiftet...",kw={"gegengift","die kluft der schatten","durotar","kor'ghan","heilmittel benötigt","orgrimmar","rhinag","skorpid","giftschwanz"},ang={["faction:Horde"]="Durotars felsiges Terrain ist rau und unbarmherzig – eine unerbittliche Feuertaufe für die neu eingetroffenen Verteidiger von Thralls jungem Reich.",["race:Troll"]="Rhinags Furcht vor einer Rückkehr nach Sen'jin unterstreicht den herben Stolz des Dunkelspeerstammes, bei dem Nachlässigkeit beim einfachen Überleben in der Wildnis scharfen Spott der Verwandten nach sich zieht."},sec={{t="Der Stich eines Skorpids",b="In den dürren Schluchten von Durotar wimmelt es von Giftschwanzskorpids – aggressive Raubtiere, deren Stich ein rasch wirkendes, lähmendes Nervengift in sich trägt. Rhinag beging den Fehler, beim Kampf gegen die Bestien nahe der Grenzlande seine Wachsamkeit schleifen zu lassen. Wohl wissend, dass das Gift in seinen Adern ihn in weniger als einer Stunde töten wird, vermag er den weiten Weg zu den Toren der Stadt nicht mehr aus eigener Kraft zu bewältigen und muss sein Überleben in die Hände dessen legen, der an seinem abgelegenen Lager vorbeikommt."},{t="Geheimnisse in den Schatten",b="Anstatt einem gewöhnlichen Apotheker oder Schamanen zu vertrauen, schickt Rhinag Reisende tief unter Orgrimmar in die schattigen unterirdischen Höhlen der Kluft der Schatten. Dort weilt Kor'ghan, ein rätselhafter Kundiger, der mit den harten Giften der Ödlande von Durotar vertraut ist. Kor'ghan besitzt das Wissen, das zum Brauen eines wirksamen Gegengifts vonnöten ist, wenngleich er jenen, die ihren Mut noch nicht unter Beweis gestellt haben, nur selten uneigennützig hilft."}},faq={{q="Wer ist Rhinag?",a="Rhinag ist ein Abenteurer der Dunkelspeertrolle, der sich an den nordwestlichen Klippen von Durotar an sein Leben klammert. Von einem Giftschwanzskorpid gestochen, fürchtet er sowohl den drohenden Tod als auch den Spott seiner Sippe in Sen'jin, sollte er in solch gedemütigtem Zustand zurückkehren.",al={"rhinag geschichte","wer ist rhinag","rhinag der troll"}},{q="Warum befindet sich Kor'ghan in der Kluft der Schatten?",a="Kor'ghan haust in der Kluft der Schatten, jener finsteren Höhle unterhalb von Orgrimmar, in der Hexenmeister, Schurken und andere Ausüber dunkler Künste ihrem Handwerk fernab der Blicke von Thralls ehrenhaften Kriegern nachgehen. Sein Verständnis von giftigen Gebräuen und zermürbenden Prüfungen fügt sich nahtlos in die unterirdische Umgebung der Kluft ein.",al={"wo ist korgan","wer ist korghan","kor'ghan aufenthaltsort"}},{q="Warum sucht Rhinag nicht einfach einen Schamanen oder Heiler in Sen'jin auf?",a="Rhinag räumt ein, dass ihm sein eigener Stolz im Wege steht. Er fürchtet, eine Rückkehr nach Sen'jin in solch unvorsichtigem, von Gift geschwächtem Zustand würde ihm bei seinen Trollbrüdern nichts als Hohn einbringen, weshalb er stattdessen eine diskrete Arznei von Kor'ghan bevorzugt.",al={"warum nicht nach sen'jin","warum rhinag sen'jin meidet"}},{q="Was geschieht, nachdem Rhinag das Gegengift erhalten hat?",a="Rhinag trinkt das Gegengift und erholt sich, doch damit enden seine Sorgen keineswegs. So wie man Kor'ghan kennt, wird der Heiler von Rhinag verlangen, sich durch weitere zermürbende Prüfungen zu beweisen – das Erlegen von Ebern und Sammeln von Skorpidstacheln –, ehe er wieder vollends in der Gunst des Meisters steht.",al={"überlebt rhinag","rhinag nachwirkungen"}},{q="Wo ist Rhinag zu finden?",a="Er befindet sich in den schroffen Klippen des nordwestlichen Durotar, unweit der Grenzpfade, die gen Westen in das Brachland führen.",al={"rhinag standort","wo ist rhinag"}},{q="Warum eilt diese Rettung so sehr?",a="Das Toxin des Giftschwanzskorpids ist außerordentlich stark; einem unbehandelten Opfer verbleibt weniger als eine Stunde, ehe das Gift die lebenswichtigen Organe überwältigt.",al={"warum zeitbegrenzt","rhinag gift timer"}}},fx={["0710a7b2"]={q="Wozu dient das Siechstachelgegengift?",a="Das Gegengift wirkt dem tödlichen Gift der Siechstachelskorpide entgegen, die im nordwestlichen Durotar lauern. Rhinag wurde während eines unvorsichtigen Scharmützels mit den Bestien tief gestochen und das Toxin durchströmt rasch sein Blut. Ohne diesen speziellen Trank, der von Kor'ghan in Orgrimmar gebraut wird, hat Rhinag weniger als eine Stunde, bevor das Gift sein Leben fordert.",al={"wofür ist das siechstachelgegengift","gebrauch von siechstachelgegengift","warum siechstachelgegengift nötig"}}},fp="15,260,17.452.0,22.425.0,14.270.0,39.310.0,67.251.0,48.282.1,26.127.0,47.148.0"}
P.entries["quest:813"] = {n="Suche nach dem Gegengift",s="Suche nach dem Gegengift ist eine dringliche Aufgabe, die für Kor'ghan in Orgrimmar übernommen wird, um ein Heilmittel für den vergifteten Jäger Rhinag zu brauen. Angesichts einer knappen Frist, bevor das Gift tödlich wirkt, muss ein Abenteurer Giftbeutel von Giftschwanzskorpiden außerhalb der Stadtmauern sammeln. Dies unterstreicht die unerbittliche Natur der Tierwelt Durotars und die Notwendigkeit, sich auf die Wildnis vorzubereiten.",h="Suche nach dem Gegengift ist eine dringliche Aufgabe, die für Kor'ghan in Orgrimmar übernommen wird, um ein...",kw={"gegengift","durotar","kor'ghan","orgrimmar","gift","rhinag","skorpid","giftschwanz"},ang={["class:Hunter"]="Kor'ghan dient allen Jägern als ernste Mahnung: Das Wissen über das Gift einer Bestie und das Mitführen geeigneter Heilmittel ist genauso entscheidend wie Euer Bogen und Eure Fährtenlesekunst.",["faction:Horde"]="Die Horde in Durotar kümmert sich um die Ihren und stellt sicher, dass isolierte Waldläufer und Späher an den Grenzen auf die Festung Orgrimmar vertrauen können, um Hilfe zu erhalten.",["race:Orc"]="Das Überleben in Durotar stellt die Ausdauer der neu angesiedelten Orcs auf die Probe und zeigt, dass selbst ein erfahrener Späher den einheimischen Gefahren des Landes zum Opfer fallen kann, wenn er unvorsichtig ist."},sec={{t="Ein Wettlauf gegen das Gift",b="Während der Jagd in Durotar beging ein Dunkelspeertroll namens Rhinag den verhängnisvollen Fehler, einheimische Giftschwanzskorpide anzugreifen, ohne ein Gegengift mitzuführen. Gestochen und ihren wirkstarken Toxinen rasch erliegend, war er gezwungen, um sofortige Hilfe zu bitten. Die Aufgabe fällt Kor'ghan zu, einem erfahrenen Jäger mit Wohnsitz in Orgrimmar, einen stärkenden Trank zu mischen, bevor das Gift sein Werk vollendet."},{t="Die Herstellung des Heilmittels",b="Die Herstellung eines Gegengifts erfordert die Beschaffung der Quelle des Leidens selbst: die Giftbeutel ausgewachsener Giftschwänze, die vor den Toren von Orgrimmar lauern. Kor'ghan bemerkt, dass es warten muss, Rhinag für seine mangelnde Vorbereitung zurechtzuweisen, da jeder Augenblick zählt. Sobald die Beutel rasch beschafft und in die Stadt zurückgebracht wurden, stellt Kor'ghan den Trank her, damit er auf direktem Weg zum sterbenden Jäger gebracht werden kann."}},faq={{q="Wer ist Rhinag?",a="Rhinag ist ein Jäger der Dunkelspeertrolle in Durotar, der beim Aufspüren von Bestien von einheimischen Giftschwänzen schwer gestochen wurde. Da er in der Wildnis kein Gegengift bei sich trug, war er handlungsunfähig und darauf angewiesen, dass Boten ein Heilmittel aus Orgrimmar herbeischaffen, bevor er dem Gift erliegt.",al={"rhinag lore","wer ist vergiftet","wer braucht das gegengift"}},{q="Wer ist Kor'ghan?",a="Kor'ghan ist ein erfahrener Jäger der Dunkelspeertrolle, der in der Kluft der Schatten in Orgrimmar ansässig ist. Er versteht die natürlichen Bestien von Durotar genauestens und besitzt das alchemistische Wissen, das erforderlich ist, um mithilfe roher Giftbeutel von Giftschwanzskorpiden ein wirksames Gegengift zu brauen.",al={"kor'ghan","wer ist korphan","korgan orgrimmar"}},{q="Woher stammen die benötigten Giftbeutel?",a="Die Giftbeutel werden direkt von Giftschwanzskorpiden erbeutet, die den felsigen, trockenen Boden nahe dem Eingang von Orgrimmar durchstreifen.",al={"wo sind giftgiftinge","fundort des giftbeutels","giftbeutel von giftschwanzskorpiden"}},{q="Warum gibt es für diese Aufgabe ein aktives Zeitlimit?",a="Die Dringlichkeit rührt von Rhinags schwindender Gesundheit in der Wildnis her. Da die Toxine der Giftschwanzskorpide außergewöhnlich virulent und schnell wirkend sind, muss Kor'ghan die Zutaten erhalten und das Heilmittel destillieren, bevor der Jäger einer systemischen Vergiftung erliegt.",al={"warum gibt es ein zeitlimit","need for a cure zeitlimit","zeitquest"}},{q="Welche Lektion betont Kor'ghan während dieser Jagd?",a="Kor'ghan warnt, dass jeder Jäger die Gewohnheiten und tödlichen Gefahren seiner Beute vor dem Angriff sorgfältig studieren muss. Ohne angemessene Vorbereitung oder Gegenmaßnahmen in die Wildnis aufzubrechen, ist ein Versäumnis, das einen Krieger leicht das Leben kosten kann.",al={"kor'ghans lektion","jagdlektion","kor'ghans rat"}},{q="Wie fügt sich diese Aufgabe mit 'Need for a Cure' zusammen?",a="'Need for a Cure' ist der grundlegende Botengang, der den Notfall in Gang setzt und den Zeittimer startet. 'Suche nach dem Gegengift' ist der Zwischenschritt, bei dem der Spieler die Rohkomponenten sammelt, damit Kor'ghan das fertige Gebräu herstellen kann.",al={"verbindung zu need for a cure","vorquest","wie hängt es zusammen"}}},fx={["837950c2"]={q="Warum möchte Kor'ghan, dass dies erledigt wird?",a="Kor'ghan erkennt an, dass Rhinag einen törichten Fehler beging, als er ohne Vorbereitung auf die tödlichsten Skorpide in Durotar jagte, doch er weigert sich, einen der Dunkelspeer wegen schlechten Urteilsvermögens sterben zu lassen. Für Kor'ghan steht das Bewahren des Lebens eines der Ihren vor Zurechtweisungen. Er möchte sofort ein Gegengift brauen, damit Rhinag die tödliche Vergiftung überlebt.",al={"warum rhinag helfen","kor'ghan motiv","warum kümmert sich kor'ghan"}},["20540779"]={q="Wozu dient der Giftbeutel eines Siechstachelskorpiden?",a="Kor'ghan benötigt die frischen Giftbeutel, um ein Gegengift für Rhinag zu destillieren. Indem er die toxischen Komponenten direkt aus den Siechstachelskorpionen in Durotar extrahiert, kann er ein Gegenmittel zusammenbrauen, das stark genug ist, um das schnell wirkende Gift zu neutralisieren, das durch das Blut des vergifteten Jägers strömt.",al={"gebrauch von siechstachel giftbeutel","wofür sind giftbeutel eines siechstachelskorpiden","warum giftbeutel sammeln"}},d062d72d={q="Was sind die Siechstachelskorpide in der Nähe von Orgrimmar?",a="Siechstachelskorpide sind räuberische Skorpide, die in den ariden Ödlanden von Durotar heimisch sind und durch die felsigen Klippen außerhalb von Orgrimmar streifen. Unter den Jägern der Orcs als einige der tödlichsten Kreaturen in der Region bekannt, können ihre toxischen Stiche bei ausbleibender Behandlung schnell töten, was sie zu gefährlichen Bestien macht, die Vorsicht und Respekt erfordern.",al={"was sind siechstachelskorpide","siechstachelskorpid","warum siechstachelskorpide töten"}}},fp="20,368,24.397.0,17.405.0,14.266.0,16.259.0,43.127.0,47.242.0,53.250.0,46.238.0"}
P.entries["quest:815"] = {n="Zerbrecht ein paar Eier",s="Break a Few Eggs ist eine Besorgung, bei der einem gehetzten Koch geholfen wird, der mit den endlosen Essenszubereitungen Schritt halten muss. Das Beschaffen frischer, zerbrechlicher Zutaten, ohne sie zu zerbrechen, hält die Küche am Laufen und das Kochen im Zeitplan.",h="Break a Few Eggs ist eine Besorgung, bei der einem gehetzten Koch geholfen wird, der mit den endlosen...",kw={"break a few eggs","frühstück","koch","kochen","eier","küche","mahlzeiten"},ang={["profession:Cooking"]="Jeder arbeitende Koch kennt den unerbittlichen Druck, Menschen satt zu halten. Das Beschaffen zerbrechlicher Zutaten, ohne sie zu zerschlagen, ist in jeder Küche die halbe Miete."},sec={{t="Endlose Mahlzeiten",b="Eine Menschenmenge zu verköstigen, ist ein anstrengendes, nie endendes Unterfangen. Zwischen Frühstück, Mittagessen und Abendessen bleibt kaum Zeit, vom Herd wegzutreten, geschweige denn die Küche zu verlassen, um nach rohen Vorräten zu suchen. In Break a Few Eggs wendet sich ein bedrängter Koch an vorbeikommende Abenteurer, um frische Eier zu beschaffen, bevor die nächste Essensausgabe in Verzug gerät."},{t="Die Dankbarkeit eines Kochs",b="Der Transport von Eiern erfordert sanftes Fingerspitzengefühl, das rohe Gewalt nicht ersetzen kann. Der Koch mag schroffe Worte und wenig Lob übrig haben, doch unversehrte Zutaten sprechen für sich. Sobald die Eier sicher und unversehrt abgeliefert sind, verliert der Koch keine Zeit, den Sammler wegzuschicken und direkt wieder an die Arbeit über dem Feuer zurückzukehren."}},faq={{q="Was ist die Quest Break a Few Eggs?",a="Break a Few Eggs ist eine kulinarische Aufgabe, bei der ein Abenteurer einem vielbeschäftigten Koch hilft, der von der ständigen Nachfrage nach Mahlzeiten überwältigt ist. Die Aufgabe besteht darin, Eier unversehrt abzuliefern, um sicherzustellen, dass das Kochen nicht hinter den Zeitplan zurückfällt.",al={"break a few eggs quest","was ist break a few eggs","eierquest"}},{q="Wer ist der Koch in Break a Few Eggs?",a="Die Köchin ist Köchin Torka aus Klingenhügel in Durotar, die rund um die Uhr Mahlzeiten zubereitet. Obwohl von schroffer und eiliger Art, ist Torka auf fähige Hände angewiesen, um Eier der Taillasher von den Echoinseln zu beschaffen, ohne sie vor der Essenszeit zu zerbrechen.",al={"wer gibt break a few eggs","eierquest koch","wer kocht"}},{q="Warum braucht der Koch Eier?",a="Der Koch benötigt sie für laufende Essenszubereitungen, sei es Frühstück, Mittagessen oder Abendessen. Menschen zu verköstigen ist eine endlose Pflicht, und frische Eier sind ein unverzichtbares Grundnahrungsmittel in der Küche, das sofort am Herd gebraucht wird.",al={"warum eier","wofür sind eier","warum eier gebraucht werden"}},{q="Warum bemerkt der Koch, man solle nicht ungeschickt sein?",a="Eier sind zerbrechlich und beim Transport leicht zu beschädigen. Der Koch legt ausdrücklich Wert auf jemanden, der nicht ungeschickt ist, da zerbrochene Schalen und ausgelaufenes Eigelb Zutaten ruinieren, die für die Essensausgabe benötigt werden.",al={"warum vorsichtig mit eiern","keine eier zerbrechen","warum nicht ungeschickt"}},{q="Worauf bezieht sich der Titel Break a Few Eggs?",a="Der Name bezieht sich auf das bekannte Sprichwort, dass man keine Omeletts machen kann, ohne ein paar Eier zu zerschlagen; passend für eine Aufgabe, bei der es darum geht, zerbrechliche Küchenzutaten für eine geschäftige Essensausgabe zu beschaffen.",al={"break a few eggs bedeutung","bedeutung redewendung","warum heißt es break a few eggs"}},{q="Warum ist der Koch so ungeduldig?",a="Der Koch ist vollauf damit beschäftigt, mit den ununterbrochenen Mahlzeiten für Frühstück, Mittagessen und Abendessen Schritt zu halten. Da noch so viel zu kochen bleibt, hat der Koch wenig Geduld für müßiges Geplauder und möchte einfach nur zurück an den Herd.",al={"haltung des kochs","warum ist der koch unhöflich","mürrischer koch"}}},fp="16,216,13.344.0,18.311.0,35.225.0,36.235.0,28.203.0,46.178.0,46.187.0,29.219.0"}
P.entries["quest:816"] = {n="Verloren, aber nicht vergessen",s="Verloren, aber nicht vergessen ist eine düstere Quest, die von Misha Tor'kren auf ihrem Gehöft nordwestlich von Klingenhügel vergeben wird. Verzweifelt auf der Suche nach Gewissheit bittet sie Reisende, die gefährlichen Ufer des Südstroms nach jeder Spur ihres eigensinnigen Sohnes Kron abzusuchen.",h="Verloren, aber nicht vergessen ist eine düstere Quest, die von Misha Tor'kren auf ihrem Gehöft nordwestlich...",kw={"amulett","krokilisk","dreadmaw","kron","misha","klingenhügel","südstrom","tor'kren"},ang={["class:Hunter"]="Für Jäger dient Kron als warnendes Beispiel für einen Fährtenleser, der die Wildheit seiner Beute falsch einschätzte und letztlich selbst als Mahlzeit endete.",["faction:Horde"]="Das Leben im frühen Durotar ist hart und unerbittlich; einfache Familien kämpfen hier gegen die unbarmherzige Landschaft und die tödlichen Raubtiere, die an seinen Grenzen streifen.",["race:Orc"]="Krons Schicksal ist eine tragische Erinnerung daran, dass Stolz und kriegerischer Ruhm zwar das Herz der orcischen Kultur bilden, rücksichtslose Arroganz ohne Respekt vor gefährlichen Bestien jedoch zu einem unrühmlichen Tod führt."},sec={{t="Die Furcht einer Mutter",b="Nordwestlich von Klingenhügel, versteckt im kargen roten Ödland von Durotar, liegt das bescheidene Gehöft der Tor'kren. Hier lebt Misha Tor'kren, eine Orcmutter, die vor Kummer und Angst gelähmt ist. Tage zuvor verkündete ihr Sohn Kron, er breche nach Westen zum Südstrom an der Grenze zum Brachland auf, um die wilden Krokilisken des Flusses zu jagen. Trotz ihrer Warnungen vor den tödlichen Bestien trieb ihn sein sturer Stolz dazu, wutentbrannt davonzustürmen, um seinen Mut zu beweisen. Seitdem wurde er nicht mehr gesehen."},{t="Eine grausame Bestätigung",b="Misha bittet vorbeiziehende Abenteurer, die Ufer des Südstroms nach Hinweisen auf Krons Schicksal abzusuchen, und schlägt sogar vor, in die Mägen der Krokilisken zu blicken. Tragischerweise erweisen sich ihre finstersten Vorahnungen als wahr. Das Erlegen der bösartigen Dreadmaw-Krokilisken am Wasser offenbart Krons verschlungenes Amulett. Die Rückgabe des Andenkens an Misha erstickt jeden Funken Hoffnung, dass ihr Junge überlebt hat, verleiht einer trauernden Mutter jedoch endlich die Gewissheit, die sie braucht, um mit der Trauer zu beginnen."}},faq={{q="Wer ist Misha Tor'kren?",a="Misha Tor'kren ist eine orcische Bauersmutter, die auf einem abgelegenen Gehöft nordwestlich von Klingenhügel in Durotar lebt. Geplagt von Kummer und Sorge bittet sie Wanderer, nach jeder Spur ihres verschollenen Sohnes Kron zu suchen.",al={"misha tor'kren","wer vergibt verloren aber nicht vergessen","kron mutter"}},{q="Wer war Kron?",a="Kron war der eigensinnige Sohn von Misha Tor'kren. Um seine Stärke zu beweisen, ignorierte er die Warnungen seiner Mutter und zog aus, um gefährliche Krokilisken nahe dem Südstrom zu jagen, wo er seinen vorzeitigen Tod fand.",al={"wer ist kron","was geschah mit kron","misha sohn"}},{q="Wo verschwand Kron?",a="Kron reiste nach Westen durch Durotar in Richtung der Grenze zum Brachland, um an den Ufern des Südstroms zu jagen.",al={"wo ist kron","wo nach kron suchen","kron aufenthaltsort"}},{q="Wie beweist Ihr Misha Krons Schicksal?",a="Ihr findet Krons verschlungenes Amulett in den Überresten von Dreadmaw-Krokilisken, die in den Gewässern des Südstroms lauern. Dieses geborgene Erbstück zu Misha zu bringen, bestätigt seinen Tod.",al={"krons amulett","hinweis auf krons schicksal","krokilisk magen"}},{q="Welche Belohnung gibt Misha?",a="Misha überreicht Euch ein Geschenk, das sie ursprünglich für Kron vorbereitet hatte, um seine triumphale Rückkehr von der Jagd zu feiern. Da sie es nach der Nachricht von seinem Tod nicht ertragen kann, es anzusehen, übergibt sie es dem Abenteurer, der ihr Gewissheit verschafft hat.",al={"verloren aber nicht vergessen belohnung","misha geschenk"}},{q="Warum ist Kron überhaupt aufgebrochen?",a="Kron wurde von sturem Stolz und dem Wunsch angetrieben, sein jagdliches Können zu beweisen. Als seine Mutter ihn warnte, dass die Krokilisken viel zu bösartig und gefährlich seien, wurde er wütend und stürmte davon, um sie dennoch zu jagen.",al={"warum jagte kron","kron stolz"}}},fx={ad2ab742={q="Warum möchte Misha Tor'kren, dass dies erledigt wird?",a="Misha wird von der Ungewissheit über das Schicksal ihres Sohnes gepeinigt. Kron ist vor Tagen nach einem Streit davongestürmt, entschlossen, sich gegen gefährliche Bestien zu beweisen. Während sie das Schlimmste fürchtet, kann sie nicht beginnen zu trauern oder einen Abschluss zu finden, bevor sie einen definitiven Beweis für sein Schicksal hat.",al={"warum benötigt misha hilfe","misha tor'kren motiv","warum nach kron suchen"}},a54100a0={q="Wozu dient Krons Amulett?",a="Krons Amulett war ein persönlicher Besitz, den Mishas Sohn bei sich trug, als er zur Jagd aufbrach. Aus dem Magen einer Flussbestie geborgen, dient es als düsterer, unbestreitbarer Beweis für seine Mutter, dass Kron entlang des Südstroms erschlagen wurde.",al={"krons amulett hintergrund","was ist das amulett","zweck von krons amulett"}},a107a32d={q="Was sind die Krokolisken entlang des Südstroms?",a="Schreckmaulkrokolisken sind aggressive, mächtige Reptilien, die in den Wasserwegen und schlammigen Ufern heimisch sind, die Durotar vom Brachland trennen. Bösartig und opportunistisch verschlingen sie jede Beute, die töricht genug ist, sich allein in ihre Futtergründe entlang des Flusses zu wagen.",al={"schreckmaulkrokolisken südstrom","warum krokolisken töten","schreckmaulkrokolisken"}}},fp="22,244,16.475.0,19.465.1,22.201.0,13.202.1,26.114.0,38.184.1,28.224.1,38.212.0"}
P.entries["quest:817"] = {n="Praktische Beute",s="Praktische Beute ist ein Jagdauftrag des Lederverarbeiters Vel'rin Fang in Sen'jin. Angesichts einer wachsenden Bevölkerung und schwindender Vorräte muss der Stamm der Dunkelspeer widerstandsfähige Tigerfelle von den benachbarten Echoinseln beschaffen, um lebensnotwendige Unterkünfte, Kleidung und Ausrüstung herzustellen.",h="Praktische Beute ist ein Jagdauftrag des Lederverarbeiters Vel'rin Fang in Sen'jin.",kw={"dunkelspeer","durotartiger","die echoinseln","jagd","lederverarbeitung","praktische beute","sen'jin","tigerfell","vel'rin fang"},ang={["class:Hunter"]="Vel'rins Erzählung über das tagelange, lautlose Ausharren, bevor die Falle zuschnappte, spiegelt unmittelbar die grundlegenden Tugenden von Geduld und Präzision wider, die allen jungen Jägern beigebracht werden.",["faction:Horde"]="Die Unterstützung der jungen Dunkelspeerenklave mit lebenswichtigen Handelsgütern trägt dazu bei, die Südflanke der Horde entlang des Großen Meeres zu sichern.",["race:Troll"]="Für die verbannten Dunkelspeer ist die Jagd auf den Echoinseln eine bittere Erinnerung an ihre verlorene Heimat, wo die Versorgung des Clans erfordert, von Zalazane geraubten Boden zu betreten."},sec={{t="Eine Frage des Überlebens",b="Das Leben an der trockenen Küste von Durotar ist hart, und die nach Sen'jin verbannten Dunkelspeertrolle müssen jede Ressource voll ausschöpfen. Tigerpelze gehören zu den vielseitigsten verfügbaren Materialien und sind unerlässlich, um Zelte, schwere Decken und verstärkte Rüstungen zusammenzunähen. Da die Siedlung durch Flüchtlinge und zurückkehrende Späher stetig wächst, sind die Vorräte knapp geworden, was Handwerker wie Vel'rin Fang dazu zwingt, neue Jagden in Auftrag zu geben."},{t="Das Gleichgewicht und die Jagd",b="Die Dunkelspeer pflegen eine wohlüberlegte Beziehung zu den Raubtieren ihres Territoriums. Anstatt die einheimischen Durotartiger zu überjagen, lassen die Trolle die Pirscher im Allgemeinen ungestört gedeihen und dezimieren sie nur, wenn die Vorräte des Stammes aufgefüllt werden müssen. Die Reise über das Wasser zu den Echoinseln, um diesen Raubtieren nachzustellen, erfüllt sowohl eine praktische Notwendigkeit als auch eine traditionelle Prüfung von Geduld, Disziplin und Wildnisfertigkeit."}},faq={{q="Wer ist Vel'rin Fang?",a="Vel'rin Fang ist ein Handwerker der Dunkelspeertrolle in Sen'jin, der mit Pelzen und Leder arbeitet. Er weist Jäger an, lebensnotwendige Felle zu sammeln, um den Stamm zu kleiden, zu beherbergen und auszurüsten.",al={"vel'rin fang","wer vergibt praktische beute","velrin fang"}},{q="Warum benötigt Sen'jin Tigerfelle?",a="Die wachsende Bevölkerung von Sen'jin hat die bestehenden Vorräte stark beansprucht. Tigerpelze liefern strapazierfähiges Material für warme Decken, robuste Zelte und Lederrüstungen, um die Dorfbewohner vor den rauen Elementen zu schützen.",al={"warum tigerpelze","zweck von praktische beute","wofür felle verwendet werden"}},{q="Wo sind die Durotartiger zu finden?",a="Die Tiger durchstreifen die Wildnis auf den Echoinseln, der Inselgruppe direkt vor der südöstlichen Küste von Durotar.",al={"wo sind die tiger","tiger standort","echoinseln tiger"}},{q="Warum jagen die Trolle nicht alle Tiger in der Nähe?",a="Vel'rin erklärt, dass die Dunkelspeer ihre Bedürfnisse bewusst mit der lokalen Ökologie in Einklang bringen. Sie lassen die Raubtiere gedeihen, damit die Population nachhaltig bleibt, und greifen nur ein, um sie zu dezimieren, wenn der Materialbedarf des Dorfes ihre Vorräte übersteigt.",al={"warum tiger gedeihen lassen","dezimierung der bestände"}},{q="Hat die Tigerjagd in der Kultur der Dunkelspeer eine Bedeutung?",a="Ja. Das Pirschen auf einen Tiger gilt als Prüfung der Geduld und List. Vel'rin erinnert sich gerne daran zurück, wie er fast einen ganzen Tag lang regungslos im Dickicht der Echoinseln ausharrte, bevor er seinen ersten großen Jagderfolg feiern konnte.",al={"tigerjagd tradition","erste tigerjagd"}},{q="Warum müssen Jäger zu den Echoinseln reisen, wenn Zalazane sie beherrscht?",a="Obwohl der abtrünnige Hexendoktor Zalazane und seine verhexten Diener einen Großteil der Inselgruppe besetzen, sind die wilden Tiere auf den Inseln nach wie vor zahlreich. Das Sammeln von Ressourcen und die Jagd an den äußeren Ufern bleibt für die Dunkelspeer ein notwendiges Risiko.",al={"tiger auf den echoinseln","warum zu den echoinseln"}}},fx={b158745d={q="Wozu wird das Durotartigerfell benutzt?",a="Die Dunkelspeer verarbeiten die Felle zu essenziellen Waren, um ihre wachsende Siedlung zu schützen und zu versorgen. Vel'rin Fang verwendet die Felle, um robuste Lederüstungen, warme Decken und wetterbeständige Zelte zu fertigen, was sicherstellt, dass die Dorfbewohner in Sen'jin geschützt bleiben und nicht erfrieren, wenn die Jahreszeiten wechseln.",al={"gebrauch von durotartigerfell","wofür ist tigerfell","tigerfell practical prey"}}},fp="14,280,20.430.0,20.432.0,20.197.0,41.219.0,35.127.0,48.256.0,51.212.0,65.231.0"}
P.entries["quest:818"] = {n="Ein geistvolles Getränk",s="Meister Vornal aus Sen'jin stellt unerfahrene Abenteurer auf die Probe, indem er Reagenzien verlangt, um sein nachlassendes Augenlicht auszugleichen. Er schickt angehende Schüler aus, um Makruraaugen und Kriecherschleim entlang der Küste von Durotar zu sammeln. Obwohl er den Gedanken verspottet, einen Lehrling aufzunehmen, dient die Aufgabe als bewusste Prüfung von Geduld und Entschlossenheit.",h="Meister Vornal aus Sen'jin stellt unerfahrene Abenteurer auf die Probe, indem er Reagenzien verlangt, um sein...",kw={"alchemie","kriecherschleim","strand der dunkelspeere","durotar","unversehrtes makruraauge","makrura","meister vornal","sen'jin"},ang={["faction:Horde"]="Das Küstengebiet von Durotar bleibt gefährlich für die junge Horde; die Beseitigung aggressiver Makrura und Brandungskriecher sichert die Fischereigebiete rund um Sen'jin.",["race:Orc"]="Vornal zweifelt offen daran, ob Orcs die ruhige Disziplin besitzen, die für die Alchemie erforderlich ist, was die Aufgabe zu einer Gelegenheit macht, zu beweisen, dass die Solidarität der Horde auch gelehrte Geduld umfasst.",["race:Troll"]="Für die Dunkelspeere, die Sen'jin wieder aufbauen, ist es unerlässlich, sich vor älteren Meistern wie Meister Vornal zu beweisen, um die mystischen und alchemistischen Traditionen des Stammes fortzuführen."},sec={{t="Das schwindende Augenlicht eines Meisters",b="Meister Vornal sitzt in Sen'jin, gezeichnet vom Alter und nachlassender Sehkraft. Wo ihm einst urtümliche Magie mühelos von den Fingerspitzen floss, stützt er sich nun stark auf die Alchemie, um seine Wahrnehmung zu schärfen und seine Künste zu wirken. Trotz seines zunehmenden körperlichen Verfalls weigert sich der starrsinnige Troll, einen Lehrling aufzunehmen; er behauptet, weder die Dunkelspeer noch die Orcs von Durotar hätten jemals jemanden hervorgebracht, der seiner Unterweisung würdig wäre."},{t="Die Prüfung der Unerprobten",b="Statt direkter Unterweisung fordert Vornal Rohstoffe von der rauen Küste: unversehrte Makruraaugen und Phiolen mit Kriecherschleim. Unbeschädigte Augen von den gepanzerten, schnappenden Makrura zu erbeuten erfordert präzise Schläge, während das Beschaffen von ausreichend Schleim die Bereitschaft eines Abenteurers testet, mühsame, niedere Arbeiten zu ertragen. Für Vornal geht es bei der Jagd auf diese Küstenbestien weniger um die Reagenzien als darum, jene auszusieben, denen es an Konzentration mangelt."},{t="Ein Maß des Willens",b="Für Meister Vornal sind Zeit und Geduld die wahren Maße für Stärke. Er erwartet von ungestümen Jungen, dass sie der Frustration nachgeben oder die Pflicht gänzlich aufgeben. Wer mit makellosen Zutaten nach Sen'jin zurückkehrt, beweist nicht nur Überlebensfähigkeiten an den gefährlichen Riffen des Kanals der Echoinseln, sondern auch die Disziplin, die nötig ist, um die subtilen Künste der Alchemie zu meistern."}},faq={{q="Wer ist Meister Vornal?",a="Meister Vornal ist ein betagter Trollalchemist und Zauberwirker, der in Sen'jin lebt. Sein Augenlicht schwindet mit dem Alter, was ihn dazu zwingt, alchemistische Lösungsmittel und Gebräue zu nutzen, um Magie zu wirken, die ihm einst leichtfiel.",al={"meister vornal","wer ist vornal","vornal lore"}},{q="Warum benötigt Vornal Makruraaugen und Kriecherschleim?",a="Vornal verlässt sich auf alchemistische Tinkturen, um seine Magie zu unterstützen und seine schwindende Sehkraft auszugleichen. Der Schleim und die unversehrten Makruraaugen dienen als Reagenzien für seine Mischungen und fungieren zugleich als Initiationsprüfung für angehende Lehrlinge.",al={"warum kriecherschleim","warum makruraaugen","was stellt vornal her"}},{q="Warum zögert Vornal so sehr, einen Lehrling auszubilden?",a="Vornal besitzt hohe Ansprüche und wenig Geduld für Arroganz. Er glaubt, dass bisher weder Troll noch Orc die aufrichtige Hingabe und Geduld bewiesen hat, die nötig sind, um von ihm zu lernen, und betrachtet die meisten angehenden Schüler als überheblich und leicht entmutigt.",al={"vornal lehrling","warum kein lehrling","sucht vornal schüler"}},{q="Wo sind diese Kreaturen rund um Sen'jin zu finden?",a="Kriecher und Makrura durchstreifen die Untiefen am Strand der Dunkelspeere und bevölkern die Wasserwege, die das Festland von den vorgelagerten Echoinseln trennen.",al={"wo sind makrura","wo sind kriecher","strand der dunkelspeer bestien"}},{q="Warum müssen die Makruraaugen unversehrt sein?",a="Alchemistische Gebräue, die die Wahrnehmung schärfen, erfordern unbeschädigte Sinnesorgane. Brutale Schläge im Kampf bergen das Risiko, die empfindlichen Augen der Makrura zu zerquetschen, was Präzision und Zurückhaltung vom Jäger verlangt.",al={"unversehrtes auge","makrura unversehrte augen","warum unversehrte augen"}},{q="Welche Lektion versucht Vornal zu erteilen?",a="Vornal glaubt, dass Geduld die wahre Charakterprüfung ist. Indem er eine repetitive und schmutzige Sammelaufgabe entlang der Brandung erteilt, will er sehen, ob ein Neuling der Schwäche und Hast erliegt oder den ruhigen Fokus eines Alchemisten bewahrt.",al={"vornal lektion","bedeutung der quest","geduldsprobe"}}},fx={["4926ebef"]={q="Warum benötigt Meister Vornal einen Abenteurer, anstatt die Reagenzien selbst zu sammeln?",a="Meister Vornal gibt zu, dass sein Sehvermögen mit dem Alter nachlässt, was gefährliche Feldarbeit entlang der Küste nicht ratsam macht. Wichtiger ist, dass er die Aufgabe als bewussten Test nutzt. Vornal weigert sich seit Langem, einen Lehrling anzunehmen, da er glaubt, dass ihm noch kein würdiger Troll oder Orc über den Weg gelaufen ist. Indem er Euch aussendet, um empfindliche Reagenzien von feindseliger Küstenfauna zu ernten, misst er Eure Geduld, Stärke und Willenskraft, um zu sehen, ob Eure Taten Eurem Selbstvertrauen entsprechen.",al={"warum ich vornal","warum benötigt vornal mich","warum einen abenteurer schicken"}},cab96330={q="Was sind die Makrura und Brandungskrabbler, die die Küste von Durotar bedrohen?",a="Makrura sind aggressive, krustazee Humanoide, die in den Gewässern und an den Küsten von Durotar heimisch sind, während Brandungskrabbler wilde, territoriale Krabben sind, die an den Stränden und im seichten Wasser in der Nähe der Echoinseln umherhuschen. Beide bewohnen die Gewässer vor dem Strand der Dunkelspeere, was die Küste für lokale Fischer und Sammler gefährlich macht. Für Meister Vornal sind sie jedoch wertvolle Quellen für spezialisierte alchemistische Reagenzien, die benötigt werden, um seine nachlassenden Sinne auszugleichen.",al={"was sind makrura","makrura durotar","brandungskrabbler sen'jin"}}},fp="16,336,23.409.0,20.445.0,17.369.0,21.225.0,52.240.0,50.245.0,55.146.0,42.197.0,38.240.0"}
P.entries["quest:819"] = {n="Chens leeres Fässchen",s="In der Wildnis des Brachlands liegt weggeworfen ein leeres Fässchen mit der Inschrift von Chen Stormstout. Es zu finden, beginnt eine Reise in die vergangenen Taten des berühmten wandernden Braumeisters, der einst sein kämpferisches Können zur Gründung von Durotar beisteuerte.",h="In der Wildnis des Brachlands liegt weggeworfen ein leeres Fässchen mit der Inschrift von Chen Stormstout.",kw={"brachland","brauen","braumeister drohn","chen stormstout","leeres fässchen","pandaren","ratschet","rexxar"},ang={["faction:Horde"]="Chen Stormstout ist als ein geschätzter Verbündeter in Erinnerung geblieben, der direkt an der Seite von Rexxar und Rokhan kämpfte, um Durotar zu errichten und die Horde in ihren frühesten Tagen zu beschützen.",["profession:Cooking"]="Das Fässchen steht für das Vermächtnis eines meisterhaften Brauers, dessen legendärer Gaumen und die Suche nach seltenen Zutaten Handwerker in ganz Kalimdor inspirierten."},sec={{t="Ein wanderndes Relikt",b="In den trockenen Weiten des Brachlands verteilt stoßen Reisende gelegentlich auf ein verlassenes Holzfass. Anders als die gewöhnlichen Fässer, die von Razormane-Quilboar oder Kolkar-Zentauren zurückgelassen wurden, zeichnet sich dieses Fass durch sorgfältige Handwerkskunst und eine deutliche beschriftete Plakette aus: 'Chen Stormstout - May your spirit be raised and always raise your spirits.' Es ist ein ungewöhnliches Relikt, das unter der Sonne Kalimdors schmort, und jeden, der neugierig genug ist, dazu veranlasst, jemanden mit Kenntnissen im Brauen aufzusuchen, um zu verstehen, wie es dorthin gelangt ist."},{t="Echos der Gründung Durotars",b="Bringt man das Gefäß zu Braumeister Drohn in Ratschet, offenbart sich dessen Herkunft. Drohn erkennt die Handwerkskunst sofort: Es gehörte Chen Stormstout, dem legendären Pandaren-Wanderer, der während der entscheidenden Schlachten, die Durotar für Thralls Horde sicherten, an der Seite von Rexxar reiste. Obwohl Jahre vergangen sind, seit Chen über die rote Erde von Kalimdor wandelte, bleiben seine legendären Braurezepte und sein wandernder Geist lebendige Erinnerungen unter den erfahrenen Brauern des Reiches."}},faq={{q="Was ist Chens leeres Fässchen?",a="Es ist ein ausgemustertes Braufass, das draußen im Brachland gefunden wurde. Es trägt eine Inschrift, die es dem wandernden Pandaren-Braumeister Chen Stormstout widmet.",al={"leeres fässchen","chens fässchen","was ist dieses fass"}},{q="Wer ist Chen Stormstout?",a="Chen Stormstout ist ein schwer fassbarer Pandaren-Braumeister, der Kalimdor weiträumig bereiste. Er ist vor allem dafür bekannt, dem Halb-Oger-Bestienmeister Rexxar während der Verteidigung und frühen Gründung von Durotar geholfen zu haben.",al={"wer ist chen","chen geschichte","pandaren braumeister"}},{q="Zu wem sollte ich das Fässchen bringen?",a="Das Fässchen kann zu Braumeister Drohn gebracht werden, einem Orc-Brauer, der an der Straße nahe Ratschet stationiert ist, Chens Zeichen wiedererkennt und weiß, wie man seine Rezepte nachbraut.",al={"wo fässchen abgeben","wer will chens fässchen","fässchen abgabe"}},{q="Warum liegt Chens Fässchen draußen im Brachland?",a="Chen durchstreifte vor Jahren Kalimdor auf der Suche nach exotischen Zutaten für seine Gebräue, insbesondere während seiner Reisen, auf denen er der heranwachsenden Horde half, ihre neue Heimat gegen die Streitkräfte von Admiral Proudmoore zu sichern.",al={"warum ist das fässchen im brachland","wie kam das fässchen hierher"}},{q="Erscheint Chen Stormstout persönlich?",a="Nein. Chen hat die Region verlassen und wurde schon lange nicht mehr in Kalimdor gesehen. Nur seine alten Fässer, Rezepte und die liebevollen Erinnerungen von Verbündeten wie Drohn und Rexxar sind geblieben.",al={"kann ich chen finden","wo ist chen stormstout","ist chen in classic"}},{q="Was macht Braumeister Drohn mit dem Fässchen?",a="Drohn ist begeistert, das Relikt zu sehen, und nutzt die Gelegenheit, um abenteuerlustige Wanderer herauszufordern, Zutaten von einheimischen Bestien zu sammeln, damit er Chens wirkungsvolle, legendäre Gebräue nachbrauen kann.",al={"drohn questreihe","was passiert als nächstes mit dem fässchen"}}},fp="16,243,17.517.0,28.455.0,25.151.0,23.203.0,29.159.0,43.205.0,38.176.0,43.185.0"}
P.entries["quest:82"] = {n="Erkundung des Giftigen Unterschlupfes",s="Leitender Feldmesser Rutenwünschels möchte wissen, wer der Feind ist. Insekten haben die Wassertümpel trockengelegt, die sich dort befanden, wo heute Der Giftige Unterschlupf liegt, und sonst ist wenig über sie bekannt. Ihr werdet gebeten, fünf Insektenteile von den Centipaar im Unterschlupf zu beschaffen und sie zu Alchimist Pestlezugg nach Gadgetzan zu bringen.",h="Leitender Feldmesser Rutenwünschels möchte wissen, wer der Feind ist.",kw={"centipaar","rutenwünschels","gadgetzan","insekten","der giftige unterschlupf","pestlezugg","tanaris"},sec={{t="Teile aus dem Unterschlupf",b="Nach der Gadgetzan Water Survey wendet sich Leitender Feldmesser Rutenwünschels den Berichten über die Insekten zu. Außer dass sie die Tümpel trockenlegen, die einst dort lagen, wo sich heute Der Giftige Unterschlupf befindet, ist wenig bekannt. Rutenwünschels möchte zuerst erfahren, wer der Feind ist, und bittet Euch, in den Unterschlupf zu gehen, fünf Teile von den dort anzutreffenden Centipaar zu erbeuten und sie zur Untersuchung nach Gadgetzan zu Alchimist Pestlezugg zurückzubringen."},{t="Was Pestlezugg herausfindet",b="Pestlezugg macht sich sofort an die Teile und erklärt sogleich, dass sie keiner bisher gesehenen Insektenform entsprechen, fast so, als würde eine äußere Macht die Insekten kontrollieren. Pestlezugg schickt Euch daraufhin zurück zu Rutenwünschels, da ein Notfall Eure Hilfe erfordert – einer, der womöglich noch mehr der Insekten in Tanaris betrifft."}},faq={{q="Warum möchte Leitender Feldmesser Rutenwünschels Insektenteile haben?",a="Insekten legen die Wassertümpel trocken, die sich einst dort befanden, wo heute Der Giftige Unterschlupf liegt, und sonst ist wenig über sie bekannt. Teile von den Centipaar sollen Pestlezugg dabei helfen herauszufinden, worum es sich bei ihnen handelt.",al={"warum insektenkörperteile sammeln","rutenwünschels insektenkörperteile","zweck des giftigen unterschlupfs"}},{q="Wo sind die Centipaar zu finden?",a="Die Centipaar befinden sich im Giftigen Unterschlupf, wo früher Wassertümpel lagen.",al={"wo ist der giftige unterschlupf","centipaar standort","wo man centipaar findet"}},{q="Wer nimmt die Insektenteile in Gadgetzan entgegen?",a="Alchimist Pestlezugg in Gadgetzan, der sie untersuchen soll.",al={"bei wem abgeben","pestlezugg aufenthaltsort","wer will die insektenkörperteile"}},{q="Was geht diesem Schritt voraus?",a="Es folgt auf die Gadgetzan Water Survey.",al={"vorherige quest","vorausgesetzte quest","was führt hierher"}}},fp="26,308,19.413.0,21.291.1,56.189.0,30.68.0,43.58.0,28.38.0"}
P.entries["quest:821"] = {n="Chens leeres Fässchen",s="Diese Quest führt die legendäre Tradition des Pandarenbrauens im Brachland fort. Braumeister Drohn in Ratschet bietet an, Chen Stormstouts berühmtes, starkes Gebräu nachzubilden, wenn Ihr wilde Zutaten von den einheimischen Bestien sammelt, die durch die Savanne streifen.",h="Diese Quest führt die legendäre Tradition des Pandarenbrauens im Brachland fort.",kw={"braumeister drohn","chen stormstout","fass","ebenenschreiterniere","ratschet","savannenlöwenhauer","brachland","donnerechsenhorn","trogggebräu"},ang={["faction:Horde"]="Chen Stormstout kämpfte Schulter an Schulter mit Rexxar, um beim Aufbau von Durotar zu helfen, was jedem Überbleibsel seiner Reise eine besondere kulturelle Bedeutung für die Horde verleiht.",["profession:Cooking"]="Kulinarische Abenteurer werden die kühne – wenn auch beunruhigende – Schnittmenge aus Grenzlandschlachterei und edler Braukunst zu schätzen wissen, die zur Herstellung legendärer Kalimdor-Spirituosen verwendet wird.",["race:Orc"]="Drohn ist ein Beispiel dafür, wie Orks die uralten Braumeistertraditionen übernommen haben, die direkt von Reisenden weitergegeben wurden, welche das Land an der Seite der frühen Horde durchquerten."},sec={{t="Ein Vermächtnis im Fass",b="Als ein weggeworfenes Fass mit pandarischen Schriftzeichen in die Hände von Braumeister Drohn in Ratschet gelangt, weckt es liebevolle Erinnerungen an den legendären Wanderer Chen Stormstout. Chen gab die Geheimnisse seines namensgebenden Gebräus an Drohns Mentor weiter, der sie wiederum Drohn anvertraute. Für Nichtbrauer mag das Rezept ungewöhnlich klingen, doch es verlangt nach rohen, kraftvollen Zutaten direkt aus der unbändigen Tierwelt des Brachlands."},{t="Ernte in der Savanne",b="Das Brauen von Chens starkem Trunk erfordert eine unorthodoxe Reihe von Bestandteilen: Ebenenschreiternieren, die Hauer eines Savannenlöwen und das Horn einer Donnerechse. Die Beschaffung dieser Gegenstände verlangt die Jagd durch die staubigen Ebenen und beweist, dass nur die widerstandsfähigsten Bestien die nötige Würze für echtes Brauen nach Pandarenart liefern können. Sobald sie beisammen sind, wird Drohn von Nostalgie erfüllt und bemerkt, dass das Wiederbeleben der alten Rezeptur seinen Magen fast so sehr wärmt wie seine früheren Fuhren Trogggebräu."}},faq={{q="Wer ist Braumeister Drohn?",a="Braumeister Drohn ist ein orkischer Braumeister, der in der Hafenstadt Ratschet stationiert ist. Er erlernte die Braukunst von einem Mentor, der die Rezepte persönlich von dem legendären Wanderer Chen Stormstout erhalten hatte.",al={"braumeister drohn","wer ist drohn","drohn ratschet"}},{q="Warum benötigt ein Bierrezept Tiernieren und Hörner?",a="Pandarische Brautraditionen – und die Anpassungen durch raue Braumeister des Grenzlands – stützen sich oft auf kraftvolle, esoterische Zutaten der heimischen Tierwelt, um ihren starken Tränken Kraft, Schärfe und unverwechselbare natürliche Essenzen zu verleihen.",al={"warum tierische zutaten","ebenenschreiternieren bier","löwenhauer bier"}},{q="Wo sind die benötigten Zutaten zu finden?",a="Alle drei Bestandteile werden von der heimischen Fauna des Brachlands erbeutet. Ebenenschreiter und Savannenlöwen streifen durch die offenen Grasländer, während Donnerechsen typischerweise in trockeneren oder felsigeren Abschnitten der Ebenen grasen.",al={"wo findet man hauer","wo gibt es donnerechsen","brauzutaten finden"}},{q="Wer war Chen Stormstout?",a="Chen Stormstout ist ein wandernder pandarischer Braumeister, der während der Gründung von Durotar durch Kalimdor reiste, der Horde half und nach exotischen, seltenen Zutaten suchte, um seine kräftigen Biere zu perfektionieren.",al={"wer ist chen","chen stormstout lore","chen"}},{q="Was geschieht, nachdem Drohn die Zutaten übergeben wurden?",a="Die Abgabe der Löwenhauer, Ebenenschreiternieren und des Donnerechsenhorns erfreut Drohn, erinnert ihn an frühere Brautage und leitet direkt die letzte Phase der Wiederherstellung des legendären Trunks ein.",al={"folgequest nach chens leeres fass","drohn belohnung","wie geht es weiter"}},{q="Was ist das Trogggebräu, das Drohn erwähnt?",a="Drohn erinnert sich beim Anblick der wilden Zutaten gern an ein früheres Gebräu namens Trogggebräu – ein Beweis für seine eigenwillige Vergangenheit, im Grenzland herbe, ungewöhnliche Mixturen zu vergären.",al={"trogggebräu","drohn trogggebräu","troggbier"}}},fx={cd71a987={q="Warum möchte Braumeister Drohn diese Zutaten?",a="Braumeister Drohn möchte das legendäre Gebräu von Sturmbräu nachbilden, ein exotisches und starkes Getränk, das von Chen Sturmbräu an Drohns Mentor und schließlich an ihn weitergegeben wurde. Das Zubereiten des Gebräus ist ein Akt der Nostalgie und des Stolzes für Drohn, der schöne Erinnerungen an berühmte frühere Mixturen weckt und die Techniken ehrt, die von dem wandernden Pandarenmeister hinterlassen wurden.",al={"warum möchte drohn dies","drohn motiv","warum das gebräu machen"}}},fp="16,247,17.400.0,23.473.1,24.197.0,56.232.0,44.237.0,24.202.0,53.205.0,38.191.0"}
P.entries["quest:822"] = {n="Chens leeres Fässchen",s="Nach der Herstellung des wirkungsvollen Stormstout bietet Braumeister Drohn in Ratschet an, ein weiteres esoterisches Rezept zu brauen, das er von dem schwer fassbaren Pandaren-Wanderer Chen Stormstout gelernt hat. Dieses potente Gebräu, bekannt als Trogg-Bier, erfordert seltene Organe und Drüsen von den einheimischen Bestien des Brachlands.",h="Nach der Herstellung des wirkungsvollen Stormstout bietet Braumeister Drohn in Ratschet an, ein weiteres...",kw={"brachland","braumeister drohn","chen stormstout","chens leeres fässchen","kodoleber","ratschet","gewitterhaut","donnerfalke","trogg-bier"},ang={["faction:Horde"]="Chen Stormstout kämpfte während der Verteidigung von Durotar an der Seite der Horde und hinterließ bei Orks wie Drohn, die ihm in jenen frühen Tagen begegneten, einen bleibenden Eindruck.",["profession:Cooking"]="Kulinarische Puristen mögen vor Trogg-Bier zurückschrecken, doch das Gewinnen reichhaltiger Innereien und potenter Drüsen spiegelt die Kochtradition der Grenze wider, bei der von einer Beute nichts verschwendet wird.",["race:Orc"]="Braumeister Drohn vertritt einen für einen Ork ungewöhnlichen Beruf, da er Chens exotische Braumethoden traditionellen Kriegerpfaden vorzog und sein Geschäft in Ratschet aufbaute."},sec={{t="Eine zweite Pandarenformel",b="Nachdem Ihr Braumeister Drohn dabei geholfen habt, das ursprüngliche Gebräu des legendären Chen Stormstout nachzubrauen, enthüllt der Ork-Braumeister, dass der wandernde Pandare mehr als nur ein Geheimnis mit ihm geteilt hat. Drohn besitzt die Formel für ein exzentrisches Getränk namens Trogg-Bier. Im Gegensatz zu alltäglichen, aus Getreide destillierten Spirituosen basiert dieses eigentümliche Gebräu vollständig auf wirkungsvollen organischen Reagenzien, die den wildesten Bestien in Zentral-Kalimdor abgewonnen werden."},{t="Die Zutaten des Trogg-Biers",b="Um dieses beißende und belebende Gebräu herzustellen, benötigt Drohn gewaltige Komponenten: Blitzdrüsen von Gewitterhäuten, eine Donnerfalkenspeicheldrüse von großen Donnerfalken sowie eine kräftige Leber von den umherstreifenden Kodos der Ebenen. Einmal destilliert, ergibt die Mischung ein intensiv stimulierendes Getränk, das wie geschaffen für das Überleben in der Wildnis ist."},{t="Eine dauerhafte Partnerschaft",b="Drohns Handwerk endet nicht mit einer einzigen Fuhre. Da er die Nachfrage unter den reisenden Abenteurern und Söldnern erkennt, die durch die neutrale Hafenstadt Ratschet ziehen, lässt Drohn die Vereinbarung dauerhaft bestehen: Er ist bereit, frisches Trogg-Bier zu brauen, wann immer ein Forscher ihm einen neuen Vorrat an Bestienorganen bringt."}},faq={{q="Wer ist Chen Stormstout?",a="Chen Stormstout ist ein schwer fassbarer, wandernder Pandaren-Braumeister, der während der Gründung von Durotar durch Kalimdor reiste. Unterwegs teilte er einige seiner wirkungsvollen Brautechniken mit Drohn in Ratschet, bevor er seine Wanderung fortsetzte.",al={"wer ist chen","chen geschichte","pandare chen"}},{q="Wo befindet sich Braumeister Drohn?",a="Braumeister Drohn hält sich in der neutralen Hafenstadt Ratschet auf, die an der Ostküste des Brachlands liegt. Er verbringt seine Tage damit, exzentrische Gebräue zu verfeinern, die er bei seiner Begegnung mit Chen kennengelernt hat.",al={"drohn aufenthaltsort","wo ist braumeister drohn","drohn nsc"}},{q="Was ist Trogg-Bier?",a="Trogg-Bier ist ein ungewöhnliches und wirkungsvolles Gebräu, das Chen Drohn beigebracht hat. Statt herkömmlichem Hopfen enthält es Tierdrüsen und Organfleisch, was ihm einen berüchtigten Kick verleiht, der wie geschaffen für abgehärtete Abenteurer ist.",al={"trogg-bier","was ist dieses getränk","was braut drohn"}},{q="Wo sammelt man Blitzdrüsen?",a="Blitzdrüsen werden von Gewitterhaut-Bestien erbeutet, die die trockenen Weiten des Brachlands durchstreifen und natürliche elektrische Ladungen in ihren Körpern tragen.",al={"blitzdrüse herkunft","gewitterhaut fundort","woher blitzdrüse"}},{q="Welche Bestien hinterlassen Donnerfalkenspeicheldrüsen?",a="Diese Drüsen werden speziell von großen Donnerfalken gesammelt, den majestätischen, schockgeladenen Raubvögeln, die am offenen Himmel über dem Brachland jagen.",al={"donnerfalkenspeicheldrüse","wo sind große donnerfalken","donnerfalke fundort"}},{q="Kann ich Trogg-Bier mehr als einmal brauen?",a="Ja. Braumeister Drohn bleibt jederzeit bereit, weitere Fuhren des Biers anzusetzen, wann immer Abenteurer ihm frische Drüsen und eine Kodoleber liefern.",al={"ist dies wiederholbar","kann ich das noch einmal tun","trogg-bier wiederholen"}}},fx={["72ec56fd"]={q="Warum möchte Braumeister Drohn diese Zutaten?",a="Drohn ist eifrig darauf bedacht, ein weiteres exotisches Rezept zu teilen, das er direkt vom wandernden Braumeister Chen Sturmbräu gelernt hat. Nachdem er Euch bereits durch die Nachbildung von Chens geschätztem Starkbier geführt hat, möchte Drohn eine Charge starkes Troggbier brauen – eine Mixtur mit einem heftigen Kick, die dazu gedacht ist, herzhafte Abenteurer zu stärken und zu unterstützen, die dem gefährlichen Brachland trotzen.",al={"warum möchte drohn dies","braumeister drohn motiv","warum troggbier brauen"}},["63499675"]={q="Wozu dient die Blitzschlagdrüse?",a="Blitzschlagdrüsen sind eine der Zutaten im Rezept für Chens Troggbier. Drohn bittet um fünf, die von Sturmhäuten im Brachland gesammelt werden.",al={"warum blitzschlagdrüse","blitzschlagdrüse gebrauch hintergrund","wofür werden blitzschlagdrüsen benutzt"}},["4ecc81d9"]={q="Wozu dient die Donnerfalkenspeicheldrüse?",a="Drohn benötigt eine Speicheldrüse von einem Großen Donnerfalken, um Chens Troggbier zu brauen. Er erklärt nicht die genaue Rolle der Drüse bei der Zubereitung des Getränks.",al={"warum donnerfalkenspeicheldrüse","gebrauch von donnerfalkenspeicheldrüse","wofür ist donnerfalkenspeichel"}},["315602f6"]={q="Wozu dient die Kodoleber?",a="Eine Kodoleber ist eine der Zutaten, die Drohn für Chens Troggbier benötigt. Er akzeptiert eine Leber von jedem der Kodos im Brachland.",al={"warum kodoleber","kodoleber gebrauch hintergrund","wofür ist die kodoleber"}}},fp="16,301,25.422.0,28.339.0,23.303.1,23.246.0,34.193.0,18.215.0,37.154.0,43.158.0,36.146.0"}
P.entries["quest:823"] = {n="Bericht an Orgnil",s="Bericht an Orgnil ist eine frühe Horde-Quest, die von Meister Gadrin aus Sen'jin vergeben wird. Sie schickt noch unerfahrene Abenteurer nach Norden nach Klingenhügel, um Orgnil Narbenseele vor dem heimtückischen Einfluss des Kults der Burning Blade zu warnen. Diese Depesche hilft dabei, Durotars verstreute Verteidigung gegen die dämonische Verderbnis zu koordinieren, die sich mitten in der Heimat der Orcs zusammenbraut.",h="Bericht an Orgnil ist eine frühe Horde-Quest, die von Meister Gadrin aus Sen'jin vergeben wird.",kw={"burning blade","durotar","meister gadrin","orgnil narbenseele","klingenhügel","bericht an orgnil","sen'jin"},ang={["faction:Horde"]="Diese Aufgabe steht für die unverzichtbare Kommunikation und Zusammenarbeit zwischen den frisch verbündeten Dunkelspeeren und den Orcs von Durotar im Angesicht gemeinsamer Bedrohungen.",["race:Orc"]="Orgnil Narbenseele verkörpert die vorderste Verteidigungslinie Eurer neuen Heimat und stellt sicher, dass dämonische Verderbnis innerhalb der Grenzen Durotars nicht Fuß fassen kann.",["race:Troll"]="Obwohl die Dunkelspeere vollkommen in ihren Kampf gegen Zalazane vertieft sind, beweist Meister Gadrin die Hingabe der Trolle an die Horde, indem er die Anführer der Orcs vor regionalen Gefahren warnt."},sec={{t="Eine koordinierte Verteidigung",b="Während Sen'jin mit seinen eigenen lokalen Sorgen zu kämpfen hat – vor allem mit Zalazanes Verrat auf den Echoinseln –, erkennt Meister Gadrin, dass die Berichte über den Kult der Burning Blade eine weitaus größere Gefahr darstellen. Im Tal der Prüfungen wurde das Geflüster dämonischer Verderbnis aufgedeckt, und der Hexendoktor der Dunkelspeer weiß, dass diesen Bedrohungen nicht isoliert begegnet werden kann. Er schickt reisende Helden die staubige Straße nach Norden nach Klingenhügel, wo die örtlichen Orc-Behörden ein wachsames Auge über ganz Durotar haben."},{t="Orgnil Narbenseele",b="Stationiert im Militärlager von Klingenhügel, ist Orgnil Narbenseele ein Orc, der damit beauftragt ist, Gefahren im Inneren auszumerzen und das zentrale Kernland zu schützen. Wenn Abenteurer Gadrins Warnung überbringen, verliert Orgnil keine Zeit und führt die Berichte aus dem Tal der Prüfungen und aus Sen'jin zusammen. Im Wissen, dass der Schatten der Burning Blade bedrohlich nahe rückt, mobilisiert er rasch Truppen, um die Kultisten zu zerschlagen, bevor deren finstere Rituale das junge Volk ins Wanken bringen können."}},faq={{q="Wer vergibt die Quest Bericht an Orgnil?",a="Meister Gadrin, der Hexendoktor und spirituelle Anführer der Dunkelspeer, der in Sen'jin verweilt, überträgt Euch diese Aufgabe, nachdem Ihr den Trollen bei ihren ersten Problemen vor Ort geholfen habt.",al={"wer vergibt bericht an orgnil","wo gibt es bericht an orgnil","questgeber bericht an orgnil"}},{q="Wo befindet sich Orgnil Narbenseele?",a="Orgnil Narbenseele befindet sich in Klingenhügel, der befestigten Siedlung nördlich von Sen'jin im zentralen Durotar.",al={"wo ist orgnil narbenseele","standort von orgnil narbenseele","orgnil narbenseele finden"}},{q="Warum schickt Euch Meister Gadrin nach Klingenhügel?",a="Meister Gadrin erkennt, dass die im Tal der Prüfungen und in ganz Durotar entdeckten dämonischen Kultaktivitäten eine Bedrohung für alle darstellen, nicht nur für die Trolle. Er schickt Euch zu Orgnil Narbenseele, dem Orc, der für den Schutz der Region vor der Burning Blade zuständig ist.",al={"warum bericht an orgnil","warum nach klingenhügel","zweck von bericht an orgnil"}},{q="Was ist die in der Quest erwähnte Burning Blade?",a="Die Burning Blade ist ein heimtückischer Kult von Dämonenanbetern, der im Verborgenen von Durotar und darüber hinaus agiert. Seine heimliche Präsenz in nahegelegenen Schluchten und Höhlen gefährdet die Sicherheit und Stabilität der noch jungen Horde.",al={"wer ist die burning blade","kult der burning blade","was ist die burning blade"}},{q="Welche Quest folgt auf Bericht an Orgnil?",a="Sobald Ihr den Bericht bei Orgnil Narbenseele in Klingenhügel abgegeben habt, weist er Euch unverzüglich die Quest Dunkle Stürme zu, um die heraufziehende Bedrohung durch die Kultisten zu untersuchen und zu bekämpfen.",al={"folgequest von bericht an orgnil","bericht an orgnil folgequest","was kommt nach bericht an orgnil"}},{q="Welche Voraussetzung muss vor Erhalt dieser Quest erfüllt sein?",a="Sie folgt ganz natürlich auf Eure Ankunft in Sen'jin über die Quest Bericht erstatten in Sen'jin und verknüpft die frühen Entdeckungen im Tal der Prüfungen mit den weiteren Ereignissen in Durotar.",al={"voraussetzung für bericht an orgnil","wie schaltet man bericht an orgnil frei","vorherige quest von bericht an orgnil"}}},fp="16,347,21.502.0,15.482.0,37.175.0,33.120.0,46.258.0,49.215.0,36.165.0,64.169.0"}
P.entries["quest:824"] = {n="Je'neu vom Irdenen Ring",s="Dieser Auftrag weist Horde-Abenteurer an, eine von den Elementaren Eschentals erbeutete, verderbte Wasserkugel zu Je'neu Sancrea vom Irdenen Ring zu bringen. Als Schamane, der sich der elementaren Harmonie verschrieben hat, versucht Je'neu, die sich ausbreitende Verderbnis entlang des Zoramstrands und in der Tiefschwarzen Grotte zu verstehen. Die Untersuchung des Relikts birgt die Hoffnung, die unnatürliche Fäulnis aufzuhalten, die die Gewässer der Region vergiftet.",h="Dieser Auftrag weist Horde-Abenteurer an, eine von den Elementaren Eschentals erbeutete, verderbte...",kw={"beschmutzte wasserkugel","tiefschwarze grotte","der irdene ring","elementare","je'neu sancrea","mastok wutfauch","der zoramstrand","außenposten von zoram'gar"},ang={["class:Shaman"]="Diese Aufgabe berührt unmittelbar die schamanische Pflicht, das elementare Gleichgewicht aufrechtzuerhalten. Die Übergabe der verderbten Kugel hilft einem Mitglied des Irdenen Rings dabei, eine gefährliche spirituelle Krankheit zu ergründen.",["faction:Horde"]="Während die Horde befestigte Lager wie den Außenposten von Zoram'gar in Eschental errichtet, ist das Aufdecken der dunklen Ursprünge hinter der Feindseligkeit der lokalen Elementare von entscheidender Bedeutung für die Sicherung der Küste.",["race:Troll"]="Je'neu Sancrea beweist die tiefe spirituelle Weisheit der Dunkelspeere und setzt seine angestammte Bindung zu den Geistern im Namen des Irdenen Rings ein."},sec={{t="Ein Bote für die Elemente",b="Als seltsame, verseuchte Elementare überall in Eschental aufzutauchen begannen, bemerkten Kundschafter die unnatürliche Macht, die sie antrieb. Unter den Überresten lag eine beschmutzte Wasserkugel, ein intaktes Gefäß, das von verderbter Magie pulsierte. Im Wissen, dass gewöhnlichen Soldaten und Kundschaftern die spirituelle Einsicht fehlte, um eine solche Anomalie zu ergründen, wies Mastok Wutfauch Horde-Reisende an, jemanden mit tiefem Wissen über alte Legenden und Elementarkunde aufzusuchen: Je'neu Sancrea."},{t="Die Augen des Irdenen Rings",b="Je'neu Sancrea gehört dem Irdenen Ring an, einem Orden von Schamanen, der sich dem Erhalt des Gleichgewichts zwischen den Urkräften Azeroths verschrieben hat. Während die Streitkräfte der Horde die Grenze entlang des Zoramstrands bewachen, konzentriert sich Je'neu auf die spirituelle Wunde, die in den nahe gelegenen Tempelruinen der Tiefschwarzen Grotte schwelt. Für ihn ist ein Elementar, der seine Kraft aus einem verdorbenen Gefäß schöpft, nicht bloß eine isolierte Bedrohung, sondern ein alarmierendes Omen, dass unsichtbare, uralte Mächte die natürliche Ordnung pervertieren."}},faq={{q="Wer ist Je'neu Sancrea?",a="Je'neu Sancrea ist ein Trollschamane, der den Irdenen Ring im nördlichen Kalimdor vertritt. Er widmet sein Leben der Zwiesprache mit den Elementen und deren Erforschung und hat sich nahe dem Zoramstrand niedergelassen, um dunkle Unruhen zu untersuchen, die aus der Tiefschwarzen Grotte aufsteigen.",al={"wer ist jeneu","jeneu sancrea lore","was macht jeneu hier"}},{q="Was ist der Irdene Ring?",a="Der Irdene Ring ist eine Organisation von Schamanen, die sich dafür einsetzt, Azeroths Urelemente im Einklang zu halten. Sie erforschen uraltes Wissen, vergessene Geister und alte Legenden, um elementares Chaos zu beheben und spirituelle Verderbnis auf der ganzen Welt zu heilen.",al={"was ist der irdene ring","wer ist der irdene ring","irdener ring geschichte"}},{q="Wo ist Je'neu Sancrea zu finden?",a="Je'neu ist am Außenposten von Zoram'gar an der Küste des Zoramstrands in Eschental zu finden, wo er die elementaren Unruhen erforscht, die aus der nahe gelegenen Tiefschwarze Grotte aufsteigen.",al={"wo ist jeneu","jeneu aufenthaltsort","jeneu sancrea finden"}},{q="Was ist die Beschmutzte Wasserkugel?",a="Die Kugel ist ein magischer Kanal, durch den mächtige Wasserelementare ihre Stärke lenken. Dass eine solche intakt und verderbt aufgefunden wird, deutet darauf hin, dass dunkle Mächte in der Gegend die örtlichen Geister absichtlich verzerren und versklaven.",al={"was ist die kugel","beschmutzte kugel hintergrund","wasserkugel"}},{q="Wer schickt Euch zu Je'neu?",a="Mastok Wutfauch, ein in Eschental stationierter Offizier der Horde, schickt Abenteurer mit dem verdorbenen Relikt zu Je'neu, nachdem er erkannt hat, dass die Armee dessen seltsame magische Natur nicht entschlüsseln kann.",al={"wer startet diese quest","mastok quest"}},{q="Was wird Je'neu mit der Kugel tun?",a="Je'neu nimmt das Gefäß in seine Obhut, damit der Irdene Ring das Wesen seiner Fäulnis untersuchen kann, in der Hoffnung, dass die Nachforschungen einen Weg aufzeigen, die Gewässer zu reinigen und den unruhigen Elementaren der Region wieder Frieden zu bringen.",al={"was geschieht mit der kugel","verderbnis heilen"}}},fx={["5c718e13"]={q="Warum sendet Euch Mastok Wutfauch zu Je'neu?",a="Mastok erkennt, dass die Beschmutzte Wasserkugel weit über seine Fachkenntnis hinausgeht. Das Verstehen verderbter Magie, alter Legenden und gestörter Elementare fällt eindeutig in den Bereich von Der Irdene Ring. Er sendet Euch zu Je'neu Sancrea, weil Je'neu ein lokaler Schamane des Irdenen Rings ist, der über das tiefe elementare Wissen verfügt, das benötigt wird, um die wahre Bedeutung und Bedrohung der Kugel zu entschlüsseln.",al={"mastok wutfauch motiv","warum zu jeneu schicken","warum möchte mastok dies erledigt haben"}}},fp="26,392,28.454.0,28.469.0,22.254.0,25.242.0,34.169.0,33.219.0,35.185.0,35.207.0"}
P.entries["quest:8241"] = {n="Nachschub an feurigem Fluxus: Eisen",s="Nach What the Flux? wendet sich Meisterschmied Burninate dem Auffüllen des schwindenden Vorrats an feurigem Fluxus in der Sengenden Schlucht zu. Burninate möchte Incendosaurusschuppen, Eisenbarren und Kohle und nimmt alles, was Ihr anbieten könnt.",h="Nach What the Flux?",kw={"kohle","feuriger fluxus","incendosaurusschuppe","eisenbarren","meisterschmied burninate","wiederbeschaffung von feurigem fluxus durch eisen","sengende schlucht","thoriumbruderschaft"},sec={{t="Feuriger Fluxus gesucht",b="Meisterschmied Burninate hat keine Zeit für Müßiggang. Feuriger Fluxus geht zur Neige, und Burninate verlangt nach Incendosaurusschuppen, Eisenbarren und Kohle: zwei Schuppen, vier Eisenbarren und Kohle. Burninate nimmt alles, was Ihr anbieten könnt."}},faq={{q="Wer verlangt nach diesen Waren?",a="Meisterschmied Burninate in der Sengenden Schlucht, der die Waren persönlich entgegennimmt.",al={"wer gibt diese quest","burninate feuriger fluxus","wo abzugeben"}},{q="Welche Materialien möchte Burninate?",a="Zwei Incendosaurusschuppen, vier Eisenbarren und etwas Kohle.",al={"welche gegenstände brauche ich","materialien für feurigen fluxus","burninate abgabe gegenstände"}},{q="Was ging diesem Ersuchen voraus?",a="Der Schritt namens What the Flux?, den Burninate Euch zuvor gab.",al={"voraussetzung für diese quest","vorherige quest feuriger fluxus","what the flux voraussetzung"}},{q="Warum möchte Burninate diese Waren?",a="Burninate sagt, der Vorrat an feurigem Fluxus schwinde, und möchte ihn aufgefüllt haben.",al={"warum feuriger fluxus","burninate motivation"}}},fp="38,213,17.222.0,25.78.0,35.54.0,30.69.0,36.78.0"}
P.entries["quest:8242"] = {n="Nachschub an feurigem Fluxus: Schweres Leder",s="Nach What the Flux? widmet sich Meisterschmied Burninate dem Auffüllen der schwindenden Vorräte an Feurigem Fluxus in der Sengenden Schlucht. Burninate verlangt nach Incendosaurusschuppen, Schwerem Leder und Kohle und nimmt alles an, was Ihr anbieten könnt.",h="Nach What the Flux?",kw={"burninate","kohle","feuriger fluxus","schweres leder","incendosaurusschuppe","sengende schlucht","thoriumbruderschaft"},sec={{t="Feuriger Fluxus gesucht",b="Meisterschmied Burninate hat keine Zeit für müßiges Geschwätz. Feuriger Fluxus wird knapp, und Burninate bittet um Incendosaurusschuppen, Schweres Leder und Kohle: zwei Schuppen, zehn Stück Schweres Leder und Kohle. Burninate nimmt alles an, was Ihr anbieten könnt."}},faq={{q="Wer verlangt nach diesen Waren?",a="Meisterschmied Burninate in der Sengenden Schlucht, der die Waren persönlich entgegennimmt.",al={"wer gibt diese quest","burninate feuriger fluxus","wo abgeben"}},{q="Welche Materialien möchte Burninate?",a="Zwei Incendosaurusschuppen, zehn Stück Schweres Leder und etwas Kohle.",al={"welche gegenstände brauche ich","materialien für feurigen fluxus","burninate gegenstände abgeben"}},{q="Was ging dieser Bitte voraus?",a="Der Schritt namens What the Flux?, den Burninate Euch davor gab.",al={"voraussetzung für diese quest","vorherige quest feuriger fluxus","what the flux voraussetzung"}},{q="Warum möchte Burninate diese Waren?",a="Burninate sagt, der Vorrat an Feurigem Fluxus schwinde, und möchte ihn auffüllen.",al={"warum feuriger fluxus","burninate motivation"}}},fp="47,217,17.239.0,25.78.0,35.67.0,30.69.0,36.78.0"}
P.entries["quest:8249"] = {n="Plunderkisten benötigt",s="Im Rabenholdtanwesen hat Fahrad einen endlosen Bedarf an robusten, verschlossenen Behältern, um die aufstrebenden Schurken der Gilde auszubilden. Da die Übungsschlösser des hauseigenen Handwerkers des Anwesens für fortgeschrittene Schüler zu einfach sind, tauscht Fahrad spezielle Wurfmesser gegen jeden ein, der bereit ist, echte schwere Plunderkisten zu beschaffen.",h="Im Rabenholdtanwesen hat Fahrad einen endlosen Bedarf an robusten, verschlossenen Behältern, um die...",kw={"schwere plunderkiste","hillsbrad","plunderkisten","schlossknacken","taschendiebstahl","rabenholdt","fahrad","zan"},ang={["class:Rogue"]="Die Beschaffung dieser schweren Kisten beruht voll und ganz auf der Kunst des Taschendiebstahls bei erfahrenen Widersachern, was Rabenholdt als zentrale Anlaufstelle für die illegalen Fertigkeiten eines Schurken festigt.",["faction:Alliance"]="Obwohl es im umkämpften Gebiet von Lordaeron verborgen liegt, agiert Rabenholdt unabhängig und nimmt Aufträge von Wanderern der Allianz ohne Rücksicht auf Fraktionsgrenzen an.",["faction:Horde"]="Agenten der Horde, die den beschwerlichen Weg in die Berge von Hillsbrad auf sich nehmen, stellen fest, dass Rabenholdt Fraktionsloyalitäten gegenüber völlig gleichgültig ist und nützliche Schmuggelware über alles andere stellt."},sec={{t="Rabenholdts Krallen schärfen",b="In der verborgenen Zuflucht des Rabenholdtanwesens, eingebettet in den Bergen über dem Vorgebirge des Hügellands, hört das Training niemals auf. Meisterdieb Fahrad beaufsichtigt die Ausbildung der Agenten der Gilde und legt großen Wert auf die praktische Beherrschung des Schlossknackens. Während Zan Übungsvorrichtungen für neue Rekruten bereitstellt, hält Fahrad dieses grobe Machwerk für erfahrene Agenten, die im Feld echte, widerspenstige Mechanismen knacken müssen, für völlig ungeeignet."},{t="Eine bemerkenswert offene Vereinbarung",b="Um das Anwesen mit Mechanismen aus der realen Welt zu versorgen, vergibt Fahrad Aufträge für schwere Plunderkisten, die gefährlichen Zielen in ganz Azeroth entwendet wurden. Obwohl nur geschickte Diebe diese Kisten ihren Opfern in der Wildnis entwenden können, beschränkt Fahrad seine Geschäfte nicht ausschließlich auf Schurken. Jeder, der Lieferungen dieser verschlossenen Kisten abliefert – selbst wenn sie bereits um alle größeren Wertsachen erleichtert wurden –, verdient sich Fahrads Gunst und einen Vorrat an tödlich ausbalancierten Wurfklingen des Anwesens, vorausgesetzt, eine symbolische Münze verbleibt darin, um die Initianden zu motivieren."}},faq={{q="Warum will Fahrad diese Plunderkisten?",a="Rabenholdts Schurkenlehrlinge benötigen realistische Mechanismen, um das Schlossknacken zu üben. Fahrad hält die vom ansässigen Handwerker des Anwesens, Zan, hergestellten Übungskisten für jeden jenseits der blutigen Anfänger für viel zu simpel, sodass echte, von gefährlichen Zielen erbeutete Schließkassetten erforderlich sind.",al={"warum plunderkisten","zweck der plunderkisten","warum fahrad kisten will"}},{q="Wo findet diese Aufgabe statt?",a="Der Austausch findet im Rabenholdtanwesen statt, einer geheimen Zuflucht der Diebesgilde, die in den Bergen nördlich des Vorgebirges des Hügellands verborgen liegt.",al={"ort für plunderkisten benötigt","wo ist fahrad","standort von rabenholdt"}},{q="Können nur Schurken diese Quest abgeben?",a="Während die schweren Plunderkisten selbst ursprünglich durch die Schurkenkunst des Taschendiebstahls beschafft werden, nimmt Fahrad Lieferungen von jedem an, der in der Lage ist, sie zum Anwesen zu bringen.",al={"ist das nur für schurken","kann jeder plunderkisten benötigt machen","andere klassen plunderkisten"}},{q="Warum müssen noch Münzen in den Kisten verbleiben?",a="Fahrad besteht darauf, dass in jeder Kiste ein paar Münzen verbleiben, da selbst Schurken in Ausbildung einen praktischen Anreiz und eine spürbare Belohnung brauchen, um ihre Bemühungen beim Schlossknacken anzuspornen.",al={"warum münzen in der kiste lassen","brauchen kisten beute","leere plunderkisten"}},{q="Was bietet Rabenholdt als Gegenleistung?",a="Fahrad belohnt Helfer mit Gildenruf und fein gefertigten Wurfmessern, von denen er sich zynisch wünscht, dass sie direkt ihren Platz im Herzen von jemandem finden.",al={"belohnung für plunderkisten benötigt","was gibt fahrad","rabenholdt wurfmesser"}},{q="Wer ist Zan, über den sich Fahrad beschwert?",a="Zan ist Rabenholdts hauseigener Lieferant für Schlösser. Fahrad hält Zans Übungsmechanismen für primitiv und nur für die unerfahrensten Neulinge anstatt für ernsthafte Agenten geeignet.",al={"wer ist zan","zan rabenholdt","zan schlösser"}}},fx={["45d1fe22"]={q="Warum benötigt Rabenholdt einen außenstehenden Schurken, um Ramschkisten zu beschaffen?",a="Rabenholdts derzeitige Lehrlinge machen noch ihre ersten Gehversuche und verfügen schlichtweg nicht über das Geschick, um auf eigene Faust an komplizierte Schlösser zu gelangen. Die Übungsmechanismen, die von ihrem hauseigenen Tüftler Zan gefertigt werden, sind für fortgeschrittenes Training viel zu primitiv. Fahrad verlässt sich auf versierte Agenten wie Euch, die sich in gefährliches Gebiet vorwagen und echte Schließkassetten mit hoher Sicherheitsstufe stibitzen, welche eine echte Herausforderung darstellen.",al={"warum werde ich nach ramschkisten gefragt","warum winstone wolf mich braucht","warum besorgt rabenholdt sich die ramschkisten nicht selbst"}}},fp="16,321,30.432.0,28.521.0,37.267.0,32.151.0,35.177.0,52.168.0,39.159.0,39.168.0"}
P.entries["quest:825"] = {n="Aus den Wrackteilen geborgen...",s="Gar'Thok aus Klingenhügel weist Späher der Horde an, die versunkenen Überreste der Flotte von Großadmiral Prachtmeer vor der Schipperküste zu plündern. Durch die Bergung fortschrittlicher Gnomenwerkzeuge aus den wässrigen Wracks hofft die Horde, die Ingenieurskunst der Allianz zu analysieren und diesen technologischen Vorteil zu ihrem eigenen Nutzen einzusetzen.",h="Gar'Thok aus Klingenhügel weist Späher der Horde an, die versunkenen Überreste der Flotte von Großadmiral...",kw={"durotar","gar'thok","gnomenwerkzeuge","prachtmeer","klingenhügel","bergungsgut","schipperküste","burg tiragarde","schiffswracks"},ang={["faction:Horde"]="Gar'Thok betrachtet jeden Schrott aus Allianzmetall als doppelten Gewinn: Wissen, um zukünftige Invasionen abzuwehren, und Material für den Aufbau der jungen Nation Durotar.",["profession:Engineering"]="Für Tüftler unterstreicht die Bergung der Gnomenwerkzeuge die frühen technologischen Reibungen zwischen der mechanischen Präzision der Allianz und dem aufkeimenden Handwerk der Horde.",["race:Gnome"]="Obwohl sie von kleiner Statur sind, hinterlassen Gnome überall dort ihre Spuren, wo die Allianz segelt; ihre hochentwickelten Gerätschaften werden von der Horde so sehr geschätzt, dass sie eigene Bergungsmissionen rechtfertigen."},sec={{t="Echos der Flotte",b="Als Großadmiral Daelin Prachtmeer die Seemacht von Kul Tiras nach Kalimdor brachte, verstopften seine Schiffe die Küstenlinie nahe Burg Tiragarde. Nach seiner Niederlage blieben zerschellte Rümpfe entlang der Schipperküste zurück. Während die überlebenden Soldaten der Kul Tiraner die Burg selbst befestigen, liegen die Trümmer ihrer Armada zerbrochen auf den Untiefen und verrotten langsam in den Gezeiten."},{t="Gnomische Apparaturen",b="Die orkische Kriegsführung stützt sich traditionell auf rohe Stärke, Eisen und Blut, doch die Horde erkennt den gefährlichen Vorteil, den der Einfallsreichtum der Allianz bietet. Gnomische Techniker begleiteten die Expeditionsflotten und statteten die Schiffe der Allianz mit komplexen Maschinen und Präzisionsgeräten aus. Gar'Thok versucht, diese versunkenen Werkzeuge zu bergen, damit die Horde die dahinterstehende Mechanik entschlüsseln kann."},{t="Bestimmt für Orgrimmar",b="Die geborgenen Werkzeuge sollen nicht in Klingenhügel verstauben. Gar'Thok veranlasst, dass sie mit einer Karawane direkt nach Orgrimmar transportiert werden. Durch die Nachentwicklung gnomischer Instrumente wollen die Handwerker und Taktiker der Horde Allianzgeräten in kommenden Konflikten besser begegnen und zugleich ihre eigenen aufstrebenden Industrien stärken."}},faq={{q="Warum birgt die Horde Werkzeuge aus diesen Wracks?",a="Die Horde möchte die fortschrittliche Technologie verstehen, die von der Allianz eingesetzt wird. Gnome bauen komplizierte Maschinen für die Streitkräfte der Menschen, und durch das Studium ihrer Werkzeuge können die Taktiker der Horde herausfinden, wie man Geräten der Allianz begegnen und zugleich nützliche Mechanismen für ihre eigenen Handwerker übernehmen kann.",al={"warum gnomen-werkzeuge holen","warum wrack plündern","gar'thok grund für werkzeuge"}},{q="Wessen Schiffe sind vor der Schipperküste gesunken?",a="Die gesunkenen Schiffe gehörten zur Flotte von Großadmiral Daelin Prachtmeer aus Kul Tiras. Nach der Landung an den Küsten von Durotar, um Krieg gegen Thralls neugegründete Nation zu führen, wurden mehrere Schiffe entlang der Küstenlinie östlich von Burg Tiragarde zerstört.",al={"wessen schiffe sind das","wer zerstörte schiffe durotar","prachtmeer flotte trümmer"}},{q="Wohin kommen die geborgenen Werkzeuge nach Klingenhügel?",a="Gar'Thok schickt die geborgenen Gnomenwerkzeuge mit der nächsten Karawane nach Orgrimmar. Dort können Ingenieure und Handwerker die Apparaturen eingehend studieren, um die Verteidigung und Industrie der Hauptstadt zu stärken.",al={"was passiert mit werkzeugen","wohin kommen gnomen-werkzeuge","wer bekommt das bergungsgut"}},{q="Warum befinden sich gnomische Werkzeuge auf menschlichen Kriegsschiffen?",a="Die Gnome sind enge Verbündete der Menschen innerhalb der Großen Allianz und versorgen Marineexpeditionen häufig mit mechanischem Fachwissen, Belagerungsgerät und Präzisionswerkzeugen zur Wartung, um die Kriegsflotten einsatzbereit zu halten.",al={"warum gnom bei menschen","gnom auf prachtmeers schiffen","allianz gnomentechnologie"}},{q="Was ist die Schipperküste?",a="Die Schipperküste ist die östliche Küstenlinie von Durotar, die an Burg Tiragarde vorbeiführt. Sie ist nach den halb versunkenen und zerstörten Schiffen benannt, die nach den Schlachten gegen Prachtmeers Expedition die seichten Gewässer säumen.",al={"wo liegt schipperküste","schipperküste lage","durotar gebiet versunkene schiffe"}},{q="Wie hängt diese Aufgabe mit der Bedrohung bei Burg Tiragarde zusammen?",a="Nachdem die Marinesoldaten der Kul Tiraner beim Angriff auf Burg Tiragarde beseitigt wurden, nutzt Gar'Thok die Gelegenheit, um die verbliebenen Ressourcen der Allianz zu plündern. Das Ausschlachten der nahegelegenen Schiffswracks stellt sicher, dass die Horde von der Niederlage des Feindes profitiert, bevor Plünderer oder die Gezeiten alles fortreißen.",al={"burg tiragarde verbindung","vernichtet die verräter verknüpfung","warum nach tiragarde tun"}}},fp="21,302,19.363.0,20.378.0,22.336.0,51.283.0,46.249.0,49.208.0,46.210.0,26.220.0,58.272.0"}
P.entries["quest:826"] = {n="Zalazane",s="Meister Gadrin von Sen'jin beauftragt Champions der Horde damit, zu den Echoinseln zu reisen, um dem Verrat des Hexendoktors Zalazane ein Ende zu setzen. Durch dunkle Magie in den Wahnsinn getrieben, versklavte Zalazane seine Stammesbrüder und riss die rechtmäßige Heimat der Dunkelspeertrolle an sich, wodurch er sie ins Exil an Durotars Küste zwang.",h="Meister Gadrin von Sen'jin beauftragt Champions der Horde damit, zu den Echoinseln zu reisen, um dem Verrat...",kw={"dunkelspeer","durotar","die echoinseln","verhexter troll","meister gadrin","sen'jin","vol'jin","voodootroll","zalazane"},ang={["class:Shaman"]="Zalazane pervertiert die spirituellen Künste und urzeitlichen Mächte, die von Trollschamanen und Hexendoktoren ausgeübt werden, und wendet bindende Magien gegen seine eigenen Brüder.",["faction:Horde"]="Der Konflikt stellt eine der ersten großen Prüfungen der Einheit für die junge Horde dar und beweist, dass Verbündete aus ganz Durotar zusammenkommen, um den vertriebenen Darkspear tribe zu verteidigen.",["race:Troll"]="Für einen Dunkelspeertroll ist das Erschlagen Zalazanes ein zutiefst persönlicher Akt der Rache und Pflicht, der den Verräter straft, welcher die rechtmäßige Heimat Eures Volkes stahl und Eure Brüder versklavte."},sec={{t="Verrat auf den Inseln",b="Als der Darkspear tribe aus seiner versunkenen Inselheimat floh und Thrall über das große Meer folgte, errichtete er eine Siedlung auf den Echoinseln direkt vor Durotars Südostküste. Zalazane, ein angesehener und mächtiger Hexendoktor des Stammes, verfiel der Machtgier. Mithilfe von Flüchen, die den Geist versklaven, unterwarf er viele seiner Verwandten und zettelte einen gewaltsamen Aufstand an. Die verbliebenen freien Dunkelspeere, angeführt von Vol'jin, wurden über das Wasser aus ihren angestammten Lagern vertrieben und gezwungen, eine vorübergehende Zuflucht in Sen'jin zu errichten."},{t="Die Qual eines Stammes",b="Zalazane begnügte sich nicht damit, den Stamm bloß zu vertreiben. Von seiner Festung auf der Kuppe der größten Echoinsel entsendet er regelmäßig Überfalltrupps über den Kanal, um weitere Dunkelspeere zu verschleppen und sie in seine Knechtschaft zu zwingen. Die Betroffenen werden zu geistlosen Voodoo- und verhexten Knechten, die für den Stamm vollkommen verloren sind. Meister Gadrin betrachtet dies nicht nur als eine Besetzung von Land, sondern als eine existenzielle Bedrohung: Bis Zalazanes abgetrennter Kopf vor die Ältesten gebracht wird, kann kein Dunkelspeer jemals wirklich sicher sein."}},faq={{q="Wer ist Zalazane?",a="Zalazane war einst ein prominenter Hexendoktor unter den Dunkelspeertrollen. Verdorben von einem Hunger nach dunkler Macht, wandte er sich gegen seine Brüder und nutzte gedankenkontrollierendes Voodoo, um Stammesangehörige zu versklaven und die Echoinseln für sich zu erobern.",al={"zalazane lore","wer ist der boss auf den echoinseln","hexendoktor zalazane"}},{q="Warum flohen die Dunkelspeere von den Echoinseln?",a="Zalazane inszenierte einen überraschenden Staatsstreich auf den Inseln und verwandelte Brüder und Schwestern durch üble Zauberei in geistlose Knechte. Vol'jin und den überlebenden freien Dunkelspeeren fehlte die Zahl, um ihren verzauberten Verwandten standzuhalten, und sie zogen sich auf das Festland von Durotar zurück, wo sie Sen'jin als vorübergehende Zuflucht gründeten.",al={"warum sind trolle in sen'jin","hintergrundgeschichte der echoinseln","wie die trolle die echoinseln verloren haben"}},{q="Was geschieht mit den Trollen unter Zalazanes Kontrolle?",a="Der Verstand der Trolle unter seinem Einfluss wurde durch mächtige Flüche völlig zerrüttet. Sie agieren rein als Zalazanes geistlose Diener, patrouillieren auf den Inseln und führen Überfälle auf das Festland durch, um weitere Opfer zu fangen. Meister Gadrin betrachtet sie als für den Stamm völlig verloren, sodass eine Hinrichtung die einzige Gnade bleibt.",al={"verhexte trolle","voodootrolle","können zalazanes knechte geheilt werden"}},{q="Wo befindet sich Zalazane?",a="Zalazane hat sein Lager auf der größten Insel der Kette der Echoinseln aufgeschlagen, direkt östlich vor der Südküste von Durotar. Er patrouilliert zwischen dem hohen Gipfel des zentralen Hügels hinab in die Ansammlung von Trollhütten unmittelbar darunter.",al={"zalazanes aufenthaltsort","zalazane finden","wo ist zalazane"}},{q="Wer vergibt die Quest, Zalazane zu töten?",a="Meister Gadrin, der Stammesälteste in Sen'jin an Durotars Südküste, bietet die Quest an, nachdem Ihr einführende Aufgaben im Umgang mit lokalen Bedrohungen abgeschlossen habt und aus dem Tal der Prüfungen ankommt.",al={"wer startet zalazane","wo man die quest für zalazane bekommt"}},{q="Warum führt Vol'jin den Angriff nicht selbst an?",a="Während Vol'jin den Stamm regiert und die Verteidigung der Dunkelspeere an der Seite von Kriegshäuptling Thrall in Orgrimmar koordiniert, verbleibt Sen'jin unter der lokalen Führung von Ältesten wie Meister Gadrin. Gadrin koordiniert das alltägliche Überleben und heuert fähige Abenteurer an, um gegen den verräterischen Hexendoktor zurückzuschlagen.",al={"wo ist vol'jin","warum kämpft vol'jin nicht gegen zalazane"}}},fx={a3c2387d={q="Wozu dient Zalazanes Kopf?",a="Meister Gadrin verlangt Zalazanes abgetrennten Kopf als unbestreitbaren Beweis für den Untergang des Hexendoktors. Nur wenn er den Kopf mit eigenen Augen sieht, kann Gadrin sicher sein, dass Zalazanes dunkler Einfluss gebrochen ist und der Stamm der Dunkelspeere endlich in Frieden ruhen kann.",al={"zweck von zalazanes kopf","warum zalazanes kopf bringen","zalazanes kopf questgegenstand"}},ae6e25c2={q="Warum möchte Meister Gadrin, dass Zalazane getötet wird?",a="Zalazane ist nicht zufrieden damit, die Echoinseln gestohlen zu haben; er entsendet kontinuierlich seine unterworfenen Trolle über das Wasser, um das Festland zu überfallen, und versklavt weitere Dunkelspeer, um seine Ränge zu verstärken. Meister Gadrin weiß, dass Sen'jin niemals sicher sein wird, solange der abtrünnige Hexendoktor lebt, um ihr Volk zu quälen und zu entführen.",al={"gadrin zalazane warum","warum zalazane töten","warum möchte meister gadrin das"}}},fp="8,295,21.525.0,17.490.0,16.236.0,42.307.0,52.300.0,26.227.0,37.208.0,46.307.0"}
P.entries["quest:827"] = {n="Die Knochenhöhle",s="Diese Aufgabe wurde vom Eremiten Margoz erteilt und führt Abenteurer der Horde in die Höhle Die Knochenhöhle, östlich von Orgrimmar. Die Höhle wurde von Kultisten der Burning Blade überrannt, die schmerzhafte dämonische Geräte verwenden, um sich an dunkle Magie zu binden. Die Sicherstellung dieser verfluchten Artefakte ermöglicht es Margoz, die Präsenz des Kults direkt vor den Toren der Hauptstadt zu untersuchen.",h="Diese Aufgabe wurde vom Eremiten Margoz erteilt und führt Abenteurer der Horde in die Höhle Die Knochenhöhle...",kw={"burning blade","kultisten","dämonisch","durotar","teufelsenergie","margoz","orgrimmar","senghalsband","die knochenhöhle"},ang={["class:Warlock"]="Die Sengenden Halsbänder sind ein Beispiel für rohe, aber wirkungsvolle Teufelsbindungen und gewähren dunklen Zauberwirkern einen Einblick darin, wie der Kult dämonische Opfer in rohe Macht umwandelt.",["faction:Horde"]="Ein dämonischer Kult, der direkt vor den Mauern von Orgrimmar schwelt, bedroht das Herz und die Sicherheit der jungen Horde.",["race:Orc"]="Die Burning Blade verkörpert die dunkle Vergangenheit, die die Orcs jeden Tag hinter sich zu lassen kämpfen; sie von den Felsen Durotars zu vertreiben, ist eine Frage des Überlebens und der Ehre."},sec={{t="Eine Höhle der Schatten",b="Die Knochenhöhle ist eine unheilvolle Höhle, die in den schroffen Hügeln im Nordosten von Durotar liegt. Obwohl sie scheinbar abgelegen ist, befindet sie sich beunruhigend nah an den mächtigen Toren von Orgrimmar. Anstatt wilder Bestien oder bloßer Gesetzloser beherbergen die Kavernen eine Zelle der Burning Blade – jenen schattenhaften dämonischen Kult, der die orcische Gesellschaft schon lange heimsucht. In diesen düsteren Tunneln vollziehen Kultisten unheilige Rituale direkt vor den Augen der Späher des Kriegshäuptlings."},{t="Dämonische Einstimmung",b="Die Kultisten, die in der Knochenhöhle operieren, tragen Searing Collars, Halsreife, die dazu bestimmt sind, ihr eigenes Fleisch zu versengen und zu brandmarken. Laut Margoz ist diese selbst zugefügte Pein keineswegs sinnlose Grausamkeit; die sengenden Qualen und die in das Metall eingebettete Teufelszauberei dienen dazu, die Träger auf dämonische Macht einzustimmen. Durch die Beschaffung dieser Artefakte beabsichtigt Margoz, die genauen Zauber und Bindungen zu entschlüsseln, die den Rängen der Burning Blade ihre Macht verleihen."},{t="Die drohende Gefahr",b="Die Entdeckung des Geheimnisses hinter den Halsbändern bestätigt, dass die Präsenz des Kults in Durotar wohlüberlegt und organisiert ist. Die Burning Blade agiert nicht einfach als versprengte Räuberbande; ihre Zaubereien reichen tief und stellen eine aktive, heimtückische Bedrohung für die neu errichteten Gebiete der Horde dar. Die Analyse der Halsbänder setzt eine Kette von Nachforschungen in Gang, die direkt in die schattenhaften Zirkel von Orgrimmar selbst führt."}},faq={{q="Wo befindet sich die Knochenhöhle?",a="Die Knochenhöhle ist eine Küstenhöhle im Nordosten von Durotar, eingebettet an der Küstenlinie östlich von Orgrimmar und nördlich von Sen'jin. Sie ist an der schroffen Felswand zu erkennen, die den Eingang einrahmt.",al={"standort der knochenhöhle","wo ist die knochenhöhle","knochenhöhle durotar"}},{q="Wer ist die Burning Blade?",a="Die Burning Blade ist ein gefährlicher Kult aus Orcs und Teufelsanbetern, der dämonischen Wesenheiten und dunkler Magie verschrieben ist. Obwohl sich die moderne Horde von der dämonischen Knechtschaft losgesagt hat, praktizieren Splittergruppen wie die Burning Blade weiterhin verbotene Rituale, um die Horde aus den Schatten heraus zu verderben.",al={"was ist die burning blade","wer sind die kultisten der burning blade","burning blade geschichte"}},{q="Wozu nutzen die Kultisten die Searing Collars?",a="Die Kultisten tragen die feurigen Metallringe um den Hals, um ihr eigenes Fleisch zu verbrennen. Margoz vermutet, dass dieser rituelle Schmerz und die dämonische Verzauberung es ihnen ermöglichen, dunkle Teufelsenergien zu kanalisieren und sich auf sie einzustimmen.",al={"zweck der sengenden halsbänder","warum sengende halsbänder getragen werden","was sind sengende halsbänder"}},{q="Wer ist Margoz?",a="Margoz ist ein orkischer Eremit, der in einem kleinen Lager auf den Klippen von Durotar nahe der Knochenhöhle lebt. Er behält die Bewegungen der Kultisten entlang der Küste im Auge und arbeitet daran, die dunklen Machenschaften der Burning Blade zu zerschlagen.",al={"wer ist margoz","margoz durotar","margoz questgeber"}},{q="Warum duldet die Horde den Kult so nah an Orgrimmar?",a="Sie dulden es nicht wissentlich. Der Kult agiert in strengster Geheimhaltung und verbirgt sich in Höhlen und öden Schluchten, die reguläre Patrouillen nur selten erreichen. Abenteurer werden gerade deshalb zur Untersuchung entsandt, weil es den Kultisten gelingt, ihre Stützpunkte zu verbergen, bis ihre dunklen Rituale beginnen.",al={"warum die knochenhöhle nahe orgrimmar liegt","burning blade nahe orgrimmar"}},{q="Was geschieht, nachdem Margoz die Halsbänder untersucht hat?",a="Margoz beabsichtigt, die Searing Collars zu untersuchen. Die Untersuchung wird mit der Quest Neeru Fireblade in Orgrimmar fortgesetzt.",al={"nächste quest nach der knochenhöhle","wohin die halsbänder führen","margoz zauber"}}},fx={cfe1a49d={q="Warum will Margoz die Searing Collars?",a="Margoz glaubt, dass die Kultisten sich durch das Verbrennen ihrer Haut mit diesen Halsbändern an dämonische Mächte binden. Er benötigt eine Sammlung intakter Halsbänder, um sie mit seiner Magie zu untersuchen und zu prüfen, in der Hoffnung, die dunklen Geheimnisse hinter der Burning Blade aufzudecken und zu enthüllen, wie tief ihre dämonische Verderbnis reicht.",al={"warum braucht margoz die halsbänder","margoz searing collars motiv","warum searing collars sammeln"}},["50396613"]={q="Gegen wen werden Ihr in Die Knochenhöhle ausgesandt?",a="Ihr werdet gegen die Kultisten der Burning Blade ausgesandt, die sich in Die Knochenhöhle verstecken, einer Höhle östlich von Orgrimmar. Sie haben sich dort unter der Nase der Horde versammelt, um abscheuliche Rituale durchzuführen, sich an dämonische Meister zu binden und Pläne gegen die Sicherheit von Durotar zu schmieden.",al={"wer ist in die knochenhöhle","die knochenhöhle gegner","burning blade kultisten die knochenhöhle"}}},fp="10,347,16.432.0,18.420.0,18.403.1,28.201.0,25.286.0,49.217.0,14.217.0,56.279.0,47.119.1"}
P.entries["quest:8273"] = {n="Orans Dankbarkeit",s="Nach Rin'ji's Secret findet die Questreihe, die mit Rin'ji is Trapped! begann, ihren Abschluss bei Oran Snakewrithe, dem Ihr eine Tafel bringt.",h="Nach Rin'ji's Secret findet die Questreihe, die mit Rin'ji is Trapped!",kw={"dunkle fürstin","hinterland","oran snakewrithe","overlook cliffs","rin'ji","tafel"},sec={{t="Eine Tafel für Oran",b="Rin'ji is Trapped! begann diese Reihe, und Rin'ji's Secret war der Schritt unmittelbar vor diesem. Oran Snakewrithe ist derjenige, der die von Euch getragene Tafel entgegennimmt."},{t="Orans Antwort",b="Oran fragt, wo die Tafel aufgetaucht ist, und Ihr berichtet von einer kleinen, verlassenen Insel an den Klippen des Rundblicks. Oran findet dies höchst interessant, verstaut die Tafel sorgfältig und sagt, dass die Dunkle Fürstin über diese Entdeckung sehr erfreut sein wird."}},faq={{q="Wer ist Oran Snakewrithe?",a="Oran Snakewrithe ist derjenige, der die Reihe abschließt, die mit Rin'ji is Trapped! begann und über Rin'ji's Secret weiterführte.",al={"oran","wer ist oran","oran snakewrithe lore"}},{q="Was geht dem in der Reihe voraus?",a="Davor kommt Rin'ji's Secret, und davor Rin'ji is Trapped!.",al={"vorherige quest","voraussetzung für oran's gratitude","wie man oran's gratitude beginnt"}}},fp="16,137,17.154.0,13.233.1,24.120.0,36.68.0"}
P.entries["quest:828"] = {n="Margoz",s="Margoz ist eine Horde-Quest, die Abenteurer damit beauftragt, einen abgeschieden lebenden Orcschamanen aufzusuchen, der über die nördlichen Ausläufer von Durotar wacht. Nach der Konfrontation mit der Teufelsverderbnis in der Schlucht weist Orgnil Narbenseele die Champions an, Margoz zu Rate zu ziehen, bevor sie eine nahegelegene Hochburg der Kultisten angreifen. Der weise Einsiedler erteilt entscheidende Ratschläge bezüglich des wachsenden Schattens, den die Burning Blade wirft.",h="Margoz ist eine Horde-Quest, die Abenteurer damit beauftragt, einen abgeschieden lebenden Orcschamanen...",kw={"burning blade","staubwindklamm","durotar","margoz","orgnil narbenseele","orgrimmar","schamane","die knochenhöhle"},ang={["class:Shaman"]="Margoz verkörpert die alte, geduldige Weisheit des Schamanismus, die an den Rändern der Wildnis wacht, um spirituelle Verderbnis wahrzunehmen, bevor sie sich zu einem Krieg auswächst.",["faction:Horde"]="Die Warnung von Margoz verdeutlicht die Verwundbarkeit von Orgrimmar und beweist, dass Dämonenkulte in Schlagdistanz zum Herzen der Horde lauern.",["race:Orc"]="Die Begegnung mit Margoz erinnert orcische Krieger an die anhaltende Verlockung der Teufelsmacht und mahnt die neue Generation, einen reinen und ehrenhaften Pfad zu beschreiten."},sec={{t="Die Wacht eines Einsiedlers",b="Nachdem Orgnil Narbenseele die Ausmaße der Teufelsverderbnis am Donnergrat erkannt hat, wird ihm bewusst, dass rohe Gewalt allein nicht genügen wird, um Durotar zu säubern. Er schickt seine Champions zu Margoz, einem erfahrenen Orcschamanen, der ein einsames Lager in den Klippen nordöstlich von Klingenhügel unterhält. Zwischen den schroffen Höhen der Staubwindklamm und dem östlichen Meer wacht Margoz über finstere Omen, die den geschäftigen Kriegern von Orgrimmar oft entgehen."},{t="Die Bedrohung durch die Knochenhöhle",b="Margoz verfügt über entscheidende Informationen über die wahre Machtbasis der Burning Blade im nördlichen Durotar: ein verborgenes Höhlensystem namens Die Knochenhöhle, das direkt in die Bergklippen außerhalb der südlichen Tore von Orgrimmar geschlagen wurde. Durch die Unterredung mit Margoz erfahren Reisende, dass die Kultisten viel näher an Thralls Hauptstadt operieren, als es den Wachen des Kriegshäuptlings bewusst ist. Der Schamane stellt sicher, dass niemand, der zur Säuberung des Zirkels ausgesandt wird, blindlings in einen dämonischen Hinterhalt gerät."}},faq={{q="Wer ist Margoz?",a="Margoz ist ein weiser, der Horde loyaler Orcschamane, der in einem abgelegenen Lager im nordöstlichen Durotar lebt. Er studiert die Bewegungen dunkler Magie und überwacht die dämonische Verderbnis, die sich in der Region ausbreitet.",al={"margoz lore","wer ist margoz","margoz nsc"}},{q="Wo finde ich Margoz?",a="Margoz lagert in den zerklüfteten Hügeln des nordöstlichen Durotar, gelegen zwischen der Staubwindklamm und der östlichen Küste, direkt südöstlich von Orgrimmar.",al={"margoz aufenthaltsort","margoz finden","wo ist margoz"}},{q="Warum schickt mich Orgnil Narbenseele zu Margoz?",a="Orgnil weiß, dass Margoz viel Zeit damit verbracht hat, die örtlichen Kultisten der Burning Blade zu studieren. Bevor er Euch ausschickt, um deren Hochburg anzugreifen, möchte Orgnil, dass Ihr Margoz' spirituelle Weisheit und praktischen Rat einholt.",al={"warum mit margoz sprechen","orgnil narbenseele margoz"}},{q="Was ist Die Knochenhöhle?",a="Die Knochenhöhle ist eine verborgene Berghöhle direkt südlich der östlichen Mauern von Orgrimmar. Sie dient der Burning Blade als befestigter Zirkel, in dem dämonenanbetende Kultisten direkt vor den Augen der Horde ihre Rituale abhalten.",al={"die knochenhöhle lore","was ist die knochenhöhle"}},{q="Was geschieht, nachdem man Margoz gefunden hat?",a="Sobald Ihr Euch bei Margoz meldet, erkennt er Eure wachsende Stärke an und beauftragt Euch sogleich damit, Die Knochenhöhle zu betreten, um die Kultisten zu erschlagen und ihre verderbten Abzeichen zu beschaffen.",al={"nächste quest nach margoz","margoz folgequest"}},{q="Gehört Margoz zur Burning Blade?",a="Nein. Margoz ist ein ergebener Schamane der Horde, der sich der Beseitigung dämonischen Einflusses verschrieben hat und junge Champions auf einem ehrenhaften, unverderbten Pfad hält.",al={"ist margoz böse","ist margoz ein kultist"}}},fp="6,392,16.446.0,24.462.0,14.205.0,23.154.0,43.222.0,19.209.0,34.174.1,36.147.0"}
P.entries["quest:829"] = {n="Neeru Feuerklinge",s="Diese Quest schickt Horde-Abenteurer von Margoz in Durotar in die schattige Unterwelt von Orgrimmar. Betraut mit einem dämonischen Senghalsband, das dem Kult der Burning Blade abgenommen wurde, werdet Ihr zu Neeru Feuerklinge geschickt, einem prominenten Hexenmeister in der Kluft der Schatten, der behauptet, dunkle Künste nur zum Schutz der Horde zu studieren.",h="Diese Quest schickt Horde-Abenteurer von Margoz in Durotar in die schattige Unterwelt von Orgrimmar.",kw={"burning blade","die kluft der schatten","durotar","margoz","neeru feuerklinge","orgrimmar","senghalsband","die knochenhöhle","hexenmeister"},ang={["class:Shaman"]="Margoz' Eingeständnis markiert eine klare Grenze zwischen Schamanismus und dämonischer Magie: Die Elemente kommunizieren nicht mit Teufelsartefakten, was die Hilfe eines Hexenmeisters erforderlich macht.",["class:Warlock"]="Das Betreten der Kluft der Schatten, um Neeru Feuerklinge zu konsultieren, bringt Euch in direkten Kontakt mit dem prominentesten Hexenmeister in Orgrimmar und bestätigt den pragmatischen Wert Eures verbotenen Handwerks für die Horde.",["faction:Horde"]="Diese Mission demonstriert den brüchigen Waffenstillstand innerhalb von Orgrimmar, wo die Schamanen des Kriegshäuptlings sich gelegentlich an schattenhafte Ausgestoßene in der Kluft der Schatten wenden müssen, um Durotar vor der Vernichtung zu bewahren."},sec={{t="Die Grenzen eines Schamanen",b="Nachdem er Senghalsbänder von den Kultisten geborgen hat, die in der Knochenhöhle lauern, stellt der Schamane Margoz fest, dass das Entschlüsseln ihrer finsteren Zauberei seine uralten Künste übersteigt. Schamanen kommunizieren mit den Elementargeistern und der Erde, während diese Artefakte nach unverhohlener dämonischer Verderbnis stinken. Da Margoz erkennt, dass das Verständnis der Artefakte der Burning Blade jemanden erfordert, der in den okkulten Künsten bewandert ist, schickt er Euch los, um einen in der Hauptstadt ansässigen Hexenmeister aufzusuchen."},{t="In die Kluft der Schatten",b="Unter den roten Klippen von Orgrimmar liegt die Kluft der Schatten, eine dämmrige Höhle, in der Ausüber verbotener Magie unter Thralls wachsamen Augen ihrem Handwerk nachgehen. Dort haust Neeru Feuerklinge, ein einflussreicher Hexenmeister der Orcs, der beteuert, dass seine Beherrschung der Teufelskräfte einzig darauf abzielt, dämonische Bedrohungen zu vereiteln. Ihm das Beispielhalsband zu überreichen, weckt sofort seine Neugier und bringt die Untersuchung des Kults in Durotar direkt in das Herz der Hexenmeister-Enklave."}},faq={{q="Warum schickt mich Margoz zu einem Hexenmeister?",a="Margoz ist ein Schamane, dessen Kräfte von den Elementen und den Geistern der Ahnen stammen. Die Senghalsbänder aus der Knochenhöhle sind rein dämonischer Natur, und das Ergründen ihrer Verzauberungen und Ursprünge erfordert jemanden, der in Teufelsmagie und den dunklen Künsten geschult ist.",al={"warum hexenmeister","warum neeru","margoz hexenmeister"}},{q="Wo finde ich Neeru Feuerklinge?",a="Neeru Feuerklinge befindet sich in der Kluft der Schatten, dem unterirdischen Höhlenkomplex unter Orgrimmar, wo sich Hexenmeister, Schurken und Schattenwirker versammeln.",al={"neeru aufenthaltsort","wo ist neeru feuerklinge","die kluft der schatten neeru"}},{q="Kann man Neeru Feuerklinge vertrauen?",a="Margoz selbst hegt Zweifel und merkt an, dass Neeru zwar behauptet, seine okkulten Forschungen seien harmlos und dienten nur dem Kampf gegen Dämonen, ob dies jedoch wahr oder falsch ist, bleibt abzuwarten. Thrall duldet Hexenmeister in Orgrimmar unter strenger Aufsicht, doch Vorsicht ist geboten.",al={"ist neeru böse","neeru vertrauenswürdig","kann ich fireblade vertrauen"}},{q="Was ist das Beispielhalsband?",a="Das Beispielhalsband ist eines der Senghalsbänder, die den Kultisten der Burning Blade in der Knochenhöhle abgenommen wurden. Margoz gibt es Euch, damit Ihr es Neeru Feuerklinge direkt zur magischen Analyse überbringt.",al={"beispielhalsband","was ist das halsband","senghalsband questgegenstand"}},{q="Was geschieht, nachdem man Neeru das Halsband übergeben hat?",a="Neeru untersucht das Halsband eingehend, was zur Quest Ak'Zeloth führt, in der er Euch tiefer in die Ermittlungen um die schattenhafte Präsenz des Kults in Durotar schickt.",al={"folgequest nach neeru","was macht neeru","questreihe nach neeru"}},{q="Warum erlaubt die Horde Hexenmeister in Orgrimmar?",a="Kriegshäuptling Thrall duldet Hexenmeister aus pragmatischer Notwendigkeit und hält sie in der unterirdischen Kluft der Schatten fest, damit ihre gefährlichen Forschungen überwacht, kontrolliert und gelegentlich genutzt werden können, um dämonische Feinde zu verstehen.",al={"warum sind hexenmeister erlaubt","hexenmeister in die kluft der schatten","thrall hexenmeister"}}},fx={["273c9fa7"]={q="Warum schickt Margoz Euch, anstatt selbst zu gehen?",a="Margoz bleibt außerhalb von Klingenhügel stationiert, um über die spirituellen Unruhen in Durotar zu wachen. Ihr seid der Abenteurer, der die Searing Collars aus Die Knochenhöhle geborgen hat, was Eure Fähigkeit im Umgang mit den dunklen Artefakten des Kults beweist. Da er ihre dämonischen Machenschaften nicht allein durch Schamanismus ergründen kann, verlässt er sich darauf, dass Ihr schnell ein Exemplar zu Die Kluft bringt.",al={"warum ich margoz","warum zu neeru geschickt","warum geht margoz nicht nach orgrimmar"}}},fp="15,317,17.439.0,24.451.0,37.267.0,33.151.0,31.258.0,27.185.0,46.160.0,47.234.0"}
P.entries["quest:83"] = {n="Feine Leinenwaren",s="Feine Leinenwaren ist eine Aufgabe im Wald von Elwynn, die von der Schneiderin Sara Roderwald im Holzfällerlager des Osttals angeboten wird. Da sie Stoff benötigt, bittet sie vorbeikommende Abenteurer, die örtlichen Defias-Banditen zur Strecke zu bringen und ihnen ihre Leinenkopftücher abzunehmen. Im Gegenzug nutzt sie das wiedergewonnene Tuch, um nützliche Waren für Reisende zu schneidern.",h="Feine Leinenwaren ist eine Aufgabe im Wald von Elwynn, die von der Schneiderin Sara Roderwald im...",kw={"sackleinen","bruderschaft der defias","holzfällerlager des osttals","wald von elwynn","rotes leinenkopftuch","feine leinenwaren","sara roderwald","schneiderei"},ang={["faction:Alliance"]="Das Ausräuchern der Defias-Banditen in den Hainen von Elwynn bringt nicht nur nützliches Material für das Osttal ein, sondern schwächt auch aktiv den Einfluss der Bruderschaft auf das Kernland des Königreichs.",["profession:Tailoring"]="Sara Roderwalds Handwerk verdeutlicht die harte Realität der ländlichen Schneiderei, in der knappe Stoffballen die örtlichen Näherinnen dazu zwingen, Stoffe direkt von den Rücken der Banditen der Region zu beschaffen."},sec={{t="Banditen und Sackleinen",b="Während sich die niederrangigen Defias-Briganten, die sich im Nordhaintal herumtreiben, mit billigen Sackleinenmasken begnügen, tragen die organisierten Gesetzlosen, die den größeren Wald von Elwynn unsicher machen, feine, karmesinrote Leinenkopftücher. Für örtliche Handwerker, denen es an Rohstoffen mangelt, stellen diese Erkennungszeichen der Bande eine überraschend praktische Quelle für brauchbaren Stoff dar."},{t="Wiederverwertung im Lager",b="Von ihrer Werkstatt im geschäftigen Holzfällerlager des Osttals nahe der Ostgrenze von Elwynn aus ist Sara Roderwald stets auf der Suche nach brauchbaren Textilien. Indem sie Abenteurer dazu ermutigt, die in den Wäldern verborgenen Lager der Defias auszudünnen, sichert sie den Nachschub für ihr Schneiderhandwerk und hilft zugleich, das dreiste Vordringen der Bruderschaft einzudämmen."}},faq={{q="Wer bietet die Quest „Feine Leinenwaren“ an?",a="Sara Roderwald, eine ansässige Schneiderin im Holzfällerlager des Osttals im östlichen Wald von Elwynn, bietet diese Quest an.",al={"wer vergibt rote leinenwaren","rote leinenwaren questgeber","sara roderwald quest"}},{q="Welche Gegenstände werden für „Feine Leinenwaren“ benötigt?",a="Ihr müsst 6 Rote Leinenkopftücher sammeln, die von Mitgliedern der Defias-Bande im gesamten Wald von Elwynn erbeutet werden können.",al={"was sammeln für rote leinenwaren","gegenstände für rote leinenwaren","benötigte kopftücher"}},{q="Wo finde ich Defias-Banditen im Wald von Elwynn?",a="Defias-Gesetzlose hausen in kleinen Lagern, die über den gesamten Wald von Elwynn verstreut sind, darunter in der Umgebung von Brackwells Kürbisbeet, dem Hof der Steinfelds und den Wäldern rund um Jerods Anlegestelle.",al={"defias orte elwynn","wo sind defias lager","wo gibt es rote kopftücher"}},{q="Warum tragen die Defias in Elwynn Leinen statt Sackleinen?",a="Laut Sara Roderwald tragen niederrangige Defias in Nordhain grobe Sackleinenmasken, während die besser ausgerüsteten Mitglieder im restlichen Elwynn rotes Leinen tragen, was auf einen höheren Organisationsgrad und besseren Nachschub innerhalb der Bruderschaft hinweist.",al={"warum rotes leinen","sackleinen vs leinen defias","defias maskenmaterial"}},{q="Warum möchte Sara Roderwald die Banditentücher haben?",a="Sara geht der Stoff für ihr Schneiderhandwerk aus. Sie bereitet das waschbare Leinen der Defias-Masken wieder auf, um nützliche Waren für Waldarbeiter und Reisende im Holzfällerlager zu nähen.",al={"warum kopftücher sammeln","was macht sara mit masken"}},{q="Wo befindet sich das Holzfällerlager des Osttals?",a="Das Holzfällerlager des Osttals liegt ganz im Osten des Walds von Elwynn, knapp nördlich der Hauptstraße, die zur Brücke ins Rotkammgebirge führt.",al={"osttal lage","wo liegt osttal","sara roderwald finden"}}},fx={["18a4a024"]={q="Wofür wird das Rotes Leinenkopftuch verwendet?",a="Die Rotes Leinenkopftuch werden als Masken von Banditen der Bruderschaft der Defias getragen, die im gesamten Wald von Elwynn umherstreifen. Während die Schurken in Nordhain sich mit grober Sackleinen behelfen, tragen die Diebe im weiteren Wald besserwertigen Stoff. Sara Timberwald trennt diese erbeuteten Masken auf und webt sie neu, um brauchbare Leinenkleidung herzustellen.",al={"wofür rotes leinenkopftuch","rotes leinenkopftuch verwendung","warum rotes leinenkopftuch"}},["8ac6c8ef"]={q="Warum sind Defias-Banditen im Wald von Elwynn?",a="Die Bruderschaft der Defias hat Lager im gesamten Wald von Elwynn errichtet, um Reisende zu belästigen, Versorgungswege auszurauben und die Autorität von Sturmwind zu untergraben. Ihre wachsende Präsenz bedroht lokale Siedlungen wie das Holzfällerlager des Osttals und nutzt die überlasteten Wachen des Königreichs aus, um ihre gesetzlosen Aktivitäten direkt vor den Toren der Hauptstadt auszuweiten.",al={"defias im wald von elwynn","warum sind defias hier","bruderschaft der defias wald von elwynn"}},fea06053={q="Warum braucht Sara Timberwald Euch anstelle der Wachen?",a="Sara Timberwald ist eine Schneiderin im Holzfällerlager des Osttals, keine Soldatin, und ihr fehlen die Mittel, um selbst gegen Gesetzlose zu kämpfen. Sturmwinds Wachen und die örtliche Garnison sind bereits überlastet damit, die weit verbreiteten Einfälle der Defias und Gnollüberfälle einzudämmen, was die einfachen Handwerker dazu zwingt, sich auf vorbeiziehende Abenteurer für Materialien und Schutz zu verlassen.",al={"warum mich fragen sara","warum nicht elwynn wachen","warum braucht timberwald hilfe"}}},fp="15,204,18.211.0,19.309.0,37.97.0,42.92.0,49.138.0,54.188.0,46.157.0,43.127.0"}
P.entries["quest:830"] = {n="Die Befehle des Admirals",s="Diese verwitterten Papiere, die aus einer verschlossenen Geldkassette auf der Spitze von Burg Tiragarde geborgen wurden, tragen das persönliche Siegel des verstorbenen Großadmirals Daelin Prachtmeer. Die sichergestellten Befehle enthüllen, dass die Garnison der Menschen aus Kul Tiras an Durotars Küste weitaus gefestigter und organisierter ist als einfache Überlebende eines Schiffbruchs. Wenn Ihr sie Gar'Thok in Klingenhügel überbringt, deckt dies anhaltende militärische Pläne auf, die die junge Orcnation bedrohen.",h="Diese verwitterten Papiere, die aus einer verschlossenen Geldkassette auf der Spitze von Burg Tiragarde...",kw={"die befehle des admirals","vergilbter umschlag","daelin prachtmeer","gar'thok","kul tiras","lieutenant benedict","klingenhügel","burg tiragarde"},ang={["faction:Horde"]="Die Aufdeckung von Prachtmeers Befehlen beweist, dass die Präsenz der Allianz an den Küsten Durotars ein organisierter Vernichtungsfeldzug war, was bekräftigt, warum die Horde ihre neugewonnene Heimat mit Wachsamkeit verteidigen muss.",["race:Orc"]="Für die Orcs, die darum kämpfen, sich in Durotar eine Zukunft aufzubauen, sind diese Dokumente eine eindringliche Mahnung an Daelin Prachtmeers unerbittlichen Hass und an die verbliebenen Truppen, die noch immer nach ihrer Vernichtung trachten."},sec={{t="Ein versiegeltes Vermächtnis",b="Verborgen in einer schweren Kiste in den oberen Stockwerken von Burg Tiragarde überdauert ein vergilbter Umschlag unter den wachsamen Augen von Lieutenant Benedict. Das mit dem Wappen von Großadmiral Daelin Prachtmeer versiegelte Pergament umreißt direkte Marinebefehle, die während Kul Tiras' blutiger Invasion von Durotar erteilt wurden. Selbst nachdem der Großadmiral bei Theramore gefallen war, hielten seine Offiziere an ihren Befestigungen fest und klammerten sich verbissen an ihren Auftrag, die Siedlung der Horde auszulöschen."},{t="Alarm in Klingenhügel",b="Gar'Thok, dem Kommandanten von Klingenhügel, die sichergestellten Dokumente zu bringen, bestätigt die schlimmsten Befürchtungen der örtlichen Verteidigungstruppen. Die an der Ostküste verschanzten Streitkräfte der Menschen sind keine ziellosen Schiffbrüchigen, sondern ein etablierter Brückenkopf, der auf Verstärkung wartet. Gar'Thok erkennt sofort, dass die Zerschlagung der Befehlsstruktur von Tiragarde eine dringende Überlebensfrage für Durotar darstellt."}},faq={{q="Wo findet man die Befehle des Admirals?",a="Die Befehle befinden sich in einem Vergilbten Umschlag in einer verschlossenen Kiste im dritten Stock von Burg Tiragarde in Durotar. Um die Kiste zu öffnen, müsst Ihr zuerst Lieutenant Benedict im zweiten Stock besiegen, um seinen Schlüssel an Euch zu nehmen.",al={"fundort der befehle","wo ist der vergilbte umschlag","die befehle des admirals finden"}},{q="Wer war Admiral Prachtmeer?",a="Großadmiral Daelin Prachtmeer war der Herrscher von Kul Tiras und oberste Befehlshaber der Flotte der Allianz während des Zweiten Krieges. Da er sich weigerte zu glauben, dass Orcs jemals friedlich leben könnten, segelte er nach Kalimdor, um einen Vernichtungskrieg gegen Durotar zu führen, bevor er bei Theramore den Tod fand.",al={"wer ist der admiral","geschichte von daelin prachtmeer","wer erteilte die befehle"}},{q="Warum befinden sich immer noch Soldaten aus Kul Tiras in Burg Tiragarde?",a="Als Daelin Prachtmeer in Durotar einmarschierte, errichtete er befestigte Stützpunkte an der Küste wie Burg Tiragarde. Nach seiner Niederlage hielten überlebende Offiziere und Marinesoldaten unter Lieutenant Benedict ihre Posten, entschlossen, seinen Feldzug gegen die Horde fortzusetzen.",al={"warum sind menschen in durotar","soldaten der burg tiragarde","kul tiras in durotar"}},{q="Warum ist Gar'Thok wegen dieser Befehle so besorgt?",a="Als militärischer Kommandant von Klingenhügel hat Gar'Thok die Aufgabe, das zentrale Durotar zu beschützen. Die Entdeckung organisierter Marinebefehle beweist, dass Burg Tiragarde eine aktive, kalkulierte militärische Bedrohung für die Heimat der Orcs darstellt und es sich nicht um unorganisierte, gestrandete Überlebende handelt.",al={"gar'thoks reaktion","warum kümmert es gar'thok"}},{q="Wer besitzt den Schlüssel zur Kiste des Admirals?",a="Lieutenant Benedict, der kommandierende Offizier von Kul Tiras auf der zweiten Ebene von Burg Tiragarde, trägt den Schlüssel bei sich, der zum Aufschließen der Geldkassette mit dem Vergilbten Umschlag benötigt wird.",al={"benedicts schlüssel","wer lässt den schlüssel fallen"}},{q="Was geschieht, nachdem man Gar'Thok die Befehle übergeben hat?",a="Nach Prüfung der Befehle erkennt Gar'Thok die Gefahr: Prachtmeers Pläne wurden vor seinem Tod ausgearbeitet, und weitere Wellen seiner Männer könnten noch an den Küsten Durotars landen. Er leitet die Befehle unverzüglich nach Orgrimmar weiter, damit der Rat des Kriegshäuptlings gewarnt ist.",al={"die befehle des admirals folgequest","nächste quest"}}},fp="20,412,15.452.0,19.385.1,37.221.0,27.293.0,51.255.0,48.265.0,41.180.0,49.251.0"}
P.entries["quest:8311"] = {n="Schlotternachtssüßigkeiten für Jesper!",s="Während der Schlotternächte liegt ein junges Waisenkind namens Jesper krank im Waisenhaus von Sturmwind und wünscht sich, an den Feierlichkeiten teilnehmen zu können. Zu schwach, um hinauszugehen, bittet er Abenteurer der Allianz, an seiner Stelle in aller Welt Süßigkeiten zu sammeln.",h="Während der Schlotternächte liegt ein junges Waisenkind namens Jesper krank im Waisenhaus von Sturmwind und...",kw={"darnassus","kaugummikugel","schlotternächte","eisenschmiede","jesper","marzipan","nachtigall","nugat","sturmwind","talvash","süßes oder saures"},ang={["faction:Alliance"]="Diese Festtagsmühe verbindet die fernen Hauptstädte miteinander und verlangt von Helden, von den prächtigen Straßen Sturmwinds über die Hallen im Berg von Eisenschmiede bis zu den Ästen von Darnassus zu reisen, um einem Waisenkind Freude zu bereiten.",["race:Gnome"]="Da ihre Heimat an die Troggs und die Verstrahlung verloren ging, obliegt die gnomische Teilnahme am Fest Talvash del Kissel in Eisenschmiede, der dafür sorgt, dass Kaugummikugeln aus Gnomeregan weiterhin geteilt werden."},sec={{t="Ein behütetes Kind",b="Jesper lebt im Waisenhaus am Kathedralenplatz in Sturmwind, und zu diesen Schlotternächten ist er krank geworden. Beraubt der einfachen kindlichen Freude, Süßigkeiten aus ganz Azeroth zusammenzutragen, bleibt Jesper drinnen und hofft, dass vorbeikommende Abenteurer den Festtagsgeist teilen und Leckereien an seiner Statt sammeln."},{t="Süßes oder Saures in der gesamten Allianz",b="Um die Festtagsköstlichkeiten zu beschaffen, von denen Jesper träumt, muss ein Abenteurer weit über den Wald von Elwynn hinausreisen. Die Quest verlangt Besuche bei den Gastwirten von Sturmwind, Eisenschmiede und Darnassus sowie beim Gnomenflüchtling Talvash del Kissel. Jeder Erwachsene verlangt eine Darbietung, bevor er seine Belohnung hergibt – so müssen Reisende wie Hühner gackern, tanzen, Muskeln spielen lassen oder wie eine Eisenbahn tuckern, um regionale Süßigkeiten wie Nugat aus Sturmwind und Kaugummikugeln aus Gnomeregan zu erhalten."}},faq={{q="Wer ist Jesper?",a="Jesper ist ein junges Waisenkind, das im Waisenhaus von Sturmwind lebt. Während der Schlotternächte sehnt er sich nach Festtagssüßigkeiten, ist jedoch zu krank, um hinauszugehen und sie selbst zu sammeln.",al={"jesper sturmwind","waise jesper","wer ist jesper"}},{q="Warum kann Jesper nicht selbst Süßigkeiten sammeln gehen?",a="Jesper ist krank, und seine Krankheit hält ihn im Waisenhaus fest, während der Rest der Stadt die Schlotternächte feiert.",al={"warum kann jesper nicht raus","ist jesper krank","jesper süßes oder saures"}},{q="Welche Leckereien wünscht sich Jesper?",a="Er bittet um vier verschiedene regionale Süßwaren: Nugat aus Sturmwind, Pfefferminzbonbons aus Eisenschmiede, Marzipan aus Darnassus und Kaugummikugeln aus Gnomeregan.",al={"jesper leckereien","schlotternächte leckereien liste","jesper süßigkeiten benötigt"}},{q="Woher erhält man die Kaugummikugel aus Gnomeregan?",a="Da Gnomeregan weiterhin verstrahlt und überrannt ist, wird die Kaugummikugel von dem Gnomenflüchtling Talvash del Kissel verteilt, der sich derzeit im Mystic Ward in Eisenschmiede aufhält.",al={"kaugummikugel aus gnomeregan fundort","wer vergibt kaugummikugel","talvash süßigkeiten"}},{q="Welche Kunststücke verlangen die Gastwirte von Euch?",a="Die Gastwirte verlangen alberne Faxen als Gegenleistung für die Süßigkeiten: Eure Muskeln in Sturmwind spielen lassen, in Darnassus tanzen, in Eisenschmiede wie ein Huhn gackern und für Talvash ein Zuggeräusch machen.",al={"schlotternächte kunststücke","gastwirt kunststücke","süßes oder saures allianz"}},{q="Was gibt Jesper Euch als Gegenleistung für die Süßigkeiten?",a="Nachdem er die Auswahl der vier Festtagssüßigkeiten erhalten hat, tauscht Jesper sie freudig gegen ein paar Kürbisleckereien ein, die er für den Reisenden aufgespart hat.",al={"jesper belohnung","leckereien für jesper abschluss"}}},fx={["103fae29"]={q="Warum will Jesper, dass die Leckereien für Schlotternächte gesammelt werden?",a="Jesper ist ein krankes Waisenkind, das im Waisenhaus von Sturmwind unter der wachsamen Aufsicht von Matron Nightingale untergebracht ist, weshalb er nicht an den Feierlichkeiten zu Schlotternächte in den Hauptstädten der Allianz teilnehmen kann. Um das Fest wie jedes andere Kind zu erleben, hofft er, die festlichen Süßigkeiten zu kosten, die für jede Hauptstadt der Allianz einzigartig sind, und bietet im Tausch seine eigenen Kürbisleckereien an, damit er nicht ganz leer ausgeht.",al={"warum will jesper leckereien","jesper motivation süßigkeiten","warum schlotternächte leckereien jesper"}},["423b280b"]={q="Wofür ist das Nugat aus Sturmwind?",a="Nugat aus Sturmwind ist eine traditionelle lokale Süßware, die während Schlotternächte vom Gastwirt im Handelsdistrikt verteilt wird. Es repräsentiert den Beitrag des Menschenkönigreichs zu den Festtagsleckereien, die Jesper von Euch sammeln lässt, und wird verdient, indem Ihr dem Gastwirt Eure Stärke beweist.",al={"nugat aus sturmwind verwendung","was ist nugat aus sturmwind","wer will nugat aus sturmwind"}},["37e1df8a"]={q="Wofür ist die Kaugummikugel aus Gnomeregan?",a="Die Kaugummikugel aus Gnomeregan ist eine typische Süßigkeit, die im Namen der verbannten Gnome von Talvash del Kissel in Eisenschmiede verteilt wird. Sie ist eine der vier einzigartigen Süßigkeiten, die Jesper von Euch sammeln lässt, damit er die Festtagsleckereien aller Völker der Allianz probieren kann.",al={"kaugummikugel aus gnomeregan verwendung","was ist kaugummikugel aus gnomeregan","wer will kaugummikugel aus gnomeregan"}},e8e502ad={q="Wofür ist das Pfefferminzbonbon aus Eisenschmiede?",a="Das Pfefferminzbonbon aus Eisenschmiede ist eine zwergische Süßigkeit, die während des Herbstfestes vom Gastwirt von Eisenschmiede verschenkt wird. Jesper benötigt es als Teil seiner vollständigen Vier-Städte-Sammlung von Schlotternächte-Süßigkeiten, die vergeben wird, nachdem der Gastwirt mit einer schwungvollen Hühnerdarstellung amüsiert wurde.",al={"pfefferminzbonbon aus eisenschmiede verwendung","was ist pfefferminzbonbon aus eisenschmiede","wer will pfefferminzbonbon aus eisenschmiede"}},["61787ad3"]={q="Wofür ist das Marzipan aus Darnassus?",a="Marzipan aus Darnassus ist eine exquisite Nachtelfen-Süßigkeit, die vom Gastwirt der Terrasse der Handwerker in Darnassus verteilt wird. Es vervollständigt das Sortiment regionaler Köstlichkeiten zu Schlotternächte, die Jesper so gerne genießen möchte, während er im Waisenhaus von Sturmwind festsitzt.",al={"marzipan aus darnassus verwendung","was ist marzipan aus darnassus","wer will marzipan aus darnassus"}}},fp="31,177,17.253.0,37.372.0,14.138.0,46.104.0,30.117.0,43.90.0,47.135.0,50.101.0"}
P.entries["quest:8312"] = {n="Schlotternachtssüßigkeiten für Spoops!",s="Hallow's End Treats for Spoops! ist eine saisonale Quest, bei der ein Abenteurer im Namen von Spoops Feiertagssüßigkeiten sammelt, da dieser zu krank ist, um um Süßes oder Saures zu ziehen. Im Austausch für Leckereien, die von Gastwirten der Städte und Kali Remik in Sen'jin gesammelt wurden, bietet Spoops magische Süßigkeiten an, die den Verzehrer in lustige und furchterregende Gestalten verwandeln.",h="Hallow's End Treats for Spoops!",kw={"suessigkeiten","schlotternaechte","gastwirt","kali remik","sen'jin","spoops","leckereien","suesses oder saures"},ang={["faction:Horde"]="Diese Quest schickt Abenteurer der Horde im Namen eines kranken Kindes quer durch ihre großen Städte und hinab zur Siedlung der Dunkelspeere in Sen'jin, um um Süßes oder Saures zu ziehen.",["race:Troll"]="Dunkelspeertrolle in Durotar nehmen an den Festlichkeiten teil, wobei Kali Remik direkt von Sen'jin aus saisonale Süßigkeiten verteilt."},sec={{t="Ein bettlägeriger Feiertag",b="Die Schlotternächte bringen Feierlichkeiten, Unfug und festliche Süßwaren in das gesamte Reich, doch nicht jeder kann im Freien an den Festlichkeiten teilnehmen. Spoops sitzt krankheitsbedingt drinnen fest, während der Rest der Welt sich dem bunten Treiben hingibt. Außerstande, durch die Straßen zu streifen, spannt Spoops umherziehende Reisende ein, um loszuziehen und in seinem Namen Leckereien zu sammeln, und bietet im Gegenzug einen sonderbaren Vorrat an gestaltwandelnden Süßwaren an."},{t="Streiche und Leckereien im ganzen Reich",b="Die Beschaffung der Leckereien erfordert eine Reise durch die Siedlungen des Reiches. Die Gastwirte der großen Städte besitzen Vorräte an Feiertagssüßigkeiten, verlangen jedoch von den Besuchern, ihren Feiertagsgeist mit Kunststücken unter Beweis zu stellen, bevor sie sich von ihren Süßigkeiten trennen. Jenseits der geschäftigen Tavernen der Städte reicht die Tradition sogar bis an die Küstengestade von Durotar, wo Kali Remik in Sen'jin Leckereien an jene verteilt, die die beschwerliche Reise auf sich nehmen."}},faq={{q="Wer ist Spoops?",a="Spoops ist eine kranke junge Person, die während der Schlotternächte nicht hinausgehen kann, um um Süßes oder Saures zu ziehen. Da Spoops an den Feiertagen teilhaben möchte, bittet Spoops Reisende darum, in ihrem Namen saisonale Leckereien von Gastwirten und Händlern auf der ganzen Welt zu sammeln.",al={"wer ist spoops","spoops","was ist spoops"}},{q="Warum kann Spoops nicht um Süßes oder Saures ziehen?",a="Spoops fühlt sich unwohl und ist zu krank, um nach draußen zu gehen und die Schlotternächte zu feiern. Weil Krankheit sie ans Bett fesselt, sind sie auf hilfsbereite Abenteurer angewiesen, die die Runde bei den verschiedenen Gastwirten der Städte machen und Feiertagssüßigkeiten sammeln.",al={"warum spoops nicht um suesses oder saures ziehen kann","warum spoops drinnen bleibt","spoops krank"}},{q="Welche Süßigkeiten bietet Spoops im Austausch an?",a="Im Austausch für die bei den Gastwirten gesammelten Feiertagssüßigkeiten verspricht Spoops besondere Bonbons, die magische, verwandelnde Eigenschaften besitzen. Ihr Verzehr kann Euch in verschiedene Kreaturen und Gestalten verwandeln, die sowohl drollig als auch furchterregend sind.",al={"welche suessigkeiten spoops gibt","spoops belohnungssuessigkeiten","besondere suessigkeiten"}},{q="Wo findet Ihr die Leckereien für Spoops?",a="Feiertagssüßigkeiten werden von Gastwirten in den Hauptstädten verteilt, die von Reisenden verlangen, Kunststücke im Austausch für Leckereien vorzuführen. Zusätzlich zu den städtischen Tavernen verteilt ein Troll namens Kali Remik in Sen'jin saisonale Süßigkeiten.",al={"wo bekomme ich suessigkeiten","wer gibt leckereien","orte fuer suessigkeiten"}},{q="Wer ist Kali Remik?",a="Kali Remik ist ein Troll, der in Sen'jin in Durotar lebt und an den Schlotternächten teilnimmt, indem er Feiertagssüßigkeiten an feiernde Reisende verteilt, die vorbeikommen.",al={"wer ist kali remik","kali remik suessigkeiten","sen'jin suessigkeiten"}},{q="Warum verlangen Gastwirte nach Kunststücken?",a="Während der Schlotternächte verlangen die Gastwirte in größeren Siedlungen von den Besuchern, ihren Feiertagsgeist zu beweisen, indem sie verschiedene alberne Kunststücke oder Gesten vorführen, bevor sie ihre Feiertagssüßigkeiten herausrücken.",al={"was gastwirte wollen","gastwirt kunststuecke","wie man gastwirt-suessigkeiten bekommt"}}},fp="31,332,19.408.0,34.400.0,14.242.0,38.224.0,41.236.0,40.246.0,18.154.0,33.197.0"}
P.entries["quest:832"] = {n="Brennende Schatten",s="Dieser geheimnisvolle, leuchtende Anhänger, der dem Kultisten Gazz'uz von der Burning Blade in den Tiefen der Knochenhöhle abgenommen wurde, flüstert dem Träger dringliche Warnungen ins Bewusstsein. Die Stimme droht Gazz'uz ausdrücklich mit dem Zorn von Neeru Fireblade, einem in Orgrimmar ansässigen Orc-Hexenmeister.",h="Dieser geheimnisvolle, leuchtende Anhänger, der dem Kultisten Gazz'uz von der Burning Blade in den Tiefen der...",kw={"burning blade","brennende schatten","die kluft der schatten","durotar","auge des brennenden schatten","gazz'uz","neeru fireblade","orgrimmar","die knochenhöhle"},ang={["class:Warlock"]="Für einen Hexenmeister, der in der Kluft der Schatten ausgebildet wird, dient das Miterleben, wie der Name eines anderen Praktizierenden von der Burning Blade beschworen wird, als deutliche Erinnerung daran, wie schmal der Grat zwischen staatlich geduldeten Teufelsstudien und offenem Verrat ist.",["faction:Horde"]="Das Aufdecken des Geflüsters zwischen den Kultisten direkt vor den Toren der Hauptstadt offenbart, dass die dämonische Verderbnis der Alten Horde noch immer unbehaglich nah am Herzen Durotars schwelt.",["race:Orc"]="Orcs, die an der Seite von Thrall kämpften, um den Makel der Legion zu tilgen, betrachten die Präsenz der Burning Blade in Durotar als eine unerträgliche Entweihung ihrer neuen Heimat."},sec={{t="Eine Stimme im Stein",b="Nach dem Sieg über Gazz'uz tief in der Knochenhöhle wird seinen Überresten ein unheilvoller Anhänger namens Auge des brennenden Schatten entrissen. Anstatt ein unbelebtes magisches Schmuckstück zu sein, vibriert der Stein vor geistiger Kommunikation. Eine fordernde Stimme spricht direkt in den Geist eines jeden, der ihn in Händen hält, verlangt Berichte von Gazz'uz und warnt ihn davor, dass seine geheimen Machenschaften östlich von Orgrimmar aufgeflogen seien."},{t="Eine seltsame Drohung",b="Was jeden loyalen Späher der Horde überrascht, ist das verzweifelte Ultimatum der Stimme: Antworten, oder Neeru Fireblade wird benachrichtigt, Gazz'uz mit rascher Brutalität zur Strecke zu bringen. Neeru Fireblade verweilt offen in Orgrimmars Kluft der Schatten und praktiziert scheinbar unter Thralls strenger Aufsicht dunkle Künste. Die Übergabe des Talismans an Neeru löst geheuchelte Überraschung und Neugier aus, wobei sich der Hexenmeister darüber wundert, dass sein Name als Schreckgespenst gegen den Kult heraufbeschworen wurde."}},faq={{q="Was ist das Auge des brennenden Schatten?",a="Das Auge des brennenden Schatten ist ein verzauberter Anhänger, den der Anführer der Burning Blade, Gazz'uz, in der Knochenhöhle hinterlassen hat. Er dient als telepathische Zwei-Wege-Verbindung zwischen den Agenten des Kults und ihren ungesehenen Meistern.",al={"auge des brennenden schatten","was ist dieser anhänger","gazz'uz auge"}},{q="Wer spricht durch den Anhänger?",a="Ein unbekannter Vorgesetzter innerhalb des Schattenrats oder der Hierarchie der Burning Blade versucht, Kontakt mit Gazz'uz aufzunehmen, ohne zu wissen, dass der Kultist in der Knochenhöhle bereits getötet wurde.",al={"wer hat zu mir gesprochen","stimme im anhänger","wer spricht durch das auge"}},{q="Warum droht die Stimme Gazz'uz mit Neeru Fireblade?",a="Die Stimme behauptet, Neeru Fireblade werde mit brutaler Gewalt über Gazz'uz herfallen, falls dieser sich nicht meldet. Neeru selbst erklärt, er sei dafür bekannt, Feinde des Kriegshäuptlings zur Strecke zu bringen, findet es jedoch merkwürdig, dass ausgerechnet er ausgewählt wurde.",al={"warum neeru erwähnen","neeru fireblade drohung","neeru verbindung"}},{q="Wohin bringe ich das Auge des brennenden Schatten?",a="Bringt den Anhänger zu Neeru Fireblade, den Ihr tief in der Kluft der Schatten in Orgrimmar finden könnt, wie er über Kesseln und Folianten gebeugt verweilt.",al={"wo brennende schatten abgeben","wo ist neeru fireblade"}},{q="Wie reagiert Neeru Fireblade, wenn man ihm das Auge übergibt?",a="Neeru ist fasziniert davon, dass die Stimme ausgerechnet seinen Namen nannte, und findet es noch merkwürdiger, dass die Kultisten der Burning Blade einen Namen tragen, der seinem eigenen so ähnelt. Er behält den Anhänger, um ihn zu studieren und über die Bedeutung seiner Botschaft nachzusinnen.",al={"neeru reaktion","was sagt neeru"}},{q="Wo befindet sich Gazz'uz?",a="Gazz'uz lauert am tiefsten Punkt der Knochenhöhle, einer Höhle, die verborgen an den zerklüfteten Felsen an Durotars Ostküste direkt östlich von Orgrimmar liegt.",al={"wo ist gazz'uz","gazz'uz aufenthaltsort","knochenhöhle boss"}}},fx={["286b7c01"]={q="Warum will die Stimme im Auge des brennenden Schatten einen Bericht?",a="Die Stimme, die durch den Anhänger flüstert, versucht Kontakt mit Gazz'uz aufzunehmen, einem Anführer der Burning Blade in Die Knochenhöhle. Die Nachricht, dass ihre verborgene Enklave von der Horde entdeckt wurde, hat die Hierarchie des Kults erreicht, und der unsichtbare Befehlshaber drängt darauf, Gazz'uz zu sammeln, um Verteidigungsmaßnahmen vorzubereiten, bevor ein unvermeidlicher Angriff ihren Stützpunkt vernichtet.",al={"warum spricht der anhänger","warum auge des brennenden schatten bericht","auge des brennenden schatten stimme motiv"}}},fp="15,272,20.410.0,16.454.1,34.200.0,36.174.0,57.224.0,42.134.0,50.220.1,25.136.0"}
P.entries["quest:833"] = {n="Eine heilige Bestattung",s="Eine heilige Bestattung ist eine Quest, die von Hüter des Wissens Raintotem anvertraut wird und Abenteurer der Horde damit beauftragt, die Teufelsfelsen im östlichen Mulgore zu beschützen. Die heiligen Begräbnisstätten der Ahnen wurden von marodierenden Bristleback-Stachelebern überrannt, welche die Gräber angesehener Taurenkrieger schänden. Diese Eindringlinge zu vertreiben, bringt jenen Ehre und Frieden zurück, die ihr Leben bei der Gründung und Verteidigung von Donnerfels gaben.",h="Eine heilige Bestattung ist eine Quest, die von Hüter des Wissens Raintotem anvertraut wird und Abenteurer...",kw={"eine heilige bestattung","ahnen","eindringling der borstennacken","hüter des wissens raintotem","mulgore","borstennacken","teufelsfelsen","donnerfels"},ang={["class:Shaman"]="Die Schändung der heiligen Stätten erzürnt die Geister der geehrten Ahnen, was Euer Eingreifen erforderlich macht, um das Gleichgewicht der Erde wiederherzustellen.",["faction:Horde"]="Den Ältesten der Tauren bei der Sicherung ihrer heiligen Denkmäler beizustehen, festigt das Gelöbnis der Horde, Mulgore an der Seite ihrer Verbündeten zu verteidigen.",["race:Tauren"]="Die Verteidigung der Teufelsfelsen ist eine Angelegenheit tiefster Ahnenehre und sorgt dafür, dass die Krieger ungestört ruhen, die die geeinte Heimat Eures Volkes ermöglicht haben."},sec={{t="Geweihter Boden der Shu'halo",b="Die Teufelsfelsen dienen als eines der verehrtesten Heiligtümer in ganz Mulgore. Eingebettet in die zerklüfteten Felsen unterhalb der östlichen Berge, sind sie die letzte Ruhestätte, die ausschließlich den tapfersten Tauren vorbehalten ist. Die hier beigesetzten Helden sind legendäre Krieger, die ihr Blut vergossen, um ihre Stämme zu schützen, ihren Häuptlingen beizustehen und auf den Mesas von Donnerfels eine dauerhafte Heimat zu errichten. Für die Shu'halo ist die Störung ihrer Ruhe nicht nur ein Frevel an der Tradition, sondern an der Erdenmutter selbst."},{t="Die Schändung durch die Bristleback",b="Die nomadischen Stacheleber des Bristleback-Stammes haben den Tauren die Herrschaft über Zentral-Kalimdor stets streitig gemacht, doch ihr jüngstes Vordringen in die Teufelsfelsen stellt eine ernste Eskalation dar. Banden von Bristleback-Eindringlingen haben sich auf die heiligen Stätten geschlichen, verwüsten die Erde und stören die Ruhestätten. Da der Wächter Hüter des Wissens Raintotem zu alt ist, um die Invasoren im Alleingang zu vertreiben, müssen junge Streiter der Horde zu den Waffen greifen, um die Stätte von den Eindringlingen zu säubern und die geehrten Toten zu verteidigen."}},faq={{q="Was sind die Teufelsfelsen?",a="Die Teufelsfelsen sind eine heilige Begräbnisstätte der Ahnen entlang der östlichen Berge von Mulgore. Sie ist eigens für die tapfersten Taurenkrieger reserviert, insbesondere für jene, die bei der Verteidigung ihrer Stämme und der Gründung von Donnerfels starben.",al={"wo sind die teufelsfelsen","teufelsfelsen mulgore","begräbnisstätte der tauren"}},{q="Wer ist Hüter des Wissens Raintotem?",a="Hüter des Wissens Raintotem ist ein ältlicher Taure, der damit betraut ist, die heiligen Stätten der Teufelsfelsen zu pflegen und zu behüten. Da er erkennt, dass seine besten Jahre hinter ihm liegen und er die eindringenden Bristleback nicht mehr allein körperlich abwehren kann, ruft er fähige Abenteurer herbei, um die Toten zu verteidigen.",al={"raintotem","hüter des wissens raintotem","wer vergibt eine heilige bestattung"}},{q="Warum befinden sich die Bristleback-Stacheleber an den Teufelsfelsen?",a="Der Stamm der Bristleback bedrängt das Territorium der Tauren in ganz Mulgore und dem Brachland unablässig. Verzweifelt auf der Suche nach Land und Ressourcen sind Gruppen von Eindringlingen in die Klüfte der Teufelsfelsen vorgedrungen und schänden dabei die Grabstätten.",al={"warum sind borstennacken an den teufelsfelsen","eindringlinge der borstennacken","invasion der borstennacken"}},{q="Warum ist diese Schändung für die Tauren so kränkend?",a="In der Kultur der Tauren genießt die Ehrung ihrer Ahnen und das Leben im Einklang mit den Geistern der Gefallenen höchste Verehrung. Wilden Stachelebern zu erlauben, die Erde zu verwüsten und die Gebeine von Helden zu stören, die für Donnerfels starben, ist eine zutiefst spirituelle Kränkung.",al={"begräbnisriten der tauren","warum den tauren bestattungen wichtig sind"}},{q="Wohin führt diese Quest als Nächstes?",a="Eine heilige Bestattung ist eine eigenständige Verteidigungsaufgabe, die von Hüter des Wissens Raintotem angeboten wird. Sobald man sich um die Bristleback-Eindringlinge gekümmert hat, ist die unmittelbare Schändung aufgehalten.",al={"folgequest eine heilige bestattung","was folgt auf eine heilige bestattung"}},{q="Wer liegt an den Teufelsfelsen begraben?",a="Die Stätte ist den Vorkämpfern der Tauren vorbehalten, die für das Überleben ihrer Stämme und Häuptlinge kämpften – insbesondere jenen, deren Opfer die Errichtung und Verteidigung von Donnerfels ermöglichten.",al={"wer liegt hier begraben","gräber der teufelsfelsen"}}},fx={e11b84bd={q="Warum fragt Hüter des Wissens Raintotem Euch, anstatt sie selbst zu vertreiben?",a="Hüter des Wissens Raintotem ist ein Ältester, der einfach zu alt ist und seine besten Jahre hinter sich hat, um zu den Waffen gegen eine gewalttätige Kriegerbande zu greifen. Da er damit betraut ist, die Geister der Teufelsfelsen zu pflegen und zu ehren, anstatt an der Front zu kämpfen, verlässt er sich auf fähige Reisende wie Euch, um mit der körperlichen Gefahr fertig zu werden, die Borstenrücken-Eindringlinge zu vertreiben.",al={"warum kann raintotem das nicht tun","warum braucht raintotem hilfe","warum kämpft raintotem nicht"}}},fp="15,401,31.497.0,27.505.0,18.233.0,28.262.0,46.243.0,51.257.0,32.165.0,27.196.0"}
P.entries["quest:834"] = {n="Wind in der Wüste",s="Rezlak, ein Ingenieur, der von Gazlowes Unternehmen beauftragt wurde, benötigt Hilfe bei der Bergung wichtiger Baumaterialien, die von Harpyien in Durotar gestohlen wurden. Ein Karawanenzug auf dem Weg nach Orgrimmar wurde in der Klingenschlucht überfallen, wobei die Vorratssäcke über die Klippen verstreut wurden.",h="Rezlak, ein Ingenieur, der von Gazlowes Unternehmen beauftragt wurde, benötigt Hilfe bei der Bergung...",kw={"karawane","durotar","staubwindharpyien","gazlowe","orgrimmar","ratschet","klingenschlucht","rezlak","vorräte"},ang={["faction:Horde"]="Jede Lieferung, die an die Bestien der Schlucht verloren geht, gefährdet den raschen Ausbau und die Befestigung der Festung der Horde in Durotar.",["profession:Engineering"]="Rezlak repräsentiert den pragmatischen Einfallsreichtum der Ingenieure des Steamwheedle-Kartells, denen es weit wichtiger ist, Baupläne und Lieferungen fristgerecht einzuhalten, als sich um die Probleme mit der lokalen Tierwelt zu sorgen.",["race:Orc"]="Die Orcs verlassen sich auf das Fachwissen der Goblins und fremde Lieferungen, um den harten, trockenen Boden von Durotars in ein befestigtes Heimatland zu verwandeln."},sec={{t="Ein Goblin unter Termindruck",b="Rezlak wurde direkt von Chefingenieur Gazlowe aus Ratschet entsandt, um die Horde bei ihren ehrgeizigen Bauprojekten in ganz Durotar zu unterstützen. Festungsanlagen in rauem, kargem Gelände zu errichten ist anstrengend genug, selbst ohne logistische Katastrophen, doch Rezlaks Lieferungen verschwinden ständig, bevor sie die Baustellen erreichen. Ohne die essenzielle Fracht kommt der gesamte Fortschritt zum Erliegen, was den reizbaren Goblin-Bauleiter festsitzen lässt, ohne Material zum Bauen."},{t="Überfall in der Schlucht",b="Die letzte wichtige Nachschublieferung, die Rezlak versprochen wurde, wurde von den Staubwindharpyien abgefangen, die die Klingenschlucht bewohnen. Diese gefiederten Aasfresser nisten entlang der hohen Schluchtpfade, die die Straße zwischen Klingenhügel und Orgrimmar flankieren, und stürzen sich auf ahnungslose Wagen. Anstatt die Fracht zu fressen oder zu zerstören, horten die Harpyien die Kisten und Säcke um ihre Nistplätze herum und lassen die Ladung intakt für jeden, der mutig genug ist, sich in ihr Gebiet zu kämpfen."}},faq={{q="Wer ist Rezlak?",a="Rezlak ist ein Goblin-Arbeiter, der bei Gazlowe, dem Boss von Ratschet, angestellt ist. Gazlowe schickte ihn nach Durotar, um die Orcs bei ihren laufenden Bauarbeiten vor den Toren von Orgrimmar zu unterstützen.",al={"rezlak","wer ist rezlak","wer gab diese quest"}},{q="Warum helfen Goblins beim Bau in Durotar?",a="Gazlowe und das Steamwheedle-Kartell unterhalten eine fortlaufende geschäftliche und technische Partnerschaft mit Kriegshäuptling Thrall. Goblin-Ingenieure und Maschinen halfen dabei, die Fundamente von Orgrimmar zu legen, und Gazlowe stellt der Horde weiterhin Vertragsarbeiter und Material zur Verfügung.",al={"warum helfen goblins den orcs","gazlowe durotar","goblin horde zusammenarbeit"}},{q="Woher kamen die Vorräte?",a="Rezlak nennt nicht den Herkunftsort der Lieferung. Er sagt lediglich, es sei eine Karawanenlieferung mit Vorräten gewesen, die er für seine Arbeit zur Unterstützung der Orcs in Durotar benötige.",al={"woher kommen die vorräte","karawanenherkunft"}},{q="Was machen die Harpyien in Durotar?",a="Die Staubwindharpyien sind aggressive, räuberische Aasfresser, die die Klippen und Schluchten im Zentrum von Durotar befallen. Sie schikanieren Reisende, überfallen Handelsrouten durch die Klingenschlucht und plündern alles Glänzende oder Nützliche für ihre Nester.",al={"warum harpyien in durotar","staubwindharpyien hintergrund","klingenschlucht harpyien"}},{q="Wo befindet sich die Klingenschlucht?",a="Die Klingenschlucht zweigt direkt von der südlichen Hauptschlucht ab, die Orgrimmar mit Klingenhügel verbindet. Schluchten schneiden in die östlichen und westlichen Klippenwände und bilden hohe Nistplätze, an denen die Staubwindharpyien ihre gestohlene Fracht horten.",al={"klingenschlucht standort","wo findet man vorräte","vorratssäcke standort"}},{q="Warum haben die Orc-Wachen die Karawane nicht beschützt?",a="Rezlak sagt, die Karawanen seien nur schwer zu sichern und diese Lieferung sei fest zugesagt worden. Er erklärt nicht, welche Wachen sie begleiteten oder warum ihr Schutz gegen die Staubwindharpyien versagte.",al={"warum scheiterte karawane","durotar sicherheit","orc karawanen"}}},fx={["5ac1923e"]={q="Warum will Rezlak, dass dies erledigt wird?",a="Rezlak wurde direkt von Gazlowe geschickt, um Ingenieurs- und Bauarbeiten für die Horde in Durotar zu überwachen. Ohne diese wesentlichen Materialien sind seine Arbeiten vollständig zum Stillstand gekommen, was ihn mit leeren Händen und frustriert zurücklässt. Er kann seinen Vertrag nicht erfüllen oder seine zugewiesenen Projekte beenden, bis die Fracht geborgen ist.",al={"rezlaks motiv","warum braucht rezlak vorräte","warum kümmert sich rezlak"}},ef031f2c={q="Wozu dient der Sack Vorräte?",a="Diese Säcke enthalten Ingenieurs- und Bauproviant, das für den Bau der Horde in ganz Durotar bestimmt ist. Rezlak und seine Mannschaft benötigen sie, um ihre Bauprojekte für die Orks fertigzustellen, aber das Material wurde in der Klingenschlucht verstreut, als Staubwind-Harpyien die Lieferkarawane abfingen.",al={"sack vorräte verwendung","was sind die säcke vorräte","rezlak versorgungssäcke"}}},fp="19,251,22.451.0,20.454.0,14.186.0,41.264.0,33.151.0,38.234.0,34.233.0,46.215.0"}
P.entries["quest:835"] = {n="Sicherung der Linien",s="Sicherung der Linien ist eine Aufgabe von Rezlak nahe der Klingenschlucht, um lebenswichtige Versorgungsrouten der Goblins durch Durotar zu schützen. Harpyien, die in der Staubwindklamm nisten, fangen immer wieder Versorgungskarawanen ab und plündern sie, was den frustrierten Goblin dazu veranlasst, schlagkräftige Hilfe anzuheuern, um sie zu beseitigen.",h="Sicherung der Linien ist eine Aufgabe von Rezlak nahe der Klingenschlucht, um lebenswichtige...",kw={"staubwindklamm","dustwind savage","dustwind storm witch","gazlowe","ratschet","klingenschlucht","rezlak","sicherung der linien"},ang={["faction:Horde"]="Die Beseitigung der Harpyienbedrohung im Osten der Klingenschlucht sichert den Fluss von Gütern und Verstärkungen zwischen den Grenzaußenposten Durotars und den Handelszentren an der Küste.",["profession:Engineering"]="Der Schutz von Rezlaks Lieferungen sorgt dafür, dass hochentwickelte Goblin-Bauteile von Ratschet aus stets die Hände lokaler Tüftler erreichen."},sec={{t="Eine von Harpyien heimgesuchte Route",b="Die trockenen Täler von Durotar sind schon unbarmherzig genug, ohne dass aggressive Harpyien auf ahnungslose Reisende herabstoßen. Im Auftrag seines Bosses Gazlowe überwacht der Goblin Rezlak die regionalen Versorgungsoperationen. Unglücklicherweise haben die Staubwindharpyien in der Staubwindklamm die Klingenschlucht zu einer Gefahr gemacht, indem sie regelmäßig Karawanen überfallen und ankommende Lieferungen beschlagnahmen, bevor diese ihre Ziele erreichen können."},{t="Geschäft und Blutvergießen",b="Rezlak lebt nach der Goblin-Devise, dass man alles erledigen lassen kann, wenn der Preis stimmt. Anstatt die Schlucht selbst zu betreten, heuert er Abenteurer an, um der Brutstätte das Rückgrat zu brechen, indem sie Dustwind Savages und Dustwind Storm Witches ausschalten. Die Beseitigung dieser Harpyien hält die Handelskorridore offen, sichert ankommende Lieferungen von Ingenieursapparaten und weist hilfsbereite Reisende auf größere Gelegenheiten in Ratschet hin."}},faq={{q="Für wen arbeitet Rezlak?",a="Rezlak arbeitet für Gazlowe, den Chefingenieur und Boss der neutralen Goblin-Hafenstadt Ratschet. Gazlowe beaufsichtigt umfangreiche Handels- und Infrastrukturprojekte in ganz Durotar und dem Brachland.",al={"rezlak boss","für wen arbeitet rezlak","rezlak arbeitgeber"}},{q="Warum greifen die Harpyien Karawanen an?",a="Die Staubwindharpyien haben einen beträchtlichen Nistplatz in der Staubwindklamm errichtet, die direkt an den Hauptverkehrswegen der Klingenschlucht liegt. Sie greifen jeden Eindringling unerbittlich an und plündern die in der Nähe vorbeiziehenden Wagen und Waren.",al={"warum greifen harpyien an","motiv der staubwindharpyien","warum staubwindklamm"}},{q="Wo befindet sich die Staubwindklamm?",a="Die Staubwindklamm liegt tief in den östlichen Ausläufern der Klingenschlucht im nördlichen Durotar, eingebettet in die kargen, karmesinroten Hügel.",al={"staubwindklamm ort","wo liegt die staubwindklamm","staubwindklamm finden"}},{q="Was geschieht, nachdem man Rezlak geholfen hat?",a="Sobald die Staubwindharpyien dezimiert sind und seine Versorgungsroute gesichert ist, weist Rezlak Abenteurer nach Ratschet jenseits der Grenze im Brachland und ermutigt sie, Gazlowe für weitere lukrative Aufträge aufzusuchen.",al={"nach sicherung der linien","rezlak folgequest","wie geht es nach rezlak weiter"}},{q="Warum kümmert sich nicht die Horde statt der Goblins um die Harpyien?",a="Die Horde unterhält zwar Außenposten in Durotar, doch ihre Ressourcen sind durch die Auseinandersetzungen mit Zentauren, Stachelebern und die Bedürfnisse ihrer eigenen Siedlungen stark beansprucht. Goblinhändler wie Rezlak finden es oft schneller und kostengünstiger, direkt unabhängige Abenteurer anzuheuern, um ihre Privatunternehmen zu schützen.",al={"warum heuern goblins an","warum kümmert sich orgrimmar nicht darum","horde und harpyien"}},{q="Welche Arten von Harpyien hausen in der Staubwindklamm?",a="Die Brutstätte besteht hauptsächlich aus wilden Dustwind Savages, die im Nahkampf angreifen, und Dustwind Storm Witches, die Wind und Blitze gegen vorbeiziehende Karawanen einsetzen.",al={"harpyienarten","arten von staubwindharpyien","gegner in der staubwindklamm"}}},fx={bafa495b={q="Warum will Rezlak, dass die Harpyien vertrieben werden?",a="Rezlak ist dafür verantwortlich, dass die Fracht durch Durotar transportiert wird, aber die Staubwind-Harpyien in der Staubwindklamm haben seine Versorgungskarawanen überfallen und geplündert. Jeder verlorene Wagen kostet Gold, verzögert lebenswichtige Materialien und gefährdet bevorstehende Lieferungen – einschließlich einiger spezieller Ausrüstungsgegenstände, auf die er persönlich aus Ratschet wartet.",al={"rezlaks motiv","warum staubwind harpyien töten","rezlak karawanen problem"}}},fp="18,283,26.418.0,22.418.0,26.197.0,39.239.0,33.139.0,34.208.0,60.281.0,48.169.0"}
P.entries["quest:8353"] = {n="Hühnchengegacker für ein Pfefferminzbonbon",s="Hühnchengegacker für ein Pfefferminzbonbon ist eine heitere saisonale Quest der Allianz, die während der Schlotternächte in Eisenschmiede angeboten wird. Um ein traditionelles Pfefferminzbonbon aus Eisenschmiede für das junge Waisenkind Jesper zu erhalten, müssen Abenteurer ihre kampferprobte Würde ablegen und mit den Armen schlagen, während sie zur Belustigung der Taverne wie ein Huhn gackern. Gastwirt Feuerbräu belohnt jeden gern, der bereit ist, seinen Stolz herunterzuschlucken, um einem Kind festliche Freude zu bereiten.",h="Hühnchengegacker für ein Pfefferminzbonbon ist eine heitere saisonale Quest der Allianz, die während der...",kw={"huhn","gackern","firebrew","schlotternächte","gastwirt","pfefferminzbonbon aus eisenschmiede","jesper","leckereien"},ang={["faction:Alliance"]="Dieser saisonale Botengang unterstreicht die Verbundenheit der Allianz-Hauptstädte und verbindet die Zwergengastfreundschaft von Eisenschmiede direkt damit, einem Waisenkind in Sturmwind eine Freude zu machen.",["race:Dwarf"]="Zwerge schätzen guten Humor, kräftige Getränke und Festtagstraditionen, und Firebrews Forderung zeigt, dass sich kein Gast in Eisenschmiede allzu ernst nimmt."},sec={{t="Eine Tradition der Schlotternächte",b="Während der Schlotternächte ist die Stimmung in ganz Azeroth ausgelassen, wenn die Leute den Übergang von der Ernte zum Winter mit kostümiertem Treiben und saisonalen Leckereien feiern. Während erfahrene Helden sich normalerweise zu alt fühlen dürften, um von Tür zu Tür nach Süßigkeiten zu betteln, bietet die Not kranker oder verwaister Kinder einen ehrenhaften Vorwand. In Sturmwind sehnt sich der junge Jesper nach festlichen Süßigkeiten, was reisende Champions der Allianz dazu veranlasst, für ihn die ikonischen regionalen Leckereien von Gastwirten aus den Hauptstädten der Allianz zu sammeln."},{t="Gastwirt Feuerbräus Preis",b="Hinter dem Tresen in Eisenschmiedes belebter Taverne steht Gastwirt Feuerbräu, der Hüter des berühmten Pfefferminzbonbons aus Eisenschmiede. Er ist nicht dafür bekannt, es Abenteurern leicht zu machen, und weigert sich, das Konfekt einfach auf bloße Nachfrage herauszugeben. Er verlangt Unterhaltung und fordert, dass gestählte Krieger und stoische Zauberwirker wie Federvieh auf dem Bauernhof flattern und gackern, bevor er den Preis herausrückt. All das geschieht im Namen des festlichen Vergnügens und beschert den Tavernenbesuchern ein herzhaftes Lachen auf Kosten des Helden."}},faq={{q="Warum möchte Gastwirt Feuerbräu, dass ich wie ein Huhn gackere?",a="Gastwirt Feuerbräu lebt den spielerischen Geist der Schlotternächte aus. Da gestandene Abenteurer viel zu alt sind, um normal um die Häuser zu ziehen, verlangt er einen komödiantischen Streich, bevor er seine Süßigkeit hergibt. In dem Glauben, dass es eine gute Tavernenunterhaltung ist, einem mächtigen Champion beim Flügelschlagen und Gackern zuzusehen, tauscht er ein Pfefferminzbonbon aus Eisenschmiede fröhlich gegen ein wenig öffentliche Demütigung ein.",al={"warum huhn gackern","firebrew huhn grund","warum muss ich gackern"}},{q="Wer ist Jesper und warum besorge ich Pfefferminzbonbons für ihn?",a="Jesper ist ein krankes Waisenkind in Sturmwind, das nicht selbst an den Feierlichkeiten der Schlotternächte in der Stadt teilnehmen kann. Um ihm eine Freude zu machen, erledigen Allianz-Abenteurer saisonale Botengänge in aller Welt, um vier besondere Festtagssüßigkeiten aus jeder großen Allianz-Hauptstadt zu sammeln, darunter das frische Pfefferminzbonbon aus Eisenschmiede in Dun Morogh.",al={"wer ist jesper","warum minzen holen","jesper waise"}},{q="Wie fügt sich diese Quest in die Schlotternächte ein?",a="Diese Quest ist eine von vier regionalen Aufgaben, die zur übergeordneten saisonalen Mission „Süßes von Jesper!“ gehören, zusammen mit den Bitten der Gastwirte von Sturmwind und Darnassus sowie von Talvash del Kissel in Eisenschmiede. Jeder von ihnen verlangt ein bestimmtes erniedrigendes oder theatralisches Emote, bevor er die typische Süßigkeit seiner Stadt aushändigt.",al={"schlotternächte reihe","jesper süßigkeiten questreihe","questreihenfolge"}},{q="Wo finde ich Gastwirt Feuerbräu?",a="Gastwirt Feuerbräu steht hinter der Schanktheke in der Stonefire Tavern im Düsterbräutal von Eisenschmiede, wo er mitten im Herzen der Zwergenhauptstadt Getränke ausschenkt und Reisende beherbergt.",al={"wo ist firebrew","firebrew standort","eisenschmiede gastwirt"}},{q="Was erhalte ich für das Gackern?",a="Nach dem Gackern überreicht Euch Gastwirt Feuerbräu ein Pfefferminzbonbon aus Eisenschmiede, eine exklusive Festtagssüßigkeit, die Ihr nach Sturmwind zurückbringen müsst, um Jespers Sortiment an Schlotternächte-Leckereien zu vervollständigen.",al={"questbelohnung","was ist das pfefferminzbonbon","pfefferminzbonbon aus eisenschmiede"}},{q="Können Horde-Spieler diese Aufgabe abschließen?",a="Nein, diese Quest ist der Allianz vorbehalten. Horde-Abenteurer haben ihr eigenes Gegenstück in dem Waisenkind Spoops, das Champions durch die Hauptstädte der Horde schickt, um Leckereien von Gastwirten in Orgrimmar, Unterstadt und Donnerfels zu sammeln.",al={"nur allianz","horde huhn quest","kann horde das tun"}}},fp="27,441,24.481.0,26.479.0,60.373.0,49.311.0,56.337.0,36.186.0,31.185.0,37.240.0"}
P.entries["quest:8354"] = {n="Hühnchengegacker für ein Pfefferminzbonbon",s="Während der Feierlichkeiten der Schlotternächte bietet Gastwirt Norman in Unterstadt Reisenden eine Süßigkeit an, die einem kranken Kind helfen. Um das Pfefferminzbonbon aus Unterstadt zu erhalten, müssen Abenteurer ihre Würde ablegen und wie ein Huhn umherflattern.",h="Während der Feierlichkeiten der Schlotternächte bietet Gastwirt Norman in Unterstadt Reisenden eine Süßigkeit...",kw={"huhn","gackern","schlotternächte","gastwirt norman","spoops","handwerksviertel","unterstadt","pfefferminzbonbon aus unterstadt"},ang={["faction:Horde"]="Abenteurer der Horde reisen während der Schlotternächte zwischen allen Hauptstädten hin und her und nehmen in jeder alberne Demütigungen auf sich, um einem Waisenkind eine Freude zu bereiten.",["race:Undead"]="Albernen Humor in den verfallenden Hallen von Unterstadt zu finden ist selten, was Normans saisonale Forderung zu einer bizarren Abwechslung vom alltäglichen nekromantischen Pragmatismus macht."},sec={{t="Ein seltenes Stück Fröhlichkeit",b="Unterstadt ist selten für Lachen oder Herzlichkeit bekannt, erbaut wie es ist unter den Ruinen von Lordaeron von den befreiten Verlassenen. Doch wenn die Schlotternächte anbrechen, schließen sich selbst die finsteren Bewohner des Handwerksviertel dem saisonalen Treiben an. Gastwirt Norman hütet einen Vorrat an Pfefferminzbonbons aus Unterstadt, bestimmt für jene, die Leckereien im Namen des jungen Spoops sammeln, eines kranken Waisenkindes, das etwas Festtagsfreude braucht."},{t="Die Leckerei verdienen",b="Statt die Leckerei gestandenen Abenteurern einfach so zu überlassen, verlangt Norman ein wenig demütigendes Schauspiel. In dem Glauben, dass erwachsene Krieger und Zauberwirker sich ihre Süßigkeiten verdienen sollten, weigert er sich, das Pfefferminzbonbon herauszugeben, ehe der Bittsteller nicht direkt vor seiner Theke ein Hühnchen imitiert."}},faq={{q="Warum möchte Gastwirt Norman, dass ich wie ein Huhn gackere?",a="Gastwirt Norman findet, dass erwachsene Recken zu alt sind, um ohne eine kleine Darbietung nach Süßigkeiten zu betteln. Um die Stimmung während der Schlotternächte aufzulockern, verlangt er einen albernen Auftritt – Flügelschlagen und Gackern wie ein Huhn –, bevor er seine festliche Leckerei aushändigt.",al={"warum huhn emote","warum gackern norman","norman hühnertanz"}},{q="Für wen ist die Leckerei gedacht?",a="Das Pfefferminzbonbon aus Unterstadt wird für Spoops gesammelt, ein krankes Waisenkind, das in Orgrimmar liegt und während des Festes der Schlotternächte nicht selbst von Tür zu Tür gehen kann.",al={"wer bekommt das pfefferminzbonbon","wofür ist das pfefferminzbonbon","warum pfefferminzbonbon aus unterstadt holen"}},{q="Wo befindet sich Gastwirt Norman?",a="Gastwirt Norman betreibt die zentrale Taverne im Handwerksviertel von Unterstadt und bedient dort Gäste der Verlassenen sowie reisende Besucher der Horde.",al={"norman aufenthaltsort","wo ist der gastwirt von unterstadt"}},{q="Ist dies eine saisonale Festtagsquest?",a="Ja. Diese Quest ist Teil der alljährlichen Feierlichkeiten zu den Schlotternächten, die in ganz Azeroth von Horde und Allianz gleichermaßen begangen werden.",al={"sind das die schlotternächte","wann ist diese quest verfügbar"}},{q="Feiern die Verlassenen normalerweise die Schlotternächte?",a="Die Verlassenen feiern die Schlotternächte mit großer Begeisterung und verbrennen vor den Ruinen von Lordaeron einen gewaltigen Weidenmann, um ihrer Befreiung zu gedenken und mit ihrem früheren sterblichen Leben zu brechen.",al={"schlotternächte verlassene","untoten feiertag"}},{q="Was geschieht, nachdem man das Pfefferminzbonbon aus Unterstadt erhalten hat?",a="Das Pfefferminzbonbon wird mit anderen besonderen Leckereien kombiniert, die in den verschiedenen Hauptstädten der Völker der Horde gesammelt wurden, um ein vollständiges Festtagsgeschenk für den kleinen Spoops zusammenzustellen.",al={"folgequest","was mache ich mit dem pfefferminzbonbon"}}},fp="27,239,19.389.0,17.301.0,58.273.0,30.167.0,34.142.0,34.125.0,44.192.0,46.146.0"}
P.entries["quest:8355"] = {n="Kaugummikugelexpress",s="Kaugummikugelexpress ist eine saisonale Schlotternächte-Quest in Eisenschmiede, die vom Gnom-Handwerker Talvash del Kissel vergeben wird. Um eine Festtagsnascherei für ein krankes Kind in Sturmwind zu erhalten, müssen Abenteurer zunächst eine spielerische Zug-Nachahmung für den erfreuten Gnom vorführen.",h="Kaugummikugelexpress ist eine saisonale Schlotternächte-Quest in Eisenschmiede, die vom Gnom-Handwerker...",kw={"kaugummikugel aus gnomeregan","schlotternächte","kaugummikugelexpress","eisenschmiede","jesper","talvash del kissel","tüftlerstadt","zug emote"},ang={["faction:Alliance"]="Die Jagd nach der Festtagskaugummikugel schickt Helden der Allianz durch die Königreiche, um sicherzustellen, dass ein kränkelndes Kind in Sturmwind an der Festzeit teilhaben kann.",["race:Gnome"]="Für die verbannten Gnome in Tüftlerstadt ist das Anbieten einer Kaugummikugel aus Gnomeregan während der Schlotternächte eine heitere Erinnerung an die Heimat und an ihren mechanischen Erfindungsgeist inmitten ihrer Vertreibung."},sec={{t="Ein wunderlicher Wegezoll",b="Während der herbstlichen Feierlichkeiten der Schlotternächte durchstreifen Schabernacktreibende die bedeutenden Hochburgen der Allianz, um einzigartige regionale Süßigkeiten zu sammeln. Im Mystic Ward von Eisenschmiede besitzt der Gnom Talvash del Kissel die begehrte Kaugummikugel aus Gnomeregan. Obwohl er mit der Not des jungen Waisenkindes mitfühlt, das sich danach sehnt, besteht Talvash darauf, den schelmischen Geist des Festes zu wahren, bevor er sich von seiner Süßigkeit trennt, und verlangt von jedem, der um eine milde Gabe bittet, eine überzeugende Zug-Nachahmung."},{t="Festtägliche Wohltätigkeit",b="Die Quest ist Teil eines übergeordneten saisonalen Vorhabens, um Jesper, einem kränkelnden Waisenkind, das in Sturmwind ruht, Freude zu bereiten. Jesper sehnt sich nach vier verschiedenen Leckereien aus allen Gebieten der Allianz: Nougat aus Sturmwind, ein Minzbonbon aus Eisenschmiede, ein Marzipanstück aus Darnassus und eine Kaugummikugel aus Gnomeregan. Indem sie eine tuckernde Lokomotive nachahmen, um Talvash zu unterhalten, sichern sich die Champions den Gnomenleckerbissen, um den Festtagswunsch des Jungen zu erfüllen."}},faq={{q="Was muss ich tun, um Kaugummikugelexpress abzuschließen?",a="Ihr müsst für Talvash del Kissel eine Zug-Nachahmung vorführen, indem Ihr ihn ins Visier nehmt und die Zug-Geste ausführt. Sobald er das Zuggeräusch hört, wird er freudig die Kaugummikugel aus Gnomeregan überreichen.",al={"wie man kaugummikugelexpress macht","kaugummikugelexpress ziel","talvash kaugummikugel streich"}},{q="Wer ist Talvash del Kissel?",a="Talvash del Kissel ist ein Gnomenjuwelier aus Gnomeregan, der im Mystic Ward innerhalb der zwergischen Bergstadt Eisenschmiede lebt. Während der Schlotternächte fungiert er als Verteiler der charakteristischen Kaugummikugeln aus Gnomeregan für die Allianz.",al={"wer ist talvash","talvash del kissel geschichte"}},{q="Wofür wird die Kaugummikugel aus Gnomeregan verwendet?",a="Die Kaugummikugel aus Gnomeregan ist eine von vier verschiedenen Festtagssüßigkeiten, die gesammelt werden, um die Schlotternächte-Bitte von Jesper zu erfüllen, einem Waisenjungen, der im Waisenhaus von Sturmwind liegt.",al={"kaugummikugel aus gnomeregan zweck","wofür ist die kaugummikugel"}},{q="Wo ist Talvash del Kissel zu finden?",a="Talvash ist im Mystic Ward von Eisenschmiede zu finden.",al={"wo ist talvash","talvash standort"}},{q="Warum lässt Talvash einen einen Zug imitieren?",a="Die Schlotternächte wurzeln in der Tradition von Streichen und Süßigkeiten. Talvash verlangt spielerisch einen harmlosen Schabernack – eine Lokomotiv-Nachahmung –, bevor er bereit ist, seine festliche Leckerei herauszugeben.",al={"warum zuggeräusch","warum zug für talvash"}},{q="Ist diese Quest das ganze Jahr über verfügbar?",a="Nein, diese Quest ist nur während des jährlichen Herbstfestes der Schlotternächte verfügbar.",al={"kann man kaugummikugelexpress jederzeit machen","ist das saisonal"}}},fp="16,265,16.467.0,15.447.0,50.184.0,26.222.0,40.177.0,38.53.0,42.185.0,35.83.0"}
P.entries["quest:8356"] = {n="Muskelspiel für Nugat",s="Während der herbstlichen Feierlichkeiten der Schlotternächte können Abenteurer, die Sturmwind besuchen, einem einheimischen Waisenkind dabei helfen, festliche Süßigkeiten zu sammeln. Um ein Stück Nugat aus Sturmwind von Gastwirtin Allison in der Taverne „Zur Vergoldeten Rose“ zu erhalten, werden Besucher scherzhaft dazu aufgefordert, eine mächtige Muskelpose einzunehmen, bevor sie die Leckerei aushändigt.",h="Während der herbstlichen Feierlichkeiten der Schlotternächte können Abenteurer, die Sturmwind besuchen, einem...",kw={"muskelspiel für nugat","vergoldete rose","schlotternächte","gastwirtin allison","jesper","sturmwind","nugat aus sturmwind","saures oder süßes"},ang={["class:Warrior"]="Für stämmige Krieger, die an blutige Schlachtfelder gewöhnt sind, ist das Anspannen der Armmuskeln auf Geheiß einer Gastwirtin eine harmlose, wenn auch leicht unrühmliche Zurschaustellung von Kraft.",["faction:Alliance"]="Der spielerische Austausch unterstreicht den heiteren Gemeinschaftssinn, der während saisonaler Feste wie den Schlotternächten in Sturmwind erblüht und Bürger sowie wandernde Helden für einen guten Lacher zusammenbringt.",["race:Human"]="Für die Menschen in Sturmwind ist das Verwöhnen von Kindern und der Austausch von Kunststücken gegen Leckereien ein geschätzter saisonaler Brauch, der eine kurze Atempause von den dunkleren Gefahren bietet, denen das Königreich gegenübersteht."},sec={{t="Eine Schlotternacht-Tradition",b="Die Schlotternächte bringen ein seltenes Gefühl der Unbeschwertheit in die Straßen von Sturmwind. Während die uralten Wurzeln des Festes den Wechsel der Jahreszeiten und das Abwehren dunkler Geister würdigen, feiert das einfache Volk es mit Verkleidungen, ausgelassenem Treiben und dem Fordern von Süßem oder Saurem. Gastwirte in der gesamten Allianz beteiligen sich, indem sie traditionelle Süßwaren verteilen, vorausgesetzt, die Festbesucher sind bereit, im Gegenzug für ihre Belohnung ein harmloses Kunststückchen vorzuführen."},{t="Unterhaltung für die Gastwirtin",b="In der Taverne „Zur Vergoldeten Rose“ im belebten Handelsdistrikt sorgt Gastwirtin Allison dafür, dass niemand festliche Süßigkeiten umsonst bekommt – selbst wenn man Botengänge für einen Waisenjungen wie Jesper erledigt. Beim Anblick der Ausrüstung oder Kleidung eines Abenteurers kommentiert Allison spielerisch dessen Statur und besteht darauf, dass er zu ihrer Belustigung die Muskeln spielen lässt. Erst wenn ein Abenteurer seine Stärke zur Schau stellt, belohnt sie ihn mit einem Stück zähem Nugat aus Sturmwind."}},faq={{q="Warum lässt Gastwirtin Allison die Leute die Muskeln anspannen?",a="Die Schlotternächte drehen sich um die Tradition von Streichen und Leckereien. Da Der Abenteurer im Namen eines Waisenkindes vorbeikommt, das nach Süßigkeiten sucht, besteht Gastwirtin Allison darauf, dass er sich das Naschwerk mit einem unterhaltsamen Kunststück verdient – nämlich dem Vorzeigen seiner Muskeln.",al={"warum muskeln anspannen für nugat","was will allison","muskel-emote grund"}},{q="Wo findet diese Quest statt?",a="Die Bitte wird vollständig im Gasthaus „Zur Vergoldeten Rose“ im Herzen von Sturmwinds Handelsdistrikt angenommen und erfüllt, wo Gastwirtin Allison die Theke bedient.",al={"wo ist muskelspiel für nugat","allison standort","gastwirtin vergoldete rose"}},{q="Für wen ist das Nugat aus Sturmwind gedacht?",a="Das Nugat ist für Jesper bestimmt, einen Waisenjungen, der sich in Sturmwind aufhält. Er hofft, während der Schlotternächte traditionelle Festsüßigkeiten aus jeder großen Allianz-Stadt probieren zu können.",al={"wer bekommt das nugat","wer will nugat aus sturmwind","jesper süßigkeiten"}},{q="Was ist Nugat aus Sturmwind?",a="Nugat aus Sturmwind ist eine regionale Süßware, die von den Gastwirten Sturmwinds während der Schlotternächte verteilt wird und unter Festbesuchern als eine der typischen Leckereien des Menschenkönigreichs bekannt ist.",al={"nugat aus sturmwind lore","schlotternächte nugat","sturmwind süßigkeit"}},{q="Können Horde-Spieler diese Leckerei von Allison erhalten?",a="Nein. Gastwirtin Allison hält sich tief im Inneren des von der Allianz kontrollierten Sturmwind auf und bedient ausschließlich Allianzmitglieder. Abenteurer der Horde führen ihre eigenen festlichen Späße für Gastwirte in ihren eigenen Hauptstädten vor.",al={"kann horde nugat bekommen","horde version von nugat"}},{q="Findet diese Quest das ganze Jahr über statt?",a="Nein. Gastwirtin Allison bietet diesen Auftrag nur während des saisonalen Schlotternächte-Events an, wenn die Bräuche des Süßigkeiten-Sammelns die Städte beherrschen.",al={"wann ist muskelspiel für nugat verfügbar","ist diese quest saisonal","schlotternächte zeitraum"}}},fp="18,176,24.297.0,26.309.0,44.122.0,33.126.0,38.158.0,25.160.0,49.194.0,34.137.0"}
P.entries["quest:8357"] = {n="Tanzen für Marzipan",s="Während der festlichen Zeit der Schlotternächte haben Abenteurer, die durch Darnassus reisen, die Aufgabe, festliche Süßigkeiten für ein krankes Waisenkind in Sturmwind zu sammeln. Gastwirtin Saelienne hält die Tradition von „Süßes oder Saures“ vollends aufrecht und verlangt eine spontane Tanzdarbietung, bevor sie sich von ihrem geschätzten Marzipan aus Darnassus trennt.",h="Während der festlichen Zeit der Schlotternächte haben Abenteurer, die durch Darnassus reisen, die Aufgabe...",kw={"tanz","darnassus","schlotternächte","gastwirtin","jesper","marzipan","saelienne","teldrassil"},ang={["faction:Alliance"]="Diese festliche Aufgabe veranschaulicht die Einigkeit und unbeschwerte Kameradschaft zwischen den Hauptstädten der Allianz, indem sie Leckereien aus dem fernen Teldrassil bis zu einem jungen Waisenkind in Sturmwind bringt.",["race:NightElf"]="Für die Nachtelfen ist die Teilnahme an den Schlotternächten eine liebenswerte Übernahme von Festtagsbräuchen der Allianz, die ihren gelassenen Waldlebensstil mit spielerischem Feiern verbindet."},sec={{t="Eine aufrechterhaltene Tradition",b="Selbst in der heiligen Waldstadt Darnassus bringen die Feierlichkeiten der Schlotternächte den langlebigen Nachtelfen heitere Stimmung. Wenn Reisende eintreffen, um im Namen von Jesper, einem kranken Kind, das sich in Sturmwind erholt, festliche Süßwaren zu sammeln, besteht Gastwirtin Saelienne darauf, dass die Regeln der Jahreszeit ungebrochen bleiben. Wohltätigkeit hin oder her: Für eine Leckerei ist zunächst ein gehöriger Streich erforderlich."},{t="Der Preis des Marzipans",b="Um das erlesene Marzipan aus Darnassus zu erhalten, müssen Abenteurer ihr würdevolles Auftreten beiseitelegen und direkt auf dem Boden des Gasthauses eine Darbietung abliefern. Saelienne verlangt nichts Geringeres als einen Tanz und belohnt freudig jene, die bereit sind, ihren Stolz abzulegen und die Festtagsfreude anzunehmen, mit der Süßware, die zur Vervollständigung des kontinentübergreifenden Feiertagspflegepakets benötigt wird."}},faq={{q="Was ist der Zweck von „Tanzen für Marzipan“?",a="Die Quest ist Teil der saisonalen Schlotternächte-Feierlichkeiten der Allianz. Ihr führt einen Tanz für Gastwirtin Saelienne in Darnassus auf, um Marzipan aus Darnassus zu erhalten – eine von mehreren festlichen Leckereien, die benötigt werden, um ein krankes Waisenkind namens Jesper in Sturmwind aufzuheitern.",al={"warum für marzipan tanzen","was ist diese quest","marzipan quest"}},{q="Wer ist Gastwirtin Saelienne?",a="Gastwirtin Saelienne leitet das Gasthaus in Darnassus und bietet Reisenden unter den Ästen von Teldrassil Schutz und Rast. Während der Schlotternächte überwacht sie die Verteilung der lokalen Feiertagssüßwaren an jene, die bereit sind, die Tradition mitzumachen.",al={"wer ist saelienne","saelienne lore"}},{q="Warum besteht Saelienne auf einen Tanz?",a="Saelienne hält sich strikt an den Geist der Schlotternächte. Obwohl die Leckerei für ein kränkliches Kind bestimmt ist, hält sie am Brauch von „Süßes oder Saures“ fest und verlangt spielerisch eine Demonstration von tänzerischem Können als Streich, bevor sie die Süßigkeit aushändigt.",al={"warum tanzen","warum möchte saelienne dass ich tanze"}},{q="Wohin gelangt das Marzipan danach?",a="Sobald es erhalten wurde, wird das Marzipan aus Darnassus zusammen mit saisonalen Süßigkeiten gebündelt, die in den Gasthäusern von Eisenschmiede und Sturmwind sowie von Talvash del Kissel in Eisenschmiede gesammelt wurden, um die Quest zu erfüllen und dem jungen Jesper in Sturmwind Festtagsfreude zu bringen.",al={"wer bekommt das marzipan","was tun mit dem marzipan"}},{q="Was ist Marzipan aus Darnassus?",a="Marzipan aus Darnassus ist eine zuckrige Süßware, die in der nachtelfischen Hauptstadt hergestellt wird. Es dient als charakteristische festliche Leckerei von Darnassus für Besucher, die während der Schlotternächte nach Süßem oder Saurem fragen.",al={"marzipan aus darnassus lore","welche art von süßigkeit ist es"}},{q="Können Spieler der Horde diese Quest abschließen?",a="Nein. „Tanzen für Marzipan“ ist eine saisonale Quest nur für die Allianz. Darnassus ist eine Festung der Allianz, und das Marzipan wird eigens für ein Waisenkind der Allianz gesammelt, das sich in Sturmwind erholt.",al={"ist diese quest nur für die allianz","horde marzipan quest"}}},fp="20,314,18.375.0,21.343.0,44.247.0,27.253.0,37.261.0,38.238.0,27.178.0,38.194.0"}
P.entries["quest:8359"] = {n="Muskelspiel für Nugat",s="Während der herbstlichen Feierlichkeiten der Schlotternächte bietet Gastwirtin Gryshka in Orgrimmar süße saisonale Leckereien für all jene an, die bereit sind mitzuspielen. Um ein Stück Nugat aus Orgrimmar für ein bettlägeriges Kind zu ergattern, müssen die Streitkräfte der Horde ihren Kriegerstolz herunterschlucken und auf Befehl ihre Muskeln spielen lassen.",h="Während der herbstlichen Feierlichkeiten der Schlotternächte bietet Gastwirtin Gryshka in Orgrimmar süße...",kw={"süßigkeiten","muskeln anspannen","gryshka","schlotternächte","nugat","orgrimmar","spoops","süßes oder saures"},ang={["class:Warrior"]="Krieger, die stolz auf ihre verheerenden Heldentaten an vorderster Front sind, mögen es amüsant – oder leicht beschämend – finden, wie Bühnendarsteller für ein Stück Festtagssüßigkeit zu posieren.",["faction:Horde"]="Selbst erfahrene Recken, die tödlichen Kriegsherren die Stirn bieten, müssen vor Gastwirten den Bizeps anspannen, um Festtagssüßigkeiten für die Kinder der Horde zu sammeln.",["race:Orc"]="Orgrimmars Gastwirtin erwartet eine eindrucksvolle Zurschaustellung von Muskeln – eine urorkische Prüfung des Stolzes, die zu heiterem Festtagstheater wird."},sec={{t="Streiche für Süßes",b="Die Schlotternächte bringen ausgelassene Stimmung, Streiche und das Sammeln von Süßwaren in die geschäftigen Hauptstädte Azeroths. Während abenteuerlustige Helden oft Drachen und finsterer Zauberei trotzen, verlangen die Bräuche des herbstlichen Festes eine weitaus leichtere Hand. Gastwirtin Gryshka, die über den Schankraum von Orgrimmars Gasthaus wacht, teilt ihre Festtagssüßigkeiten gern – aber nur, wenn die Gäste sich an die älteste Regel der Saison halten: Führt ein Kunststück vor oder geht mit leeren Händen aus."},{t="Muskeln zur Schau gestellt",b="Amüsiert über jede Verkleidung und Rüstung, in der ein Abenteurer erscheint, verlangt Gryshka eine Zurschaustellung roher orkischer Kraft. Bevor sie auch nur ein einziges Stück Nugat aus Orgrimmar für den kleinen Spoops herausrückt, besteht sie darauf, dass der mächtige Reisende eine muskulöse Pose einnimmt. Es ist eine heitere Erinnerung daran, dass selbst die gefürchtetsten Krieger der Horde dazu gebracht werden können, das einfache Volk für Süßigkeiten zu unterhalten."}},faq={{q="Wer verlangt die Muskelpose?",a="Gastwirtin Gryshka, die Wirtin der Haupttaverne im Tal der Stärke innerhalb von Orgrimmar, verlangt das Kunststück, bevor sie ihre Festtagssüßigkeiten aushändigt.",al={"wer vergibt die quest","gryshka","gastwirtin gryshka"}},{q="Warum muss ich für Süßigkeiten die Muskeln anspannen?",a="Der Brauch der Schlotternächte besagt, dass Süßigkeitensammler im Austausch für Naschereien ein kleines Kunststück vorführen müssen. Gryshka beschließt, den Abenteurer zu necken, indem sie eine Zurschaustellung bloßer körperlicher Kraft fordert, bevor sie ihn belohnt.",al={"warum muskeln anspannen","was ist das kunststück","nugat bedingung"}},{q="Wofür wird das Nugat aus Orgrimmar verwendet?",a="Das Nugat ist eine von vier verschiedenen Süßigkeiten, die in den Hauptstädten der Horde gesammelt werden, um Spoops aufzumuntern – einen kranken Waisenjungen, der nicht selbst um die Häuser ziehen kann.",al={"warum brauche ich nugat","nugat verwendung","spoops süßigkeiten"}},{q="Wo hält sich Gastwirtin Gryshka auf?",a="Sie steht hinter dem Tresen des Hauptgasthauses im Tal der Stärke in Orgrimmar und bedient dort müde Reisende wie Einheimische gleichermaßen.",al={"wo ist gryshka","orgrimmar gastwirtin standort"}},{q="Kann jedes Mitglied der Horde daran teilnehmen?",a="Ja, jedes Mitglied der Horde kann Gastwirtin Gryshka während der Schlotternächte aufsuchen, um eine Pose einzunehmen und die saisonale Leckerei einzufordern.",al={"wer kann muskeln anspannen","fraktionsbeschränkungen","nur horde"}},{q="Zu welchem Fest gehört dies?",a="Diese Aufgabe ist Teil der Schlotternächte, eines Herbstfestes, das das Ende der Ernte und den Triumph über die eigene Sterblichkeit mit Verkleidungen, Streichen und Süßigkeiten feiert.",al={"welches event","welcher feiertag","schlotternächte quest"}}},fp="18,305,17.451.0,17.396.0,27.154.0,32.213.0,38.159.0,36.136.0,41.128.0,31.155.0"}
P.entries["quest:836"] = {n="Rettet OOX-09/HL!",s="Nachdem das Signalfeuer den gestürzten Peilroboter aufgeschreckt hat, spricht Oglethorpe Obnoticus aus dem Roboter selbst. OOX-09/HL benötigt einen offenen, sicheren Ort, um seinen Start zu beginnen, daher soll er zur Küstenlinie jenseits von Overlook Cliff eskortiert werden, und danach wartet Oglethorpe in Beutebucht.",h="Nachdem das Signalfeuer den gestürzten Peilroboter aufgeschreckt hat, spricht Oglethorpe Obnoticus aus dem...",kw={"beutebucht","tarnung","peilroboter","oglethorpe obnoticus","overlook cliff","oox-09/hl"},sec={{t="Ein Spaziergang zur Küste",b="Oglethorpes Stimme knackt erneut aus dem Roboter. Die Maschine benötigt einen offenen, sicheren Ort, um eine langwierige Startprozedur zu beginnen, und die Küstenlinie jenseits von Overlook Cliff eignet sich dafür hervorragend. Ihre eingebaute Tarnung kann noch nicht genutzt werden, und Oglethorpe braucht Zeit, um sie wieder einsatzbereit zu machen."},{t="Nachricht in Beutebucht",b="Sobald der Roboter sicher an die Küste gebracht wurde, bittet Oglethorpe Obnoticus Euch, nach Beutebucht zu kommen und mit ihm zu sprechen."}},faq={{q="Wohin muss der Roboter eskortiert werden?",a="OOX-09/HL soll zur Küstenlinie jenseits von Overlook Cliff gebracht werden, einem offenen Ort, an dem er seinen Start beginnen kann.",al={"wohin geht oox-09","hinterland huhn eskortierziel","kueste von overlook cliff"}},{q="Wer ist für die Erschaffung dieses Peilroboters verantwortlich?",a="Der Roboter ist das Werk des Gnoms Oglethorpe Obnoticus, der sich in Beutebucht aufhält.",al={"wer hat oox-09 erschaffen","oox schoepfer","wer hat das huhn gebaut"}},{q="Warum kann der Roboter nicht einfach dort starten, wo er gefunden wurde?",a="Seine Startprozedur ist langwierig und erfordert einen offenen, sicheren Ort. In der Zwischenzeit benötigt Oglethorpe Zeit, um seine Tarnung wieder einsatzbereit zu machen.",al={"warum laeuft das huhn","warum oox-09 eskortieren"}},{q="Wohin geht Ihr, sobald die Eskorte die Küste erreicht?",a="Oglethorpe Obnoticus bittet um ein Treffen in Beutebucht, sobald der Roboter sicher an der Küste ist.",al={"wo rescue oox-09 abgeben","bei wem melde ich mich","standort von oglethorpe"}},{q="Was geschah vor dieser Eskorte?",a="Sie folgt auf Find OOX-09/HL!, bei der das Notsignalfeuer zum abgestürzten Roboter gebracht wurde.",al={"oox-09 vorherige quest","voraussetzung fuer rescue oox-09"}}},fp="17,267,19.280.0,17.113.0,41.111.0,50.77.0,55.136.0,50.88.0,29.90.0"}
P.entries["quest:8360"] = {n="Tanzen für Marzipan",s="Tanzen für Marzipan ist eine festliche Quest der Schlotternächte, die von Gastwirtin Pala in Donnerfels angeboten wird. Um eine süße Leckerei für ein krankes Waisenkind zu besorgen, müssen Abenteurer ihre kampferprobte Würde beiseiteschieben und einen fröhlichen Tanz für die Gastwirtin aufführen. Dies unterstreicht den verspielten, gemeinschaftsorientierten Geist des Feiertags, selbst hoch oben auf den windgepeitschten Hochebenen von Mulgore.",h="Tanzen für Marzipan ist eine festliche Quest der Schlotternächte, die von Gastwirtin Pala in Donnerfels...",kw={"tanzen für marzipan","schlotternächte","gastwirtin pala","marzipan","mulgore","donnerfels","süßes oder saures"},ang={["faction:Horde"]="Ein heiterer Moment in den sonst harten Alltagsmühen der Horde, der das Herz der Fraktion zeigt, während Reisende durch die Hauptstädte ziehen, um einem Waisenkind Festtagsfreude zu bringen.",["race:Tauren"]="Gastwirtin Pala bringt traditionelle Festtagsstimmung direkt nach Mulgore und beweist, dass selbst hochgewachsene, stoische Tauren Freude an einem guten Tanz für einen guten Zweck haben können."},sec={{t="Ein Tanz auf der Hochebene",b="Während des herbstlichen Festes der Schlotternächte herrscht in ganz Azeroth ausgelassene Stimmung, selbst in den ruhigen Höhen von Donnerfels. Gastwirtin Pala, die für die Gastfreundschaft auf den hohen Hochebenen sorgt, kommt in Festtagsstimmung und verlangt einen Streich, bevor sie Leckereien austeilt. Selbst wenn ein Abenteurer im Namen eines kranken Kindes eintrifft, bleibt die Tradition bestehen: Pala besteht darauf, ein paar festliche Tanzschritte zu sehen, bevor sie sich von ihrem geschätzten Marzipan aus Donnerfels trennt."},{t="Streiche für Leckereien",b="Der Festtagsbrauch, Vergnügen gegen Süßigkeiten einzutauschen, bringt eine seltene, heitere Seite der Kultur der Horde zum Vorschein. Palas Bitte erfordert nichts weiter, als vorzutreten, die Reisemüdigkeit abzuschütteln und Eure besten Schritte zu zeigen. Nachdem sie bestens unterhalten wurde, händigt die Gastwirtin das Marzipan gerne aus und gibt ihre besten Wünsche für das kranke Kind mit auf den Weg, das auf die Leckerei wartet."}},faq={{q="Was ist das Ziel von Tanzen für Marzipan?",a="Die Quest verlangt von Euch, ein Tanz-Emote vor Gastwirtin Pala in Donnerfels auszuführen. Als Gegenleistung gibt sie Euch ein Stück Marzipan aus Donnerfels, das Teil einer größeren Sammlung von Feiertagsleckereien ist, die während der Schlotternächte für ein krankes Waisenkind zusammengetragen werden.",al={"warum tanzen für marzipan","marzipan quest ziel","tanzen für marzipan aufgabe"}},{q="Wer vergibt diese Quest?",a="Gastwirtin Pala, die Tauren-Gastwirtin, die Besucher und Einheimische in Donnerfels bewirtet, bietet diese Quest während des Feiertags der Schlotternächte an.",al={"wer startet tanzen für marzipan","pala quest","gastwirtin pala donnerfels"}},{q="Warum besteht Pala auf einen Tanz, wenn die Süßigkeit für ein krankes Kind ist?",a="Pala betont, dass Festtagstraditionen respektiert werden müssen, selbst bei edlen Vorhaben. Im Geiste von „Süßes oder Saures“ muss man ein Kunststück oder einen Streich vorführen, um die süße Belohnung zu verdienen, damit die Schlotternächte fröhlich und lebendig bleiben.",al={"warum muss ich tanzen","warum will pala einen tanz"}},{q="Welche Belohnung erhaltet Ihr für das Tanzen?",a="Ihr erhaltet ein Stück Marzipan aus Donnerfels, eine lokale festliche Süßigkeit, die benötigt wird, um die umfassende Leckereien-Sammlung der Schlotternächte für das kranke Kind abzuschließen.",al={"marzipan belohnung","tanzen für marzipan gegenstand"}},{q="Können Spieler der Allianz diese Quest abschließen?",a="Nein. Gastwirtin Pala ist eine Händlerin der Horde im Herzen von Donnerfels, wodurch dieser Zwischenstopp auf der festlichen Süßigkeiten-Tour ausschließlich Mitgliedern der Horde zugänglich ist.",al={"nur für die horde","allianz tanzen für marzipan"}},{q="Wann ist diese Quest verfügbar?",a="Diese Quest ist nur während des jährlichen Herbstfeiertags der Schlotternächte verfügbar, wenn Gastwirte in ganz Azeroth besondere Süßwaren und festliche Spiele anbieten.",al={"wann marzipan erhalten","schlotternächte marzipan quest"}}},fp="20,356,20.447.0,17.386.0,44.250.0,21.137.0,65.223.0,39.160.0,41.168.0,29.156.0"}
P.entries["quest:837"] = {n="Übergriff",s="Encroachment ist eine Quest der Horde, die von Gar'Thok in Klingenhügel im zentralen Durotar vergeben wird. Sie beauftragt Streiter damit, tief in die westlichen Dornengestrüpp-Bauten vorzudringen, um die verschanzten Razormane-Stacheleber zu eliminieren, welche die Grenzen der jungen Orc-Nation bedrohen.",h="Encroachment ist eine Quest der Horde, die von Gar'Thok in Klingenhügel im zentralen Durotar vergeben wird.",kw={"dornensträucher","durotar","encroachment","gar'thok","stacheleber","klingenhügel","razormane"},ang={["faction:Horde"]="Die Sicherung von Durotar gegen die einheimischen Razormane-Stacheleber ist von entscheidender Bedeutung, um eine sichere dauerhafte Heimat für die entstehende Horde zu schaffen.",["race:Orc"]="Nachdem die Orcs Durotar als ihr neues souveränes Land beansprucht haben, betrachten sie die verbliebenen Dornengestrüpp-Bauten der Razormane als eine inakzeptable Bedrohung für ihre Siedlungen."},sec={{t="Ein Dorn im Auge Durotars",b="Als Thrall die Orcs nach Kalimdor führte und Durotar gründete, stellten sie fest, dass ein Großteil des kargen, trockenen Landes bereits von den Razormane-Stachelebern bewohnt war. Diese aggressiven, eberartigen Kreaturen erwiesen sich als ständiger Dorn im Auge der neuen Siedlung. Durch anhaltende militärische Anstrengungen drängte die Horde den Großteil ihrer Streitmacht zurück, doch befestigte Gruppen der Razormane klammern sich weiterhin hartnäckig an ihre dornigen Schanzen westlich von Klingenhügel."},{t="Gar'Thoks Offensive",b="Gar'Thok, ein in Klingenhügel stationierter Offizier, leitet die Bemühungen, die verbliebene Bedrohung durch die Razormane ein für alle Mal zu beseitigen. Er beauftragt erfahrene Verteidiger damit, direkt in die westlichen Dornengestrüpp-Lager vorzustoßen, um deren Kundschafter, Krieger und Staubläufer auszuschalten. Für Gar'Thok und die Führung der Horde bedeutet jeder Stützpunkt der Stacheleber nahe Klingenhügel ein enormes Risiko, und ein Angriff an diesem Ort gilt als erster Schritt zur Sicherung Kalimdors."},{t="Das Roden des Gestrüpps",b="Die Ausschaltung der Verteidiger der Stacheleber ebnet den Truppen der Horde den Weg, um die Dornengestrüpp-Bauten niederzubrennen und die Razormane daran zu hindern, die westlichen Ausläufer zurückzuerobern. Indem die Horde diese Konstruktionen dem Erdboden gleichmacht, beseitigt sie eine anhaltende Bedrohung und sichert die Westgrenze von Durotar, wodurch wichtige Nachschubwege zwischen Klingenhügel und dem weiteren Reich geschützt werden."}},faq={{q="Wer vergibt die Quest Encroachment?",a="Die Quest wird von Gar'Thok vergeben, einem Orc-Offizier, der in Klingenhügel im zentralen Durotar stationiert ist.",al={"wer vergibt encroachment","wo man encroachment erhält","questgeber für encroachment"}},{q="Warum kämpft die Horde in Durotar gegen die Razormane-Stacheleber?",a="Als die Orcs in Durotar eintrafen, hielten die Razormane-Stacheleber einen Großteil der Region besetzt. Obwohl die Horde die meisten von ihnen zurückdrängte, verbleiben westlich von Klingenhügel befestigte Enklaven, welche die Sicherheit und die Grenzen der neuen Heimat der Orcs bedrohen.",al={"warum borstennackenschweine durotar bekämpfen","warum razormane angreifen","stacheleberkonflikt durotar"}},{q="Wo befinden sich die Lager der Razormane?",a="Die Lager der Razormane liegen westlich von Klingenhügel. Ihr könnt ihr Territorium leicht an den dichten Dickichten aus dornigem Gestrüpp erkennen.",al={"wo die lager der stacheleber liegen","wie man lager der razormane findet","standort von encroachment"}},{q="Wer sind die Razormane?",a="Die Razormane sind ein feindseliger Stamm von Stachelebern, der in den trockenen Ebenen von Kalimdor beheimatet ist. Sie errichten defensive Dornengestrüpp-Bauten und widersetzen sich erbittert der Besiedlung von Durotar und dem Brachland durch die Horde.",al={"wer sind die razormane","geschichte der razormane","was sind razormane"}},{q="Was geschieht, sobald die Stacheleber besiegt sind?",a="Nach Abgabe der Quest lässt Gar'Thok die geräumten Dornenhecken und Bauten der Stacheleber niederbrennen, was die Kontrolle der Horde über das Gebiet festigt und die Grenzen von Durotar sichert.",al={"was nach encroachment geschieht","abgabe von encroachment","schicksal der lager der stacheleber"}},{q="Welche Rolle spielt Klingenhügel in diesem Konflikt?",a="Klingenhügel ist eine befestigte Orc-Siedlung im zentralen Durotar, die als militärischer und logistischer Knotenpunkt zwischen dem Tal der Prüfungen und Orgrimmar dient.",al={"wo liegt klingenhügel","was ist klingenhügel"}}},fp="12,250,25.433.0,20.442.0,21.356.0,33.90.0,60.231.0,38.141.0,22.189.0,44.175.0,43.148.0"}
P.entries["quest:84"] = {n="Zurück zu Billy",s="Zurück zu Billy ist ein Schritt in der andauernden Fehde zwischen den Familien Steinfeld und Maclure im zentralen Wald von Elwynn. Nachdem Ihr die Zutaten für eine Schweinebauch-Pastete gesammelt habt, bringt Ihr das frisch gebackene Gericht zurück zum jungen Billy Maclure, um Informationen über Bernice Steinfelds verschwundene Halskette zu entlocken.",h="Zurück zu Billy ist ein Schritt in der andauernden Fehde zwischen den Familien Steinfeld und Maclure im...",kw={"zurück zu billy","bernice stonefield","billy maclure","wald von elwynn","weinberge der maclures","schweinebauchpastete","hof der steinfelds","stonefield halskette"},ang={["faction:Alliance"]="Selbst der friedliche Wald von Elwynn wird von alltäglichen Streitigkeiten geplagt; der Umgang mit zankenden menschlichen Gehöften ist eine typische Pflicht für Reisende, die den Einheimischen beistehen.",["profession:Cooking"]="Schweinebauch-Pastete ist ein klassisches Hausmannskost-Gericht der Farmen von Elwynn, zubereitet aus dem Fleisch der wilden Eber, die den Wald durchstreifen."},sec={{t="Eine bittere Pastete",b="Der Generationenstreit zwischen den Steinfelds und den Maclures lässt wenig Raum für nachbarschaftliche Freundlichkeit. Tantchen Bernice Steinfeld buk die verlangte Schweinebauch-Pastete nur deshalb widerwillig, weil der junge Billy Maclure sich weigerte, ohne sie sein Wissen über ihr Familienerbstück preiszugeben. Selbst als sie das warme Gebäck überreicht, ist ihr Ärger unübersehbar, und sie trägt dem Boten auf, dem Maclure-Jungen auszurichten, er solle an jedem Bissen ersticken."},{t="Die Bestechung eines Jungen",b="Auf der anderen Straßenseite in den Weinbergen der Maclures wartet Billy Maclure mit leerem Bauch und einer passenden Gedächtnislücke. Der Handel verdeutlicht die starrsinnige Kleinlichkeit, welche die beiden Gehöfte entzweit, wo selbst Kinder lernen, Klatsch und gestohlene Schmuckstücke gegen Leckereien vom Bauernhof einzutauschen. Sobald die Pastete überbracht ist, klärt sich Billys Gedächtnis praktischerweise auf, was die Suche nach dem wahren Verbleib der Halskette einleitet."}},faq={{q="Was ist der Zweck dieser Lieferung?",a="Billy Maclure behauptete zu wissen, wo sich Tantchen Bernice Steinfelds verlorene Halskette befindet, weigerte sich jedoch zu reden, bis er eine hausgemachte Schweinebauch-Pastete erhielt. Die Übergabe der Pastete erfüllt seine Forderung, damit er verrät, wohin das Erbstück geraten ist.",al={"warum pastete liefern","was will billy","zurück zu billy ziel"}},{q="Warum ist Tantchen Bernice so wütend auf Billy?",a="Die Familien Steinfeld und Maclure liegen seit Jahren in einer erbitterten ländlichen Fehde. Bernice missfällt es zutiefst, für ein lästiges Maclure-Kind eine Leckerei backen zu müssen, nur um ein Erbstück wiederzuerlangen, das an ihren Grundstücksgrenzen verloren ging.",al={"warum hasst bernice billy","streit stonefield maclure","warum soll er ersticken"}},{q="Wo befindet sich die Halskette laut Billy tatsächlich?",a="Sobald Billy die Pastete verschlungen hat, gibt er preis, dass er die Halskette nicht behalten hat. Stattdessen fiel sie Goldzahn in die Hände, einem berüchtigten Kobold, der in der Tiefenschachtmine lauert.",al={"wo ist die halskette","wer hat die halskette genommen","verbindung zu goldzahn"}},{q="Wo befindet sich Billy Maclure?",a="Billy Maclure befindet sich in den Weinbergen der Maclures, direkt südlich der Straße im zentralen Wald von Elwynn, gegenüber vom Hof der Steinfelds.",al={"billy maclure aufenthaltsort","wo ist billy","billy finden"}},{q="Wer hat die Schweinebauchpastete gebacken?",a="Tantchen Bernice Steinfeld hat die Pastete auf dem Hof der Steinfelds gebacken, nachdem Ihr frische Stücke Eberfleisch aus der nahen Wildnis beschafft hattet.",al={"wer hat die pastete gemacht","pastetenkoch"}},{q="Beendet diese Quest die Fehde zwischen den Familien?",a="Nein. Die Lieferung der Pastete erfüllt lediglich Billys persönliche Erpressung. Die tief sitzende Feindseligkeit zwischen den erwachsenen Steinfelds und Maclures bleibt so bitter wie eh und je.",al={"endet die fehde","frieden stonefield maclure"}}},fx={["6d42dc77"]={q="Warum schickt Tante Bernice einen Außenstehenden, um sich um Billy zu kümmern?",a="Die erbitterte Fehde zwischen den Steinfelds und den Maclures macht einen direkten Kontakt zwischen den Familien fast unmöglich. Tante Bernice kann es nicht ertragen, selbst einen Fuß auf das Land der Maclures zu setzen – geschweige denn persönlich ein nervtötendes Kind zu bedienen, das Essen als Gegenleistung für gestohlenes Eigentum verlangt. Ein durchreisender Wanderer bietet einen neutralen Boten, der über die Straße gehen, den Kuchen abliefern und dem jungen Billy die Wahrheit entlocken kann, ohne einen offenen Streit zwischen den benachbarten Clans zu entfachen.",al={"warum zurück zu billy schicken","warum nicht bernice selbst","warum braucht tante bernice einen abenteurer"}}},fp="13,232,12.302.0,13.353.1,37.229.0,42.209.0,46.149.1,31.121.0,29.135.0,54.133.0"}
P.entries["quest:840"] = {n="Freiwilliger der Horde",s="Freiwilliger der Horde ist eine einführende Übergangsquest, die junge Abenteurer der Horde aus Durotar hinaus und in die weite Wildnis des Brachlands führt. Sie wird vom Späher Takrin Pathseeker entlang der westlichen Straße von Klingenhügel aus gestartet und schickt Rekruten über den Südstrom zu Kargal Schlachtnarbes Grenzaußenposten.",h="Freiwilliger der Horde ist eine einführende Übergangsquest, die junge Abenteurer der Horde aus Durotar hinaus...",kw={"brachland","freiwilliger der horde","das wegekreuz","kargal schlachtnarbe","klingenhügel","anwerbungsbrief","der südstrom","takrin pathseeker"},ang={["faction:Horde"]="Diese Einberufung markiert den Übergang eines Kriegers vom lokalen Beschützer Durotars zu einem anerkannten Verteidiger der weiteren Territorien der Horde in ganz Kalimdor.",["race:Orc"]="Für junge Orcs, die ihre Trainingsgelände im Tal der Prüfungen und in Klingenhügel verlassen, ist es ein wesentlicher Übergangsritus im Dienst des Kriegshäuptlings, dem Ruf von Kargal Schlachtnarbe zu folgen.",["race:Troll"]="Dunkelspeertrolle, die an der Seite ihrer Orc-Verbündeten kämpfen, nutzen diesen Einsatz, um die Expansion der Horde zu unterstützen und die an das große Meer grenzenden Gebiete zu sichern."},sec={{t="Überquerung des Südstroms",b="Sobald ein angehender Soldat der Horde seine Stärke rund um Klingenhügel unter Beweis stellt, rufen ihn die Bedürfnisse der weiteren Nation nach Westen. Takrin Pathseeker hält entlang der unbefestigten Hauptstraße, die Durotar verlässt, Wache und mustert Reisende im Namen seines Freundes, des Veteranen Kargal Schlachtnarbe. Die Annahme von Takrins Anwerbungsbrief markiert den ersten formellen Auftrag eines Rekruten jenseits der neuen Heimat der Orcs in Durotar."},{t="Grenzverteidigung",b="Der Grenzaußenposten jenseits der Brücke überspannt die Grenze zwischen den roten Schluchten Durotars und den ariden Weiten des Brachlands. Kargal Schlachtnarbe hat die Aufgabe, Rekruten zu mustern, um die Grenzen zu halten, auch wenn der Dienst als Grenzwache nur der Anfang ist. Da Zentauren, Borstennacken und Expeditionen der Allianz die Grenze sondieren, wird die unverbrauchte Truppenstärke dringend zur Siedlung des Wegekreuzes umgeleitet."}},faq={{q="Wohin bringe ich den Anwerbungsbrief?",a="Folgt der westlichen Straße, die von Klingenhügel in Durotar über die Holzbrücke über den Südstrom führt. Kargal Schlachtnarbe ist am Wachturm des Horde-Außenpostens direkt hinter der Grenze auf der Seite des Brachlands stationiert.",al={"wo muss ich hin","kargal schlachtnarbe aufenthaltsort","abgabeort"}},{q="Wer ist Takrin Pathseeker?",a="Takrin Pathseeker ist ein Späher der Horde, der an der westlichen Straße außerhalb von Klingenhügel stationiert ist. Er behält die Straße im Auge und hält nach fähigen Kriegern Ausschau, um sie nach Westen zu seinem Kameraden Kargal Schlachtnarbe zu schicken.",al={"takrin rolle","wer gibt die quest","questgeber"}},{q="Wer ist Kargal Schlachtnarbe?",a="Kargal Schlachtnarbe ist ein schroffer Veteranenoffizier, der den Wachposten im östlichen Brachland leitet. Er mustert eintreffende Freiwillige, unterzeichnet ihre Einberufungspapiere und schickt sie weiter in die Savanne, um dem Wegekreuz zu helfen.",al={"wer ist kargal","schlachtnarbe lore"}},{q="Was geschieht, nachdem Kargal den Brief unterzeichnet hat?",a="Kargal nimmt den Brief entgegen und verpflichtet Euch mit der Quest „Crossroads Conscription“ sofort zu weiteren Diensten. Er weist Euch an, auf der Hauptstraße nach Westen zu marschieren und Euch bei Sergra Darkthorn am Wegekreuz zu melden.",al={"nächste quest","was nach freiwilliger der horde","wohin als nächstes"}},{q="Warum rekrutiert die Horde Soldaten für das Brachland?",a="Das Brachland ist ein offenes Grenzgebiet, das für die Verbindung von Orgrimmar mit Mulgore von entscheidender Bedeutung ist. Da wilde Borstennackenvölker, plündernde Zentauren und opportunistische Übergriffe der Allianz die Versorgungsrouten bedrohen, benötigt die Horde jede fähige Hand, um die Straßen zu sichern.",al={"warum anwerbung","brachland gefahr","warum rekrutieren"}},{q="Ist diese Quest für Spieler der Allianz verfügbar?",a="Nein. Diese Quest ist ausschließlich für Mitglieder der Horde gedacht, die von den frühen Durotar-Questreihen in das Brachland übergehen.",al={"kann allianz das machen","ist das nur für horde"}}},fx={dfa16f64={q="Warum möchte Takrin Pathseeker, dass Ihr den Anwerbungsbrief überbringt?",a="Takrin Pathseeker dient als vorgeschobener Späher, der die Straße von Durotar in die trockenen Ebenen überwacht. Sein alter Kamerad Kargal Schlachtnarbe kommandiert den Grenzposten direkt auf der anderen Seite des Flusses und hat mit einem ständigen Mangel an fähigen Kriegern zu kämpfen. Da er Potenzial in Eurer Stärke sieht, möchte Takrin frisches Blut direkt in die Garnison im Brachland lenken, um die Verteidigung der Horde zu stärken, anstatt fähige Hände in Klingenhügel untätig zu lassen.",al={"warum schickt takrin mich","takrin pathseeker motiv","warum rekrutieren für kargal"}},["788e36ab"]={q="Warum schickt Takrin einen Abenteurer, anstatt selbst Bericht bei Kargal zu erstatten?",a="Takrin ist damit beauftragt, die wichtige Kreuzung zwischen Durotar und der westlichen Grenze zu überwachen und dabei Reisende sowie Bedrohungen auf der Straße im Auge zu behalten. Seinen Posten zu verlassen, um einzelne Nachrichten zu überbringen, würde seine Pflicht verletzen. Noch wichtiger ist, dass er nach potenziellen Soldaten Ausschau hält, die Kargal unterstützen könnten. Wenn Ihr direkt dem Kommandanten des Außenpostens Bericht erstattet, beweist dies Eure Bereitschaft und Initiative, der Horde zu dienen.",al={"warum geht takrin nicht selbst","warum schickt er mich zu kargal","warum ich conscript of the horde"}}},fp="22,320,22.383.0,14.392.0,39.218.0,25.195.0,25.214.0,43.215.0,53.249.0,44.121.0"}
P.entries["quest:841"] = {n="Eine weitere Kraftquelle?",s="Chefingenieur Bilgewhizzle in Gadgetzan hat weitere Energiequellen und verkauft Euch eine weitere zum Preis von zehn Wastewander Water Pouches.",h="Chefingenieur Bilgewhizzle in Gadgetzan hat weitere Energiequellen und verkauft Euch eine weitere zum Preis...",kw={"bilgewhizzle","gadgetzan","energiequelle","tanaris","wastewander","wasserbeutel"},sec={{t="Ein kostspieliger Ersatz",b="Chefingenieur Bilgewhizzle vermutet, dass die Zeit der ersten Energiequelle aus Slake That Thirst abgelaufen ist oder sie vielleicht im Sand verloren ging. Was auch immer der Grund sein mag, Bilgewhizzle hat zusätzliche Energiequellen zu verkaufen. Diesmal beträgt der Preis zehn Wastewander Water Pouches, denn die Zeiten sind überall hart und Energiequellen wachsen nicht auf Bäumen."}},faq={{q="Warum will Chefingenieur Bilgewhizzle Wastewander-Wasserbeutel?",a="Bilgewhizzle verkauft eine weitere Energiequelle für zehn Wastewander Water Pouches und sagt, dass die Zeiten überall hart seien.",al={"bilgewhizzle wasserbeutel","warum wasserbeutel"}},{q="Wer bietet diesen Tausch an?",a="Chefingenieur Bilgewhizzle, der zusätzliche Energiequellen zu verkaufen hat.",al={"wer startet another power source","questgeber energiequelle"}},{q="Was geschah vor dem Bedarf an einer weiteren Energiequelle?",a="Es folgt auf Slake That Thirst, wo Ihr zum ersten Mal eine Energiequelle für Euer Set erhalten habt.",al={"voraussetzung another power source","vorherige quest energiequelle"}}},fp="21,139,20.332.0,68.109.0,25.70.0,52.83.0"}
P.entries["quest:842"] = {n="Wegekreuzwehrpflicht",s="Wegekreuzwehrpflicht führt frisch rekrutierte Hordekämpfer vom Grenzposten ins Herz des Brachlands. Mit einem unterzeichneten Brief von Kargal Schlachtnarbe melden sich Abenteurer direkt bei Sergra Dunkeldorn am überaus wichtigen strategischen Knotenpunkt namens Das Wegekreuz.",h="Wegekreuzwehrpflicht führt frisch rekrutierte Hordekämpfer vom Grenzposten ins Herz des Brachlands.",kw={"brachland","battlescar","wehrpflicht","das wegekreuz","darkthorn","farwatch","kargal","sergra","thrall"},ang={["class:Shaman"]="Sergra Dunkeldorn verdeutlicht, dass Schamanen in Thralls Horde nicht bloß als mystische Berater dienen, sondern auch als direkte militärische Befehlshaber und Verwalter wichtiger strategischer Außenposten.",["faction:Horde"]="Dieser Auftrag markiert den üblichen Übergangsritus für junge Hordekämpfer, die aus der Sicherheit ihrer heimatlichen Startgebiete in die umkämpfte Wildnis des Brachlands aufbrechen.",["race:Orc"]="Der Austausch zwischen Kargal und Sergra unterstreicht die sich wandelnde gesellschaftliche Dynamik in Thralls reformierter Horde, in der Verdienst und spirituelle Einsicht die alten Clan-Traditionen einfacher Fußsoldatenarbeit herausfordern."},sec={{t="Zum Dienst melden",b="Nachdem sie sich vor Kargal Schlachtnarbe an der Fernwacht an der Grenze von Durotar bewiesen haben, erhalten Rekruten einen unterzeichneten Einberufungsbefehl und werden nach Westen geschickt. Die Reise folgt dem festgetretenen Feldweg durch das trockene Gestrüpp des Brachlands, bis die zentrale Kreuzung erreicht ist. An dieser sonnenverbrannten Weggabelung liegt Das Wegekreuz, der lebenswichtige logistische Knotenpunkt der Horde, der das nördliche Kalimdor mit der südlichen Wildnis verbindet."},{t="Die Schamanin vom Wegekreuz",b="Dort erwartet die Neuankömmlinge Sergra Dunkeldorn, eine scharfzüngige Orcschamanin, die von Kriegshäuptling Thrall persönlich ausgewählt wurde, um die Operationen im Wegekreuz zu leiten. Trotz des Murrens erfahrener Veteranen wie Kargal Schlachtnarbe – der sie für schwierig und übermäßig geschwätzig hält – schätzt Thrall Sergra sehr. Grimmig und unnachgiebig erinnert sie Rekruten, insbesondere arrogante Männer, rasch daran, dass Kriegerinnen und Anführerinnen in Thralls Horde auf völlig gleicher Stufe stehen und keinerlei Unverschämtheiten dulden."}},faq={{q="Wer schickt mich auf diese Quest?",a="Kargal Schlachtnarbe, ein Orcveteran, der an der Fernwacht kurz westlich der Brücke zwischen Durotar und dem Brachland stationiert ist, schickt Euch auf diesen Einsatz.",al={"wer gibt crossroads-wehrpflicht","questgeber crossroads-wehrpflicht","kargal quest"}},{q="Wo befindet sich Sergra Dunkeldorn?",a="Sergra Dunkeldorn ist direkt im Zentrum vom Wegekreuz stationiert und steht nahe der Straßenkreuzung, an der Karawanen und Boten aufeinandertreffen.",al={"sergra dunkeldorn standort","wo ist sergra","sergra dunkeldorn finden"}},{q="Warum beschwert sich Kargal über Sergra?",a="Kargal empfindet Sergra als anstrengend und nennt sie eine bösartige Schamanin, die in Rätseln redet, bevor sie jemanden praktische Arbeit verrichten lässt. Trotz seines persönlichen Unmuts respektiert er den Befehl von Kriegshäuptling Thrall, Rekruten zu ihr zu schicken.",al={"warum mag kargal sergra nicht","kargal gegen sergra","verflucht sei sie"}},{q="Warum spricht Sergra mit männlichen und weiblichen Charakteren unterschiedlich?",a="Sergra Dunkeldorn ist sehr stolz auf Thralls Grundsatz, der weiblichen Kriegern in der neuen Horde völlige Gleichberechtigung gewährt. Weibliche Rekruten ermutigt sie herzlich für ihren Einsatz, während sie männliche Rekruten warnt, dass sie weder Respektlosigkeit noch Anmaßung dulden wird.",al={"sergra dialog mann frau","sergra dunkeldorn dialog","sergra gleichberechtigung"}},{q="Welche Route sollte ich nehmen, um das Wegekreuz zu erreichen?",a="Folgt der Hauptstraße von der Fernwacht nach Westen, bis Ihr auf eine T-Kreuzung trefft, biegt dann links ab und folgt der südlichen Straße direkt in die Siedlung Das Wegekreuz.",al={"weg nach das wegekreuz","wegbeschreibung nach das wegekreuz","das wegekreuz pfad"}},{q="Was passiert nach der Meldung bei Sergra Dunkeldorn?",a="Sobald Ihr von Sergra empfangen wurdet, nimmt sie Eure Dienste in Anspruch, um das Wegekreuz direkt zu unterstützen, und schickt Euch los, um bei lokalen Bedrohungen, der Jagd und der Sicherung des Außenpostens im gesamten zentralen Brachland zu helfen.",al={"was kommt nach crossroads-wehrpflicht","folgequest sergra","brachland rekruten nächste quest"}}},fx={["3243ab88"]={q="Warum schickt mich Kargal Schlachtnarbe zum Wegekreuz?",a="Als Kommandant der Fernwacht verarbeitet Kargal frische Wehrpflichtige, die aus Durotar ins Brachland kommen. Anstatt jeden kampffähigen Kämpfer an einem Eingangsposten zu behalten, ist es seine Pflicht gegenüber der Horde, neue Rekruten tiefer in die Grenzgebiete zu schicken. Das Wegekreuz dient als zentraler Knotenpunkt der Autorität der Horde und der militärischen Mobilisierung im Brachland, wo Arbeitskräfte dringend benötigt werden, um die umliegenden Ländereien unter der Aufsicht von Sergra Darkthorn zu sichern.",al={"warum zum das wegekreuz schicken","kargal motiv crossroads conscription","warum bei sergra melden"}},["07e83289"]={q="Warum schickt Kargal mich anstelle eines seiner Wachen?",a="Ihr seid ein ankommender Wehrpflichtiger, der sich beweisen und seinen Unterhalt innerhalb der Horde verdienen will. Kargals Wachen am Außenposten sind bereits damit beauftragt, den Grenzwachtposten gegen lokale Bedrohungen zu besetzen. Euch zusammen mit einem unterschriebenen Anwerbungsbrief loszuschicken, verstärkt sowohl den Außenposten am Wegekreuz als auch testet es, ob ein neuer Rekrut die Disziplin besitzt, allein durch die wilden Ebenen zu navigieren und Befehle zu befolgen.",al={"warum braucht kargal mich","warum keine wache zum das wegekreuz schicken","warum ich kargal"}}},fp="23,265,18.412.0,28.496.0,27.153.0,34.139.0,38.216.0,64.259.0,49.173.0,49.186.0"}
P.entries["quest:843"] = {n="Ganns Rekultivierung",s="Ganns Rekultivierung ist eine Quest der Horde, die von dem wandernden Tauren-Verbannten Gann Steinkeil im Südlichen Brachland angeboten wird. Tief gekränkt durch die archäologische Ausgrabung der Zwerge bei Bael Modan, die seinen Stamm vertrieben hat, wirbt Gann Reisende an, um zurückzuschlagen, indem sie die Arbeiter der Ausgrabungsstätte töten und das Tagebuch ihres Anführers beschaffen.",h="Ganns Rekultivierung ist eine Quest der Horde, die von dem wandernden Tauren-Verbannten Gann Steinkeil im...",kw={"bael modan","bael'dun","ausgrabungsstätte der zwerge","gann steinkeil","khazgorm","südliches brachland"},ang={["class:Shaman"]="Die explosiven Sprengungen und tiefen Grabungen bei Bael Modan verwunden die umgebenden Erdgeister, was Ganns Feldzug zu einer notwendigen Reinigung elementarer Zerrüttung macht.",["faction:Horde"]="Bael Modan stellt eine befestigte Hochburg der Allianz tief im Gebiet von Kalimdor dar, was die Verteidigung von Ganns Anspruch sowohl zu einem Akt der Ehre als auch zu einer strategischen Eindämmung macht.",["race:Tauren"]="Für die Shu'halo ist Ganns Notlage eine erbitternde Mahnung daran, wie wenig Respekt die Allianz der Erdenmutter entgegenbringt, indem sie Dynamit und Eisenzahnräder einsetzt, um uralte Begräbnisstätten zu zerstören."},sec={{t="Ein vertriebener Stamm",b="Bevor die Kanonen und Spitzhacken des Prospektors die Erde aufbrachen, waren die roten Klippen südlich des Brachlands der angestammte Geburtsort und die Jagdgründe des Clans von Gann Steinkeil. Als die Zwerge aus Eisenschmiede eintrafen, um Bael Modan zu errichten, wurden die Tauren gewaltsam vertrieben oder getötet, um Platz für gewaltige Steinbrüche und Schützengräben zu schaffen. Da friedliche Proteste ignoriert wurden und die Diplomatie erschöpft war, wandert Gann nun in Einsamkeit durch den Staub der südlichen Straße und plant eine blutige Vergeltung für seine gefallenen Verwandten."},{t="Die Ruinen von Bael Modan",b="Das Vorgehen der Zwerge bei Bael Modan nimmt wenig Rücksicht auf das Land oder dessen Hüter. Indem sie die Hänge mit Dampfmaschinen und schweren Sprengstoffen aufriss, drang die Expedition unter Prospektor Khazgorm tief in die Erde vor. Ganns Aufgabe ist einfach und kompromisslos: Lichtung der Reihen der Ausgräber und Vorarbeiter der Bael'dun, die den heiligen Boden aufwühlen, Tötung von Khazgorm selbst und Beschaffung der persönlichen Ausgrabungsnotizen des Prospektors, um herauszufinden, worauf es die Eindringlinge der Allianz wirklich abgesehen haben."}},faq={{q="Wer ist Gann Steinkeil?",a="Gann Steinkeil ist ein einsamer Überlebender der Tauren, dessen Stamm einst im Südlichen Brachland lebte. Nachdem Ausgräber der Zwerge sein Volk vertrieben und jene getötet hatten, die Widerstand leisteten, begann Gann die südliche Hauptstraße auf und ab zu wandern, auf der Suche nach Gerechtigkeit und Rache gegen die vordringende Ausgrabungsstätte der Allianz.",al={"gann","wer vergibt ganns rekultivierung","gann steinkeil lore"}},{q="Warum sind die Zwerge im Brachland?",a="Die Zwerge sind eine Expedition aus Eisenschmiede, die Bael'dun, die eine Festung und eine Ausgrabung bei Bael Modan im Südlichen Brachland errichtet haben. Ihre Sprengungen und lärmenden Grabungsmaschinen reißen die Hügel unter völliger Missachtung der einheimischen Tauren-Bewohner auf.",al={"warum sind zwerge in bael modan","zweck von bael modan","eisenschmiede im brachland"}},{q="Wer ist Prospektor Khazgorm?",a="Prospektor Khazgorm ist der Anführer der Zwerge, der die Ausgrabungsarbeiten in der Ausgrabungsstätte südlich der Festung Bael Modan leitet. Gann hält ihn für direkt verantwortlich für die Entweihung seiner angestammten Ländereien und verlangt sein Tagebuch als Beweis für seinen Tod.",al={"khazgorm","prospektor khazgorm","anführer von bael modan"}},{q="Wo ist Gann Steinkeil zu finden?",a="Gann Steinkeil wandert entlang der Straße im äußersten Südlichen Brachland auf und ab, westlich der Festung Bael Modan und nördlich der Straße, die zum Großen Aufzug und nach Tausend Nadeln führt.",al={"ganns aufenthaltsort","gann finden","wo ist gann"}},{q="Hat Gann versucht, dies friedlich zu lösen?",a="Ja. Gann erklärt ausdrücklich, dass diplomatische Wege unternommen wurden, um die Zerstörung seiner angestammten Ländereien zu stoppen, die Zwerge diese Bemühungen jedoch abtaten und die Hügel weiterhin aufsprengten, was ihn dazu zwang, zu Gewalt zu greifen.",al={"haben die tauren diplomatie versucht","gann diplomatie"}},{q="Was geschieht nach dieser Quest?",a="Nach Erhalt von Khazgorms Tagebuch studiert Gann die Notizen, um die Technologie und Pläne der Zwerge zu verstehen, was direkt in die Questreihe 'Revenge of Gann' übergeht, um ihre schweren Maschinen zu sabotieren.",al={"folgequest nach ganns rekultivierung","gann folgequest"}}},fx={["5ecef431"]={q="Warum will Gann Steinkeil die Zwerge vertreiben?",a="Bael Modan liegt direkt auf dem angestammten Land von Ganns Stamm. Als die Zwerge ankamen, vertrieben ihr unerbittliches Graben, laute Maschinen und Sprengungen die Tauren aus ihrem Zuhause und kosteten viele unschuldige Leben. Nachdem er alle friedlichen Ansätze ausgeschöpft hat, sucht Gann Vergeltung und will die heilige Heimat seines Volkes mit Gewalt zurückfordern.",al={"gann motiv","warum bael modan zwerge töten","warum will gann rache"}},fd3e714a={q="Wozu dient Khazgorms Tagebuch?",a="Das Tagebuch gehört Prospektor Khazgorm, dem Anführer, der die zerstörerische Ausgrabungsstätte Bael Modan beaufsichtigt. Gann möchte die Seiten studieren, um Einblicke in die Operationen der Zwerge, ihre Motive in der Region und die beste Art und Weise zu gewinnen, ihre anhaltende Zerstörung seines angestammten Territoriums zu stoppen.",al={"verwendung khazgorms tagebuch","warum khazgorms tagebuch sammeln","was will gann mit dem tagebuch"}},["4442e883"]={q="Warum bittet Gann Euch, anstatt die Ausgrabung selbst zu erledigen?",a="Gann wandert völlig allein durch das Südliches Brachland, ein Exilant, dessen Stamm durch die Ankunft der Zwerge abgeschlachtet oder vertrieben wurde. Da er vor einer befestigten Siedlung steht, die von Dutzenden bewaffneter Ausgräber, Vorarbeiter und deren Anführer besetzt ist, kann er nicht hoffen, die Eindringlinge ohne einen fähigen Champion zu vertreiben, der in seinem Namen kämpft.",al={"warum kann gann es nicht selbst tun","warum braucht gann hilfe","warum ich gann"}}},fp="18,312,17.498.0,23.474.0,23.283.0,35.250.0,27.259.0,35.171.0,40.228.0,30.198.1"}
P.entries["quest:844"] = {n="Ebenenschreiterbedrohung",s="„Ebenenschreiterbedrohung“ ist eine einführende Jagdaufgabe, die von Sergra Dunkeldorn im Wegekreuz vergeben wird. Frisch eingetroffene Abenteurer der Horde werden angewiesen, die einheimischen Ebenenschreiter auszudünnen, die die Versorgungswege der Siedlung plündern; dies dient sowohl der Schädlingsbekämpfung als auch einer ersten Prüfung des jagdlichen Könnens.",h="„Ebenenschreiterbedrohung“ ist eine einführende Jagdaufgabe, die von Sergra Dunkeldorn im Wegekreuz vergeben...",kw={"brachland","schnabel","das wegekreuz","darkthorn","jagd","ebenenschreiter","sergra","vorräte"},ang={["class:Hunter"]="Für junge Jäger bildet Sergras Prüfung ein unerlässliches Fundament im Anschleichen, Fährtenlesen und Erlegen von Beute in der weiten Savanne.",["faction:Horde"]="Das Wegekreuz ist ein zentraler logistischer Knotenpunkt; das Sichern seiner Nahrungsvorräte vor wilden Tieren gewährleistet, dass die Horde ihre Stellung in Kalimdor behaupten kann.",["race:Orc"]="Orcs schätzen die Disziplin der Jagd, und Sergra erwartet von jedem Neuankömmling, seinen Mut an den einheimischen Bestien zu beweisen, bevor gewichtigere Aufgaben übernommen werden."},sec={{t="Sicherung des Wegekreuzes",b="Das Wegekreuz liegt im logistischen Herzen von Kalimdor und koordiniert Versorgungskarawanen durch die raue Savanne. Allerdings treibt das karge Terrain die einheimische Tierwelt zu verzweifelter Nahrungssuche. Herden großer, flugunfähiger Ebenenschreiter, die östlich des Außenpostens umherstreifen, haben damit begonnen, an Kisten mit Vorräten herumzupicken und die Lebensader der Siedlung zu stören. Um diese gefährdeten Rationen zu schützen, entsendet die Schamanin Sergra Dunkeldorn Reisende, um die aggressiven Vögel auszudünnen, bevor sie den Vorräten des Außenpostens ernsthaften Schaden zufügen."},{t="Die erste Jagd",b="Während die Schädlingsbekämpfung ein unmittelbares praktisches Ziel ist, betrachtet Sergra die Ebenenschreiter als Maßstab für Neuankömmlinge. Für sie sind die Vögel einfache Beute – leichtes Wild, das jungen Jägern beibringen soll, den Naturgewalten zu trotzen und Beute in den sonnenverbrannten Ebenen aufzuspüren. Die scharfen Schnäbel zurückzubringen beweist, dass ein Jäger die Geduld und das grundlegende kriegerische Geschick besitzt, die nötig sind, um sich den wilderen Bestien des Brachlands zu stellen."}},faq={{q="Warum geraten die Ebenenschreiter ins Visier?",a="Herden von Ebenenschreitern östlich des Wegekreuzes sind dreist genug geworden, Nahrungsvorräte zu plündern und vorbeiziehende Nachschublinien zu bedrängen. Sergra Dunkeldorn befiehlt deren Dezimierung, um die lebenswichtigen Vorräte der Siedlung zu bewahren.",al={"warum ebenenschreiter töten","ebenenschreiter problem","was ebenenschreiter getan haben"}},{q="Wer ist Sergra Dunkeldorn?",a="Sergra Dunkeldorn ist eine erfahrene Orcschamanin, die im Wegekreuz stationiert ist. Sie überwacht die Jagdprüfungen der Siedlung, bildet eintreffende Abenteurer aus und setzt sie gegen wilde Bestien ein, die die Vorhaben der Horde bedrohen.",al={"wer ist sergra","sergra dunkeldorn rolle","questgeber das wegekreuz"}},{q="Warum verlangt Sergra ausdrücklich ihre Schnäbel?",a="Der harte, scharfe Schnabel ist die primäre Waffe und das wichtigste Werkzeug des Ebenenschreiters bei der Nahrungssuche. Das Erbeuten ihrer Schnäbel dient als unbestreitbarer Beweis dafür, dass die plündernden Vögel erlegt wurden.",al={"warum ebenenschreiterschnäbel","ebenenschreiterschnabel beweis"}},{q="Was folgt nach dieser Jagd?",a="Sobald die Ebenenschreiter erledigt sind, prüft Sergra Euch an schnellerer, temperamentvollerer Beute, indem sie Euch beauftragt, die Zhevras zu jagen, die die Ebenen durchstreifen.",al={"was kommt danach","folgequest nach ebenenschreitern","jagdabfolge"}},{q="Wo halten sich diese Ebenenschreiter auf?",a="Sie streifen unmittelbar östlich und südöstlich des Wegekreuzes durch die Savannengrasländer und suchen entlang der Handelswege nach Nahrung.",al={"wo sind ebenenschreiter","ebenenschreiter orte","jagdgründe"}},{q="Ist dies Teil einer größeren Jagdreihe?",a="Ja. Diese Aufgabe markiert den Beginn von Sergra Dunkeldorns Jagdprüfungen im Brachland, die nach und nach zu immer gefährlicheren Bestien der Savanne übergehen.",al={"brachland jagdreihe","sergra questreihe"}}},fx={["416dd73a"]={q="Warum braucht Sergra Darkthorn einen Abenteurer statt der Wachen am Wegekreuz?",a="Die am Wegekreuz stationierten Wachen haben alle Hände voll damit zu tun, die Verteidigungsanlagen gegen die Angriffe der Quilboars instand zu halten und die örtlichen Wege zu sichern. Die lästigen Plünderer draußen in der Ebene zu jagen, erfüllt für Sergra einen doppelten Zweck: Es entlastet die Versorgung der Siedlung mit Nahrung und prüft zugleich, ob Neuankömmlinge über die Spurenlese- und Kampffertigkeiten verfügen, die sie zum Überleben im Brachland brauchen.",al={"warum soll ich geschickt werden","warum töten die wachen die ebnenläufer nicht","warum ein abenteurer gegen ebnenläufer"}}},fp="19,292,23.516.0,14.423.0,35.207.0,24.221.0,46.172.0,27.143.0,38.116.0,40.174.0"}
P.entries["quest:845"] = {n="Die Zhevras",s="Die Zhevras ist eine frühe Jagdprüfung, die von Sergra Dunkeldorn im Wegekreuz vergeben wird. Als Teil einer fortlaufenden Prüfung des kriegerischen Könnens in den Savannen des Brachlands werden junge Jäger damit beauftragt, flinke Zhevraläufer aufzuspüren und deren kraftvolle Hufe zu erbeuten.",h="Die Zhevras ist eine frühe Jagdprüfung, die von Sergra Dunkeldorn im Wegekreuz vergeben wird.",kw={"brachland","das wegekreuz","hufe","jagdprüfung","sergra dunkeldorn","zhevra","zhevraläufer"},ang={["class:Hunter"]="Für Scharfschützen und Fährtenleser, die sich im Brachland ihre ersten Sporen verdienen, dient das Nachstellen flinker Zhevraherden als unverzichtbare Praxis in Verfolgung und Präzision.",["faction:Horde"]="Das Wegekreuz verlässt sich auf durchreisende Abenteurer, um die umliegenden Wildtierpopulationen unter Kontrolle zu halten und die Versorgungswege der Siedlung frei zu halten.",["race:Tauren"]="Sergra weist ausdrücklich darauf hin, dass ein Zhevratritt einen ausgewachsenen Tauren von den Hufen reißen kann, was diese Prüfung zu einer passenden Mahnung macht, dass selbst Weidetiere der Ebenen Respekt verlangen."},sec={{t="Ein Schritt weiter in der Savanne",b="Nach einem ersten Ausdünnen der überwucherten Ebenenschreiter des Brachlands lenkt Sergra Dunkeldorn angehende Krieger der Horde auf etwas anspruchsvolleres Wild. Die gestreiften Zhevras streifen in Herden über die nördlichen und südlichen Ebenen. Obwohl sie nicht die Spitzenprädatoren der Savanne sind, handelt es sich um leichtfüßige Herdentiere, die für ihre hartnäckige Ausdauer und kräftige, knochenbrechende Tritte bekannt sind."},{t="Die Prüfungen von Darkthorn",b="Für Sergra geht es bei dieser Jagd weniger um die Beschaffung von Handelsgütern als vielmehr darum, das wachsende Können eines Abenteurers auf die Probe zu stellen. Sie verlangt vier intakte Hufe als physischen Beweis für den Abschuss und warnt davor, dass der Hinterhuftritt der Bestie genug Wucht besitzt, um einen ausgewachsenen Tauren auf die Keulen zu werfen. Wer sich gegen diese schnellen Läufer beweist, verdient sich das Recht auf noch tödlichere Prüfungen gegen die räuberischen Streuner der Ebenen."}},faq={{q="Wer vergibt diese Jagd?",a="Sergra Dunkeldorn, eine erfahrene Orcschamanin, die im Wegekreuz im zentralen Brachland stationiert ist, vergibt diese Prüfung, um heranwachsende Krieger der Horde zu testen.",al={"wer gibt die zhevras quest","questgeber zhevra","sergra dunkeldorn quest"}},{q="Wo sind die Zhevras zu finden?",a="Zhevraläufer durchstreifen die offenen Ebenen sowohl nördlich als auch südlich vom Wegekreuz im gesamten zentralen Brachland.",al={"wo sind zhevraläufer","zhevra aufenthaltsort","brachland zhevra karte"}},{q="Warum will Sergra Zhevrahufe?",a="Die Hufe dienen als Trophäenbeweis für eine saubere Jagd. Ihre Beine sind bemerkenswert kräftig, und die Rückkehr mit vier Hufen beweist, dass ein Jäger ein Tier bezwingen kann, das selbst einen mächtigen Tauren umwerfen könnte.",al={"warum zhevrahufe","zhevra huf beweis","warum zhevras jagen"}},{q="Was folgt nach dieser Quest?",a="Nachdem Ihr Eure Fähigkeiten gegen Zhevras bewiesen habt, stellt Sergra Euch in der Quest Jagt die Jägerin gegen echte Raubtiere auf die Probe.",al={"folgequest nach die zhevras","zhevra folgequest","darkthorn nächste quest"}},{q="Sind Zhevras gefährlich?",a="Obwohl sie im Allgemeinen friedliche Grasfresser sind, besitzen Zhevras enorme Beinkraft. Sergra warnt davor, dass ein einziger direkter Tritt eines aufgeschreckten oder in die Enge getriebenen Zhevraläufers einen stämmigen Tauren rücklings zu Boden strecken kann.",al={"wie gefährlich sind zhevras","zhevra gefahr","zhevra tritt"}},{q="Warum wurden davor Ebenenschreiter gejagt?",a="Sergra baut ihre Prüfungen mit allmählich steigendem Schwierigkeitsgrad auf. Ebenenschreiter dienen als erste Zielübungen, während Zhevras den Umgang mit schnellerer und physisch stärkerer Beute erfordern, bevor es gegen aggressive Savannenstreuner geht.",al={"vorherige quest","ebenenschreiter bedrohung verbindung"}}},fx={["6d2e3590"]={q="Warum will Sergra Darkthorn, dass The Zhevra gejagt werden?",a="Sergra Darkthorn testet Euer Jagdgeschick und stählt Euch für die brutale Wildnis des Brachlands. Während Steppenläufer grundlegende Zielübungen bieten, sind The Zhevra robustere Bestien, deren kraftvolle Tritte Eure Reflexe und Ausdauer auf die Probe stellen. Indem sie Euch auf sie ansetzt, stellt Sergra sicher, dass Ihr mit gefährlichen Wildtieren umgehen könnt, bevor sie Euch gegen die Spitzenprädatoren des Gebiets aussendet.",al={"warum the zhevra jagen","sergra motiv","sergra darkthorn grund"}},["1cbbdcd0"]={q="Was sind die Zhevra-Läufer?",a="The Zhevra sind schnelle, gestreifte Equiden, die in den trockenen Savannen des Brachlands heimisch sind. Wenn sie in Herden durch die Ebenen nördlich und südlich von Das Wegekreuz ziehen, verlassen sie sich auf Geschwindigkeit und beeindruckende Hinterbeine, um unter Streunern und Raptoren zu überleben. Obwohl sie von Natur aus keine aggressiven Raubtiere sind, können ihre Tritte einen ausgewachsenen Tauren von den Beinen holen.",al={"was sind the zhevra","zhevra-läufer","wen jagen wir"}}},fp="10,267,24.378.0,23.404.0,22.145.0,27.102.0,35.211.0,28.123.0,22.198.0,42.235.0"}
P.entries["quest:846"] = {n="Ganns Rache",s="Ganns Rache ist eine Quest der Horde im südlichen Brachland, bei der der trauernde Tauren-Verbannte Gann Steinkeil Vergeltung an der Expedition von Bael Modan plant. Nachdem Prospector Khazgorm eliminiert wurde, schickt Gann Reisende in die Zwergenfestung, um flüchtige Munition für einen explosiven Gegenangriff zu beschaffen.",h="Ganns Rache ist eine Quest der Horde im südlichen Brachland, bei der der trauernde Tauren-Verbannte Gann...",kw={"bael modan","brachland","dynamit","sprengstoff","gann steinkeil","eisenschmiede","khazgorm","nitroglyzerin","natriumnitrat","holzbrei"},ang={["faction:Horde"]="Das Neutralisieren der Zwergenoperationen im südlichen Brachland verhindert, dass ein militärischer Brückenkopf der Allianz die Transitrouten zwischen Mulgore, dem Wegekreuz und der südlichen Grenze abschneidet.",["profession:Engineering"]="Die Kombination aus Nitroglyzerin, Natriumnitrat und Holzbrei demonstriert die klassische zwergische Rezeptur für Industriedynamit, die spontan für die asymmetrische Kriegsführung angepasst wurde.",["race:Tauren"]="Für die Tauren stellt Bael Modan eine schwere Wunde an der Earth Mother dar, was die Sabotage der zwergischen Maschinerie zu einer spirituellen und territorialen Pflicht macht."},sec={{t="Eine Kostprobe der eigenen Medizin",b="Der Tod von Prospector Khazgorm versetzte der Ausgrabungsstätte von Bael Modan einen Rückschlag, doch Gann Steinkeil weiß, dass dies nur vorübergehend ist. Die Operationen der Zwerge ruhen selten lange, und bald wird ein neuer Vorarbeiter eintreffen, um die Maschinen zu beaufsichtigen, die das Land seiner Ahnen ausweiden. Da er sich weigert mitanzusehen, wie die Erde durch weitere Ausgrabungen leidet, beschließt Gann, mit der Technologie der Eindringlinge zurückzuschlagen. Indem er ihre Sprengausrüstung in ein Werkzeug der Sabotage verwandelt, plant er, ihre Festung von innen heraus zu erschüttern."},{t="Überfall auf die Festung",b="Die Festung von Bael Modan dient sowohl als Ausgrabungsbasis als auch als befestigte Garnison, ausgestattet mit Soldaten, Scharfschützen und Offizieren, die die Interessen der Zwerge im Brachland schützen. Gann findet heraus, dass die Verteidiger Materialien lagern, die sich für industrielle Sprengungen eignen: Nitroglyzerin, Holzbrei und Natriumnitrat. Er beauftragt Verbündete der Horde damit, den Umkreis zu infiltrieren, um den Zwergen diese flüchtigen Komponenten direkt abzunehmen und genügend Rohmaterial für eine verheerende Sprengladung anzuhäufen."}},faq={{q="Warum sinnt Gann Steinkeil auf Rache?",a="Die Zwerge aus Eisenschmiede in Bael Modan überrannten Ganns angestammte Heimat, entweihten den Boden und vertrieben sein Volk, um ihre Ausgrabungsstätte zu errichten. Nachdem er den obersten Ausgräber getötet und dessen Tagebuch an sich gebracht hat, will Gann ihrer anhaltenden Zerstörung endgültig Einhalt gebieten.",al={"warum gann wütend ist","gann steinkeil motiv","was haben die zwerge gann angetan"}},{q="Wo sind die explosiven Materialien zu finden?",a="Die Zutaten werden vom zwergischen Personal mitgeführt, das Bael Modan verteidigt. Scharfschützen, Soldaten und Offiziere in und um die befestigte Ausgrabungsstätte im südlichen Brachland tragen die Nitroglyzerinfläschchen, Holzbreibündel und Natriumnitratproben bei sich.",al={"wo man nitroglyzerin bekommt","wie man holzbrei bekommt","wo ist natriumnitrat"}},{q="Warum benötigt Gann Holzbrei und Chemikalien?",a="Zwergische Ausgrabungsbaupläne zeigen, dass die Stabilisierung von flüchtigem Nitroglyzerin mit Holzbrei und die Mischung mit Natriumnitrat einen zuverlässigen industriellen Sprengstoff ergibt. Gann beabsichtigt, eine maßgeschneiderte Sprengladung herzustellen, um wichtige zwergische Bauwerke in die Luft zu jagen.",al={"warum holzbrei","was stellt gann her","zutaten für ganns bombe"}},{q="Was geschieht nach dem Sammeln der Vorräte?",a="Sobald Ihr die Rohkomponenten zurückbringt, setzt Gann eine Sprengladung zusammen und beauftragt Euch damit, sie zu benutzen, um die Flugmaschine der Zwerge an der Ausgrabungsstätte von Bael Modan zu sprengen – einen entscheidenden Teil der Infrastruktur der Stätte.",al={"wie geht ganns rache weiter","nach dem sammeln der zutaten"}},{q="Warum beendet der Tod von Khazgorm die Bedrohung durch die Zwerge nicht?",a="Khazgorm war lediglich der leitende Ausgräber. Die militärische Präsenz der Zwerge in Bael Modan ist tief verwurzelt und durch Verteidigungswälle sowie Nachschublinien befestigt. Eisenschmiede wird einfach einen weiteren Vorarbeiter schicken, um die Grabungen fortzusetzen, es sei denn, der gesamte Stützpunkt erleidet einen verheerenden Schlag.",al={"warum khazgorms tod nicht genügte","ist bael modan aufgehalten"}},{q="Welche strategische Bedrohung stellt Bael Modan für die Horde dar?",a="Obwohl seine Festung ursprünglich zur Verteidigung der Ausgrabungsstätte erbaut wurde, hat sich Bael Modan zu einer schwer bemannten Bastion der Allianz entwickelt. Gelegen an den Handelsrouten des südlichen Brachlands stellt es eine aktive militärische Bedrohung für nahegelegene Siedlungen der Horde auf Kalimdor dar.",al={"warum sich die horde für bael modan interessiert","bael modan bedrohung"}}},fx={["410ab5f4"]={q="Wer trägt die für den Sprengstoff benötigten Vorräte?",a="Die Vorräte befinden sich in der Zwergengarnison, die in Bael Modan stationiert ist. Die Schützen, Soldaten und Offiziere innerhalb der Ausgrabung und der Festung nutzen häufig Sprengpulver und Maschinen, um das Land aufzureißen, was bedeutet, dass sie reichlich Vorräte an flüchtigen Chemikalien und Stabilisatoren griffbereit halten.",al={"wer hat die sprengstoffmaterialien","bael modan zwerge","revenge of gann ziele"}},["5f27d24f"]={q="Warum braucht Gann Euch, anstatt Bael Modan selbst anzugreifen?",a="Gann Steinkeil ist ein ausgestoßener Überlebender eines zerschlagenen Stammes, der auf eigene Faust handelt, ohne die Unterstützung einer großen Kriegspartei. Eine ganze befestigte Garnison der Eisenschmiede-Zwerge im Alleingang zu erschlagen, liegt weit außerhalb seiner Reichweite, also verlässt er sich auf einen fähigen Champion der Horde, um in die Festung einzudringen und das zu beschaffen, was er braucht.",al={"warum braucht gann mich","warum kann gann es nicht selbst erledigen","warum ich revenge of gann"}}},fp="15,306,29.495.0,16.500.0,39.274.0,40.250.0,43.257.0,42.208.1,52.270.0,51.255.0"}
P.entries["quest:847"] = {n="Arglist des Raptors",s="Nachdem Tor'gans Kugel Gor'mul die Essenz des Raptors verliehen hat, lässt die Macht, die er spürte, ihn über die Magie der Schamanen nachdenken. Er schickt Euch los, um Tor'gan mitzuteilen, dass er fürs Erste überzeugt ist und zuhören wird.",h="Nachdem Tor'gans Kugel Gor'mul die Essenz des Raptors verliehen hat, lässt die Macht, die er spürte, ihn über...",kw={"arathihochland","gor'mul","list des raptors","hammerfall","schamane","tor'gan"},sec={{t="Ein überzeugter Krieger",b="Gor'mul fragt sich laut, ob die Macht, die ihn durchströmt, die Macht der Schamanen ist, die Tor'gan ihm zu zeigen versuchte. Er findet es interessant. Er bittet Euch, Tor'gan auszurichten, dass er fürs Erste überzeugt ist und sich anhören wird, was Tor'gan zu sagen hat."},{t="Tor'gans Antwort",b="Tor'gan sagt, dass er mit Gor'mul sprechen wird, sobald die Verzauberung nachlässt. Er dankt Euch dafür, dass Ihr geholfen habt, Gor'mul wieder unter die Lebenden zu bringen, und nimmt an, dass Gor'mul ebenfalls dankbar ist."}},faq={{q="Wer schickt Euch, um mit Tor'gan zu sprechen?",a="Gor'mul tut das. Nachdem er die Macht der Kugel gespürt hat, bittet er Euch, Tor'gan mitzuteilen, dass er fürs Erste überzeugt ist.",al={"wer startet list des raptors 3","wer vergibt diese quest","wo beginnt dies"}},{q="Warum ändert Gor'mul seine Meinung über Tor'gan?",a="Er fragt sich, ob die Macht, die er spürte, die Macht der Schamanen ist, die Tor'gan ihm zu zeigen versuchte, und er findet es interessant. Er ist fürs Erste überzeugt und wird Tor'gan zuhören.",al={"warum hat gormul seine meinung geaendert","gormul schamanenmagie","ist gormul ueberzeugt"}},{q="Was geschah vor diesem Schritt?",a="Sie folgt dem früheren Schritt, bei dem Ihr Tor'gans Kugel zu Gor'mul gebracht habt.",al={"vorherige quest","vorbedingung list des raptors"}}},fp="19,205,19.254.0,15.180.1,36.125.0,47.182.0,27.74.0"}
P.entries["quest:848"] = {n="Pilzsporen",s="Apotheker Helbrim von der Königlichen Apothekervereinigung beauftragt Abenteurer der Horde damit, Pilzsporen rund um die Oasen des Brachlandes zu sammeln. Die seltsamen, mutativen Energien, die durch diese Quellen fließen, haben die einheimische Flora in wirkungsvolle Reagenzien verwandelt. Helbrim versucht, diese einzigartigen Exemplare zu ernten, um Gebräue für seine Kollegin in Donnerfels herzustellen.",h="Apotheker Helbrim von der Königlichen Apothekervereinigung beauftragt Abenteurer der Horde damit, Pilzsporen...",kw={"apotheker helbrim","apothekerin zamah","brachland","das wegekreuz","die vergessenen teiche","pilzsporen","die blühende oase","königliche apothekervereinigung","die brackige oase"},ang={["class:Druid"]="Die Oasen bergen eine unnatürlich turbulente Welle von Naturmagie, die aggressive Mutationen im umliegenden Ökosystem hervorruft.",["faction:Horde"]="Die Untersuchung der gestörten Gewässer des Brachlands trägt dazu bei, die lebenswichtigen Pfade zu schützen, die Orgrimmar, das Wegekreuz und Donnerfels verbinden.",["profession:Herbalism"]="Die beladenen Pilze, die rund um die Oasen des Brachlands wachsen, veranschaulichen, wie plötzliche Einflüsse von Umweltenergie gewöhnliche Flora in wirkungsvolle Reagenzien verwandeln können.",["race:Undead"]="Selbst weit entfernt von Lordaeron setzen Forscher der Verlassenen ihre alchemistische Arbeit fort und nutzen Kalimdors natürliche Anomalien für die Ziele der Königlichen Apothekervereinigung."},sec={{t="Lebendige und mutierte Flora",b="Das Brachland ist im Allgemeinen eine trockene, sonnenverbrannte Savanne, doch seine Oasen – wie Die vergessenen Teiche, Die blühende Oase und Die brackige Oase – strotzen vor unnatürlicher Vitalität. Eine merkwürdige Welle von Lebensenergie entspringt diesen Gewässern und verformt sowie stärkt die Pflanzen und Bestien, die daraus trinken. Beladene Pilze, die an den schlammigen Ufern wachsen, nehmen diese intensiven Strömungen auf und füllen ihre Sporen mit seltenen Eigenschaften, die die Neugier vorbeikommender Alchemisten wecken."},{t="Die Königliche Apothekervereinigung in Kalimdor",b="Obwohl er fernab von Unterstadt im Wegekreuz stationiert ist, widmet sich Apotheker Helbrim weiterhin den Forschungen der Königlichen Apothekervereinigung. Da er die seltsame Wirksamkeit von Kalimdors einheimischen Reagenzien erkennt, sammelt er diese veränderten Sporen, um mächtige Mixturen herzustellen. Die hier gesammelten Exemplare sind für Apothekerin Zamah in Donnerfels bestimmt, was die subtilen, weitreichenden wissenschaftlichen Bemühungen zeigt, die die Verlassenen in den verbündeten Ländern durchführen."}},faq={{q="Wo wachsen diese Pilzsporen?",a="Die Sporen werden von beladenen Pilzen gesammelt, die am Wasserrand der Oasen im Brachland wachsen, darunter Die vergessenen Teiche, Die blühende Oase und Die brackige Oase.",al={"wo pilzsporen finden","pilzsporen fundort","beladene pilze fundort"}},{q="Warum sind die Pilze in der Nähe der Oasen verändert?",a="Eine mächtige Welle von Lebensenergie fließt durch das Wasser der Oasen im Brachland. Anstatt ein normales Pflanzenwachstum aufrechtzuerhalten, belebt und verändert diese Energie die umliegende Tier- und Pflanzenwelt aggressiv.",al={"warum die pilze mutiert sind","oasen lebensenergie","was stimmt mit den oasen nicht"}},{q="Wer ist Apotheker Helbrim?",a="Apotheker Helbrim ist ein Mitglied der Königlichen Apothekervereinigung der Verlassenen, das im Wegekreuz im Brachland stationiert ist. Er erforscht die ungewöhnliche Biologie der Region und sammelt einheimische Materialien für alchemistische Studien.",al={"helbrim lore","wer ist helbrim","apotheker im wegekreuz"}},{q="Was plant Helbrim mit den Sporen zu tun?",a="Helbrim nutzt die wirkungsvollen Sporen, um ein bestimmtes Gebräu herzustellen, das er an seine Forschungskollegin, Apothekerin Zamah, in der Taurenstadt Donnerfels schicken will.",al={"wofür sind die sporen","pilzsporen zweck"}},{q="Warum sind Apotheker der Verlassenen im Brachland tätig?",a="Als Teil der Horde erforschen Wissenschaftler der Verlassenen fremde Umgebungen und die einzigartige Flora in ganz Kalimdor, um neue Reagenzien für Medikamente, Toxine und Gebräue zu entdecken.",al={"warum untote im brachland sind","königliche apothekervereinigung in kalimdor"}},{q="Welche Oase ist am sichersten, um die Sporen zu sammeln?",a="Die vergessenen Teiche nordwestlich vom Wegekreuz sind im Vergleich zur blühenden Oase oder der brackigen Oase im Süden von Tieren niedrigerer Stufe bevölkert, was sie zum sichersten Ort macht, um die Pilze zu sammeln.",al={"leichteste oase für sporen","sicherste oase brachland"}}},fx={f81deb18={q="Warum will Apotheker Helbrim, dass die Pilzsporen gesammelt werden?",a="Apotheker Helbrim untersucht die seltsamen Lebensenergien, die durch die Oasen des Brachlands strömen und die umgebende Flora und Fauna mutieren lassen. Die Königliche Apothekervereinigung hält die potenten Eigenschaften dieser veränderten Pilze für ihre Forschung für einzigartig wertvoll. Helbrim benötigt die Exemplare dringend, um ein spezielles Gebräu vorzubereiten, das an seine Mitarbeiterin Apothecary Zamah weitergeleitet werden muss, die in Donnerfels stationiert ist.",al={"warum will helbrim pilzsporen","helbrim motiv","warum pilzsporen sammeln"}}},fp="13,353,25.469.0,40.448.0,34.180.0,45.206.0,26.208.0,45.173.0,55.176.0,49.213.0"}
P.entries["quest:849"] = {n="Ganns Rache",s="Ganns Rache markiert den finalen Schlag in Gann Steinkeils Vendetta gegen die Zwerge von Bael Modan. Bewaffnet mit einer maßgeschneiderten Sprengladung, hergestellt nach gestohlenen zwergischen Bauplänen, wird ein Agent der Horde damit beauftragt, die geschätzte Flugmaschine der Expedition zur Detonation zu bringen, um den gefallenen Stamm der Stonespire zu rächen.",h="Ganns Rache markiert den finalen Schlag in Gann Steinkeils Vendetta gegen die Zwerge von Bael Modan.",kw={"bael modan","dynamitstange von gann","flugmaschine","gann steinkeil","khazgorm","stonespire stamm","brachland","donnerfels"},ang={["faction:Horde"]="Die Zerstörung der Flugmaschine von Bael Modan neutralisiert eine Luftwaffe der Allianz, die fähig war, tief im südlichen Brachland Aufklärung zu betreiben und zuzuschlagen.",["profession:Engineering"]="Der an der Maschine verwendete Sprengstoff wurde konstruiert, indem Baupläne aus Eisenschmiede gegen einen Gyrokopter gewendet wurden – ein ironischer Geniestreich der Feld-Sabotage.",["race:Tauren"]="Den Clan der Stonespire durch die Zerstörung zwergischer Kriegsmaschinen zu rächen, trifft bei jedem Tauren, der seine angestammte Heimat vor Entweihung verteidigt, einen tiefen Nerv."},sec={{t="Ein Symbol der Beherrschung",b="Die Ausgrabung von Bael Modan ist mehr als nur ein aufdringlicher Bergbaubetrieb; sie ist eine bewaffnete Festung, die direkt auf dem angestammten Land der vertriebenen Stonespire-Tauren errichtet wurde. Entscheidend für die operative Reichweite und die militärische Macht der Prospektoren ist ihre Gyrokopter-Flugmaschine. Stationiert auf einem Wachturm über der Ausgrabungsstätte, überwacht das mechanische Fluggerät das umliegende Brachland, schützt Nachschublinien und fungiert als schwebendes Symbol für das dreiste Eindringen der Allianz auf kalimdorischen Boden."},{t="Gegen seine Schöpfer gewandt",b="Nachdem er die Baupläne von Prospector Khazgorm erbeutet hat, fertigt Gann Steinkeil eine spezielle Sprengladung an, die Dynamitstange von Gann genannt wird. Indem diese explosive Munition an der Flugmaschine angebracht wird, sorgt Gann dafür, dass die technologische Hybris der Zwerge zu ihrem Verderben wird. Die resultierende Explosion zerschmettert ein lebenswichtiges militärisches Gut, versetzt dem Kontingent von Bael'dun einen demütigenden Schlag und ehrt die Geister des verlorenen Stammes."}},faq={{q="Warum will Gann ausgerechnet die Flugmaschine zerstören?",a="Die Flugmaschine ist sowohl eine Kriegswaffe als auch ein entscheidender Teil der Infrastruktur von Bael Modan, der den Zwergen Luftaufklärung ermöglicht. Für Gann ist sie vor allem ein unverhohlenes Symbol zwergischer Macht und eine beleidigende Präsenz, die über dem Land aufragt, das sein hingeschlachteter Stamm einst seine Heimat nannte.",al={"warum gyrokopter zerstören","flugmaschine zweck","warum ziel flugmaschine"}},{q="Wo befindet sich die Flugmaschine in Bael Modan?",a="Die Flugmaschine steht auf einer hölzernen Turmplattform auf halber Höhe der Rampe, die in die Hauptausgrabungsgrube führt, und nicht innerhalb oder direkt an der primären Zwergenfestung.",al={"wo ist flugmaschine","flugmaschine standort","bael modan gyrokopter ort"}},{q="Wie hat Gann den Sprengsatz hergestellt?",a="Gann fertigte die Dynamitstange von Gann mithilfe technischer Schemata und Konstruktionspläne an, die kürzlich von Prospector Khazgorm geborgen wurden, und wendete so die eigenen Entwürfe der Zwerge gegen sie selbst.",al={"wie bombe hergestellt","dynamitstange ursprung","khazgorm pläne sprengstoff"}},{q="Welchem Stamm gehört Gann an?",a="Gann gehört zum Stamm der Stonespire, einem Taurenclan, der historisch das südliche Brachland bewohnte, bis die Ausgrabung der Zwerge aus Eisenschmiede sie gewaltsam vertrieb und ihre Siedlung zerstörte.",al={"gann stamm","was ist stonespire stamm","wer sind stonespire tauren"}},{q="Stoppt die Zerstörung der Maschine die Ausgrabung dauerhaft?",a="Sie schwächt die Lufthoheit und Infrastruktur von Bael Modan erheblich und verschafft Gann persönliche Vergeltung, doch die tief verschanzten zwergischen Ausgräber und ihre Festung bleiben eine aktive Bastion der Allianz in der Region.",al={"ist bael modan gestoppt","fällt bael modan","hat gann gewonnen"}},{q="Welche Anerkennung gewährt Gann nach Abschluss dieser Mission?",a="Gann verkündet, dass der Held, der die Maschine zerstört hat, in Donnerfels als Verteidiger der heiligen Taurenlande und als beständiger Champion seines verlorenen Stammes verehrt werden wird.",al={"gann abschluss","gann quest ende","was sagt gann"}}},fx={["947c7a95"]={q="Was ist die Flugmaschine in Bael Modan?",a="Das Ziel ist ein Zwergen-Gyrokopter, der in Bael Modan stationiert ist. Diese Flugmaschine wurde von der Zwergenexpedition gebaut und gewartet und fungiert als lebenswichtige Infrastruktur für ihre Ausgrabung, dient als luftgestützte Kriegswaffe und steht als drohendes Symbol für das Eindringen der Zwerge, das Ganns Volk aus seiner angestammten Heimat vertrieben hat.",al={"bael modan flugmaschine","was ist das ziel in revenge of gann","zwergenflugmaschine bael modan"}}},fp="15,303,22.481.0,22.425.1,62.298.0,50.180.0,41.183.0,31.196.0,60.226.0,61.167.1"}
P.entries["quest:85"] = {n="Die verlorene Halskette",s="Die verlorene Halskette ist eine einführende Aufgabe im südlichen Wald von Elwynn, die von „Tantchen“ Bernice Steinfeld vergeben wird. Da sie Diebstahl durch den schelmischen kleinen Jungen des rivalisierenden Clans vermutet, schickt Bernice Abenteurer über die Straße, um Billy Maclure zur Rede zu stellen und ihr verschollenes Erbstück wiederzubeschaffen.",h="Die verlorene Halskette ist eine einführende Aufgabe im südlichen Wald von Elwynn, die von „Tantchen“ Bernice...",kw={"bernice","billy","elwynn","hof","maclure","halskette","steinfeld","weinberge"},ang={["faction:Alliance"]="Für Neulinge der Allianz, die ihre Laufbahn im Wald von Elwynn beginnen, sind die Schlichtungen der belanglosen Streitigkeiten zwischen den zankenden Familien Steinfeld und Maclure ein klassischer Vorgeschmack auf das hiesige Grenzlandleben.",["race:Human"]="Die Missgunst zwischen den Steinfelds und den Maclures zeigt, dass nicht aller Unfrieden im Königreich Sturmwind von Defias-Gesetzlosen oder Gnoll-Kriegstrupps ausgeht; alte ländliche Nachbarschaftsfehden reichen genauso tief."},sec={{t="Eine nachbarschaftliche Anschuldigung",b="Die Familien Steinfeld und Maclure teilen sich angrenzende Ländereien im südlichen Wald von Elwynn, doch zwischen ihnen herrscht kaum Wohlwollen. Als „Tantchen“ Bernice Steinfeld bemerkt, dass ihre geliebte Halskette verschwunden ist, zögert sie keine Sekunde, mit dem Finger auf den Jüngsten des rivalisierenden Haushalts zu zeigen. Fest davon überzeugt, dass der junge Billy Maclure sich auf ihren Hof geschlichen und den Schmuck an sich gerissen hat, bittet die verbitterte Witwe jeden hilfsbereiten Reisenden, zu den Weinbergen hinüberzugehen, den Jungen aufzuspüren und die Rückgabe zu fordern."},{t="Ein Junge mit Appetit",b="Die Konfrontation mit Billy Maclure auf dem benachbarten Weinberg verkompliziert die Angelegenheit rasch. Empört bestreitet Billy, die Halskette entwendet zu haben, und beteuert, kein Dieb zu sein. Mit einem vielsagenden Grinsen deutet er jedoch an, dass er durchaus wissen könnte, was tatsächlich aus dem Schmuckstück geworden ist – vorausgesetzt, jemand stillt seinen knurrenden Magen zuerst mit einer frischen Schweinefleischpastete."}},faq={{q="Wer ist Tantchen Bernice Steinfeld?",a="Tantchen Bernice Steinfeld ist eine ältere Witwe, die auf dem Hof der Steinfelds im südlichen Wald von Elwynn lebt. Sie hegt tiefes Misstrauen gegenüber der benachbarten Familie Maclure, insbesondere gegen deren unruhestiftenden jungen Sohn Billy.",al={"wer ist tantchen bernice","bernice steinfeld","wer gibt die verlorene halskette"}},{q="Hat Billy Maclure die Halskette tatsächlich gestohlen?",a="Billy bestreitet bei der Konfrontation beharrlich, ein Dieb zu sein. Er deutet an, dass er wissen könnte, wer sie genommen hat, weigert sich jedoch, das Geheimnis zu lüften, ehe er ordentlich verköstigt wurde.",al={"ist billy ein dieb","hat billy sie gestohlen","hat billy die halskette genommen"}},{q="Wo finde ich Billy Maclure?",a="Billy Maclure treibt sich für gewöhnlich zwischen den Weinreben auf den Weinbergen der Maclures herum, die direkt östlich gegenüber dem Hof der Steinfelds auf der anderen Straßenseite liegen.",al={"billy maclure aufenthaltsort","wo ist billy","billy maclure finden"}},{q="Warum mögen sich die Steinfelds und die Maclures nicht?",a="Die beiden benachbarten Familien liegen seit Jahren in einer verbitterten ländlichen Fehde. Spannungen kochen wegen Landbesitz, Stolz und langjährigen persönlichen Fehden hoch, was dazu führt, dass beide Seiten voneinander sofort das Schlimmste vermuten.",al={"familienfehde","fehde zwischen steinfeld und maclure","warum hassen sie sich"}},{q="Was geschieht nach dem Gespräch mit Billy Maclure?",a="Billy beteuert, viel zu hungrig zu sein, um sich daran zu erinnern, wo die Halskette geblieben ist, und schickt Euch direkt zu Tantchen Bernice zurück, damit sie ihm im Austausch für die Information eine Schweinefleischpastete backt.",al={"wie geht es weiter","nach die verlorene halskette","naechste quest"}},{q="Wo findet diese Quest statt?",a="Die Quest findet vollständig im südlichen Wald von Elwynn statt und führt zwischen dem Hof der Steinfelds und den angrenzenden Weinbergen der Maclures hin und her.",al={"questzone","wo ist die verlorene halskette"}}},fx={b7900c48={q="Warum will Tante Bernice ihre Halskette zurück?",a="Tante Bernice ist eine ältere Witwe, und die Halskette ist ein zutiefst geschätzter persönlicher Besitz. Der Verlust belastet sie sehr, und sie verdächtigt sofort die rivalisierende Familie von nebenan – speziell den jungen Billy Maclure –, sie gestohlen zu haben. Das Wiedererlangen des Erbstücks würde ihr Seelenfrieden bringen und das Herz einer alten Witwe erwärmen.",al={"warum will bernice die halskette","bernice halskettenmotiv","bedeutung stonefield halskette"}},["27b02d6f"]={q="Warum stellt Tante Bernice Billy Maclure nicht selbst zur Rede?",a="Die erbitterte Fehde zwischen den Steinfelds und den Maclures macht es für beide Seiten fast unmöglich, zivilisiert miteinander zu sprechen, ohne einen Streit vom Zaun zu brechen. Bernice kann nicht einfach selbst zu den Weinberge der Maclures hinübergehen, und die Wachen von Sturmwind sind viel zu sehr damit beschäftigt, sich mit Gnollen und Defias-Banditen auseinanderzusetzen, um kleine Streitigkeiten zwischen benachbarten Bauern zu schlichten. Ein vorbeikommender Abenteurer bietet eine neutrale Partei, die den Jungen direkt befragen kann.",al={"warum braucht bernice mich","warum einen abenteurer zu billy schicken","warum nicht die wachen von sturmwind fragen"}}},fp="13,184,23.386.0,22.232.1,33.196.0,46.144.1,31.117.0,55.206.0,44.156.1,33.101.0"}
P.entries["quest:850"] = {n="Anführer der Kolkar",s="Anführer der Kolkar leitet einen Feldzug ein, der von dem Orc Regthar Totenfurt angeführt wird, um aufstrebende Kriegsherren der Zentauren im Brachland zu zerschlagen. Die nomadischen Kolkar haben den Tauren über Generationen hinweg zugesetzt, doch neu aufgetauchte Häuptlinge organisieren ihre unorganisierten Banden zu einer ernsthaften militärischen Bedrohung. Regthar beauftragt die Streiter der Horde damit, Barak Kodobane bei den Vergessenen Teichen zur Strecke zu bringen, bevor sich sein Einfluss weiter ausbreiten kann.",h="Anführer der Kolkar leitet einen Feldzug ein, der von dem Orc Regthar Totenfurt angeführt wird, um...",kw={"barak","brachland","zentauren","das wegekreuz","deathgate","die vergessenen teiche","kodobane","kolkar","regthar"},ang={["faction:Horde"]="Die Kreuzungen des Brachlands dienen als unverzichtbare Lebensader, die Mulgore, Durotar und weiter entfernte Vorposten der Horde verbindet. Die Ausschaltung der Kolkar-Führung schützt verwundbare Nachschubkarawanen vor verheerenden Hinterhalten.",["race:Orc"]="Thrall verpflichtete die Horde zum Schutz der Tauren, und erfahrene Veteranen wie Regthar Totenfurt nehmen diesen Bluteid ernst; sie behandeln Kriegstreiber der Zentauren als unmittelbare strategische Bedrohung für die Hoheit der Orcs im Brachland.",["race:Tauren"]="Für die Tauren ist das Niedermähen der Kolkar-Befehlshaber eine Frage des Überlebens und der Vergeltung. Zentaurenclans metzelten Stämme nieder und vertrieben die Shu'halo über Jahrzehnte hinweg von ihren angestammten Weiden, ehe die Horde in Kalimdor Fuß fassen konnte."},sec={{t="Eine aufkeimende Bedrohung im Dürreland",b="Seit zahllosen Jahren haben die pferdeleibigen Zentauren Kalimdor terrorisiert und die nomadischen Tauren beinahe an den Rand der Auslöschung getrieben, ehe Thralls Horde eintraf und das Blatt wendete. Im Brachland zieht der vorherrschende Stamm der Kolkar für gewöhnlich in zerstreuten, zersplitterten Raubtrupps umher. In letzter Zeit jedoch haben aggressive Häuptlinge damit begonnen, die verstreuten Banden zu vereinen, wodurch aus einfachen Plünderern eine geschlossene militärische Macht wird, die den befestigten Vorposten der Horde die Stirn bieten kann."},{t="Der Bestie den Kopf abschlagen",b="In einem Lager westlich vom Wegekreuz stationiert, erkannte der Orc-Krieger Regthar Totenfurt, dass die Kolkar stark auf bloßes Imponiergehabe und rohe Gewalt setzen, um ihren Zusammenhalt zu wahren. Ohne starke Befehlshaber verfallen ihre Plünderer in interne Streitigkeiten. Um ihren Vormarsch zu bremsen, weist Regthar die Abenteurer der Horde an, der Schlange den Kopf abzuschlagen – beginnend mit Barak Kodobane, einem ehrgeizigen Anführer, der nahe den grünen Gewässern der Vergessenen Teiche lagert."},{t="Der Erste von Vielen",b="Die Tötung von Barak Kodobane versetzt den nördlichen Lagern der Kolkar einen schweren Schlag, doch Regthar weiß, dass Barak lediglich die Vorhut einer größeren Bewegung darstellt. Seine Beseitigung markiert den Auftakt eines gezielten Feldzugs zur Zerschlagung der Führungsriege der Kolkar und ebnet den Weg zur Jagd auf die Häuptlinge Verog der Derwisch und Hezrul Blutmal im gesamten Brachland."}},faq={{q="Wer ist Barak Kodobane?",a="Barak Kodobane ist ein grimmiger Anführer der Kolkar-Zentauren, der Plünderer um die vergessenen Teiche nördlich vom Wegekreuz um sich scharte. Bekannt für seine Gerissenheit und Grausamkeit, erwies er sich als weitaus gefährlicher als gewöhnliche nomadische Räuber, da er zerstreute Clans zu einer offensiven Bedrohung gegen die Horde zusammenschloss.",al={"barak","wer ist barak","barak kodobane geschichte"}},{q="Wo kann ich Barak Kodobane finden?",a="Barak Kodobane unterhält ein Lager an den Vergessenen Teichen, einer fruchtbaren Oase nördlich vom Wegekreuz im zentralen Brachland. Er ist für gewöhnlich von treuen Kolkar-Wachen umgeben.",al={"barak standort","wo ist barak","vergessene teiche barak"}},{q="Wer ist Regthar Totenfurt?",a="Regthar Totenfurt ist ein Orc-Veteran in einem kleinen Bunkerlager direkt westlich vom Wegekreuz. Er überwacht die Bewegungen der Zentauren im Brachland und koordiniert Präventivschläge, um Siedlungen der Horde vor organisierten Überfällen zu schützen.",al={"regthar","wer gibt anführer der kolkar","regthar totenfurt geschichte"}},{q="Warum sind die Kolkar ein solches Problem für die Horde?",a="Die Zentauren führen seit Generationen einen unbarmherzigen, beinahe vernichtenden Krieg gegen die Tauren. Als vollwertige Mitglieder der Horde verlassen sich die Tauren auf ihre Verbündeten, um ihre angestammten Jagdgründe und Handelswege im Brachland vor der fortwährenden Expansion der Zentauren zu sichern.",al={"warum gegen kolkar kämpfen","kolkar bedrohung","zentauren horde feindschaft"}},{q="Was geschieht, nachdem Barak getötet wurde?",a="Nach dem Sieg über Barak Kodobane wird offenbar, dass andere Häuptlinge an weiteren Orten im Brachland Truppen zusammenziehen. Regthar schickt Euch unverzüglich los, um Verog der Derwisch an der Brackigen Oase und anschließend Hezrul Blutmal an der Blühenden Oase zu beseitigen, was schließlich in der Verteidigung gegen einen direkten Angriff der Kolkar gipfelt.",al={"folgequest nach barak","anführer der kolkar folgequest","was kommt danach"}},{q="Warum versammeln sich die Kolkar um die Oasen?",a="Wasser und fruchtbares Land sind im trockenen Klima des Brachlands kostbare Schätze. Indem sie natürliche Quellen wie Die vergessenen Teiche besetzen, sichern sich die Kolkar lebenswichtige Wasservorräte und verwehren Reisenden und Taurenjägern gleichzeitig strategische Rastplätze.",al={"warum sind zentauren an oasen","kolkar wasser","vergessene teiche zentauren"}}},fx={["55ee765d"]={q="Warum will Regthar Deathgate, dass die Kolkar Leaders getötet werden?",a="Zentaurenstämme schikanieren die Tauren seit Generationen, aber die Kolkar im Brachland sind normalerweise zersplittert und unorganisiert. Kürzlich haben charismatische Häuptlinge begonnen, die verstreuten Kriegstrupps zu einer vereinten Bedrohung gegen die Siedlungen der Horde zu sammeln. Regthar weiß, dass, wenn man diesen aufstrebenden Kommandeuren erlaubt, sich zu organisieren, der Stützpunkt der Horde im gesamten Brachland zusammenbrechen könnte. Das Eliminieren von Figuren wie Barak Kodobane schlägt den Kopf des Aufstands ab, bevor er die regionalen Verteidigungsanlagen überwältigen kann.",al={"warum kolkar leaders töten","regthar deathgate motiv","warum will regthar dass dies erledigt wird"}},["4347847a"]={q="Wozu dient Kodobanns Kopf?",a="Regthar benötigt einen unbestreitbaren Beweis, dass der Zentaurenkommandeur gefallen ist. An der rauen Grenze des Brachlands reichen Gerüchte und Behauptungen nicht aus, um die Sicherheit zu garantieren. Das Zurückbringen des abgetrennten Kopfes von Barak bestätigt, dass der bei The Forgotten Pools lagernde Kolkar-Kriegstrupp seinen Anführer verloren hat und nicht mehr den Willen besitzt, weitere Angriffe zu koordinieren.",al={"warum baraks kopf","zweck baraks kopf","was mache ich mit baraks kopf"}}},fp="14,401,31.466.0,22.446.0,17.360.1,22.286.0,32.176.0,25.231.0,48.268.0,35.299.1,42.250.0"}
P.entries["quest:851"] = {n="Verog der Derwisch",s="Verog der Derwisch ist ein schwer fassbarer Anführer der Kolkarzentauren, der die südlichen Ebenen des Brachlands durchstreift. Um seinen Überfällen ein Ende zu setzen, weist Regthar Totenfurt die Champions der Horde an, das Kommandaozelt der Zentauren an der brackigen Oase zu überfallen und den nomadischen Befehlshaber so ins Freie zu zwingen.",h="Verog der Derwisch ist ein schwer fassbarer Anführer der Kolkarzentauren, der die südlichen Ebenen des...",kw={"brachland","zentaur","das wegekreuz","derwisch","kolkar","regthar totenfurt","die brackige oase","verog"},ang={["faction:Horde"]="Die Kontrolle über die Oasen ist für das Überleben im trockenen Brachland unerlässlich; die Vernichtung von Zentaurenkommandanten stellt sicher, dass die Wasserrouten für Versorgungskarawanen nutzbar bleiben.",["race:Orc"]="Regthar Totenfurt hält die Auslöschung der Kolkarkriegsfürsten für unverzichtbar, um die Straße zwischen dem Wegekreuz und dem Steinkrallengebirge für Reisende aus Durotar zu sichern.",["race:Tauren"]="Die Kolkar jagten und bedrängten die nomadischen Tauren über Generationen hinweg auf diesen Ebenen, was die Hinrichtung von Anführern wie Verog zu einem Akt lang ersehnter Vergeltung macht."},sec={{t="Den Derwisch hervorlocken",b="Nach dem Untergang von Barak Kodobane richtet der Ork-Krieger Regthar Totenfurt seinen Blick auf die verbliebenen Kriegsfürsten des Kolkarstammes. Anders als Barak, der sich offen an den nördlichen Gewässern der vergessenen Teiche aufhielt, streift Verog der Derwisch weit über die sonnenverbrannten Ebenen umher und verweilt selten lange in einem Lager. Ihn durch das gewaltige Gebiet zu verfolgen, wäre ein vergebliches Unterfangen, weshalb den Spähern der Horde nur eine tragfähige Strategie bleibt: den Kommandanten zu zwingen, zu ihnen zu kommen."},{t="Die brackige Oase",b="Verog operiert von dem Kommandoposten der Zentauren aus, der an der brackigen Oase südöstlich vom Wegekreuz liegt. Regthar weist Abenteurer an, das Lager direkt anzugreifen und Kolkarkrieger nahe ihres Kommandaozelts niederzustrecken, bis Panik einen Hornruf erzwingt. Diese Taktik nutzt den Stolz der Zentauren gegen sie aus – schlagt genug von Verogs Untergebenen auf ihrem eigenen Land nieder, und der Derwisch eilt zurück, um seinen Außenposten zu verteidigen, womit er geradewegs in die wartenden Klingen der Horde läuft."}},faq={{q="Wer ist Verog der Derwisch?",a="Verog der Derwisch ist ein umherstreifender Kriegsfürst der Kolkarzentauren im Brachland. Er leitet Operationen von der brackigen Oase aus, verbringt jedoch einen Großteil seiner Zeit damit, die südlichen Ödlande zu durchstreifen, was es schwer macht, ihn direkt in die Enge zu treiben.",al={"wer ist verog","verog lore","verog der derwisch"}},{q="Warum bleibt Verog nicht in seinem Lager?",a="Getreu seinem Titel „Derwisch“ ist Verog ein nomadischer Anführer, der eher die einsamen Weiten des Brachlands aufsucht, als untätig in einem einzelnen Lager zu sitzen. Seine mobile Natur schützt ihn vor organisierten Kriegstrupps der Horde und zwingt seine Feinde dazu, ihn zu provozieren, damit er sich zeigt.",al={"wo ist verog","warum wandert verog","verog fehlt"}},{q="Wie beschwört man Verog?",a="Verog wird zu seinem Kommandoposten zurückgelockt, wenn sein Stamm bedroht wird. Indem Abenteurer die Zentauren angreifen, die sich um das auffällige Kommandaozelt an der brackigen Oase scharen, stiften sie genug Unruhe, sodass die überlebenden Kolkar Alarm schlagen, woraufhin Verog zurücksprintet, um sein Zelt zu verteidigen.",al={"wie spawnt man verog","verog finden","verog taucht nicht auf"}},{q="Wer befiehlt Verogs Tod?",a="Regthar Totenfurt, ein Orkveteran, der westlich vom Wegekreuz an der Hauptstraße zum Steinkrallengebirge lagert, befiehlt Verogs Hinrichtung. Er versucht, das Rückgrat der Kolkar zu brechen, indem er methodisch jeden ihrer regionalen Befehlshaber zur Strecke bringt.",al={"wer gibt die quest","regthar totenfurt"}},{q="Was geschieht, nachdem Verog gefallen ist?",a="Bringt man Verogs abgetrennten Kopf zu Regthar zurück, kann der Ork ihn neben dem von Barak Kodobane in seine Sammlung aufnehmen. Anschließend nimmt Regthar Hezrul Blutmal ins Visier, den Kriegsfürsten der Zentauren, der die blühende Oase im Süden kontrolliert.",al={"was kommt danach","nach verog"}},{q="Warum sind die Kolkarzentauren im Brachland ein so großes Problem?",a="Die Kolkar sind aggressive, territoriale Raubtiere, die die lebenswichtigen Wasserquellen im gesamten Brachland beanspruchen. Ihre häufigen Angriffe auf Karawanen, Außenposten und einheimische Taurenherden machen sie zu einer unmittelbaren existenziellen Bedrohung für die noch junge Hordenpräsenz in Zentral-Kalimdor.",al={"warum kolkar bekämpfen","kolkar bedrohung"}}},fx={["42943e7a"]={q="Warum will Regthar Deathgate, dass Verog getötet wird?",a="Regthar Deathgate zerschlägt systematisch die Führung der Kolkar-Zentauren, die das nördliche Brachland und Das Wegekreuz bedrohen. Verog the Dervish befehligt den Zentauren-Kriegstrupp, der bei The Stagnant Oasis stationiert ist. Indem er ihn zusammen mit den anderen Kolkar-Häuptlingen eliminiert, will Regthar deren Befehlskette zerschlagen und ihren Griff auf die lebenswichtigen Oasen schwächen, bevor ihre Streitkräfte die Siedlungen der Horde überwältigen können.",al={"warum verog töten","regthar deathgate motiv","warum will regthar verog tot sehen"}},f05e98a6={q="Wozu wird Verogs Kopf verwendet?",a="Regthar Deathgate nimmt den abgetrennten Kopf von Verog als unbestreitbaren Beweis für den Tod des Derwischs. Er beabsichtigt, ihn zusammen mit Kodobanns Kopf an seinem Außenposten auf einen Pfahl zu spießen, was sowohl als Abrechnung gefallener feindlicher Kommandeure dient als auch als grimmige Warnung an jeden Kolkar, der sich entlang der Straße westlich von Das Wegekreuz nähert.",al={"zweck verogs kopf","was macht regthar mit verogs kopf","warum verogs kopf mitnehmen"}}},fp="17,270,23.494.0,18.475.0,25.225.0,35.281.0,24.287.0,25.245.0,31.231.1,57.269.0"}
P.entries["quest:852"] = {n="Hezrul Blutmal",s="Hezrul Blutmal ist eine Mission, die der Orcveteran Regthar Totenfurt vergibt, um den obersten Kriegsfürsten der Kolkarzentauren im Brachland auszuschalten. Indem sie Hezruls Kopf an der blühenden Oase erbeutet, will die Horde die Befehlshierarchie der Invasoren ein für alle Mal zerschlagen.",h="Hezrul Blutmal ist eine Mission, die der Orcveteran Regthar Totenfurt vergibt, um den obersten Kriegsfürsten...",kw={"blutmal","zentaur","das wegekreuz","deathgate","hezrul","kolkar","blühende oase","oase","regthar"},ang={["faction:Horde"]="Die Sicherung vom Wegekreuz und dem Brachland erfordert es, den eisernen Griff der Zentauren um die drei großen Oasen zu brechen, welche das Reisen in der Region ermöglichen.",["race:Orc"]="Regthar Totenfurt betrachtet den Kampf gegen die Kolkar durch die Linse orcischer Kriegsführung und stellt fest, dass der wilden Wut der Zentauren die eiserne Disziplin fehlt, die von der Horde kultiviert wurde.",["race:Tauren"]="Über Generationen hinweg litten die nomadischen Tauren unter brutaler Vertreibung und Blutvergießen durch die Zentauren; Kriegsfürsten wie Hezrul ein Ende zu setzen bringt hart erkämpfte Vergeltung."},sec={{t="Enthauptung der Kolkar",b="Nach dem Tod von Barak Kodobane und Verog dem Derwisch verbleibt nur noch ein oberster Häuptling unter den Kolkar des Brachlands: Hezrul Blutmal. Regthar Totenfurt sieht in Hezrul die brutale und gerissene Speerspitze, welche die Zentaurenüberfälle in der gesamten Savanne leitet. Hezrul niederzustrecken soll Chaos stiften und ihre Reihen unwiderruflich spalten – dem unberechenbaren Ungetüm den Kopf abschlagen, bevor es die Siedlungen der Horde überrennen kann."},{t="Die Festung an der blühenden Oase",b="Hezrul befehligt seine Kriegstrupps von der blühenden Oase aus, die südlich vom Wegekreuz liegt. Die Kontrolle über die wenigen Wasserlöcher im Brachland ist überlebenswichtig, was die Oase zu einem strategischen Knotenpunkt und Aufmarschgebiet für Raubzüge der Kolkar macht. Indem Recken der Horde Hezrul auf seinem eigenen Territorium entgegentreten, entreißen sie den Zentauren ihre wichtigste Zuflucht und brechen deren Herrschaft über die südlichen Pfade der Region."},{t="Gefährliche Nachwehen",b="Obgleich Regthar den Sieg über Hezrul lobt und bemerkt, dass den Zentauren die zielgerichtete Disziplin der Orcs fehlt, bringt das Attentat den Clan keineswegs lautlos zur Ruhe. Statt friedlich auseinanderzuströmen, sammeln die erzürnten Kolkar ihre verbliebenen Kräfte für einen verzweifelten, groß angelegten Sturmangriff direkt auf Regthars Lager, um blutige Rache zu nehmen."}},faq={{q="Wer ist Hezrul Blutmal?",a="Hezrul Blutmal ist der oberste Häuptling der Kolkarzentauren, die im Brachland operieren. Von der Horde als wild, listig und brutal eingestuft, befehligt er die verschiedenen Klane und Plünderer von seiner Festung an der blühenden Oase aus.",al={"wer ist hezrul","hezrul blutmal lore","zentaurenführer brachland"}},{q="Wo ist Hezrul Blutmal zu finden?",a="Hezrul patrouilliert im südlichen Brachland an den Ufern der blühenden Oase, südlich vom Wegekreuz, flankiert von seinen Kolkar-Leibwächtern.",al={"wo ist hezrul","hezrul aufenthaltsort","wo man hezrul findet"}},{q="Wer vergibt die Quest, Hezrul zu töten?",a="Regthar Totenfurt, ein Orckrieger, der in einem kleinen Lager westlich vom Wegekreuz an der Straße zum Steinkrallengebirge stationiert ist, erteilt diesen Auftrag.",al={"wer vergibt hezrul blutmal","regthar totenfurt quest","questgeber hezrul"}},{q="Warum will die Horde Hezrul tot sehen?",a="Die Kolkar bedrohen fortwährend die Handelsrouten und Siedlungen der Horde. Regthar glaubt, dass die Beseitigung ihres obersten Häuptlings die Einigkeit des Klans bricht und ihre Fähigkeit, einen koordinierten Krieg zu führen, drastisch schwächt.",al={"warum hezrul töten","hezrul blutmal zweck","kolkar bedrohung brachland"}},{q="Was geschieht, nachdem Hezrul getötet wurde?",a="Anstatt aufzugeben, schließen sich die überlebenden Kolkar in blinder Wut zusammen und starten einen sofortigen Gegenangriff auf den Außenposten von Regthar Totenfurt westlich vom Wegekreuz.",al={"gegenangriff nach hezrul","was geschieht als nächstes","folgen von hezruls tod"}},{q="In welcher Beziehung steht Hezrul zu Barak und Verog?",a="Barak Kodobane und Verog der Derwisch waren untergeordnete Anführer der Kolkar, die einzelne Oasen und Kriegstrupps befehligten, während Hezrul Blutmal als oberster Anführer über den gesamten Klan im Brachland herrschte.",al={"barak verog hezrul","kolkar häuptlinge","drei zentaurenführer"}}},fx={ca31e908={q="Wozu dient Hezruls Kopf?",a="Regthar Deathgate benötigt Hezruls Kopf als unwiderlegbaren Beweis dafür, dass der oberste Anführer der Kolkar im Brachland gefallen ist. Genau wie bei Barak Kodobane und Verog the Dervish vor ihm, bestätigt das Zurückbringen des abgetrennten Kopfes der Horde, dass die Zentaurenführung gebrochen und die Bedrohung beseitigt wurde.",al={"verwendung hezruls kopf","warum hezruls kopf mitnehmen","hezrul kopf"}}},fp="16,272,23.452.0,24.397.0,21.356.1,24.230.0,36.136.0,35.148.0,36.221.0,35.164.1,42.210.0"}
